<# :: Hybrid CMD / Powershell Launcher - Rename to .CMD or .PS1 - CMD mode needs anything above this line removed to function properly
@START /MIN "" POWERSHELL -nop -w hidden -c "iex ([io.file]::ReadAllText('%~f0'))">nul&EXIT
#>

<#
.SYNOPSIS
	MiniBot v2.51.0 - Local AI agent host for Windows PowerShell 5.1
.DESCRIPTION
	OpenAI-compatible agent client (WPF UI + tools). Hybrid .CMD/.PS1 launcher; irm|iex friendly.
.NOTES
	Windows PowerShell 5.1+. Optional System.Speech for /speech (Right-Ctrl PTT + TTS).
#>

param(
	# --- Primary OpenAI-compatible API (llama.cpp / main host) ---
	# Prefer .../v1 when the server is OpenAI-compat (vLLM, Unsloth Studio). llama.cpp often uses bare :8080.
	# Port stays in the URL (not a separate param) so multi-endpoint bases, HTTPS, and /v1 paths stay simple.
	# Localhost placeholder: nothing listening -> Connect recovery popup to enter real endpoint (xAI, LAN, etc.).
	# Leave empty ("") to open Connect immediately without a probe timeout.
	[string]$BaseUrl = "", # e.g. http://127.0.0.1:8080/v1 - Hardcode here for direct connect without login popup
	# Optional preferred model id. Leave empty to auto-pick from /models (single model)
	# or the PoweredBy picker (multiple). Only used when set / -Model is passed.
	# HF/Unsloth-style ids with a slash are OK: unsloth/Qwen3.5-4B-MTP-GGUF
	[string]$Model = "",
	# Max completion tokens. 0 = auto (n_ctx/8 from server). Set a value or pass -MaxTokens to lock.
	[int]$MaxTokens = 0,
	# Optional n_ctx fallback. 0 = use server /props + /models only. Set / -ContextWindowTokens if needed.
	[int]$ContextWindowTokens = 0,
	# Optional display override. Leave empty to use the live server model id.
	[string]$ModelAlias = "",
	# Primary HTTP auth Bearer key (NOT chat prompt text). Use "none" to skip.
	# Examples: -ApiKey 'sk-...'   |   Unsloth: sk-unsloth-...   |   vLLM: value from --api-key
	# xAI Grok: -BaseUrl 'https://api.x.ai/v1' -ApiKey 'xai-...' -Model 'grok-4.5'
	# If you log in with NPM Basic for the primary llama.cpp host, leave this "none" unless the app itself needs Bearer.
	[string]$ApiKey = "none",
	[double]$Temperature = 0.15,
	[int]$MaxTurns = 50,
	# Auto-continue when a text reply is truncated (finish_reason=length or mid-sentence)
	[int]$MaxReplyContinues = 5,
	[string]$AgentName = "MiniBot",
	[string]$Version = "2.51.0",
	[bool]$AutoApproveEnabled = $false,
	# Voice: Right-Ctrl hold-to-talk dictation + optional TTS of model replies
	[bool]$SpeechEnabled = $false,
	# Speak final assistant text via SAPI when speech is on
	[bool]$SpeechAutoReply = $true,
	# Also set by env store=1 when the param is omitted - HOLD CAPS-LOCK DURING LAUNCH TO CLEAR STORED CREDS
	[bool]$StoreCredentials = $false,
	[int]$MaxToolResultChars = 10000,
	[int]$MaxHistoryMessages = 48,
	[int]$CommandTimeoutSec = 360,
	[double]$ContextSoftPct = 0.72,
	[double]$ContextHardPct = 0.88,
	[bool]$AutoCompactEnabled = $true,
	# Optional model summary on compact (else extractive)
	[bool]$ModelCompactEnabled = $true,
	# Tool surface: core (default, progressive) | full (all groups enabled)
	[ValidateSet('core','full')]
	[string]$ToolProfile = "core",
	[string]$TaskApiBase = "",
	# File debug log (Desktop\MiniBot-debug.log). Off by default. Env: debug=1
	[bool]$DebugLog = $false,
	# Hide attached console / Windows Terminal host window (PS1 and irm|iex). CMD hybrid line is separate (START /MIN -w hidden).
	[bool]$HideConsole = $true
)

# =============================================================================
# Multi-model / multi-endpoint (optional hardcode; UI: PoweredBy -> + Add endpoint)
# =============================================================================
# Extra endpoints: each base can use apikey | npm | none independently.
#   apikey -> Bearer from MBExtraApiKeys
#   npm    -> same session NPM Basic as the primary host
#   none   -> no Authorization header
# Prefer .../v1 for vLLM / Unsloth Studio. Bare host:port is fine for many llama.cpp builds.
# Runtime UI: PoweredBy -> + Add endpoint -> Auth mode. Do not commit real secrets.
#
# --- llama.cpp + NPM (same reverse proxy / NPM Basic as primary) ---
#   $script:MBExtraApiBases = @('https://llama.example.com')
#   $script:MBExtraApiAuth  = @{ 'https://llama.example.com' = 'npm' }
#
# --- llama.cpp + none (open LAN, no Authorization) ---
#   $script:MBExtraApiBases = @('http://127.0.0.1:8081')
#   $script:MBExtraApiAuth  = @{ 'http://127.0.0.1:8081' = 'none' }
#
# --- llama.cpp + apikey (Bearer) ---
#   $script:MBExtraApiBases = @('http://127.0.0.1:8081')
#   $script:MBExtraApiAuth  = @{ 'http://127.0.0.1:8081' = 'apikey' }
#   $script:MBExtraApiKeys  = @{ 'http://127.0.0.1:8081' = 'sk-your-key' }
#
# --- Unsloth Studio + apikey ---
#   $script:MBExtraApiBases = @('http://192.168.1.10:8888/v1')
#   $script:MBExtraApiAuth  = @{ 'http://192.168.1.10:8888/v1' = 'apikey' }
#   $script:MBExtraApiKeys  = @{ 'http://192.168.1.10:8888/v1' = 'sk-unsloth-xxxxxxxx' }
#
# --- vLLM + none (open LAN) ---
#   $script:MBExtraApiBases = @('http://192.168.1.20:8000/v1')
#   $script:MBExtraApiAuth  = @{ 'http://192.168.1.20:8000/v1' = 'none' }
#
# --- vLLM + apikey (--api-key / OpenAI-compat Bearer) ---
#   $script:MBExtraApiBases = @('http://192.168.1.20:8000/v1')
#   $script:MBExtraApiAuth  = @{ 'http://192.168.1.20:8000/v1' = 'apikey' }
#   $script:MBExtraApiKeys  = @{ 'http://192.168.1.20:8000/v1' = 'token-abc123' }
# =============================================================================

# Extra OpenAI-compatible API bases (in addition to -BaseUrl). Uncomment / edit to hardcode.
$script:MBExtraApiBases = @(
)

# Per-base auth mode: 'apikey' | 'npm' | 'none'
$script:MBExtraApiAuth = @{
}

# Per-base Bearer keys when auth mode is 'apikey'
$script:MBExtraApiKeys = @{
}

# Console hide (PS param -HideConsole). CMD users: edit the hybrid @START line at top of file.
$solo = $true
$script:MB_HideConsole = [bool]$HideConsole
$script:MB_HiddenConsoleHwnd = [IntPtr]::Zero
if ($script:MB_HideConsole) {
	try {
		Add-Type -MemberDefinition @"
using System;
using System.Runtime.InteropServices;
public static class Win32 {
	[DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
	[DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr handle, int nCmdShow);
	[DllImport("kernel32.dll", SetLastError=true)] static extern IntPtr CreateToolhelp32Snapshot(uint dwFlags, uint th32ProcessID);
	[DllImport("kernel32.dll", SetLastError=true)] static extern bool Process32First(IntPtr hSnapshot, ref PROCESSENTRY32 lppe);
	[DllImport("kernel32.dll", SetLastError=true)] static extern bool Process32Next(IntPtr hSnapshot, ref PROCESSENTRY32 lppe);
	[DllImport("kernel32.dll", SetLastError=true)] static extern bool CloseHandle(IntPtr hObject);
	const uint TH32CS_SNAPPROCESS = 2;
	[StructLayout(LayoutKind.Sequential, CharSet=CharSet.Auto)]
	struct PROCESSENTRY32 {
		public uint dwSize; public uint cntUsage; public uint th32ProcessID;
		public IntPtr th32DefaultHeapID; public uint th32ModuleID; public uint cntThreads;
		public uint th32ParentProcessID; public int pcPriClassBase; public uint dwFlags;
		[MarshalAs(UnmanagedType.ByValTStr, SizeConst=260)] public string szExeFile;
	}
	public static uint GetParentProcessId(uint pid) {
		IntPtr snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
		if (snap == IntPtr.Zero || snap == (IntPtr)(-1)) return 0;
		try {
			PROCESSENTRY32 pe = new PROCESSENTRY32();
			pe.dwSize = (uint)Marshal.SizeOf(typeof(PROCESSENTRY32));
			if (!Process32First(snap, ref pe)) return 0;
			do { if (pe.th32ProcessID == pid) return pe.th32ParentProcessID; }
			while (Process32Next(snap, ref pe));
			return 0;
		} finally { CloseHandle(snap); }
	}
}
"@ -Name "Win32" -Namespace "Win32Functions" -ErrorAction Stop
	} catch {}

	try {
		$hwnd = [Win32Functions.Win32]::GetConsoleWindow()
		if ($hwnd -ne [IntPtr]::Zero) {
			$script:MB_HiddenConsoleHwnd = $hwnd
			[void][Win32Functions.Win32]::ShowWindow($hwnd, 0)  # SW_HIDE
		} else {
			# Parent walk without WMI/CIM (Windows Terminal has no console hwnd)
			$currentProcessId = [uint32]$PID
			$guard = 0
			while ($currentProcessId -and $guard -lt 16) {
				$guard++
				$currentProcess = Get-Process -Id $currentProcessId -ErrorAction SilentlyContinue
				if ($currentProcess -and $currentProcess.ProcessName -eq 'WindowsTerminal') {
					$hwnd = $currentProcess.MainWindowHandle
					if ($hwnd -ne [IntPtr]::Zero) {
						$script:MB_HiddenConsoleHwnd = $hwnd
						[void][Win32Functions.Win32]::ShowWindow($hwnd, 0)  # SW_HIDE
					}
					break
				}
				try { $currentProcessId = [Win32Functions.Win32]::GetParentProcessId($currentProcessId) } catch { break }
			}
		}
	} catch {}
}

