$script:MB_STATE_MARKER = '[SESSION STATE'

# --- Temp lifecycle: track session temps, clean as we go, sweep orphans on launch/exit ---
function Get-MBOsTempPath {
	$t = $env:TEMP
	if ([string]::IsNullOrWhiteSpace($t)) {
		try { $t = [System.IO.Path]::GetTempPath() } catch { $t = $null }
	}
	if ([string]::IsNullOrWhiteSpace($t)) { $t = $env:TMP }
	return [string]$t
}

function Register-MBTempPath {
	param([string]$Path)
	if ([string]::IsNullOrWhiteSpace($Path)) { return }
	try {
		if (-not $script:MB.TempTracked) {
			$script:MB.TempTracked = New-Object System.Collections.ArrayList
		}
		$full = [string]$Path
		try { $full = [System.IO.Path]::GetFullPath($Path) } catch {}
		$exists = $false
		foreach ($x in @($script:MB.TempTracked)) {
			if ([string]::Equals([string]$x, $full, [StringComparison]::OrdinalIgnoreCase)) {
				$exists = $true
				break
			}
		}
		if (-not $exists) { [void]$script:MB.TempTracked.Add($full) }
	} catch {}
}

function Unregister-MBTempPath {
	param([string]$Path)
	if ([string]::IsNullOrWhiteSpace($Path)) { return }
	try {
		if (-not $script:MB.TempTracked) { return }
		$full = [string]$Path
		try { $full = [System.IO.Path]::GetFullPath($Path) } catch {}
		for ($i = $script:MB.TempTracked.Count - 1; $i -ge 0; $i--) {
			if ([string]::Equals([string]$script:MB.TempTracked[$i], $full, [StringComparison]::OrdinalIgnoreCase)) {
				$script:MB.TempTracked.RemoveAt($i)
			}
		}
	} catch {}
}

function Remove-MBTempPath {
	param(
		[string]$Path,
		[switch]$KeepIfMissing
	)
	if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
	$ok = $true
	try {
		if (Test-Path -LiteralPath $Path) {
			Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop
		} elseif (-not $KeepIfMissing) {
			# already gone
		}
	} catch {
		$ok = $false
		try {
			# Retry: clear read-only then remove
			Get-ChildItem -LiteralPath $Path -Recurse -Force -ErrorAction SilentlyContinue |
				ForEach-Object { try { $_.Attributes = 'Normal' } catch {} }
			Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction SilentlyContinue
			$ok = -not (Test-Path -LiteralPath $Path)
		} catch { $ok = $false }
	}
	try { Unregister-MBTempPath -Path $Path } catch {}
	return $ok
}

function New-MBTempDir {
	param(
		[string]$Prefix = 'MiniBot',
		[switch]$NoRegister
	)
	$base = Get-MBOsTempPath
	if ([string]::IsNullOrWhiteSpace($base)) { throw 'TEMP path unavailable' }
	$p = $Prefix
	if ([string]::IsNullOrWhiteSpace($p)) { $p = 'MiniBot' }
	# Prefer MiniBot- prefix so remnant sweep can find us
	if ($p -notmatch '(?i)^MiniBot|^minibot|^mb-') { $p = 'MiniBot-' + $p }
	$dir = Join-Path $base ($p.TrimEnd('-_') + '-' + [guid]::NewGuid().ToString('n'))
	New-Item -ItemType Directory -Path $dir -Force | Out-Null
	if (-not $NoRegister) { Register-MBTempPath -Path $dir }
	return $dir
}

function New-MBTempFile {
	param(
		[string]$Prefix = 'MiniBot',
		[string]$Extension = '.tmp',
		[switch]$NoRegister
	)
	$base = Get-MBOsTempPath
	if ([string]::IsNullOrWhiteSpace($base)) { throw 'TEMP path unavailable' }
	$p = $Prefix
	if ([string]::IsNullOrWhiteSpace($p)) { $p = 'MiniBot' }
	if ($p -notmatch '(?i)^MiniBot|^minibot|^mb-') { $p = 'MiniBot-' + $p }
	$ext = $Extension
	if ([string]::IsNullOrWhiteSpace($ext)) { $ext = '.tmp' }
	if ($ext[0] -ne '.') { $ext = '.' + $ext }
	$path = Join-Path $base ($p.TrimEnd('-_') + '-' + [guid]::NewGuid().ToString('n') + $ext)
	# Touch empty file so path is reserved
	try { [System.IO.File]::WriteAllBytes($path, [byte[]]@()) } catch {
		New-Item -ItemType File -Path $path -Force | Out-Null
	}
	if (-not $NoRegister) { Register-MBTempPath -Path $path }
	return $path
}

function Clear-MBTrackedTemps {
	# Remove everything registered for this session (order: deepest paths first)
	$list = @()
	try { $list = @($script:MB.TempTracked) } catch { $list = @() }
	if ($list.Count -eq 0) { return 0 }
	$sorted = @($list | Sort-Object { ([string]$_).Length } -Descending)
	$n = 0
	foreach ($p in $sorted) {
		if (Remove-MBTempPath -Path ([string]$p)) { $n++ }
	}
	try { $script:MB.TempTracked.Clear() } catch {
		try { $script:MB.TempTracked = New-Object System.Collections.ArrayList } catch {}
	}
	return $n
}

function Clear-MBTempRemnants {
	param(
		[switch]$IncludeActiveSandbox,
		[switch]$Quiet
	)
	# Sweep known MiniBot temp names left by crash / kill / improper close.
	# Does not touch MiniBot-debug.log or unrelated %TEMP% content.
	$base = Get-MBOsTempPath
	if ([string]::IsNullOrWhiteSpace($base) -or -not (Test-Path -LiteralPath $base)) {
		return @{ ok = $true; removed = 0; failed = 0 }
	}

	$keep = @{}
	if (-not $IncludeActiveSandbox) {
		try {
			$sr = [string]$script:MB.SandboxRoot
			if ($sr) {
				$kf = $sr
				try { $kf = [System.IO.Path]::GetFullPath($sr) } catch {}
				$keep[$kf.ToLowerInvariant()] = $true
			}
		} catch {}
		try {
			foreach ($t in @($script:MB.TempTracked)) {
				$kf = [string]$t
				try { $kf = [System.IO.Path]::GetFullPath($t) } catch {}
				if ($kf) { $keep[$kf.ToLowerInvariant()] = $true }
			}
		} catch {}
	}

	$candidates = New-Object System.Collections.ArrayList
	$dirNames = @(
		'MiniBotSandbox'
	)
	$dirPrefixes = @(
		'MiniBotInstall-',
		'MiniBotSetup-',
		'MiniBot7z-',
		'MiniBot-',
		'minibot-pdf-',
		'mb-battery-'
	)
	$filePrefixes = @(
		'minibot-pdf-winrt-',
		'minibot-pdf-',
		'mb-battery-',
		'MiniBot-'
	)

	try {
		foreach ($name in $dirNames) {
			$p = Join-Path $base $name
			if (Test-Path -LiteralPath $p) { [void]$candidates.Add((Get-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue)) }
		}
		Get-ChildItem -LiteralPath $base -Force -ErrorAction SilentlyContinue | ForEach-Object {
			$leaf = [string]$_.Name
			if ($_.PSIsContainer) {
				foreach ($pre in $dirPrefixes) {
					if ($leaf.StartsWith($pre, [StringComparison]::OrdinalIgnoreCase)) {
						[void]$candidates.Add($_)
						break
					}
				}
			} else {
				# Never delete the optional debug log if someone put it in TEMP
				if ($leaf -match '(?i)^MiniBot-debug\.log$') { return }
				foreach ($pre in $filePrefixes) {
					if ($leaf.StartsWith($pre, [StringComparison]::OrdinalIgnoreCase)) {
						[void]$candidates.Add($_)
						break
					}
				}
			}
		}
	} catch {}

	$removed = 0
	$failed = 0
	# Longest paths first so children go before parents when both listed
	$items = @($candidates | Where-Object { $_ } | Sort-Object { ([string]$_.FullName).Length } -Descending)
	$seen = @{}
	foreach ($item in $items) {
		try {
			$fp = [string]$item.FullName
			if ([string]::IsNullOrWhiteSpace($fp)) { continue }
			$key = $fp.ToLowerInvariant()
			if ($seen.ContainsKey($key)) { continue }
			$seen[$key] = $true
			if ($keep.ContainsKey($key)) { continue }
			# Skip if path is under a keep root (active sandbox)
			$skip = $false
			foreach ($k in @($keep.Keys)) {
				if ($key.StartsWith($k.TrimEnd('\') + '\') -or $key -eq $k) { $skip = $true; break }
			}
			if ($skip) { continue }
			try {
				if ($item.PSIsContainer) {
					Remove-Item -LiteralPath $fp -Recurse -Force -ErrorAction Stop
				} else {
					Remove-Item -LiteralPath $fp -Force -ErrorAction Stop
				}
				$removed++
			} catch {
				try {
					Get-ChildItem -LiteralPath $fp -Recurse -Force -ErrorAction SilentlyContinue |
						ForEach-Object { try { $_.Attributes = 'Normal' } catch {} }
					Remove-Item -LiteralPath $fp -Recurse -Force -ErrorAction SilentlyContinue
					if (Test-Path -LiteralPath $fp) { $failed++ } else { $removed++ }
				} catch { $failed++ }
			}
		} catch { $failed++ }
	}

	if (-not $Quiet -and ($removed -gt 0 -or $failed -gt 0)) {
		try {
			Write-MBDebugLog -Step 'TEMP_REMNANT_SWEEP' -Detail ("removed={0} failed={1}" -f $removed, $failed)
		} catch {}
	}
	return @{ ok = ($failed -eq 0); removed = $removed; failed = $failed }
}

function Invoke-MBTempCleanup {
	param(
		[switch]$Remnants,
		[switch]$Tracked,
		[switch]$Sandbox,
		[switch]$All
	)
	if ($All) {
		$Tracked = $true
		$Sandbox = $true
		$Remnants = $true
	}
	$n = 0
	if ($Sandbox) {
		try {
			$root = [string]$script:MB.SandboxRoot
			if ($root) {
				if (Remove-MBTempPath -Path $root) { $n++ }
			}
			$script:MB.SandboxRoot = $null
			$script:MB.SandboxId = $null
			$script:MB.SandboxLast = $null
		} catch {}
	}
	if ($Tracked) {
		try { $n += [int](Clear-MBTrackedTemps) } catch {}
	}
	if ($Remnants) {
		try {
			$r = Clear-MBTempRemnants -IncludeActiveSandbox:$Sandbox -Quiet
			if ($r -and $r.removed) { $n += [int]$r.removed }
		} catch {}
	}
	return $n
}

# Orphans from prior improper close (before any work this session)
try { $null = Clear-MBTempRemnants -Quiet } catch {}

function Get-MBDebugLogPath {
	try {
		if ($script:MB.DebugLogPath) { return [string]$script:MB.DebugLogPath }
		$desk = [Environment]::GetFolderPath('Desktop')
		if ([string]::IsNullOrWhiteSpace($desk)) { $desk = $env:USERPROFILE }
		if ([string]::IsNullOrWhiteSpace($desk)) { $desk = $env:TEMP }
		$script:MB.DebugLogPath = Join-Path $desk 'MiniBot-debug.log'
		return [string]$script:MB.DebugLogPath
	} catch {
		return (Join-Path $env:TEMP 'MiniBot-debug.log')
	}
}

function Write-MBDebugLog {
	param(
		[Parameter(Mandatory = $true)][string]$Step,
		[string]$Detail = ''
	)
	$on = $false
	try { $on = [bool]$script:MB.DebugLogEnabled } catch { $on = $false }
	if (-not $on) { return }
	try {
		$path = Get-MBDebugLogPath
		$n = 0
		try {
			$script:MB.DebugSeq = [int]$script:MB.DebugSeq + 1
			$n = [int]$script:MB.DebugSeq
		} catch { $n = 0 }
		$ts = Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff'
		$tid = [System.Threading.Thread]::CurrentThread.ManagedThreadId
		$hostUi = ''
		try { $hostUi = [string]$script:MB.HostUi } catch {}
		$line = '[{0}] #{1} tid={2} host={3} | {4}' -f $ts, $n, $tid, $hostUi, $Step
		if (-not [string]::IsNullOrWhiteSpace($Detail)) {
			$d = ($Detail -replace '[\r\n]+', ' | ')
			if ($d.Length -gt 800) { $d = $d.Substring(0, 797) + '...' }
			$line += ' :: ' + $d
		}
		$line += [Environment]::NewLine
		[System.IO.File]::AppendAllText($path, $line)
	} catch {
		try {
			$fallback = Join-Path $env:TEMP 'MiniBot-debug.log'
			[System.IO.File]::AppendAllText($fallback, ("{0} FALLBACK {1}`r`n" -f (Get-Date -Format o), $Step))
		} catch {}
	}
}



function Normalize-MBApiBase {
	param([string]$Url)
	$u = [string]$Url
	if ([string]::IsNullOrWhiteSpace($u)) { return '' }
	$u = $u.Trim()
	if ($u -notmatch '^(?i)https?://') {
		# host:port or host -> assume http
		if ($u -match '^\d+$') { $u = "http://127.0.0.1:$u" }
		else { $u = "http://$u" }
	}
	while ($u.EndsWith('/')) { $u = $u.Substring(0, $u.Length - 1) }
	$u = $u -replace '/chat/completions\s*$', '' -replace '/models\s*$', ''
	$u = $u -replace '/v1/chat/completions\s*$', '' -replace '/v1/models\s*$', ''
	while ($u.EndsWith('/')) { $u = $u.Substring(0, $u.Length - 1) }
	return $u
}

function Get-MBApiBaseUrl {
	try {
		$ab = [string]$script:MB.ActiveModelBase
		if (-not [string]::IsNullOrWhiteSpace($ab)) { return (Normalize-MBApiBase -Url $ab) }
	} catch {}
	try {
		if ($script:MB -and $script:MB.ResolvedApiBase) {
			$rb = [string]$script:MB.ResolvedApiBase
			if (-not [string]::IsNullOrWhiteSpace($rb)) { return (Normalize-MBApiBase -Url $rb) }
		}
	} catch {}
	$u = Normalize-MBApiBase -Url ([string]$BaseUrl)
	if ([string]::IsNullOrWhiteSpace($u)) { return 'http://127.0.0.1:8080' }
	return $u
}

function Get-MBShortHostLabel {
	param([string]$Base)
	try {
		$u = [uri](Normalize-MBApiBase -Url $Base)
		$port = $u.Port
		if (($u.Scheme -eq 'http' -and $port -eq 80) -or ($u.Scheme -eq 'https' -and $port -eq 443)) {
			return $u.Host
		}
		return ("{0}:{1}" -f $u.Host, $port)
	} catch {
		$b = Normalize-MBApiBase -Url $Base
		return $b
	}
}

function Initialize-MBExtraApiBases {
	try {
		if ($null -eq $script:MB) { return }
		try {
			$script:MB.PrimaryApiBase = Normalize-MBApiBase -Url ([string](Get-Variable -Name BaseUrl -Scope Script -ValueOnly -ErrorAction SilentlyContinue))
		} catch {
			try { $script:MB.PrimaryApiBase = Normalize-MBApiBase -Url ([string]$script:MB.PrimaryApiBase) } catch {}
		}
		$seed = New-Object System.Collections.ArrayList
		# Keep any already-added runtime extras
		try {
			foreach ($x in @($script:MB.ExtraApiBases)) {
				$n = Normalize-MBApiBase -Url ([string]$x)
				if ($n -and -not ($seed | Where-Object { [string]::Equals($_, $n, [StringComparison]::OrdinalIgnoreCase) })) {
					[void]$seed.Add($n)
				}
			}
		} catch {}
		foreach ($x in @($script:MBExtraApiBases)) {
			$n = Normalize-MBApiBase -Url ([string]$x)
			if ($n -and -not ($seed | Where-Object { [string]::Equals($_, $n, [StringComparison]::OrdinalIgnoreCase) })) {
				[void]$seed.Add($n)
			}
		}
		$script:MB.ExtraApiBases = @($seed)

		# Seed per-base Bearer keys from $script:MBExtraApiKeys (top-of-script examples)
		try {
			$map = $null
			try { $map = $script:MBExtraApiKeys } catch { $map = $null }
			if ($map -is [hashtable]) {
				foreach ($k in @($map.Keys)) {
					$bn = Normalize-MBApiBase -Url ([string]$k)
					$kv = [string]$map[$k]
					if ($bn -and (Test-MBApiKeyUsable -Key $kv)) {
						Set-MBApiKeyForBase -BaseUrl $bn -ApiKeyValue $kv
					}
				}
			}
		} catch {}

		# Seed per-base auth mode from $script:MBExtraApiAuth ('apikey'|'npm'|'none')
		try {
			$am = $null
			try { $am = $script:MBExtraApiAuth } catch { $am = $null }
			if ($am -is [hashtable]) {
				foreach ($k in @($am.Keys)) {
					$bn = Normalize-MBApiBase -Url ([string]$k)
					$mode = ([string]$am[$k]).Trim().ToLowerInvariant()
					if (-not $bn) { continue }
					if ($mode -eq 'basic') { $mode = 'npm' }
					if ($mode -in @('bearer', 'key')) { $mode = 'apikey' }
					if ($mode -in @('npm', 'apikey', 'none')) {
						Set-MBApiAuthModeForBase -BaseUrl $bn -Mode $mode
					}
				}
			}
		} catch {}

		# Primary -ApiKey (xAI xai-... / OpenAI sk-...) => apikey mode on primary base
		try {
			$pk = ''
			try { $pk = [string]$ApiKey } catch { $pk = '' }
			$pb = ''
			try { $pb = [string]$script:MB.PrimaryApiBase } catch { $pb = '' }
			if ([string]::IsNullOrWhiteSpace($pb)) {
				try { $pb = Normalize-MBApiBase -Url ([string](Get-Variable -Name BaseUrl -ValueOnly -ErrorAction SilentlyContinue)) } catch {}
			}
			if ((Test-MBApiKeyUsable -Key $pk) -and -not [string]::IsNullOrWhiteSpace($pb)) {
				Set-MBApiAuthModeForBase -BaseUrl $pb -Mode 'apikey'
				Set-MBApiKeyForBase -BaseUrl $pb -ApiKeyValue $pk
			}
		} catch {}
	} catch {
		try { if ($null -eq $script:MB.ExtraApiBases) { $script:MB.ExtraApiBases = @() } } catch {}
	}
}

function Get-MBConfiguredApiBases {
	try { Initialize-MBExtraApiBases } catch {}
	$out = New-Object System.Collections.ArrayList
	$add = {
		param([string]$raw)
		$n = Normalize-MBApiBase -Url $raw
		if ([string]::IsNullOrWhiteSpace($n)) { return }
		foreach ($x in @($out)) {
			if ([string]::Equals($x, $n, [StringComparison]::OrdinalIgnoreCase)) { return }
		}
		[void]$out.Add($n)
	}
	try { & $add ([string]$BaseUrl) } catch {}
	try { & $add ([string]$script:MB.PrimaryApiBase) } catch {}
	try { & $add ([string]$script:MB.ResolvedApiBase) } catch {}
	try { & $add ([string]$script:MB.ActiveModelBase) } catch {}
	try {
		foreach ($x in @($script:MB.ExtraApiBases)) { & $add ([string]$x) }
	} catch {}
	try {
		foreach ($e in @($script:MB.RemoteModelEntries)) {
			if ($null -eq $e) { continue }
			try { & $add ([string]$e.Base) } catch {}
		}
	} catch {}
	if ($out.Count -eq 0) { [void]$out.Add('http://127.0.0.1:8080/v1') }
	return @($out)
}

function Get-MBApiBaseIdentityKeys {
	# Canonical forms for equality: with and without trailing /v1 (probe tries both).
	param([string]$Url)
	$n = Normalize-MBApiBase -Url $Url
	if ([string]::IsNullOrWhiteSpace($n)) { return @() }
	$keys = New-Object System.Collections.ArrayList
	[void]$keys.Add($n)
	if ($n -match '(?i)/v1$') {
		$root = $n -replace '(?i)/v1$', ''
		if (-not [string]::IsNullOrWhiteSpace($root)) { [void]$keys.Add($root) }
	} else {
		[void]$keys.Add(($n + '/v1'))
	}
	return @($keys)
}

function Get-MBLiveApiBases {
	# Strict list for "+ Add endpoint" duplicate check only:
	#  - ActiveModelBase (what this session is using now)
	#  - ExtraApiBases (successfully multi-added endpoints)
	# Do NOT include launch -BaseUrl / PrimaryApiBase / RemoteModelEntries:
	# model refresh polls configured seeds and would false-positive "already connected".
	$out = New-Object System.Collections.ArrayList
	$add = {
		param([string]$raw)
		$n = Normalize-MBApiBase -Url $raw
		if ([string]::IsNullOrWhiteSpace($n)) { return }
		foreach ($x in @($out)) {
			if ([string]::Equals($x, $n, [StringComparison]::OrdinalIgnoreCase)) { return }
		}
		[void]$out.Add($n)
	}
	try { & $add ([string]$script:MB.ActiveModelBase) } catch {}
	try {
		foreach ($x in @($script:MB.ExtraApiBases)) { & $add ([string]$x) }
	} catch {}
	return @($out)
}

function Test-MBApiBaseAlreadyConfigured {
	# True if Url is the same live endpoint as one already in this session (with/without /v1).
	param([string]$Url)
	$want = @(Get-MBApiBaseIdentityKeys -Url $Url)
	if ($want.Count -eq 0) { return $false }
	$known = @()
	try { $known = @(Get-MBLiveApiBases) } catch { $known = @() }
	foreach ($k in $known) {
		if ([string]::IsNullOrWhiteSpace([string]$k)) { continue }
		foreach ($kk in @(Get-MBApiBaseIdentityKeys -Url $k)) {
			if ([string]::IsNullOrWhiteSpace([string]$kk)) { continue }
			foreach ($w in $want) {
				if ([string]::IsNullOrWhiteSpace([string]$w)) { continue }
				if ([string]::Equals($w, $kk, [StringComparison]::OrdinalIgnoreCase)) { return $true }
			}
		}
	}
	return $false
}

function Find-MBApiBaseAlreadyConfigured {
	# Returns the live base string that matches Url, or '' if none.
	param([string]$Url)
	$want = @(Get-MBApiBaseIdentityKeys -Url $Url)
	if ($want.Count -eq 0) { return '' }
	$known = @()
	try { $known = @(Get-MBLiveApiBases) } catch { $known = @() }
	foreach ($k in $known) {
		if ([string]::IsNullOrWhiteSpace([string]$k)) { continue }
		foreach ($kk in @(Get-MBApiBaseIdentityKeys -Url $k)) {
			if ([string]::IsNullOrWhiteSpace([string]$kk)) { continue }
			foreach ($w in $want) {
				if ([string]::IsNullOrWhiteSpace([string]$w)) { continue }
				if ([string]::Equals($w, $kk, [StringComparison]::OrdinalIgnoreCase)) {
					return (Normalize-MBApiBase -Url $k)
				}
			}
		}
	}
	return ''
}

function Get-MBDeepErrorMessage {
	param($ErrorRecord)
	if ($null -eq $ErrorRecord) { return 'Unknown error' }
	$ex = $null
	if ($ErrorRecord -is [System.Exception]) { $ex = $ErrorRecord }
	elseif ($ErrorRecord.Exception) { $ex = $ErrorRecord.Exception }
	else { return [string]$ErrorRecord }

	$msgs = New-Object System.Collections.ArrayList
	$seen = 0
	while ($null -ne $ex -and $seen -lt 8) {
		$seen++
		if ($ex -is [System.AggregateException] -and $ex.InnerExceptions -and $ex.InnerExceptions.Count -gt 0) {
			$ex = $ex.InnerExceptions[0]
			continue
		}
		if ($ex.Message) { [void]$msgs.Add($ex.Message) }
		if ($ex.InnerException) { $ex = $ex.InnerException } else { break }
	}
	if ($msgs.Count -eq 0) { return [string]$ErrorRecord }
	return ($msgs -join ' | ')
}

if (-not ("MiniBot.Core.Native" -as [type])) {
	$miniBotCs = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;

namespace MiniBot.Core {
	public static class Native {
		static readonly Regex ScriptTag = new Regex("<script[^>]*>.*?</script>", RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
		static readonly Regex StyleTag  = new Regex("<style[^>]*>.*?</style>", RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
		static readonly Regex Comment   = new Regex("<!--.*?-->", RegexOptions.Singleline | RegexOptions.Compiled);
		static readonly Regex Noscript  = new Regex("<noscript[^>]*>.*?</noscript>", RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
		static readonly Regex BlockTags = new Regex("</?(nav|footer|header|aside|form|iframe|object|embed|svg|noscript)[^>]*>", RegexOptions.IgnoreCase | RegexOptions.Compiled);
		static readonly Regex StripTags = new Regex("<[^>]+>", RegexOptions.Compiled);
		static readonly Regex Ws        = new Regex(@"[ \t\f\v]+", RegexOptions.Compiled);
		static readonly Regex MultiNl   = new Regex(@"\n{3,}", RegexOptions.Compiled);
		static readonly Regex TitleRx   = new Regex(@"<title[^>]*>(.*?)</title>", RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
		static readonly Regex MainRx    = new Regex(@"<main[^>]*>(.*?)</main>", RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
		static readonly Regex ArtRx     = new Regex(@"<article[^>]*>(.*?)</article>", RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);
		static readonly Regex BodyRx    = new Regex(@"<body[^>]*>(.*?)</body>", RegexOptions.IgnoreCase | RegexOptions.Singleline | RegexOptions.Compiled);

		public static string HtmlToText(string html, int maxLength) {
			if (string.IsNullOrEmpty(html)) return "";
			string title = "No title";
			var tm = TitleRx.Match(html);
			if (tm.Success) title = Ws.Replace(tm.Groups[1].Value, " ").Trim();

			html = ScriptTag.Replace(html, " ");
			html = StyleTag.Replace(html, " ");
			html = Comment.Replace(html, " ");
			html = Noscript.Replace(html, " ");

			string main = html;
			var m = MainRx.Match(html);
			if (m.Success) main = m.Groups[1].Value;
			else {
				m = ArtRx.Match(html);
				if (m.Success) main = m.Groups[1].Value;
				else {
					m = BodyRx.Match(html);
					if (m.Success) main = m.Groups[1].Value;
				}
			}

			main = Regex.Replace(main, @"</(p|div|li|tr|h[1-6]|br|hr)[^>]*>", "\n", RegexOptions.IgnoreCase);
			main = Regex.Replace(main, @"<br\s*/?>", "\n", RegexOptions.IgnoreCase);
			main = BlockTags.Replace(main, " ");
			string text = StripTags.Replace(main, " ");
			text = System.Net.WebUtility.HtmlDecode(text);
			text = Ws.Replace(text, " ");
			text = MultiNl.Replace(text.Replace("\r\n", "\n").Replace('\r', '\n'), "\n\n").Trim();

			if (maxLength > 0 && text.Length > maxLength)
				text = text.Substring(0, maxLength) + "\n\n[content truncated]";

			return "**Title:** " + title + "\n\n**Content:**\n" + text;
		}

		public static volatile bool CancelRequested = false;
		// Host can set this each wait tick (e.g. WPF Esc / window close). Keeps long runs interruptible.
		public static volatile bool ExternalCancel = false;
		public static volatile int ActiveChildPid = 0;
		const int MaxCaptureChars = 1500000;

		public class RunResult {
			public int ExitCode;
			public string StdOut;
			public string StdErr;
			public long ElapsedMs;
			public bool TimedOut;
			public bool Cancelled;
			public int Pid;
		}

		// Kill process and all descendants (PS sandbox often leaves grandchild powershell.exe alive).
		public static void KillProcessTree(int pid) {
			if (pid <= 0) return;
			try {
				var psi = new ProcessStartInfo {
					FileName = "taskkill.exe",
					Arguments = "/F /T /PID " + pid,
					UseShellExecute = false,
					CreateNoWindow = true,
					RedirectStandardOutput = true,
					RedirectStandardError = true
				};
				using (var tk = Process.Start(psi)) {
					if (tk != null) tk.WaitForExit(8000);
				}
			} catch {
				try {
					using (var p = Process.GetProcessById(pid)) {
						p.Kill();
						p.WaitForExit(3000);
					}
				} catch {}
			}
		}

		static void AppendCapped(StringBuilder sb, string line) {
			if (line == null || sb == null) return;
			lock (sb) {
				if (sb.Length >= MaxCaptureChars) return;
				int room = MaxCaptureChars - sb.Length;
				if (line.Length + 2 > room) {
					if (room > 32) sb.Append(line.Substring(0, room - 32)).Append("\n...[output capped]...\n");
					return;
				}
				sb.AppendLine(line);
			}
		}

		public static RunResult RunProcess(string fileName, string arguments, string workingDir, int timeoutMs) {
			var sw = Stopwatch.StartNew();
			var result = new RunResult { ExitCode = -1 };
			var psi = new ProcessStartInfo {
				FileName = fileName,
				Arguments = arguments ?? "",
				WorkingDirectory = string.IsNullOrEmpty(workingDir) ? Environment.CurrentDirectory : workingDir,
				UseShellExecute = false,
				RedirectStandardOutput = true,
				RedirectStandardError = true,
				CreateNoWindow = true,
				// UTF-8 with replacement: invalid sequences become U+FFFD.
				// PowerShell children are forced to UTF-8 by the PS wrapper in Invoke-RunCommand.
				StandardOutputEncoding = new UTF8Encoding(false, false),
				StandardErrorEncoding = new UTF8Encoding(false, false)
			};

			var sbOut = new StringBuilder();
			var sbErr = new StringBuilder();
			int pid = 0;

			using (var proc = new Process()) {
				proc.StartInfo = psi;
				proc.EnableRaisingEvents = false;
				proc.OutputDataReceived += (s, e) => { if (e.Data != null) AppendCapped(sbOut, e.Data); };
				proc.ErrorDataReceived  += (s, e) => { if (e.Data != null) AppendCapped(sbErr, e.Data); };

				try {
					CancelRequested = false;
					ExternalCancel = false;
					proc.Start();
					try { pid = proc.Id; result.Pid = pid; ActiveChildPid = pid; } catch { pid = 0; }
					proc.BeginOutputReadLine();
					proc.BeginErrorReadLine();

					while (!proc.HasExited) {
						try {
							if (Console.KeyAvailable) {
								var key = Console.ReadKey(true);
								if (key.Key == ConsoleKey.Escape) CancelRequested = true;
							}
						} catch {}

						if (CancelRequested || ExternalCancel) {
							try { KillProcessTree(pid > 0 ? pid : proc.Id); } catch { try { proc.Kill(); } catch {} }
							result.Cancelled = true;
							try { proc.WaitForExit(5000); } catch {}
							break;
						}
						if (timeoutMs > 0 && sw.ElapsedMilliseconds > timeoutMs) {
							try { KillProcessTree(pid > 0 ? pid : proc.Id); } catch { try { proc.Kill(); } catch {} }
							result.TimedOut = true;
							try { proc.WaitForExit(5000); } catch {}
							break;
						}
						Thread.Sleep(40);
					}

					if (!result.Cancelled && !result.TimedOut) {
						proc.WaitForExit(2000);
						try { result.ExitCode = proc.ExitCode; } catch { result.ExitCode = -1; }
					} else if (proc.HasExited) {
						try { result.ExitCode = proc.ExitCode; } catch { result.ExitCode = -1; }
					}
				} catch (Exception ex) {
					sbErr.AppendLine(ex.Message);
					if (pid > 0) { try { KillProcessTree(pid); } catch {} }
				} finally {
					if (ActiveChildPid == pid) ActiveChildPid = 0;
				}
			}

			sw.Stop();
			result.ElapsedMs = sw.ElapsedMilliseconds;
			result.StdOut = sbOut.ToString();
			result.StdErr = sbErr.ToString();
			return result;
		}

		public static string TruncateMiddle(string text, int maxChars) {
			if (string.IsNullOrEmpty(text) || maxChars <= 0 || text.Length <= maxChars) return text ?? "";
			int keep = maxChars / 2 - 40;
			if (keep < 200) keep = 200;
			int head = keep;
			int tail = maxChars - keep - 80;
			if (tail < 100) tail = 100;
			return text.Substring(0, head)
				+ "\n\n... [" + (text.Length - head - tail) + " chars omitted] ...\n\n"
				+ text.Substring(text.Length - tail);
		}

		// Speech PTT (user32). VK_RCONTROL=0xA3 only.
		[DllImport("user32.dll")]
		static extern short GetAsyncKeyState(int vKey);

		public static bool IsKeyDown(int vKey) {
			try { return (GetAsyncKeyState(vKey) & 0x8000) != 0; }
			catch { return false; }
		}

		public static bool IsSpeechPttDown() {
			return IsKeyDown(0xA3); // Right-Ctrl only
		}
	}

	// Default playback volume/mute via Core Audio EndpointVolume (IAudioEndpointVolume).
	[ComImport, Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")]
	class MMDeviceEnumeratorComObject { }

	[Guid("A95664D2-9614-4F35-A746-DE8DB63617E6"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
	interface IMMDeviceEnumerator {
		[PreserveSig] int EnumAudioEndpoints(int dataFlow, int dwStateMask, out IntPtr ppDevices);
		[PreserveSig] int GetDefaultAudioEndpoint(int dataFlow, int role, out IMMDevice ppEndpoint);
	}

	[Guid("D666063F-1587-4E43-81F1-B948E807363F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
	interface IMMDevice {
		[PreserveSig] int Activate(ref Guid iid, int dwClsCtx, IntPtr pActivationParams, [MarshalAs(UnmanagedType.IUnknown)] out object ppInterface);
	}

	[Guid("5CDF2C82-841E-4546-9722-0CF74078229A"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
	interface IAudioEndpointVolume {
		[PreserveSig] int RegisterControlChangeNotify(IntPtr pNotify);
		[PreserveSig] int UnregisterControlChangeNotify(IntPtr pNotify);
		[PreserveSig] int GetChannelCount(out uint pnChannelCount);
		[PreserveSig] int SetMasterVolumeLevel(float fLevelDB, Guid pguidEventContext);
		[PreserveSig] int SetMasterVolumeLevelScalar(float fLevel, Guid pguidEventContext);
		[PreserveSig] int GetMasterVolumeLevel(out float pfLevelDB);
		[PreserveSig] int GetMasterVolumeLevelScalar(out float pfLevel);
		[PreserveSig] int SetChannelVolumeLevel(uint nChannel, float fLevelDB, Guid pguidEventContext);
		[PreserveSig] int SetChannelVolumeLevelScalar(uint nChannel, float fLevel, Guid pguidEventContext);
		[PreserveSig] int GetChannelVolumeLevel(uint nChannel, out float pfLevelDB);
		[PreserveSig] int GetChannelVolumeLevelScalar(uint nChannel, out float pfLevel);
		[PreserveSig] int SetMute([MarshalAs(UnmanagedType.Bool)] bool bMute, Guid pguidEventContext);
		[PreserveSig] int GetMute([MarshalAs(UnmanagedType.Bool)] out bool pbMute);
	}

	public static class AudioEndpoint {
		const int eRender = 0;
		const int CLSCTX_ALL = 23;

		static IAudioEndpointVolume TryGetVol(out string error, out int roleUsed) {
			error = null;
			roleUsed = -1;
			IMMDeviceEnumerator enu = null;
			try {
				enu = (IMMDeviceEnumerator)(new MMDeviceEnumeratorComObject());
			} catch (Exception ex) {
				error = "MMDeviceEnumerator unavailable: " + ex.Message;
				return null;
			}
			int[] roles = new int[] { 1, 0, 2 };
			Guid iid = typeof(IAudioEndpointVolume).GUID;
			foreach (int role in roles) {
				IMMDevice dev = null;
				try {
					int hr = enu.GetDefaultAudioEndpoint(eRender, role, out dev);
					if (hr < 0 || dev == null) continue;
					object o = null;
					hr = dev.Activate(ref iid, CLSCTX_ALL, IntPtr.Zero, out o);
					if (hr < 0 || o == null) continue;
					IAudioEndpointVolume vol = o as IAudioEndpointVolume;
					if (vol == null) continue;
					roleUsed = role;
					return vol;
				} catch { }
			}
			error = "No default playback endpoint (render). Check Sound settings / external audio.";
			return null;
		}

		public static bool TryGet(out float level, out bool mute, out string error, out int role) {
			level = 0f;
			mute = false;
			error = null;
			role = -1;
			try {
				IAudioEndpointVolume vol = TryGetVol(out error, out role);
				if (vol == null) return false;
				float v;
				int hr = vol.GetMasterVolumeLevelScalar(out v);
				if (hr < 0) {
					error = "GetMasterVolumeLevelScalar failed HR=0x" + hr.ToString("X8");
					return false;
				}
				bool m = false;
				hr = vol.GetMute(out m);
				if (hr < 0) {
					level = v;
					mute = false;
					error = null;
					return true;
				}
				level = v;
				mute = m;
				return true;
			} catch (NullReferenceException) {
				error = "Audio endpoint COM object was null (no default device or driver oddity).";
				return false;
			} catch (Exception ex) {
				error = ex.Message;
				return false;
			}
		}

		public static bool TrySetLevel(float v, out string error) {
			error = null;
			try {
				if (v < 0f) v = 0f;
				if (v > 1f) v = 1f;
				int role;
				IAudioEndpointVolume vol = TryGetVol(out error, out role);
				if (vol == null) return false;
				int hr = vol.SetMasterVolumeLevelScalar(v, Guid.Empty);
				if (hr < 0) {
					error = "SetMasterVolumeLevelScalar failed HR=0x" + hr.ToString("X8");
					return false;
				}
				return true;
			} catch (NullReferenceException) {
				error = "Audio endpoint COM object was null while setting level.";
				return false;
			} catch (Exception ex) {
				error = ex.Message;
				return false;
			}
		}

		public static bool TrySetMute(bool m, out string error) {
			error = null;
			try {
				int role;
				IAudioEndpointVolume vol = TryGetVol(out error, out role);
				if (vol == null) return false;
				int hr = vol.SetMute(m, Guid.Empty);
				if (hr < 0) {
					error = "SetMute failed HR=0x" + hr.ToString("X8");
					return false;
				}
				return true;
			} catch (NullReferenceException) {
				error = "Audio endpoint COM object was null while setting mute.";
				return false;
			} catch (Exception ex) {
				error = ex.Message;
				return false;
			}
		}
	}

}
'@

	try {
		Add-Type -TypeDefinition $miniBotCs -Language CSharp -ErrorAction Stop
	} catch {
		if (-not ("MiniBot.Core.Native" -as [type])) {
			Write-Warning "MiniBot C# helpers failed to load: $($_.Exception.Message). Falling back to pure PowerShell."
		}
	}
}

