DOCS: SearchMicrosoftLearn / ReadMicrosoftLearn (learn.microsoft.com only); SearchSs64 / ReadSs64 (ss64.com only — Windows CMD, PowerShell, bash). Search then Read best URL. Cap pages; quote official syntax/flags. Prefer over guessing cmdlets or inventing registry paths. General web = web group.
"@
	web = @"
WEB: SearchWeb (query→title/url/snippet) then BrowsePage on best URLs. MakeHttpRequest for APIs. BrowsePage returns readable text + links + needs_render if JS shell. GitHub: ConvertGitHubUrl/GetGitHubRawFile/ListGitHubDirectory. Downloads→files DownloadFile. Official MS Learn / SS64 = docs group.
"@
}

function Build-MBSystemPromptLive {
	$parts = New-Object System.Collections.ArrayList
	[void]$parts.Add([string]$script:MBSystemPromptBase)

	$active = @()
	try { $active = @($script:MB.ActiveToolGroups) } catch { $active = @('core') }
	if ($active.Count -eq 0) { $active = @('core') }
	$activeSet = @{}
	foreach ($g in $active) {
		if ($g) { $activeSet[[string]$g.ToLowerInvariant()] = $true }
	}
	if ($activeSet.ContainsKey('full') -or $activeSet.ContainsKey('all')) {
		foreach ($k in @($script:MBGroupPrompt.Keys)) { $activeSet[$k] = $true }
	}
	if (-not $activeSet.ContainsKey('core')) { $activeSet['core'] = $true }

	$order = @('core','vision','sound','forensics','system','network','diag','repair','setup','identity','shares','installers','sandbox','files','packages','registry','clipboard','docs','web')
	$onList = New-Object System.Collections.ArrayList
	$offBits = New-Object System.Collections.ArrayList
	foreach ($g in $order) {
		if ($activeSet.ContainsKey($g)) {
			[void]$onList.Add($g)
			if ($script:MBGroupPrompt.Contains($g)) {
				$snip = ([string]$script:MBGroupPrompt[$g]).Trim()
				if ($snip) { [void]$parts.Add($snip) }
			}
		} else {
			[void]$offBits.Add($g)
		}
	}

	[void]$parts.Add(("ON: {0}." -f (($onList | ForEach-Object { $_ }) -join ',')))
	if ($offBits.Count -gt 0) {
		[void]$parts.Add(("OFF (EnableToolGroup group=a,b): {0}." -f ($offBits -join ',')))
	}
	return (($parts | Where-Object { $_ -and "$_".Trim() }) -join "`n")
}

function Get-MBSystemPrompt {
	# Base system prompt; frozen mid tool-loop for prompt-cache stability.
	try {
		if ([bool]$script:MB.WireStateFrozen -and -not [string]::IsNullOrEmpty([string]$script:MB.FrozenBaseContent)) {
			return [string]$script:MB.FrozenBaseContent
		}
	} catch {}
	return (Build-MBSystemPromptLive)
}

$SystemPrompt = Get-MBSystemPrompt

$Tools = @(
	@{ type = "function"; function = @{ name = "ReadFile"; description = "Read text files (head/tail/offset+length). NEVER images/video/PDF/binary — use vision tools or ![path]."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; head = @{ type = "integer" }; tail = @{ type = "integer" }; offset = @{ type = "integer" }; length = @{ type = "integer" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "WriteFile"; description = "Create/overwrite whole file. Prefer EditFile/ApplyPatch for edits. ALWAYS prompts. Default backup=true writes path.bak before overwrite."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; content = @{ type = "string" }; backup = @{ type = "boolean"; description = "Write path.bak before overwrite (default true; ignored on create)" } }; required = @("path","content") } } },
	@{ type = "function"; function = @{ name = "EditFile"; description = "Search/replace (unique match default). replaceAll / occurrence / edits[] supported. ALWAYS prompts. Default backup=true writes path.bak first. Prefer ReadFile first."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; search = @{ type = "string" }; replace = @{ type = "string" }; useRegex = @{ type = "boolean" }; replaceAll = @{ type = "boolean" }; occurrence = @{ type = "integer" }; backup = @{ type = "boolean"; description = "Write path.bak before apply (default true)" }; edits = @{ type = "array"; items = @{ type = "object"; properties = @{ search = @{ type = "string" }; replace = @{ type = "string" }; useRegex = @{ type = "boolean" }; replaceAll = @{ type = "boolean" }; occurrence = @{ type = "integer" } }; required = @("search","replace") } } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "ApplyPatch"; description = "Apply unified diff / *** Update File patch. Creates files when --- /dev/null or *** Add File. ALWAYS prompts. Default backup=true for existing targets."; parameters = @{ type = "object"; properties = @{ patch = @{ type = "string" }; path = @{ type = "string" }; backup = @{ type = "boolean"; description = "Write path.bak before patching existing files (default true)" } }; required = @("patch") } } },
	@{ type = "function"; function = @{ name = "RunCommand"; description = "Run PowerShell (default) or cmd. Pass exact command text. Mutating/multi-statement/redirects need approval."; parameters = @{ type = "object"; properties = @{ command = @{ type = "string" }; shell = @{ type = "string"; enum = @("powershell","cmd") }; timeout_sec = @{ type = "integer" } }; required = @("command") } } },
	@{ type = "function"; function = @{ name = "RemoteCommand"; description = "Domain-administrator remoting tool (WinRM only). REQUIRES this host domain-joined with a signed-in domain user (orange/unavailable on workgroup or local-user sessions). Run a command on a REMOTE host (not this PC). ALWAYS approval. Native WinRM/PowerShell remoting. host= + command= required. shell=powershell|cmd|pwsh. Prefer username=DOMAIN\\DomainAdmin + password. Empty password only if account is truly blank. Optional port, use_ssl, timeout_sec. transport=winrm only. On auth failure NEED_INPUT for domain admin credentials. Do not use local RunCommand for remote hosts."; parameters = @{ type = "object"; properties = @{ host = @{ type = "string"; description = "Remote IP or hostname (also accepts user@host or host:port)" }; computer = @{ type = "string"; description = "Alias for host" }; command = @{ type = "string"; description = "Command/script to run on the remote host" }; transport = @{ type = "string"; description = "winrm only (default)" }; shell = @{ type = "string"; description = "powershell (default), cmd, or pwsh" }; username = @{ type = "string"; description = "Domain account preferred: DOMAIN\\DomainAdmin (domain admin tool)" }; password = @{ type = "string"; description = "Domain account password (WinRM). Empty only if truly blank" }; port = @{ type = "integer"; description = "WinRM port (default 5985 / 5986 with use_ssl)" }; use_ssl = @{ type = "boolean"; description = "WinRM over HTTPS" }; timeout_sec = @{ type = "integer"; description = "Timeout seconds (default harness CommandTimeout)" } }; required = @("host","command") } } },
	@{ type = "function"; function = @{ name = "ListDirectory"; description = "List directory (≤500; truncated flag)."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "SearchFiles"; description = "Regex search file contents under path."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; pattern = @{ type = "string" }; glob = @{ type = "string" }; recursive = @{ type = "boolean" }; ignoreCase = @{ type = "boolean" }; maxResults = @{ type = "integer" } }; required = @("path","pattern") } } },
	@{ type = "function"; function = @{ name = "DiffText"; description = "Unified line diff (LCS-based) of two strings or files. Shows @@ hunks with context."; parameters = @{ type = "object"; properties = @{ left = @{ type = "string" }; right = @{ type = "string" }; leftIsFile = @{ type = "boolean" }; rightIsFile = @{ type = "boolean" }; context = @{ type = "integer"; description = "Context lines around changes (default 3)" }; maxLines = @{ type = "integer"; description = "Max output lines (default 200)" } }; required = @("left","right") } } },
	@{ type = "function"; function = @{ name = "HexView"; description = "Binary/PE forensics: hex dump + PE labels; disasm=true x86/x64 with IAT/delay/export labels + uncertain resync; hash=true SHA256 file+sections; functions=true prologue scan; entropy/carve; at_entry/rva/section. Flags .NET managed. DIFF path2. Prefer over ReadAllBytes. HexEdit presets; HexSearch; StringsScan."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Primary file" }; path2 = @{ type = "string"; description = "Optional compare file (diff mode)" }; compare = @{ type = "string"; description = "Alias for path2" }; offset = @{ type = "string"; description = "Start offset decimal or 0xHEX" }; length = @{ type = "integer"; description = "Bytes to show (default 256, max 16384)" }; width = @{ type = "integer"; description = "Bytes per line (default 16)" }; show_ascii = @{ type = "boolean" }; annotate = @{ type = "boolean"; description = "PE headers/sections + strings (default false; use detail=full for tour)" }; next_diff = @{ type = "boolean"; description = "With path2: seek next byte difference from offset" }; side_by_side = @{ type = "boolean"; description = "Diff layout side-by-side (default true)" }; max_scan = @{ type = "integer"; description = "Optional max bytes to scan for next_diff (0=full)" }; disasm = @{ type = "boolean"; description = "x86/x64 disassembly; IAT/export labels on indirect calls" }; trace = @{ type = "boolean"; description = "Walk control flow from offset (follow JMP; list JE/JNE both paths)" }; at_entry = @{ type = "boolean"; description = "Start at PE entry point file offset" }; rva = @{ type = "string"; description = "PE RVA (decimal/0x) -> map to file offset" }; section = @{ type = "string"; description = "PE section name (e.g. .text) -> start raw offset" }; max_insns = @{ type = "integer"; description = "Disasm instruction count (default 48, max 200)" }; max_steps = @{ type = "integer"; description = "Trace steps (default 32, max 80)" }; follow_calls = @{ type = "boolean"; description = "trace: step into CALL targets" }; prefer_branch = @{ type = "string"; description = "trace: fallthrough (default) or taken at Jcc" }; arch = @{ type = "string"; description = "auto|x86|x64 (default auto from PE)" }; dump_hex = @{ type = "boolean"; description = "Include hex dump (default true)" }; entropy = @{ type = "boolean"; description = "Shannon entropy map (high = packed/encrypted)" }; entropy_blocks = @{ type = "integer"; description = "Entropy windows (default 64)" }; carve = @{ type = "boolean"; description = "Find embedded MZ/PE images" }; hash = @{ type = "boolean"; description = "SHA256 of file + each PE section" }; functions = @{ type = "boolean"; description = "Heuristic function prologue scan in .text" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "HexEdit"; description = "Patch bytes at offset. hex= or bytes[] OR preset=force_jcc|nop_range|ret0|ret|int3 (length= for nop/int3 count). ALWAYS prompts with disasm before/after. Default backup=true path.bak."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; offset = @{ type = "string" }; hex = @{ type = "string" }; bytes = @{ type = "array"; items = @{ type = "integer" } }; preset = @{ type = "string"; description = "force_jcc|nop_range|ret0|ret|int3" }; length = @{ type = "integer"; description = "Byte count for nop_range/int3 presets" }; extend = @{ type = "boolean" }; backup = @{ type = "boolean"; description = "Write path.bak before patch (default true)" } }; required = @("path","offset") } } },
	@{ type = "function"; function = @{ name = "HexSearch"; description = "Search file for hex byte pattern with ?? wildcards (e.g. pattern='E8 ?? ?? ?? ??' or '4D 5A'). Returns file offsets. Follow with HexView offset=..."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; pattern = @{ type = "string"; description = "Hex bytes with optional ?? wildcards" }; hex = @{ type = "string"; description = "Alias for pattern" }; offset = @{ type = "string"; description = "Start offset" }; maxResults = @{ type = "integer"; description = "Max hits (default 32)" }; max_scan = @{ type = "integer"; description = "Max bytes to scan from offset (0=to EOF)" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "StringsScan"; description = "Full-file ASCII/UTF-16LE string extraction. filter=path|url|ip|registry|email|interesting or substring. Prefer over dumping whole binary with ReadFile."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; minLen = @{ type = "integer"; description = "Minimum string length (default 4)" }; maxHits = @{ type = "integer"; description = "Max strings (default 80)" }; offset = @{ type = "string" }; max_scan = @{ type = "integer"; description = "Max bytes to scan (0=full file)" }; encoding = @{ type = "string"; description = "ascii|utf16|both (default both)" }; filter = @{ type = "string"; description = "path|url|ip|registry|email|interesting or free text" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "GetWorkingDirectory"; description = "Agent CWD."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "SetWorkingDirectory"; description = "Set agent CWD."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "GetEnvironment"; description = "Env vars / PATH summary."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string" } } } } },
	@{ type = "function"; function = @{ name = "SetEnvironment"; description = "Set env var. User/Machine ALWAYS prompt; Process does not."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string" }; value = @{ type = "string" }; target = @{ type = "string" } }; required = @("name","value") } } },
	@{ type = "function"; function = @{ name = "GetSystemInfo"; description = "Basic system information as JSON (OS/CPU/RAM/IPs). Prefer over Get-ComputerInfo or broad inventory shells."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "GetProcessList"; description = "Top processes by CPU as JSON."; parameters = @{ type = "object"; properties = @{ limit = @{ type = "integer" } } } } },
	@{ type = "function"; function = @{ name = "StopProcess"; description = "Stop one or more processes. ALWAYS approval. Prefer pid= from GetProcessList; or name= ProcessName (without .exe). force=true (default) uses Force. Never kills MiniBot itself or protected system processes (csrss, lsass, services, smss, wininit, winlogon, System, svchost, dwm, ...). Prefer over taskkill in RunCommand."; parameters = @{ type = "object"; properties = @{ pid = @{ type = "integer"; description = "Process id (preferred)" }; process_id = @{ type = "integer"; description = "Alias for pid" }; name = @{ type = "string"; description = "ProcessName without .exe (may match multiple)" }; force = @{ type = "boolean"; description = "Force kill (default true)" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "GetProcessTree"; description = "Process parent/child tree (pid, ppid, name, depth). Optional root_pid to start from one process."; parameters = @{ type = "object"; properties = @{ root_pid = @{ type = "integer"; description = "Start from this PID (0 = all roots)" }; max_depth = @{ type = "integer"; description = "Max tree depth (default 6)" }; max_nodes = @{ type = "integer"; description = "Cap nodes returned (default 200)" } } } } },
	@{ type = "function"; function = @{ name = "GetNetConnections"; description = "TCP connections/listeners (local/remote address:port, state, pid, process). Like netstat."; parameters = @{ type = "object"; properties = @{ state = @{ type = "string"; description = "Filter e.g. Listen, Established" }; port = @{ type = "integer"; description = "Filter by local or remote port" }; max = @{ type = "integer"; description = "Max rows (default 100)" } } } } },
	@{ type = "function"; function = @{ name = "FindFiles"; description = "Find by name/ext/size/days. Multi-ext one call (extensions=[mp4,mkv] or glob='*.mp4;*.mkv'). Cap max=100 (hard 500), newest first; truncated=use rows (specific->narrow; vague play->pick one then INLINE ![label](path)). Content->SearchFiles."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; glob = @{ type = "string" }; globs = @{ type = "array"; items = @{ type = "string" } }; extensions = @{ type = "array"; items = @{ type = "string" } }; modified_within_days = @{ type = "integer" }; min_bytes = @{ type = "integer" }; max_bytes = @{ type = "integer" }; recursive = @{ type = "boolean" }; max = @{ type = "integer" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "ReadImage"; description = "Load an image for vision (next model reply can see it). png/jpg/gif/bmp/tif/webp. ALWAYS heavily downscales for the model (default max side ~896px, hard max 1024, max ~0.72MP, JPEG) so large TIFFs/photos cannot OOM llama.cpp. Optional maxWidth is clamped. Prefer small/cropped images. To show the operator the full file without vision cost PREFER inline markdown ![label](absolute-path) in your reply. No approval."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; maxWidth = @{ type = "integer"; description = "Vision max side px (default ~896, hard-capped at 1024)" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "ReadPdf"; description = "Read a PDF (cheap path first). Default page=1 only - multipage vision is expensive; only set page>1 or call again for other pages if the user needs them or page 1 is insufficient. Extracts text when clean; if empty/garbled, auto-renders that one page into vision. render=true forces vision; maxWidth downscales vision."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; maxChars = @{ type = "integer"; description = "Max text chars (default 50000)" }; page = @{ type = "integer"; description = "1-based page for vision render (default 1). Prefer 1 unless user needs another page." }; render = @{ type = "boolean"; description = "Force page render to vision even if text looks fine" }; autoVision = @{ type = "boolean"; description = "Auto-render when text empty/garbled (default true)" }; maxWidth = @{ type = "integer"; description = "Vision max width px (default 1280)" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "Clipboard"; description = "Read or write clipboard text. Always requires approval."; parameters = @{ type = "object"; properties = @{ action = @{ type = "string"; enum = @("read","write") }; text = @{ type = "string" } }; required = @("action") } } },
	@{ type = "function"; function = @{ name = "ViewScreen"; description = "Look at the desktop for vision (MemoryStream base64; NO file by default). NO approval. DEFAULT: omit save and path - capture stays in memory for the next model turn only. ONLY set save=true or path= when the user explicitly wants a PNG on disk. After a disk save, reply with the exact path. monitor: primary|all|0|1|... Do not save screenshots unprompted."; parameters = @{ type = "object"; properties = @{ save = @{ type = "boolean"; description = "Write PNG to disk. Default false = memory only. true without path = Desktop. Only when user asked to save." }; path = @{ type = "string"; description = "Disk save path (file or folder). Implies save. Only when user asked for a file. Omit for look-only." }; monitor = @{ type = "string"; description = "primary | all | 0-based monitor index" }; x = @{ type = "integer" }; y = @{ type = "integer" }; width = @{ type = "integer" }; height = @{ type = "integer" }; maxWidth = @{ type = "integer"; description = "Vision downscale max width (default 1280); disk save (if any) is full-res" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "GetBSODInfo"; description = "Recent BSOD/minidump info + related events."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "GetEventLogs"; description = "Recent errors/warnings + disk I/O events. Collapses duplicate Id+Provider (e.g. DCOM 10016 spam) into Count. Default hours=72 max=40."; parameters = @{ type = "object"; properties = @{ hours = @{ type = "integer"; description = "Lookback hours (default 72, max 168)" }; max = @{ type = "integer"; description = "Max unique event rows (default 40)" } } } } },
	@{ type = "function"; function = @{ name = "GetDiskHealth"; description = "Physical disk health + SMART counters."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "GetDiskSpace"; description = "Drive free/used + top folders under path. Recursive sizes use a fast Win32 FindFirstFileEx walk, not PowerShell Get-ChildItem -Recurse."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Folder whose top-level children are sized (default C:\\)" }; deep = @{ type = "boolean"; description = "true (default) = full recursive under each top-level child; false = immediate files only" }; top = @{ type = "integer"; description = "How many largest folders to return (default 10)" }; timeout_sec = @{ type = "integer"; description = "Scan budget seconds (default 45)" } } } } },
	@{ type = "function"; function = @{ name = "GetInstalledSoftware"; description = "Installed programs (Uninstall registry). Optional name filter; caps results for context."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string"; description = "Filter by display name or publisher (substring)" }; max = @{ type = "integer"; description = "Max rows (default 200, max 1000)" } } } } },
	@{ type = "function"; function = @{ name = "GetDriverInfo"; description = "Query PnP drivers with filters."; parameters = @{ type = "object"; properties = @{ filter = @{ type = "string"; description = "unsigned, microsoft, realtek, nvidia, network, audio, storage, or free text" }; limit = @{ type = "integer" }; showAll = @{ type = "boolean" } } } } },
	@{ type = "function"; function = @{ name = "GetStartupItems"; description = "Startup programs + automatic services (capped; default max_services=25, system noise deprioritized)."; parameters = @{ type = "object"; properties = @{ max_services = @{ type = "integer"; description = "Max auto services to return (default 25)" }; include_all_services = @{ type = "boolean"; description = "true = dump all auto services up to max (default false prioritizes non-system)" } } } } },
	@{ type = "function"; function = @{ name = "GetMemoryInfo"; description = "RAM usage + top consumers."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "GetNetworkInfo"; description = "Adapters + connectivity test."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "GetLocalShares"; description = "List SMB shares published on THIS PC (not remote discovery). Read-only. Returns share name, path, and who has access: share_access / access_summary (share ACL via Get-SmbShareAccess) plus optional ntfs_access on the folder. Special shares (C$, ADMIN$, IPC$) omitted unless include_special=true. include_ntfs=false for share ACL only. Clipboard copy is opt-in: copy_clipboard=true. For remote shares use FindShares; to create use CreateShare; to unpublish use RemoveShare."; parameters = @{ type = "object"; properties = @{ include_special = @{ type = "boolean"; description = "Include admin/special shares ending in $ (default false)" }; include_ntfs = @{ type = "boolean"; description = "Include NTFS ACL on share path (default true)" }; copy_clipboard = @{ type = "boolean"; description = "Copy first UNC to clipboard (default false, opt-in)" }; max = @{ type = "integer"; description = "Max shares (default 80)" } } } } },
	@{ type = "function"; function = @{ name = "GetMappedDrives"; description = "List network drive mappings on THIS PC (letter -> UNC, status). Read-only. Combines Get-SmbMapping, PSDrive, net use. include_disconnected=false to hide Unavailable. Not for finding remote shares (FindShares) or mapping (MapNetworkDrive). To disconnect use RemoveMappedDrive (setup group)."; parameters = @{ type = "object"; properties = @{ include_disconnected = @{ type = "boolean"; description = "Include Unavailable/Disconnected maps (default true)" } } } } },
	@{ type = "function"; function = @{ name = "GetPrinters"; description = "List printers on THIS PC (local + network connections). Read-only. Returns name, port, driver, default, shared. Use RemoveNetworkPrinter to remove; AddNetworkPrinter to add a UNC printer."; parameters = @{ type = "object"; properties = @{ include_remote = @{ type = "boolean"; description = "Include network/UNC printers (default true)" }; max = @{ type = "integer"; description = "Max rows (default 80)" } } } } },
	@{ type = "function"; function = @{ name = "ScanNetwork"; description = "Scan the local LAN for machines and identify them (IP, MAC, hostname, MAC vendor). Harness-native LAN discovery (no GUI). Discovery: active=true (default) uses fast flood-ping - Test-Connection -Count 1 -AsJob for the whole subnet at once then Wait-Job. Then ARP/neighbors + SendARP MAC discovery (required for vendor OUI), reverse DNS, macvendorlookup. active=false = ARP only (quieter). Default auto primary private /24. Returns sorted hosts. To find which hosts export a share, call FindShares next (not RunCommand)."; parameters = @{ type = "object"; properties = @{ subnet = @{ type = "string"; description = "Optional CIDR or prefix e.g. 192.168.1.0/24 or 192.168.1. (default auto)" }; active = @{ type = "boolean"; description = "Flood-ping subnet then ARP/MAC resolve (default true). false = neighbors only" }; resolve_mac = @{ type = "boolean"; description = "SendARP MAC discovery for IPs missing MAC (default true; required for vendors)" }; resolve_hostnames = @{ type = "boolean"; description = "Reverse DNS (default true)" }; resolve_vendors = @{ type = "boolean"; description = "MAC OUI vendor lookup (default true; needs internet + MAC)" }; timeout_ms = @{ type = "integer"; description = "Wait-Job timeout budget ms for flood (default 4000 effective floor)" }; max_hosts = @{ type = "integer"; description = "Max addresses to flood-ping (default 254, max 1022)" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "FindShares"; description = "REQUIRED tool when the user asks to find/locate/discover a network share (or which PC has a named share). Do not use RunCommand. TARGETED: computer=IP or hosts=['IP'] only those machines. SEARCH: omit hosts = auto LAN flood then probe. Then TCP 445/139 (PortProbe) + timed net use guess (share_name=temp or common names). Optional username/password; access-denied still means share exists. Returns found_uncs/hosts_with_match - next call MapNetworkDrive (setup group). Not for creating shares (use CreateShare)."; parameters = @{ type = "object"; properties = @{ hosts = @{ type = "array"; items = @{ type = "string" }; description = "Known host IPs (targeted). Omit for auto LAN search." }; computer = @{ type = "string"; description = "Single known host (targeted)" }; share_name = @{ type = "string"; description = "Share name to try first e.g. temp" }; share_names = @{ type = "array"; items = @{ type = "string" }; description = "Extra share names to try" }; username = @{ type = "string"; description = "Optional HOST\\share for probe" }; password = @{ type = "string"; description = "Optional password for probe" }; port_timeout_ms = @{ type = "integer"; description = "TCP timeout ms (default 300)" }; probe_timeout_sec = @{ type = "integer"; description = "net use timeout sec per guess (default 3)" }; stop_on_first_match = @{ type = "boolean"; description = "Stop after first hit (default false)" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "PortProbe"; description = "Native TCP port probe (connect test). Read-only. computer= or hosts=[] (or omit for LAN flood-alive). ports=[80,443,3389] and/or profile=winrm|ssh|rdp|web|smb. Returns open/closed per host. Use before RemoteCommand or to find services. Not nmap banner scan."; parameters = @{ type = "object"; properties = @{ computer = @{ type = "string"; description = "Single host/IP" }; host = @{ type = "string"; description = "Alias for computer" }; hosts = @{ type = "array"; items = @{ type = "string" }; description = "Multiple hosts" }; ports = @{ type = "array"; items = @{ type = "integer" }; description = "TCP ports e.g. [22,80,443,3389,5985]" }; profile = @{ type = "string"; description = "winrm | ssh | rdp | web | smb (port set shortcut)" }; timeout_ms = @{ type = "integer"; description = "Per-port timeout ms (default 800)" }; max_hosts = @{ type = "integer"; description = "Max hosts when scanning (default 32)" }; use_ssl = @{ type = "boolean"; description = "For profile=winrm prefer 5986 only" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "FindWebHosts"; description = "Find LAN hosts with web ports open (80,443,8080,8443) via PortProbe. TARGETED: computer=/hosts=. SEARCH: omit hosts = ICMP flood then probe. Read-only. Not for scraping pages (use BrowsePage/MakeHttpRequest on a known URL)."; parameters = @{ type = "object"; properties = @{ computer = @{ type = "string" }; hosts = @{ type = "array"; items = @{ type = "string" } }; timeout_ms = @{ type = "integer" }; max_hosts = @{ type = "integer" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "FindRdp"; description = "Find LAN hosts with RDP open (TCP 3389) via PortProbe. TARGETED: computer=/hosts=. SEARCH: omit hosts = ICMP flood then probe. Read-only."; parameters = @{ type = "object"; properties = @{ computer = @{ type = "string" }; hosts = @{ type = "array"; items = @{ type = "string" } }; timeout_ms = @{ type = "integer" }; max_hosts = @{ type = "integer" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "GetWindowsUpdateStatus"; description = "Pending Windows updates via native Microsoft.Update.Session COM (no PSGallery). Optional PSWindowsUpdate module fallback only if COM fails."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "GetSystemUptime"; description = "Uptime and last boot."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "RunQuickDiagnostics"; description = "Bundle: BSOD, events (24h collapsed), disk health, one-level disk space, memory. Embeds objects not nested JSON strings."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "RunRepairTool"; description = "sfc, dism, or chkdsk. ALWAYS prompts for approval."; parameters = @{ type = "object"; properties = @{ tool = @{ type = "string"; enum = @("sfc","dism","chkdsk") }; driveLetter = @{ type = "string" }; arguments = @{ type = "string" } }; required = @("tool") } } },
	@{ type = "function"; function = @{ name = "GetServiceStatus"; description = "Service status. Omit name to list services (optional status filter, max cap). With name = one service."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string"; description = "Service name; omit to list many" }; status = @{ type = "string"; description = "When listing: Running|Stopped|..." }; max = @{ type = "integer"; description = "Max when listing (default 250)" } } } } },
	@{ type = "function"; function = @{ name = "ReadRegistry"; description = "Read registry key values. path: HKLM:\\SOFTWARE\\... or HKCU:\\... (also HKEY_LOCAL_MACHINE\\...)."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "e.g. HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "SetRegistry"; description = "Create/set a registry value (creates key if missing). ALWAYS prompts. path accepts HKLM:\\SOFTWARE\\... (same as ReadRegistry). type: String|ExpandString|MultiString|DWord|QWord|Binary (also REG_DWORD/REG_SZ/int)."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "e.g. HKCU:\\Software\\MyApp or HKLM:\\SOFTWARE\\..." }; name = @{ type = "string"; description = "Value name; (default) for default value" }; value = @{ type = "string"; description = "Value (hex for Binary; MultiString newline/semicolon separated; 0xHEX ok for DWord)" }; type = @{ type = "string"; description = "String (default) | ExpandString | MultiString | DWord | QWord | Binary | REG_DWORD | REG_SZ | int" } }; required = @("path","name","value") } } },
	@{ type = "function"; function = @{ name = "GetPowerInfo"; description = "Battery/power health summary as single clean JSON (ok/has_battery/fields). Soft errors as ok=false."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "GetScheduledTasks"; description = "Scheduled tasks for diagnostics/persistence hunting. Default max=30, includeSystem=false (excludes Microsoft\\Windows + SYSTEM). filter=system|enabled|recent|user or name substring."; parameters = @{ type = "object"; properties = @{ days = @{ type = "integer" }; filter = @{ type = "string" }; includeDisabled = @{ type = "boolean" }; includeSystem = @{ type = "boolean"; description = "Include Microsoft\\Windows / SYSTEM tasks (default false)" }; max = @{ type = "integer"; description = "Max tasks returned (default 30)" }; exportPath = @{ type = "string" } } } } },
	@{ type = "function"; function = @{ name = "MakeHttpRequest"; description = "HTTP client GET/POST/PUT/PATCH/DELETE/HEAD/OPTIONS with auth, headers, JSON/form/raw body. Default verify_ssl=false (bad/self-signed HTTPS via system curl -k). verify_ssl=true uses strict Invoke-WebRequest. Returns status_code, headers, body, final_url."; parameters = @{ type = "object"; properties = @{ method = @{ type = "string"; enum = @("GET","POST","PUT","PATCH","DELETE","HEAD","OPTIONS") }; url = @{ type = "string" }; headers = @{ type = "object" }; params = @{ type = "object" }; json_body = @{ type = "object" }; form_data = @{ type = "object" }; raw_data = @{ type = "string" }; bearer_token = @{ type = "string" }; basic_auth_username = @{ type = "string" }; basic_auth_password = @{ type = "string" }; cookies = @{ type = "object" }; content_type = @{ type = "string" }; verify_ssl = @{ type = "boolean"; description = "default false = curl -k for HTTPS; true = strict cert check" }; user_agent = @{ type = "string" }; timeout = @{ type = "integer"; description = "seconds (default 30, max 600)" } }; required = @("method","url") } } },
	@{ type = "function"; function = @{ name = "BrowsePage"; description = "Fetch a URL and return readable text (title, text, absolute links, final_url, content_kind). Detects JS shells (needs_render=true). Default verify_ssl=false (curl -k). Prefer SearchWeb first when discovering pages. Not for binary/PDF (use DownloadFile/ReadPdf)."; parameters = @{ type = "object"; properties = @{ url = @{ type = "string" }; max_length = @{ type = "integer"; description = "Max text chars (default 12000)" }; verify_ssl = @{ type = "boolean"; description = "default false = curl -k for HTTPS" }; user_agent = @{ type = "string" }; extract_links = @{ type = "boolean"; description = "Include links[] (default true)" }; max_links = @{ type = "integer"; description = "Max links (default 24)" } }; required = @("url") } } },
	@{ type = "function"; function = @{ name = "SearchWeb"; description = "Web search via Brave → {title,url,snippet}[]. Then BrowsePage best URLs. MS docs: use SearchMicrosoftLearn instead."; parameters = @{ type = "object"; properties = @{ query = @{ type = "string"; description = "Search query" }; max_results = @{ type = "integer"; description = "Max results (default 8, max 20)" }; engine = @{ type = "string"; description = "brave (default; only engine used)" }; verify_ssl = @{ type = "boolean"; description = "default true for search endpoints" }; user_agent = @{ type = "string" } }; required = @("query") } } },
	@{ type = "function"; function = @{ name = "SearchMicrosoftLearn"; description = "Search Microsoft Learn / docs (learn.microsoft.com). Prefer for official Windows, PowerShell, .NET, Azure, and product docs. Returns {title,url,snippet}[]. Then ReadMicrosoftLearn on the best URL. Not general web (use SearchWeb)."; parameters = @{ type = "object"; properties = @{ query = @{ type = "string"; description = "Search query e.g. Get-SmbShare, Group Policy no auto update" }; max_results = @{ type = "integer"; description = "Max results (default 8, max 15)" }; locale = @{ type = "string"; description = "Locale e.g. en-us (default en-us)" } }; required = @("query") } } },
	@{ type = "function"; function = @{ name = "ReadMicrosoftLearn"; description = "Fetch and extract readable text from a Microsoft Learn / docs.microsoft.com page. url= must be learn.microsoft.com (or docs.microsoft.com). Prefer after SearchMicrosoftLearn. Caps text length."; parameters = @{ type = "object"; properties = @{ url = @{ type = "string"; description = "Full https://learn.microsoft.com/... URL" }; max_length = @{ type = "integer"; description = "Max text chars (default 10000)" } }; required = @("url") } } },
	@{ type = "function"; function = @{ name = "SearchSs64"; description = "Search SS64 command references (ss64.com): Windows CMD, PowerShell, bash. Returns {title,url,snippet}[]. Then ReadSs64. scope=auto|ps|nt|bash biases the search."; parameters = @{ type = "object"; properties = @{ query = @{ type = "string"; description = "Command or topic e.g. robocopy, Get-ChildItem, find" }; max_results = @{ type = "integer"; description = "Max results (default 8, max 15)" }; scope = @{ type = "string"; description = "auto (default) | ps | nt | bash — PowerShell, Windows CMD, or Linux/bash" } }; required = @("query") } } },
	@{ type = "function"; function = @{ name = "ReadSs64"; description = "Fetch readable text from an ss64.com page. url= full ss64 URL, OR command= name (e.g. robocopy, dir) with optional scope=ps|nt|bash to resolve a direct page. Prefer after SearchSs64."; parameters = @{ type = "object"; properties = @{ url = @{ type = "string"; description = "Full https://ss64.com/... URL" }; command = @{ type = "string"; description = "Command name to resolve if url omitted e.g. robocopy" }; scope = @{ type = "string"; description = "When using command=: auto|ps|nt|bash (default auto tries ps then nt)" }; max_length = @{ type = "integer"; description = "Max text chars (default 10000)" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "ConvertGitHubUrl"; description = "Convert github.com URLs to raw.githubusercontent.com form."; parameters = @{ type = "object"; properties = @{ github_url = @{ type = "string" } }; required = @("github_url") } } },
	@{ type = "function"; function = @{ name = "GetGitHubRawFile"; description = "Fetch raw file content from a GitHub URL."; parameters = @{ type = "object"; properties = @{ github_url = @{ type = "string" }; max_length = @{ type = "integer" } }; required = @("github_url") } } },
	@{ type = "function"; function = @{ name = "ListGitHubDirectory"; description = "List files/folders in a GitHub repo (repo URL or tree/blob URL; optional ref)."; parameters = @{ type = "object"; properties = @{ github_url = @{ type = "string"; description = "github.com owner/repo or tree/blob URL" }; ref = @{ type = "string"; description = "Branch/tag/commit if not in URL (default main)" } }; required = @("github_url") } } },
	@{ type = "function"; function = @{ name = "SandBoxWrite"; description = "Save a named PowerShell piece (no run). Optional depends_on=[other pieces] for auto load order. Prefer small functions per piece."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string"; description = "Piece name (letters/numbers/_-)" }; code = @{ type = "string"; description = "PowerShell source for this piece" }; description = @{ type = "string"; description = "Optional short note" }; depends_on = @{ type = "array"; description = "Piece names this piece requires (loaded first when resolve_deps=true)"; items = @{ type = "string" } } }; required = @("name","code") } } },
	@{ type = "function"; function = @{ name = "SandBox"; description = "Run/check lab code. Multi-piece: merge_results=true (default) builds `$Result.by_piece / `$Result.merged; resolve_deps=true expands depends_on and topo-sorts. Assert examples: `$Result.merged.Sum -eq 5, `$Result.by_piece.math_ops.Sum -eq 5. Modes: code= | piece= | pieces=[] | save_as=. Checks: expect_*, assert[]. compose=true writes composed.ps1."; parameters = @{ type = "object"; properties = @{ code = @{ type = "string"; description = "Snippet/glue. Prefer `$Result = @{ Key = value }" }; path = @{ type = "string" }; piece = @{ type = "string"; description = "Run one piece (deps auto-included by default)" }; pieces = @{ type = "array"; description = "Pieces to run (deps expanded + sorted by default)"; items = @{ type = "string" } }; save_as = @{ type = "string" }; compose = @{ type = "boolean" }; resolve_deps = @{ type = "boolean"; description = "Expand depends_on + topo-sort (default true)" }; merge_results = @{ type = "boolean"; description = "Merge each piece `$Result into by_piece/merged (default true)" }; test_script = @{ type = "string" }; timeout_sec = @{ type = "integer" }; expect_exit = @{ type = "integer" }; expect_stdout = @{ type = "string" }; expect_stdout_regex = @{ type = "string" }; expect_stderr_empty = @{ type = "boolean" }; assert = @{ type = "array"; description = "Host asserts. `$Result has by_piece, merged, order, plus promoted merged keys"; items = @{ type = "string" } } }; required = @() } } },
	@{ type = "function"; function = @{ name = "SandBoxList"; description = "List saved pieces and last PASS/FAIL status for each (incremental progress)."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "GetSandBoxInfo"; description = "Show SandBox session root, paths (work/pieces/fixtures/out), workflow hints, last run."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "ClearSandBox"; description = "Delete SandBox scratch tree(s). Default: this session only. all=true removes every MiniBotSandbox session under %TEMP% (stale sessions too)."; parameters = @{ type = "object"; properties = @{ all = @{ type = "boolean"; description = "If true, delete ALL MiniBotSandbox folders on this machine (not just the current session)" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "ControlService"; description = "Start, stop, or restart a Windows service; optionally set startup type. ALWAYS prompts."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string"; description = "Service name (not always display name)" }; action = @{ type = "string"; description = "start | stop | restart | set_startup" }; startup_type = @{ type = "string"; description = "For set_startup or with restart: Automatic | Manual | Disabled | AutomaticDelayedStart" } }; required = @("name","action") } } },
	@{ type = "function"; function = @{ name = "DownloadFile"; description = "Download a URL to a local path (size-capped). ALWAYS prompts."; parameters = @{ type = "object"; properties = @{ url = @{ type = "string" }; path = @{ type = "string"; description = "Destination file path" }; overwrite = @{ type = "boolean"; description = "Overwrite existing file (default false)" }; max_mb = @{ type = "integer"; description = "Max size in MB (default 100, max 512)" }; timeout_sec = @{ type = "integer"; description = "Timeout seconds (default 120)" } }; required = @("url","path") } } },
	@{ type = "function"; function = @{ name = "ExpandArchive"; description = "Extract a .zip archive to a folder. ALWAYS prompts."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Archive path (.zip)" }; destination = @{ type = "string"; description = "Output folder" }; force = @{ type = "boolean"; description = "Overwrite existing files (default false)" } }; required = @("path","destination") } } },
	@{ type = "function"; function = @{ name = "CompressArchive"; description = "Create a .zip from a file or folder. ALWAYS prompts."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Source file or folder" }; destination = @{ type = "string"; description = "Output .zip path" }; force = @{ type = "boolean"; description = "Overwrite zip if present (default false)" } }; required = @("path","destination") } } },
	@{ type = "function"; function = @{ name = "MakeIso"; description = "Build a .iso from a folder (IMAPI2 / New-IsoFile style). ALWAYS prompts. Default: folder CONTENTS at ISO root (like Get-ChildItem source | New-IsoFile) — set include_folder=true to wrap as one top-level folder. boot_file= path to efisys.bin (or etfsboot.com) for bootable Windows/WinPE media. force=true overwrites (dismounts if mounted first). title= volume label. Prefer over ad-hoc New-IsoFile scripts."; parameters = @{ type = "object"; properties = @{ source = @{ type = "string"; description = "Source folder (or file) to pack" }; path = @{ type = "string"; description = "Alias for source" }; destination = @{ type = "string"; description = "Output .iso path" }; iso_path = @{ type = "string"; description = "Alias for destination" }; boot_file = @{ type = "string"; description = "Optional boot image e.g. source\\efi\\microsoft\\boot\\efisys.bin" }; title = @{ type = "string"; description = "ISO volume title / label" }; force = @{ type = "boolean"; description = "Overwrite existing .iso (default false)" }; include_folder = @{ type = "boolean"; description = "true = include the source folder itself at ISO root; false (default) = add children only" }; media = @{ type = "string"; description = "IMAPI media type (default DVDPLUSRW_DUALLAYER)" } }; required = @("source","destination") } } },
	@{ type = "function"; function = @{ name = "MountIso"; description = "Mount a .iso as a virtual drive (Mount-DiskImage). ALWAYS prompts. Returns drive letter. Prefer over shell Mount-DiskImage."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Path to .iso file" }; iso_path = @{ type = "string"; description = "Alias for path" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "UnmountIso"; description = "Dismount a mounted .iso (Dismount-DiskImage). ALWAYS prompts. Pass path= to the .iso and/or letter= drive (e.g. E). Prefer over shell Dismount-DiskImage."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Path to the .iso that is mounted" }; iso_path = @{ type = "string"; description = "Alias for path" }; letter = @{ type = "string"; description = "Drive letter e.g. E or E:" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "MakeCab"; description = "Build a .cab with makecab.exe (LZX by default) and live progress in the UI. ALWAYS prompts. source= folder (pack files inside) and/or files=[paths]. force=true overwrites. Prefer over raw makecab directive scripts."; parameters = @{ type = "object"; properties = @{ source = @{ type = "string"; description = "Folder whose files are packed (non-recursive by default)" }; path = @{ type = "string"; description = "Alias for source folder" }; files = @{ type = "array"; items = @{ type = "string" }; description = "Explicit file paths to pack" }; destination = @{ type = "string"; description = "Output .cab path" }; cab_path = @{ type = "string"; description = "Alias for destination" }; force = @{ type = "boolean"; description = "Overwrite existing .cab (default false)" }; recursive = @{ type = "boolean"; description = "When source is a folder, include subfolders (default false)" }; compression = @{ type = "string"; description = "LZX (default) | MSZIP | none" }; compression_level = @{ type = "integer"; description = "LZX level 1-7 (default 7)" }; compression_memory = @{ type = "integer"; description = "LZX memory 15-21 (default 21)" } }; required = @("destination") } } },
	@{ type = "function"; function = @{ name = "ExpandCab"; description = "Extract a .cab with expand.exe. ALWAYS prompts. path= .cab, destination= output folder. force=true allows non-empty dest."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Source .cab path" }; cab_path = @{ type = "string"; description = "Alias for path" }; destination = @{ type = "string"; description = "Output folder" }; force = @{ type = "boolean"; description = "Allow extract into existing non-empty folder (default false)" } }; required = @("path","destination") } } },
	@{ type = "function"; function = @{ name = "BulkRename"; description = "REQUIRED for bulk/batch/mass rename of many files. Prefer over Rename-Item/ren loops in RunCommand — use RunCommand only if BulkRename errors/fails. path= directory. glob= filter (default *). Mode A: find= + replace= (substring; use_regex=true for .NET regex with `$1). Mode B: template= e.g. photo_{n:03}{ext} tokens {name}{stem}{ext}{n}{n:00}{parent}. dry_run=true DEFAULT (plan only). dry_run=false applies and ALWAYS prompts. recursive=false default. max=200. Prefer dry_run first then apply."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Folder containing files to rename" }; directory = @{ type = "string"; description = "Alias for path" }; glob = @{ type = "string"; description = "Name filter e.g. *.jpg (default *)" }; recursive = @{ type = "boolean"; description = "Include subfolders (default false)" }; find = @{ type = "string"; description = "Text or regex to match in the file name" }; replace = @{ type = "string"; description = "Replacement (use `$1 groups when use_regex=true)" }; use_regex = @{ type = "boolean"; description = "Treat find as .NET regex (default false)" }; template = @{ type = "string"; description = "New-name template: {name} {stem} {ext} {n} {n:00} {parent}" }; start_index = @{ type = "integer"; description = "Counter start for {n} (default 1)" }; dry_run = @{ type = "boolean"; description = "true=preview only (default true); false=apply with approval" }; max = @{ type = "integer"; description = "Max files to process (default 200, hard 1000)" }; force = @{ type = "boolean"; description = "Allow overwrite if target name exists (default false)" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "FindDuplicates"; description = "REQUIRED for finding duplicate files by content. Prefer over Get-FileHash|Group-Object shells in RunCommand — use RunCommand only if FindDuplicates errors/fails. Size buckets then SHA256. path= root. recursive=true default. min_bytes skips tiny files (default 1). max_scan caps walk (default 10000). max_groups caps result groups (default 40). No approval."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Root folder to scan" }; directory = @{ type = "string"; description = "Alias for path" }; recursive = @{ type = "boolean"; description = "Recurse subfolders (default true)" }; glob = @{ type = "string"; description = "Optional name filter e.g. *.pdf" }; min_bytes = @{ type = "integer"; description = "Ignore files smaller than this (default 1)" }; max_scan = @{ type = "integer"; description = "Max files to enumerate (default 10000)" }; max_groups = @{ type = "integer"; description = "Max duplicate groups returned (default 40)" }; max_per_group = @{ type = "integer"; description = "Max paths listed per group (default 12)" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "FindPSModule"; description = "Search PowerShell Gallery modules (read-only). Isolated process with timeout (default 60s); Esc/Stop aborts."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string"; description = "Module name or wildcard" }; max_results = @{ type = "integer"; description = "Max results (default 15)" }; timeout_sec = @{ type = "integer"; description = "Timeout seconds (default 60)" } }; required = @("name") } } },
	@{ type = "function"; function = @{ name = "GetInstalledPSModule"; description = "List installed PowerShell modules (optional name filter)."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string"; description = "Optional module name filter" } } } } },
	@{ type = "function"; function = @{ name = "InstallPSModule"; description = "Install a PowerShell module (default CurrentUser scope). ALWAYS prompts. Isolated process with timeout (default 180s); Esc/Stop aborts — will not freeze MiniBot."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string" }; version = @{ type = "string"; description = "Optional exact version" }; scope = @{ type = "string"; description = "CurrentUser (default) or AllUsers" }; allow_prerelease = @{ type = "boolean" }; timeout_sec = @{ type = "integer"; description = "Timeout seconds (default 180)" } }; required = @("name") } } },
	@{ type = "function"; function = @{ name = "UpdatePSModule"; description = "Update an installed PowerShell module. ALWAYS prompts. Isolated process with timeout (default 180s); Esc/Stop aborts — Gallery hangs will not freeze MiniBot."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string" }; scope = @{ type = "string"; description = "CurrentUser or AllUsers (optional)" }; timeout_sec = @{ type = "integer"; description = "Timeout seconds (default 180)" } }; required = @("name") } } },
	@{ type = "function"; function = @{ name = "SpeakText"; description = "Speak text aloud via Windows built-in speech (System.Speech SAPI). Prefer short plain sentences. No approval."; parameters = @{ type = "object"; properties = @{ text = @{ type = "string"; description = "Text to speak" }; rate = @{ type = "integer"; description = "Speech rate -10..10 (default 1)" }; wait = @{ type = "boolean"; description = "true = block until finished (default false async)" } }; required = @("text") } } },
	@{ type = "function"; function = @{ name = "AudioVolume"; description = "Get or set default playback volume/mute (Windows Core Audio). action=get|set|mute|unmute. level=0-100 for set. set/mute ALWAYS prompt."; parameters = @{ type = "object"; properties = @{ action = @{ type = "string"; description = "get (default) | set | mute | unmute" }; level = @{ type = "integer"; description = "0-100 percent when action=set" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "DisplayBrightness"; description = "Get or set internal display brightness when supported (usually laptops via WMI). action=get|set; level=0-100. Desktops often unsupported - tool reports that cleanly. set ALWAYS prompts."; parameters = @{ type = "object"; properties = @{ action = @{ type = "string"; description = "get (default) | set" }; level = @{ type = "integer"; description = "0-100 percent when action=set" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "SetWindowsOption"; description = "Apply a named Windows setup/tune option (explorer, UAC, power, boot F8, network sharing, timezone, bitlocker-off, etc). option= catalog key; value= on|off|show|hide|... ALWAYS prompts. Call ListWindowsOptions for keys."; parameters = @{ type = "object"; properties = @{ option = @{ type = "string"; description = "e.g. explorer.hidden_files, power.max_performance, boot.f8_legacy" }; value = @{ type = "string"; description = "Target value (on/off/show/hide/timezone id/etc)" }; drive = @{ type = "string"; description = "Drive letter for bitlocker/restore options (default C:)" } }; required = @("option","value") } } },
	@{ type = "function"; function = @{ name = "ListWindowsOptions"; description = "List SetWindowsOption catalog keys, allowed values, and short descriptions (read-only)."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "GroupPolicy"; description = "Local Group Policy editor via Policies registry (Administrative Template-style). NOT domain RSAT GPO. actions: status|list_catalog|get|set|remove|list_key|search|gpupdate|export_security. Prefer key= catalog shortcut; or path= + name=. set/remove/gpupdate ALWAYS prompt. Writes only under SOFTWARE\\Policies and CurrentVersion\\Policies. Optional gpupdate=true after set/remove."; parameters = @{ type = "object"; properties = @{ action = @{ type = "string"; description = "status|list_catalog|get|set|remove|list_key|search|gpupdate|export_security" }; key = @{ type = "string"; description = "Catalog key e.g. windows.update.no_auto_update (preferred for known settings)" }; path = @{ type = "string"; description = "Registry path e.g. HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\WindowsUpdate\\AU" }; name = @{ type = "string"; description = "Value name under path" }; value = @{ type = "string"; description = "Value for set (DWord/string)" }; type = @{ type = "string"; description = "DWord|String|ExpandString|MultiString|QWord (default DWord)" }; pattern = @{ type = "string"; description = "Filter for list_catalog/search" }; max = @{ type = "integer"; description = "Max rows (default 80)" }; gpupdate = @{ type = "boolean"; description = "After set/remove, run gpupdate /force (default false)" } }; required = @("action") } } },
	@{ type = "function"; function = @{ name = "SystemRestore"; description = "System Restore: action=status|enable|disable|create|list. enable/create/disable ALWAYS prompt. create optional description=."; parameters = @{ type = "object"; properties = @{ action = @{ type = "string"; description = "status|enable|disable|create|list" }; description = @{ type = "string"; description = "Restore point description when action=create" }; drive = @{ type = "string"; description = "Drive letter (default C:)" } }; required = @("action") } } },
	@{ type = "function"; function = @{ name = "UninstallSoftware"; description = "Uninstall an installed program by display name match (Uninstall registry). Prefer exact-ish name from GetInstalledSoftware first. ALWAYS prompts. No silent force beyond QuietUninstall/msiexec when available."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string"; description = "Display name substring to match" }; product_code = @{ type = "string"; description = "Optional MSI product code {GUID}" } }; required = @("name") } } },
	@{ type = "function"; function = @{ name = "AddLocalUser"; description = "Create a local Windows user. ALWAYS prompts. Optional full_name, description, admin=true (Administrators group). Password is operator-visible (pass what they said; show it back in the result). If the account already exists returns ok=false exists=true. To delete use RemoveLocalUser."; parameters = @{ type = "object"; properties = @{ username = @{ type = "string" }; password = @{ type = "string" }; full_name = @{ type = "string" }; description = @{ type = "string" }; admin = @{ type = "boolean"; description = "Add to local Administrators (default false)" } }; required = @("username","password") } } },
	@{ type = "function"; function = @{ name = "JoinDomain"; description = "Join this PC to an Active Directory domain. ALWAYS prompts. Requires domain + domain join credentials. Optional ou= distinguished name, new_name= rename before join, reboot=true to restart after success."; parameters = @{ type = "object"; properties = @{ domain = @{ type = "string"; description = "Domain FQDN e.g. corp.example.com" }; username = @{ type = "string"; description = "Domain account authorized to join (DOMAIN\\user or user@domain)" }; password = @{ type = "string" }; ou = @{ type = "string"; description = "Optional target OU DN" }; new_name = @{ type = "string"; description = "Optional new computer name before join" }; reboot = @{ type = "boolean"; description = "Restart after successful join (default false)" } }; required = @("domain","username","password") } } },
	@{ type = "function"; function = @{ name = "LeaveDomain"; description = "Leave the Active Directory domain (join workgroup). ALWAYS prompts. REQUIRED: local_username + local_password of a local admin that can sign in after disjoin. No UI password popup - if missing or auth fails, returns NEED_INPUT so you ASK the operator in chat. If no local admin exists, call AddLocalUser admin=true with a password the operator chooses, then LeaveDomain with those creds. workgroup= default WORKGROUP; reboot=true optional. Show the local admin password back to the operator when they provide it."; parameters = @{ type = "object"; properties = @{ workgroup = @{ type = "string"; description = "Target workgroup name (default WORKGROUP)" }; reboot = @{ type = "boolean"; description = "Restart after successful leave (default false)" }; local_username = @{ type = "string"; description = "REQUIRED local admin username" }; local_password = @{ type = "string"; description = "REQUIRED local admin password (operator-visible; no popup)" } }; required = @("local_username","local_password") } } },
			@{ type = "function"; function = @{ name = "MapNetworkDrive"; description = "Map a network share to a drive letter. ALWAYS prompts. path=\\\\server\\share required. letter= optional - if omitted or busy, auto-picks free letter D-Z (skips CD/DVD reserved letters even when empty). Prefer username=share (bare, like working net use /user:share) or domain=HOST username=share. If username is set, pass password= (empty string allowed for blank-password accounts; no popup). Matches: net use M: \\\\IP\\temp /user:share pass /persistent:yes. force=true remaps requested letter."; parameters = @{ type = "object"; properties = @{ letter = @{ type = "string"; description = "Preferred letter e.g. M - omit to auto-pick free non-CD letter" }; path = @{ type = "string"; description = "UNC \\\\server\\share" }; username = @{ type = "string"; description = "Bare share often works; or HOST\\\\user in JSON" }; domain = @{ type = "string"; description = "Optional host if username is bare" }; password = @{ type = "string"; description = "Required when username set; ask operator if missing" }; persistent = @{ type = "boolean"; description = "default true" }; force = @{ type = "boolean"; description = "Delete existing mapping on letter first" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "RemoveMappedDrive"; description = "Disconnect a mapped network drive letter on THIS PC. ALWAYS approval. REQUIRED: letter= (e.g. Z). Call GetMappedDrives first if unknown. Does not delete remote share data. Prefer over net use /delete in RunCommand."; parameters = @{ type = "object"; properties = @{ letter = @{ type = "string"; description = "Drive letter e.g. Z or Z:" }; path = @{ type = "string"; description = "Optional expected UNC (for display/verify)" }; force = @{ type = "boolean"; description = "Force remove (default true)" } }; required = @("letter") } } },
@{ type = "function"; function = @{ name = "AddNetworkPrinter"; description = "Connect a network/shared printer (\\\\server\\printer). ALWAYS prompts. Optional name= friendly name, set_default=true."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string"; description = "Printer share UNC \\\\server\\printer" }; name = @{ type = "string"; description = "Optional local display name" }; set_default = @{ type = "boolean"; description = "Set as default printer (default false)" } }; required = @("path") } } },
	@{ type = "function"; function = @{ name = "RemoveNetworkPrinter"; description = "Remove a printer from THIS PC. ALWAYS approval. REQUIRED: name= exact printer name from GetPrinters (or path= UNC). Prefer over printui in RunCommand."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string"; description = "Printer name from GetPrinters" }; path = @{ type = "string"; description = "Alias - UNC or name" } }; required = @("name") } } },
	@{ type = "function"; function = @{ name = "RemoveLocalUser"; description = "Delete a local Windows user account. ALWAYS approval. REQUIRED: username=. Refuses built-in accounts (Administrator, Guest, ...) and the currently logged-on user. Does not delete the profile folder under C:\\Users. Prefer over net user /delete in RunCommand."; parameters = @{ type = "object"; properties = @{ username = @{ type = "string" }; name = @{ type = "string"; description = "Alias for username" } }; required = @("username") } } },
	@{ type = "function"; function = @{ name = "Reboot"; description = "Schedule reboot or shutdown, or abort a pending timer. ALWAYS approval. action=reboot (default) | shutdown | abort. delay_sec=60 default (0=immediate). force=true closes apps. reason= optional message. Abort pending with action=abort. Prefer over shutdown.exe in RunCommand."; parameters = @{ type = "object"; properties = @{ action = @{ type = "string"; description = "reboot | shutdown | abort" }; delay_sec = @{ type = "integer"; description = "Seconds before reboot/shutdown (default 60, max 86400)" }; reason = @{ type = "string"; description = "Optional comment shown in shutdown UI" }; force = @{ type = "boolean"; description = "Force-close apps (default true)" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "CreateShare"; description = "Share a local folder over SMB. ALWAYS approval once. REQUIRED: path, name, access_username, access_password (or share_password), everyone_full (true|false - ALWAYS ask: Everyone access or only a specific user?). If access_username exists: verifies password via local logon (does not overwrite). If missing: creates user. force_password_update=true (alias reset_password=true) only when operator wants to RESET password on existing user. Grants share+NTFS rights to that user; optionally Everyone. Optional access_right/permission = Full|Change|Read (DEFAULT Full if omitted - do not force Full when Read/Change requested). No UI popups. Show password back. SMBv1 check if off. Copies UNC."; parameters = @{ type = "object"; properties = @{ path = @{ type = "string" }; name = @{ type = "string" }; access_username = @{ type = "string"; description = "Local account for grant (created if missing). Not Everyone." }; access_password = @{ type = "string"; description = "Password for access_username" }; share_password = @{ type = "string"; description = "Alias for access_password" }; everyone_full = @{ type = "boolean"; description = "REQUIRED. true=also grant Everyone same access_right; false=only access_username" }; access_right = @{ type = "string"; description = "Full (default) | Change | Read - share+NTFS level" }; permission = @{ type = "string"; description = "Alias for access_right" }; force_password_update = @{ type = "boolean"; description = "true = reset existing user password to access_password (destructive; only when operator asks)" }; reset_password = @{ type = "boolean"; description = "Alias for force_password_update" }; description = @{ type = "string" }; ensure_network = @{ type = "boolean" }; ensure_discovery = @{ type = "boolean" }; ensure_folder = @{ type = "boolean" }; force = @{ type = "boolean" } }; required = @("path","name","access_username","access_password","everyone_full") } } },
	@{ type = "function"; function = @{ name = "RemoveShare"; description = "Unpublish a local SMB share on THIS PC. ALWAYS approval. REQUIRED: name (share name from GetLocalShares). Removes the share only - does not delete the folder or local users. force=true (default) closes open files then removes. Refuses special/admin shares (C$, ADMIN$, IPC$, PRINT$). Prefer over RunCommand net share /delete."; parameters = @{ type = "object"; properties = @{ name = @{ type = "string"; description = "Share name to remove (e.g. temp). UNC \\PC\\name also accepted." }; share = @{ type = "string"; description = "Alias for name" }; force = @{ type = "boolean"; description = "Force close sessions and remove (default true)" } }; required = @("name") } } },
	@{ type = "function"; function = @{ name = "NewMachineSetup"; description = "Full new-machine setup. profile=residential|business (settings flavor only). ALWAYS prompts once listing SETTINGS + SOFTWARE. Settings: restore, F8, max power, explorer UX, network discovery/sharing, time sync, Device Encryption off. If portable, re-enable encryption after setup is recommended. Software (full catalog every time): 7zip, Chrome, Adobe Reader, ADWCleaner (runs a scan), VLC. skip_software=true for settings only. dry_run=true previews."; parameters = @{ type = "object"; properties = @{ profile = @{ type = "string"; description = "residential | business (settings notes only; software catalog is always the full default set)" }; dry_run = @{ type = "boolean" }; timezone = @{ type = "string" }; skip_restore_point = @{ type = "boolean" }; skip_software = @{ type = "boolean" } }; required = @("profile") } } },
	@{ type = "function"; function = @{ name = "ListInstallers"; description = "List silent installer catalog (id, name, notes). Read-only. Catalog: 7zip, chrome, adobe_reader, adwcleaner, vlc."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "InstallPackage"; description = "Silent download+install from the installers catalog. package=id or packages=[ids]. Follows redirects (dynamic URLs). ALWAYS prompts. Temp downloads cleaned after each package. Ids: 7zip, chrome, adobe_reader, adwcleaner (will run a scan), vlc."; parameters = @{ type = "object"; properties = @{ package = @{ type = "string"; description = "Single package id" }; packages = @{ type = "array"; items = @{ type = "string" }; description = "Multiple package ids" } }; required = @() } } },
	@{ type = "function"; function = @{ name = "EnableToolGroup"; description = "Silently enable group(s): group=network,shares or groups=[diag,repair]. See MAP. Then call tools same turn; never narrate."; parameters = @{ type = "object"; properties = @{ group = @{ type = "string" }; groups = @{ type = "array"; items = @{ type = "string" } } }; required = @() } } },
	@{ type = "function"; function = @{ name = "ListToolGroups"; description = "List groups/tools. Prefer EnableToolGroup + MAP."; parameters = @{ type = "object"; properties = @{} } } },
	@{ type = "function"; function = @{ name = "TaskBoard"; description = "Ordered plan cursor (SESSION STATE). ONE TaskBoard call per turn (no parallel status/update/clear). Execute ONLY now. set: items max 12; replace=true overwrites (returns prior_snapshot). update: id=now|concrete status=done advances; pass epoch= from last response so id=now+done is not loop-guarded; blocked needs note=. No rewind of earlier done (immutable_completed). Batch: contiguous dones only. Returns flat items[], updated[], goal, now, epoch, progress. complete=true includes final_items/final_goal/final_board; live counters 0/0 until clear."; parameters = @{ type = "object"; properties = @{ action = @{ type = "string"; description = "set | update | status | clear" }; goal = @{ type = "string"; description = "Overall goal (action=set)" }; items = @{ type = "array"; description = "Required non-empty ordered steps for set" }; replace = @{ type = "boolean"; description = "set: overwrite open board" }; id = @{ type = "string"; description = "prefer now or concrete id from items[]/now" }; ids = @{ type = "array"; description = "batch ids; contiguous from now if done" }; updates = @{ type = "array"; description = "batch [{id,status,title,note}] transactional" }; status = @{ type = "string"; description = "pending|in_progress|done|blocked" }; title = @{ type = "string"; description = "rename now only" }; note = @{ type = "string"; description = "required for blocked" }; epoch = @{ type = "integer"; description = "pass last response epoch on update so id=now status=done is not loop-guarded" }; verbose = @{ type = "boolean"; description = "include board text" } }; required = @("action") } } }
)

# Progressive tool catalog (core lean; optional groups on demand)
$script:MBToolCatalog = [ordered]@{
	core = @(
