function Initialize-MBToolGroups {
	if (-not $script:MB.ActiveToolGroups) {
		$script:MB.ActiveToolGroups = New-Object System.Collections.ArrayList
	}
	$script:MB.ActiveToolGroups.Clear()
	[void]$script:MB.ActiveToolGroups.Add('core')
	$profile = [string]$script:MB.ToolProfile
	if ([string]::IsNullOrWhiteSpace($profile)) { $profile = [string]$ToolProfile }
	if ($profile -match '^(?i)full|all$') {
		foreach ($g in @(Get-MBToolGroupOrder)) {
			if (-not ($script:MB.ActiveToolGroups -contains $g)) {
				[void]$script:MB.ActiveToolGroups.Add($g)
			}
		}
	}
}

function Sync-MBContextUiAfterWarm {
	param(
		[array]$Messages = $null,
		[int]$PromptTokens = 0,
		[string]$Reason = ''
	)
	try {
		if ($null -eq $Messages) {
			try { $Messages = @($script:Messages) } catch { $Messages = @() }
		}
		$pt = [int]$PromptTokens
		if ($pt -gt 0) {
			try { $script:MB.LastServerPromptTokens = $pt } catch {}
			try { $script:MB.TokenCountSource = 'usage' } catch {}
			$msgChars = 0
			try {
				foreach ($m in @($Messages)) {
					if ($null -eq $m) { continue }
					$msgChars += [int](Get-MBMessageCharCount -Message $m)
				}
			} catch {}
			$toolsTok = 0
			try { $toolsTok = [int]$script:MB.ToolsOverheadTok } catch { $toolsTok = 0 }
			$wd = ''
			try { $wd = [string]$script:MB.WorkingDir } catch { $wd = '' }
			$cacheKey = '{0}|{1}|{2}|{3}' -f @($Messages).Count, $msgChars, $toolsTok, $wd
			try {
				$script:MB.TokCacheKey = $cacheKey
				$script:MB.TokCacheTokens = $pt
				$script:MB.TokCacheAt = Get-Date
			} catch {}
			try {
				$usable = [int](Get-MBEffectivePromptBudget)
				$pct = if ($usable -gt 0) { [math]::Min(3.0, $pt / [double]$usable) } else { 1.0 }
				$level = 'ok'
				if ($pct -ge [double]$script:MB.ContextHardPct) { $level = 'hard' }
				elseif ($pct -ge [double]$script:MB.ContextSoftPct) { $level = 'soft' }
				$script:MB.LastCtxTokens = $pt
				$script:MB.LastCtxPct = $pct
				$script:MB.LastCtxLevel = $level
			} catch {}
			try {
				Write-MBDebugLog -Step 'CACHE_WARM_CTX' -Detail ("pt={0} reason={1}" -f $pt, $Reason)
			} catch {}
		} else {
			try { [void](Get-MBContextEstimate -Messages $Messages -ForceRefresh) } catch {}
		}
		try { Set-MBContextBarReady } catch {}
		try { Update-MBWpfLiveChrome -Force } catch {}
		try { Refresh-MBWpfStickyFromSession } catch {}
	} catch {}
}

function Invoke-MBPromptCacheWarm {
	param(
		[array]$Messages = $null,
		[int]$TimeoutSeconds = 180,
		[string]$Reason = ''
	)
	try {
		if ($null -eq $Messages) {
			try { $Messages = @($script:Messages) } catch { $Messages = @() }
		}
		if (-not $Messages -or @($Messages).Count -eq 0) { return $false }
		$model = ''
		try { $model = [string](Get-MBActiveModel) } catch { $model = '' }
		if ([string]::IsNullOrWhiteSpace($model) -or $model -eq 'Select Model') { return $false }
		$tools = @(Get-MBActiveTools)
		$body = New-MBChatRequestBody -Messages $Messages -Tools $tools -ModelName $model `
			-Temp 0 -MaxTok 1 -Stream $false -CachePrompt $true -ToolChoice 'none'
		if ([string]::IsNullOrWhiteSpace($body)) { return $false }
		$apiBase = Get-MBApiBaseUrl
		$url = "$apiBase/chat/completions"
		$headers = @{ 'Content-Type' = 'application/json' }
		try {
			$auth = Get-MBAuthHeaderValue -BaseUrl $apiBase
			if ($auth) { $headers['Authorization'] = $auth }
		} catch {}
		$sw = [System.Diagnostics.Stopwatch]::StartNew()
		$pr = Invoke-MBHttpPostQuick -Url $url -Headers $headers -Body $body -TimeoutSeconds $TimeoutSeconds
		$sw.Stop()
		if ($pr.Ok) {
			$warmPt = 0
			try {
				$raw = [string]$pr.Content
				if (-not [string]::IsNullOrWhiteSpace($raw)) {
					$jo = $raw | ConvertFrom-Json -ErrorAction Stop
					$u = $null
					try { $u = $jo.usage } catch { $u = $null }
					if ($null -ne $u) {
						$pt0 = $null
						try { $pt0 = $u.prompt_tokens } catch { $pt0 = $null }
						if ($null -eq $pt0) { try { $pt0 = $u.PromptTokens } catch { $pt0 = $null } }
						if ($null -ne $pt0) { $warmPt = [int]$pt0 }
					}
				}
			} catch { $warmPt = 0 }
			try {
				Write-MBDebugLog -Step 'CACHE_WARM_OK' -Detail ("ms={0} tools={1} msgs={2} pt={3} reason={4}" -f $sw.ElapsedMilliseconds, @($tools).Count, @($Messages).Count, $warmPt, $Reason)
			} catch {}
			try { Sync-MBContextUiAfterWarm -Messages $Messages -PromptTokens $warmPt -Reason $Reason } catch {}
			return $true
		}
		try {
			Write-MBDebugLog -Step 'CACHE_WARM_FAIL' -Detail ("status={0} err={1} reason={2}" -f $pr.StatusCode, $pr.Error, $Reason)
		} catch {}
		return $false
	} catch {
		try { Write-MBDebugLog -Step 'CACHE_WARM_ERR' -Detail $_.Exception.Message } catch {}
		return $false
	}
}

function Sync-MBPromptAfterToolGroups {
	param([switch]$Force)
	$frozen = $false
	try { $frozen = [bool]$script:MB.WireStateFrozen } catch { $frozen = $false }
	if ($frozen -and -not $Force) {
		try { $script:MB.PendingToolGroupPromptSync = $true } catch {}
		$expanded = $false
		try { $expanded = [bool](Expand-MBFrozenToolsFromActive) } catch { $expanded = $false }
		try {
			if ([int]$script:MB.FrozenToolsOverheadTok -gt 0) {
				$script:MB.ToolsOverheadTok = [int]$script:MB.FrozenToolsOverheadTok
				$script:MB.ToolsOverheadChars = [int]$script:MB.FrozenToolsOverheadChars
			}
		} catch {}
		if ($expanded) {
			try { $script:MB.PendingCacheWarmAfterEnable = $true } catch {}
		}
		try { Update-MBWpfToolGroupBar -Force } catch {}
		return
	}
	try { Initialize-MBToolsOverhead } catch {}
	try {
		if ($script:Messages) {
			$script:Messages = @(Sync-MBSystemMessages -Messages $script:Messages)
		}
	} catch {}
	try { $script:SystemPrompt = Get-MBSystemPrompt } catch {}
	try { $script:MB.PendingToolGroupPromptSync = $false } catch {}
	try {
		if ($script:Messages -and @($script:Messages).Count -gt 2) {
			try { $script:MB.PendingCacheWarmAfterEnable = $true } catch {}
		}
	} catch {}
	try { Update-MBWpfToolGroupBar -Force } catch {}
}

function Get-MBToolGroupOrder {
	@('core','vision','sound','forensics','system','network','diag','repair','setup','identity','shares','installers','sandbox','files','packages','registry','clipboard','docs','web')
}

function Add-MBUsedToolName {
	param([string]$Name)
	if ([string]::IsNullOrWhiteSpace($Name)) { return }
	try {
		if ($null -eq $script:MB.UsedToolNames -or -not ($script:MB.UsedToolNames -is [hashtable])) {
			$script:MB.UsedToolNames = @{}
		}
		$key = [string]$Name.Trim()
		if ($script:MB.UsedToolNames.ContainsKey($key)) { return }
		$script:MB.UsedToolNames[$key] = $true
		try { Update-MBWpfToolGroupBar -Force } catch {}
	} catch {}
}

function Get-MBToolUserTipBody {
	# Operator-facing body only (no tool name prefix). Prefer MBToolUserTips map.
	param([string]$Name, [string]$Description = '')
	$n = ([string]$Name).Trim()
	if ([string]::IsNullOrWhiteSpace($n)) { return '' }

	if ($script:MBToolUserTips) {
		if ($script:MBToolUserTips.Contains($n)) {
			return [string]$script:MBToolUserTips[$n]
		}
		foreach ($k in @($script:MBToolUserTips.Keys)) {
			if ([string]::Equals([string]$k, $n, [StringComparison]::OrdinalIgnoreCase)) {
				return [string]$script:MBToolUserTips[$k]
			}
		}
	}

	# Fallback: first sentence of schema, stripped of agent-routing noise (should rarely hit).
	$d = ([string]$Description).Trim()
	if ([string]::IsNullOrWhiteSpace($d)) { return '' }
	$d = $d -replace '(?i)\bREQUIRED\b[^.]*\.\s*', ''
	$d = $d -replace '(?i)\bALWAYS prompts?[^.]*\.\s*', ''
	$d = $d -replace '(?i)\bPrefer over[^.]*\.\s*', ''
	$d = $d -replace '(?i)\bDo not use[^.]*\.\s*', ''
	$d = $d -replace '(?i)\bNEVER[^.]*\.\s*', ''
	$d = $d -replace '(?i)\bmissing_tool[^.]*\.\s*', ''
	$d = $d -replace '(?i)\bEnableToolGroup[^.]*\.\s*', ''
	$d = $d.Trim()
	if ($d -match '^(.+?[.!?])(\s|$)') { $d = $Matches[1].Trim() }
	if ($d.Length -gt 180) { $d = $d.Substring(0, 177).Trim() + '...' }
	return $d
}

function Get-MBToolUserTipText {
	param([string]$Name, [string]$Description = '')
	$n = ([string]$Name).Trim()
	if ([string]::IsNullOrWhiteSpace($n)) { return '' }
	$body = Get-MBToolUserTipBody -Name $n -Description $Description
	if ([string]::IsNullOrWhiteSpace($body)) { return $n }
	return ("{0}`n{1}" -f $n, $body)
}

function Get-MBToolUiTips {
	$groupTips = @{}
	$groupLabels = @{}
	try {
		foreach ($key in @($script:MBToolGroupMeta.Keys)) {
			$meta = $script:MBToolGroupMeta[$key]
			$lab = [string](Get-MBProp $meta 'Label')
			if ([string]::IsNullOrWhiteSpace($lab)) { $lab = [string]$key }
			$desc = [string](Get-MBProp $meta 'Description')
			if ([string]::IsNullOrWhiteSpace($desc)) { $desc = 'Tool group' }
			$groupLabels[[string]$key] = $lab
			$groupTips[[string]$key] = ("{0}`n{1}`n`nClick to list tools in this group." -f $lab, $desc)
		}
	} catch {}

	$toolTips = @{}
	try {
		$toolList = @()
		try { $toolList = @($Tools) } catch { $toolList = @() }
		if ($toolList.Count -eq 0) {
			try { $toolList = @($script:MBTools) } catch { $toolList = @() }
		}
		foreach ($entry in $toolList) {
			if ($null -eq $entry) { continue }
			$fn = Get-MBProp $entry 'function'
			if ($null -eq $fn) { continue }
			$nm = [string](Get-MBProp $fn 'name')
			if ([string]::IsNullOrWhiteSpace($nm)) { continue }
			$desc = [string](Get-MBProp $fn 'description')
			$toolTips[$nm] = Get-MBToolUserTipText -Name $nm -Description $desc
		}
	} catch {}

	# Seed map-only tools even if schema list is empty at call time
	if ($script:MBToolUserTips) {
		foreach ($k in @($script:MBToolUserTips.Keys)) {
			if (-not $toolTips.ContainsKey([string]$k)) {
				$toolTips[[string]$k] = Get-MBToolUserTipText -Name ([string]$k)
			}
		}
	}

	# Always-present meta tools
	if (-not $toolTips.ContainsKey('EnableToolGroup')) {
		$toolTips['EnableToolGroup'] = Get-MBToolUserTipText -Name 'EnableToolGroup'
	}
	if (-not $toolTips.ContainsKey('ListToolGroups')) {
		$toolTips['ListToolGroups'] = Get-MBToolUserTipText -Name 'ListToolGroups'
	}

	# Vision-gated tools: orange UI when Abilities lacks lowercase "vision"
	$hasVision = $false
	try { $hasVision = [bool](Test-MBModelHasVision) } catch { $hasVision = $false }
	if (-not $hasVision) {
		foreach ($vt in @(Get-MBVisionToolNames)) {
			$base = ''
			if ($toolTips.ContainsKey($vt)) { $base = [string]$toolTips[$vt] }
			if ([string]::IsNullOrWhiteSpace($base)) { $base = Get-MBToolUserTipText -Name $vt }
			if ([string]::IsNullOrWhiteSpace($base)) { $base = $vt }
			$toolTips[$vt] = ("{0}`n`nUnavailable: the connected model cannot view images or the screen." -f $base.TrimEnd())
		}
	}

	# GroupPolicy: orange when Windows edition has no Local GPO (Home/Core, no gpedit)
	$hasGpo = $true
	try { $hasGpo = [bool](Test-MBWindowsHasLocalGroupPolicy) } catch { $hasGpo = $true }
	if (-not $hasGpo) {
		$why = Get-MBGroupPolicyUnavailableReason
		foreach ($gt in @(Get-MBGroupPolicyToolNames)) {
			$base = ''
			if ($toolTips.ContainsKey($gt)) { $base = [string]$toolTips[$gt] }
			if ([string]::IsNullOrWhiteSpace($base)) { $base = Get-MBToolUserTipText -Name $gt }
			if ([string]::IsNullOrWhiteSpace($base)) { $base = $gt }
			$toolTips[$gt] = ("{0}`n`nUnavailable: {1}" -f $base.TrimEnd(), $why)
		}
	}

	# RemoteCommand: operator tip from map; append domain gate when off-domain
	$onDomain = $true
	try { $onDomain = [bool](Test-MBHostOnDomain) } catch { $onDomain = $true }
	$domainWhy = ''
	if (-not $onDomain) {
		try { $domainWhy = Get-MBRemoteCommandUnavailableReason } catch { $domainWhy = 'This PC or user is not on a domain.' }
	}
	foreach ($rt in @(Get-MBRemoteCommandToolNames)) {
		$base = Get-MBToolUserTipText -Name $rt
		if ([string]::IsNullOrWhiteSpace($base)) { $base = $rt }
		if (-not $onDomain -and $domainWhy) {
			$toolTips[$rt] = ("{0}`n`nUnavailable: {1}" -f $base.TrimEnd(), $domainWhy.TrimEnd())
		} else {
			$toolTips[$rt] = $base
		}
	}

	return @{
		groups = $groupTips
		labels = $groupLabels
		tools  = $toolTips
	}
}

function Update-MBWpfToolGroupBar {
	# Agent thread pushes tool-group snapshot; STA timer paints chips.
	param([switch]$Force)
	if (-not (Test-MBWpfActive)) { return }
	$W = $script:MB.Wpf
	if (-not $W) { return }

	$order = @(Get-MBToolGroupOrder)
	$activeList = New-Object System.Collections.ArrayList
	try {
		foreach ($g in @($script:MB.ActiveToolGroups)) {
			$gl = ([string]$g).Trim().ToLowerInvariant()
			if ($gl -and -not ($activeList -contains $gl)) { [void]$activeList.Add($gl) }
		}
	} catch {}
	if ($activeList.Count -eq 0) { [void]$activeList.Add('core') }
	if ($activeList -contains 'full' -or $activeList -contains 'all') {
		$activeList = New-Object System.Collections.ArrayList
		foreach ($g in $order) { [void]$activeList.Add($g) }
	}
	$usedList = New-Object System.Collections.ArrayList
	try {
		if ($script:MB.UsedToolNames -is [hashtable]) {
			foreach ($u in @($script:MB.UsedToolNames.Keys)) {
				if ($u) { [void]$usedList.Add([string]$u) }
			}
		}
	} catch {}
	$usedList = @($usedList | Sort-Object)
	$hasVision = $false
	try { $hasVision = [bool](Test-MBModelHasVision) } catch { $hasVision = $false }
	$hasGpo = $true
	try { $hasGpo = [bool](Test-MBWindowsHasLocalGroupPolicy) } catch { $hasGpo = $true }
	$onDomain = $false
	try { $onDomain = [bool](Test-MBHostOnDomain) } catch { $onDomain = $false }
	$fp = ((@($activeList) -join ',') + '|u:' + ($usedList -join ',') + '|v:' + $(if ($hasVision) { '1' } else { '0' }) + '|gpo:' + $(if ($hasGpo) { '1' } else { '0' }) + '|dom:' + $(if ($onDomain) { '1' } else { '0' }))
	if (-not $Force) {
		try {
			if ($W.ToolGroupsFp -eq $fp -and $W.ToolGroupsBuilt -and -not $W.ToolGroupsDirty) { return }
		} catch {}
	}

	$toolsByGroup = @{}
	foreach ($g in $order) {
		try {
			if ($script:MBToolCatalog -and $script:MBToolCatalog.Contains($g)) {
				$toolsByGroup[$g] = @($script:MBToolCatalog[$g] | ForEach-Object { [string]$_ })
			} else {
				$toolsByGroup[$g] = @()
			}
		} catch { $toolsByGroup[$g] = @() }
	}
	$visionBlocked = @{}
	if (-not $hasVision) {
		foreach ($vt in @(Get-MBVisionToolNames)) { $visionBlocked[$vt] = $true }
	}
	# Tools shown orange in setup menu when edition lacks Local Group Policy (Home/Core)
	$gpoBlocked = @{}
	$gpoBlockReason = ''
	if (-not $hasGpo) {
		$gpoBlockReason = Get-MBGroupPolicyUnavailableReason
		foreach ($gt in @(Get-MBGroupPolicyToolNames)) { $gpoBlocked[$gt] = $true }
	}
	$domainBlocked = @{}
	if (-not $onDomain) {
		foreach ($rt in @(Get-MBRemoteCommandToolNames)) { $domainBlocked[$rt] = $true }
	}

	# Stable catalog order (core…web) so chips wrap evenly; active state is lime, not reordering
	$displayOrder = New-Object System.Collections.ArrayList
	foreach ($g in $order) {
		$gs = [string]$g
		if ($gs -and -not ($displayOrder -contains $gs)) { [void]$displayOrder.Add($gs) }
	}
	foreach ($g in @($activeList)) {
		$gs = [string]$g
		if ($gs -and -not ($displayOrder -contains $gs) -and $script:MBToolCatalog -and $script:MBToolCatalog.Contains($gs)) {
			[void]$displayOrder.Add($gs)
		}
	}

	# Installers chip: tools, then divider, then catalog package names
	$installerPkgs = New-Object System.Collections.ArrayList
	try {
		$cat = Get-MBInstallerCatalog
		foreach ($k in @($cat.Keys)) {
			$p = $cat[$k]
			if (-not $p) { continue }
			$id = [string]$p.id
			if ([string]::IsNullOrWhiteSpace($id)) { $id = [string]$k }
			$nm = [string]$p.name
			if ([string]::IsNullOrWhiteSpace($nm)) { $nm = $id }
			$note = ''
			try { $note = [string]$p.notes } catch { $note = '' }
			if ([string]::IsNullOrWhiteSpace($note)) {
				try { $note = [string]$p.note } catch { $note = '' }
			}
			[void]$installerPkgs.Add([pscustomobject]@{ id = $id; name = $nm; note = $note })
		}
	} catch {}

	$tips = $null
	try { $tips = Get-MBToolUiTips } catch { $tips = $null }

	try {
		$W.ToolGroupsData = @{
			order              = @($displayOrder)
			active             = @($activeList)
			tools              = $toolsByGroup
			installerPackages  = @($installerPkgs)
			groupTips          = $(if ($tips) { $tips.groups } else { @{} })
			toolTips           = $(if ($tips) { $tips.tools } else { @{} })
			usedTools          = @($usedList)
			modelHasVision     = $hasVision
			visionBlocked      = $visionBlocked
			hasLocalGroupPolicy = $hasGpo
			gpoBlocked         = $gpoBlocked
			gpoBlockReason     = $gpoBlockReason
			domainBlocked      = $domainBlocked
			fp                 = $fp
		}
		$W.ToolGroupsDirty = $true
	} catch {}
}

function Get-MBToolGroupForName {
	param([string]$Name)
	if ([string]::IsNullOrWhiteSpace($Name)) { return $null }
	$target = $Name.Trim()
	foreach ($key in @($script:MBToolCatalog.Keys)) {
		foreach ($n in @($script:MBToolCatalog[$key])) {
			if ($n -eq $target) { return $key }
			if ($n -and $n.ToLowerInvariant() -eq $target.ToLowerInvariant()) { return $key }
		}
	}
	return $null
}

