function Resolve-MBToolName {
	param([string]$Name)
	if ([string]::IsNullOrWhiteSpace($Name)) { return $null }
	$raw = $Name.Trim()
	$all = @($Tools | ForEach-Object { $_.function.name } | Where-Object { $_ })
	foreach ($n in $all) {
		if ($n -eq $raw) { return $n }
	}
	$lower = $raw.ToLowerInvariant()
	foreach ($n in $all) {
		if ($n.ToLowerInvariant() -eq $lower) { return $n }
	}
	$nick = @{
		'read_file' = 'ReadFile'; 'write_file' = 'WriteFile'; 'edit_file' = 'EditFile'
		'run' = 'RunCommand'; 'run_command' = 'RunCommand'; 'shell' = 'RunCommand'
		'exec' = 'RunCommand'; 'bash' = 'RunCommand'; 'powershell' = 'RunCommand'
		'remote' = 'RemoteCommand'; 'remote_command' = 'RemoteCommand'; 'remote_shell' = 'RemoteCommand'
		'winrm' = 'RemoteCommand'; 'invoke_command' = 'RemoteCommand'
		'psremoting' = 'RemoteCommand'; 'remote_ps' = 'RemoteCommand'; 'remote_powershell' = 'RemoteCommand'
		'list_dir' = 'ListDirectory'; 'ls' = 'ListDirectory'; 'dir' = 'ListDirectory'
		'search' = 'SearchFiles'; 'grep' = 'SearchFiles'; 'find' = 'FindFiles'
		'hex' = 'HexView'; 'hexview' = 'HexView'; 'hex_view' = 'HexView'; 'hexdump' = 'HexView'
		'hexedit' = 'HexEdit'; 'hex_edit' = 'HexEdit'; 'hexpatch' = 'HexEdit'
		'hexsearch' = 'HexSearch'; 'hex_search' = 'HexSearch'; 'findhex' = 'HexSearch'; 'find_hex' = 'HexSearch'
		'strings' = 'StringsScan'; 'strings_scan' = 'StringsScan'; 'stringscan' = 'StringsScan'
		'screenshot' = 'ViewScreen'; 'screen' = 'ViewScreen'; 'capture' = 'ViewScreen'
		'image' = 'ReadImage'; 'pdf' = 'ReadPdf'; 'read_pdf' = 'ReadPdf'; 'read_image' = 'ReadImage'
		'http' = 'MakeHttpRequest'; 'fetch' = 'BrowsePage'; 'browse' = 'BrowsePage'
		'search_web' = 'SearchWeb'; 'web_search' = 'SearchWeb'; 'searchweb' = 'SearchWeb'; 'duckduckgo' = 'SearchWeb'
		'search_learn' = 'SearchMicrosoftLearn'; 'search_microsoft_learn' = 'SearchMicrosoftLearn'
		'microsoft_learn' = 'SearchMicrosoftLearn'; 'ms_learn' = 'SearchMicrosoftLearn'
		'read_learn' = 'ReadMicrosoftLearn'; 'read_microsoft_learn' = 'ReadMicrosoftLearn'
		'search_ss64' = 'SearchSs64'; 'ss64_search' = 'SearchSs64'
		'read_ss64' = 'ReadSs64'; 'ss64' = 'ReadSs64'
		'download' = 'DownloadFile'; 'wget' = 'DownloadFile'; 'curl' = 'MakeHttpRequest'
		'bulk_rename' = 'BulkRename'; 'bulkrename' = 'BulkRename'; 'rename_bulk' = 'BulkRename'
		'rename_files' = 'BulkRename'; 'mass_rename' = 'BulkRename'; 'batch_rename' = 'BulkRename'
		'find_duplicates' = 'FindDuplicates'; 'findduplicates' = 'FindDuplicates'; 'duplicates' = 'FindDuplicates'
		'dupes' = 'FindDuplicates'; 'find_dupes' = 'FindDuplicates'; 'duplicate_files' = 'FindDuplicates'
		'clipboard' = 'Clipboard'; 'clip' = 'Clipboard'
		'registry' = 'ReadRegistry'; 'reg' = 'ReadRegistry'
		'process' = 'GetProcessList'; 'processes' = 'GetProcessList'; 'ps' = 'GetProcessList'
		'stop_process' = 'StopProcess'; 'kill_process' = 'StopProcess'; 'kill' = 'StopProcess'; 'taskkill' = 'StopProcess'
		'service' = 'GetServiceStatus'; 'services' = 'GetServiceStatus'
		'netstat' = 'GetNetConnections'; 'ports' = 'GetNetConnections'
		'scan_network' = 'ScanNetwork'; 'lan_scan' = 'ScanNetwork'; 'ip_scan' = 'ScanNetwork'
		'arp_scan' = 'ScanNetwork'; 'network_scan' = 'ScanNetwork'
		'probe_shares' = 'FindShares'; 'find_shares' = 'FindShares'
		'smb_probe' = 'FindShares'; 'find_share' = 'FindShares'
		'port_probe' = 'PortProbe'; 'probe_ports' = 'PortProbe'; 'tcp_probe' = 'PortProbe'
		'portscan' = 'PortProbe'; 'port_scan' = 'PortProbe'
		'find_web' = 'FindWebHosts'; 'find_web_hosts' = 'FindWebHosts'; 'web_hosts' = 'FindWebHosts'
		'find_rdp' = 'FindRdp'; 'rdp_hosts' = 'FindRdp'; 'find_remote_desktop' = 'FindRdp'
		'list_shares' = 'GetLocalShares'; 'local_shares' = 'GetLocalShares'; 'get_local_shares' = 'GetLocalShares'
		'smb_shares' = 'GetLocalShares'; 'who_has_share_access' = 'GetLocalShares'
		'mapped_drives' = 'GetMappedDrives'; 'map_list' = 'GetMappedDrives'; 'net_use' = 'GetMappedDrives'
		'list_maps' = 'GetMappedDrives'; 'get_mapped_drives' = 'GetMappedDrives'
		'enable_tools' = 'EnableToolGroup'; 'enable_group' = 'EnableToolGroup'
		'tools' = 'ListToolGroups'; 'list_tools' = 'ListToolGroups'
		'taskboard' = 'TaskBoard'; 'task_board' = 'TaskBoard'; 'todo' = 'TaskBoard'
		'todos' = 'TaskBoard'; 'todo_write' = 'TaskBoard'; 'task_plan' = 'TaskBoard'
		'plan_tasks' = 'TaskBoard'; 'checklist' = 'TaskBoard'
		'volume' = 'AudioVolume'; 'mute' = 'AudioVolume'; 'unmute' = 'AudioVolume'
		'set_volume' = 'AudioVolume'; 'setvolume' = 'AudioVolume'; 'audio_volume' = 'AudioVolume'
		'speaker' = 'AudioVolume'; 'speakers' = 'AudioVolume'; 'sound_level' = 'AudioVolume'
		'brightness' = 'DisplayBrightness'; 'set_brightness' = 'DisplayBrightness'; 'display_brightness' = 'DisplayBrightness'
		'dim' = 'DisplayBrightness'; 'screen_brightness' = 'DisplayBrightness'
		'uninstall' = 'UninstallSoftware'; 'setup_machine' = 'NewMachineSetup'; 'new_machine' = 'NewMachineSetup'
		'add_user' = 'AddLocalUser'; 'local_user' = 'AddLocalUser'; 'create_user' = 'AddLocalUser'
		'join_domain' = 'JoinDomain'; 'domain_join' = 'JoinDomain'
		'leave_domain' = 'LeaveDomain'; 'disjoin' = 'LeaveDomain'; 'disjoin_domain' = 'LeaveDomain'
		'unjoin' = 'LeaveDomain'; 'unjoin_domain' = 'LeaveDomain'; 'remove_domain' = 'LeaveDomain'
		'map_drive' = 'MapNetworkDrive'; 'map_network_drive' = 'MapNetworkDrive'
		'unmap_drive' = 'RemoveMappedDrive'; 'remove_mapped_drive' = 'RemoveMappedDrive'; 'disconnect_drive' = 'RemoveMappedDrive'
		'unmap' = 'RemoveMappedDrive'; 'net_use_delete' = 'RemoveMappedDrive'
		'add_printer' = 'AddNetworkPrinter'; 'network_printer' = 'AddNetworkPrinter'
		'remove_printer' = 'RemoveNetworkPrinter'; 'delete_printer' = 'RemoveNetworkPrinter'
		'list_printers' = 'GetPrinters'; 'get_printers' = 'GetPrinters'; 'printers' = 'GetPrinters'
		'remove_user' = 'RemoveLocalUser'; 'delete_user' = 'RemoveLocalUser'; 'remove_local_user' = 'RemoveLocalUser'
		'reboot' = 'Reboot'; 'restart' = 'Reboot'; 'shutdown' = 'Reboot'; 'restart_pc' = 'Reboot'
		'create_share' = 'CreateShare'; 'make_share' = 'CreateShare'; 'network_share' = 'CreateShare'
		'smb_share' = 'CreateShare'; 'share_folder' = 'CreateShare'
		'remove_share' = 'RemoveShare'; 'delete_share' = 'RemoveShare'; 'unshare' = 'RemoveShare'
		'drop_share' = 'RemoveShare'; 'stop_share' = 'RemoveShare'
		'system_restore' = 'SystemRestore'; 'restore_point' = 'SystemRestore'
		'list_installers' = 'ListInstallers'; 'install_package' = 'InstallPackage'; 'install_app' = 'InstallPackage'
		'group_policy' = 'GroupPolicy'; 'gpedit' = 'GroupPolicy'; 'gpo' = 'GroupPolicy'
		'local_policy' = 'GroupPolicy'; 'secpol' = 'GroupPolicy'; 'policies' = 'GroupPolicy'
	}
	$key = ($lower -replace '[\s-]+', '_')
	if ($nick.ContainsKey($key)) { return [string]$nick[$key] }
	if ($nick.ContainsKey($lower)) { return [string]$nick[$lower] }

	$compact = $lower -replace '[^a-z0-9]', ''
	if ($compact.Length -lt 4) { return $null }
	$best = $null
	$bestScore = 0
	foreach ($n in $all) {
		$nc = $n.ToLowerInvariant() -replace '[^a-z0-9]', ''
		$score = 0
		if ($nc -eq $compact) { return $n }
		if ($nc.Contains($compact)) { $score = 50 + $compact.Length }
		elseif ($compact.Contains($nc) -and $nc.Length -ge 5) { $score = 40 + $nc.Length }
		elseif ($nc.StartsWith($compact.Substring(0, [math]::Min(5, $compact.Length)))) { $score = 20 }
		if ($score -gt $bestScore) { $bestScore = $score; $best = $n }
	}
	if ($bestScore -ge 25) { return $best }
	return $null
}

function Get-MBToolEnableHint {
	param([string]$ToolName)
	$resolved = Resolve-MBToolName -Name $ToolName
	if (-not $resolved) { $resolved = $ToolName }
	if ((Test-MBToolNeedsVision -Name $resolved) -and -not (Test-MBModelHasVision)) {
		return "Current model has no vision ability (Abilities must include 'vision'). $resolved is unavailable - do not call it."
	}
	if ((Test-MBToolNeedsGroupPolicyEdition -Name $resolved) -and -not (Test-MBWindowsHasLocalGroupPolicy)) {
		$why = Get-MBGroupPolicyUnavailableReason
		return "unavailable_tool=$resolved reason=windows_edition. $why Do not use RunCommand/reg to fake gpedit on Home."
	}
	if ((Test-MBToolNeedsDomainMembership -Name $resolved) -and -not (Test-MBHostOnDomain)) {
		$why = Get-MBRemoteCommandUnavailableReason
		return "unavailable_tool=$resolved reason=not_domain_joined. $why Do not thrash with RunCommand workarounds."
	}
	$grp = Get-MBToolGroupForName -Name $resolved
	if ($grp -and $grp -ne 'core') {
		# Machine-parseable recovery: models often spiral into RunCommand without this
		return "missing_tool=$resolved group=$grp. Call EnableToolGroup group=$grp then call $resolved (same turn; do not narrate; do not use RunCommand for this intent)."
	}
	if ($grp -eq 'core') {
		return "missing_tool=$resolved group=core (should already be available). Call $resolved directly - do not use RunCommand."
	}
	return "Call EnableToolGroup using MAP (vision|sound|forensics|system|network|diag|repair|setup|identity|shares|installers|sandbox|files|packages|registry|clipboard|web) then the real tool name."
}

function Get-MBAbilityParts {
	# Same tokens as the banner Abilities line (lowercase bits: vision, audio, ...)
	$capBits = New-Object System.Collections.ArrayList
	try {
		$m = Get-MBActiveModel
		if ([string]::IsNullOrWhiteSpace($m) -or $m -eq 'Select Model') { return @() }
		$info = $null
		try { $info = $script:MB.ServerInfo } catch { $info = $null }
		$ent = $null
		try {
			$k = [string]$script:MB.ActiveModelKey
			if ($k) { $ent = @($script:MB.RemoteModelEntries | Where-Object { $_.Key -eq $k } | Select-Object -First 1) }
			if (-not $ent) { $ent = @($script:MB.RemoteModelEntries | Where-Object { $_.Id -eq $m } | Select-Object -First 1) }
		} catch {}
		$vision = $false
		$audio = $false
		$slots = 0
		$nParams = 0
		if ($ent) {
			try { if ($ent.NParams -gt 0) { $nParams = [double]$ent.NParams } } catch {}
			try { $vision = [bool]$ent.Vision } catch {}
		}
		if ($info) {
			try { $vision = [bool]$info.Vision } catch {}
			try { $audio = [bool]$info.Audio } catch {}
			try { if ([int]$info.TotalSlots -gt 0) { $slots = [int]$info.TotalSlots } } catch {}
		}
		if ($vision) { [void]$capBits.Add('vision') }
		if ($audio) { [void]$capBits.Add('audio') }
		if ($slots -eq 1) {
			[void]$capBits.Add('logical (1)')
		} elseif ($slots -gt 1) {
			[void]$capBits.Add(('synchronous ({0})' -f $slots))
		}
		$ps = Format-MBParamCount -N $nParams
		if ($ps) { [void]$capBits.Add(('{0} params' -f $ps)) }
	} catch {}
	return @($capBits)
}

function Test-MBModelHasVision {
	# Abilities line shows lowercase "vision" when present - match that token only
	try {
		foreach ($p in @(Get-MBAbilityParts)) {
			if ([string]$p -ceq 'vision') { return $true }
		}
	} catch {}
	return $false
}

