		[int]$timeout_ms = 600,
		[int]$max_hosts = 64
	)
	Invoke-FindLanService -Service rdp -Hosts $Hosts -Computer $Computer -TimeoutMs $timeout_ms -MaxHosts $max_hosts
}

function Invoke-GetWindowsUpdateStatus {
	# Prefer native Windows Update COM (Microsoft.Update.Session) — no PSGallery/PSWindowsUpdate required.
	# Falls back to PSWindowsUpdate module only if COM path fails.
	$lastBoot = $null
	try {
		$lastBoot = (Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue).LastBootUpTime
		if ($lastBoot) { $lastBoot = $lastBoot.ToString('s') }
	} catch {}

	try {
		$session = New-Object -ComObject Microsoft.Update.Session
		$searcher = $session.CreateUpdateSearcher()
		# Pending software updates (not installed). Include optional for completeness; cap rows.
		$searchResult = $searcher.Search("IsInstalled=0 and Type='Software'")
		$rows = New-Object System.Collections.ArrayList
		$i = 0
		foreach ($u in @($searchResult.Updates)) {
			if ($null -eq $u) { continue }
			$i++
			if ($i -gt 80) { break }
			$kb = ''
			try {
				if ($u.KBArticleIDs -and @($u.KBArticleIDs).Count -gt 0) {
					$kb = (@($u.KBArticleIDs) | ForEach-Object { "KB$_" }) -join ','
				}
			} catch {}
			$sizeMb = $null
			try {
				if ($u.MaxDownloadSize -gt 0) {
					$sizeMb = [math]::Round([double]$u.MaxDownloadSize / 1MB, 2)
				}
			} catch {}
			[void]$rows.Add([ordered]@{
				Title      = [string]$u.Title
				KB         = $kb
				SizeMB     = $sizeMb
				IsDownloaded = $(try { [bool]$u.IsDownloaded } catch { $null })
				IsMandatory  = $(try { [bool]$u.IsMandatory } catch { $null })
				MsrcSeverity = $(try { [string]$u.MsrcSeverity } catch { '' })
			})
		}
		return ConvertTo-MBJson ([ordered]@{
			ok             = $true
			method         = 'Microsoft.Update.Session'
			count          = $rows.Count
			truncated     = ($i -gt 80)
			PendingUpdates = @($rows)
			LastBoot       = $lastBoot
			note           = 'Native WU COM search (IsInstalled=0 Software). No PSWindowsUpdate module required.'
		}) -Depth 5
	} catch {
		$comErr = $_.Exception.Message
		# Optional module fallback
		try {
			if (Get-Module -ListAvailable -Name PSWindowsUpdate) {
				Import-Module PSWindowsUpdate -ErrorAction SilentlyContinue
				$updates = @(Get-WUList -ErrorAction SilentlyContinue | Select-Object -First 80 Title, KB, Size)
				return ConvertTo-MBJson ([ordered]@{
					ok             = $true
					method         = 'PSWindowsUpdate'
					count          = $updates.Count
					PendingUpdates = $updates
					LastBoot       = $lastBoot
					com_error      = $comErr
					note           = 'COM path failed; used PSWindowsUpdate module fallback.'
				}) -Depth 4
			}
		} catch {}
		return ConvertTo-MBJson ([ordered]@{
			ok      = $false
			error   = $comErr
			LastBoot = $lastBoot
			note    = 'Windows Update COM unavailable (service disabled, offline, or policy). Install PSWindowsUpdate only if you want the module fallback.'
		})
	}
}

function Invoke-GetSystemUptime {
	$os = Get-CimInstance Win32_OperatingSystem
	$uptime = (Get-Date) - $os.LastBootUpTime
	ConvertTo-MBJson @{
		UptimeDays = [math]::Round($uptime.TotalDays, 2)
		Uptime     = "{0}d {1}h {2}m" -f $uptime.Days, $uptime.Hours, $uptime.Minutes
		LastBoot   = $os.LastBootUpTime.ToString("s")
	}
}

function Invoke-RunQuickDiagnostics {
	# Embed parsed objects (not nested JSON strings). Short event window; one-level disk scan.
	$diskRaw = Invoke-GetDiskSpace -deep:$false -timeout_sec 20 -top 8
	$diskObj = ConvertFrom-MBToolJson $diskRaw
	try {
		if ($diskObj -and $diskObj.PSObject.Properties['Note']) {
			$diskObj | Add-Member -NotePropertyName ScanNote -NotePropertyValue 'one_level (deep=false). Pass GetDiskSpace deep=true for recursive folder sizes.' -Force
		}
	} catch {}

	$bundle = [ordered]@{
		GeneratedAt = (Get-Date).ToString('s')
		Uptime      = ConvertFrom-MBToolJson (Invoke-GetSystemUptime)
		BSOD        = ConvertFrom-MBToolJson (Invoke-GetBSODInfo)
		Events      = ConvertFrom-MBToolJson (Invoke-GetEventLogs -hours 24 -max 25)
		DiskHealth  = ConvertFrom-MBToolJson (Invoke-GetDiskHealth)
		DiskSpace   = $diskObj
		Memory      = ConvertFrom-MBToolJson (Invoke-GetMemoryInfo)
		note        = 'QuickDiag: events last 24h collapsed; disk scan is one-level (not recursive). Use specialized tools for deep dive.'
	}
	Limit-MBResult (ConvertTo-MBJson $bundle -Depth 8) 32000
}

function Invoke-RunRepairTool {
	param(
		[string]$tool,
		[string]$driveLetter,
		[string]$arguments
	)
	$tool = "$tool".ToLower()
	$command = switch ($tool) {
		"sfc" {
			if ($arguments) { "sfc $arguments" } else { "sfc /scannow" }
		}
		"chkdsk" {
			$drive = if ($driveLetter) { $driveLetter } else { "C:" }
			if ($arguments) { "chkdsk $drive $arguments" } else { "chkdsk $drive /scan" }
		}
		"dism" {
			if ($arguments) { "DISM $arguments" } else { "DISM /Online /Cleanup-Image /RestoreHealth" }
		}
		default { return "ERROR: Unknown tool '$tool'. Use sfc, dism, or chkdsk." }
	}

	$details = "Tool: $tool"
	if ($driveLetter) { $details += "`nDrive: $driveLetter" }
	if ($arguments) { $details += "`nArguments: $arguments" }
	$details += "`n`nExecutes:`n  $command"

	if (-not (Request-Confirmation -Title "Repair tool requires approval" -Details $details)) {
		return "BLOCKED BY USER: Repair action denied by operator."
	}
	return Invoke-RunCommand -command $command -shell "cmd" -timeout_sec 7200
}

function ConvertTo-MBServiceRow {
	param($Svc)
	if ($null -eq $Svc) { return $null }
	$statusStr = 'Unknown'
	$startStr = 'Unknown'
	try { $statusStr = [string]$Svc.Status } catch {}
	try { $startStr = [string]$Svc.StartType } catch {}
	# Normalize to stable string enums (never numeric ServiceControllerStatus)
	return [ordered]@{
		Name        = [string]$Svc.Name
		DisplayName = [string]$Svc.DisplayName
		Status      = $statusStr
		StartType   = $startStr
	}
}

function Invoke-GetServiceStatus {
	param(
		[string]$name,
		[string]$status = '',
		[int]$max = 250
	)
	if ($max -le 0) { $max = 250 }
	if ($max -gt 1000) { $max = 1000 }
	try {
		if ($name) {
			$svc = Get-Service -Name $name -ErrorAction Stop
			return ConvertTo-MBJson ([ordered]@{
				ok      = $true
				count   = 1
				service = (ConvertTo-MBServiceRow $svc)
			}) -Depth 4
		}
		$svcs = @(Get-Service -ErrorAction Stop)
		if ($status) {
			$want = $status.Trim()
			$svcs = @($svcs | Where-Object { [string]$_.Status -like $want -or [string]$_.Status -eq $want })
		}
		$total = $svcs.Count
		$svcs = @($svcs | Sort-Object Name | Select-Object -First $max)
		$rows = @($svcs | ForEach-Object { ConvertTo-MBServiceRow $_ })
		return ConvertTo-MBJson ([ordered]@{
			ok        = $true
			count     = $rows.Count
			total     = $total
			truncated = ($total -gt $rows.Count)
			services  = $rows
			status_enum = @('Running','Stopped','Paused','StartPending','StopPending','ContinuePending','PausePending')
			starttype_enum = @('Automatic','Manual','Disabled','Boot','System')
		}) -Depth 5
	} catch {
		return ConvertTo-MBJson ([ordered]@{ ok = $false; error = $_.Exception.Message })
	}
}

function Invoke-ControlService {
	param(
		[string]$name,
		[string]$action,
		[string]$startup_type
	)
	if ([string]::IsNullOrWhiteSpace($name)) { return "ERROR: name is required." }
	if ([string]::IsNullOrWhiteSpace($action)) { return "ERROR: action is required (start|stop|restart|set_startup)." }
	$action = $action.Trim().ToLowerInvariant()
	if ($action -notin @('start','stop','restart','set_startup')) {
		return "ERROR: action must be start, stop, restart, or set_startup."
	}

	$startMap = @{
		'automatic'             = 'Automatic'
		'auto'                  = 'Automatic'
		'manual'                = 'Manual'
		'disabled'              = 'Disabled'
		'automaticdelayedstart' = 'Automatic'
		'delayed'               = 'Automatic'
		'delayedauto'           = 'Automatic'
	}
	$wantStartup = $null
	$wantDelayed = $false
	if (-not [string]::IsNullOrWhiteSpace($startup_type)) {
		$key = ($startup_type -replace '[\s_-]','').ToLowerInvariant()
		if (-not $startMap.ContainsKey($key)) {
			return "ERROR: startup_type must be Automatic, Manual, Disabled, or AutomaticDelayedStart."
		}
		$wantStartup = $startMap[$key]
		if ($key -in @('automaticdelayedstart','delayed','delayedauto')) { $wantDelayed = $true }
	}
	if ($action -eq 'set_startup' -and -not $wantStartup) {
		return "ERROR: set_startup requires startup_type."
	}

	try {
		$svc = Get-Service -Name $name -ErrorAction Stop
	} catch {
		return "ERROR: Service not found: $name - $($_.Exception.Message)"
	}

	$details = "Service: $($svc.Name) ($($svc.DisplayName))`nCurrent: Status=$($svc.Status) StartType=$($svc.StartType)`nAction: $action"
	if ($wantStartup) {
		$details += "`nStartupType: $wantStartup"
		if ($wantDelayed) { $details += " (DelayedAutoStart)" }
	}
	if (-not (Request-Confirmation -Title "ControlService requires approval" -Details $details)) {
		return "BLOCKED BY USER: Service control denied by operator."
	}

	try {
		switch ($action) {
			'start' {
				if ($svc.Status -eq 'Running') {
					return ConvertTo-MBJson @{ success = $true; note = "Already running"; service = (ConvertTo-MBServiceRow $svc) }
				}
				Start-Service -Name $svc.Name -ErrorAction Stop
			}
			'stop' {
				if ($svc.Status -eq 'Stopped') {
					return ConvertTo-MBJson @{ success = $true; note = "Already stopped"; service = (ConvertTo-MBServiceRow $svc) }
				}
				Stop-Service -Name $svc.Name -Force -ErrorAction Stop
			}
			'restart' {
				Restart-Service -Name $svc.Name -Force -ErrorAction Stop
			}
			'set_startup' {
			}
		}

		if ($wantStartup -or $action -eq 'set_startup') {
			Set-Service -Name $svc.Name -StartupType $wantStartup -ErrorAction Stop
			if ($wantDelayed) {
				try {
					$regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\$($svc.Name)"
					if (Test-Path -LiteralPath $regPath) {
						Set-ItemProperty -LiteralPath $regPath -Name DelayedAutoStart -Value 1 -Type DWord -Force -ErrorAction Stop
					}
				} catch {
					# Best-effort; service start type still set
				}
			} elseif ($wantStartup -eq 'Automatic') {
				try {
					$regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\$($svc.Name)"
					if (Test-Path -LiteralPath $regPath) {
						$prop = Get-ItemProperty -LiteralPath $regPath -Name DelayedAutoStart -ErrorAction SilentlyContinue
						if ($null -ne $prop -and $null -ne $prop.DelayedAutoStart) {
							Set-ItemProperty -LiteralPath $regPath -Name DelayedAutoStart -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
						}
					}
				} catch {}
			}
		}

		$after = Get-Service -Name $svc.Name -ErrorAction Stop
		$prefix = if ($script:MB.AutoApprove) { "SUCCESS (auto-approved)" } else { "SUCCESS" }
		return ConvertTo-MBJson @{
			success = $true
			message = "$prefix`: ControlService $action on $($after.Name)"
			service = (ConvertTo-MBServiceRow $after)
		}
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

function Write-MBDownloadProgress {
	param(
		[string]$Label = 'Downloading',
		[int]$Percent = -1,
		[int64]$Bytes = 0,
		[int64]$TotalBytes = 0,
		[ValidateSet('start','update','done','fail')]
		[string]$Phase = 'update',
		[string]$Detail = ''
	)
	if (-not (Test-MBWpfActive)) { return }
	$lab = ([string]$Label).Trim()
	if ($lab.Length -eq 0) { $lab = 'Downloading' }
	if (-not $script:MB.Wpf.WriteQueue) {
		$script:MB.Wpf.WriteQueue = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
	}
	$script:MB.Wpf.WriteQueue.Enqueue([pscustomobject]@{
		Kind       = 'dl-progress'
		Text       = $lab
		Percent    = [int]$Percent
		Bytes      = [int64]$Bytes
		TotalBytes = [int64]$TotalBytes
		Phase      = [string]$Phase
		Detail     = [string]$Detail
		Color      = 'Cyan'
		NoNewline  = $true
		MdNoLinks  = 1
	})
}

function Invoke-MBHttpDownload {
	param(
		[Parameter(Mandatory)]
		[string]$Url,
		[Parameter(Mandatory)]
		[string]$OutPath,
		[int]$TimeoutSec = 900,
		[int64]$MaxBytes = 0,
		[string]$UserAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) MiniBot/2.8',
		[string]$Label = 'Downloading',
		[switch]$ShowProgress
	)
	if ([string]::IsNullOrWhiteSpace($Url) -or [string]::IsNullOrWhiteSpace($OutPath)) {
		return @{ ok = $false; error = 'url/out required' }
	}
	if ($TimeoutSec -lt 15) { $TimeoutSec = 15 }
	try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 -bor [Net.SecurityProtocolType]::Tls11 -bor [Net.SecurityProtocolType]::Tls } catch {}

	$dir = Split-Path -Parent $OutPath
	if ($dir -and -not (Test-Path -LiteralPath $dir)) {
		New-Item -ItemType Directory -Path $dir -Force | Out-Null
	}

	$response = $null
	$inStream = $null
	$outStream = $null
	$wrotePartial = $false
	$finalUrl = $Url
	$contentType = $null
	$total = [int64]0
	$contentLength = [int64]-1
	$lastPct = -1
	$lastTick = 0

	try {
		if ($ShowProgress) {
			Write-MBDownloadProgress -Label $Label -Percent 0 -Bytes 0 -TotalBytes 0 -Phase start
		}

		$uri = New-Object System.Uri ($Url)
		$req = [System.Net.HttpWebRequest]::Create($uri)
		$req.Method = 'GET'
		$req.Timeout = [Math]::Min(30000, $TimeoutSec * 1000)
		$req.ReadWriteTimeout = $TimeoutSec * 1000
		$req.AllowAutoRedirect = $true
		try { $req.MaximumAutomaticRedirections = 15 } catch {}
		$req.UserAgent = $UserAgent
		$req.AutomaticDecompression = [System.Net.DecompressionMethods]::GZip -bor [System.Net.DecompressionMethods]::Deflate

		$response = $req.GetResponse()
		try { $finalUrl = [string]$response.ResponseUri.AbsoluteUri } catch {}
		try { $contentType = [string]$response.ContentType } catch {}
		try { $contentLength = [int64]$response.ContentLength } catch { $contentLength = -1 }
		if ($MaxBytes -gt 0 -and $contentLength -gt 0 -and $contentLength -gt $MaxBytes) {
			throw (New-Object System.Exception ("Content-Length {0} bytes exceeds max {1}." -f $contentLength, $MaxBytes))
		}

		$inStream = $response.GetResponseStream()
		$outStream = New-Object System.IO.FileStream -ArgumentList @($OutPath, [System.IO.FileMode]::Create)
		$wrotePartial = $true
		$buffer = New-Object byte[] 16384
		$count = $inStream.Read($buffer, 0, $buffer.Length)
		$total = [int64]$count
		while ($count -gt 0) {
			if (Test-MBInterrupt) {
				throw (New-Object System.Exception 'Download interrupted by user.')
			}
			if ($MaxBytes -gt 0 -and $total -gt $MaxBytes) {
				throw (New-Object System.Exception ("Download exceeded max size ({0} bytes)." -f $MaxBytes))
			}
			$outStream.Write($buffer, 0, $count)
			$count = $inStream.Read($buffer, 0, $buffer.Length)
			$total = $total + [int64]$count

			if ($ShowProgress) {
				$now = [Environment]::TickCount
				$should = $false
				$pct = -1
				if ($contentLength -gt 0) {
					$totalKb = [Math]::Max(1.0, [Math]::Floor($contentLength / 1024.0))
					$doneKb = [Math]::Floor($total / 1024.0)
					$pct = [int](($doneKb / $totalKb) * 100)
					if ($pct -gt 100) { $pct = 100 }
					if ($pct -ne $lastPct) { $should = $true; $lastPct = $pct }
				} else {
					if (($now - $lastTick) -ge 200 -or $lastTick -eq 0) { $should = $true; $lastTick = $now }
				}
				if ($should) {
					$totShow = if ($contentLength -gt 0) { $contentLength } else { [int64]0 }
					Write-MBDownloadProgress -Label $Label -Percent $pct -Bytes $total -TotalBytes $totShow -Phase update
				}
			}
		}
		$outStream.Flush()
		$outStream.Close(); $outStream = $null
		$inStream.Close(); $inStream = $null
		$response.Close(); $response = $null

		if ($total -lt 1) {
			throw (New-Object System.Exception 'empty download body')
		}
		if ($ShowProgress) {
			$totShow = if ($contentLength -gt 0) { $contentLength } else { $total }
			Write-MBDownloadProgress -Label $Label -Percent 100 -Bytes $total -TotalBytes $totShow -Phase done
		}
		return @{
			ok           = $true
			path         = $OutPath
			bytes        = $total
			final_url    = $finalUrl
			content_type = $contentType
			content_length = $contentLength
		}
	} catch {
		$err = $_.Exception.Message
		if ($ShowProgress) {
			try { Write-MBDownloadProgress -Label $Label -Percent -1 -Bytes $total -TotalBytes 0 -Phase fail -Detail $err } catch {}
		}
		if ($outStream) { try { $outStream.Close() } catch {} }
		if ($inStream) { try { $inStream.Close() } catch {} }
		if ($response) { try { $response.Close() } catch {} }
		if ($wrotePartial -and (Test-Path -LiteralPath $OutPath)) {
			try { Remove-Item -LiteralPath $OutPath -Force -ErrorAction SilentlyContinue } catch {}
		}
		return @{ ok = $false; error = $err; bytes = $total }
	} finally {
		if ($outStream) { try { $outStream.Dispose() } catch {} }
		if ($inStream) { try { $inStream.Dispose() } catch {} }
		if ($response) { try { $response.Dispose() } catch {} }
	}
}

function Invoke-DownloadFile {
	param(
		[string]$url,
		[string]$path,
		[bool]$overwrite = $false,
		[int]$max_mb = 100,
		[int]$timeout_sec = 120
	)
	if ([string]::IsNullOrWhiteSpace($url)) { return "ERROR: url is required." }
	if ([string]::IsNullOrWhiteSpace($path)) { return "ERROR: path is required." }
	if ($url -notmatch '^(?i)https?://') { return "ERROR: url must start with http:// or https://" }

	if ($max_mb -le 0) { $max_mb = 100 }
	if ($max_mb -gt 512) { $max_mb = 512 }
	if ($timeout_sec -le 0) { $timeout_sec = 120 }
	if ($timeout_sec -gt 3600) { $timeout_sec = 3600 }
	$maxBytes = [int64]$max_mb * 1MB

	$dest = Resolve-MBPath $path
	if ((Test-Path -LiteralPath $dest) -and -not $overwrite) {
		return "ERROR: Destination exists (set overwrite=true): $dest"
	}
	$parent = Split-Path -Parent $dest
	if ($parent -and -not (Test-Path -LiteralPath $parent)) {
		return "ERROR: Parent directory does not exist: $parent"
	}

	$details = "Download URL to local path:`n`n  URL:  $url`n  Path: $dest`n  Max:  ${max_mb} MB`n  Overwrite: $overwrite`n  Timeout: ${timeout_sec}s"
	if (-not (Request-Confirmation -Title "DownloadFile requires approval" -Details $details)) {
		return "BLOCKED BY USER: Download denied by operator."
	}

	$leaf = [System.IO.Path]::GetFileName($dest)
	if ([string]::IsNullOrWhiteSpace($leaf)) { $leaf = 'file' }
	$r = Invoke-MBHttpDownload -Url $url -OutPath $dest -TimeoutSec $timeout_sec -MaxBytes $maxBytes `
		-UserAgent 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) MiniBot/2.8 DownloadFile' `
		-Label ("Downloading {0}" -f $leaf) -ShowProgress
	if (-not $r.ok) {
		return "ERROR: $($r.error)"
	}
	$prefix = if ($script:MB.AutoApprove) { "SUCCESS (auto-approved)" } else { "SUCCESS" }
	return ConvertTo-MBJson @{
		success      = $true
		message      = "$prefix`: Downloaded $($r.bytes) bytes to $dest"
		path         = $dest
		bytes        = $r.bytes
		url          = $url
		final_url    = $r.final_url
		content_type = $r.content_type
		max_mb       = $max_mb
	}
}

function Invoke-ExpandArchive {
	param(
		[string]$path,
		[string]$destination,
		[bool]$force = $false
	)
	if ([string]::IsNullOrWhiteSpace($path)) { return "ERROR: path is required." }
	if ([string]::IsNullOrWhiteSpace($destination)) { return "ERROR: destination is required." }

	$src = Resolve-MBPath $path
	$dest = Resolve-MBPath $destination
	if (-not (Test-Path -LiteralPath $src)) { return "ERROR: Archive not found: $src" }
	if (-not (Test-Path -LiteralPath $src -PathType Leaf)) { return "ERROR: path must be a file: $src" }
	$ext = [System.IO.Path]::GetExtension($src)
	if ($ext -notin @('.zip','.ZIP')) {
		return "ERROR: Only .zip archives are supported (got extension '$ext')."
	}

	$details = "Extract archive:`n`n  Archive: $src`n  Dest:    $dest`n  Force:   $force"
	if (-not (Request-Confirmation -Title "ExpandArchive requires approval" -Details $details)) {
		return "BLOCKED BY USER: Extract denied by operator."
	}

	try {
		if (-not (Test-Path -LiteralPath $dest)) {
			New-Item -ItemType Directory -Path $dest -Force -ErrorAction Stop | Out-Null
		}
		$expandParams = @{
			LiteralPath     = $src
			DestinationPath = $dest
			ErrorAction     = 'Stop'
		}
		$eaCmd = Get-Command Expand-Archive -ErrorAction SilentlyContinue
		if ($force -and $eaCmd -and $eaCmd.Parameters.ContainsKey('Force')) {
			$expandParams['Force'] = $true
		}
		Expand-Archive @expandParams
		$entries = @(Get-ChildItem -LiteralPath $dest -Recurse -Force -ErrorAction SilentlyContinue | Select-Object -First 50)
		$prefix = if ($script:MB.AutoApprove) { "SUCCESS (auto-approved)" } else { "SUCCESS" }
		return ConvertTo-MBJson @{
			success     = $true
			message     = "$prefix`: Extracted $src -> $dest"
			path        = $src
			destination = $dest
			sample      = @($entries | ForEach-Object {
				[ordered]@{
					name = $_.Name
					full = $_.FullName
					type = $(if ($_.PSIsContainer) { 'dir' } else { 'file' })
					size = $(if (-not $_.PSIsContainer) { [int64]$_.Length } else { $null })
				}
			})
		} -Depth 5
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

function Invoke-CompressArchive {
	param(
		[string]$path,
		[string]$destination,
		[bool]$force = $false
	)
	if ([string]::IsNullOrWhiteSpace($path)) { return "ERROR: path is required." }
	if ([string]::IsNullOrWhiteSpace($destination)) { return "ERROR: destination is required." }

	$src = Resolve-MBPath $path
	$dest = Resolve-MBPath $destination
	if (-not (Test-Path -LiteralPath $src)) { return "ERROR: Source not found: $src" }

	$destExt = [System.IO.Path]::GetExtension($dest)
	if ($destExt -and $destExt.ToLowerInvariant() -ne '.zip') {
		return "ERROR: destination must end with .zip (got '$destExt')."
	}
	if (-not $destExt) { $dest = "$dest.zip" }

	if ((Test-Path -LiteralPath $dest) -and -not $force) {
		return "ERROR: Destination zip exists (set force=true): $dest"
	}

	$parent = Split-Path -Parent $dest
	if ($parent -and -not (Test-Path -LiteralPath $parent)) {
		return "ERROR: Parent directory does not exist: $parent"
	}

	$details = "Create zip archive:`n`n  Source: $src`n  Zip:    $dest`n  Force:  $force"
	if (-not (Request-Confirmation -Title "CompressArchive requires approval" -Details $details)) {
		return "BLOCKED BY USER: Compress denied by operator."
	}

	try {
		if ((Test-Path -LiteralPath $dest) -and $force) {
			Remove-Item -LiteralPath $dest -Force -ErrorAction Stop
		}
		Compress-Archive -Path $src -DestinationPath $dest -ErrorAction Stop
		$fi = Get-Item -LiteralPath $dest -ErrorAction Stop
		$prefix = if ($script:MB.AutoApprove) { "SUCCESS (auto-approved)" } else { "SUCCESS" }
		return ConvertTo-MBJson @{
			success     = $true
			message     = "$prefix`: Compressed $src -> $dest"
			path        = $src
			destination = $dest
			bytes       = [int64]$fi.Length
		}
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

# ISO helpers (IMAPI2)
function Initialize-MBIsoFileType {
	if ('MB_ISOFileWriter' -as [type]) { return $true }
	try {
		$cp = New-Object System.CodeDom.Compiler.CompilerParameters
		$cp.CompilerOptions = '/unsafe'
		Add-Type -CompilerParameters $cp -TypeDefinition @'
public class MB_ISOFileWriter {
  public unsafe static void Create(string Path, object Stream, int BlockSize, int TotalBlocks) {
    int bytes = 0;
    byte[] buf = new byte[BlockSize];
    var ptr = (System.IntPtr)(&bytes);
    var o = System.IO.File.OpenWrite(Path);
    var i = Stream as System.Runtime.InteropServices.ComTypes.IStream;
    if (o != null) {
      while (TotalBlocks-- > 0) {
        i.Read(buf, BlockSize, ptr);
        o.Write(buf, 0, bytes);
      }
      o.Flush();
      o.Close();
    }
  }
}
'@ -ErrorAction Stop
		return [bool]('MB_ISOFileWriter' -as [type])
	} catch {
		return $false
	}
}

function Dismount-MBIsoIfMounted {
	param([string]$IsoPath)
	if ([string]::IsNullOrWhiteSpace($IsoPath)) { return }
	if (-not (Test-Path -LiteralPath $IsoPath)) { return }
	try {
		$img = Get-DiskImage -ImagePath $IsoPath -ErrorAction SilentlyContinue
		if ($img -and $img.Attached) {
			Dismount-DiskImage -ImagePath $IsoPath -ErrorAction SilentlyContinue | Out-Null
		}
	} catch {}
}

function Get-MBIsoMountInfo {
	param([string]$IsoPath)
	$out = [ordered]@{
		path         = $IsoPath
		attached     = $false
		drive_letter = ''
		device_path  = ''
	}
	if ([string]::IsNullOrWhiteSpace($IsoPath) -or -not (Test-Path -LiteralPath $IsoPath)) { return $out }
	try {
		$img = Get-DiskImage -ImagePath $IsoPath -ErrorAction Stop
		$out.attached = [bool]$img.Attached
		$out.device_path = [string]$img.DevicePath
		if ($img.Attached) {
			$vol = Get-Volume -DiskImage $img -ErrorAction SilentlyContinue | Select-Object -First 1
			if ($vol -and $vol.DriveLetter) {
				$out.drive_letter = ([string]$vol.DriveLetter).TrimEnd(':')
			}
		}
	} catch {}
	return $out
}

function New-MBIsoFile {
	# Create ISO from paths via IMAPI2.
	param(
		[Parameter(Mandatory = $true)]
		[object[]]$Items,
		[Parameter(Mandatory = $true)]
		[string]$Path,
		[string]$BootFile = '',
		[string]$Title = '',
		[string]$Media = 'DVDPLUSRW_DUALLAYER',
		[switch]$Force
	)
	if (-not (Initialize-MBIsoFileType)) {
		throw "ISO writer type failed to load (needs Windows PowerShell + /unsafe Add-Type)."
	}
	$mediaTypes = @(
		'UNKNOWN','CDROM','CDR','CDRW','DVDROM','DVDRAM','DVDPLUSR','DVDPLUSRW','DVDPLUSR_DUALLAYER',
		'DVDDASHR','DVDDASHRW','DVDDASHR_DUALLAYER','DISK','DVDPLUSRW_DUALLAYER','HDDVDROM','HDDVDR',
		'HDDVDRAM','BDROM','BDR','BDRE'
	)
	$mediaName = if ([string]::IsNullOrWhiteSpace($Media)) { 'DVDPLUSRW_DUALLAYER' } else { $Media.Trim().ToUpperInvariant() }
	$mediaIdx = [array]::IndexOf($mediaTypes, $mediaName)
	if ($mediaIdx -lt 0) { throw "Unknown media type '$Media'. Use e.g. DVDPLUSRW_DUALLAYER, DVDPLUSR, CDR." }

	$volTitle = if ([string]::IsNullOrWhiteSpace($Title)) {
		(Get-Date).ToString('yyyyMMdd-HHmmss')
	} else {
		# Volume labels are limited; strip bad chars
		$t = [regex]::Replace([string]$Title, '[\\/:*?"<>|]', '_')
		if ($t.Length -gt 32) { $t = $t.Substring(0, 32) }
		$t
	}

	$boot = $null
	if (-not [string]::IsNullOrWhiteSpace($BootFile)) {
		if (-not (Test-Path -LiteralPath $BootFile -PathType Leaf)) {
			throw "Boot file not found: $BootFile"
		}
		if ($mediaName -in @('BDR', 'BDRE')) {
			Write-Warning "Bootable image often fails with media type $mediaName"
		}
		$stream = New-Object -ComObject ADODB.Stream
		$stream.Type = 1 # adTypeBinary
		$stream.Open()
		$stream.LoadFromFile((Get-Item -LiteralPath $BootFile).FullName)
		$boot = New-Object -ComObject IMAPI2FS.BootOptions
		$boot.AssignBootImage($stream)
	}

	$image = New-Object -ComObject IMAPI2FS.MsftFileSystemImage
	$image.VolumeName = $volTitle
	$image.ChooseImageDefaultsForMediaType($mediaIdx)

	$itemCount = 0
	foreach ($raw in @($Items)) {
		if ($null -eq $raw) { continue }
		$item = $null
		if ($raw -is [System.IO.FileInfo] -or $raw -is [System.IO.DirectoryInfo]) {
			$item = $raw
		} else {
			$p = [string]$raw
			if ([string]::IsNullOrWhiteSpace($p)) { continue }
			if (-not (Test-Path -LiteralPath $p)) { throw "Source item not found: $p" }
			$item = Get-Item -LiteralPath $p -Force -ErrorAction Stop
		}
		if (-not $item) { continue }
		try {
			# true = include the item node (file or folder tree)
			[void]$image.Root.AddTree($item.FullName, $true)
			$itemCount++
		} catch {
			throw ("Failed adding '{0}': {1} (try a different media type or fewer files)" -f $item.FullName, $_.Exception.Message.Trim())
		}
	}
	if ($itemCount -eq 0) { throw "No files/folders were added to the ISO." }

	if ($boot) { $image.BootImageOptions = $boot }

	if ((Test-Path -LiteralPath $Path) -and -not $Force) {
		throw "ISO already exists (use force=true): $Path"
	}
	if (Test-Path -LiteralPath $Path) {
		Dismount-MBIsoIfMounted -IsoPath $Path
		Remove-Item -LiteralPath $Path -Force -ErrorAction Stop
	}
	$parent = Split-Path -Parent $Path
	if ($parent -and -not (Test-Path -LiteralPath $parent)) {
		throw "Parent directory does not exist: $parent"
	}
	# Ensure empty target file exists for IMAPI writer
	[void](New-Item -Path $Path -ItemType File -Force -ErrorAction Stop)

	$result = $image.CreateResultImage()
	[MB_ISOFileWriter]::Create($Path, $result.ImageStream, $result.BlockSize, $result.TotalBlocks)
	return (Get-Item -LiteralPath $Path -ErrorAction Stop)
}

function Invoke-MakeIso {
	param(
		[string]$source = '',
		[string]$destination = '',
		[string]$boot_file = '',
		[string]$title = '',
		[bool]$force = $false,
		[bool]$include_folder = $false,
		[string]$media = 'DVDPLUSRW_DUALLAYER'
	)
	if ([string]::IsNullOrWhiteSpace($source)) { return "ERROR: source is required (folder to pack)." }
	if ([string]::IsNullOrWhiteSpace($destination)) { return "ERROR: destination is required (output .iso path)." }

	$src = Resolve-MBPath $source
	$dest = Resolve-MBPath $destination
	if (-not (Test-Path -LiteralPath $src)) { return "ERROR: Source not found: $src" }

	$destExt = [System.IO.Path]::GetExtension($dest)
	if ($destExt -and $destExt.ToLowerInvariant() -ne '.iso') {
		return "ERROR: destination must end with .iso (got '$destExt')."
	}
	if (-not $destExt) { $dest = "$dest.iso" }

	$boot = ''
	if (-not [string]::IsNullOrWhiteSpace($boot_file)) {
		$boot = Resolve-MBPath $boot_file
		if (-not (Test-Path -LiteralPath $boot -PathType Leaf)) {
			return "ERROR: boot_file not found: $boot"
		}
	}

	if ((Test-Path -LiteralPath $dest) -and -not $force) {
		return "ERROR: Destination ISO exists (set force=true): $dest"
	}

	# Match CMD workflow: Get-ChildItem source | New-IsoFile  (children at ISO root)
	$items = @()
	$srcItem = Get-Item -LiteralPath $src -Force -ErrorAction Stop
	if ($srcItem.PSIsContainer -and -not $include_folder) {
		$items = @(Get-ChildItem -LiteralPath $src -Force -ErrorAction Stop)
		if ($items.Count -eq 0) { return "ERROR: Source folder is empty: $src" }
	} else {
		$items = @($srcItem)
	}

	$modeLabel = if ($include_folder -or -not $srcItem.PSIsContainer) {
		'include source item as-is'
	} else {
		'folder contents at ISO root (bootable-media style)'
	}
	$details = @"
Build ISO image (IMAPI2 / New-IsoFile style):

  Source:      $src
  Mode:        $modeLabel
  Items:       $($items.Count)
  ISO:         $dest
  Boot file:   $(if ($boot) { $boot } else { '(none)' })
  Title:       $(if ($title) { $title } else { '(auto timestamp)' })
  Media:       $media
  Force:       $force
"@
	if (-not (Request-Confirmation -Title "MakeIso requires approval" -Details $details)) {
		return "BLOCKED BY USER: MakeIso denied by operator."
	}

	try {
		$sw = [System.Diagnostics.Stopwatch]::StartNew()
		$fi = New-MBIsoFile -Items $items -Path $dest -BootFile $boot -Title $title -Media $media -Force:$force
		$sw.Stop()
		$prefix = if ($script:MB.AutoApprove) { 'SUCCESS (auto-approved)' } else { 'SUCCESS' }
		return ConvertTo-MBJson ([ordered]@{
			success        = $true
			message        = ("{0}: ISO created {1}" -f $prefix, $dest)
			source         = $src
			destination    = $dest
			boot_file      = $(if ($boot) { $boot } else { $null })
			title          = $(if ($title) { $title } else { $null })
			include_folder = [bool]$include_folder
			item_count     = [int]$items.Count
			bytes          = [int64]$fi.Length
			duration_ms    = [int]$sw.ElapsedMilliseconds
			bootable       = [bool](-not [string]::IsNullOrWhiteSpace($boot))
		}) -Depth 5
	} catch {
		return "ERROR: MakeIso failed: $($_.Exception.Message)"
	}
}

function Invoke-MountIso {
	param([string]$path = '')
	if ([string]::IsNullOrWhiteSpace($path)) { return "ERROR: path is required (.iso file)." }
	$iso = Resolve-MBPath $path
	if (-not (Test-Path -LiteralPath $iso -PathType Leaf)) {
		return "ERROR: ISO not found: $iso"
	}
	$ext = [System.IO.Path]::GetExtension($iso)
	if ($ext -and $ext.ToLowerInvariant() -ne '.iso') {
		return "ERROR: path should be a .iso file (got '$ext')."
	}

	$cur = Get-MBIsoMountInfo -IsoPath $iso
	if ($cur.attached -and $cur.drive_letter) {
		return ConvertTo-MBJson ([ordered]@{
			success      = $true
			message      = "Already mounted at $($cur.drive_letter):"
			path         = $iso
			drive_letter = $cur.drive_letter
			already      = $true
		})
	}

	$details = "Mount ISO image:`n`n  ISO: $iso"
	if (-not (Request-Confirmation -Title "MountIso requires approval" -Details $details)) {
		return "BLOCKED BY USER: MountIso denied by operator."
	}

	try {
		$img = Mount-DiskImage -ImagePath $iso -PassThru -ErrorAction Stop
		# Storage subsystem sometimes needs a moment to assign a letter
		$letter = ''
		for ($i = 0; $i -lt 20; $i++) {
			Start-Sleep -Milliseconds 150
			$info = Get-MBIsoMountInfo -IsoPath $iso
			if ($info.drive_letter) { $letter = $info.drive_letter; break }
			try {
				$vol = Get-Volume -DiskImage $img -ErrorAction SilentlyContinue | Select-Object -First 1
				if ($vol -and $vol.DriveLetter) {
					$letter = ([string]$vol.DriveLetter).TrimEnd(':')
					break
				}
			} catch {}
		}
		$prefix = if ($script:MB.AutoApprove) { 'SUCCESS (auto-approved)' } else { 'SUCCESS' }
		return ConvertTo-MBJson ([ordered]@{
			success      = $true
			message      = $(if ($letter) { "$prefix`: Mounted $iso -> ${letter}:" } else { "$prefix`: Mounted $iso (no drive letter yet)" })
			path         = $iso
			drive_letter = $letter
			device_path  = $(try { [string]$img.DevicePath } catch { '' })
		})
	} catch {
		return "ERROR: MountIso failed: $($_.Exception.Message)"
	}
}

function Invoke-UnmountIso {
	param(
		[string]$path = '',
		[string]$letter = ''
	)
	$iso = ''
	$drive = ''
	if (-not [string]::IsNullOrWhiteSpace($path)) {
		$iso = Resolve-MBPath $path
	}
	if (-not [string]::IsNullOrWhiteSpace($letter)) {
		$drive = ([string]$letter).Trim().TrimEnd(':').ToUpperInvariant()
		if ($drive.Length -ne 1 -or $drive -notmatch '^[A-Z]$') {
			return "ERROR: letter must be a single drive letter (e.g. E)."
		}
	}
	if (-not $iso -and -not $drive) {
		return "ERROR: Provide path= to the .iso and/or letter= drive to unmount."
	}

	# Resolve ISO path from drive letter if needed
	if (-not $iso -and $drive) {
		try {
			$disk = Get-Volume -DriveLetter $drive -ErrorAction Stop | Get-Partition -ErrorAction SilentlyContinue | Get-Disk -ErrorAction SilentlyContinue
			# Prefer DiskImage lookup via Get-DiskImage for all attached
			$attached = @(Get-DiskImage -ErrorAction SilentlyContinue | Where-Object { $_.Attached })
			foreach ($a in $attached) {
				try {
					$vol = Get-Volume -DiskImage $a -ErrorAction SilentlyContinue | Select-Object -First 1
					if ($vol -and ([string]$vol.DriveLetter).TrimEnd(':').ToUpperInvariant() -eq $drive) {
						$iso = [string]$a.ImagePath
						break
					}
				} catch {}
			}
		} catch {}
		if (-not $iso) {
			# Fallback: dismount by path only works with ImagePath; try letter-based CIM
			return "ERROR: Could not resolve mounted ISO for letter ${drive}:. Pass path= to the .iso file."
		}
	}

	if ($iso -and -not (Test-Path -LiteralPath $iso)) {
		return "ERROR: ISO path not found: $iso"
	}

	$info = if ($iso) { Get-MBIsoMountInfo -IsoPath $iso } else { $null }
	$details = "Unmount ISO image:`n`n  ISO:    $(if ($iso) { $iso } else { '(unknown)' })`n  Letter: $(if ($drive) { $drive + ':' } else { $(if ($info -and $info.drive_letter) { $info.drive_letter + ':' } else { '(auto)' }) })"
	if (-not (Request-Confirmation -Title "UnmountIso requires approval" -Details $details)) {
		return "BLOCKED BY USER: UnmountIso denied by operator."
	}

	try {
		if ($info -and -not $info.attached) {
			return ConvertTo-MBJson ([ordered]@{
				success = $true
				message = "ISO was not mounted: $iso"
				path    = $iso
				already = $true
			})
		}
		Dismount-DiskImage -ImagePath $iso -ErrorAction Stop | Out-Null
		$prefix = if ($script:MB.AutoApprove) { 'SUCCESS (auto-approved)' } else { 'SUCCESS' }
		return ConvertTo-MBJson ([ordered]@{
			success      = $true
			message      = "$prefix`: Dismounted $iso"
			path         = $iso
			drive_letter = $(if ($info) { $info.drive_letter } else { $drive })
		})
	} catch {
		return "ERROR: UnmountIso failed: $($_.Exception.Message)"
	}
}

function Get-MBMakeCabExe {
	$candidates = @(
		(Join-Path $env:WINDIR 'System32\makecab.exe'),
		(Join-Path $env:WINDIR 'SysWOW64\makecab.exe'),
		'makecab.exe'
	)
	foreach ($c in $candidates) {
		if ($c -eq 'makecab.exe') {
			$cmd = Get-Command makecab.exe -ErrorAction SilentlyContinue
			if ($cmd -and $cmd.Source) { return [string]$cmd.Source }
			continue
		}
		if (Test-Path -LiteralPath $c) { return $c }
	}
	return $null
}

function Get-MBExpandCabExe {
	$candidates = @(
		(Join-Path $env:WINDIR 'System32\expand.exe'),
		(Join-Path $env:WINDIR 'SysWOW64\expand.exe'),
		'expand.exe'
	)
	foreach ($c in $candidates) {
		if ($c -eq 'expand.exe') {
			$cmd = Get-Command expand.exe -ErrorAction SilentlyContinue
			if ($cmd -and $cmd.Source) { return [string]$cmd.Source }
			continue
		}
		if (Test-Path -LiteralPath $c) { return $c }
	}
	return $null
}

function Invoke-MakeCab {
	param(
		[string]$source = '',
		$files = $null,
		[string]$destination = '',
		[bool]$force = $false,
		[bool]$recursive = $false,
		[string]$compression = 'LZX',
		[int]$compression_level = 7,
		[int]$compression_memory = 21
	)
	if ([string]::IsNullOrWhiteSpace($destination)) {
		return "ERROR: destination is required (output .cab path)."
	}
	$dest = Resolve-MBPath $destination
	$destExt = [System.IO.Path]::GetExtension($dest)
	if ($destExt -and $destExt.ToLowerInvariant() -ne '.cab') {
		return "ERROR: destination must end with .cab (got '$destExt')."
	}
	if (-not $destExt) { $dest = "$dest.cab" }

	$makecab = Get-MBMakeCabExe
	if (-not $makecab) {
		return "ERROR: makecab.exe not found (expected under %WINDIR%\\System32)."
	}

	# Collect source files: folder and/or explicit list
	$fileList = New-Object System.Collections.ArrayList
	$addFile = {
		param([string]$fp, [string]$cabName = '')
		if ([string]::IsNullOrWhiteSpace($fp)) { return }
		$full = Resolve-MBPath $fp
		if (-not (Test-Path -LiteralPath $full -PathType Leaf)) {
			throw "File not found: $full"
		}
		$name = if ($cabName) { [System.IO.Path]::GetFileName($cabName) } else { [System.IO.Path]::GetFileName($full) }
		if ([string]::IsNullOrWhiteSpace($name)) { $name = [System.IO.Path]::GetFileName($full) }
		[void]$fileList.Add([pscustomobject]@{ FullName = $full; CabName = $name })
	}

	try {
		foreach ($f in @(Convert-MBForceArray $files)) {
			if ($null -eq $f) { continue }
			if ($f -is [string]) {
				& $addFile ([string]$f) ''
			} else {
				$p = Get-MBProp $f 'path'
				if (-not $p) { $p = Get-MBProp $f 'source' }
				if (-not $p) { $p = Get-MBProp $f 'file' }
				$n = Get-MBProp $f 'name'
				if (-not $n) { $n = Get-MBProp $f 'cab_name' }
				if ($p) { & $addFile ([string]$p) ([string]$n) }
			}
		}
		if (-not [string]::IsNullOrWhiteSpace($source)) {
			$src = Resolve-MBPath $source
			if (-not (Test-Path -LiteralPath $src)) { return "ERROR: source not found: $src" }
			$item = Get-Item -LiteralPath $src -Force -ErrorAction Stop
			if ($item.PSIsContainer) {
				$gci = @{
					LiteralPath = $src
					File        = $true
					Force       = $true
					ErrorAction = 'Stop'
				}
				if ($recursive) { $gci['Recurse'] = $true }
				foreach ($fi in @(Get-ChildItem @gci)) {
					$rel = $fi.Name
					if ($recursive) {
						try {
							$rel = $fi.FullName.Substring($src.TrimEnd('\', '/').Length).TrimStart('\', '/')
							$rel = $rel -replace '/', '\'
						} catch { $rel = $fi.Name }
					}
					# CAB entry names: use flat name unless recursive (then path with backslash -> underscore for safety in simple mode)
					$cabName = if ($recursive -and $rel -match '[\\/]') {
						($rel -replace '[\\/]', '_')
					} else {
						[System.IO.Path]::GetFileName($rel)
					}
					& $addFile $fi.FullName $cabName
				}
			} else {
				& $addFile $item.FullName ''
			}
		}
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}

	if ($fileList.Count -eq 0) {
		return "ERROR: No files to pack. Pass source= folder and/or files=[...]."
	}
	# Deduplicate cab names (keep first)
	$seen = @{}
	$unique = New-Object System.Collections.ArrayList
	foreach ($e in @($fileList)) {
		$key = [string]$e.CabName
		if ($seen.ContainsKey($key.ToLowerInvariant())) {
			$base = [System.IO.Path]::GetFileNameWithoutExtension($key)
			$ext = [System.IO.Path]::GetExtension($key)
			$i = 2
			do {
				$try = "{0}_{1}{2}" -f $base, $i, $ext
				$i++
			} while ($seen.ContainsKey($try.ToLowerInvariant()))
			$e.CabName = $try
			$key = $try
		}
		$seen[$key.ToLowerInvariant()] = $true
		[void]$unique.Add($e)
	}
	$fileList = $unique

	if ((Test-Path -LiteralPath $dest) -and -not $force) {
		return "ERROR: Destination cab exists (set force=true): $dest"
	}
	$parent = Split-Path -Parent $dest
	if ($parent -and -not (Test-Path -LiteralPath $parent)) {
		return "ERROR: Parent directory does not exist: $parent"
	}

	$comp = ([string]$compression).Trim().ToUpperInvariant()
	if ([string]::IsNullOrWhiteSpace($comp)) { $comp = 'LZX' }
	if ($comp -notin @('LZX', 'MSZIP', 'NONE', 'OFF')) {
		return "ERROR: compression must be LZX, MSZIP, or none (got '$compression')."
	}
	if ($compression_level -lt 1) { $compression_level = 1 }
	if ($compression_level -gt 7) { $compression_level = 7 }
	if ($compression_memory -lt 15) { $compression_memory = 15 }
	if ($compression_memory -gt 21) { $compression_memory = 21 }

	$sample = @($fileList | Select-Object -First 8 | ForEach-Object { "  $($_.CabName)  <=  $($_.FullName)" })
	if ($fileList.Count -gt 8) { $sample += "  ... +$($fileList.Count - 8) more" }
	$details = @"
Build cabinet (makecab.exe):

  Output:       $dest
  Files:        $($fileList.Count)
  Compression:  $comp$(if ($comp -eq 'LZX') { " level=$compression_level mem=$compression_memory" } else { '' })
  Force:        $force

$($sample -join "`n")
"@
	if (-not (Request-Confirmation -Title "MakeCab requires approval" -Details $details)) {
		return "BLOCKED BY USER: MakeCab denied by operator."
	}

	$workRoot = $null
	try {
		# Stage in temp: numeric sources 100/101/..., DDF directive file, makecab /F + /D CabinetNameTemplate
		$workRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("MiniBotCab_" + [guid]::NewGuid().ToString('N').Substring(0, 10))
		if (Test-Path -LiteralPath $workRoot) {
			Remove-Item -LiteralPath $workRoot -Recurse -Force -ErrorAction SilentlyContinue
		}
		New-Item -ItemType Directory -Path $workRoot -Force | Out-Null

		# Stage files as progressive ids starting at 100 (makecab SourceDir=. map)
		$id = 100
		$stagedEntries = New-Object System.Collections.ArrayList
		foreach ($e in @($fileList)) {
			$srcId = [string]$id
			$staged = Join-Path $workRoot $srcId
			Copy-Item -LiteralPath $e.FullName -Destination $staged -Force -ErrorAction Stop
			$cabSafe = ([string]$e.CabName) -replace '["\r\n]', '_'
			if ([string]::IsNullOrWhiteSpace($cabSafe)) { $cabSafe = "file$id" }
			[void]$stagedEntries.Add([pscustomobject]@{
				Id       = $id
				SrcId    = $srcId
				CabName  = $cabSafe
				Source   = [string]$e.FullName
			})
			$id++
		}

		# DDF defaults: LZX level 7 / memory 21; Compress ON/OFF via /D on cmdline
		$ddfLines = New-Object System.Collections.Generic.List[string]
		[void]$ddfLines.Add('.new Cabinet')
		[void]$ddfLines.Add('.Set Cabinet=ON')
		[void]$ddfLines.Add('.Set CabinetFileCountThreshold=0')
		[void]$ddfLines.Add('.Set ChecksumWidth=1')
		[void]$ddfLines.Add('.Set ClusterSize=CDROM')
		[void]$ddfLines.Add('.Set LongSourceFileNames=ON')
		if ($comp -eq 'MSZIP') {
			[void]$ddfLines.Add('.Set CompressionType=MSZIP')
		} elseif ($comp -eq 'NONE' -or $comp -eq 'OFF') {
			# Type still set; Compress=OFF on cmdline is what stores uncompressed
			[void]$ddfLines.Add('.Set CompressionType=MSZIP')
		} else {
			[void]$ddfLines.Add('.Set CompressionType=LZX')
			[void]$ddfLines.Add(".Set CompressionLevel=$compression_level")
			[void]$ddfLines.Add(".Set CompressionMemory=$compression_memory")
		}
		[void]$ddfLines.Add('.Set DiskDirectoryTemplate=')
		[void]$ddfLines.Add('.Set FolderFileCountThreshold=0')
		[void]$ddfLines.Add('.Set FolderSizeThreshold=0')
		[void]$ddfLines.Add('.Set GenerateInf=ON')
		[void]$ddfLines.Add('.Set InfFileName=nul')
		[void]$ddfLines.Add('.Set MaxCabinetSize=0')
		[void]$ddfLines.Add('.Set MaxDiskFileCount=0')
		[void]$ddfLines.Add('.Set MaxDiskSize=0')
		[void]$ddfLines.Add('.Set MaxErrors=0')
		[void]$ddfLines.Add('.Set ReservePerCabinetSize=0')
		[void]$ddfLines.Add('.Set ReservePerDataBlockSize=0')
		[void]$ddfLines.Add('.Set ReservePerFolderSize=0')
		[void]$ddfLines.Add('.Set RptFileName=nul')
		[void]$ddfLines.Add('.Set UniqueFiles=ON')
		[void]$ddfLines.Add('.Set SourceDir=.')
		# File map: 100 "name.ext"  (source id unquoted; cabinet name quoted) — built after packing list is final
		foreach ($se in @($stagedEntries)) {
			[void]$ddfLines.Add(('{0} "{1}"' -f $se.SrcId, $se.CabName))
		}

		$ddfPath = Join-Path $workRoot 'offline.config'
		# CRLF: makecab expects directive file with Windows line endings
		$ddfText = ($ddfLines -join "`r`n") + "`r`n"
		[System.IO.File]::WriteAllText($ddfPath, $ddfText, (New-Object System.Text.UTF8Encoding $false))

		# Build into work dir first, then copy to destination (CabinetNameTemplate absolute path)
		$outCab = Join-Path $workRoot 'out.cab'
		if ((Test-Path -LiteralPath $dest) -and $force) {
			Remove-Item -LiteralPath $dest -Force -ErrorAction Stop
		}

		$compressArg = if ($comp -eq 'NONE' -or $comp -eq 'OFF') { 'OFF' } else { 'ON' }
		# makecab /F config /D Compress=... /D CabinetNameTemplate=absPath  (cwd = stage)
		$argLine = '/F "{0}" /D Compress={1} /D CabinetNameTemplate="{2}"' -f $ddfPath, $compressArg, $outCab

		try { Write-MBDownloadProgress -Label 'MakeCab' -Percent 0 -Phase start -Detail ("packing {0} file(s)" -f $stagedEntries.Count) } catch {}

		$psi = New-Object System.Diagnostics.ProcessStartInfo
		$psi.FileName = $makecab
		$psi.Arguments = $argLine
		$psi.WorkingDirectory = $workRoot
		$psi.UseShellExecute = $false
		$psi.RedirectStandardOutput = $true
		$psi.RedirectStandardError = $true
		$psi.CreateNoWindow = $true
		try {
			$utf8 = New-Object System.Text.UTF8Encoding $false
			$psi.StandardOutputEncoding = $utf8
			$psi.StandardErrorEncoding = $utf8
		} catch {}

		$proc = New-Object System.Diagnostics.Process
		$proc.StartInfo = $psi
		$childPid = 0
		$lastPct = -1
		$sw = [System.Diagnostics.Stopwatch]::StartNew()
		$stderrBuf = New-Object System.Text.StringBuilder
		$stdoutBuf = New-Object System.Text.StringBuilder

		# Progress: integer percent from lines like "  12.34% - completing disk..."
		$pctRx = [regex]'(?i)(\d{1,3})(?=\.\d{1,2}\s*%)'

		[void]$proc.Start()
		try {
			$childPid = [int]$proc.Id
			Register-MBChildProcess -ProcessId $childPid
		} catch { $childPid = 0 }

		$errTask = $proc.StandardError.ReadToEndAsync()

		$readLine = {
			param($pr)
			try { return $pr.StandardOutput.ReadLine() } catch { return $null }
		}
		while (-not $proc.HasExited) {
			if (Test-MBInterrupt) {
				try { Stop-MBProcessTree -ProcessId $childPid } catch { try { $proc.Kill() } catch {} }
				try { Write-MBDownloadProgress -Label 'MakeCab' -Percent -1 -Phase fail -Detail 'cancelled' } catch {}
				if ($childPid -gt 0) { try { Unregister-MBChildProcess -ProcessId $childPid } catch {} }
				return "ERROR: MakeCab cancelled by operator."
			}
			$line = & $readLine $proc
			if ($null -ne $line) {
				[void]$stdoutBuf.AppendLine($line)
				$m = $pctRx.Match([string]$line)
				if (-not $m.Success) {
					$m = [regex]::Match([string]$line, '(?i)(\d{1,3})\s*%')
				}
				if ($m.Success) {
					$p = 0
					[void][int]::TryParse($m.Groups[1].Value, [ref]$p)
					if ($p -gt 100) { $p = 100 }
					if ($p -ne $lastPct) {
						$lastPct = $p
						try { Write-MBDownloadProgress -Label 'MakeCab' -Percent $p -Phase update -Detail ([string]$line).Trim() } catch {}
					}
				}
			} else {
				Start-Sleep -Milliseconds 40
			}
			if ($sw.ElapsedMilliseconds -gt 1800000) {
				try { Stop-MBProcessTree -ProcessId $childPid } catch { try { $proc.Kill() } catch {} }
				try { Write-MBDownloadProgress -Label 'MakeCab' -Percent -1 -Phase fail -Detail 'timeout' } catch {}
				if ($childPid -gt 0) { try { Unregister-MBChildProcess -ProcessId $childPid } catch {} }
				return "ERROR: MakeCab timed out after 30 minutes."
			}
		}
		try {
			while ($true) {
				$line = & $readLine $proc
				if ($null -eq $line) { break }
				[void]$stdoutBuf.AppendLine($line)
				$m = $pctRx.Match([string]$line)
				if (-not $m.Success) { $m = [regex]::Match([string]$line, '(?i)(\d{1,3})\s*%') }
				if ($m.Success) {
					$p = 0
					[void][int]::TryParse($m.Groups[1].Value, [ref]$p)
					if ($p -gt 100) { $p = 100 }
					if ($p -ne $lastPct) {
						$lastPct = $p
						try { Write-MBDownloadProgress -Label 'MakeCab' -Percent $p -Phase update } catch {}
					}
				}
			}
		} catch {}
		try { [void]$proc.WaitForExit(2000) } catch {}
		$exitCode = -1
		try { $exitCode = [int]$proc.ExitCode } catch { $exitCode = -1 }
		try {
			if ($errTask.IsCompleted) { [void]$stderrBuf.Append([string]$errTask.Result) }
			else {
				try { [void]$errTask.Wait(1000) } catch {}
				if ($errTask.IsCompleted) { [void]$stderrBuf.Append([string]$errTask.Result) }
			}
		} catch {}
		if ($childPid -gt 0) { try { Unregister-MBChildProcess -ProcessId $childPid } catch {} }
		try { $proc.Dispose() } catch {}

		if (-not (Test-Path -LiteralPath $outCab)) {
			foreach ($alt in @(
				(Join-Path $workRoot '1.cab'),
				(Join-Path $workRoot 'disk1\1.cab'),
				(Join-Path $workRoot 'disk1\out.cab')
			)) {
				if (Test-Path -LiteralPath $alt) { $outCab = $alt; break }
			}
		}
		if (-not (Test-Path -LiteralPath $outCab)) {
			$err = $stderrBuf.ToString()
			if ([string]::IsNullOrWhiteSpace($err)) { $err = $stdoutBuf.ToString() }
			$err = Sanitize-MBProcessOutput -Text $err
			if ($err.Length -gt 600) { $err = $err.Substring($err.Length - 600) }
			try { Write-MBDownloadProgress -Label 'MakeCab' -Percent -1 -Phase fail -Detail 'makecab failed' } catch {}
			return ("ERROR: makecab failed (exit {0}). {1}" -f $exitCode, $err.Trim())
		}
		if ($exitCode -ne 0) {
			$probe = Get-Item -LiteralPath $outCab -ErrorAction SilentlyContinue
			if (-not $probe -or $probe.Length -lt 1) {
				$err = Sanitize-MBProcessOutput -Text ($stderrBuf.ToString() + "`n" + $stdoutBuf.ToString())
				if ($err.Length -gt 400) { $err = $err.Substring($err.Length - 400) }
				return ("ERROR: makecab failed (exit {0}). {1}" -f $exitCode, $err.Trim())
			}
		}

		$fiOut = Get-Item -LiteralPath $outCab -ErrorAction Stop
		if ($fiOut.Length -lt 1) {
			return "ERROR: makecab produced empty cab: $outCab"
		}

		Copy-Item -LiteralPath $outCab -Destination $dest -Force -ErrorAction Stop
		$fi = Get-Item -LiteralPath $dest -ErrorAction Stop
		$sw.Stop()
		try { Write-MBDownloadProgress -Label 'MakeCab' -Percent 100 -Phase done -Detail $dest } catch {}
		$prefix = if ($script:MB.AutoApprove) { 'SUCCESS (auto-approved)' } else { 'SUCCESS' }
		return ConvertTo-MBJson ([ordered]@{
			success            = $true
			message            = ("{0}: CAB created {1}" -f $prefix, $dest)
			destination        = $dest
			bytes              = [int64]$fi.Length
			file_count         = [int]$stagedEntries.Count
			compression        = $comp
			compression_level  = $(if ($comp -eq 'LZX') { $compression_level } else { $null })
			duration_ms        = [int]$sw.ElapsedMilliseconds
			ddf                = 'offline.config'
			files              = @($stagedEntries | Select-Object -First 40 | ForEach-Object {
				[ordered]@{ id = [int]$_.Id; name = $_.CabName; source = $_.Source }
			})
		}) -Depth 6
	} catch {
		try { Write-MBDownloadProgress -Label 'MakeCab' -Percent -1 -Phase fail -Detail $_.Exception.Message } catch {}
		return "ERROR: MakeCab failed: $($_.Exception.Message)"
	} finally {
		if ($workRoot -and (Test-Path -LiteralPath $workRoot)) {
			try { Remove-Item -LiteralPath $workRoot -Recurse -Force -ErrorAction SilentlyContinue } catch {}
		}
	}
}

function Invoke-ExpandCab {
	param(
		[string]$path = '',
		[string]$destination = '',
		[bool]$force = $false
	)
	if ([string]::IsNullOrWhiteSpace($path)) { return "ERROR: path is required (.cab file)." }
	if ([string]::IsNullOrWhiteSpace($destination)) { return "ERROR: destination is required (output folder)." }

	$cab = Resolve-MBPath $path
	$dest = Resolve-MBPath $destination
	if (-not (Test-Path -LiteralPath $cab -PathType Leaf)) {
		return "ERROR: CAB not found: $cab"
	}
	$ext = [System.IO.Path]::GetExtension($cab)
	if ($ext -and $ext.ToLowerInvariant() -ne '.cab') {
		return "ERROR: path should be a .cab file (got '$ext')."
	}

	$expand = Get-MBExpandCabExe
	if (-not $expand) {
		return "ERROR: expand.exe not found (expected under %WINDIR%\\System32)."
	}

	if (Test-Path -LiteralPath $dest) {
		$item = Get-Item -LiteralPath $dest -Force -ErrorAction SilentlyContinue
		if ($item -and -not $item.PSIsContainer) {
			return "ERROR: destination exists and is a file: $dest"
		}
		$kids = @()
		try { $kids = @(Get-ChildItem -LiteralPath $dest -Force -ErrorAction SilentlyContinue) } catch {}
		if ($kids.Count -gt 0 -and -not $force) {
			return "ERROR: destination is not empty (set force=true): $dest"
		}
	}

	$details = "Extract cabinet:`n`n  CAB:  $cab`n  Dest: $dest`n  Force: $force"
	if (-not (Request-Confirmation -Title "ExpandCab requires approval" -Details $details)) {
		return "BLOCKED BY USER: ExpandCab denied by operator."
	}

	try {
		if (-not (Test-Path -LiteralPath $dest)) {
			New-Item -ItemType Directory -Path $dest -Force | Out-Null
		}
		try { Write-MBDownloadProgress -Label 'ExpandCab' -Percent 0 -Phase start -Detail $cab } catch {}
		# expand.exe quoting: trailing '\' inside "..." escapes the close quote on Windows.
		# Use dest without trailing slash, or "dest\." form. Prefer unquoted when no spaces.
		$destArg = $dest.TrimEnd('\', '/')
		$quotePath = {
			param([string]$p)
			if ($p -match '[\s"]') {
				return '"' + ($p -replace '"', '""') + '"'
			}
			return $p
		}
		$cabQ = & $quotePath $cab
		$destQ = & $quotePath $destArg
		$argLine = "-F:* $cabQ $destQ"
		$rr = Invoke-MBProcessCapture -FileName $expand -Arguments $argLine -WorkingDir $destArg -TimeoutMs 600000
		if ($rr.TimedOut) {
			try { Write-MBDownloadProgress -Label 'ExpandCab' -Percent -1 -Phase fail -Detail 'timeout' } catch {}
			return "ERROR: ExpandCab timed out."
		}
		if ($rr.Cancelled) {
			try { Write-MBDownloadProgress -Label 'ExpandCab' -Percent -1 -Phase fail -Detail 'cancelled' } catch {}
			return "ERROR: ExpandCab cancelled."
		}
		if ([int]$rr.ExitCode -ne 0) {
			$err = Sanitize-MBProcessOutput -Text $(if ($rr.StdErr) { $rr.StdErr } else { $rr.StdOut })
			if ($err.Length -gt 400) { $err = $err.Substring($err.Length - 400) }
			try { Write-MBDownloadProgress -Label 'ExpandCab' -Percent -1 -Phase fail -Detail 'expand failed' } catch {}
			return ("ERROR: expand.exe failed (exit {0}). {1}" -f $rr.ExitCode, $err.Trim())
		}
		$entries = @()
		try {
			$entries = @(Get-ChildItem -LiteralPath $dest -Recurse -Force -ErrorAction SilentlyContinue | Select-Object -First 50)
		} catch {}
		try { Write-MBDownloadProgress -Label 'ExpandCab' -Percent 100 -Phase done -Detail $dest } catch {}
		$prefix = if ($script:MB.AutoApprove) { 'SUCCESS (auto-approved)' } else { 'SUCCESS' }
		return ConvertTo-MBJson ([ordered]@{
			success     = $true
			message     = "$prefix`: Extracted $cab -> $dest"
			path        = $cab
			destination = $dest
			sample      = @($entries | ForEach-Object {
				[ordered]@{
					name = $_.Name
					full = $_.FullName
					type = $(if ($_.PSIsContainer) { 'dir' } else { 'file' })
					size = $(if (-not $_.PSIsContainer) { [int64]$_.Length } else { $null })
				}
			})
		}) -Depth 5
	} catch {
		try { Write-MBDownloadProgress -Label 'ExpandCab' -Percent -1 -Phase fail -Detail $_.Exception.Message } catch {}
		return "ERROR: ExpandCab failed: $($_.Exception.Message)"
	}
}

function Invoke-BulkRename {
	param(
		[string]$path,
		[string]$directory = '',
		[string]$glob = '*',
		[bool]$recursive = $false,
		[string]$find = '',
		[string]$replace = '',
		[bool]$use_regex = $false,
		[string]$template = '',
		[int]$start_index = 1,
		[bool]$dry_run = $true,
		[int]$max = 200,
		[bool]$force = $false
	)
	if ([string]::IsNullOrWhiteSpace($path) -and -not [string]::IsNullOrWhiteSpace($directory)) {
		$path = $directory
	}
	if ([string]::IsNullOrWhiteSpace($path)) { return "ERROR: path is required (folder to rename inside)." }

	$root = Resolve-MBPath $path
	if (-not (Test-Path -LiteralPath $root)) { return "ERROR: path not found: $root" }
	if (-not (Test-Path -LiteralPath $root -PathType Container)) {
		return "ERROR: path must be a folder: $root"
	}

	if ($max -le 0) { $max = 200 }
	if ($max -gt 1000) { $max = 1000 }
	if ($start_index -lt 0) { $start_index = 0 }
	if ([string]::IsNullOrWhiteSpace($glob)) { $glob = '*' }

	$hasFind = -not [string]::IsNullOrEmpty($find)
	$hasTemplate = -not [string]::IsNullOrWhiteSpace($template)
	if (-not $hasFind -and -not $hasTemplate) {
		return "ERROR: provide find=+replace= (optional use_regex) or template= (e.g. photo_{n:03}{ext})."
	}
	if ($hasFind -and $hasTemplate) {
		return "ERROR: use either find/replace or template, not both."
	}
	if ($null -eq $replace) { $replace = '' }

	$patterns = @(Convert-MBFindFilePatterns -glob $glob)
	if ($patterns.Count -eq 0) { $patterns = @('*') }

	try {
		$gci = @{
			LiteralPath = $root
			File        = $true
			ErrorAction = 'SilentlyContinue'
			Force       = $true
		}
		if ($recursive) { $gci['Recurse'] = $true }
		$useNativeFilter = ($patterns.Count -eq 1 -and $patterns[0] -ne '*' -and $patterns[0] -notmatch '[\\/]')
		if ($useNativeFilter) { $gci['Filter'] = $patterns[0] }
		$files = @(Get-ChildItem @gci | Sort-Object FullName)
		if (-not $useNativeFilter -or $patterns[0] -eq '*') {
			if ($patterns.Count -gt 1 -or $patterns[0] -ne '*') {
				$files = @($files | Where-Object {
					$n = $_.Name
					$ok = $false
					foreach ($p in $patterns) {
						if ($p -eq '*' -or $n -like $p) { $ok = $true; break }
					}
					$ok
				})
			}
		}
	} catch {
		return "ERROR: failed to list files: $($_.Exception.Message)"
	}

	$totalMatched = $files.Count
	if ($totalMatched -eq 0) {
		return ConvertTo-MBJson @{
			success = $true
			dry_run = $dry_run
			path    = $root
			message = "No files matched glob '$glob' under $root"
			count   = 0
			renames = @()
		}
	}

	$files = @($files | Select-Object -First $max)
	$rx = $null
	if ($hasFind -and $use_regex) {
		try {
			$rx = New-Object System.Text.RegularExpressions.Regex($find, [System.Text.RegularExpressions.RegexOptions]::None)
		} catch {
			return "ERROR: invalid regex in find=: $($_.Exception.Message)"
		}
	}

	$planned = New-Object System.Collections.ArrayList
	$skipped = New-Object System.Collections.ArrayList
	$targetSeen = @{}
	$idx = $start_index

	foreach ($f in $files) {
		$oldName = [string]$f.Name
		$stem = [System.IO.Path]::GetFileNameWithoutExtension($oldName)
		$ext = [System.IO.Path]::GetExtension($oldName)
		$parentName = ''
		try { $parentName = [System.IO.Path]::GetFileName([System.IO.Path]::GetDirectoryName($f.FullName)) } catch { $parentName = '' }
		$newName = $null

		if ($hasTemplate) {
			$newName = [string]$template
			# padded counters first: {n:00} {n:000}
			while ($newName -match '\{n:(\d+)\}') {
				$w = 1
				try { $w = [int]$Matches[1] } catch { $w = 1 }
				if ($w -lt 1) { $w = 1 }
				if ($w -gt 12) { $w = 12 }
				$pad = $idx.ToString().PadLeft($w, '0')
				$tok = [string]$Matches[0]
				$at = $newName.IndexOf($tok)
				if ($at -lt 0) { break }
				$newName = $newName.Remove($at, $tok.Length).Insert($at, $pad)
			}
			$newName = $newName.Replace('{n}', "$idx")
			$newName = $newName.Replace('{name}', $oldName)
			$newName = $newName.Replace('{stem}', $stem)
			$newName = $newName.Replace('{base}', $stem)
			$newName = $newName.Replace('{ext}', $ext)
			$newName = $newName.Replace('{parent}', $parentName)
			$idx++
		} else {
			if ($use_regex -and $null -ne $rx) {
				if (-not $rx.IsMatch($oldName)) {
					[void]$skipped.Add([ordered]@{ from = $oldName; reason = 'no_regex_match' })
					continue
				}
				$newName = $rx.Replace($oldName, [string]$replace)
			} else {
				if ($oldName.IndexOf([string]$find, [System.StringComparison]::Ordinal) -lt 0) {
					[void]$skipped.Add([ordered]@{ from = $oldName; reason = 'no_substring_match' })
					continue
				}
				$newName = $oldName.Replace([string]$find, [string]$replace)
			}
		}

		if ([string]::IsNullOrWhiteSpace($newName)) {
			[void]$skipped.Add([ordered]@{ from = $oldName; reason = 'empty_new_name' })
			continue
		}
		# strip path separators / illegal name chars
		$newName = $newName -replace '[\\/:\*\?"<>\|]', '_'
		$newName = $newName.Trim().TrimEnd('.')
		if ([string]::IsNullOrWhiteSpace($newName)) {
			[void]$skipped.Add([ordered]@{ from = $oldName; reason = 'empty_after_sanitize' })
			continue
		}
		if ($newName -eq $oldName) {
			[void]$skipped.Add([ordered]@{ from = $oldName; reason = 'unchanged' })
			continue
		}

		$dir = [System.IO.Path]::GetDirectoryName($f.FullName)
		$dest = Join-Path $dir $newName
		$key = $dest.ToLowerInvariant()
		$conflict = $false
		$conflictReason = ''
		if ($targetSeen.ContainsKey($key)) {
			$conflict = $true
			$conflictReason = 'duplicate_target_in_batch'
		} elseif ((Test-Path -LiteralPath $dest) -and -not $force) {
			$conflict = $true
			$conflictReason = 'target_exists'
		}
		$targetSeen[$key] = $true

		$row = [ordered]@{
			from = $f.FullName
			to   = $dest
			from_name = $oldName
			to_name   = $newName
		}
		if ($conflict) {
			$row['conflict'] = $true
			$row['reason'] = $conflictReason
			[void]$skipped.Add($row)
			continue
		}
		[void]$planned.Add($row)
	}

	$preview = @($planned | Select-Object -First 40)
	$payload = [ordered]@{
		success       = $true
		dry_run       = $dry_run
		path          = $root
		glob          = $(if ($patterns.Count -eq 1) { $patterns[0] } else { ($patterns -join ';') })
		recursive     = $recursive
		matched       = $totalMatched
		capped        = ($totalMatched -gt $files.Count)
		planned_count = $planned.Count
		skipped_count = $skipped.Count
		renames       = $preview
		skipped_sample = @($skipped | Select-Object -First 20)
	}
	if ($hasTemplate) {
		$payload['mode'] = 'template'
		$payload['template'] = $template
		$payload['start_index'] = $start_index
	} else {
		$payload['mode'] = $(if ($use_regex) { 'regex' } else { 'substring' })
		$payload['find'] = $find
		$payload['replace'] = $replace
	}

	if ($planned.Count -eq 0) {
		$payload['message'] = "No renames to apply (matched=$totalMatched, skipped=$($skipped.Count))."
		return ConvertTo-MBJson $payload -Depth 6
	}

	if ($dry_run) {
		$payload['message'] = "DRY RUN: $($planned.Count) rename(s) planned (showing up to 40). Re-call with dry_run=false to apply (will prompt)."
		$payload['hint'] = 'Review renames[]. Set dry_run=false to apply after operator approval.'
		return ConvertTo-MBJson $payload -Depth 6
	}

	# Apply: approval required
	$sampleLines = @($planned | Select-Object -First 12 | ForEach-Object { "  $($_.from_name)  ->  $($_.to_name)" })
	$more = if ($planned.Count -gt 12) { "`n  ... +$($planned.Count - 12) more" } else { '' }
	$details = "Bulk rename $($planned.Count) file(s) under:`n  $root`n`n" + ($sampleLines -join "`n") + $more + "`n`nforce=$force"
	if (-not (Request-Confirmation -Title "BulkRename requires approval" -Details $details)) {
		return "BLOCKED BY USER: BulkRename denied by operator."
	}

	$ok = 0
	$fail = New-Object System.Collections.ArrayList
	$done = New-Object System.Collections.ArrayList
	foreach ($r in $planned) {
		try {
			if ((Test-Path -LiteralPath $r.to) -and $force) {
				Remove-Item -LiteralPath $r.to -Force -ErrorAction Stop
			}
			Rename-Item -LiteralPath $r.from -NewName $r.to_name -ErrorAction Stop
			$ok++
			if ($done.Count -lt 40) {
				[void]$done.Add([ordered]@{ from = $r.from; to = $r.to; from_name = $r.from_name; to_name = $r.to_name })
			}
		} catch {
			[void]$fail.Add([ordered]@{ from = $r.from; to = $r.to; error = $_.Exception.Message })
		}
	}

	$prefix = if ($script:MB.AutoApprove) { "SUCCESS (auto-approved)" } else { "SUCCESS" }
	return ConvertTo-MBJson ([ordered]@{
		success       = ($fail.Count -eq 0)
		dry_run       = $false
		message       = "$prefix`: renamed $ok / $($planned.Count) file(s); failed=$($fail.Count)"
		path          = $root
		renamed_count = $ok
		failed_count  = $fail.Count
		renames       = @($done)
		failures      = @($fail | Select-Object -First 20)
		skipped_count = $skipped.Count
	}) -Depth 6
}

function Invoke-FindDuplicates {
	param(
		[string]$path,
		[string]$directory = '',
		[bool]$recursive = $true,
		[string]$glob = '*',
		[long]$min_bytes = 1,
		[int]$max_scan = 10000,
		[int]$max_groups = 40,
		[int]$max_per_group = 12
	)
	if ([string]::IsNullOrWhiteSpace($path) -and -not [string]::IsNullOrWhiteSpace($directory)) {
		$path = $directory
	}
	if ([string]::IsNullOrWhiteSpace($path)) { return "ERROR: path is required." }

	$root = Resolve-MBPath $path
	if (-not (Test-Path -LiteralPath $root)) { return "ERROR: path not found: $root" }
	if (-not (Test-Path -LiteralPath $root -PathType Container)) {
		return "ERROR: path must be a folder: $root"
	}

	if ($min_bytes -lt 0) { $min_bytes = 0 }
	if ($max_scan -le 0) { $max_scan = 10000 }
	if ($max_scan -gt 50000) { $max_scan = 50000 }
	if ($max_groups -le 0) { $max_groups = 40 }
	if ($max_groups -gt 200) { $max_groups = 200 }
	if ($max_per_group -le 0) { $max_per_group = 12 }
	if ($max_per_group -gt 50) { $max_per_group = 50 }
	if ([string]::IsNullOrWhiteSpace($glob)) { $glob = '*' }

	$patterns = @(Convert-MBFindFilePatterns -glob $glob)
	if ($patterns.Count -eq 0) { $patterns = @('*') }

	try {
		$gci = @{
			LiteralPath = $root
			File        = $true
			ErrorAction = 'SilentlyContinue'
			Force       = $true
		}
		if ($recursive) { $gci['Recurse'] = $true }
		$useNativeFilter = ($patterns.Count -eq 1 -and $patterns[0] -ne '*' -and $patterns[0] -notmatch '[\\/]')
		if ($useNativeFilter) { $gci['Filter'] = $patterns[0] }
		# Stream-ish: take max_scan+1 to know truncation
		$all = @(Get-ChildItem @gci | Select-Object -First ($max_scan + 1))
		$truncated = ($all.Count -gt $max_scan)
		if ($truncated) { $all = @($all | Select-Object -First $max_scan) }
		if (-not $useNativeFilter -or ($patterns.Count -gt 1) -or ($patterns[0] -ne '*' -and -not $useNativeFilter)) {
			if (-not $useNativeFilter) {
				$all = @($all | Where-Object {
					$n = $_.Name
					$ok = $false
					foreach ($p in $patterns) {
						if ($p -eq '*' -or $n -like $p) { $ok = $true; break }
					}
					$ok
				})
			}
		}
		if ($min_bytes -gt 0) {
			$all = @($all | Where-Object { [int64]$_.Length -ge $min_bytes })
		}
	} catch {
		return "ERROR: scan failed: $($_.Exception.Message)"
	}

	$scanned = $all.Count
	if ($scanned -eq 0) {
		return ConvertTo-MBJson @{
			success = $true
			path    = $root
			message = "No files to scan under $root"
			scanned = 0
			groups  = @()
			duplicate_groups = 0
		}
	}

	# Group by size
	$bySize = @{}
	foreach ($f in $all) {
		$sz = [int64]$f.Length
		if (-not $bySize.ContainsKey($sz)) {
			$bySize[$sz] = New-Object System.Collections.ArrayList
		}
		[void]$bySize[$sz].Add($f)
	}

	$candidateFiles = New-Object System.Collections.ArrayList
	$sizeBuckets = 0
	foreach ($sz in @($bySize.Keys)) {
		$bucket = $bySize[$sz]
		if ($bucket.Count -gt 1) {
			$sizeBuckets++
			foreach ($f in $bucket) { [void]$candidateFiles.Add($f) }
		}
	}

	# Hash candidates
	$hashMap = @{}
	$hashErrors = 0
	foreach ($f in $candidateFiles) {
		try {
			$h = Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256 -ErrorAction Stop
			$hex = [string]$h.Hash
			if (-not $hashMap.ContainsKey($hex)) {
				$hashMap[$hex] = New-Object System.Collections.ArrayList
			}
			[void]$hashMap[$hex].Add([ordered]@{
				path  = $f.FullName
				name  = $f.Name
				bytes = [int64]$f.Length
			})
		} catch {
			$hashErrors++
		}
	}

	$groups = New-Object System.Collections.ArrayList
	$dupFileCount = 0
	$wasted = [int64]0
	foreach ($hex in @($hashMap.Keys | Sort-Object)) {
		$items = $hashMap[$hex]
		if ($items.Count -lt 2) { continue }
		$bytes = [int64]$items[0].bytes
		$extra = $items.Count - 1
		$dupFileCount += $items.Count
		$wasted += ($bytes * $extra)
		$shown = @($items | Select-Object -First $max_per_group)
		[void]$groups.Add([ordered]@{
			hash       = $hex
			bytes      = $bytes
			count      = $items.Count
			paths      = @($shown | ForEach-Object { $_.path })
			files      = $shown
			truncated  = ($items.Count -gt $max_per_group)
			wasted_bytes = ($bytes * $extra)
		})
	}

	# Largest waste first
	$groups = @($groups | Sort-Object { -$_.wasted_bytes }, { -$_.count })
	$totalGroups = $groups.Count
	$groupsOut = @($groups | Select-Object -First $max_groups)

	return ConvertTo-MBJson ([ordered]@{
		success           = $true
		path              = $root
		recursive         = $recursive
		glob              = $(if ($patterns.Count -eq 1) { $patterns[0] } else { ($patterns -join ';') })
		min_bytes         = $min_bytes
		scanned           = $scanned
		scan_truncated    = $truncated
		size_buckets      = $sizeBuckets
		hashed            = $candidateFiles.Count
		hash_errors       = $hashErrors
		duplicate_groups  = $totalGroups
		groups_returned   = $groupsOut.Count
		duplicate_files   = $dupFileCount
		wasted_bytes      = $wasted
		groups            = $groupsOut
		message           = $(if ($totalGroups -eq 0) {
			"No content duplicates found among $scanned file(s) (size-prefilter then SHA256)."
		} else {
			"Found $totalGroups duplicate group(s); ~$wasted wasted bytes (keeping one copy per group)."
		})
		hint = $(if ($truncated) {
			"Scan capped at max_scan=$max_scan. Narrow path/glob or raise max_scan to cover more."
		} elseif ($totalGroups -gt $groupsOut.Count) {
			"Returning top $max_groups groups by wasted space. Raise max_groups for more."
		} else { $null })
	}) -Depth 6
}


function Invoke-MBPSGalleryOp {
	# Isolate Find/Install/Update-Module in a child powershell.exe with timeout + Esc kill.
	param(
		[ValidateSet('Find','Install','Update')]
		[string]$Op,
		[string]$Name,
		[string]$Version = '',
		[string]$Scope = 'CurrentUser',
		[bool]$AllowPrerelease = $false,
		[int]$MaxResults = 15,
		[int]$TimeoutSec = 0
	)
	if ([string]::IsNullOrWhiteSpace($Name)) {
		return @{ Ok = $false; Error = 'name is required'; TimedOut = $false; Cancelled = $false; ExitCode = -1; StdOut = ''; StdErr = '' }
	}
	if ($TimeoutSec -le 0) {
		$TimeoutSec = switch ($Op) {
			'Find' { 60 }
			'Install' { 180 }
			'Update' { 180 }
			default { 120 }
		}
	}
	if ($TimeoutSec -lt 15) { $TimeoutSec = 15 }
	if ($TimeoutSec -gt 600) { $TimeoutSec = 600 }

	$nameEsc = $Name.Replace("'", "''")
	$verEsc = ([string]$Version).Replace("'", "''")
	$scopeEsc = ([string]$Scope).Replace("'", "''")
	$maxR = [int]$MaxResults
	if ($maxR -le 0) { $maxR = 15 }
	if ($maxR -gt 50) { $maxR = 50 }
	$pre = if ($AllowPrerelease) { '$true' } else { '$false' }

	# Child script on disk: NonInteractive Gallery ops (NuGet bootstrap, PSGallery trust, Force/Confirm:$false)
	$child = @"
`$ErrorActionPreference = 'Stop'
`$ProgressPreference = 'SilentlyContinue'
`$ConfirmPreference = 'None'
`$WhatIfPreference = `$false
try { `$PSDefaultParameterValues = @{
	'*:Confirm' = `$false
	'*:Force' = `$true
	'Install-Module:Confirm' = `$false
	'Install-Module:Force' = `$true
	'Update-Module:Confirm' = `$false
	'Update-Module:Force' = `$true
	'Find-Module:Repository' = 'PSGallery'
	'Install-Module:Repository' = 'PSGallery'
	'Install-PackageProvider:Confirm' = `$false
	'Install-PackageProvider:Force' = `$true
	'Set-PSRepository:InstallationPolicy' = 'Trusted'
} } catch {}
try {
	`$proto = [System.Net.SecurityProtocolType]::Tls12
	try { `$proto = `$proto -bor [System.Net.SecurityProtocolType]::Tls13 } catch {}
	[System.Net.ServicePointManager]::SecurityProtocol = `$proto
} catch {}
try { [Net.ServicePointManager]::Expect100Continue = `$false } catch {}

function Initialize-MBGalleryNonInteractive {
	try {
		`$needNuGet = `$true
		`$nug = @(Get-PackageProvider -Name NuGet -ListAvailable -ErrorAction SilentlyContinue |
			Sort-Object { [version]`$_.Version } -Descending)
		if (`$nug.Count -gt 0) {
			try {
				if ([version]`$nug[0].Version -ge [version]'2.8.5.201') { `$needNuGet = `$false }
			} catch { `$needNuGet = `$false }
		}
		if (`$needNuGet) {
			try {
				Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force -Confirm:`$false -Scope CurrentUser -ErrorAction Stop | Out-Null
			} catch {
				try { Install-PackageProvider -Name NuGet -Force -Confirm:`$false -ErrorAction Stop | Out-Null } catch {}
			}
		}
	} catch {}
	try { Import-Module PackageManagement -ErrorAction SilentlyContinue | Out-Null } catch {}
	try { Import-Module PowerShellGet -ErrorAction SilentlyContinue | Out-Null } catch {}
	try {
		`$repo = Get-PSRepository -Name PSGallery -ErrorAction SilentlyContinue
		if (-not `$repo) {
			try { Register-PSRepository -Default -ErrorAction SilentlyContinue } catch {}
			try {
				if (-not (Get-PSRepository -Name PSGallery -ErrorAction SilentlyContinue)) {
					Register-PSRepository -Name PSGallery -SourceLocation 'https://www.powershellgallery.com/api/v2' -InstallationPolicy Trusted -ErrorAction SilentlyContinue
				}
			} catch {}
		}
		Set-PSRepository -Name PSGallery -InstallationPolicy Trusted -ErrorAction SilentlyContinue
	} catch {}
	try {
		if (Get-Command Set-PackageSource -ErrorAction SilentlyContinue) {
			Set-PackageSource -Name PSGallery -Trusted -Force -ErrorAction SilentlyContinue | Out-Null
		}
	} catch {}
}
Initialize-MBGalleryNonInteractive

`$name = '$nameEsc'
`$op = '$Op'
try {
	switch (`$op) {
		'Find' {
			if (-not (Get-Command Find-Module -ErrorAction SilentlyContinue)) { throw 'Find-Module not available (install PowerShellGet).' }
			`$fp = @{
				Name = `$name
				Repository = 'PSGallery'
				ErrorAction = 'Stop'
			}
			`$fm = Get-Command Find-Module -ErrorAction SilentlyContinue
			if (`$fm -and `$fm.Parameters.ContainsKey('AllowPrerelease') -and $pre) { `$fp['AllowPrerelease'] = `$true }
			if (`$fm -and `$fm.Parameters.ContainsKey('Force')) { `$fp['Force'] = `$true }
			if (`$fm -and `$fm.Parameters.ContainsKey('Confirm')) { `$fp['Confirm'] = `$false }
			`$mods = @(Find-Module @fp | Select-Object -First $maxR)
			`$rows = @(`$mods | ForEach-Object {
				[ordered]@{
					Name = `$_.Name
					Version = [string]`$_.Version
					Author = [string]`$_.Author
					Description = `$(if (`$_.Description) { ([string]`$_.Description).Substring(0, [math]::Min(200, ([string]`$_.Description).Length)) } else { '' })
					Repository = [string]`$_.Repository
				}
			})
			@{ success = `$true; count = `$rows.Count; query = `$name; modules = `$rows; gallery = 'PSGallery'; trusted = `$true } | ConvertTo-Json -Compress -Depth 6
		}
		'Install' {
			if (-not (Get-Command Install-Module -ErrorAction SilentlyContinue)) { throw 'Install-Module not available (install PowerShellGet).' }
			`$ip = @{
				Name = `$name
				Scope = '$scopeEsc'
				Force = `$true
				AllowClobber = `$true
				Confirm = `$false
				ErrorAction = 'Stop'
				Repository = 'PSGallery'
			}
			if ('$verEsc') { `$ip['RequiredVersion'] = '$verEsc' }
			`$imCmd = Get-Command Install-Module -ErrorAction SilentlyContinue
			if (`$imCmd -and `$imCmd.Parameters.ContainsKey('AcceptLicense')) { `$ip['AcceptLicense'] = `$true }
			if ($pre -and `$imCmd -and `$imCmd.Parameters.ContainsKey('AllowPrerelease')) { `$ip['AllowPrerelease'] = `$true }
			if (`$imCmd -and `$imCmd.Parameters.ContainsKey('SkipPublisherCheck')) { `$ip['SkipPublisherCheck'] = `$true }
			Install-Module @ip
			`$installed = @(Get-Module -ListAvailable -Name `$name -ErrorAction SilentlyContinue | Sort-Object Version -Descending | Select-Object -First 3)
			@{
				success = `$true
				name = `$name
				scope = '$scopeEsc'
				modules = @(`$installed | ForEach-Object { [ordered]@{ Name = `$_.Name; Version = [string]`$_.Version; ModuleBase = [string]`$_.ModuleBase } })
			} | ConvertTo-Json -Compress -Depth 6
		}
		'Update' {
			if (-not (Get-Command Update-Module -ErrorAction SilentlyContinue)) { throw 'Update-Module not available (install PowerShellGet).' }
			`$before = @(Get-Module -ListAvailable -Name `$name -ErrorAction SilentlyContinue | Sort-Object Version -Descending | Select-Object -First 1)
			if (`$before.Count -eq 0) { throw "Module '`$name' is not installed." }
			`$up = @{
				Name = `$name
				Force = `$true
				Confirm = `$false
				ErrorAction = 'Stop'
			}
			`$umCmd = Get-Command Update-Module -ErrorAction SilentlyContinue
			if (`$umCmd -and `$umCmd.Parameters.ContainsKey('AcceptLicense')) { `$up['AcceptLicense'] = `$true }
			`$scopeVal = '$scopeEsc'
			if (`$scopeVal -and `$umCmd -and `$umCmd.Parameters.ContainsKey('Scope')) {
				try { Update-Module @up -Scope `$scopeVal }
				catch { Update-Module @up }
			} else {
				Update-Module @up
			}
			`$after = @(Get-Module -ListAvailable -Name `$name -ErrorAction SilentlyContinue | Sort-Object Version -Descending | Select-Object -First 3)
			@{
				success = `$true
				name = `$name
				before = `$(if (`$before[0]) { [string]`$before[0].Version } else { `$null })
				modules = @(`$after | ForEach-Object { [ordered]@{ Name = `$_.Name; Version = [string]`$_.Version; ModuleBase = [string]`$_.ModuleBase } })
			} | ConvertTo-Json -Compress -Depth 6
		}
	}
} catch {
	`$errMsg = `$_.Exception.Message
	if ([string]::IsNullOrWhiteSpace(`$errMsg)) { `$errMsg = 'operation failed' }
	if (`$errMsg -match '(?i)NuGet|package provider|untrusted|confirmation|interactive|prompt|PSGallery') {
		`$errMsg = (`$errMsg.Trim() + ' [hint: NuGet bootstrap / PSGallery trust / -Force -Confirm:`$false]')
	}
	if (`$errMsg.Length -gt 300) { `$errMsg = `$errMsg.Substring(0, 297) + '...' }
	@{ success = `$false; error = `$errMsg } | ConvertTo-Json -Compress
	exit 2
}
"@

	$scriptPath = $null
	$out = @{
		Ok = $false
		TimedOut = $false
		Cancelled = $false
		ExitCode = -1
		StdOut = ''
		StdErr = ''
		Error = ''
		Payload = $null
		Isolation = 'file'
	}
	try {
		$scriptPath = Join-Path ([System.IO.Path]::GetTempPath()) ("MiniBotGallery_" + [guid]::NewGuid().ToString('N').Substring(0, 12) + '.ps1')
		# UTF-8 with BOM for PS 5.1 -File
		$utf8Bom = New-Object System.Text.UTF8Encoding $true
		[System.IO.File]::WriteAllText($scriptPath, $child, $utf8Bom)

		$psExe = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
		if (-not (Test-Path -LiteralPath $psExe)) { $psExe = 'powershell.exe' }
		$timeoutMs = [int]($TimeoutSec * 1000)
		$argLine = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "' + $scriptPath + '"'
		$rr = Invoke-MBProcessCapture -FileName $psExe -Arguments $argLine -TimeoutMs $timeoutMs
		$out.TimedOut = [bool]$rr.TimedOut
		$out.Cancelled = [bool]$rr.Cancelled
		$out.ExitCode = [int]$rr.ExitCode
		$out.StdOut = [string]$rr.StdOut
		$out.StdErr = [string]$rr.StdErr
	} catch {
		$out.Error = "Gallery child launch failed: $($_.Exception.Message)"
		return $out
	} finally {
		if ($scriptPath -and (Test-Path -LiteralPath $scriptPath)) {
			try { Remove-Item -LiteralPath $scriptPath -Force -ErrorAction SilentlyContinue } catch {}
		}
	}

	if ($out.Cancelled) {
		$out.Error = "$Op module operation cancelled by user (Esc/Stop)."
		return $out
	}
	if ($out.TimedOut) {
		$out.Error = "$Op-Module timed out after ${TimeoutSec}s (PowerShell Gallery / NuGet may be slow or stuck)."
		return $out
	}
	$stderr = Sanitize-MBProcessOutput -Text $out.StdErr
	$stdout = Sanitize-MBProcessOutput -Text $out.StdOut
	$jsonText = ''
	try {
		$blob = if (-not [string]::IsNullOrWhiteSpace($stdout)) { $stdout } else { $stderr }
		if ($blob -match '(\{[\s\S]*\})\s*$') { $jsonText = $Matches[1] }
	} catch {}
	if ($out.ExitCode -ne 0) {
		if ($jsonText) {
			try {
				$j = $jsonText | ConvertFrom-Json -ErrorAction Stop
				$em = ''
				try { $em = [string]$j.error } catch {}
				if (-not $em) { try { $em = [string]$j.message } catch {} }
				if ($em) { $out.Error = $em; return $out }
			} catch {}
		}
		$msg = $stderr
		if ([string]::IsNullOrWhiteSpace($msg)) { $msg = $stdout }
		if ([string]::IsNullOrWhiteSpace($msg)) { $msg = "exit code $($out.ExitCode)" }
		if ($msg.Length -gt 400) { $msg = $msg.Substring(0, 397) + '...' }
		$out.Error = $msg
		return $out
	}
	if ([string]::IsNullOrWhiteSpace($stdout)) {
		$out.Error = "$Op-Module produced no output."
		return $out
	}
	try {
		if (-not $jsonText -and $stdout -match '(\{[\s\S]*\})\s*$') { $jsonText = $Matches[1] }
		if (-not $jsonText) { $jsonText = $stdout }
		$out.Payload = $jsonText | ConvertFrom-Json -ErrorAction Stop
		try {
			if ($null -ne $out.Payload.success -and -not [bool]$out.Payload.success) {
				$em = [string]$out.Payload.error
				if (-not $em) { $em = "$Op failed" }
				$out.Error = $em
				$out.Ok = $false
				return $out
			}
		} catch {}
		$out.Ok = $true
	} catch {
		$out.Error = "could not parse $Op-Module result"
	}
	return $out
}

function Invoke-FindPSModule {
	param(
		[string]$name,
		[int]$max_results = 15,
		[int]$timeout_sec = 60
	)
	if ([string]::IsNullOrWhiteSpace($name)) { return (Format-MBShortToolError -ErrorText 'name is required') }
	if ($max_results -le 0) { $max_results = 15 }
	if ($max_results -gt 50) { $max_results = 50 }
	if ($timeout_sec -le 0) { $timeout_sec = 60 }

	$r = Invoke-MBPSGalleryOp -Op Find -Name $name -MaxResults $max_results -TimeoutSec $timeout_sec
	if (-not $r.Ok) {
		$err = if ($r.Error) { [string]$r.Error } else { "Find-Module failed (exit $($r.ExitCode))" }
		# Prefer short message; never dump full child runner / CLIXML
		$short = Sanitize-MBProcessOutput -Text $err
		if ([string]::IsNullOrWhiteSpace($short) -and $r.StdErr) {
			$short = Sanitize-MBProcessOutput -Text $r.StdErr
		}
		return (Format-MBShortToolError -ErrorText $short -Fallback 'Find-Module failed')
	}
	try {
		$payload = $r.Payload
		return ConvertTo-MBJson @{
			success = $true
			count   = [int]$payload.count
			query   = [string]$payload.query
			modules = @($payload.modules)
			note    = 'Find-Module in child process (timeout; Esc aborts).'
		} -Depth 6
	} catch {
		return (Format-MBShortToolError -ErrorText $_.Exception.Message -Fallback 'Find-Module parse failed')
	}
}

function Invoke-GetInstalledPSModule {
	param([string]$name)
	try {
		$gciParams = @{ ListAvailable = $true; ErrorAction = 'Stop' }
		if (-not [string]::IsNullOrWhiteSpace($name)) {
			$gciParams['Name'] = $name
		}
		$mods = @(Get-Module @gciParams | Sort-Object Name, Version -Descending)
		$seen = @{}
		$rows = New-Object System.Collections.ArrayList
		foreach ($m in $mods) {
			if ($seen.ContainsKey($m.Name)) { continue }
			$seen[$m.Name] = $true
			[void]$rows.Add([ordered]@{
				Name        = $m.Name
				Version     = [string]$m.Version
				ModuleBase  = [string]$m.ModuleBase
				Author      = [string]$m.Author
				Description = $(if ($m.Description) {
					$d = [string]$m.Description
					if ($d.Length -gt 160) { $d.Substring(0, 160) + '...' } else { $d }
				} else { '' })
			})
			if ($rows.Count -ge 80) { break }
		}
		return ConvertTo-MBJson @{
			success = $true
			count   = $rows.Count
			filter  = $(if ($name) { $name } else { $null })
			modules = @($rows)
		} -Depth 5
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

function Invoke-InstallPSModule {
	param(
		[string]$name,
		[string]$version,
		[string]$scope = 'CurrentUser',
		[bool]$allow_prerelease = $false,
		[int]$timeout_sec = 180
	)
	if ([string]::IsNullOrWhiteSpace($name)) { return (Format-MBShortToolError -ErrorText 'name is required') }
	if (-not (Get-Command Install-Module -ErrorAction SilentlyContinue)) {
		return (Format-MBShortToolError -ErrorText 'Install-Module not available. Install PowerShellGet first.')
	}

	$scopeNorm = if ([string]::IsNullOrWhiteSpace($scope)) { 'CurrentUser' } else { $scope.Trim() }
	if ($scopeNorm -notin @('CurrentUser','AllUsers')) {
		return (Format-MBShortToolError -ErrorText 'scope must be CurrentUser or AllUsers')
	}
	if ($scopeNorm -eq 'AllUsers') {
		$isAdmin = $false
		try {
			$wi = [Security.Principal.WindowsIdentity]::GetCurrent()
			$wp = New-Object Security.Principal.WindowsPrincipal($wi)
			$isAdmin = $wp.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
		} catch {}
		if (-not $isAdmin) {
			return (Format-MBShortToolError -ErrorText 'AllUsers scope requires an elevated (Administrator) PowerShell session')
		}
	}
	if ($timeout_sec -le 0) { $timeout_sec = 180 }

	$details = "Install PowerShell module from PSGallery:`n`n  Name:    $name`n  Scope:   $scopeNorm`n  Timeout: ${timeout_sec}s (Esc/Stop aborts)"
	if ($version) { $details += "`n  Version: $version" }
	if ($allow_prerelease) { $details += "`n  Prerelease: yes" }
	$details += "`n`nRuns Install-Module in a child process so Gallery/NuGet hangs cannot freeze MiniBot."
	if (-not (Request-Confirmation -Title "InstallPSModule requires approval" -Details $details)) {
		return (Format-MBShortToolError -ErrorText 'Module install denied by operator' -Fallback 'denied')
	}

	$r = Invoke-MBPSGalleryOp -Op Install -Name $name -Version $version -Scope $scopeNorm -AllowPrerelease $allow_prerelease -TimeoutSec $timeout_sec
	if (-not $r.Ok) {
		$err = if ($r.Error) { [string]$r.Error } elseif ($r.StdErr) { [string]$r.StdErr } else { "Install-Module failed (exit $($r.ExitCode))" }
		return (Format-MBShortToolError -ErrorText $err -Fallback 'Install-Module failed')
	}
	try {
		$payload = $r.Payload
		$prefix = if ($script:MB.AutoApprove) { "SUCCESS (auto-approved)" } else { "SUCCESS" }
		return ConvertTo-MBJson @{
			success  = $true
			message  = "$prefix`: Install-Module $name (scope=$scopeNorm)"
			name     = $name
			scope    = $scopeNorm
			modules  = @($payload.modules)
		} -Depth 5
	} catch {
		return (Format-MBShortToolError -ErrorText $_.Exception.Message -Fallback 'Install-Module parse failed')
	}
}

function Invoke-UpdatePSModule {
	param(
		[string]$name,
		[string]$scope,
		[int]$timeout_sec = 180
	)
	if ([string]::IsNullOrWhiteSpace($name)) { return (Format-MBShortToolError -ErrorText 'name is required') }
	if (-not (Get-Command Update-Module -ErrorAction SilentlyContinue)) {
		return (Format-MBShortToolError -ErrorText 'Update-Module not available. Install PowerShellGet first.')
	}

	$before = @(Get-Module -ListAvailable -Name $name -ErrorAction SilentlyContinue |
		Sort-Object Version -Descending | Select-Object -First 1)
	if ($before.Count -eq 0) {
		return (Format-MBShortToolError -ErrorText "Module '$name' is not installed. Use InstallPSModule first.")
	}
	if ($timeout_sec -le 0) { $timeout_sec = 180 }

	$details = "Update installed PowerShell module:`n`n  Name: $name`n  Current: $([string]$before[0].Version)`n  Timeout: ${timeout_sec}s (Esc/Stop aborts)"
	if ($scope) { $details += "`n  Scope: $scope" }
	$details += "`n`nRuns Update-Module in a child process so Gallery/NuGet hangs cannot freeze MiniBot."
	if (-not (Request-Confirmation -Title "UpdatePSModule requires approval" -Details $details)) {
		return (Format-MBShortToolError -ErrorText 'Module update denied by operator' -Fallback 'denied')
	}

	$scopeArg = if ($scope) { $scope.Trim() } else { '' }
	$r = Invoke-MBPSGalleryOp -Op Update -Name $name -Scope $scopeArg -TimeoutSec $timeout_sec
	if (-not $r.Ok) {
		$err = if ($r.Error) { [string]$r.Error } elseif ($r.StdErr) { [string]$r.StdErr } else { "Update-Module failed (exit $($r.ExitCode))" }
		return (Format-MBShortToolError -ErrorText $err -Fallback 'Update-Module failed')
	}
	try {
		$payload = $r.Payload
		$prefix = if ($script:MB.AutoApprove) { "SUCCESS (auto-approved)" } else { "SUCCESS" }
		return ConvertTo-MBJson @{
			success = $true
			message = "$prefix`: Update-Module $name"
			name    = $name
			before  = $(if ($before[0]) { [string]$before[0].Version } else { $null })
			modules = @($payload.modules)
		} -Depth 5
	} catch {
		return (Format-MBShortToolError -ErrorText $_.Exception.Message -Fallback 'Update-Module parse failed')
	}
}

function Convert-MBRegistryPath {
	# Normalize model-friendly paths to PS registry provider paths (HKLM:\...).
	# Accepts: HKLM:\x, HKLM\x, HKEY_LOCAL_MACHINE\x, HKLM:/x, Computer\HKEY_...
	param([string]$Path)
	if ([string]::IsNullOrWhiteSpace($Path)) { return '' }
	$p = ([string]$Path).Trim().Trim('"').Trim("'")
	$p = $p -replace '^(?i)\\\\\.\\', ''
	$p = $p -replace '^(?i)Computer\\', ''
	$p = $p -replace '/', '\'
	$hiveMap = [ordered]@{
		'HKEY_LOCAL_MACHINE'  = 'HKLM'
		'HKEY_CURRENT_USER'   = 'HKCU'
		'HKEY_CLASSES_ROOT'   = 'HKCR'
		'HKEY_USERS'          = 'HKU'
		'HKEY_CURRENT_CONFIG' = 'HKCC'
	}
	foreach ($full in @($hiveMap.Keys)) {
		if ($p.Length -ge $full.Length -and $p.Substring(0, $full.Length).Equals($full, [StringComparison]::OrdinalIgnoreCase)) {
			$rest = $p.Substring($full.Length)
			$p = $hiveMap[$full] + $rest
			break
		}
	}
	if ($p -match '^(?i)(HKLM|HKCU|HKCR|HKCC|HKU)(.*)$') {
		$hive = $Matches[1].ToUpperInvariant()
		$rest = [string]$Matches[2]
		$rest = $rest -replace '^:', ''
		if ([string]::IsNullOrEmpty($rest)) {
			$p = "${hive}:\"
		} else {
			$rest = $rest.TrimStart('\')
			$p = "${hive}:\$rest"
		}
	}
	$p = $p -replace '(\\+)', '\'
	return $p
}

function Resolve-MBRegistryValueType {
	# Map model type strings → Set-ItemProperty -Type names (RegistryValueKind).
	param([string]$TypeName)
	$raw = if ($null -eq $TypeName) { 'String' } else { [string]$TypeName }
	# REG_DWORD / reg-dword / "REG DWORD" → dword
	$tKey = ($raw.Trim() -replace '[\s\-_]', '').ToLowerInvariant()
	if ($tKey.StartsWith('reg') -and $tKey.Length -gt 3) {
		$tKey = $tKey.Substring(3)
	}
	$typeMap = @{
		''             = 'String'
		'sz'           = 'String'
		'string'       = 'String'
		'str'          = 'String'
		'text'         = 'String'
		'expandstring' = 'ExpandString'
		'expand'       = 'ExpandString'
		'expandsz'     = 'ExpandString'
		'multistring'  = 'MultiString'
		'multi'        = 'MultiString'
		'multisz'      = 'MultiString'
		'dword'        = 'DWord'
		'dwordle'      = 'DWord'
		'int'          = 'DWord'
		'int32'        = 'DWord'
		'uint32'       = 'DWord'
		'long'         = 'DWord'
		'qword'        = 'QWord'
		'qwordle'      = 'QWord'
		'int64'        = 'QWord'
		'uint64'       = 'QWord'
		'binary'       = 'Binary'
		'bin'          = 'Binary'
		'bytes'        = 'Binary'
		'hex'          = 'Binary'
		'none'         = 'String'
	}
	if ($typeMap.ContainsKey($tKey)) { return $typeMap[$tKey] }
	return $null
}

function Invoke-ReadRegistry {
	param([string]$path)
	try {
		$path = Convert-MBRegistryPath -Path $path
		if ([string]::IsNullOrWhiteSpace($path)) { return "ERROR: path is required (e.g. HKLM:\\Software\\...)." }
		if (-not (Test-Path -LiteralPath $path)) { return "ERROR: Registry path not found: $path" }
		Get-ItemProperty -LiteralPath $path -ErrorAction Stop |
			Select-Object * -ExcludeProperty PSPath, PSParentPath, PSChildName, PSDrive, PSProvider |
			ConvertTo-Json -Compress -Depth 4
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

function Invoke-SetRegistry {
	# ValueType param (aliases: type) — avoids -Type splat quirks.
	param(
		[string]$path,
		[string]$name,
		[string]$value,
		[Alias('type', 'Type', 'reg_type', 'value_type', 'ValueType', 'kind')]
		[string]$ValueType = 'String'
	)
	$path = Convert-MBRegistryPath -Path $path
	if ([string]::IsNullOrWhiteSpace($path)) { return "ERROR: path is required (e.g. HKCU:\\Software\\... or HKLM:\\SOFTWARE\\...)." }
	if ([string]::IsNullOrWhiteSpace($name)) { return "ERROR: name (value name) is required. Use (default) for default value." }
	$propType = Resolve-MBRegistryValueType -TypeName $ValueType
	if (-not $propType) {
		return "ERROR: type/ValueType '$ValueType' not recognized. Use String|ExpandString|MultiString|DWord|QWord|Binary (also REG_DWORD, REG_SZ, int, etc.)."
	}
	$val = $value
	if ($propType -eq 'DWord' -or $propType -eq 'QWord') {
		try {
			$vs = ([string]$value).Trim()
			if ($vs -match '^(?i)0x([0-9a-f]+)$') {
				$val = [Convert]::ToInt64($Matches[1], 16)
			} else {
				$val = [long]$vs
			}
			if ($propType -eq 'DWord') {
				# Registry DWord is UInt32 range; allow signed cast via unchecked int
				if ($val -gt [int]::MaxValue -and $val -le [uint32]::MaxValue) {
					$val = [int]([uint32]$val)
				} else {
					$val = [int]$val
				}
			}
		} catch { return "ERROR: value must be numeric (or 0xHEX) for $propType." }
	} elseif ($propType -eq 'MultiString') {
		$val = @([string]$value -split "`n|;" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
	} elseif ($propType -eq 'Binary') {
		try {
			$hex = ([string]$value) -replace '\s', '' -replace '^0x', ''
			if ($hex.Length % 2 -ne 0) { return "ERROR: Binary hex string must have even length." }
			$val = New-Object byte[] ($hex.Length / 2)
			for ($i = 0; $i -lt $val.Length; $i++) {
				$val[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16)
			}
		} catch {
			return "ERROR: Binary value must be hex string."
		}
	}
	$details = "Write registry:`n  path  = $path`n  name  = $name`n  type  = $propType`n  value = $value"
	if (-not (Request-Confirmation -Title "SetRegistry requires approval" -Details $details)) {
		return "BLOCKED BY USER: SetRegistry denied."
	}
	try {
		if (-not (Test-Path -LiteralPath $path)) {
			New-Item -Path $path -Force -ErrorAction Stop | Out-Null
		}
		$n = $name
		if ($n -eq '(default)' -or $n -eq '(Default)' -or $n -eq '@' -or $n -eq '') { $n = '(default)' }
		# Use RegistryValueKind enum so -Type is always accepted by the Registry provider
		$kind = [Microsoft.Win32.RegistryValueKind]::$propType
		Set-ItemProperty -LiteralPath $path -Name $n -Value $val -Type $kind -Force -ErrorAction Stop
		return ConvertTo-MBJson @{
			ok    = $true
			path  = $path
			name  = $n
			type  = $propType
			value = $value
		}
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

function Convert-MBFindFilePatterns {
	# Normalize glob / globs / extensions into a unique list of -like patterns (e.g. *.mp4).
	# Important: do NOT default-merge glob='*' with extensions — that would match every file
	# because matchAny treats '*' as accept-all. Only use '*' when no real filters were given.
	param(
		$glob = $null,
		$globs = $null,
		$extensions = $null
	)
	$patterns = New-Object System.Collections.ArrayList
	$seen = @{}
	$addOne = {
		param([string]$Raw)
		if ([string]::IsNullOrWhiteSpace($Raw)) { return }
		$x = $Raw.Trim().Trim('"').Trim("'")
		if ([string]::IsNullOrWhiteSpace($x)) { return }
		$key = $x.ToLowerInvariant()
		if ($seen.ContainsKey($key)) { return }
		$seen[$key] = $true
		[void]$patterns.Add($x)
	}
	$addMaybeSplit = {
		param($Raw)
		if ($null -eq $Raw) { return }
		if ($Raw -is [System.Array] -or ($Raw -is [System.Collections.IEnumerable] -and -not ($Raw -is [string]))) {
			foreach ($item in @($Raw)) { & $addMaybeSplit $item }
			return
		}
		$s = [string]$Raw
		if ([string]::IsNullOrWhiteSpace($s)) { return }
		# Multi in one string: "*.mp4;*.mkv" or "*.mp4,*.mkv" or "*.mp4|*.mkv"
		if ($s -match '[,;|]') {
			foreach ($piece in ($s -split '[,;|]+')) {
				& $addOne $piece
			}
		} else {
			& $addOne $s
		}
	}
	& $addMaybeSplit $glob
	& $addMaybeSplit $globs
	foreach ($extRaw in @(Convert-MBForceArray $extensions)) {
		if ($null -eq $extRaw) { continue }
		$e = [string]$extRaw
		if ([string]::IsNullOrWhiteSpace($e)) { continue }
		# allow "mp4", ".mp4", "*.mp4", or "mp4,mkv"
		if ($e -match '[,;|]') {
			foreach ($piece in ($e -split '[,;|]+')) {
				$p = $piece.Trim().TrimStart('.')
				if ($p -match '^\*') { & $addOne $p }
				elseif ($p) { & $addOne ("*.{0}" -f $p) }
			}
		} else {
			$p = $e.Trim()
			if ($p -match '[\*\?]') { & $addOne $p }
			else {
				$p = $p.TrimStart('.')
				if ($p) { & $addOne ("*.{0}" -f $p) }
			}
		}
	}
	# If any real filter exists, drop bare '*' (model sometimes sends glob='*' with extensions=...)
	$real = New-Object System.Collections.ArrayList
	foreach ($p in @($patterns)) {
		if ([string]$p -ne '*') { [void]$real.Add($p) }
	}
	if ($real.Count -gt 0) { return @($real) }
	return @('*')
}

function Invoke-FindFiles {
	param(
		[string]$path = '.',
		$glob = $null,
		$globs = $null,
		$extensions = $null,
		[int]$modified_within_days = 0,
		[long]$min_bytes = 0,
		[long]$max_bytes = 0,
		[switch]$recursive,
		[int]$max = 100
	)
	if ($max -le 0) { $max = 100 }
	if ($max -gt 500) { $max = 500 }
	$root = Resolve-MBPath -Path $path
	if (-not (Test-Path -LiteralPath $root)) { return "ERROR: path not found: $root" }
	$patterns = @(Convert-MBFindFilePatterns -glob $glob -globs $globs -extensions $extensions)
	if ($patterns.Count -eq 0) { $patterns = @('*') }
	try {
		$gci = @{
			LiteralPath = $root
			File        = $true
			ErrorAction = 'SilentlyContinue'
			Force       = $true
		}
		if ($recursive) { $gci['Recurse'] = $true }

		# Single simple name filter -> native Filter (fast). Multi-pattern -> one walk + -like any.
		$useNativeFilter = ($patterns.Count -eq 1 -and $patterns[0] -ne '*' -and $patterns[0] -notmatch '[\\/]')
		if ($useNativeFilter) {
			$gci['Filter'] = $patterns[0]
		}
		$files = @(Get-ChildItem @gci)
		if (-not $useNativeFilter) {
			$matchAny = {
				param($f)
				$n = [string]$f.Name
				$full = [string]$f.FullName
				$ext = ''
				try { $ext = [string]$f.Extension } catch { $ext = '' }
				foreach ($p in $patterns) {
					if ($p -eq '*') { return $true }
					# Extension-style patterns: *.mp4 or .mp4 -> match Extension (more reliable than name -like)
					if ($p -match '^\*\.([A-Za-z0-9]+)$') {
						$want = '.' + $Matches[1]
						if ($ext -and [string]::Equals($ext, $want, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
						continue
					}
					if ($p -match '^\.([A-Za-z0-9]+)$') {
						$want = '.' + $Matches[1]
						if ($ext -and [string]::Equals($ext, $want, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
						continue
					}
					if ($p -match '[\\/]') {
						if ($full -like $p -or $n -like $p) { return $true }
					} else {
						if ($n -like $p) { return $true }
					}
				}
				return $false
			}
			$files = @($files | Where-Object { & $matchAny $_ })
		} elseif ($patterns[0] -match '[\\/]') {
			$p0 = $patterns[0]
			$files = @($files | Where-Object { $_.Name -like $p0 -or $_.FullName -like $p0 })
		}
		if ($modified_within_days -gt 0) {
			$cut = (Get-Date).AddDays(-[double]$modified_within_days)
			$files = @($files | Where-Object { $_.LastWriteTime -ge $cut })
		}
		if ($min_bytes -gt 0) {
			$files = @($files | Where-Object { $_.Length -ge $min_bytes })
		}
		if ($max_bytes -gt 0) {
			$files = @($files | Where-Object { $_.Length -le $max_bytes })
		}
		$total = $files.Count
		$files = @($files | Sort-Object LastWriteTime -Descending | Select-Object -First $max)
		$rows = @(foreach ($f in $files) {
			[ordered]@{
				path     = $f.FullName
				name     = $f.Name
				bytes    = [long]$f.Length
				modified = $f.LastWriteTime.ToString('s')
				created  = $f.CreationTime.ToString('s')
			}
		})
		$isTrunc = ($total -gt $rows.Count)
		$payload = [ordered]@{
			root      = $root
			glob      = $(if ($patterns.Count -eq 1) { $patterns[0] } else { ($patterns -join ';') })
			globs     = $patterns
			count     = $rows.Count
			total     = $total
			truncated = $isTrunc
			files     = $rows
		}
		if ($isTrunc) {
			$payload['hint'] = (
				"TRUNCATED: showing {0} of {1} matches (newest first). Do NOT re-run FindFiles with the same args or Get-ChildItem -Recurse to dump the rest. " +
				"If the operator was SPECIFIC (named file/subject/folder/criteria): narrow path/name/days/size (or raise max once, hard max 500) until you match — do not pick a random unrelated file. " +
				"If they were deliberately VAGUE (e.g. play something / show a random ... / any clip with no criteria): pick one suitable path from files[] now and act — no extra search loops. " +
				"Play/show: embed INLINE as ![label](absolute-path). Default app only if format is not inline-compatible or they asked external."
			) -f $rows.Count, $total
		}
		return ConvertTo-MBJson $payload
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

function Convert-MBOffsetToInt64 {
	# Accept int/long or string "123" / "0x1A0" / "1A0h"
	param($Value, [long]$Default = 0)
	if ($null -eq $Value) { return $Default }
	if ($Value -is [long] -or $Value -is [int] -or $Value -is [int64]) {
		$n = [long]$Value
		if ($n -lt 0) { return $Default }
		return $n
	}
	$s = ([string]$Value).Trim()
	if ([string]::IsNullOrWhiteSpace($s)) { return $Default }
	try {
		if ($s -match '^(?i)0x([0-9a-f]+)$') {
			return [Convert]::ToInt64($Matches[1], 16)
		}
		if ($s -match '^(?i)([0-9a-f]+)h$') {
			return [Convert]::ToInt64($Matches[1], 16)
		}
		$n2 = 0L
		if ([long]::TryParse($s, [ref]$n2)) {
			if ($n2 -lt 0) { return $Default }
			return $n2
		}
	} catch {}
	return $Default
}

function Convert-MBHexStringToBytes {
	# "DE AD BE EF", "DEADBEEF", "0xDE,0xAD", "de:ad:be:ef"
	param([string]$Hex)
	$out = New-Object System.Collections.Generic.List[byte]
	if ([string]::IsNullOrWhiteSpace($Hex)) { return ,@() }
	$s = [string]$Hex
	$s = $s -replace '(?i)0x', ''
	$s = $s -replace '[^0-9A-Fa-f]', ''
	if (($s.Length % 2) -ne 0) {
		throw "Hex string must have an even number of digits (got $($s.Length))."
	}
	if ($s.Length -eq 0) { return ,@() }
	for ($i = 0; $i -lt $s.Length; $i += 2) {
		$out.Add([Convert]::ToByte($s.Substring($i, 2), 16))
	}
	return ,$out.ToArray()
}

function Get-MBHexAsciiGlyph {
	# Single-width glyph for dump gutter (printable ASCII, else '.')
	param([byte]$B)
	if ($B -ge 32 -and $B -le 126) { return [string][char]$B }
	return '.'
}

function Get-MBControlCharName {
	param([byte]$B)
	switch ([int]$B) {
		0x00 { return 'NUL' }
		0x01 { return 'SOH' }
		0x02 { return 'STX' }
		0x03 { return 'ETX' }
		0x04 { return 'EOT' }
		0x05 { return 'ENQ' }
		0x06 { return 'ACK' }
		0x07 { return 'BEL' }
		0x08 { return 'BS' }
		0x09 { return 'TAB' }
		0x0A { return 'LF' }
		0x0B { return 'VT' }
		0x0C { return 'FF' }
		0x0D { return 'CR' }
		0x0E { return 'SO' }
		0x0F { return 'SI' }
		0x10 { return 'DLE' }
		0x11 { return 'DC1' }
		0x12 { return 'DC2' }
		0x13 { return 'DC3' }
		0x14 { return 'DC4' }
		0x15 { return 'NAK' }
		0x16 { return 'SYN' }
		0x17 { return 'ETB' }
		0x18 { return 'CAN' }
		0x19 { return 'EM' }
		0x1A { return 'SUB' }
		0x1B { return 'ESC' }
		0x1C { return 'FS' }
		0x1D { return 'GS' }
		0x1E { return 'RS' }
		0x1F { return 'US' }
		0x7F { return 'DEL' }
		default { return $null }
	}
}

function Format-MBHexDump {
	param(
		[byte[]]$Bytes,
		[long]$BaseOffset = 0,
		[int]$Width = 16,
		[bool]$ShowAscii = $true,
		# optional per-byte mask: true = highlight as changed (prefix line with * and mark byte with !)
		[bool[]]$DiffMask = $null
	)
	if ($null -eq $Bytes -or $Bytes.Length -eq 0) { return '(empty)' }
	if ($Width -lt 1) { $Width = 16 }
	if ($Width -gt 32) { $Width = 32 }
	$sb = New-Object System.Text.StringBuilder
	$i = 0
	while ($i -lt $Bytes.Length) {
		$lineOff = $BaseOffset + $i
		$lineHasDiff = $false
		if ($DiffMask) {
			for ($c = 0; $c -lt $Width; $c++) {
				if (($i + $c) -lt $Bytes.Length -and ($i + $c) -lt $DiffMask.Length -and $DiffMask[$i + $c]) {
					$lineHasDiff = $true
					break
				}
			}
		}
		if ($lineHasDiff) { [void]$sb.Append('* ') } else { [void]$sb.Append('  ') }
		[void]$sb.Append(('{0:X8}  ' -f $lineOff))
		$ascii = New-Object System.Text.StringBuilder
		for ($c = 0; $c -lt $Width; $c++) {
			if (($i + $c) -lt $Bytes.Length) {
				$b = $Bytes[$i + $c]
				$changed = $false
				if ($DiffMask -and ($i + $c) -lt $DiffMask.Length -and $DiffMask[$i + $c]) { $changed = $true }
				if ($changed) {
					[void]$sb.Append(('{0:X2}!' -f $b))
				} else {
					[void]$sb.Append(('{0:X2} ' -f $b))
				}
				if ($ShowAscii) {
					[void]$ascii.Append((Get-MBHexAsciiGlyph -B $b))
				}
			} else {
				[void]$sb.Append('   ')
				if ($ShowAscii) { [void]$ascii.Append(' ') }
			}
			if ($c -eq 7) { [void]$sb.Append(' ') }
		}
		if ($ShowAscii) {
			[void]$sb.Append(' |')
			[void]$sb.Append($ascii.ToString())
			[void]$sb.Append('|')
		}
		[void]$sb.AppendLine()
		$i += $Width
	}
	return $sb.ToString().TrimEnd()
}

function Format-MBHexDumpSideBySide {
	# A/B dual dump for comparison (same offsets). Diff lines marked with * on the marker column.
	param(
		[byte[]]$BytesA,
		[byte[]]$BytesB,
		[long]$BaseOffset = 0,
		[int]$Width = 16,
		[bool]$ShowAscii = $true
	)
	if ($Width -lt 1) { $Width = 16 }
	if ($Width -gt 16) { $Width = 16 } # side-by-side stays readable
	$lenA = if ($BytesA) { $BytesA.Length } else { 0 }
	$lenB = if ($BytesB) { $BytesB.Length } else { 0 }
	$maxLen = [Math]::Max($lenA, $lenB)
	if ($maxLen -eq 0) { return '(empty)' }
	$sb = New-Object System.Text.StringBuilder
	[void]$sb.AppendLine(('  {0,-44}  {1}' -f 'A (path)', 'B (path2)'))
	$i = 0
	while ($i -lt $maxLen) {
		$lineOff = $BaseOffset + $i
		$lineDiff = $false
		for ($c = 0; $c -lt $Width; $c++) {
			$ia = $i + $c
			$ba = if ($ia -lt $lenA) { $BytesA[$ia] } else { $null }
			$bb = if ($ia -lt $lenB) { $BytesB[$ia] } else { $null }
			if ($ba -ne $bb) { $lineDiff = $true; break }
		}
		$mark = if ($lineDiff) { '* ' } else { '  ' }
		$hexA = New-Object System.Text.StringBuilder
		$hexB = New-Object System.Text.StringBuilder
		$ascA = New-Object System.Text.StringBuilder
		$ascB = New-Object System.Text.StringBuilder
		for ($c = 0; $c -lt $Width; $c++) {
			$ia = $i + $c
			if ($ia -lt $lenA) {
				$b = $BytesA[$ia]
				$ch = ($ia -lt $lenB -and $b -ne $BytesB[$ia])
				if ($ch) { [void]$hexA.Append(('{0:X2}!' -f $b)) } else { [void]$hexA.Append(('{0:X2} ' -f $b)) }
				if ($ShowAscii) { [void]$ascA.Append((Get-MBHexAsciiGlyph -B $b)) }
			} else {
				[void]$hexA.Append('   ')
				if ($ShowAscii) { [void]$ascA.Append(' ') }
			}
			if ($ia -lt $lenB) {
				$b2 = $BytesB[$ia]
				$ch2 = ($ia -lt $lenA -and $b2 -ne $BytesA[$ia])
				if ($ch2) { [void]$hexB.Append(('{0:X2}!' -f $b2)) } else { [void]$hexB.Append(('{0:X2} ' -f $b2)) }
				if ($ShowAscii) { [void]$ascB.Append((Get-MBHexAsciiGlyph -B $b2)) }
			} else {
				[void]$hexB.Append('   ')
				if ($ShowAscii) { [void]$ascB.Append(' ') }
			}
		}
		$left = ('{0:X8}  {1}' -f $lineOff, $hexA.ToString().TrimEnd())
		if ($ShowAscii) { $left += (' |{0}|' -f $ascA.ToString()) }
		$right = $hexB.ToString().TrimEnd()
		if ($ShowAscii) { $right += (' |{0}|' -f $ascB.ToString()) }
		[void]$sb.AppendLine(('{0}{1,-48}  {2}' -f $mark, $left, $right))
		$i += $Width
	}
	return $sb.ToString().TrimEnd()
}

function Read-MBFileBytes {
	param(
		[string]$Path,
		[long]$Offset = 0,
		[int]$Length = 256
	)
	$fs = $null
	try {
		$fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		$fileLen = $fs.Length
		if ($Offset -lt 0) { $Offset = 0 }
		if ($Offset -ge $fileLen) {
			return @{ Ok = $true; FileSize = $fileLen; Offset = $Offset; Bytes = [byte[]]@(); Eof = $true }
		}
		$take = [int][Math]::Min([long]$Length, $fileLen - $Offset)
		$buf = New-Object byte[] $take
		[void]$fs.Seek($Offset, [System.IO.SeekOrigin]::Begin)
		$read = $fs.Read($buf, 0, $take)
		if ($read -lt $take) {
			$tmp = New-Object byte[] $read
			[Array]::Copy($buf, $tmp, $read)
			$buf = $tmp
		}
		return @{
			Ok       = $true
			FileSize = $fileLen
			Offset   = $Offset
			Bytes    = $buf
			Eof      = (($Offset + $buf.Length) -ge $fileLen)
		}
	} catch {
		return @{ Ok = $false; Error = $_.Exception.Message }
	} finally {
		if ($null -ne $fs) { try { $fs.Dispose() } catch {} }
	}
}

function Find-MBNextByteDiff {
	# Scan two files from StartOffset; return first differing absolute offset, or -1 if identical to end of shorter.
	param(
		[string]$PathA,
		[string]$PathB,
		[long]$StartOffset = 0,
		[int]$ChunkSize = 65536,
		[long]$MaxScan = 0  # 0 = no limit beyond files
	)
	$fa = $null; $fb = $null
	try {
		$fa = [System.IO.File]::Open($PathA, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		$fb = [System.IO.File]::Open($PathB, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		$lenA = $fa.Length
		$lenB = $fb.Length
		$pos = [Math]::Max(0L, $StartOffset)
		$endLimit = [Math]::Min($lenA, $lenB)
		if ($MaxScan -gt 0) {
			$cap = $pos + $MaxScan
			if ($cap -lt $endLimit) { $endLimit = $cap }
		}
		if ($pos -ge $endLimit) {
			if ($lenA -ne $lenB -and $pos -ge [Math]::Min($lenA, $lenB)) {
				return @{ Found = $true; Offset = [Math]::Min($lenA, $lenB); Reason = 'length_mismatch_after' }
			}
			return @{ Found = $false; Offset = -1L; Reason = 'no_diff' }
		}
		[void]$fa.Seek($pos, [System.IO.SeekOrigin]::Begin)
		[void]$fb.Seek($pos, [System.IO.SeekOrigin]::Begin)
		$bufA = New-Object byte[] $ChunkSize
		$bufB = New-Object byte[] $ChunkSize
		while ($pos -lt $endLimit) {
			$want = [int][Math]::Min([long]$ChunkSize, $endLimit - $pos)
			$ra = $fa.Read($bufA, 0, $want)
			$rb = $fb.Read($bufB, 0, $want)
			$n = [Math]::Min($ra, $rb)
			for ($i = 0; $i -lt $n; $i++) {
				if ($bufA[$i] -ne $bufB[$i]) {
					return @{ Found = $true; Offset = ($pos + $i); Reason = 'byte_diff'; ByteA = [int]$bufA[$i]; ByteB = [int]$bufB[$i] }
				}
			}
			if ($ra -ne $rb) {
				return @{ Found = $true; Offset = ($pos + $n); Reason = 'chunk_length' }
			}
			$pos += $n
			if ($n -le 0) { break }
		}
		if ($lenA -ne $lenB) {
			return @{ Found = $true; Offset = [Math]::Min($lenA, $lenB); Reason = 'file_length'; SizeA = $lenA; SizeB = $lenB }
		}
		return @{ Found = $false; Offset = -1L; Reason = 'identical' }
	} catch {
		return @{ Found = $false; Offset = -1L; Reason = 'error'; Error = $_.Exception.Message }
	} finally {
		if ($fa) { try { $fa.Dispose() } catch {} }
		if ($fb) { try { $fb.Dispose() } catch {} }
	}
}

function Convert-MBPeRvaToOffset {
	param(
		[System.Collections.IEnumerable]$Sections,
		[uint32]$Rva
	)
	if ($null -eq $Sections) { return $null }
	foreach ($s in @($Sections)) {
		try {
			$vrva = [uint32]$s.virt_rva
			$vsz = [uint32]$s.virt_size
			$rsz = [uint32]$s.raw_size
			$rptr = [uint32]$s.raw_ptr
			$span = $vsz
			if ($rsz -gt $span) { $span = $rsz }
			if ($span -eq 0) { $span = $rsz }
			if ($Rva -ge $vrva -and $Rva -lt ($vrva + $span)) {
				return [long]($rptr + ($Rva - $vrva))
			}
		} catch {}
	}
	return $null
}

function Convert-MBPeOffsetToRva {
	param(
		[System.Collections.IEnumerable]$Sections,
		[long]$FileOffset
	)
	if ($null -eq $Sections -or $FileOffset -lt 0) { return $null }
	foreach ($s in @($Sections)) {
		try {
			$rptr = [uint32]$s.raw_ptr
			$rsz = [uint32]$s.raw_size
			if ($rsz -eq 0) { continue }
			if ($FileOffset -ge $rptr -and $FileOffset -lt ([long]$rptr + [long]$rsz)) {
				return [uint32]([uint32]$s.virt_rva + [uint32]($FileOffset - $rptr))
			}
		} catch {}
	}
	return $null
}

function Read-MBPeAsciiZ {
	param(
		[System.IO.Stream]$Stream,
		[long]$Offset,
		[int]$MaxLen = 256
	)
	if ($null -eq $Stream -or $Offset -lt 0 -or $Offset -ge $Stream.Length) { return '' }
	if ($MaxLen -lt 1) { $MaxLen = 64 }
	if ($MaxLen -gt 512) { $MaxLen = 512 }
	[void]$Stream.Seek($Offset, [System.IO.SeekOrigin]::Begin)
	$buf = New-Object byte[] $MaxLen
	$n = $Stream.Read($buf, 0, $MaxLen)
	if ($n -le 0) { return '' }
	$end = 0
	while ($end -lt $n -and $buf[$end] -ne 0) { $end++ }
	if ($end -le 0) { return '' }
	return [System.Text.Encoding]::ASCII.GetString($buf, 0, $end)
}

function Get-MBPeSymbolMap {
	# IAT slot file offsets -> dll!func ; export function file offsets / RVAs -> names.
	# Used to label call/jmp [rip+disp] and direct calls into exports.
	param(
		[string]$Path,
		[int]$MaxDlls = 48,
		[int]$MaxFuncsPerDll = 256,
		[int]$MaxExports = 512
	)
	$map = [ordered]@{
		Ok                 = $false
		Is64               = $false
		ImageBase          = [uint64]0
		Sections           = @()
		ImportDllCount     = 0
		IatSlotCount       = 0
		ExportCount        = 0
		ExportModule       = ''
		IatByFileOffset    = @{}   # string key of long fo -> label
		ExportByFileOffset = @{}
		ExportByRva        = @{}
		DelayDllCount      = 0
		DelayDlls          = @()
		BoundImportNote    = $null
		IsDotNet           = $false
		ClrRva             = 0
		Error              = $null
	}
	$fs = $null
	try {
		$fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		if ($fs.Length -lt 64) { $map.Error = 'too_small'; return $map }
		$hdr = New-Object byte[] 64
		[void]$fs.Read($hdr, 0, 64)
		if ($hdr[0] -ne 0x4D -or $hdr[1] -ne 0x5A) { $map.Error = 'not_mz'; return $map }
		$e_lfanew = [BitConverter]::ToInt32($hdr, 0x3C)
		if ($e_lfanew -le 0 -or ($e_lfanew + 24) -gt $fs.Length) { $map.Error = 'bad_lfanew'; return $map }
		[void]$fs.Seek([long]$e_lfanew, [System.IO.SeekOrigin]::Begin)
		$peSig = New-Object byte[] 4
		[void]$fs.Read($peSig, 0, 4)
		if ($peSig[0] -ne 0x50 -or $peSig[1] -ne 0x45) { $map.Error = 'not_pe'; return $map }
		$coff = New-Object byte[] 20
		[void]$fs.Read($coff, 0, 20)
		$numSec = [BitConverter]::ToUInt16($coff, 2)
		$optSize = [BitConverter]::ToUInt16($coff, 16)
		$optOff = $e_lfanew + 24
		$is64 = $false
		$imgBase = [uint64]0
		$dataDirOff = 0
		$numRvaSizes = 0
		if ($optSize -ge 2 -and ($optOff + $optSize) -le $fs.Length) {
			[void]$fs.Seek([long]$optOff, [System.IO.SeekOrigin]::Begin)
			$opt = New-Object byte[] ([Math]::Min([int]$optSize, 384))
			[void]$fs.Read($opt, 0, $opt.Length)
			$magic = [BitConverter]::ToUInt16($opt, 0)
			$is64 = ($magic -eq 0x20B)
			$map.Is64 = $is64
			if ($magic -eq 0x20B -and $opt.Length -ge 32) {
				$imgBase = [BitConverter]::ToUInt64($opt, 24)
				$dataDirOff = $optOff + 112
				if ($opt.Length -ge 110) { $numRvaSizes = [BitConverter]::ToInt32($opt, 108) }
			} elseif ($magic -eq 0x10B -and $opt.Length -ge 32) {
				$imgBase = [uint64][BitConverter]::ToUInt32($opt, 28)
				$dataDirOff = $optOff + 96
				if ($opt.Length -ge 96) { $numRvaSizes = [BitConverter]::ToInt32($opt, 92) }
			} else {
				$map.Error = 'bad_optional'
				return $map
			}
		}
		$map.ImageBase = $imgBase
		$secOff = $e_lfanew + 24 + $optSize
		$secs = New-Object System.Collections.ArrayList
		$maxSec = [Math]::Min([int]$numSec, 48)
		for ($s = 0; $s -lt $maxSec; $s++) {
			$so = $secOff + ($s * 40)
			if (($so + 40) -gt $fs.Length) { break }
			[void]$fs.Seek([long]$so, [System.IO.SeekOrigin]::Begin)
			$sec = New-Object byte[] 40
			[void]$fs.Read($sec, 0, 40)
			$nb = New-Object byte[] 8
			[Array]::Copy($sec, 0, $nb, 0, 8)
			$name = [System.Text.Encoding]::ASCII.GetString($nb).TrimEnd([char]0)
			[void]$secs.Add([ordered]@{
				name      = $name
				virt_rva  = [BitConverter]::ToUInt32($sec, 12)
				virt_size = [BitConverter]::ToUInt32($sec, 8)
				raw_ptr   = [BitConverter]::ToUInt32($sec, 20)
				raw_size  = [BitConverter]::ToUInt32($sec, 16)
			})
		}
		$map.Sections = @($secs)
		if ($numRvaSizes -le 0) { $numRvaSizes = 16 }
		if ($numRvaSizes -gt 16) { $numRvaSizes = 16 }
		$readDir = {
			param([int]$Index)
			if ($dataDirOff -le 0) { return $null }
			$do = $dataDirOff + ($Index * 8)
			if (($do + 8) -gt $fs.Length) { return $null }
			[void]$fs.Seek([long]$do, [System.IO.SeekOrigin]::Begin)
			$db = New-Object byte[] 8
			[void]$fs.Read($db, 0, 8)
			$rva = [BitConverter]::ToUInt32($db, 0)
			$sz = [BitConverter]::ToUInt32($db, 4)
			if ($rva -eq 0) { return $null }
			return @{ Rva = $rva; Size = $sz }
		}
		# --- Imports / IAT ---
		$impDir = & $readDir 1
		if ($impDir) {
			$impFile = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva ([uint32]$impDir.Rva)
			if ($null -ne $impFile) {
				$dllCount = 0
				$descOff = [long]$impFile
				$thunkSize = if ($is64) { 8 } else { 4 }
				$ordMask = if ($is64) { [uint64]0x8000000000000000 } else { [uint64]0x80000000 }
				while ($dllCount -lt $MaxDlls) {
					if (($descOff + 20) -gt $fs.Length) { break }
					[void]$fs.Seek($descOff, [System.IO.SeekOrigin]::Begin)
					$desc = New-Object byte[] 20
					[void]$fs.Read($desc, 0, 20)
					$oft = [BitConverter]::ToUInt32($desc, 0)
					$nameRva = [BitConverter]::ToUInt32($desc, 12)
					$ft = [BitConverter]::ToUInt32($desc, 16)
					if ($oft -eq 0 -and $nameRva -eq 0 -and $ft -eq 0) { break }
					$dllName = ''
					$nameOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $nameRva
					if ($null -ne $nameOff) {
						$dllName = Read-MBPeAsciiZ -Stream $fs -Offset ([long]$nameOff) -MaxLen 128
					}
					if (-not $dllName) { $dllName = ('dll_{0}' -f $dllCount) }
					$intRva = if ($oft -ne 0) { $oft } else { $ft }
					$iatRva = $ft
					if ($intRva -eq 0 -or $iatRva -eq 0) {
						$dllCount++
						$descOff += 20
						continue
					}
					$intOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $intRva
					$iatOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $iatRva
					if ($null -eq $intOff -or $null -eq $iatOff) {
						$dllCount++
						$descOff += 20
						continue
					}
					$fi = 0
					while ($fi -lt $MaxFuncsPerDll) {
						$slotInt = [long]$intOff + ($fi * $thunkSize)
						$slotIat = [long]$iatOff + ($fi * $thunkSize)
						if (($slotInt + $thunkSize) -gt $fs.Length) { break }
						[void]$fs.Seek($slotInt, [System.IO.SeekOrigin]::Begin)
						$tb = New-Object byte[] $thunkSize
						[void]$fs.Read($tb, 0, $thunkSize)
						$thunkVal = [uint64]0
						if ($is64) {
							$thunkVal = [BitConverter]::ToUInt64($tb, 0)
						} else {
							$thunkVal = [uint64][BitConverter]::ToUInt32($tb, 0)
						}
						if ($thunkVal -eq 0) { break }
						$label = ''
						if (($thunkVal -band $ordMask) -ne 0) {
							$ord = [int]($thunkVal -band 0xFFFF)
							$label = ('{0}!#{1}' -f $dllName, $ord)
						} else {
							# Hint/Name RVA (lower 31/32 bits; PE RVAs fit in 32-bit)
							$ibnRva = [uint32]($thunkVal -band [uint64]0x7FFFFFFF)
							$ibnOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $ibnRva
							if ($null -ne $ibnOff) {
								$fn = Read-MBPeAsciiZ -Stream $fs -Offset ([long]$ibnOff + 2) -MaxLen 192
								if ($fn) { $label = ('{0}!{1}' -f $dllName, $fn) }
							}
						}
						if (-not $label) { $label = ('{0}!?' -f $dllName) }
						$key = [string]$slotIat
						$map.IatByFileOffset[$key] = $label
						# Also map INT slot for completeness
						$map.IatByFileOffset[[string]$slotInt] = $label
						$fi++
					}
					$map.IatSlotCount += $fi
					$dllCount++
					$descOff += 20
				}
				$map.ImportDllCount = $dllCount
			}
		}
		# --- Exports ---
		$expDir = & $readDir 0
		if ($expDir -and [uint32]$expDir.Size -ge 40) {
			$expFile = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva ([uint32]$expDir.Rva)
			if ($null -ne $expFile) {
				[void]$fs.Seek([long]$expFile, [System.IO.SeekOrigin]::Begin)
				$ed = New-Object byte[] 40
				[void]$fs.Read($ed, 0, 40)
				$nameRvaE = [BitConverter]::ToUInt32($ed, 12)
				$ordBase = [BitConverter]::ToUInt32($ed, 16)
				$numFuncs = [BitConverter]::ToUInt32($ed, 20)
				$numNames = [BitConverter]::ToUInt32($ed, 24)
				$funcsRva = [BitConverter]::ToUInt32($ed, 28)
				$namesRva = [BitConverter]::ToUInt32($ed, 32)
				$ordsRva = [BitConverter]::ToUInt32($ed, 36)
				$modName = ''
				$modOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $nameRvaE
				if ($null -ne $modOff) {
					$modName = Read-MBPeAsciiZ -Stream $fs -Offset ([long]$modOff) -MaxLen 128
				}
				$map.ExportModule = $modName
				$funcsOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $funcsRva
				$namesOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $namesRva
				$ordsOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $ordsRva
				# Build ordinal -> name
				$nameByOrdIndex = @{}
				if ($null -ne $namesOff -and $null -ne $ordsOff -and $numNames -gt 0) {
					$takeN = [Math]::Min([int]$numNames, $MaxExports)
					for ($ni = 0; $ni -lt $takeN; $ni++) {
						[void]$fs.Seek([long]($namesOff + ($ni * 4)), [System.IO.SeekOrigin]::Begin)
						$nb4 = New-Object byte[] 4
						[void]$fs.Read($nb4, 0, 4)
						$nrva = [BitConverter]::ToUInt32($nb4, 0)
						[void]$fs.Seek([long]($ordsOff + ($ni * 2)), [System.IO.SeekOrigin]::Begin)
						$ob = New-Object byte[] 2
						[void]$fs.Read($ob, 0, 2)
						$ordIdx = [int][BitConverter]::ToUInt16($ob, 0)
						$nOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $nrva
						$en = if ($null -ne $nOff) { Read-MBPeAsciiZ -Stream $fs -Offset ([long]$nOff) -MaxLen 128 } else { '' }
						if ($en) { $nameByOrdIndex[$ordIdx] = $en }
					}
				}
				if ($null -ne $funcsOff -and $numFuncs -gt 0) {
					$takeF = [Math]::Min([int]$numFuncs, $MaxExports)
					for ($fi = 0; $fi -lt $takeF; $fi++) {
						[void]$fs.Seek([long]($funcsOff + ($fi * 4)), [System.IO.SeekOrigin]::Begin)
						$fb = New-Object byte[] 4
						[void]$fs.Read($fb, 0, 4)
						$frva = [BitConverter]::ToUInt32($fb, 0)
						if ($frva -eq 0) { continue }
						# Skip forwarders (RVA inside export dir)
						if ($frva -ge [uint32]$expDir.Rva -and $frva -lt ([uint32]$expDir.Rva + [uint32]$expDir.Size)) { continue }
						$en = if ($nameByOrdIndex.ContainsKey($fi)) { [string]$nameByOrdIndex[$fi] } else { ('ord_{0}' -f ($ordBase + $fi)) }
						$label = if ($modName) { ('{0}!{1}' -f $modName, $en) } else { $en }
						$map.ExportByRva[[string]$frva] = $label
						$fOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $frva
						if ($null -ne $fOff) {
							$map.ExportByFileOffset[[string][long]$fOff] = $label
						}
						$map.ExportCount++
					}
				}
			}
		}
		# --- Bound import (dir 11): presence note only ---
		try {
			$boundDir = & $readDir 11
			if ($boundDir) {
				$bOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva ([uint32]$boundDir.Rva)
				$map.BoundImportNote = [ordered]@{
					rva        = [uint32]$boundDir.Rva
					size       = [uint32]$boundDir.Size
					file       = $bOff
					file_hex   = $(if ($null -ne $bOff) { ('0x{0:X}' -f [long]$bOff) } else { $null })
					hint       = 'Bound imports present (pre-bound IAT). Runtime may skip normal loader walk; labels still use INT/IAT names when available.'
				}
			}
		} catch {}
		# --- Delay-load imports (dir 13) ---
		try {
			$delayDir = & $readDir 13
			if ($delayDir) {
				$dFile = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva ([uint32]$delayDir.Rva)
				if ($null -ne $dFile) {
					$delayList = New-Object System.Collections.ArrayList
					$descOff = [long]$dFile
					$dCount = 0
					$thunkSize = if ($is64) { 8 } else { 4 }
					$ordMask = if ($is64) { [uint64]0x8000000000000000 } else { [uint64]0x80000000 }
					while ($dCount -lt $MaxDlls) {
						if (($descOff + 32) -gt $fs.Length) { break }
						[void]$fs.Seek($descOff, [System.IO.SeekOrigin]::Begin)
						$dd = New-Object byte[] 32
						[void]$fs.Read($dd, 0, 32)
						# IMAGE_DELAYLOAD_DESCRIPTOR (all zero = end)
						$attrs = [BitConverter]::ToUInt32($dd, 0)
						$nameRvaD = [BitConverter]::ToUInt32($dd, 4)
						$iatRvaD = [BitConverter]::ToUInt32($dd, 12)
						$intRvaD = [BitConverter]::ToUInt32($dd, 16)
						if ($attrs -eq 0 -and $nameRvaD -eq 0 -and $iatRvaD -eq 0 -and $intRvaD -eq 0) { break }
						$dllName = ''
						$nOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $nameRvaD
						if ($null -ne $nOff) {
							$dllName = Read-MBPeAsciiZ -Stream $fs -Offset ([long]$nOff) -MaxLen 128
						}
						if (-not $dllName) { $dllName = ('delay_dll_{0}' -f $dCount) }
						$funcs = New-Object System.Collections.ArrayList
						$nameTableRva = if ($intRvaD -ne 0) { $intRvaD } else { $iatRvaD }
						$iatTableRva = $iatRvaD
						if ($nameTableRva -ne 0 -and $iatTableRva -ne 0) {
							$ntOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $nameTableRva
							$iatOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $iatTableRva
							if ($null -ne $ntOff -and $null -ne $iatOff) {
								$fi = 0
								while ($fi -lt $MaxFuncsPerDll) {
									$slotN = [long]$ntOff + ($fi * $thunkSize)
									$slotI = [long]$iatOff + ($fi * $thunkSize)
									if (($slotN + $thunkSize) -gt $fs.Length) { break }
									[void]$fs.Seek($slotN, [System.IO.SeekOrigin]::Begin)
									$tb = New-Object byte[] $thunkSize
									[void]$fs.Read($tb, 0, $thunkSize)
									$thunkVal = if ($is64) { [BitConverter]::ToUInt64($tb, 0) } else { [uint64][BitConverter]::ToUInt32($tb, 0) }
									if ($thunkVal -eq 0) { break }
									$label = ''
									if (($thunkVal -band $ordMask) -ne 0) {
										$label = ('{0}!#{1} (delay)' -f $dllName, [int]($thunkVal -band 0xFFFF))
									} else {
										$ibnRva = [uint32]($thunkVal -band [uint64]0x7FFFFFFF)
										$ibnOff = Convert-MBPeRvaToOffset -Sections $map.Sections -Rva $ibnRva
										if ($null -ne $ibnOff) {
											$fn = Read-MBPeAsciiZ -Stream $fs -Offset ([long]$ibnOff + 2) -MaxLen 192
											if ($fn) { $label = ('{0}!{1} (delay)' -f $dllName, $fn) }
										}
									}
									if (-not $label) { $label = ('{0}!? (delay)' -f $dllName) }
									$map.IatByFileOffset[[string]$slotI] = $label
									$map.IatByFileOffset[[string]$slotN] = $label
									[void]$funcs.Add($label)
									$fi++
								}
								$map.IatSlotCount += $fi
							}
						}
						[void]$delayList.Add([ordered]@{
							dll   = $dllName
							funcs = @($funcs | Select-Object -First 24)
							func_count = $funcs.Count
						})
						$dCount++
						$descOff += 32
					}
					$map.DelayDllCount = $dCount
					$map.DelayDlls = @($delayList)
				}
			}
		} catch {}
		# --- CLR / .NET (dir 14) ---
		try {
			$clrDir = & $readDir 14
			if ($clrDir -and [uint32]$clrDir.Rva -gt 0) {
				$map.IsDotNet = $true
				$map.ClrRva = [uint32]$clrDir.Rva
			}
			# Also flag mscoree import as managed hint
			if (-not $map.IsDotNet) {
				foreach ($k in @($map.IatByFileOffset.Keys)) {
					$lab = [string]$map.IatByFileOffset[$k]
					if ($lab -match '(?i)mscoree\.dll') { $map.IsDotNet = $true; break }
				}
			}
		} catch {}
		$map.Ok = $true
	} catch {
		$map.Error = $_.Exception.Message
		$map.Ok = $false
	} finally {
		if ($fs) { try { $fs.Dispose() } catch {} }
	}
	return $map
}

function Get-MBFileSha256Hex {
	param(
		[Parameter(Mandatory)][string]$Path,
		[long]$Offset = 0,
		[long]$Length = 0
	)
	$fs = $null
	$sha = $null
	try {
		$sha = [System.Security.Cryptography.SHA256]::Create()
		$fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		if ($Offset -lt 0) { $Offset = 0 }
		if ($Offset -ge $fs.Length) {
			$hash = $sha.ComputeHash([byte[]]@())
			return ([BitConverter]::ToString($hash) -replace '-', '').ToLowerInvariant()
		}
		if ($Length -le 0) { $Length = $fs.Length - $Offset }
		$Length = [Math]::Min($Length, $fs.Length - $Offset)
		[void]$fs.Seek($Offset, [System.IO.SeekOrigin]::Begin)
		$buf = New-Object byte[] 65536
		$left = $Length
		while ($left -gt 0) {
			$want = [int][Math]::Min([long]$buf.Length, $left)
			$n = $fs.Read($buf, 0, $want)
			if ($n -le 0) { break }
			[void]$sha.TransformBlock($buf, 0, $n, $null, 0)
			$left -= $n
		}
		[void]$sha.TransformFinalBlock([byte[]]@(), 0, 0)
		return ([BitConverter]::ToString($sha.Hash) -replace '-', '').ToLowerInvariant()
	} catch {
		return $null
	} finally {
		if ($sha) { try { $sha.Dispose() } catch {} }
		if ($fs) { try { $fs.Dispose() } catch {} }
	}
}

function Get-MBPeIdentity {
	# SHA256 whole file + per-section; .NET / delay / bound hints for triage.
	param(
		[string]$Path,
		[bool]$SectionHashes = $true,
		$SymbolMap = $null
	)
	$out = [ordered]@{
		Ok = $false
		path = $Path
		file_size = 0L
		sha256 = $null
		sections = @()
		is_dotnet = $false
		dotnet_hint = $null
		delay_load = $null
		bound_import = $null
		Error = $null
	}
	try {
		if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
			$out.Error = 'not_found'; return $out
		}
		$fi = Get-Item -LiteralPath $Path
		$out.file_size = [long]$fi.Length
		$out.sha256 = Get-MBFileSha256Hex -Path $Path
		if ($null -eq $SymbolMap) {
			try { $SymbolMap = Get-MBPeSymbolMap -Path $Path } catch { $SymbolMap = $null }
		}
		if ($SymbolMap -and $SymbolMap.Ok) {
			$out.is_dotnet = [bool]$SymbolMap.IsDotNet
			if ($out.is_dotnet) {
				$out.dotnet_hint = 'Managed (.NET) binary — native x86 disasm at entry is often a thunk to _CorExeMain; prefer metadata/IL tools offline. HexView still useful for PE layout / native stubs.'
			}
			if ($SymbolMap.DelayDllCount -gt 0) {
				$out.delay_load = [ordered]@{
					dll_count = [int]$SymbolMap.DelayDllCount
					dlls = @($SymbolMap.DelayDlls | Select-Object -First 16)
					hint = 'Delay-load DLLs resolve at first call; IAT slots labeled with (delay).'
				}
			}
			if ($SymbolMap.BoundImportNote) {
				$out.bound_import = $SymbolMap.BoundImportNote
			}
			if ($SectionHashes -and $SymbolMap.Sections) {
				$secOut = New-Object System.Collections.ArrayList
				foreach ($s in @($SymbolMap.Sections)) {
					$rptr = [long][uint32]$s.raw_ptr
					$rsz = [long][uint32]$s.raw_size
					$h = $null
					if ($rsz -gt 0 -and $rptr -ge 0) {
						# Cap huge sections for responsiveness
						$take = $rsz
						if ($take -gt 64MB) { $take = 64MB }
						$h = Get-MBFileSha256Hex -Path $Path -Offset $rptr -Length $take
					}
					[void]$secOut.Add([ordered]@{
						name       = [string]$s.name
						raw_ptr    = $rptr
						raw_ptr_hex = ('0x{0:X}' -f $rptr)
						raw_size   = $rsz
						sha256     = $h
						sha256_truncated = ($rsz -gt 64MB)
					})
				}
				$out.sections = @($secOut)
			}
		} elseif ($SectionHashes) {
			# Non-PE: still have whole-file hash
			$out.sections = @()
		}
		$out.Ok = ($null -ne $out.sha256)
		if (-not $out.Ok -and -not $out.Error) { $out.Error = 'hash_failed' }
	} catch {
		$out.Error = $_.Exception.Message
	}
	return $out
}

function Find-MBX86Functions {
	# Heuristic function starts in a PE code section (prologues + INT3 padding).
	param(
		[string]$Path,
		[int]$MaxHits = 48,
		[string]$Section = '.text'
	)
	$hits = New-Object System.Collections.ArrayList
	$pe = $null
	try { $pe = Get-MBPeDisasmContext -Path $Path } catch { $pe = $null }
	if (-not $pe -or -not $pe.Ok) {
		return @{ Ok = $false; Error = 'not_pe'; functions = @() }
	}
	$is64 = [bool]$pe.Is64
	$sec = $null
	foreach ($s in @($pe.Sections)) {
		$sn = [string]$s.name
		if ([string]::Equals($sn, $Section, [StringComparison]::OrdinalIgnoreCase)) { $sec = $s; break }
		if ($sn.TrimStart('.') -eq $Section.TrimStart('.')) { $sec = $s; break }
	}
	if (-not $sec) {
		# pick first executable-looking: .text or first with EXEC-ish name
		foreach ($s in @($pe.Sections)) {
			if ([string]$s.name -match '(?i)text|code') { $sec = $s; break }
		}
		if (-not $sec -and $pe.Sections.Count -gt 0) { $sec = $pe.Sections[0] }
	}
	if (-not $sec -or [uint32]$sec.raw_size -eq 0) {
		return @{ Ok = $false; Error = 'no_code_section'; functions = @() }
	}
	$rptr = [long][uint32]$sec.raw_ptr
	$rsz = [long][uint32]$sec.raw_size
	if ($rsz -gt 4MB) { $rsz = 4MB } # scan cap
	$r = Read-MBFileBytes -Path $Path -Offset $rptr -Length ([int]$rsz)
	if (-not $r.Ok) { return @{ Ok = $false; Error = $r.Error; functions = @() } }
	$b = $r.Bytes
	$n = $b.Length
	if ($MaxHits -le 0) { $MaxHits = 48 }
	if ($MaxHits -gt 200) { $MaxHits = 200 }

	$patterns = New-Object System.Collections.ArrayList
	# x86
	[void]$patterns.Add(@{ bytes = [byte[]](0x55, 0x8B, 0xEC); name = 'push ebp; mov ebp,esp' })
	[void]$patterns.Add(@{ bytes = [byte[]](0x55, 0x89, 0xE5); name = 'push ebp; mov ebp,esp' })
	[void]$patterns.Add(@{ bytes = [byte[]](0x55, 0x8B, 0xE5); name = 'push ebp; mov ebp,esp?' })
	# x64
	[void]$patterns.Add(@{ bytes = [byte[]](0x48, 0x89, 0x5C, 0x24); name = 'mov [rsp+..],rbx' })
	[void]$patterns.Add(@{ bytes = [byte[]](0x48, 0x83, 0xEC); name = 'sub rsp, imm8' })
	[void]$patterns.Add(@{ bytes = [byte[]](0x48, 0x81, 0xEC); name = 'sub rsp, imm32' })
	[void]$patterns.Add(@{ bytes = [byte[]](0x40, 0x53); name = 'push rbx (rex)' })
	[void]$patterns.Add(@{ bytes = [byte[]](0x40, 0x55); name = 'push rbp (rex)' })
	[void]$patterns.Add(@{ bytes = [byte[]](0x55, 0x48, 0x8B, 0xEC); name = 'push rbp; mov rbp,rsp' })
	[void]$patterns.Add(@{ bytes = [byte[]](0x55, 0x48, 0x89, 0xE5); name = 'push rbp; mov rbp,rsp' })

	$seen = @{}
	$i = 0
	while ($i -lt $n -and $hits.Count -lt $MaxHits) {
		$matched = $false
		# INT3/NOP padding then code
		if ($b[$i] -eq 0xCC -or $b[$i] -eq 0x90) {
			$j = $i
			while ($j -lt $n -and ($b[$j] -eq 0xCC -or $b[$j] -eq 0x90)) { $j++ }
			if ($j -gt $i -and $j -lt $n -and $b[$j] -ne 0xCC) {
				# start after pad
				$abs = $rptr + $j
				$key = [string]$abs
				if (-not $seen.ContainsKey($key)) {
					$seen[$key] = $true
					[void]$hits.Add([ordered]@{
						offset = $abs
						offset_hex = ('0x{0:X}' -f $abs)
						kind = 'after_pad'
						pattern = $(if ($b[$i] -eq 0xCC) { 'int3_pad' } else { 'nop_pad' })
						section = [string]$sec.name
					})
					$matched = $true
				}
				$i = $j
				continue
			}
		}
		foreach ($p in $patterns) {
			$pb = $p.bytes
			if (($i + $pb.Length) -gt $n) { continue }
			$ok = $true
			for ($k = 0; $k -lt $pb.Length; $k++) {
				if ($b[$i + $k] -ne $pb[$k]) { $ok = $false; break }
			}
			if (-not $ok) { continue }
			$abs = $rptr + $i
			$key = [string]$abs
			if (-not $seen.ContainsKey($key)) {
				$seen[$key] = $true
				[void]$hits.Add([ordered]@{
					offset = $abs
					offset_hex = ('0x{0:X}' -f $abs)
					kind = 'prologue'
					pattern = [string]$p.name
					section = [string]$sec.name
				})
			}
			$matched = $true
			break
		}
		$i++
	}
	# Include entry if mapped
	if ($null -ne $pe.EntryFile) {
		$ek = [string][long]$pe.EntryFile
		if (-not $seen.ContainsKey($ek)) {
			$hits.Insert(0, [ordered]@{
				offset = [long]$pe.EntryFile
				offset_hex = ('0x{0:X}' -f [long]$pe.EntryFile)
				kind = 'entry'
				pattern = 'AddressOfEntryPoint'
				section = ''
			})
		}
	}
	return @{
		Ok = $true
		section = [string]$sec.name
		is64 = $is64
		count = $hits.Count
		functions = @($hits | Select-Object -First $MaxHits)
		hint = 'Heuristic only. HexView offset=<offset_hex> disasm=true to inspect.'
	}
}

function Get-MBFileEntropyMap {
	# Sliding-window Shannon entropy for packed/encrypted island detection.
	param(
		[string]$Path,
		[int]$BlockSize = 0,
		[int]$MaxBlocks = 256,
		[double]$HighThreshold = 7.0
	)
	$result = [ordered]@{
		Ok            = $false
		file_size     = 0L
		block_size    = 0
		blocks        = @()
		high_entropy  = @()
		mean_entropy  = 0.0
		max_entropy   = 0.0
		min_entropy   = 0.0
		Error         = $null
	}
	$fs = $null
	try {
		$fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		$len = $fs.Length
		$result.file_size = $len
		if ($len -le 0) { $result.Error = 'empty'; return $result }
		if ($BlockSize -le 0) {
			# Adaptive: aim for ~MaxBlocks windows
			$bs = [int][Math]::Ceiling([double]$len / [double][Math]::Max(1, $MaxBlocks))
			if ($bs -lt 256) { $bs = 256 }
			if ($bs -gt 65536) { $bs = 65536 }
			# Prefer power-of-two-ish sizes
			if ($bs -le 512) { $bs = 512 }
			elseif ($bs -le 1024) { $bs = 1024 }
			elseif ($bs -le 4096) { $bs = 4096 }
			elseif ($bs -le 16384) { $bs = 16384 }
			else { $bs = 65536 }
			$BlockSize = $bs
		}
		if ($BlockSize -lt 64) { $BlockSize = 64 }
		if ($BlockSize -gt 262144) { $BlockSize = 262144 }
		if ($MaxBlocks -le 0) { $MaxBlocks = 256 }
		if ($MaxBlocks -gt 1024) { $MaxBlocks = 1024 }
		$result.block_size = $BlockSize
		$buf = New-Object byte[] $BlockSize
		$hist = New-Object int[] 256
		$blocks = New-Object System.Collections.ArrayList
		$high = New-Object System.Collections.ArrayList
		$sumE = 0.0
		$maxE = 0.0
		$minE = 8.0
		$pos = 0L
		$bi = 0
		$log2 = [Math]::Log(2.0)
		while ($pos -lt $len -and $bi -lt $MaxBlocks) {
			$want = [int][Math]::Min([long]$BlockSize, $len - $pos)
			[void]$fs.Seek($pos, [System.IO.SeekOrigin]::Begin)
			$n = $fs.Read($buf, 0, $want)
			if ($n -le 0) { break }
			for ($h = 0; $h -lt 256; $h++) { $hist[$h] = 0 }
			for ($i = 0; $i -lt $n; $i++) { $hist[$buf[$i]]++ }
			$ent = 0.0
			$inv = 1.0 / [double]$n
			for ($h = 0; $h -lt 256; $h++) {
				$c = $hist[$h]
				if ($c -le 0) { continue }
				$p = $c * $inv
				$ent -= $p * ([Math]::Log($p) / $log2)
			}
			$rec = [ordered]@{
				offset     = $pos
				offset_hex = ('0x{0:X}' -f $pos)
				length     = $n
				entropy    = [Math]::Round($ent, 3)
			}
			[void]$blocks.Add($rec)
			$sumE += $ent
			if ($ent -gt $maxE) { $maxE = $ent }
			if ($ent -lt $minE) { $minE = $ent }
			if ($ent -ge $HighThreshold) {
				[void]$high.Add($rec)
			}
			$pos += $want
			$bi++
			# If file larger than MaxBlocks * BlockSize, sample remaining with stride
			if ($bi -ge $MaxBlocks) { break }
			if ($pos -lt $len -and (($len - $pos) / $BlockSize) -gt ($MaxBlocks - $bi)) {
				# jump ahead to cover file tail
				$remainBlocks = $MaxBlocks - $bi
				if ($remainBlocks -gt 1) {
					$stride = [long][Math]::Max($BlockSize, [long](($len - $pos) / $remainBlocks))
					# keep sequential for first portion; only stride when needed
				}
			}
		}
		$result.blocks = @($blocks)
		$result.high_entropy = @($high)
		$result.mean_entropy = if ($blocks.Count -gt 0) { [Math]::Round($sumE / $blocks.Count, 3) } else { 0.0 }
		$result.max_entropy = [Math]::Round($maxE, 3)
		$result.min_entropy = if ($blocks.Count -gt 0) { [Math]::Round($minE, 3) } else { 0.0 }
		$result.Ok = $true
		$result['hint'] = 'entropy near 8.0 suggests encrypted/compressed; low (~1-5) code/text. Use HexView offset= on high blocks or StringsScan.'
	} catch {
		$result.Error = $_.Exception.Message
	} finally {
		if ($fs) { try { $fs.Dispose() } catch {} }
	}
	return $result
}

function Find-MBEmbeddedMz {
	# Find nested MZ/PE images (overlay / dropped / appended PEs). Skips primary PE at offset 0.
	param(
		[string]$Path,
		[long]$StartOffset = 0,
		[int]$MaxHits = 16,
		[long]$MaxScan = 0
	)
	$hits = New-Object System.Collections.ArrayList
	$fs = $null
	try {
		$fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		$len = $fs.Length
		if ($MaxScan -le 0 -or $MaxScan -gt $len) { $MaxScan = $len }
		if ($StartOffset -lt 0) { $StartOffset = 0 }
		$end = [Math]::Min($len, $StartOffset + $MaxScan)
		$chunk = 1024 * 1024
		$buf = New-Object byte[] ($chunk + 4)
		$pos = $StartOffset
		while ($pos -lt $end -and $hits.Count -lt $MaxHits) {
			$want = [int][Math]::Min([long]$chunk + 1, $end - $pos)
			if ($want -lt 2) { break }
			[void]$fs.Seek($pos, [System.IO.SeekOrigin]::Begin)
			$n = $fs.Read($buf, 0, $want)
			if ($n -lt 2) { break }
			$i = 0
			while ($i -lt ($n - 1) -and $hits.Count -lt $MaxHits) {
				if ($buf[$i] -eq 0x4D -and $buf[$i + 1] -eq 0x5A) {
					$abs = $pos + $i
					# Skip trivial DOS header at 0 unless StartOffset forces it
					$valid = $false
					$peOff = $null
					$machine = ''
					$is64 = $false
					try {
						if (($abs + 0x40) -le $len) {
							[void]$fs.Seek($abs + 0x3C, [System.IO.SeekOrigin]::Begin)
							$lb = New-Object byte[] 4
							[void]$fs.Read($lb, 0, 4)
							$lf = [BitConverter]::ToInt32($lb, 0)
							if ($lf -ge 0x40 -and $lf -lt 0x1000 -and ($abs + $lf + 24) -le $len) {
								[void]$fs.Seek($abs + $lf, [System.IO.SeekOrigin]::Begin)
								$ps = New-Object byte[] 4
								[void]$fs.Read($ps, 0, 4)
								if ($ps[0] -eq 0x50 -and $ps[1] -eq 0x45 -and $ps[2] -eq 0 -and $ps[3] -eq 0) {
									$valid = $true
									$peOff = $abs + $lf
									$coff = New-Object byte[] 22
									[void]$fs.Read($coff, 0, 22)
									$mach = [BitConverter]::ToUInt16($coff, 0)
									$optMagic = [BitConverter]::ToUInt16($coff, 20)
									$is64 = ($optMagic -eq 0x20B)
									$machine = switch ($mach) {
										0x14c { 'i386' }
										0x8664 { 'AMD64' }
										0xAA64 { 'ARM64' }
										default { ('0x{0:X}' -f $mach) }
									}
								}
							}
						}
					} catch { $valid = $false }
					if ($valid) {
						if ($abs -eq 0 -and $StartOffset -eq 0) {
							# primary image — note but prefer nested
							[void]$hits.Add([ordered]@{
								offset      = 0L
								offset_hex  = '0x0'
								kind        = 'primary_pe'
								pe_offset   = $peOff
								machine     = $machine
								is64        = $is64
							})
						} else {
							[void]$hits.Add([ordered]@{
								offset      = $abs
								offset_hex  = ('0x{0:X}' -f $abs)
								kind        = 'embedded_pe'
								pe_offset   = $peOff
								pe_offset_hex = ('0x{0:X}' -f $peOff)
								machine     = $machine
								is64        = $is64
								hint        = 'HexView path= offset=this disasm/annotate; or extract with ReadFileBytes slice / copy'
							})
						}
					}
					$i += 2
					continue
				}
				$i++
			}
			# overlap 1 byte for MZ spanning chunks
			$pos += [Math]::Max(1, $n - 1)
		}
	} catch {
		return @{ Ok = $false; Error = $_.Exception.Message; hits = @() }
	} finally {
		if ($fs) { try { $fs.Dispose() } catch {} }
	}
	$embedded = @($hits | Where-Object { $_.kind -eq 'embedded_pe' })
	return @{
		Ok = $true
		hits = @($hits)
		embedded_count = $embedded.Count
		embedded = $embedded
	}
}

function Convert-MBHexPatternToBytesAndMask {
	# "4D 5A ?? 00" or "4D5A??00" -> byte[] pattern + bool[] mask (true=must match)
	param([string]$Pattern)
	$p = ([string]$Pattern).Trim()
	if ([string]::IsNullOrWhiteSpace($p)) { throw 'Empty hex pattern' }
	$p = $p -replace '[,\-:]', ' '
	$p = $p -replace '\s+', ' '
	$tokens = @()
	if ($p -match '\s' -or $p -match '\?') {
		# split by space; also split contiguous hex into pairs when no spaces
		foreach ($t in ($p -split ' ')) {
			if ([string]::IsNullOrWhiteSpace($t)) { continue }
			if ($t -eq '??' -or $t -eq '?') { $tokens += '??'; continue }
			if ($t -match '^[0-9A-Fa-f]{2}$') { $tokens += $t.ToUpperInvariant(); continue }
			if ($t -match '^[0-9A-Fa-f?]+$') {
				$s = $t
				if (($s.Length % 2) -ne 0) { throw "Odd-length hex token: $t" }
				for ($i = 0; $i -lt $s.Length; $i += 2) {
					$pair = $s.Substring($i, 2)
					if ($pair -eq '??' -or $pair -match '\?') { $tokens += '??' }
					else { $tokens += $pair.ToUpperInvariant() }
				}
				continue
			}
			throw "Invalid hex token: $t"
		}
	} else {
		$s = $p
		if (($s.Length % 2) -ne 0) { throw 'Odd-length hex pattern' }
		for ($i = 0; $i -lt $s.Length; $i += 2) {
			$pair = $s.Substring($i, 2)
			if ($pair -eq '??') { $tokens += '??' }
			else { $tokens += $pair.ToUpperInvariant() }
		}
	}
	if ($tokens.Count -eq 0) { throw 'No pattern bytes' }
	if ($tokens.Count -gt 4096) { throw 'Pattern too long (max 4096 bytes)' }
	$bytes = New-Object byte[] $tokens.Count
	$mask = New-Object bool[] $tokens.Count
	for ($i = 0; $i -lt $tokens.Count; $i++) {
		if ($tokens[$i] -eq '??') {
			$bytes[$i] = 0
			$mask[$i] = $false
		} else {
			$bytes[$i] = [Convert]::ToByte($tokens[$i], 16)
			$mask[$i] = $true
		}
	}
	return @{ Bytes = $bytes; Mask = $mask; Length = $tokens.Count }
}

function Find-MBHexPattern {
	param(
		[string]$Path,
		[string]$Pattern,
		[long]$Offset = 0,
		[int]$MaxResults = 32,
		[long]$MaxScan = 0
	)
	$pm = Convert-MBHexPatternToBytesAndMask -Pattern $Pattern
	$pat = $pm.Bytes
	$mask = $pm.Mask
	$patLen = $pm.Length
	$hits = New-Object System.Collections.ArrayList
	$fs = $null
	try {
		$fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		$len = $fs.Length
		if ($Offset -lt 0) { $Offset = 0 }
		if ($Offset -ge $len) {
			return @{ Ok = $true; hits = @(); pattern_len = $patLen; scanned = 0; note = 'offset past EOF' }
		}
		$scanEnd = $len
		if ($MaxScan -gt 0) { $scanEnd = [Math]::Min($len, $Offset + $MaxScan) }
		if ($MaxResults -le 0) { $MaxResults = 32 }
		if ($MaxResults -gt 500) { $MaxResults = 500 }
		# Stream with overlap
		$chunk = 1024 * 1024
		$overlap = $patLen - 1
		if ($overlap -lt 0) { $overlap = 0 }
		$buf = New-Object byte[] ($chunk + $overlap + $patLen)
		$pos = $Offset
		$scanned = 0L
		while ($pos -lt $scanEnd -and $hits.Count -lt $MaxResults) {
			$want = [int][Math]::Min([long]$chunk + $overlap, $scanEnd - $pos)
			if ($want -lt $patLen) { break }
			[void]$fs.Seek($pos, [System.IO.SeekOrigin]::Begin)
			$n = $fs.Read($buf, 0, $want)
			if ($n -lt $patLen) { break }
			$scanned += $n
			$limit = $n - $patLen
			for ($i = 0; $i -le $limit -and $hits.Count -lt $MaxResults; $i++) {
				$ok = $true
				for ($j = 0; $j -lt $patLen; $j++) {
					if ($mask[$j] -and $buf[$i + $j] -ne $pat[$j]) { $ok = $false; break }
				}
				if (-not $ok) { continue }
				$abs = $pos + $i
				$ctxLen = [Math]::Min(16, $patLen + 8)
				$ctx = New-Object System.Collections.Generic.List[string]
				for ($k = 0; $k -lt $ctxLen -and ($i + $k) -lt $n; $k++) {
					[void]$ctx.Add(('{0:X2}' -f $buf[$i + $k]))
				}
				[void]$hits.Add([ordered]@{
					offset     = $abs
					offset_hex = ('0x{0:X}' -f $abs)
					bytes      = ($ctx -join ' ')
				})
				# skip ahead by 1 to find overlapping matches
			}
			$step = $n - $overlap
			if ($step -lt 1) { $step = 1 }
			$pos += $step
		}
		return @{
			Ok          = $true
			path        = $Path
			pattern_len = $patLen
			hits        = @($hits)
			count       = $hits.Count
			scanned     = $scanned
			truncated   = ($hits.Count -ge $MaxResults)
		}
	} catch {
		return @{ Ok = $false; Error = $_.Exception.Message; hits = @() }
	} finally {
		if ($fs) { try { $fs.Dispose() } catch {} }
	}
}

function Get-MBFileStrings {
	# Full-file ASCII / UTF-16LE string extraction with optional filters.
	param(
		[string]$Path,
		[int]$MinLen = 4,
		[int]$MaxHits = 80,
		[long]$Offset = 0,
		[long]$MaxScan = 0,
		[string]$Encoding = 'both', # ascii | utf16 | both
		[string]$Filter = ''        # path|url|ip|registry|email|all or free substring
	)
	if ($MinLen -lt 3) { $MinLen = 3 }
	if ($MinLen -gt 64) { $MinLen = 64 }
	if ($MaxHits -le 0) { $MaxHits = 80 }
	if ($MaxHits -gt 500) { $MaxHits = 500 }
	$encMode = ([string]$Encoding).ToLowerInvariant()
	if ($encMode -notin @('ascii', 'utf16', 'utf16le', 'both', 'all')) { $encMode = 'both' }
	if ($encMode -eq 'all') { $encMode = 'both' }
	if ($encMode -eq 'utf16le') { $encMode = 'utf16' }
	$filt = ([string]$Filter).Trim().ToLowerInvariant()
	$useClass = $filt -in @('path', 'url', 'ip', 'registry', 'email', 'all', 'interesting')
	$testInteresting = {
		param([string]$S)
		if ([string]::IsNullOrEmpty($S)) { return $false }
		if ($filt -eq '' -or $filt -eq 'all' -or $filt -eq 'interesting') {
			if ($S -match '(?i)https?://|\\\\[a-z0-9]|[A-Za-z]:\\|/bin/|cmd\.exe|powershell|CreateFile|VirtualAlloc|LoadLibrary|GetProcAddress|HKEY_|SOFTWARE\\') { return $true }
			if ($S -match '\b\d{1,3}(\.\d{1,3}){3}\b') { return $true }
			if ($S -match '(?i)[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}') { return $true }
			return $false
		}
		switch ($filt) {
			'path' { return ($S -match '(?i)[A-Za-z]:\\|\\\\|/usr/|/etc/|\.dll|\.exe|\.sys') }
			'url' { return ($S -match '(?i)https?://|ftp://|www\.') }
			'ip' { return ($S -match '\b\d{1,3}(\.\d{1,3}){3}\b') }
			'registry' { return ($S -match '(?i)HKEY_|HKLM|HKCU|SOFTWARE\\|SYSTEM\\') }
			'email' { return ($S -match '(?i)[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}') }
			default { return ($S.ToLowerInvariant().Contains($filt)) }
		}
	}
	$hits = New-Object System.Collections.ArrayList
	$fs = $null
	try {
		$fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		$len = $fs.Length
		if ($Offset -lt 0) { $Offset = 0 }
		$scanEnd = $len
		if ($MaxScan -gt 0) { $scanEnd = [Math]::Min($len, $Offset + $MaxScan) }
		$chunk = 512 * 1024
		# ASCII
		if ($encMode -in @('ascii', 'both')) {
			$buf = New-Object byte[] $chunk
			$pos = $Offset
			$run = New-Object System.Collections.Generic.List[byte]
			$runStart = -1L
			while ($pos -lt $scanEnd -and $hits.Count -lt $MaxHits) {
				$want = [int][Math]::Min([long]$chunk, $scanEnd - $pos)
				[void]$fs.Seek($pos, [System.IO.SeekOrigin]::Begin)
				$n = $fs.Read($buf, 0, $want)
				if ($n -le 0) { break }
				for ($i = 0; $i -lt $n -and $hits.Count -lt $MaxHits; $i++) {
					$b = $buf[$i]
					if ($b -ge 32 -and $b -le 126) {
						if ($run.Count -eq 0) { $runStart = $pos + $i }
						[void]$run.Add($b)
					} else {
						if ($run.Count -ge $MinLen) {
							$s = [System.Text.Encoding]::ASCII.GetString($run.ToArray())
							$pass = if ($filt) { & $testInteresting $s } else { $true }
							if ($pass) {
								$show = $s
								if ($show.Length -gt 160) { $show = $show.Substring(0, 157) + '...' }
								[void]$hits.Add([ordered]@{
									offset = $runStart
									offset_hex = ('0x{0:X}' -f $runStart)
									encoding = 'ascii'
									length = $run.Count
									text = $show
								})
							}
						}
						$run.Clear()
						$runStart = -1L
					}
				}
				$pos += $n
			}
			if ($run.Count -ge $MinLen -and $hits.Count -lt $MaxHits) {
				$s = [System.Text.Encoding]::ASCII.GetString($run.ToArray())
				$pass = if ($filt) { & $testInteresting $s } else { $true }
				if ($pass) {
					$show = $s
					if ($show.Length -gt 160) { $show = $show.Substring(0, 157) + '...' }
					[void]$hits.Add([ordered]@{
						offset = $runStart
						offset_hex = ('0x{0:X}' -f $runStart)
						encoding = 'ascii'
						length = $run.Count
						text = $show
					})
				}
			}
		}
		# UTF-16LE
		if ($encMode -in @('utf16', 'both') -and $hits.Count -lt $MaxHits) {
			$buf = New-Object byte[] $chunk
			$pos = $Offset
			if (($pos % 2) -ne 0) { $pos++ }
			$chars = New-Object System.Collections.Generic.List[char]
			$runStart = -1L
			while ($pos -lt $scanEnd -and $hits.Count -lt $MaxHits) {
				$want = [int][Math]::Min([long]$chunk, $scanEnd - $pos)
				if (($want % 2) -ne 0) { $want-- }
				if ($want -lt 2) { break }
				[void]$fs.Seek($pos, [System.IO.SeekOrigin]::Begin)
				$n = $fs.Read($buf, 0, $want)
				if ($n -lt 2) { break }
				if (($n % 2) -ne 0) { $n-- }
				for ($i = 0; $i -lt $n -and $hits.Count -lt $MaxHits; $i += 2) {
					$ch = [int]$buf[$i] -bor ([int]$buf[$i + 1] -shl 8)
					$isPrint = ($ch -ge 32 -and $ch -le 126)
					if ($isPrint) {
						if ($chars.Count -eq 0) { $runStart = $pos + $i }
						[void]$chars.Add([char]$ch)
					} else {
						if ($chars.Count -ge $MinLen) {
							$s = -join $chars
							$pass = if ($filt) { & $testInteresting $s } else { $true }
							if ($pass) {
								$show = $s
								if ($show.Length -gt 160) { $show = $show.Substring(0, 157) + '...' }
								[void]$hits.Add([ordered]@{
									offset = $runStart
									offset_hex = ('0x{0:X}' -f $runStart)
									encoding = 'utf16le'
									length = $chars.Count
									text = $show
								})
							}
						}
						$chars.Clear()
						$runStart = -1L
					}
				}
				$pos += $n
			}
		}
		return @{
			Ok = $true
			path = $Path
			min_len = $MinLen
			filter = $(if ($filt) { $filt } else { $null })
			encoding = $encMode
			count = $hits.Count
			hits = @($hits)
			truncated = ($hits.Count -ge $MaxHits)
		}
	} catch {
		return @{ Ok = $false; Error = $_.Exception.Message; hits = @() }
	} finally {
		if ($fs) { try { $fs.Dispose() } catch {} }
	}
}

function Get-MBFileMagicAnnotations {
	# Common container/image/archive magic at file start (testing builds/artifacts).
	param(
		[string]$Path,
		[byte[]]$HeadBytes = $null
	)
	$notes = New-Object System.Collections.ArrayList
	$b = $HeadBytes
	if ($null -eq $b -or $b.Length -lt 4) {
		try {
			$r = Read-MBFileBytes -Path $Path -Offset 0 -Length 32
			if ($r.Ok) { $b = $r.Bytes }
		} catch { $b = $null }
	}
	if ($null -eq $b -or $b.Length -lt 2) { return @() }
	$add = {
		param([long]$Off, [string]$Text, [string]$Kind = 'magic')
		[void]$notes.Add([ordered]@{ offset = $Off; kind = $Kind; text = $Text })
	}.GetNewClosure()
	# PE/DOS
	if ($b.Length -ge 2 -and $b[0] -eq 0x4D -and $b[1] -eq 0x5A) {
		& $add 0 'Magic: MZ (DOS/PE executable or image)'
	}
	# ELF
	elseif ($b.Length -ge 4 -and $b[0] -eq 0x7F -and $b[1] -eq 0x45 -and $b[2] -eq 0x4C -and $b[3] -eq 0x46) {
		& $add 0 'Magic: ELF executable/object'
	}
	# ZIP / JAR / DOCX / APK (PK..)
	elseif ($b.Length -ge 4 -and $b[0] -eq 0x50 -and $b[1] -eq 0x4B -and ($b[2] -eq 0x03 -or $b[2] -eq 0x05 -or $b[2] -eq 0x07)) {
		& $add 0 'Magic: ZIP/PK archive (zip/jar/apk/office container)'
	}
	# PNG
	elseif ($b.Length -ge 8 -and $b[0] -eq 0x89 -and $b[1] -eq 0x50 -and $b[2] -eq 0x4E -and $b[3] -eq 0x47) {
		& $add 0 'Magic: PNG image'
	}
	# JPEG
	elseif ($b.Length -ge 3 -and $b[0] -eq 0xFF -and $b[1] -eq 0xD8 -and $b[2] -eq 0xFF) {
		& $add 0 'Magic: JPEG image'
	}
	# GIF
	elseif ($b.Length -ge 6 -and $b[0] -eq 0x47 -and $b[1] -eq 0x49 -and $b[2] -eq 0x46) {
		& $add 0 'Magic: GIF image'
	}
	# BMP
	elseif ($b.Length -ge 2 -and $b[0] -eq 0x42 -and $b[1] -eq 0x4D) {
		& $add 0 'Magic: BMP image'
	}
	# PDF
	elseif ($b.Length -ge 5 -and $b[0] -eq 0x25 -and $b[1] -eq 0x50 -and $b[2] -eq 0x44 -and $b[3] -eq 0x46) {
		& $add 0 'Magic: PDF document'
	}
	# 7z
	elseif ($b.Length -ge 6 -and $b[0] -eq 0x37 -and $b[1] -eq 0x7A -and $b[2] -eq 0xBC -and $b[3] -eq 0xAF) {
		& $add 0 'Magic: 7z archive'
	}
	# RAR
	elseif ($b.Length -ge 4 -and $b[0] -eq 0x52 -and $b[1] -eq 0x61 -and $b[2] -eq 0x72 -and $b[3] -eq 0x21) {
		& $add 0 'Magic: RAR archive'
	}
	# GZIP
	elseif ($b.Length -ge 2 -and $b[0] -eq 0x1F -and $b[1] -eq 0x8B) {
		& $add 0 'Magic: GZIP compressed'
	}
	# CAB
	elseif ($b.Length -ge 4 -and $b[0] -eq 0x4D -and $b[1] -eq 0x53 -and $b[2] -eq 0x43 -and $b[3] -eq 0x46) {
		& $add 0 'Magic: Microsoft CAB archive'
	}
	# MSI/OLE compound (D0 CF 11 E0)
	elseif ($b.Length -ge 4 -and $b[0] -eq 0xD0 -and $b[1] -eq 0xCF -and $b[2] -eq 0x11 -and $b[3] -eq 0xE0) {
		& $add 0 'Magic: OLE/CFB compound (doc/xls/msi/etc.)'
	}
	# WAV / RIFF
	elseif ($b.Length -ge 12 -and $b[0] -eq 0x52 -and $b[1] -eq 0x49 -and $b[2] -eq 0x46 -and $b[3] -eq 0x46) {
		$four = ''
		try { $four = [System.Text.Encoding]::ASCII.GetString($b, 8, 4) } catch {}
		& $add 0 ("Magic: RIFF container{0}" -f $(if ($four) { " ($four)" } else { '' }))
	}
	# ISO 9660 (CD001 at 0x8001 etc) - check if length allows
	try {
		$iso = Read-MBFileBytes -Path $Path -Offset 0x8001 -Length 5
		if ($iso.Ok -and $iso.Bytes.Length -ge 5) {
			$sig = [System.Text.Encoding]::ASCII.GetString($iso.Bytes)
			if ($sig -eq 'CD001') { & $add 0x8001 'Magic: ISO 9660 primary volume (CD001)' }
		}
	} catch {}
	return @($notes)
}

function Get-MBControlCharAnnotations {
	# Label control / DEL bytes in the viewed window (for test binary inspection).
	param(
		[byte[]]$Bytes,
		[long]$BaseOffset = 0,
		[int]$MaxHits = 48
	)
	$out = New-Object System.Collections.ArrayList
	if ($null -eq $Bytes) { return @() }
	# Aggregate runs of same control for readability
	$i = 0
	while ($i -lt $Bytes.Length -and $out.Count -lt $MaxHits) {
		$b = $Bytes[$i]
		$nm = Get-MBControlCharName -B $b
		if ($nm) {
			$start = $i
			while ($i -lt $Bytes.Length -and $Bytes[$i] -eq $b) { $i++ }
			$len = $i - $start
			$txt = if ($len -gt 1) { ("{0} x{1}" -f $nm, $len) } else { $nm }
			[void]$out.Add([ordered]@{
				offset = ($BaseOffset + $start)
				length = $len
				kind   = 'control'
				byte   = ('0x{0:X2}' -f $b)
				text   = $txt
			})
		} else {
			$i++
		}
	}
	return @($out)
}

function Get-MBPeAnnotations {
	# PE/COFF map for test binaries: headers, sections, dirs, imports (no disassembler).
	param([string]$Path)
	$notes = New-Object System.Collections.ArrayList
	$sections = New-Object System.Collections.ArrayList
	$fs = $null
	try {
		$fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		if ($fs.Length -lt 64) { return @() }
		$hdr = New-Object byte[] 64
		[void]$fs.Read($hdr, 0, 64)
		if ($hdr[0] -ne 0x4D -or $hdr[1] -ne 0x5A) { return @() } # MZ
		$e_lfanew = [BitConverter]::ToInt32($hdr, 0x3C)
		if ($e_lfanew -le 0 -or ($e_lfanew + 24) -gt $fs.Length) {
			[void]$notes.Add([ordered]@{ offset = 0; kind = 'pe'; text = 'MZ header (invalid e_lfanew)' })
			return @($notes)
		}
		[void]$notes.Add([ordered]@{ offset = 0; kind = 'pe'; text = 'DOS MZ header' })
		[void]$notes.Add([ordered]@{ offset = 0x3C; kind = 'pe'; text = ('e_lfanew -> 0x{0:X}' -f $e_lfanew) })
		# DOS stub region
		if ($e_lfanew -gt 0x40) {
			[void]$notes.Add([ordered]@{ offset = 0x40; kind = 'pe'; text = ('DOS stub region (to PE at 0x{0:X})' -f $e_lfanew) })
		}
		[void]$fs.Seek([long]$e_lfanew, [System.IO.SeekOrigin]::Begin)
		$peSig = New-Object byte[] 4
		[void]$fs.Read($peSig, 0, 4)
		if ($peSig[0] -ne 0x50 -or $peSig[1] -ne 0x45 -or $peSig[2] -ne 0 -or $peSig[3] -ne 0) {
			[void]$notes.Add([ordered]@{ offset = $e_lfanew; kind = 'pe'; text = 'PE signature missing' })
			return @($notes)
		}
		[void]$notes.Add([ordered]@{ offset = $e_lfanew; kind = 'pe'; text = 'PE signature (PE\0\0)' })
		$coff = New-Object byte[] 20
		[void]$fs.Read($coff, 0, 20)
		$machine = [BitConverter]::ToUInt16($coff, 0)
		$numSec = [BitConverter]::ToUInt16($coff, 2)
		$timedate = [BitConverter]::ToUInt32($coff, 4)
		$chars = [BitConverter]::ToUInt16($coff, 18)
		$optSize = [BitConverter]::ToUInt16($coff, 16)
		$machName = switch ($machine) {
			0x14c { 'i386' }
			0x8664 { 'AMD64' }
			0xAA64 { 'ARM64' }
			0x1c0 { 'ARM' }
			0x1c4 { 'ARMv7' }
			0x200 { 'IA64' }
			default { ('0x{0:X}' -f $machine) }
		}
		$charBits = New-Object System.Collections.ArrayList
		if ($chars -band 0x0002) { [void]$charBits.Add('EXECUTABLE') }
		if ($chars -band 0x2000) { [void]$charBits.Add('DLL') }
		if ($chars -band 0x0020) { [void]$charBits.Add('LARGE_ADDRESS_AWARE') }
		if ($chars -band 0x0100) { [void]$charBits.Add('32BIT_MACHINE') }
		if ($chars -band 0x0001) { [void]$charBits.Add('RELOCS_STRIPPED') }
		$charTxt = if ($charBits.Count -gt 0) { ($charBits -join '|') } else { ('0x{0:X}' -f $chars) }
		[void]$notes.Add([ordered]@{
			offset = ($e_lfanew + 4)
			kind   = 'pe'
			text   = ("COFF Machine={0} Sections={1} Characteristics={2}" -f $machName, $numSec, $charTxt)
		})
		if ($timedate -gt 0) {
			try {
				$epoch = [DateTime]::new(1970, 1, 1, 0, 0, 0, [DateTimeKind]::Utc).AddSeconds([double]$timedate)
				[void]$notes.Add([ordered]@{
					offset = ($e_lfanew + 8)
					kind   = 'pe'
					text   = ('TimeDateStamp {0:yyyy-MM-dd HH:mm:ss}Z (0x{1:X})' -f $epoch, $timedate)
				})
			} catch {
				[void]$notes.Add([ordered]@{ offset = ($e_lfanew + 8); kind = 'pe'; text = ('TimeDateStamp 0x{0:X}' -f $timedate) })
			}
		}
		$optOff = $e_lfanew + 24
		$isPE32Plus = $false
		$isPE32 = $false
		$epRva = [uint32]0
		$imgBase = [uint64]0
		$sectionAlign = [uint32]0
		$fileAlign = [uint32]0
		$subsystem = [uint16]0
		$numRvaSizes = 0
		$dataDirOff = 0
		if ($optSize -ge 2 -and ($optOff + $optSize) -le $fs.Length) {
			[void]$fs.Seek([long]$optOff, [System.IO.SeekOrigin]::Begin)
			$opt = New-Object byte[] ([Math]::Min([int]$optSize, 384))
			[void]$fs.Read($opt, 0, $opt.Length)
			$magic = [BitConverter]::ToUInt16($opt, 0)
			$isPE32Plus = ($magic -eq 0x20B)
			$isPE32 = ($magic -eq 0x10B)
			if ($isPE32 -or $isPE32Plus) {
				$epRva = [BitConverter]::ToUInt32($opt, 16)
				$codeBase = [BitConverter]::ToUInt32($opt, 20)
				if ($isPE32Plus -and $opt.Length -ge 32) {
					$imgBase = [BitConverter]::ToUInt64($opt, 24)
					if ($opt.Length -ge 40) {
						$sectionAlign = [BitConverter]::ToUInt32($opt, 32)
						$fileAlign = [BitConverter]::ToUInt32($opt, 36)
					}
					if ($opt.Length -ge 72) { $subsystem = [BitConverter]::ToUInt16($opt, 68) }
					# DataDirectory starts at optional+112 for PE32+
					$dataDirOff = $optOff + 112
					if ($opt.Length -ge 110) { $numRvaSizes = [BitConverter]::ToInt32($opt, 108) }
				} elseif ($opt.Length -ge 32) {
					$imgBase = [uint64][BitConverter]::ToUInt32($opt, 28)
					if ($opt.Length -ge 40) {
						$sectionAlign = [BitConverter]::ToUInt32($opt, 32)
						$fileAlign = [BitConverter]::ToUInt32($opt, 36)
					}
					if ($opt.Length -ge 72) { $subsystem = [BitConverter]::ToUInt16($opt, 68) }
					$dataDirOff = $optOff + 96
					if ($opt.Length -ge 96) { $numRvaSizes = [BitConverter]::ToInt32($opt, 92) }
				}
				$subName = switch ([int]$subsystem) {
					1 { 'Native' }
					2 { 'Windows GUI' }
					3 { 'Windows CUI' }
					5 { 'OS/2 CUI' }
					7 { 'POSIX CUI' }
					9 { 'Windows CE' }
					10 { 'EFI app' }
					11 { 'EFI boot driver' }
					12 { 'EFI runtime driver' }
					13 { 'EFI ROM' }
					14 { 'Xbox' }
					16 { 'Windows boot app' }
					default { ('0x{0:X}' -f $subsystem) }
				}
				[void]$notes.Add([ordered]@{
					offset = $optOff
					kind   = 'pe'
					text   = ('OptionalHeader {0} EntryPointRVA=0x{1:X} ImageBase=0x{2:X} Subsystem={3}' -f $(if ($isPE32Plus) { 'PE32+' } else { 'PE32' }), $epRva, $imgBase, $subName)
				})
				[void]$notes.Add([ordered]@{
					offset = ($optOff + 16)
					kind   = 'pe'
					text   = ('AddressOfEntryPoint RVA 0x{0:X}' -f $epRva)
				})
				if ($codeBase -gt 0) {
					[void]$notes.Add([ordered]@{ offset = ($optOff + 20); kind = 'pe'; text = ('BaseOfCode RVA 0x{0:X}' -f $codeBase) })
				}
				if ($sectionAlign -gt 0) {
					[void]$notes.Add([ordered]@{
						offset = $optOff
						kind   = 'pe'
						text   = ('SectionAlign=0x{0:X} FileAlign=0x{1:X}' -f $sectionAlign, $fileAlign)
					})
				}
			}
		}
		$secOff = $e_lfanew + 24 + $optSize
		$maxSec = [Math]::Min([int]$numSec, 48)
		for ($s = 0; $s -lt $maxSec; $s++) {
			$so = $secOff + ($s * 40)
			if (($so + 40) -gt $fs.Length) { break }
			[void]$fs.Seek([long]$so, [System.IO.SeekOrigin]::Begin)
			$sec = New-Object byte[] 40
			[void]$fs.Read($sec, 0, 40)
			$nameBytes = New-Object byte[] 8
			[Array]::Copy($sec, 0, $nameBytes, 0, 8)
			$name = [System.Text.Encoding]::ASCII.GetString($nameBytes).TrimEnd([char]0)
			$vsize = [BitConverter]::ToUInt32($sec, 8)
			$vrva = [BitConverter]::ToUInt32($sec, 12)
			$rsize = [BitConverter]::ToUInt32($sec, 16)
			$rptr = [BitConverter]::ToUInt32($sec, 20)
			$schars = [BitConverter]::ToUInt32($sec, 36)
			$sflags = New-Object System.Collections.ArrayList
			if ($schars -band 0x20) { [void]$sflags.Add('CODE') }
			if ($schars -band 0x40) { [void]$sflags.Add('IDATA') }
			if ($schars -band 0x80) { [void]$sflags.Add('UDATA') }
			if ($schars -band 0x20000000) { [void]$sflags.Add('EXEC') }
			if ($schars -band 0x40000000) { [void]$sflags.Add('READ') }
			if ($schars -band 0x80000000) { [void]$sflags.Add('WRITE') }
			$sflagTxt = if ($sflags.Count -gt 0) { ($sflags -join '|') } else { ('0x{0:X}' -f $schars) }
			$secObj = [ordered]@{
				name      = $name
				virt_rva  = $vrva
				virt_size = $vsize
				raw_ptr   = $rptr
				raw_size  = $rsize
				chars     = $schars
			}
			[void]$sections.Add($secObj)
			[void]$notes.Add([ordered]@{
				offset    = $so
				kind      = 'pe_section'
				text      = ('Section "{0}" VA=0x{1:X} VSize=0x{2:X} RawPtr=0x{3:X} RawSize=0x{4:X} [{5}]' -f $name, $vrva, $vsize, $rptr, $rsize, $sflagTxt)
				section   = $name
				raw_ptr   = $rptr
				raw_size  = $rsize
				virt_rva  = $vrva
				virt_size = $vsize
			})
			if ($rptr -gt 0) {
				[void]$notes.Add([ordered]@{
					offset  = [long]$rptr
					kind    = 'pe_section_data'
					text    = ('Start of section "{0}" raw data' -f $name)
					section = $name
				})
				if ($rsize -gt 0) {
					$endRaw = [long]$rptr + [long]$rsize - 1
					if ($endRaw -gt 0 -and $endRaw -lt $fs.Length) {
						[void]$notes.Add([ordered]@{
							offset  = $endRaw
							kind    = 'pe_section_data'
							text    = ('End of section "{0}" raw data' -f $name)
							section = $name
						})
					}
				}
			}
		}
		# Entry point file offset
		if ($epRva -gt 0 -and $sections.Count -gt 0) {
			$epFile = Convert-MBPeRvaToOffset -Sections $sections -Rva $epRva
			if ($null -ne $epFile) {
				[void]$notes.Add([ordered]@{
					offset = [long]$epFile
					kind   = 'pe_entry'
					text   = ('Entry point file offset 0x{0:X} (RVA 0x{1:X}, ImageBase+RVA VA 0x{2:X})' -f $epFile, $epRva, ($imgBase + $epRva))
					rva    = $epRva
				})
			} else {
				[void]$notes.Add([ordered]@{
					offset = $optOff + 16
					kind   = 'pe_entry'
					text   = ('Entry point RVA 0x{0:X} (no section mapping for file offset)' -f $epRva)
					rva    = $epRva
				})
			}
		}
		# Data directories
		$dirNames = @(
			'Export','Import','Resource','Exception','Security','BaseReloc','Debug','Architecture',
			'GlobalPtr','TLS','LoadConfig','BoundImport','IAT','DelayImport','CLR','Reserved'
		)
		if ($numRvaSizes -le 0) { $numRvaSizes = 16 }
		if ($numRvaSizes -gt 16) { $numRvaSizes = 16 }
		if ($dataDirOff -gt 0) {
			for ($d = 0; $d -lt $numRvaSizes; $d++) {
				$do = $dataDirOff + ($d * 8)
				if (($do + 8) -gt $fs.Length) { break }
				[void]$fs.Seek([long]$do, [System.IO.SeekOrigin]::Begin)
				$db = New-Object byte[] 8
				[void]$fs.Read($db, 0, 8)
				$drva = [BitConverter]::ToUInt32($db, 0)
				$dsz = [BitConverter]::ToUInt32($db, 4)
				if ($drva -eq 0 -and $dsz -eq 0) { continue }
				$dname = if ($d -lt $dirNames.Count) { $dirNames[$d] } else { ("Dir{0}" -f $d) }
				$fo = Convert-MBPeRvaToOffset -Sections $sections -Rva $drva
				$foTxt = if ($null -ne $fo) { (' file=0x{0:X}' -f $fo) } else { '' }
				[void]$notes.Add([ordered]@{
					offset = $(if ($null -ne $fo) { [long]$fo } else { [long]$do })
					kind   = 'pe_dir'
					text   = ('DataDir[{0}] {1} RVA=0x{2:X} Size=0x{3:X}{4}' -f $d, $dname, $drva, $dsz, $foTxt)
					rva    = $drva
					size   = $dsz
					dir    = $dname
				})
			}
			# Import DLL names (first N)
			try {
				$impNote = $notes | Where-Object { $_.dir -eq 'Import' } | Select-Object -First 1
				if ($impNote -and $impNote.rva) {
					$impFile = Convert-MBPeRvaToOffset -Sections $sections -Rva ([uint32]$impNote.rva)
					if ($null -ne $impFile) {
						$maxDll = 24
						$dllCount = 0
						$descOff = [long]$impFile
						while ($dllCount -lt $maxDll) {
							if (($descOff + 20) -gt $fs.Length) { break }
							[void]$fs.Seek($descOff, [System.IO.SeekOrigin]::Begin)
							$desc = New-Object byte[] 20
							[void]$fs.Read($desc, 0, 20)
							$oft = [BitConverter]::ToUInt32($desc, 0)
							$nameRva = [BitConverter]::ToUInt32($desc, 12)
							$ft = [BitConverter]::ToUInt32($desc, 16)
							if ($oft -eq 0 -and $nameRva -eq 0 -and $ft -eq 0) { break }
							$nameOff = Convert-MBPeRvaToOffset -Sections $sections -Rva $nameRva
							$dllName = ''
							if ($null -ne $nameOff) {
								[void]$fs.Seek([long]$nameOff, [System.IO.SeekOrigin]::Begin)
								$nb = New-Object byte[] 128
								$nr = $fs.Read($nb, 0, 128)
								$end = 0
								while ($end -lt $nr -and $nb[$end] -ne 0) { $end++ }
								if ($end -gt 0) {
									$dllName = [System.Text.Encoding]::ASCII.GetString($nb, 0, $end)
								}
							}
							if ($dllName) {
								[void]$notes.Add([ordered]@{
									offset = [long]$nameOff
									kind   = 'pe_import'
									text   = ('Import DLL: {0}' -f $dllName)
									dll    = $dllName
								})
							}
							$dllCount++
							$descOff += 20
						}
						if ($dllCount -gt 0) {
							[void]$notes.Add([ordered]@{
								offset = [long]$impFile
								kind   = 'pe_import'
								text   = ('Import table: {0} DLL descriptor(s) listed' -f $dllCount)
							})
						}
					}
				}
			} catch {}
			# Export DLL name + a few export names
			try {
				$expNote = $notes | Where-Object { $_.dir -eq 'Export' } | Select-Object -First 1
				if ($expNote -and $expNote.rva -and [uint32]$expNote.size -ge 40) {
					$expFile = Convert-MBPeRvaToOffset -Sections $sections -Rva ([uint32]$expNote.rva)
					if ($null -ne $expFile) {
						[void]$fs.Seek([long]$expFile, [System.IO.SeekOrigin]::Begin)
						$ed = New-Object byte[] 40
						[void]$fs.Read($ed, 0, 40)
						$nameRvaE = [BitConverter]::ToUInt32($ed, 12)
						$numFuncs = [BitConverter]::ToUInt32($ed, 20)
						$numNames = [BitConverter]::ToUInt32($ed, 24)
						$namesRva = [BitConverter]::ToUInt32($ed, 32)
						$modOff = Convert-MBPeRvaToOffset -Sections $sections -Rva $nameRvaE
						if ($null -ne $modOff) {
							[void]$fs.Seek([long]$modOff, [System.IO.SeekOrigin]::Begin)
							$mb = New-Object byte[] 128
							$mr = $fs.Read($mb, 0, 128)
							$me = 0
							while ($me -lt $mr -and $mb[$me] -ne 0) { $me++ }
							$modName = if ($me -gt 0) { [System.Text.Encoding]::ASCII.GetString($mb, 0, $me) } else { '' }
							if ($modName) {
								[void]$notes.Add([ordered]@{
									offset = [long]$modOff
									kind   = 'pe_export'
									text   = ('Export module: {0} (funcs={1} names={2})' -f $modName, $numFuncs, $numNames)
								})
							}
						}
						# first few export names
						if ($numNames -gt 0 -and $namesRva -gt 0) {
							$namesOff = Convert-MBPeRvaToOffset -Sections $sections -Rva $namesRva
							if ($null -ne $namesOff) {
								$takeN = [Math]::Min([int]$numNames, 16)
								for ($ni = 0; $ni -lt $takeN; $ni++) {
									[void]$fs.Seek([long]($namesOff + ($ni * 4)), [System.IO.SeekOrigin]::Begin)
									$nrvaB = New-Object byte[] 4
									[void]$fs.Read($nrvaB, 0, 4)
									$nrva = [BitConverter]::ToUInt32($nrvaB, 0)
									$nOff = Convert-MBPeRvaToOffset -Sections $sections -Rva $nrva
									if ($null -eq $nOff) { continue }
									[void]$fs.Seek([long]$nOff, [System.IO.SeekOrigin]::Begin)
									$nb2 = New-Object byte[] 96
									$nr2 = $fs.Read($nb2, 0, 96)
									$ne = 0
									while ($ne -lt $nr2 -and $nb2[$ne] -ne 0) { $ne++ }
									if ($ne -le 0) { continue }
									$en = [System.Text.Encoding]::ASCII.GetString($nb2, 0, $ne)
									[void]$notes.Add([ordered]@{
										offset = [long]$nOff
										kind   = 'pe_export'
										text   = ('Export name: {0}' -f $en)
									})
								}
							}
						}
					}
				}
			} catch {}
		}
	} catch {
		return @()
	} finally {
		if ($fs) { try { $fs.Dispose() } catch {} }
	}
	return @($notes)
}

function Get-MBStringAnnotations {
	# Printable ASCII + UTF-16LE runs inside a byte window.
	param(
		[byte[]]$Bytes,
		[long]$BaseOffset = 0,
		[int]$MinLen = 4,
		[int]$MaxHits = 48
	)
	$out = New-Object System.Collections.ArrayList
	if ($null -eq $Bytes -or $Bytes.Length -eq 0) { return @() }
	# ASCII runs
	$i = 0
	while ($i -lt $Bytes.Length -and $out.Count -lt $MaxHits) {
		if ($Bytes[$i] -ge 32 -and $Bytes[$i] -le 126) {
			$start = $i
			while ($i -lt $Bytes.Length -and $Bytes[$i] -ge 32 -and $Bytes[$i] -le 126) { $i++ }
			$len = $i - $start
			if ($len -ge $MinLen) {
				$slice = New-Object byte[] $len
				[Array]::Copy($Bytes, $start, $slice, 0, $len)
				$s = [System.Text.Encoding]::ASCII.GetString($slice)
				if ($s.Length -gt 80) { $s = $s.Substring(0, 77) + '...' }
				[void]$out.Add([ordered]@{
					offset = ($BaseOffset + $start)
					length = $len
					kind   = 'string_ascii'
					text   = $s
				})
			}
		} else {
			$i++
		}
	}
	# UTF-16LE runs (Windows test binaries)
	$i = 0
	while ($i -lt ($Bytes.Length - 1) -and $out.Count -lt $MaxHits) {
		# aligned-ish: prefer even indices relative to base, but accept any if printable LE pattern
		$b0 = $Bytes[$i]; $b1 = $Bytes[$i + 1]
		$isPrint = ($b1 -eq 0 -and $b0 -ge 32 -and $b0 -le 126)
		if ($isPrint) {
			$start = $i
			$chars = New-Object System.Text.StringBuilder
			while (($i + 1) -lt $Bytes.Length -and $Bytes[$i + 1] -eq 0 -and $Bytes[$i] -ge 32 -and $Bytes[$i] -le 126) {
				[void]$chars.Append([char]$Bytes[$i])
				$i += 2
			}
			$s = $chars.ToString()
			if ($s.Length -ge $MinLen) {
				if ($s.Length -gt 80) { $s = $s.Substring(0, 77) + '...' }
				$byteLen = ($i - $start)
				[void]$out.Add([ordered]@{
					offset = ($BaseOffset + $start)
					length = $byteLen
					kind   = 'string_utf16le'
					text   = $s
				})
			}
		} else {
			$i++
		}
	}
	return @($out)
}

function Get-MBByteClassSummary {
	# Compact class counts for the viewed window (testing orientation).
	param([byte[]]$Bytes)
	if ($null -eq $Bytes -or $Bytes.Length -eq 0) {
		return [ordered]@{ total = 0 }
	}
	$nul = 0; $ctrl = 0; $print = 0; $high = 0; $del = 0
	foreach ($b in $Bytes) {
		if ($b -eq 0) { $nul++ }
		elseif ($b -eq 0x7F) { $del++ }
		elseif ($b -lt 32) { $ctrl++ }
		elseif ($b -le 126) { $print++ }
		else { $high++ }
	}
	return [ordered]@{
		total     = $Bytes.Length
		nul       = $nul
		control   = $ctrl
		printable = $print
		del       = $del
		high_bit  = $high
	}
}


function Get-MBPeDisasmContext {
	# Compact PE map for disasm/trace: arch, entry file offset, sections.
	param([string]$Path)
	$ctx = [ordered]@{
		Ok = $false
		Is64 = $false
		Machine = ''
		EntryRva = 0
		EntryFile = $null
		ImageBase = [uint64]0
		Sections = @()
	}
	$fs = $null
	try {
		$fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		if ($fs.Length -lt 64) { return $ctx }
		$hdr = New-Object byte[] 64
		[void]$fs.Read($hdr, 0, 64)
		if ($hdr[0] -ne 0x4D -or $hdr[1] -ne 0x5A) { return $ctx }
		$e_lfanew = [BitConverter]::ToInt32($hdr, 0x3C)
		if ($e_lfanew -le 0 -or ($e_lfanew + 24) -gt $fs.Length) { return $ctx }
		[void]$fs.Seek([long]$e_lfanew, [System.IO.SeekOrigin]::Begin)
		$peSig = New-Object byte[] 4
		[void]$fs.Read($peSig, 0, 4)
		if ($peSig[0] -ne 0x50 -or $peSig[1] -ne 0x45) { return $ctx }
		$coff = New-Object byte[] 20
		[void]$fs.Read($coff, 0, 20)
		$machine = [BitConverter]::ToUInt16($coff, 0)
		$numSec = [BitConverter]::ToUInt16($coff, 2)
		$optSize = [BitConverter]::ToUInt16($coff, 16)
		$ctx.Machine = switch ($machine) {
			0x14c { 'i386' }
			0x8664 { 'AMD64' }
			0xAA64 { 'ARM64' }
			default { ('0x{0:X}' -f $machine) }
		}
		$optOff = $e_lfanew + 24
		$epRva = [uint32]0
		$imgBase = [uint64]0
		$is64 = $false
		if ($optSize -ge 2 -and ($optOff + $optSize) -le $fs.Length) {
			[void]$fs.Seek([long]$optOff, [System.IO.SeekOrigin]::Begin)
			$opt = New-Object byte[] ([Math]::Min([int]$optSize, 256))
			[void]$fs.Read($opt, 0, $opt.Length)
			$magic = [BitConverter]::ToUInt16($opt, 0)
			$is64 = ($magic -eq 0x20B)
			$ctx.Is64 = $is64
			if ($magic -eq 0x10B -or $magic -eq 0x20B) {
				$epRva = [BitConverter]::ToUInt32($opt, 16)
				if ($is64 -and $opt.Length -ge 32) { $imgBase = [BitConverter]::ToUInt64($opt, 24) }
				elseif ($opt.Length -ge 32) { $imgBase = [uint64][BitConverter]::ToUInt32($opt, 28) }
			}
		}
		$ctx.EntryRva = $epRva
		$ctx.ImageBase = $imgBase
		$secOff = $e_lfanew + 24 + $optSize
		$secs = New-Object System.Collections.ArrayList
		$maxSec = [Math]::Min([int]$numSec, 48)
		for ($s = 0; $s -lt $maxSec; $s++) {
			$so = $secOff + ($s * 40)
			if (($so + 40) -gt $fs.Length) { break }
			[void]$fs.Seek([long]$so, [System.IO.SeekOrigin]::Begin)
			$sec = New-Object byte[] 40
			[void]$fs.Read($sec, 0, 40)
			$nb = New-Object byte[] 8
			[Array]::Copy($sec, 0, $nb, 0, 8)
			$name = [System.Text.Encoding]::ASCII.GetString($nb).TrimEnd([char]0)
			[void]$secs.Add([ordered]@{
				name = $name
				virt_rva = [BitConverter]::ToUInt32($sec, 12)
				virt_size = [BitConverter]::ToUInt32($sec, 8)
				raw_ptr = [BitConverter]::ToUInt32($sec, 20)
				raw_size = [BitConverter]::ToUInt32($sec, 16)
			})
		}
		$ctx.Sections = @($secs)
		if ($epRva -gt 0) {
			$ctx.EntryFile = Convert-MBPeRvaToOffset -Sections $ctx.Sections -Rva $epRva
		}
		$ctx.Ok = $true
	} catch {
		$ctx.Ok = $false
	} finally {
		if ($fs) { try { $fs.Dispose() } catch {} }
	}
	return $ctx
}

function Get-MBX86ModRMExtraLen {
	# Bytes after the ModRM byte (SIB + displacement), not counting ModRM itself.
	param(
		[byte[]]$Bytes,
		[int]$ModRmIndex,
		[bool]$Addr16 = $false
	)
	if ($ModRmIndex -ge $Bytes.Length) { return -1 }
	$modrm = [int]$Bytes[$ModRmIndex]
	$mod = ($modrm -shr 6) -band 3
	$rm = $modrm -band 7
	$extra = 0
	$i = $ModRmIndex + 1
	if ($Addr16) {
		if ($mod -eq 0 -and $rm -eq 6) { $extra = 2 }
		elseif ($mod -eq 1) { $extra = 1 }
		elseif ($mod -eq 2) { $extra = 2 }
		return $extra
	}
	# 32/64-bit addressing
	if ($mod -ne 3 -and $rm -eq 4) {
		# SIB
		if ($i -ge $Bytes.Length) { return -1 }
		$sib = [int]$Bytes[$i]
		$extra++
		$i++
		$base = $sib -band 7
		if ($mod -eq 0 -and $base -eq 5) { $extra += 4 }
		elseif ($mod -eq 1) { $extra += 1 }
		elseif ($mod -eq 2) { $extra += 4 }
		return $extra
	}
	if ($mod -eq 0 -and $rm -eq 5) { return 4 } # disp32
	if ($mod -eq 1) { return 1 }
	if ($mod -eq 2) { return 4 }
	return 0
}

function Read-MBX86Instruction {
	# Decode one x86/x64 instruction focusing on control-flow + common ops for abandonware PE.
	param(
		[byte[]]$Bytes,
		[int]$Index = 0,
		[long]$FileOffset = 0,
		[bool]$Is64 = $false
	)
	$n = $Bytes.Length
	if ($Index -lt 0 -or $Index -ge $n) {
		return @{ Ok = $false; Error = 'eof' }
	}
	$start = $Index
	$i = $Index
	$opSize16 = $false
	$addr16 = $false
	$rep = ''
	$lock = $false
	$rexW = $false
	# prefixes
	while ($i -lt $n) {
		$b = [int]$Bytes[$i]
		if ($b -eq 0xF0) { $lock = $true; $i++; continue }
		if ($b -eq 0xF2) { $rep = 'repne'; $i++; continue }
		if ($b -eq 0xF3) { $rep = 'rep'; $i++; continue }
		if ($b -eq 0x2E -or $b -eq 0x36 -or $b -eq 0x3E -or $b -eq 0x26 -or $b -eq 0x64 -or $b -eq 0x65) { $i++; continue } # seg
		if ($b -eq 0x66) { $opSize16 = $true; $i++; continue }
		if ($b -eq 0x67) { $addr16 = $true; $i++; continue }
		if ($Is64 -and $b -ge 0x40 -and $b -le 0x4F) {
			$rexW = (($b -band 8) -ne 0)
			$i++
			continue
		}
		break
	}
	if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated_only' } }
	$op = [int]$Bytes[$i]
	$i++
	$mnem = 'db'
	$opstr = ('0x{0:X2}' -f $op)
	$isCF = $false
	$isUncond = $false
	$isCond = $false
	$isCall = $false
	$isRet = $false
	$target = $null
	$fallthrough = $null
	$immHex = ''
	$usesRipRel = $false
	$ripRelDisp = 0
	$isIndirectCf = $false

	$jcc8 = @{
		'70'='jo'; '71'='jno'; '72'='jb/jc'; '73'='jae/jnc'; '74'='je/jz'; '75'='jne/jnz'
		'76'='jbe'; '77'='ja'; '78'='js'; '79'='jns'; '7A'='jp'; '7B'='jnp'
		'7C'='jl'; '7D'='jge'; '7E'='jle'; '7F'='jg'
	}

	$finish = {
		param($endI)
		$len = $endI - $start
		$raw = New-Object byte[] $len
		[Array]::Copy($Bytes, $start, $raw, 0, $len)
		$hx = ($raw | ForEach-Object { '{0:X2}' -f $_ }) -join ' '
		$fo = $FileOffset + $start
		$fallthrough = $FileOffset + $endI
		return @{
			Ok = $true
			offset = [long]$fo
			offset_hex = ('0x{0:X}' -f $fo)
			length = $len
			bytes = $hx
			mnemonic = $mnem
			operands = $opstr
			is_control_flow = $isCF
			is_unconditional_jump = $isUncond
			is_conditional_jump = $isCond
			is_call = $isCall
			is_ret = $isRet
			is_indirect = $isIndirectCf
			uses_rip_rel = $usesRipRel
			rip_rel_disp = $(if ($usesRipRel) { [int]$ripRelDisp } else { $null })
			target = $target
			target_hex = $(if ($null -ne $target) { ('0x{0:X}' -f [long]$target) } else { $null })
			fallthrough = [long]$fallthrough
			fallthrough_hex = ('0x{0:X}' -f [long]$fallthrough)
			next_index = $endI
		}
	}

	# Single-byte opcodes
	if ($op -eq 0x90) {
		$mnem = 'nop'; $opstr = ''
		return & $finish $i
	}
	if ($op -eq 0xCC) {
		$mnem = 'int3'; $opstr = ''; $isCF = $true; $isRet = $true # treat as stop
		return & $finish $i
	}
	if ($op -eq 0xC3) {
		$mnem = 'ret'; $opstr = ''; $isCF = $true; $isRet = $true
		return & $finish $i
	}
	if ($op -eq 0xC2) {
		if ($i + 1 -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$imm = [BitConverter]::ToUInt16($Bytes, $i); $i += 2
		$mnem = 'ret'; $opstr = ('0x{0:X}' -f $imm); $isCF = $true; $isRet = $true
		return & $finish $i
	}
	if ($op -eq 0xCB -or $op -eq 0xCA) {
		$mnem = 'retf'; $isCF = $true; $isRet = $true
		if ($op -eq 0xCA) {
			if ($i + 1 -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
			$imm = [BitConverter]::ToUInt16($Bytes, $i); $i += 2
			$opstr = ('0x{0:X}' -f $imm)
		} else { $opstr = '' }
		return & $finish $i
	}
	# JMP rel8
	if ($op -eq 0xEB) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$ub = [int]$Bytes[$i]; $rel = $(if ($ub -ge 128) { $ub - 256 } else { $ub }); $i++
		$mnem = 'jmp'; $isCF = $true; $isUncond = $true
		$target = [long]($FileOffset + $i + $rel)
		$opstr = ('short 0x{0:X}' -f $target)
		return & $finish $i
	}
	# JMP rel32 / CALL rel32
	if ($op -eq 0xE9 -or $op -eq 0xE8) {
		if ($i + 3 -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$rel = [BitConverter]::ToInt32($Bytes, $i); $i += 4
		if ($op -eq 0xE9) {
			$mnem = 'jmp'; $isCF = $true; $isUncond = $true
		} else {
			$mnem = 'call'; $isCF = $true; $isCall = $true
		}
		$target = [long]($FileOffset + $i + $rel)
		$opstr = ('0x{0:X}' -f $target)
		return & $finish $i
	}
	# Jcc rel8
	$jccKey = '{0:X2}' -f $op
	if ($jcc8.ContainsKey($jccKey)) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$ub = [int]$Bytes[$i]; $rel = $(if ($ub -ge 128) { $ub - 256 } else { $ub }); $i++
		$mnem = [string]$jcc8[$jccKey]
		$isCF = $true; $isCond = $true
		$target = [long]($FileOffset + $i + $rel)
		$opstr = ('short 0x{0:X}' -f $target)
		return & $finish $i
	}
	# LOOP/JCXZ
	if ($op -in 0xE0, 0xE1, 0xE2, 0xE3) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$ub = [int]$Bytes[$i]; $rel = $(if ($ub -ge 128) { $ub - 256 } else { $ub }); $i++
		$mnem = switch ($op) { 0xE0 { 'loopne' } 0xE1 { 'loope' } 0xE2 { 'loop' } 0xE3 { 'jcxz/jecxz' } }
		$isCF = $true; $isCond = $true
		$target = [long]($FileOffset + $i + $rel)
		$opstr = ('short 0x{0:X}' -f $target)
		return & $finish $i
	}
	# Two-byte: 0F xx
	if ($op -eq 0x0F) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$op2 = [int]$Bytes[$i]; $i++
		# Jcc rel32
		if ($op2 -ge 0x80 -and $op2 -le 0x8F) {
			if ($i + 3 -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
			$rel = [BitConverter]::ToInt32($Bytes, $i); $i += 4
			$map = @{
				'80'='jo'; '81'='jno'; '82'='jb/jc'; '83'='jae/jnc'; '84'='je/jz'; '85'='jne/jnz'
				'86'='jbe'; '87'='ja'; '88'='js'; '89'='jns'; '8A'='jp'; '8B'='jnp'
				'8C'='jl'; '8D'='jge'; '8E'='jle'; '8F'='jg'
			}
			$mnem = [string]$map[('{0:X2}' -f $op2)]
			$isCF = $true; $isCond = $true
			$target = [long]($FileOffset + $i + $rel)
			$opstr = ('0x{0:X}' -f $target)
			return & $finish $i
		}
		# common 0F with modrm
		if ($op2 -in 0x1F, 0xB6, 0xB7, 0xBE, 0xBF, 0xAF, 0xA3, 0xAB, 0xBA) {
			if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
			$extra = Get-MBX86ModRMExtraLen -Bytes $Bytes -ModRmIndex $i -Addr16 $addr16
			if ($extra -lt 0) { return @{ Ok = $false; Error = 'truncated' } }
			$i = $i + 1 + $extra
			$mnem = switch ($op2) {
				0x1F { 'nop' }
				0xB6 { 'movzx' }
				0xB7 { 'movzx' }
				0xBE { 'movsx' }
				0xBF { 'movsx' }
				0xAF { 'imul' }
				default { ('0F {0:X2}' -f $op2) }
			}
			$opstr = 'r/m'
			return & $finish $i
		}
		$mnem = ('0F {0:X2}' -f $op2)
		$opstr = ''
		return & $finish $i
	}
	# FF /2 CALL, /4 JMP r/m (often call [rip+disp] -> IAT)
	if ($op -eq 0xFF) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$modrm = [int]$Bytes[$i]
		$mod = ($modrm -shr 6) -band 3
		$reg = ($modrm -shr 3) -band 7
		$rm = $modrm -band 7
		$extra = Get-MBX86ModRMExtraLen -Bytes $Bytes -ModRmIndex $i -Addr16 $addr16
		if ($extra -lt 0) { return @{ Ok = $false; Error = 'truncated' } }
		# x64: mod=00 r/m=101 => [RIP+disp32]; x86: absolute [disp32]
		if ($mod -eq 0 -and $rm -eq 5 -and $extra -ge 4) {
			$dispOff = $i + 1
			if (-not $addr16 -and ($dispOff + 3) -lt $n) {
				$ripRelDisp = [BitConverter]::ToInt32($Bytes, $dispOff)
				$usesRipRel = $true  # on x86 this is abs disp; resolver treats per arch
			}
		}
		$i = $i + 1 + $extra
		if ($reg -eq 2) {
			$mnem = 'call'; $opstr = 'r/m'; $isCF = $true; $isCall = $true; $isIndirectCf = $true
			if ($usesRipRel) { $opstr = if ($Is64) { ('[rip+0x{0:X}]' -f $ripRelDisp) } else { ('[0x{0:X}]' -f $ripRelDisp) } }
		} elseif ($reg -eq 4) {
			$mnem = 'jmp'; $opstr = 'r/m'; $isCF = $true; $isUncond = $true; $isIndirectCf = $true
			if ($usesRipRel) { $opstr = if ($Is64) { ('[rip+0x{0:X}]' -f $ripRelDisp) } else { ('[0x{0:X}]' -f $ripRelDisp) } }
		} elseif ($reg -eq 6) {
			$mnem = 'push'; $opstr = 'r/m'
			if ($usesRipRel) { $opstr = if ($Is64) { ('[rip+0x{0:X}]' -f $ripRelDisp) } else { ('[0x{0:X}]' -f $ripRelDisp) } }
		} else {
			$mnem = 'ff'; $opstr = ('/{0}' -f $reg)
		}
		return & $finish $i
	}
	# PUSH/POP r32
	if ($op -ge 0x50 -and $op -le 0x57) {
		$regs = @('eax','ecx','edx','ebx','esp','ebp','esi','edi')
		if ($Is64) { $regs = @('rax','rcx','rdx','rbx','rsp','rbp','rsi','rdi') }
		$mnem = 'push'; $opstr = $regs[$op - 0x50]
		return & $finish $i
	}
	if ($op -ge 0x58 -and $op -le 0x5F) {
		$regs = @('eax','ecx','edx','ebx','esp','ebp','esi','edi')
		if ($Is64) { $regs = @('rax','rcx','rdx','rbx','rsp','rbp','rsi','rdi') }
		$mnem = 'pop'; $opstr = $regs[$op - 0x58]
		return & $finish $i
	}
	# MOV r/m, r | r, r/m | etc with modrm
	if ($op -in 0x88, 0x89, 0x8A, 0x8B, 0x8C, 0x8D, 0x8E, 0x01, 0x03, 0x29, 0x2B, 0x31, 0x33, 0x39, 0x3B, 0x85, 0x20, 0x21, 0x09, 0x0A, 0x0B) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$extra = Get-MBX86ModRMExtraLen -Bytes $Bytes -ModRmIndex $i -Addr16 $addr16
		if ($extra -lt 0) { return @{ Ok = $false; Error = 'truncated' } }
		$i = $i + 1 + $extra
		$mnem = switch ($op) {
			0x8D { 'lea' }
			0x85 { 'test' }
			{ $_ -in 0x88, 0x89, 0x8A, 0x8B } { 'mov' }
			{ $_ -in 0x01, 0x03 } { 'add' }
			{ $_ -in 0x29, 0x2B } { 'sub' }
			{ $_ -in 0x31, 0x33 } { 'xor' }
			{ $_ -in 0x39, 0x3B } { 'cmp' }
			{ $_ -in 0x20, 0x21 } { 'and' }
			{ $_ -in 0x09, 0x0A, 0x0B } { 'or' }
			default { ('op_{0:X2}' -f $op) }
		}
		$opstr = 'r/m'
		return & $finish $i
	}
	# MOV r32, imm32
	if ($op -ge 0xB8 -and $op -le 0xBF) {
		$regs = @('eax','ecx','edx','ebx','esp','ebp','esi','edi')
		if ($Is64 -and $rexW) { $regs = @('rax','rcx','rdx','rbx','rsp','rbp','rsi','rdi') }
		$immLen = if ($Is64 -and $rexW) { 8 } elseif ($opSize16) { 2 } else { 4 }
		if (($i + $immLen - 1) -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		if ($immLen -eq 4) {
			$imm = [BitConverter]::ToUInt32($Bytes, $i)
			$opstr = ('{0}, 0x{1:X}' -f $regs[$op - 0xB8], $imm)
		} elseif ($immLen -eq 2) {
			$imm = [BitConverter]::ToUInt16($Bytes, $i)
			$opstr = ('{0}, 0x{1:X}' -f $regs[$op - 0xB8], $imm)
		} else {
			$imm = [BitConverter]::ToUInt64($Bytes, $i)
			$opstr = ('{0}, 0x{1:X}' -f $regs[$op - 0xB8], $imm)
		}
		$i += $immLen
		$mnem = 'mov'
		return & $finish $i
	}
	# group 0x80/81/83 imm
	if ($op -in 0x80, 0x81, 0x83) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$modrm = [int]$Bytes[$i]
		$reg = ($modrm -shr 3) -band 7
		$extra = Get-MBX86ModRMExtraLen -Bytes $Bytes -ModRmIndex $i -Addr16 $addr16
		if ($extra -lt 0) { return @{ Ok = $false; Error = 'truncated' } }
		$i = $i + 1 + $extra
		$immLen = if ($op -eq 0x81) { if ($opSize16) { 2 } else { 4 } } else { 1 }
		if (($i + $immLen - 1) -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$i += $immLen
		$ops = @('add','or','adc','sbb','and','sub','xor','cmp')
		$mnem = $ops[$reg]
		$opstr = 'r/m, imm'
		return & $finish $i
	}
	# C6/C7 mov imm
	if ($op -in 0xC6, 0xC7) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$extra = Get-MBX86ModRMExtraLen -Bytes $Bytes -ModRmIndex $i -Addr16 $addr16
		if ($extra -lt 0) { return @{ Ok = $false; Error = 'truncated' } }
		$i = $i + 1 + $extra
		$immLen = if ($op -eq 0xC6) { 1 } elseif ($opSize16) { 2 } else { 4 }
		if (($i + $immLen - 1) -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$i += $immLen
		$mnem = 'mov'; $opstr = 'r/m, imm'
		return & $finish $i
	}
	# TEST al/ax/eax, imm
	if ($op -eq 0xA8) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$i++; $mnem = 'test'; $opstr = 'al, imm8'
		return & $finish $i
	}
	if ($op -eq 0xA9) {
		$immLen = if ($opSize16) { 2 } else { 4 }
		if (($i + $immLen - 1) -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$i += $immLen
		$mnem = 'test'; $opstr = 'eax, imm'
		return & $finish $i
	}
	# CMP/TEST with modrm 0x84
	if ($op -eq 0x84) {
		if ($i -ge $n) { return @{ Ok = $false; Error = 'truncated' } }
		$extra = Get-MBX86ModRMExtraLen -Bytes $Bytes -ModRmIndex $i -Addr16 $addr16
		if ($extra -lt 0) { return @{ Ok = $false; Error = 'truncated' } }
		$i = $i + 1 + $extra
		$mnem = 'test'; $opstr = 'r/m'
		return & $finish $i
	}
	# Fallback: consume 1 byte as db
	$mnem = 'db'
	$opstr = ('0x{0:X2}' -f $op)
	return & $finish $i
}

function Resolve-MBDisasmSymbols {
	# Attach IAT/export labels and mem_file for RIP-relative / abs indirect ops.
	param(
		$Instruction,
		$SymbolMap,
		[bool]$Is64 = $false
	)
	if ($null -eq $Instruction -or -not $Instruction.Ok) { return $Instruction }
	if ($null -eq $SymbolMap -or -not $SymbolMap.Ok) { return $Instruction }
	$secs = $SymbolMap.Sections
	# Direct call/jmp target -> export
	if ($null -ne $Instruction.target) {
		$tKey = [string][long]$Instruction.target
		if ($SymbolMap.ExportByFileOffset.ContainsKey($tKey)) {
			$Instruction['symbol'] = [string]$SymbolMap.ExportByFileOffset[$tKey]
			$Instruction['operands'] = ('{0}  ; {1}' -f $Instruction.operands, $Instruction.symbol)
		} else {
			$trva = Convert-MBPeOffsetToRva -Sections $secs -FileOffset ([long]$Instruction.target)
			if ($null -ne $trva) {
				$rk = [string][uint32]$trva
				if ($SymbolMap.ExportByRva.ContainsKey($rk)) {
					$Instruction['symbol'] = [string]$SymbolMap.ExportByRva[$rk]
					$Instruction['operands'] = ('{0}  ; {1}' -f $Instruction.operands, $Instruction.symbol)
				}
			}
		}
	}
	# RIP-relative or abs [disp32] mem operand (call/jmp/push [m])
	if ($Instruction.uses_rip_rel -and $null -ne $Instruction.rip_rel_disp) {
		$disp = [int]$Instruction.rip_rel_disp
		$nextFo = [long]$Instruction.offset + [int]$Instruction.length
		$memFo = $null
		if ($Is64) {
			$nextRva = Convert-MBPeOffsetToRva -Sections $secs -FileOffset $nextFo
			if ($null -ne $nextRva) {
				$memRvaLong = [int64][uint32]$nextRva + [int64]$disp
				if ($memRvaLong -ge 0 -and $memRvaLong -le [uint32]::MaxValue) {
					$memFo = Convert-MBPeRvaToOffset -Sections $secs -Rva ([uint32]$memRvaLong)
				}
			}
		} else {
			# x86: [disp32] is absolute VA; convert VA -> RVA -> file when ImageBase known
			$va = [uint64][uint32]$disp
			$img = [uint64]$SymbolMap.ImageBase
			if ($img -gt 0 -and $va -ge $img) {
				$memRva = [uint32]($va - $img)
				$memFo = Convert-MBPeRvaToOffset -Sections $secs -Rva $memRva
			} else {
				# sometimes encoded as raw VA equal to file-ish; try as file offset
				if ($disp -ge 0) { $memFo = [long]$disp }
			}
		}
		if ($null -ne $memFo) {
			$Instruction['mem_file'] = [long]$memFo
			$Instruction['mem_file_hex'] = ('0x{0:X}' -f [long]$memFo)
			$mk = [string][long]$memFo
			if ($SymbolMap.IatByFileOffset.ContainsKey($mk)) {
				$sym = [string]$SymbolMap.IatByFileOffset[$mk]
				$Instruction['symbol'] = $sym
				$Instruction['iat_file'] = [long]$memFo
				$Instruction['operands'] = ('[{0}]' -f $sym)
			} else {
				$Instruction['operands'] = ('{0}  ; mem_file=0x{1:X}' -f $Instruction.operands, $memFo)
			}
		}
	}
	return $Instruction
}

function Get-MBX86Disasm {
	# Linear disassembly listing from a file offset.
	# Marks uncertain (db) runs and attempts resync on INT3/NOP/common prologues after desync.
	param(
		[string]$Path,
		[long]$Offset = 0,
		[int]$MaxInsns = 48,
		[bool]$Is64 = $false,
		[int]$ReadBytes = 0,
		$SymbolMap = $null
	)
	if ($MaxInsns -le 0) { $MaxInsns = 48 }
	if ($MaxInsns -gt 200) { $MaxInsns = 200 }
	if ($ReadBytes -le 0) { $ReadBytes = [Math]::Min(4096, $MaxInsns * 16) }
	if ($ReadBytes -gt 8192) { $ReadBytes = 8192 }
	if ($null -eq $SymbolMap) {
		try { $SymbolMap = Get-MBPeSymbolMap -Path $Path } catch { $SymbolMap = $null }
	}
	$r = Read-MBFileBytes -Path $Path -Offset $Offset -Length $ReadBytes
	if (-not $r.Ok) { return @{ Ok = $false; Error = $r.Error; instructions = @() } }
	$ins = New-Object System.Collections.ArrayList
	$idx = 0
	$count = 0
	$symHits = 0
	$uncertain = 0
	$resyncs = 0
	$dbRun = 0
	$bytes = $r.Bytes
	while ($count -lt $MaxInsns -and $idx -lt $bytes.Length) {
		$dec = Read-MBX86Instruction -Bytes $bytes -Index $idx -FileOffset $Offset -Is64 $Is64
		if (-not $dec.Ok) {
			# hard fail: skip one byte and mark
			if ($idx -lt $bytes.Length) {
				$fo = $Offset + $idx
				[void]$ins.Add(@{
					Ok = $true
					offset = [long]$fo
					offset_hex = ('0x{0:X}' -f $fo)
					length = 1
					bytes = ('{0:X2}' -f $bytes[$idx])
					mnemonic = 'db'
					operands = ('0x{0:X2}' -f $bytes[$idx])
					uncertain = $true
					is_control_flow = $false
					is_ret = $false
					next_index = $idx + 1
				})
				$uncertain++
				$dbRun++
				$idx++
				$count++
			} else { break }
		} else {
			$isDb = ([string]$dec.mnemonic -eq 'db')
			if ($isDb) {
				$dec['uncertain'] = $true
				$uncertain++
				$dbRun++
			} else {
				$dbRun = 0
				$dec['uncertain'] = $false
			}
			try {
				$dec = Resolve-MBDisasmSymbols -Instruction $dec -SymbolMap $SymbolMap -Is64 $Is64
				if ($dec.symbol) { $symHits++ }
			} catch {}
			[void]$ins.Add($dec)
			$idx = [int]$dec.next_index
			$count++
			if ($dec.is_ret -and -not $isDb) { break }
		}
		# After a short db run, try resync to alignment/prologue
		if ($dbRun -ge 2 -and $idx -lt $bytes.Length -and $count -lt $MaxInsns) {
			$best = -1
			$look = [Math]::Min($bytes.Length - 1, $idx + 12)
			for ($s = $idx; $s -le $look; $s++) {
				$bb = [int]$bytes[$s]
				# INT3 / NOP pad end, or classic prologues
				if ($bb -eq 0xCC -or $bb -eq 0x90) { $best = $s; break }
				if ($bb -eq 0x55) { $best = $s; break } # push ebp/rbp
				if ($bb -eq 0xC3) { $best = $s; break } # ret (end of garbage)
				if ($Is64 -and $bb -eq 0x48 -and ($s + 1) -lt $bytes.Length) {
					$n1 = [int]$bytes[$s + 1]
					if ($n1 -in 0x89, 0x83, 0x81, 0x8B) { $best = $s; break }
				}
			}
			if ($best -gt $idx) {
				$skipN = $best - $idx
				$fo = $Offset + $idx
				[void]$ins.Add(@{
					Ok = $true
					offset = [long]$fo
					offset_hex = ('0x{0:X}' -f $fo)
					length = $skipN
					bytes = '..'
					mnemonic = 'resync'
					operands = ('skip {0} uncertain byte(s) -> 0x{1:X}' -f $skipN, ($Offset + $best))
					uncertain = $true
					resync = $true
					is_control_flow = $false
					is_ret = $false
					next_index = $best
				})
				$idx = $best
				$resyncs++
				$dbRun = 0
				$count++
			}
		}
	}
	$dotnetWarn = $null
	if ($SymbolMap -and $SymbolMap.IsDotNet) {
		$dotnetWarn = 'PE looks managed (.NET). Native listing may be a bootstrap thunk — treat with caution.'
	}
	return @{
		Ok = $true
		offset = $Offset
		offset_hex = ('0x{0:X}' -f $Offset)
		is64 = $Is64
		count = $ins.Count
		symbols_resolved = $symHits
		uncertain_count = $uncertain
		resync_count = $resyncs
		imports_mapped = $(if ($SymbolMap -and $SymbolMap.Ok) { [int]$SymbolMap.IatSlotCount } else { 0 })
		exports_mapped = $(if ($SymbolMap -and $SymbolMap.Ok) { [int]$SymbolMap.ExportCount } else { 0 })
		delay_dlls = $(if ($SymbolMap -and $SymbolMap.Ok) { [int]$SymbolMap.DelayDllCount } else { 0 })
		is_dotnet = $(if ($SymbolMap) { [bool]$SymbolMap.IsDotNet } else { $false })
		dotnet_warning = $dotnetWarn
		instructions = @($ins)
	}
}

function Get-MBX86Trace {
	# Walk control flow: follow unconditional JMP; at Jcc record both paths; CALL records target then falls through.
	param(
		[string]$Path,
		[long]$Offset = 0,
		[int]$MaxSteps = 32,
		[bool]$Is64 = $false,
		[bool]$FollowCalls = $false,
		[string]$PreferBranch = 'fallthrough'  # fallthrough | taken
	)
	if ($MaxSteps -le 0) { $MaxSteps = 32 }
	if ($MaxSteps -gt 80) { $MaxSteps = 80 }
	$steps = New-Object System.Collections.ArrayList
	$branches = New-Object System.Collections.ArrayList
	$visited = @{}
	$pos = [long]$Offset
	$fileLen = 0L
	try { $fileLen = (Get-Item -LiteralPath $Path).Length } catch {}
	for ($s = 0; $s -lt $MaxSteps; $s++) {
		if ($pos -lt 0 -or ($fileLen -gt 0 -and $pos -ge $fileLen)) { break }
		$key = [string]$pos
		if ($visited.ContainsKey($key)) {
			[void]$steps.Add([ordered]@{
				step = $s
				note = 'loop_detected'
				offset = $pos
				offset_hex = ('0x{0:X}' -f $pos)
			})
			break
		}
		$visited[$key] = $true
		$chunk = Read-MBFileBytes -Path $Path -Offset $pos -Length 32
		if (-not $chunk.Ok -or $chunk.Bytes.Length -eq 0) { break }
		$dec = Read-MBX86Instruction -Bytes $chunk.Bytes -Index 0 -FileOffset $pos -Is64 $Is64
		if (-not $dec.Ok) {
			[void]$steps.Add([ordered]@{ step = $s; note = 'decode_fail'; offset = $pos })
			break
		}
		$rec = [ordered]@{
			step = $s
			offset = $dec.offset
			offset_hex = $dec.offset_hex
			bytes = $dec.bytes
			mnemonic = $dec.mnemonic
			operands = $dec.operands
			is_control_flow = $dec.is_control_flow
			target = $dec.target
			target_hex = $dec.target_hex
			fallthrough = $dec.fallthrough
			fallthrough_hex = $dec.fallthrough_hex
		}
		[void]$steps.Add($rec)
		if ($dec.is_ret) { break }
		if ($dec.is_unconditional_jump -and $null -ne $dec.target) {
			$pos = [long]$dec.target
			continue
		}
		if ($dec.is_conditional_jump -and $null -ne $dec.target) {
			[void]$branches.Add([ordered]@{
				at = $dec.offset
				at_hex = $dec.offset_hex
				mnemonic = $dec.mnemonic
				taken = $dec.target
				taken_hex = $dec.target_hex
				not_taken = $dec.fallthrough
				not_taken_hex = $dec.fallthrough_hex
				hint = 'HexView offset=taken_hex or not_taken_hex with disasm=true to explore either path. HexEdit can patch Jcc (e.g. 75->EB always, 75->90 90 nop).'
			})
			if ($PreferBranch -eq 'taken') { $pos = [long]$dec.target }
			else { $pos = [long]$dec.fallthrough }
			continue
		}
		if ($dec.is_call -and $null -ne $dec.target) {
			[void]$branches.Add([ordered]@{
				at = $dec.offset
				at_hex = $dec.offset_hex
				mnemonic = 'call'
				taken = $dec.target
				taken_hex = $dec.target_hex
				not_taken = $dec.fallthrough
				not_taken_hex = $dec.fallthrough_hex
				hint = 'CALL target listed; default continues at return (fallthrough). Use follow_calls=true to step into.'
			})
			if ($FollowCalls) { $pos = [long]$dec.target }
			else { $pos = [long]$dec.fallthrough }
			continue
		}
		# call r/m or jmp r/m - cannot resolve statically
		if ($dec.is_call -or $dec.is_unconditional_jump) {
			[void]$branches.Add([ordered]@{
				at = $dec.offset
				at_hex = $dec.offset_hex
				mnemonic = $dec.mnemonic
				note = 'indirect - target not static; inspect surrounding mov/lea'
			})
			if ($dec.is_unconditional_jump) { break }
			$pos = [long]$dec.fallthrough
			continue
		}
		$pos = [long]$dec.fallthrough
	}
	return @{
		Ok = $true
		start = $Offset
		start_hex = ('0x{0:X}' -f $Offset)
		steps = @($steps)
		branches = @($branches)
		prefer_branch = $PreferBranch
	}
}


function Invoke-HexView {
	param(
		[string]$path,
		$path2 = $null,
		$compare = $null,
		$offset = 0,
		[int]$length = 256,
		[int]$width = 16,
		[bool]$show_ascii = $true,
		# Default off — full PE tour is opt-in (annotate=true or detail=full) to save context on smoke checks
		[bool]$annotate = $false,
		[string]$detail = '', # minimal (default) | full (forces annotate)
		[bool]$next_diff = $false,
		[bool]$side_by_side = $true,
		[int]$max_scan = 0,
		# Control-flow / disasm (prefer these over ReadAllBytes for PE navigation)
		[bool]$disasm = $false,
		[bool]$trace = $false,
		[bool]$at_entry = $false,
		[int]$max_insns = 48,
		[int]$max_steps = 32,
		[bool]$follow_calls = $false,
		[string]$prefer_branch = 'fallthrough', # fallthrough | taken
		[string]$arch = 'auto', # auto | x86 | x64
		[bool]$dump_hex = $true,
		# Forensics
		[bool]$entropy = $false,
		[bool]$carve = $false,
		[bool]$hash = $false,
		[bool]$functions = $false,
		$rva = $null,
		[string]$section = '',
		[int]$entropy_blocks = 64
	)
	$path = Resolve-MBPath -Path $path -MustExist
	if ([string]::IsNullOrWhiteSpace($path)) { return 'ERROR: Empty or invalid path' }
	if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return "ERROR: File not found: $path" }

	$det = ([string]$detail).Trim().ToLowerInvariant()
	if ($det -in @('full', 'verbose', 'all')) { $annotate = $true }
	elseif ($det -in @('minimal', 'min', 'slim', 'light') -and -not $disasm -and -not $trace) { $annotate = $false }

	$cmpPath = $null
	if (-not [string]::IsNullOrWhiteSpace([string]$path2)) { $cmpPath = Resolve-MBPath -Path ([string]$path2) }
	elseif (-not [string]::IsNullOrWhiteSpace([string]$compare)) { $cmpPath = Resolve-MBPath -Path ([string]$compare) }
	if ($cmpPath) {
		if (-not (Test-Path -LiteralPath $cmpPath -PathType Leaf)) {
			return "ERROR: Compare file not found: $cmpPath"
		}
	}

	$off = Convert-MBOffsetToInt64 -Value $offset -Default 0
	$peCtx = $null
	try { $peCtx = Get-MBPeDisasmContext -Path $path } catch { $peCtx = $null }
	$symMap = $null
	$is64 = $false
	if ($arch -eq 'x64') { $is64 = $true }
	elseif ($arch -eq 'x86') { $is64 = $false }
	elseif ($peCtx -and $peCtx.Ok) { $is64 = [bool]$peCtx.Is64 }

	# section= name -> start of raw data
	if (-not [string]::IsNullOrWhiteSpace($section)) {
		if ($peCtx -and $peCtx.Ok -and $peCtx.Sections) {
			$want = $section.Trim()
			$foundSec = $null
			foreach ($s in @($peCtx.Sections)) {
				if ([string]::Equals([string]$s.name, $want, [StringComparison]::OrdinalIgnoreCase)) {
					$foundSec = $s; break
				}
			}
			if (-not $foundSec) {
				# allow .text without dot etc
				foreach ($s in @($peCtx.Sections)) {
					$sn = [string]$s.name
					if ($sn.TrimStart('.') -eq $want.TrimStart('.')) { $foundSec = $s; break }
				}
			}
			if ($foundSec -and [uint32]$foundSec.raw_ptr -gt 0) {
				$off = [long][uint32]$foundSec.raw_ptr
			} else {
				return "ERROR: section '$section' not found or has no raw data"
			}
		} else {
			return 'ERROR: section= requires a PE with section table'
		}
	}

	# rva= -> file offset
	if ($null -ne $rva -and [string]$rva -ne '') {
		$rvaVal = Convert-MBOffsetToInt64 -Value $rva -Default -1
		if ($rvaVal -lt 0) { return 'ERROR: invalid rva (use decimal or 0xHEX)' }
		if ($peCtx -and $peCtx.Ok -and $peCtx.Sections) {
			$fo = Convert-MBPeRvaToOffset -Sections $peCtx.Sections -Rva ([uint32]$rvaVal)
			if ($null -eq $fo) {
				return ("ERROR: RVA 0x{0:X} not mapped to a section" -f $rvaVal)
			}
			$off = [long]$fo
		} else {
			return 'ERROR: rva= requires a PE with section table'
		}
	}

	if ($at_entry) {
		if ($peCtx -and $peCtx.Ok -and $null -ne $peCtx.EntryFile) {
			$off = [long]$peCtx.EntryFile
		} else {
			return 'ERROR: at_entry=true but PE entry file offset not found (not a PE or unmapped EP)'
		}
	}

	# Auto-enable disasm when trace requested
	if ($trace) { $disasm = $true }

	if ($length -le 0) { $length = 256 }
	if ($length -gt 16384) { $length = 16384 }
	if ($width -le 0) { $width = 16 }
	if ($width -gt 32) { $width = 32 }
	if ($max_insns -le 0) { $max_insns = 48 }
	if ($max_insns -gt 200) { $max_insns = 200 }
	if ($max_steps -le 0) { $max_steps = 32 }
	if ($max_steps -gt 80) { $max_steps = 80 }
	$pref = ([string]$prefer_branch).ToLowerInvariant()
	if ($pref -ne 'taken') { $pref = 'fallthrough' }

	$diffInfo = $null
	if ($cmpPath -and $next_diff) {
		$diffInfo = Find-MBNextByteDiff -PathA $path -PathB $cmpPath -StartOffset $off -MaxScan $max_scan
		if ($diffInfo.Found -and [long]$diffInfo.Offset -ge 0) {
			$off = [long]$diffInfo.Offset
			$align = [Math]::Max(0L, $off - ($off % [Math]::Max(1, $width)))
			$off = $align
		}
	}

	# When pure disasm/trace, still read a hex window for context unless dump_hex=false
	$hexLen = $length
	if ($disasm -and -not $cmpPath) {
		$hexLen = [Math]::Max($length, [Math]::Min(512, $max_insns * 8))
	}
	$ra = Read-MBFileBytes -Path $path -Offset $off -Length $hexLen
	if (-not $ra.Ok) { return "ERROR: $($ra.Error)" }

	$rb = $null
	$diffMask = $null
	$diffCount = 0
	$firstDiffInWindow = -1L
	$nextDiffAfterWindow = $null

	if ($cmpPath) {
		$rb = Read-MBFileBytes -Path $cmpPath -Offset $off -Length $length
		if (-not $rb.Ok) { return "ERROR: compare file: $($rb.Error)" }
		$maxL = [Math]::Max($ra.Bytes.Length, $rb.Bytes.Length)
		$diffMask = New-Object 'bool[]' $maxL
		for ($i = 0; $i -lt $maxL; $i++) {
			$ba = if ($i -lt $ra.Bytes.Length) { $ra.Bytes[$i] } else { $null }
			$bb = if ($i -lt $rb.Bytes.Length) { $rb.Bytes[$i] } else { $null }
			$d = ($ba -ne $bb)
			$diffMask[$i] = $d
			if ($d) {
				$diffCount++
				if ($firstDiffInWindow -lt 0) { $firstDiffInWindow = $off + $i }
			}
		}
		$after = $off + $maxL
		$nd = Find-MBNextByteDiff -PathA $path -PathB $cmpPath -StartOffset $after -MaxScan $max_scan
		if ($nd.Found) {
			$nextDiffAfterWindow = [ordered]@{
				offset = [long]$nd.Offset
				offset_hex = ('0x{0:X}' -f [long]$nd.Offset)
				reason = [string]$nd.Reason
			}
		} else {
			$nextDiffAfterWindow = [ordered]@{ offset = $null; reason = [string]$nd.Reason }
		}
	}

	$dump = $null
	if ($dump_hex -or $cmpPath -or -not $disasm) {
		if ($cmpPath -and $side_by_side) {
			$dump = Format-MBHexDumpSideBySide -BytesA $ra.Bytes -BytesB $rb.Bytes -BaseOffset $off -Width ([Math]::Min($width, 16)) -ShowAscii $show_ascii
		} elseif ($cmpPath) {
			$dumpA = Format-MBHexDump -Bytes $ra.Bytes -BaseOffset $off -Width $width -ShowAscii $show_ascii -DiffMask $diffMask
			$dumpB = Format-MBHexDump -Bytes $rb.Bytes -BaseOffset $off -Width $width -ShowAscii $show_ascii -DiffMask $diffMask
			$dump = ("--- A: {0}`n{1}`n--- B: {2}`n{3}" -f $path, $dumpA, $cmpPath, $dumpB)
		} else {
			$dump = Format-MBHexDump -Bytes $ra.Bytes -BaseOffset $off -Width $width -ShowAscii $show_ascii
		}
	}

	$annotations = New-Object System.Collections.ArrayList
	# Lighter annotate on large / system binaries (full PE import/export dumps kill local-model context)
	$annotateMode = 'off'
	if ($annotate) {
		$annotateMode = 'full'
		$sysPath = $false
		try {
			$win = [string]$env:WINDIR
			if ($win -and $path.StartsWith($win, [StringComparison]::OrdinalIgnoreCase)) { $sysPath = $true }
			if ($path -match '(?i)\\(System32|SysWOW64|WinSxS)\\') { $sysPath = $true }
		} catch {}
		$bigFile = ($ra.FileSize -gt 2MB)
		if ($sysPath -or $bigFile) { $annotateMode = 'light' }
		# Explicit disasm/trace still get PE entry/sections; skip string flood
		if ($disasm -or $trace) {
			if ($annotateMode -eq 'full') { $annotateMode = 'full' }
		}

		$winEnd = $off + $ra.Bytes.Length
		$peAll = @()
		try { $peAll = @(Get-MBPeAnnotations -Path $path) } catch { $peAll = @() }
		try {
			foreach ($m in @(Get-MBFileMagicAnnotations -Path $path)) { [void]$annotations.Add($m) }
		} catch {}
		# Always include PE structural labels (headers, entry, sections) — cheap and high value
		foreach ($a in $peAll) {
			if ($a.kind -in @('pe', 'pe_entry', 'pe_section', 'pe_section_data')) {
				[void]$annotations.Add($a)
			}
		}
		if ($annotateMode -eq 'full') {
			foreach ($a in $peAll) {
				if ($a.kind -in @('pe_dir', 'pe_import', 'pe_export')) {
					[void]$annotations.Add($a)
				}
			}
			try {
				foreach ($c in @(Get-MBControlCharAnnotations -Bytes $ra.Bytes -BaseOffset $off -MaxHits 48)) {
					[void]$annotations.Add($c)
				}
			} catch {}
			try {
				foreach ($s in @(Get-MBStringAnnotations -Bytes $ra.Bytes -BaseOffset $off -MinLen 4 -MaxHits 40)) {
					[void]$annotations.Add($s)
				}
			} catch {}
			foreach ($a in $peAll) {
				try {
					$ao = [long]$a.offset
					if ($ao -ge $off -and $ao -lt $winEnd) {
						$dup = $false
						foreach ($ex in $annotations) {
							if ([long]$ex.offset -eq $ao -and [string]$ex.text -eq [string]$a.text) { $dup = $true; break }
						}
						if (-not $dup) { [void]$annotations.Add($a) }
					}
				} catch {}
			}
		} else {
			# light: only PE structure + a few in-window strings (no full import table)
			try {
				foreach ($s in @(Get-MBStringAnnotations -Bytes $ra.Bytes -BaseOffset $off -MinLen 6 -MaxHits 12)) {
					[void]$annotations.Add($s)
				}
			} catch {}
		}
		$annCap = if ($annotateMode -eq 'light') { 48 } else { 100 }
		if ($annotations.Count -gt $annCap) {
			$tmp = New-Object System.Collections.ArrayList
			for ($ai = 0; $ai -lt $annCap; $ai++) { [void]$tmp.Add($annotations[$ai]) }
			$annotations = $tmp
		}
	}

	$payload = [ordered]@{
		path = $path
		file_size = [long]$ra.FileSize
		offset = $off
		offset_hex = ('0x{0:X}' -f $off)
		length = $ra.Bytes.Length
		width = $width
		truncated = (-not $ra.Eof)
		show_ascii = $show_ascii
		annotate = $annotate
		annotate_mode = $annotateMode
		disasm = $disasm
		trace = $trace
		arch = $(if ($is64) { 'x64' } else { 'x86' })
		legend = 'disasm=true: x86/x64 + IAT/delay/export labels; uncertain db runs resync. hash=true SHA256 file+sections. functions=true prologue scan. entropy/carve/rva/section/at_entry. HexSearch ?? patterns; StringsScan; HexEdit preset=force_jcc|nop_range|ret0.'
	}
	if ($dump) { $payload['dump'] = $dump }
	try { $payload['byte_classes'] = Get-MBByteClassSummary -Bytes $ra.Bytes } catch {}
	if ($annotations -and $annotations.Count -gt 0) {
		$payload['annotations'] = @($annotations)
	}
	if ($peCtx -and $peCtx.Ok) {
		$payload['pe'] = [ordered]@{
			machine = $peCtx.Machine
			is64 = [bool]$peCtx.Is64
			entry_rva = $peCtx.EntryRva
			entry_file = $peCtx.EntryFile
			entry_file_hex = $(if ($null -ne $peCtx.EntryFile) { ('0x{0:X}' -f [long]$peCtx.EntryFile) } else { $null })
			image_base = ('0x{0:X}' -f [uint64]$peCtx.ImageBase)
		}
		# file offset -> RVA for current window start
		try {
			$curRva = Convert-MBPeOffsetToRva -Sections $peCtx.Sections -FileOffset $off
			if ($null -ne $curRva) {
				$payload['pe']['view_rva'] = $curRva
				$payload['pe']['view_rva_hex'] = ('0x{0:X}' -f [uint32]$curRva)
				$payload['pe']['view_va_hex'] = ('0x{0:X}' -f ([uint64]$peCtx.ImageBase + [uint32]$curRva))
			}
		} catch {}
	}

	# Symbol map for disasm/hash/dotnet (load once when needed)
	if ($disasm -or $trace -or $hash) {
		try { $symMap = Get-MBPeSymbolMap -Path $path } catch { $symMap = $null }
		if ($symMap -and $symMap.Ok) {
			$payload['symbols'] = [ordered]@{
				import_dlls   = [int]$symMap.ImportDllCount
				iat_slots     = [int]$symMap.IatSlotCount
				exports       = [int]$symMap.ExportCount
				export_module = [string]$symMap.ExportModule
				delay_dlls    = [int]$symMap.DelayDllCount
				delay_list    = $(if ($symMap.DelayDllCount -gt 0) { @($symMap.DelayDlls | Select-Object -First 12) } else { @() })
				bound_import  = $symMap.BoundImportNote
				is_dotnet     = [bool]$symMap.IsDotNet
			}
			if ($symMap.IsDotNet) {
				$payload['dotnet_warning'] = 'Managed (.NET) binary detected (CLR dir and/or mscoree). Native disasm at entry is often a bootstrap — do not treat as app logic.'
			}
		}
	}

	if ($hash) {
		try {
			$id = Get-MBPeIdentity -Path $path -SectionHashes $true -SymbolMap $symMap
			if ($id.Ok) {
				$payload['identity'] = [ordered]@{
					sha256      = $id.sha256
					file_size   = $id.file_size
					is_dotnet   = $id.is_dotnet
					dotnet_hint = $id.dotnet_hint
					delay_load  = $id.delay_load
					bound_import = $id.bound_import
					sections    = @($id.sections | Select-Object -First 24)
				}
			} else {
				$payload['identity_error'] = [string]$id.Error
			}
		} catch {
			$payload['identity_error'] = $_.Exception.Message
		}
	}

	if ($functions) {
		try {
			$fnSec = if ($section) { $section } else { '.text' }
			$fn = Find-MBX86Functions -Path $path -MaxHits 48 -Section $fnSec
			if ($fn.Ok) {
				$payload['functions'] = [ordered]@{
					section = $fn.section
					count   = $fn.count
					is64    = $fn.is64
					list    = $fn.functions
					hint    = $fn.hint
				}
			} else {
				$payload['functions_error'] = [string]$fn.Error
			}
		} catch {
			$payload['functions_error'] = $_.Exception.Message
		}
	}

	if ($disasm) {
		try {
			$d = Get-MBX86Disasm -Path $path -Offset $off -MaxInsns $max_insns -Is64 $is64 -SymbolMap $symMap
			if ($d.Ok) {
				# compact listing string for model readability
				$lines = New-Object System.Collections.ArrayList
				foreach ($ins in @($d.instructions)) {
					$mark = if ($ins.uncertain) { '?' } else { ' ' }
					$tline = ('{0}{1} {2,-20}  {3,-12} {4}' -f $mark, $ins.offset_hex, $ins.bytes, $ins.mnemonic, $ins.operands)
					if ($ins.is_control_flow -and $ins.target_hex) {
						$tline += ('  -> {0}' -f $ins.target_hex)
						if ($ins.is_conditional_jump) { $tline += (' | else {0}' -f $ins.fallthrough_hex) }
					}
					if ($ins.symbol -and ($tline -notmatch [regex]::Escape([string]$ins.symbol))) {
						$tline += ('  ; {0}' -f $ins.symbol)
					}
					[void]$lines.Add($tline)
				}
				$payload['disassembly'] = [ordered]@{
					offset = $d.offset
					offset_hex = $d.offset_hex
					count = $d.count
					is64 = $d.is64
					symbols_resolved = $d.symbols_resolved
					uncertain_count = $d.uncertain_count
					resync_count = $d.resync_count
					imports_mapped = $d.imports_mapped
					exports_mapped = $d.exports_mapped
					delay_dlls = $d.delay_dlls
					is_dotnet = $d.is_dotnet
					dotnet_warning = $d.dotnet_warning
					listing = ($lines -join "`n")
					instructions = @($d.instructions)
					how_to_follow = 'Lines starting with ? are uncertain (db) or resync skips. JMP/Jcc/CALL -> file_offset; [dll!func] via IAT/delay. functions=true for prologue list.'
				}
			} else {
				$payload['disassembly_error'] = [string]$d.Error
			}
		} catch {
			$payload['disassembly_error'] = $_.Exception.Message
		}
	}

	if ($trace) {
		try {
			$tr = Get-MBX86Trace -Path $path -Offset $off -MaxSteps $max_steps -Is64 $is64 -FollowCalls $follow_calls -PreferBranch $pref
			# decorate branch targets with symbols when possible
			if ($symMap -and $symMap.Ok -and $tr.branches) {
				foreach ($br in @($tr.branches)) {
					try {
						if ($br.taken) {
							$tk = [string][long]$br.taken
							if ($symMap.ExportByFileOffset.ContainsKey($tk)) { $br['taken_symbol'] = $symMap.ExportByFileOffset[$tk] }
						}
					} catch {}
				}
			}
			$payload['trace'] = $tr
			$payload['hint'] = 'trace.branches lists JE/JNE/Jcc alternatives. Set offset to taken_hex or not_taken_hex and disasm/trace again. Prefer HexView over manual ReadAllBytes.'
		} catch {
			$payload['trace_error'] = $_.Exception.Message
		}
	}

	if ($entropy) {
		try {
			$em = Get-MBFileEntropyMap -Path $path -MaxBlocks $entropy_blocks
			if ($em.Ok) {
				$payload['entropy'] = [ordered]@{
					block_size   = $em.block_size
					mean         = $em.mean_entropy
					min          = $em.min_entropy
					max          = $em.max_entropy
					high_count   = @($em.high_entropy).Count
					high_entropy = @($em.high_entropy | Select-Object -First 24)
					sample_blocks = @($em.blocks | Select-Object -First 12)
					hint         = $em.hint
				}
			} else {
				$payload['entropy_error'] = [string]$em.Error
			}
		} catch {
			$payload['entropy_error'] = $_.Exception.Message
		}
	}

	if ($carve) {
		try {
			$cv = Find-MBEmbeddedMz -Path $path -MaxHits 16
			if ($cv.Ok) {
				$payload['carve'] = [ordered]@{
					embedded_count = $cv.embedded_count
					embedded       = @($cv.embedded)
					all_hits       = @($cv.hits | Select-Object -First 20)
				}
			} else {
				$payload['carve_error'] = [string]$cv.Error
			}
		} catch {
			$payload['carve_error'] = $_.Exception.Message
		}
	}

	if ($cmpPath) {
		$payload['compare_path'] = $cmpPath
		$payload['compare_file_size'] = [long]$rb.FileSize
		$payload['diff_mode'] = $true
		$payload['side_by_side'] = [bool]$side_by_side
		$payload['diff_bytes_in_window'] = $diffCount
		$payload['first_diff_in_window'] = $(if ($firstDiffInWindow -ge 0) { $firstDiffInWindow } else { $null })
		$payload['first_diff_in_window_hex'] = $(if ($firstDiffInWindow -ge 0) { ('0x{0:X}' -f $firstDiffInWindow) } else { $null })
		$payload['next_diff_after_window'] = $nextDiffAfterWindow
	}

	if ($diffInfo) {
		$payload['next_diff_seek'] = [ordered]@{
			requested_from = Convert-MBOffsetToInt64 -Value $offset -Default 0
			landed_offset = $off
			found = [bool]$diffInfo.Found
			reason = [string]$diffInfo.Reason
			raw_diff_offset = $(if ($diffInfo.Found) { [long]$diffInfo.Offset } else { $null })
		}
	}

	if ($ra.Bytes.Length -eq 0) {
		$payload['note'] = 'offset at or past EOF'
	}

	return ConvertTo-MBJson $payload -Depth 12
}

function Invoke-HexSearch {
	param(
		[string]$path,
		[string]$pattern = '',
		[string]$hex = '',
		$offset = 0,
		[int]$maxResults = 32,
		$max_scan = 0
	)
	$path = Resolve-MBPath -Path $path
	if ([string]::IsNullOrWhiteSpace($path)) { return 'ERROR: Empty or invalid path' }
	if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return "ERROR: File not found: $path" }
	$pat = $pattern
	if ([string]::IsNullOrWhiteSpace($pat)) { $pat = $hex }
	if ([string]::IsNullOrWhiteSpace($pat)) {
		return 'ERROR: Provide pattern= or hex= (e.g. "4D 5A ?? 00" or "E8 ?? ?? ?? ??")'
	}
	$off = Convert-MBOffsetToInt64 -Value $offset -Default 0
	$ms = 0L
	if ($null -ne $max_scan -and [string]$max_scan -ne '') {
		try { $ms = [long]$max_scan } catch { $ms = 0 }
	}
	try {
		$r = Find-MBHexPattern -Path $path -Pattern $pat -Offset $off -MaxResults $maxResults -MaxScan $ms
		if (-not $r.Ok) { return "ERROR: $($r.Error)" }
		return ConvertTo-MBJson ([ordered]@{
			status      = 'ok'
			path        = $path
			pattern     = $pat
			pattern_len = $r.pattern_len
			count       = $r.count
			truncated   = $r.truncated
			hits        = $r.hits
			hint        = 'Use HexView offset=<hit.offset_hex> disasm=true or dump. ?? = wildcard byte.'
		}) -Depth 8
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

function Invoke-StringsScan {
	param(
		[string]$path,
		[int]$minLen = 4,
		[int]$maxHits = 80,
		$offset = 0,
		$max_scan = 0,
		[string]$encoding = 'both',
		[string]$filter = ''
	)
	$path = Resolve-MBPath -Path $path
	if ([string]::IsNullOrWhiteSpace($path)) { return 'ERROR: Empty or invalid path' }
	if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return "ERROR: File not found: $path" }
	$off = Convert-MBOffsetToInt64 -Value $offset -Default 0
	$ms = 0L
	if ($null -ne $max_scan -and [string]$max_scan -ne '') {
		try { $ms = [long]$max_scan } catch { $ms = 0 }
	}
	try {
		$r = Get-MBFileStrings -Path $path -MinLen $minLen -MaxHits $maxHits -Offset $off -MaxScan $ms -Encoding $encoding -Filter $filter
		if (-not $r.Ok) { return "ERROR: $($r.Error)" }
		return ConvertTo-MBJson ([ordered]@{
			status    = 'ok'
			path      = $path
			min_len   = $r.min_len
			encoding  = $r.encoding
			filter    = $r.filter
			count     = $r.count
			truncated = $r.truncated
			hits      = $r.hits
			hint      = 'filter=path|url|ip|registry|email|interesting or free text. encoding=ascii|utf16|both. HexView offset=hit.offset_hex to inspect.'
		}) -Depth 8
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

function Resolve-MBHexEditPreset {
	# Build patch bytes for named forensic patches. Returns @{ Ok; Patch; Note; Error }
	param(
		[string]$Preset,
		[string]$Path,
		[long]$Offset,
		[int]$Length = 0
	)
	$p = ([string]$Preset).Trim().ToLowerInvariant() -replace '[-\s]', '_'
	if ([string]::IsNullOrWhiteSpace($p)) {
		return @{ Ok = $false; Error = 'empty preset' }
	}
	# aliases
	switch ($p) {
		'force_jmp' { $p = 'force_jcc' }
		'force' { $p = 'force_jcc' }
		'always_jump' { $p = 'force_jcc' }
		'nop' { $p = 'nop_range' }
		'nops' { $p = 'nop_range' }
		'ret_0' { $p = 'ret0' }
		'return0' { $p = 'ret0' }
		'xor_ret' { $p = 'ret0' }
	}
	try {
		switch ($p) {
			'force_jcc' {
				# Short Jcc 7x xx -> EB xx (unconditional short jmp, same size)
				# Near Jcc 0F 8x rel32 -> 90 E9 rel32 (nop + near jmp; rel already relative to end of jcc which is same as end of e9+nop? 
				# 0F 8x dd dd dd dd is 6 bytes; E9 rel32 is 5 bytes — use EB with computed 8-bit if in range else 90 E9 with adjusted disp
				$br = Read-MBFileBytes -Path $Path -Offset $Offset -Length 6
				if (-not $br.Ok -or $br.Bytes.Length -lt 2) {
					return @{ Ok = $false; Error = 'cannot read bytes at offset for force_jcc' }
				}
				$b0 = [int]$br.Bytes[0]
				if ($b0 -ge 0x70 -and $b0 -le 0x7F) {
					$patch = [byte[]](0xEB, $br.Bytes[1])
					return @{ Ok = $true; Patch = $patch; Note = ('force_jcc: short {0:X2}->{1:X2} EB (always jmp short)' -f $b0, $b0) }
				}
				if ($b0 -eq 0x0F -and $br.Bytes.Length -ge 6) {
					$b1 = [int]$br.Bytes[1]
					if ($b1 -ge 0x80 -and $b1 -le 0x8F) {
						$rel = [BitConverter]::ToInt32($br.Bytes, 2)
						# Original: next = off+6, target = next+rel
						# New: 90 E9 rel' where next' = off+5, need next'+rel' = target => rel' = rel+1
						$newRel = $rel + 1
						$rb = [BitConverter]::GetBytes([int]$newRel)
						$patch = [byte[]](0x90, 0xE9, $rb[0], $rb[1], $rb[2], $rb[3])
						return @{ Ok = $true; Patch = $patch; Note = ('force_jcc: near 0F {0:X2} -> 90 E9 (nop+jmp near, rel adjusted +1)' -f $b1) }
					}
				}
				return @{ Ok = $false; Error = ('force_jcc: byte at offset is 0x{0:X2} (need 7x short Jcc or 0F 8x near Jcc)' -f $b0) }
			}
			'nop_range' {
				$len = $Length
				if ($len -le 0) { $len = 1 }
				if ($len -gt 4096) { $len = 4096 }
				$patch = New-Object byte[] $len
				for ($i = 0; $i -lt $len; $i++) { $patch[$i] = 0x90 }
				return @{ Ok = $true; Patch = $patch; Note = ("nop_range: {0} x NOP (0x90)" -f $len) }
			}
			'ret0' {
				# xor eax,eax ; ret  — works x86 and zero-extends to rax on x64 for 32-bit zeroing
				$patch = [byte[]](0x31, 0xC0, 0xC3)
				return @{ Ok = $true; Patch = $patch; Note = 'ret0: 31 C0 C3  (xor eax,eax; ret)' }
			}
			'ret' {
				$patch = [byte[]](0xC3)
				return @{ Ok = $true; Patch = $patch; Note = 'ret: C3' }
			}
			'int3' {
				$len = $Length
				if ($len -le 0) { $len = 1 }
				if ($len -gt 4096) { $len = 4096 }
				$patch = New-Object byte[] $len
				for ($i = 0; $i -lt $len; $i++) { $patch[$i] = 0xCC }
				return @{ Ok = $true; Patch = $patch; Note = ("int3: {0} x CC" -f $len) }
			}
			default {
				return @{ Ok = $false; Error = "unknown preset '$Preset' (use force_jcc|nop_range|ret0|ret|int3)" }
			}
		}
	} catch {
		return @{ Ok = $false; Error = $_.Exception.Message }
	}
}

function Invoke-HexEdit {
	param(
		[string]$path,
		$offset = 0,
		[string]$hex = '',
		$bytes = $null,
		[bool]$extend = $true,
		[bool]$backup = $true,
		[string]$preset = '',
		[int]$length = 0
	)
	$path = Resolve-MBPath -Path $path
	if ([string]::IsNullOrWhiteSpace($path)) { return 'ERROR: Empty or invalid path' }

	$off = Convert-MBOffsetToInt64 -Value $offset -Default -1
	if ($off -lt 0) { return 'ERROR: invalid offset (use decimal or 0xHEX)' }

	$presetNote = ''
	$patch = $null
	try {
		if (-not [string]::IsNullOrWhiteSpace($preset)) {
			$exists0 = Test-Path -LiteralPath $path -PathType Leaf
			if (-not $exists0 -and $preset -match '(?i)force') {
				return 'ERROR: preset=force_jcc requires an existing file at path'
			}
			$pr = Resolve-MBHexEditPreset -Preset $preset -Path $path -Offset $off -Length $length
			if (-not $pr.Ok) { return "ERROR: $($pr.Error)" }
			$patch = $pr.Patch
			$presetNote = [string]$pr.Note
		} elseif ($null -ne $bytes) {
			$list = New-Object System.Collections.Generic.List[byte]
			foreach ($b in @(Convert-MBForceArray $bytes)) {
				$n = 0
				if (-not [int]::TryParse(([string]$b), [ref]$n)) {
					return "ERROR: invalid byte value: $b"
				}
				if ($n -lt 0 -or $n -gt 255) { return "ERROR: byte out of range 0-255: $n" }
				$list.Add([byte]$n)
			}
			$patch = $list.ToArray()
		} elseif (-not [string]::IsNullOrWhiteSpace($hex)) {
			$patch = Convert-MBHexStringToBytes -Hex $hex
		} else {
			return 'ERROR: provide hex=, bytes=[], or preset=force_jcc|nop_range|ret0|ret|int3'
		}
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
	if ($null -eq $patch -or $patch.Length -eq 0) { return 'ERROR: empty patch' }
	if ($patch.Length -gt 65536) { return 'ERROR: patch too large (max 65536 bytes per call)' }

	$exists = Test-Path -LiteralPath $path -PathType Leaf
	$end = $off + $patch.Length
	$curSize = 0L
	if ($exists) {
		try { $curSize = (Get-Item -LiteralPath $path).Length } catch { $curSize = 0 }
	}
	$previewDump = Format-MBHexDump -Bytes $patch -BaseOffset $off -Width 16 -ShowAscii $true
	$beforeDump = ''
	$beforeBytes = $null
	if ($exists -and $curSize -gt $off) {
		try {
			$beforeLen = [int][Math]::Min([long]$patch.Length, $curSize - $off)
			if ($beforeLen -gt 0) {
				$br = Read-MBFileBytes -Path $path -Offset $off -Length $beforeLen
				if ($br.Ok -and $br.Bytes.Length -gt 0) {
					$beforeBytes = $br.Bytes
					$beforeDump = Format-MBHexDump -Bytes $br.Bytes -BaseOffset $off -Width 16 -ShowAscii $true
				}
			}
		} catch { $beforeDump = '' }
	}
	# Disasm before/after preview (best-effort)
	$disasmBefore = ''
	$disasmAfter = ''
	try {
		$peCtx = $null
		try { $peCtx = Get-MBPeDisasmContext -Path $path } catch {}
		$is64 = $false
		if ($peCtx -and $peCtx.Ok) { $is64 = [bool]$peCtx.Is64 }
		if ($exists -and $null -ne $beforeBytes -and $beforeBytes.Length -gt 0) {
			$linesB = New-Object System.Collections.ArrayList
			$ix = 0; $nIns = 0
			while ($ix -lt $beforeBytes.Length -and $nIns -lt 6) {
				$dec = Read-MBX86Instruction -Bytes $beforeBytes -Index $ix -FileOffset $off -Is64 $is64
				if (-not $dec.Ok) { break }
				[void]$linesB.Add(('{0}  {1,-16}  {2} {3}' -f $dec.offset_hex, $dec.bytes, $dec.mnemonic, $dec.operands))
				$ix = [int]$dec.next_index
				$nIns++
			}
			if ($linesB.Count -gt 0) { $disasmBefore = $linesB -join "`n" }
		}
		# after: patch bytes as if written
		$linesA = New-Object System.Collections.ArrayList
		$ix = 0; $nIns = 0
		while ($ix -lt $patch.Length -and $nIns -lt 6) {
			$dec = Read-MBX86Instruction -Bytes $patch -Index $ix -FileOffset $off -Is64 $is64
			if (-not $dec.Ok) { break }
			[void]$linesA.Add(('{0}  {1,-16}  {2} {3}' -f $dec.offset_hex, $dec.bytes, $dec.mnemonic, $dec.operands))
			$ix = [int]$dec.next_index
			$nIns++
		}
		if ($linesA.Count -gt 0) { $disasmAfter = $linesA -join "`n" }
	} catch {}

	$details = @"
Path: $path
Offset: $off (0x$('{0:X}' -f $off))
Bytes: $($patch.Length)
Preset: $(if ($presetNote) { $presetNote } elseif ($preset) { $preset } else { '(raw hex/bytes)' })
Extend past EOF: $extend
Backup (.bak): $backup
Exists: $exists (current size $curSize)
End after write: $end

$(if ($beforeDump) { "Before (existing bytes):`n$beforeDump`n`n" } else { '' })After (patch to write):
$previewDump
$(if ($disasmBefore) { "`nDisasm BEFORE:`n$disasmBefore`n" } else { '' })$(if ($disasmAfter) { "`nDisasm AFTER:`n$disasmAfter`n" } else { '' })
"@
	$codeShow = if ($disasmBefore -or $disasmAfter) {
		"$(if ($disasmBefore) { "BEFORE:`n$disasmBefore`n`n" } else { '' })AFTER:`n$disasmAfter`n`nHEX AFTER:`n$previewDump"
	} elseif ($beforeDump) {
		"BEFORE:`n$beforeDump`n`nAFTER:`n$previewDump"
	} else { $previewDump }
	if (-not (Request-Confirmation -Title 'HexEdit requires approval' -Details $details -Code $codeShow -CodeLang 'text')) {
		return 'BLOCKED BY USER: HexEdit denied by operator.'
	}

	$fs = $null
	try {
		$bakPath = $null
		if ($exists -and $backup) {
			$bakPath = Backup-MBFile -Path $path -Enabled $true
		}
		$parent = [System.IO.Path]::GetDirectoryName($path)
		if ($parent -and -not (Test-Path -LiteralPath $parent)) {
			[void][System.IO.Directory]::CreateDirectory($parent)
		}
		$mode = if ($exists) { [System.IO.FileMode]::Open } else { [System.IO.FileMode]::Create }
		$fs = [System.IO.File]::Open($path, $mode, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
		$needLen = $off + $patch.Length
		if ($needLen -gt $fs.Length) {
			if (-not $extend -and $exists) {
				return "ERROR: write past EOF (file size $($fs.Length), need $needLen). Set extend=true or lower offset."
			}
			$fs.SetLength($needLen)
		}
		[void]$fs.Seek($off, [System.IO.SeekOrigin]::Begin)
		$fs.Write($patch, 0, $patch.Length)
		$fs.Flush()
		$newSize = $fs.Length
		$tag = if ($script:MB.AutoApprove) { 'SUCCESS (auto-approved)' } else { 'SUCCESS' }
		try {
			$beforeShow = if ($disasmBefore) { $disasmBefore } elseif ($beforeDump) { $beforeDump } else { '' }
			$afterShow = if ($disasmAfter) { $disasmAfter } else { $previewDump }
			$sum = ('offset 0x{0:X}  wrote {1} byte(s)' -f $off, $patch.Length)
			if ($presetNote) { $sum = $sum + "  |  $presetNote" }
			elseif ($preset) { $sum = $sum + "  |  preset=$preset" }
			Write-MBHexDiffInline -Title ("HexEdit  {0}" -f $path) -Before $beforeShow -After $afterShow -Summary $sum -MaxLines 48
		} catch {}
		return ConvertTo-MBJson @{
			status     = $tag
			path       = $path
			offset     = $off
			offset_hex = ('0x{0:X}' -f $off)
			written    = $patch.Length
			file_size  = $newSize
			backup     = $bakPath
			preset     = $(if ($preset) { $preset } else { $null })
			preset_note = $(if ($presetNote) { $presetNote } else { $null })
			disasm_before = $(if ($disasmBefore) { $disasmBefore } else { $null })
			disasm_after  = $(if ($disasmAfter) { $disasmAfter } else { $null })
			dump       = $previewDump
		}
	} catch {
		return "ERROR: $($_.Exception.Message)"
	} finally {
		if ($null -ne $fs) { try { $fs.Dispose() } catch {} }
	}
}

function Invoke-GetPowerInfo {
	$reportPath = New-MBTempFile -Prefix 'mb-battery' -Extension '.html'
	try {
		$scheme = ''
		try {
			$scheme = (powercfg /getactivescheme 2>&1 | Out-String).Trim()
			if ($scheme.Length -gt 200) { $scheme = $scheme.Substring(0, 197) + '...' }
		} catch { $scheme = '' }

		$p = $null
		try {
			$p = Start-Process -FilePath "powercfg.exe" -ArgumentList "/batteryreport","/output",$reportPath -Wait -PassThru -WindowStyle Hidden -ErrorAction SilentlyContinue
		} catch {}

		if (-not (Test-Path -LiteralPath $reportPath)) {
			return ConvertTo-MBJson ([ordered]@{
				ok           = $true
				has_battery  = $false
				note         = 'No battery report (desktop or unsupported hardware).'
				active_scheme = $scheme
			})
		}
		$html = Get-Content -LiteralPath $reportPath -Raw -ErrorAction SilentlyContinue
		$designCap = if ($html -match 'Design Capacity</td>\s*<td[^>]*>([\d,]+)\s*mWh') { $matches[1] -replace ',','' } else { $null }
		$fullCap   = if ($html -match 'Full Charge Capacity</td>\s*<td[^>]*>([\d,]+)\s*mWh') { $matches[1] -replace ',','' } else { $null }
		$cycleCount = if ($html -match 'Cycle Count</td>\s*<td[^>]*>(\d+)</td>') { $matches[1] } else { $null }
		$healthPct = $null
		if ($designCap -and $fullCap) {
			try {
				$d = [double]$designCap
				$f = [double]$fullCap
				if ($d -gt 0) { $healthPct = [math]::Round(($f / $d) * 100, 1) }
			} catch {}
		}
		return ConvertTo-MBJson ([ordered]@{
			ok                       = $true
			has_battery              = $true
			design_capacity_mWh      = $designCap
			full_charge_capacity_mWh = $fullCap
			estimated_health_percent = $healthPct
			cycle_count              = $cycleCount
			active_scheme            = $scheme
		})
	} catch {
		return ConvertTo-MBJson ([ordered]@{
			ok    = $false
			error = $_.Exception.Message
		})
	} finally {
		try { Remove-MBTempPath -Path $reportPath } catch {}
	}
}

function Invoke-GetScheduledTasks {
	param(
		[int]$days = 7,
		[string]$filter,
		[bool]$includeDisabled = $false,
		[bool]$includeSystem = $false,
		[int]$max = 30,
		[string]$exportPath
	)
	try {
		if ($max -le 0) { $max = 30 }
		if ($max -gt 150) { $max = 150 }
		$allTasks = @(Get-ScheduledTask -ErrorAction SilentlyContinue)
		if ($allTasks.Count -eq 0) {
			return ConvertTo-MBJson @{ Error = "No scheduled tasks found or insufficient permissions." }
		}
		$cutoff = (Get-Date).AddDays(-[math]::Abs($days))
		$taskDetails = @()
		$systemCount = 0
		$recentCount = 0
		$enabledCount = 0
		$matchedCount = 0

		foreach ($task in $allTasks) {
			if ((Test-MBInterrupt)) { break }
			$info = $null
			try { $info = $task | Get-ScheduledTaskInfo -ErrorAction SilentlyContinue } catch {}

			$triggerTypes = @()
			if ($task.Triggers) {
				foreach ($trig in $task.Triggers) {
					$tType = "Unknown"
					if ($trig.PSObject.Properties['CimClass']) {
						$tType = $trig.CimClass.CimClassName -replace 'MSFT_Task','' -replace 'Trigger',''
					}
					$triggerTypes += $tType
				}
			}

			$principal = if ($task.Principal) { $task.Principal.UserId } else { $null }
			$taskPathStr = [string]$task.TaskPath
			$isSystem = ($principal -and ($principal -match 'SYSTEM')) -or ($taskPathStr -match '(?i)\\Microsoft\\Windows\\')
			$lastRun = if ($info -and $info.LastRunTime -and $info.LastRunTime.Year -gt 2000) { $info.LastRunTime } else { $null }
			$isRecent = $lastRun -and ($lastRun -gt $cutoff)
			$execute = $null
			$arguments = ""
			if ($task.Actions) {
				$firstAction = $task.Actions | Select-Object -First 1
				if ($firstAction) {
					$execute = $firstAction.Execute
					if ($firstAction.Arguments) { $arguments = $firstAction.Arguments }
				}
			}
			$stateStr = if ($task.State) { $task.State.ToString() } else { "Unknown" }
			$isEnabled = $stateStr -in @('Ready','Running','Queued')

			if ($isSystem) { $systemCount++ }
			if ($isRecent -and $isEnabled) { $recentCount++ }
			if ($isEnabled) { $enabledCount++ }

			$include = $true
			if (-not $includeDisabled -and -not $isEnabled) { $include = $false }
			if (-not $includeSystem -and $isSystem) { $include = $false }
			if ($filter) {
				$f = $filter.Trim().ToLower()
				if ($f -eq 'system') {
					# Explicit system filter overrides includeSystem=false
					$include = $isSystem
					if (-not $includeDisabled -and -not $isEnabled) { $include = $false }
				}
				elseif ($f -eq 'enabled' -and -not $isEnabled) { $include = $false }
				elseif ($f -eq 'recent' -and -not $isRecent) { $include = $false }
				elseif ($f -eq 'user' -or $f -eq 'nonsystem') {
					if ($isSystem) { $include = $false }
				}
				elseif ($f -notin @('system','enabled','recent','user','nonsystem')) {
					if (-not ($task.TaskName.ToLower().Contains($f) -or $taskPathStr.ToLower().Contains($f))) {
						$include = $false
					}
				}
			}

			if (-not $include) { continue }
			$matchedCount++

			$detail = [pscustomobject]@{
				TaskName       = $task.TaskName
				TaskPath       = $taskPathStr
				State          = $stateStr
				Enabled        = $isEnabled
				LastRunTime    = if ($lastRun) { $lastRun.ToString("yyyy-MM-dd HH:mm:ss") } else { "Never" }
				NextRunTime    = if ($info -and $info.NextRunTime -and $info.NextRunTime.Year -gt 2000) { $info.NextRunTime.ToString("yyyy-MM-dd HH:mm:ss") } else { "N/A" }
				LastTaskResult = if ($info) { $info.LastTaskResult } else { $null }
				Principal      = $principal
				IsSystem       = [bool]$isSystem
				Execute        = $execute
				Arguments      = $(if ($arguments -and $arguments.Length -gt 120) { $arguments.Substring(0, 117) + '...' } else { $arguments })
				TriggerTypes   = if ($triggerTypes.Count -gt 0) { ($triggerTypes -join '; ') } else { "None" }
			}
			$taskDetails += $detail
		}

		$taskDetails = @($taskDetails | Select-Object -First $max)

		$result = @{
			Summary = @{
				TotalTasks          = $allTasks.Count
				EnabledTasks        = $enabledCount
				SystemLevelTasks    = $systemCount
				RecentActivityTasks = $recentCount
				MatchedTasks        = $matchedCount
				ReturnedTasks       = $taskDetails.Count
				Truncated           = ($matchedCount -gt $taskDetails.Count)
				DaysLookback        = $days
				Max                 = $max
				IncludeSystem       = [bool]$includeSystem
				IncludeDisabled     = [bool]$includeDisabled
				FilterApplied       = $(if ($filter) { $filter } else { "None" })
			}
			Tasks = $taskDetails
			note  = 'Default: max=30, includeSystem=false (excludes \\Microsoft\\Windows\\ + SYSTEM principal). filter=system|enabled|recent|user or name substring. includeSystem=true for Microsoft tasks.'
		}

		if ($exportPath) {
			$exportPath = Resolve-MBPath $exportPath
			if (-not (Request-Confirmation -Title "Export scheduled tasks CSV" -Details "Export $($taskDetails.Count) tasks to:`n  $exportPath")) {
				$result.ExportStatus = "BLOCKED BY USER"
			} else {
				try {
					$taskDetails | Export-Csv -Path $exportPath -NoTypeInformation -Encoding UTF8 -Force
					$result.ExportStatus = "SUCCESS: $exportPath"
				} catch {
					$result.ExportStatus = "ERROR: $($_.Exception.Message)"
				}
			}
		}

		return Limit-MBResult (ConvertTo-MBJson $result -Depth 6)
	} catch {
		return ConvertTo-MBJson @{ Error = "GetScheduledTasks failed: $($_.Exception.Message)" }
	}
}

function Convert-IfJson {
	param($val)
	if ($val -is [string]) {
		$t = $val.Trim()
		if ($t.StartsWith('{') -or $t.StartsWith('[')) {
			try { return $t | ConvertFrom-Json -ErrorAction Stop } catch { return $val }
		}
	}
	return $val
}

function ConvertTo-MBHttpHeaderHash {
	param($headers)
	$h = @{}
	if ($null -eq $headers) { return $h }
	if ($headers -is [hashtable]) {
		foreach ($k in @($headers.Keys)) { $h[[string]$k] = [string]$headers[$k] }
		return $h
	}
	if ($headers -is [System.Collections.IDictionary]) {
		foreach ($k in @($headers.Keys)) { $h[[string]$k] = [string]$headers[$k] }
		return $h
	}
	try {
		foreach ($p in $headers.PSObject.Properties) {
			if ($p.Name -and $p.Name -notmatch '^PS') { $h[[string]$p.Name] = [string]$p.Value }
		}
	} catch {}
	return $h
}

function Get-MBHttpHeaderInsensitive {
	param([hashtable]$Headers, [string]$Name)
	if ($null -eq $Headers -or [string]::IsNullOrWhiteSpace($Name)) { return $null }
	foreach ($k in @($Headers.Keys)) {
		if ([string]::Equals([string]$k, $Name, [StringComparison]::OrdinalIgnoreCase)) {
			return [string]$Headers[$k]
		}
	}
	return $null
}

function Remove-MBHttpHeaderInsensitive {
	param([hashtable]$Headers, [string]$Name)
	if ($null -eq $Headers -or [string]::IsNullOrWhiteSpace($Name)) { return }
	$drop = @()
	foreach ($k in @($Headers.Keys)) {
		if ([string]::Equals([string]$k, $Name, [StringComparison]::OrdinalIgnoreCase)) { $drop += $k }
	}
	foreach ($k in $drop) { [void]$Headers.Remove($k) }
}

function Enable-MBHttpTls {
	try {
		$proto = [System.Net.SecurityProtocolType]::Tls12
		try { $proto = $proto -bor [System.Net.SecurityProtocolType]::Tls13 } catch {}
		try { $proto = $proto -bor [System.Net.SecurityProtocolType]::Tls11 } catch {}
		[System.Net.ServicePointManager]::SecurityProtocol = $proto
	} catch {
		try { [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12 } catch {}
	}
	try { [System.Net.ServicePointManager]::Expect100Continue = $false } catch {}
}

function Resolve-MBCurlExe {
	# System curl only (not aliases). Used for insecure HTTPS without process cert callbacks (AV-safe).
	try {
		$sys = Join-Path $env:SystemRoot 'System32\curl.exe'
		if (Test-Path -LiteralPath $sys) { return $sys }
	} catch {}
	try {
		$cmd = Get-Command curl.exe -ErrorAction SilentlyContinue
		if ($cmd -and $cmd.Path -and (Test-Path -LiteralPath $cmd.Path)) {
			if ($cmd.Path -notmatch '(?i)\\WindowsPowerShell\\|\\PowerShell\\') { return $cmd.Path }
		}
	} catch {}
	return $null
}

function Invoke-MBCurlHttp {
	# Out-of-process HTTPS via curl.exe. -k when VerifySsl is false (no ServicePointManager cert hooks).
	param(
		[string]$CurlPath,
		[string]$Method = 'GET',
		[string]$Url,
		[hashtable]$Headers = $null,
		[string]$Body = $null,
		[string]$ContentType = $null,
		[int]$TimeoutSec = 30,
		[bool]$VerifySsl = $true
	)
	if ([string]::IsNullOrWhiteSpace($CurlPath) -or -not (Test-Path -LiteralPath $CurlPath)) {
		return @{ ok = $false; error = 'curl.exe not found' }
	}
	if ($TimeoutSec -lt 1) { $TimeoutSec = 1 }
	if ($TimeoutSec -gt 600) { $TimeoutSec = 600 }

	$tmp = $null
	$hdrFile = $null
	$bodyFile = $null
	$dataFile = $null
	try {
		$tmp = Join-Path ([System.IO.Path]::GetTempPath()) ('mb-http-' + [guid]::NewGuid().ToString('n'))
		[void][System.IO.Directory]::CreateDirectory($tmp)
		$hdrFile = Join-Path $tmp 'resp.hdr'
		$bodyFile = Join-Path $tmp 'resp.body'

		$argList = New-Object System.Collections.ArrayList
		[void]$argList.Add('-sS')
		[void]$argList.Add('-L')
		[void]$argList.Add('--max-time')
		[void]$argList.Add("$TimeoutSec")
		[void]$argList.Add('-X')
		[void]$argList.Add(([string]$Method).ToUpperInvariant())
		if (-not $VerifySsl) { [void]$argList.Add('-k') }
		[void]$argList.Add('-D')
		[void]$argList.Add($hdrFile)
		[void]$argList.Add('-o')
		[void]$argList.Add($bodyFile)
		# Trailer: status | final URL after -L | content-type (parsed below)
		[void]$argList.Add('-w')
		[void]$argList.Add("`n__MBCURL__%{http_code}|%{url_effective}|%{content_type}")

		if ($Headers) {
			foreach ($k in @($Headers.Keys)) {
				$kn = [string]$k
				if ([string]::IsNullOrWhiteSpace($kn)) { continue }
				# Content-Type handled separately so it is not doubled
				if ([string]::Equals($kn, 'Content-Type', [StringComparison]::OrdinalIgnoreCase)) { continue }
				[void]$argList.Add('-H')
				[void]$argList.Add(('{0}: {1}' -f $kn, [string]$Headers[$k]))
			}
		}
		if ($ContentType) {
			[void]$argList.Add('-H')
			[void]$argList.Add(('Content-Type: {0}' -f $ContentType))
		}
		if ($null -ne $Body -and "$Body" -ne '') {
			$dataFile = Join-Path $tmp 'req.body'
			[System.IO.File]::WriteAllText($dataFile, [string]$Body, (New-Object System.Text.UTF8Encoding $false))
			[void]$argList.Add('--data-binary')
			[void]$argList.Add(('@' + $dataFile))
		}
		[void]$argList.Add([string]$Url)

		$nativeTimeout = $TimeoutSec + 15
		if ($nativeTimeout -lt 20) { $nativeTimeout = 20 }
		$r = Invoke-MBSetupNative -File $CurlPath -ArgumentList @($argList.ToArray()) -TimeoutSec $nativeTimeout
		$codeStr = (([string]$r.out) + '').Trim()
		$status = 0
		$finalUrl = [string]$Url
		$contentType = ''
		if ($codeStr -match '__MBCURL__(\d{3})\|([^\r\n|]*)\|([^\r\n]*)\s*$') {
			$status = [int]$Matches[1]
			if ($Matches[2]) { $finalUrl = [string]$Matches[2].Trim() }
			if ($Matches[3]) { $contentType = [string]$Matches[3].Trim() }
		} elseif ($codeStr -match '(\d{3})\s*$') {
			$status = [int]$Matches[1]
		} elseif ($codeStr -match '^\d{3}$') {
			$status = [int]$codeStr
		}

		$respHeaders = @{}
		if ($hdrFile -and (Test-Path -LiteralPath $hdrFile)) {
			try {
				$rawH = [System.IO.File]::ReadAllText($hdrFile)
				# Keep last header block after redirects
				$blocks = @([regex]::Split($rawH, '(?m)(?=^HTTP/\d)'))
				$block = ''
				foreach ($b in $blocks) { if ($b -and $b.Trim()) { $block = $b } }
				foreach ($line in ($block -split "`r?`n")) {
					if ($line -match '^(?i)HTTP/') { continue }
					if ($line -match '^\s*$') { continue }
					if ($line -match '^\s*([^:]+)\s*:\s*(.*)$') {
						$hk = $Matches[1].Trim()
						$hv = $Matches[2].Trim()
						if ($respHeaders.ContainsKey($hk)) {
							$respHeaders[$hk] = [string]$respHeaders[$hk] + ', ' + $hv
						} else {
							$respHeaders[$hk] = $hv
						}
					}
				}
			} catch {}
		}
		if ($contentType -and -not $respHeaders.ContainsKey('Content-Type') -and -not $respHeaders.ContainsKey('content-type')) {
			$respHeaders['Content-Type'] = $contentType
		} elseif (-not $contentType) {
			try {
				foreach ($hk in @($respHeaders.Keys)) {
					if ([string]::Equals([string]$hk, 'Content-Type', [StringComparison]::OrdinalIgnoreCase)) {
						$contentType = [string]$respHeaders[$hk]
						break
					}
				}
			} catch {}
		}

		$bodyText = ''
		if ($bodyFile -and (Test-Path -LiteralPath $bodyFile)) {
			try { $bodyText = [System.IO.File]::ReadAllText($bodyFile) } catch { $bodyText = '' }
		}

		# curl exit 0 = transport ok (even for 4xx/5xx). Non-zero = network/TLS/etc.
		if (-not $r.ok -and $status -lt 100) {
			$err = (([string]$r.err) + ' ' + ([string]$r.out)).Trim()
			if (-not $err) { $err = "curl exit $($r.exit)" }
			return @{
				ok           = $false
				error        = $err
				status_code  = $(if ($status -gt 0) { $status } else { $null })
				headers      = $respHeaders
				body_text    = $bodyText
				final_url    = $finalUrl
				content_type = $contentType
				method       = 'curl'
			}
		}

		return @{
			ok           = $true
			status_code  = $status
			headers      = $respHeaders
			body_text    = $bodyText
			final_url    = $finalUrl
			content_type = $contentType
			method       = 'curl'
			exit         = $r.exit
		}
	} catch {
		return @{ ok = $false; error = $_.Exception.Message; method = 'curl' }
	} finally {
		if ($tmp -and (Test-Path -LiteralPath $tmp)) {
			try { Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue } catch {}
		}
	}
}

function Read-MBHttpErrorResponseBody {
	param($Response, [int]$MaxChars = 32000)
	if ($null -eq $Response) { return $null }
	try {
		$stream = $Response.GetResponseStream()
		if ($null -eq $stream) { return $null }
		$reader = New-Object System.IO.StreamReader($stream)
		try {
			$text = $reader.ReadToEnd()
			if ($null -eq $text) { return $null }
			if ($text.Length -gt $MaxChars) {
				return $text.Substring(0, $MaxChars) + "`n... [truncated]"
			}
			return $text
		} finally {
			try { $reader.Close() } catch {}
			try { $stream.Close() } catch {}
		}
	} catch {
		return $null
	}
}

function ConvertFrom-MBHttpBodyPreferJson {
	param([string]$BodyText, [int]$MaxChars = 120000)
	$t = if ($null -eq $BodyText) { '' } else { [string]$BodyText }
	$truncated = $false
	if ($t.Length -gt $MaxChars) {
		$t = $t.Substring(0, $MaxChars) + "`n... [truncated]"
		$truncated = $true
	}
	$parsed = $t
	if (-not $truncated -and $t.Length -gt 0) {
		$trim = $t.TrimStart()
		if ($trim.StartsWith('{') -or $trim.StartsWith('[')) {
			try { $parsed = $t | ConvertFrom-Json -ErrorAction Stop } catch { $parsed = $t }
		}
	}
	return @{ text = $t; body = $parsed; truncated = $truncated }
}

function ConvertTo-MBFormUrlEncoded {
	param($FormData)
	if ($null -eq $FormData) { return '' }
	$parts = New-Object System.Collections.ArrayList
	if ($FormData -is [hashtable] -or $FormData -is [System.Collections.IDictionary]) {
		foreach ($k in @($FormData.Keys)) {
			[void]$parts.Add(('{0}={1}' -f [uri]::EscapeDataString([string]$k), [uri]::EscapeDataString([string]$FormData[$k])))
		}
	} else {
		try {
			foreach ($p in $FormData.PSObject.Properties) {
				if ($p.Name -and $p.Name -notmatch '^PS') {
					[void]$parts.Add(('{0}={1}' -f [uri]::EscapeDataString([string]$p.Name), [uri]::EscapeDataString([string]$p.Value)))
				}
			}
		} catch {
			return [string]$FormData
		}
	}
	return ($parts -join '&')
}

function Invoke-MakeHttpRequest {
	param(
		[string]$method = 'GET',
		[Parameter(Mandatory = $true)][string]$url,
		[object]$headers = $null,
		[object]$params = $null,
		[object]$json_body = $null,
		[object]$form_data = $null,
		[string]$raw_data = $null,
		[string]$bearer_token = $null,
		[string]$basic_auth_username = $null,
		[string]$basic_auth_password = $null,
		[object]$cookies = $null,
		[string]$content_type = $null,
		# Default false: self-signed / host-mismatch certs common on LAN gear
		[object]$verify_ssl = $false,
		[string]$user_agent = $null,
		[int]$timeout = 0
	)

	$url = ([string]$url).Trim()
	if ([string]::IsNullOrWhiteSpace($url)) {
		return ConvertTo-MBJson @{ success = $false; error = 'url required' }
	}
	if ($url -notmatch '^(?i)https?://') {
		return ConvertTo-MBJson @{ success = $false; error = 'url must start with http:// or https://'; url = $url }
	}

	$methodU = ([string]$method).Trim().ToUpperInvariant()
	if ($methodU -notin @('GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS')) {
		return ConvertTo-MBJson @{ success = $false; error = "unsupported method '$method'" }
	}

	$doVerify = $true
	try { $doVerify = Convert-MBToBool -Value $verify_ssl -Default $false } catch { $doVerify = $false }

	$headers   = Convert-IfJson $headers
	$params    = Convert-IfJson $params
	$json_body = Convert-IfJson $json_body
	$form_data = Convert-IfJson $form_data
	$cookies   = Convert-IfJson $cookies

	$headerHash = ConvertTo-MBHttpHeaderHash -headers $headers
	if ($user_agent) {
		Remove-MBHttpHeaderInsensitive -Headers $headerHash -Name 'User-Agent'
		$headerHash['User-Agent'] = [string]$user_agent
	} elseif (-not (Get-MBHttpHeaderInsensitive -Headers $headerHash -Name 'User-Agent')) {
		$headerHash['User-Agent'] = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36 MiniBot/1.0'
	}

	if ($params) {
		$q = New-Object System.Collections.ArrayList
		if ($params -is [hashtable] -or $params -is [System.Collections.IDictionary]) {
			foreach ($k in @($params.Keys)) {
				[void]$q.Add(('{0}={1}' -f [uri]::EscapeDataString([string]$k), [uri]::EscapeDataString([string]$params[$k])))
			}
		} else {
			foreach ($p in $params.PSObject.Properties) {
				if ($p.Name -and $p.Name -notmatch '^PS') {
					[void]$q.Add(('{0}={1}' -f [uri]::EscapeDataString([string]$p.Name), [uri]::EscapeDataString([string]$p.Value)))
				}
			}
		}
		if ($q.Count -gt 0) {
			$sep = if ($url -match '\?') { '&' } else { '?' }
			$url = $url + $sep + ($q -join '&')
		}
	}

	if ($basic_auth_username -and $null -ne $basic_auth_password) {
		$pair = '{0}:{1}' -f $basic_auth_username, $basic_auth_password
		Remove-MBHttpHeaderInsensitive -Headers $headerHash -Name 'Authorization'
		$headerHash['Authorization'] = 'Basic ' + [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($pair))
	} elseif ($bearer_token) {
		Remove-MBHttpHeaderInsensitive -Headers $headerHash -Name 'Authorization'
		$headerHash['Authorization'] = 'Bearer ' + ([string]$bearer_token).Trim()
	}

	if ($cookies) {
		$cookieParts = New-Object System.Collections.ArrayList
		if ($cookies -is [hashtable] -or $cookies -is [System.Collections.IDictionary]) {
			foreach ($k in @($cookies.Keys)) { [void]$cookieParts.Add(('{0}={1}' -f $k, $cookies[$k])) }
		} else {
			foreach ($p in $cookies.PSObject.Properties) {
				if ($p.Name -and $p.Name -notmatch '^PS') { [void]$cookieParts.Add(('{0}={1}' -f $p.Name, $p.Value)) }
			}
		}
		if ($cookieParts.Count -gt 0) {
			Remove-MBHttpHeaderInsensitive -Headers $headerHash -Name 'Cookie'
			$headerHash['Cookie'] = ($cookieParts -join '; ')
		}
	}

	# Body + Content-Type (PS 5.1 IWR: use -ContentType, not Content-Type header)
	$body = $null
	$ct = ([string]$content_type).Trim()
	if (-not $ct) { $ct = Get-MBHttpHeaderInsensitive -Headers $headerHash -Name 'Content-Type' }
	Remove-MBHttpHeaderInsensitive -Headers $headerHash -Name 'Content-Type'

	if ($null -ne $json_body -and "$json_body" -ne '') {
		if ($json_body -is [string]) {
			$body = [string]$json_body
		} else {
			$body = ($json_body | ConvertTo-Json -Depth 12 -Compress)
		}
		if (-not $ct) { $ct = 'application/json; charset=utf-8' }
	} elseif ($null -ne $form_data -and "$form_data" -ne '') {
		if ($form_data -is [string]) {
			$body = [string]$form_data
		} else {
			$body = ConvertTo-MBFormUrlEncoded -FormData $form_data
		}
		if (-not $ct) { $ct = 'application/x-www-form-urlencoded; charset=utf-8' }
	} elseif ($null -ne $raw_data -and "$raw_data" -ne '') {
		$body = [string]$raw_data
	}

	$timeoutSec = if ($timeout -gt 0) { [int]$timeout } else { 30 }
	if ($timeoutSec -lt 1) { $timeoutSec = 1 }
	if ($timeoutSec -gt 600) { $timeoutSec = 600 }

	$hasCreds = $false
	if ($bearer_token -or ($basic_auth_username -and $null -ne $basic_auth_password)) { $hasCreds = $true }
	if (Get-MBHttpHeaderInsensitive -Headers $headerHash -Name 'Authorization') { $hasCreds = $true }
	if (-not (Request-MBNetworkApproval -Method $methodU -Url $url -HasCredentials $hasCreds -ToolName 'MakeHttpRequest')) {
		return 'BLOCKED BY USER: HTTP request denied by operator.'
	}

	# Insecure HTTPS: use system curl.exe -k (no process-wide cert callback — that trips AV).
	$needInsecureHttps = ((-not $doVerify) -and ($url -match '^(?i)https:'))
	if ($needInsecureHttps) {
		$curl = Resolve-MBCurlExe
		if (-not $curl) {
			return ConvertTo-MBJson ([ordered]@{
				success    = $false
				error      = 'Bad/self-signed HTTPS needs system curl.exe (System32). Install curl or use verify_ssl=true with a valid cert.'
				url        = $url
				verify_ssl = $false
			})
		}
		$cr = Invoke-MBCurlHttp -CurlPath $curl -Method $methodU -Url $url -Headers $headerHash -Body $body -ContentType $ct -TimeoutSec $timeoutSec -VerifySsl $false
		if (-not $cr.ok -and -not $cr.status_code) {
			return Limit-MBResult (ConvertTo-MBJson ([ordered]@{
				success     = $false
				error       = $(if ($cr.error) { $cr.error } else { 'curl request failed' })
				status_code = $cr.status_code
				body        = $cr.body_text
				method      = $methodU
				url         = $url
				verify_ssl  = $false
				transport   = 'curl'
			}) -Depth 8)
		}
		$bodyPack = ConvertFrom-MBHttpBodyPreferJson -BodyText ([string]$cr.body_text)
		$okHttp = ($cr.status_code -ge 200 -and $cr.status_code -lt 400)
		$ctOut = $(if ($cr.content_type) { $cr.content_type } else { Get-MBHttpHeaderValueInsensitive -Headers $cr.headers -Name 'Content-Type' })
		return Limit-MBResult (ConvertTo-MBJson ([ordered]@{
			success         = [bool]$okHttp
			status_code     = [int]$cr.status_code
			headers         = $cr.headers
			body            = $bodyPack.body
			body_truncated  = [bool]$bodyPack.truncated
			final_url       = $(if ($cr.final_url) { $cr.final_url } else { $url })
			content_type    = $ctOut
			content_length  = $(try { [int64]([string]$cr.body_text).Length } catch { $null })
			method          = $methodU
			verify_ssl      = $false
			transport       = 'curl'
			error           = $(if (-not $okHttp) { "HTTP $($cr.status_code)" } else { $null })
		}) -Depth 10)
	}

	$iwr = @{
		Uri             = $url
		Method          = $methodU
		Headers         = $headerHash
		UseBasicParsing = $true
		TimeoutSec      = $timeoutSec
	}
	if ($null -ne $body) { $iwr['Body'] = $body }
	if ($ct) { $iwr['ContentType'] = $ct }

	Enable-MBHttpTls
	try {
		$resp = Invoke-WebRequest @iwr -ErrorAction Stop
		$respHeaders = @{}
		try {
			foreach ($h in $resp.Headers.GetEnumerator()) {
				$respHeaders[[string]$h.Key] = ($h.Value -join ', ')
			}
		} catch {}
		$bodyPack = ConvertFrom-MBHttpBodyPreferJson -BodyText ([string]$resp.Content)
		$finalUrl = $url
		try { $finalUrl = $resp.BaseResponse.ResponseUri.AbsoluteUri } catch {}
		$clen = $null
		try { $clen = [int64]$resp.RawContentLength } catch {
			try { $clen = [int64]([string]$resp.Content).Length } catch {}
		}
		$ctIwr = Get-MBHttpHeaderValueInsensitive -Headers $respHeaders -Name 'Content-Type'
		return Limit-MBResult (ConvertTo-MBJson ([ordered]@{
			success         = $true
			status_code     = [int]$resp.StatusCode
			headers         = $respHeaders
			body            = $bodyPack.body
			body_truncated  = [bool]$bodyPack.truncated
			final_url       = $finalUrl
			content_type    = $ctIwr
			content_length  = $clen
			method          = $methodU
			verify_ssl      = [bool]$doVerify
			transport       = 'iwr'
		}) -Depth 10)
	} catch {
		$status = $null
		$errBody = $null
		$webEx = $_.Exception
		$respObj = $null
		try { $respObj = $webEx.Response } catch {}
		if ($null -eq $respObj) {
			try { $respObj = $webEx.InnerException.Response } catch {}
		}
		if ($respObj) {
			try { $status = [int]$respObj.StatusCode } catch {
				try { $status = [int]$respObj.StatusCode.value__ } catch {}
			}
			$errBody = Read-MBHttpErrorResponseBody -Response $respObj
		}
		$parsedErr = $null
		if ($errBody) {
			$pack = ConvertFrom-MBHttpBodyPreferJson -BodyText $errBody -MaxChars 32000
			$parsedErr = $pack.body
			$errBody = $pack.text
		}
		return Limit-MBResult (ConvertTo-MBJson ([ordered]@{
			success     = $false
			error       = $webEx.Message
			status_code = $status
			body        = $(if ($null -ne $parsedErr) { $parsedErr } else { $errBody })
			method      = $methodU
			url         = $url
			verify_ssl  = [bool]$doVerify
			transport   = 'iwr'
		}) -Depth 8)
	}
}

function Get-MBDefaultBrowserUserAgent {
	return 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36'
}

function Convert-MBResolveAbsoluteUrl {
	param(
		[string]$BaseUrl,
		[string]$Href
	)
	if ([string]::IsNullOrWhiteSpace($Href)) { return $null }
	$h = $Href.Trim()
	if ($h.Length -eq 0) { return $null }
	if ($h.StartsWith('#')) { return $null }
	if ($h -match '^(?i)(javascript|mailto|tel|data):') { return $null }
	# Unwrap DDG/Bing redirect wrappers (uddg= / bing ck).
	$unwrapOnce = {
		param([string]$U)
		if ([string]::IsNullOrWhiteSpace($U)) { return $U }
		$x = $U
		if ($x -match '(?i)[?&]uddg=([^&]+)') {
			try { $x = [uri]::UnescapeDataString($Matches[1]) } catch {}
		} elseif ($x -match '(?i)[?&]uddg%3D([^&]+)') {
			try { $x = [uri]::UnescapeDataString([uri]::UnescapeDataString($Matches[1])) } catch {}
		}
		if ($x -match '(?i)bing\.com/ck/' -and $x -match '(?i)[?&]u=([^&]+)') {
			try { $x = [uri]::UnescapeDataString($Matches[1]) } catch {}
		}
		if ($x -match '(?i)^https?://[^/]+/.*[?&]url=(https?%3A[^&]+)') {
			try { $x = [uri]::UnescapeDataString($Matches[1]) } catch {}
		}
		return $x
	}
	try { $h = & $unwrapOnce $h } catch {}
	try { $h = & $unwrapOnce $h } catch {}  # second pass for double-wrap
	try {
		if ($h -match '^(?i)https?://') { return $h }
		if ($h.StartsWith('//')) {
			return ('https:{0}' -f $h)
		}
		if ([string]::IsNullOrWhiteSpace($BaseUrl)) { return $null }
		$base = New-Object System.Uri($BaseUrl)
		return (New-Object System.Uri($base, $h)).AbsoluteUri
	} catch {
		return $null
	}
}

function Get-MBHttpHeaderValueInsensitive {
	param($Headers, [string]$Name)
	if ($null -eq $Headers -or [string]::IsNullOrWhiteSpace($Name)) { return $null }
	try {
		if ($Headers -is [hashtable] -or $Headers -is [System.Collections.IDictionary]) {
			foreach ($k in @($Headers.Keys)) {
				if ([string]::Equals([string]$k, $Name, [StringComparison]::OrdinalIgnoreCase)) {
					return [string]$Headers[$k]
				}
			}
		}
	} catch {}
	return $null
}

function Convert-MBHtmlStripToText {
	param([string]$HtmlChunk)
	if ([string]::IsNullOrEmpty($HtmlChunk)) { return '' }
	$t = [string]$HtmlChunk
	$t = [regex]::Replace($t, '(?is)<script[^>]*>.*?</script>', ' ')
	$t = [regex]::Replace($t, '(?is)<style[^>]*>.*?</style>', ' ')
	$t = [regex]::Replace($t, '(?is)<noscript[^>]*>.*?</noscript>', ' ')
	$t = [regex]::Replace($t, '(?is)<!--.*?-->', ' ')
	$t = [regex]::Replace($t, '(?is)</?(p|div|li|tr|h[1-6]|section|article|header|footer|br|hr|blockquote|pre)[^>]*>', "`n")
	$t = [regex]::Replace($t, '(?i)<br\s*/?>', "`n")
	$t = [regex]::Replace($t, '<[^>]+>', ' ')
	$t = [System.Net.WebUtility]::HtmlDecode($t)
	$t = $t -replace "`r`n", "`n" -replace "`r", "`n"
	$t = [regex]::Replace($t, '[ \t\f\v]+', ' ')
	$t = [regex]::Replace($t, '\n{3,}', "`n`n")
	return $t.Trim()
}

function Convert-MBHtmlToReadable {
	# Agent-oriented extract: title, main text, absolute links, JS-shell detection.
	param(
		[string]$Html,
		[string]$BaseUrl = '',
		[int]$MaxLength = 12000,
		[int]$MaxLinks = 24,
		[bool]$ExtractLinks = $true
	)
	if ($null -eq $Html) { $Html = '' }
	if ($MaxLength -le 0) { $MaxLength = 12000 }
	if ($MaxLength -gt 100000) { $MaxLength = 100000 }
	if ($MaxLinks -le 0) { $MaxLinks = 24 }
	if ($MaxLinks -gt 80) { $MaxLinks = 80 }

	$title = ''
	if ($Html -match '(?is)<title[^>]*>(.*?)</title>') {
		$title = Convert-MBHtmlStripToText -HtmlChunk $Matches[1]
		$title = ($title -replace '\s+', ' ').Trim()
	}
	if (-not $title -and $Html -match '(?is)<meta[^>]+property=["'']og:title["''][^>]+content=["'']([^"'']+)["'']') {
		$title = [System.Net.WebUtility]::HtmlDecode($Matches[1]).Trim()
	}
	if (-not $title) { $title = 'No title' }

	# Prefer main/article/role=main; drop chrome
	$work = $Html
	$main = $null
	foreach ($pat in @(
		'(?is)<main\b[^>]*>(.*?)</main>',
		'(?is)<article\b[^>]*>(.*?)</article>',
		'(?is)<div[^>]+role=["'']main["''][^>]*>(.*?)</div>',
		'(?is)<div[^>]+id=["''](content|main|main-content|article|post|primary)["''][^>]*>(.*?)</div>'
	)) {
		$m = [regex]::Match($work, $pat)
		if ($m.Success) {
			$main = if ($m.Groups.Count -gt 2 -and $m.Groups[2].Success) { $m.Groups[2].Value } else { $m.Groups[1].Value }
			if ((Convert-MBHtmlStripToText -HtmlChunk $main).Length -ge 80) { break }
			$main = $null
		}
	}
	if (-not $main -and $work -match '(?is)<body[^>]*>(.*?)</body>') {
		$main = $Matches[1]
	}
	if (-not $main) { $main = $work }

	# Strip common chrome from body extract
	$main = [regex]::Replace($main, '(?is)<(nav|footer|header|aside|form)\b[^>]*>.*?</\1>', ' ')
	$main = [regex]::Replace($main, '(?is)<div[^>]+class=["''][^"'']*\b(nav|menu|sidebar|footer|cookie|banner|ads?|share|comment)[^"'']*["''][^>]*>.*?</div>', ' ')

	$text = Convert-MBHtmlStripToText -HtmlChunk $main
	# Prefer native cleaner when available and text is thin
	if ($script:HasNative -and $text.Length -lt 40 -and $Html.Length -gt 200) {
		try {
			$nat = [MiniBot.Core.Native]::HtmlToText($Html, $MaxLength)
			if ($nat -match '(?s)\*\*Content:\*\*\s*(.*)$') {
				$nt = $Matches[1].Trim()
				if ($nt.Length -gt $text.Length) { $text = $nt }
			}
		} catch {}
	}

	$truncated = $false
	if ($text.Length -gt $MaxLength) {
		$text = $text.Substring(0, $MaxLength) + "`n`n[content truncated]"
		$truncated = $true
	}

	# Link harvest
	$links = New-Object System.Collections.ArrayList
	if ($ExtractLinks) {
		$seen = @{}
		$ms = [regex]::Matches($Html, '(?is)<a\b[^>]*href\s*=\s*["'']([^"'']+)["''][^>]*>(.*?)</a>')
		foreach ($lm in $ms) {
			if ($links.Count -ge $MaxLinks) { break }
			$href = $lm.Groups[1].Value.Trim()
			$abs = Convert-MBResolveAbsoluteUrl -BaseUrl $BaseUrl -Href $href
			if (-not $abs) { continue }
			if ($seen.ContainsKey($abs.ToLowerInvariant())) { continue }
			$seen[$abs.ToLowerInvariant()] = $true
			$lt = Convert-MBHtmlStripToText -HtmlChunk $lm.Groups[2].Value
			$lt = ($lt -replace '\s+', ' ').Trim()
			if ($lt.Length -gt 120) { $lt = $lt.Substring(0, 117) + '...' }
			if (-not $lt) { $lt = $abs }
			[void]$links.Add([ordered]@{ text = $lt; url = $abs })
		}
	}

	# JS-shell / SPA detection
	$scriptBytes = 0
	foreach ($sm in [regex]::Matches($Html, '(?is)<script\b[^>]*>(.*?)</script>')) {
		$scriptBytes += $sm.Groups[1].Value.Length
	}
	$scriptTagCount = ([regex]::Matches($Html, '(?i)<script\b')).Count
	$plainLen = $text.Length
	$needsRender = $false
	$renderReasons = New-Object System.Collections.ArrayList
	if ($Html -match '(?i)enable\s+javascript|requires?\s+javascript|noscript') {
		if ($plainLen -lt 400) {
			$needsRender = $true
			[void]$renderReasons.Add('javascript_required_message')
		}
	}
	if ($plainLen -lt 180 -and $scriptBytes -gt 4000) {
		$needsRender = $true
		[void]$renderReasons.Add('thin_text_heavy_script')
	}
	if ($plainLen -lt 120 -and $scriptTagCount -ge 6) {
		$needsRender = $true
		[void]$renderReasons.Add('many_scripts_little_text')
	}
	if ($Html -match '(?i)id=["''](root|app|__next|__nuxt)["'']' -and $plainLen -lt 250) {
		$needsRender = $true
		[void]$renderReasons.Add('spa_root_shell')
	}
	if ($Html -match '(?i)__NEXT_DATA__|ng-version=|data-reactroot' -and $plainLen -lt 300) {
		$needsRender = $true
		[void]$renderReasons.Add('framework_shell')
	}

	return [ordered]@{
		title           = $title
		text            = $text
		text_length     = $plainLen
		truncated      = $truncated
		links           = @($links)
		link_count      = $links.Count
		needs_render    = $needsRender
		render_reasons  = @($renderReasons)
		script_tags     = $scriptTagCount
		script_bytes    = $scriptBytes
	}
}

function Get-MBContentKindFromTypeAndBody {
	param(
		[string]$ContentType = '',
		[string]$Body = ''
	)
	$ct = ([string]$ContentType).ToLowerInvariant()
	if ($ct -match 'json') { return 'json' }
	if ($ct -match 'text/plain') { return 'text' }
	if ($ct -match 'text/markdown|text/x-markdown') { return 'markdown' }
	if ($ct -match 'text/csv') { return 'csv' }
	if ($ct -match 'text/html|application/xhtml') { return 'html' }
	if ($ct -match 'image/') { return 'image' }
	if ($ct -match 'audio/|video/') { return 'media' }
	if ($ct -match 'application/pdf') { return 'pdf' }
	if ($ct -match 'application/octet-stream|application/zip|application/x-|application/wasm') { return 'binary' }
	$trim = if ($null -eq $Body) { '' } else { $Body.TrimStart() }
	if ($trim.StartsWith('{') -or $trim.StartsWith('[')) {
		try { $null = $trim | ConvertFrom-Json -ErrorAction Stop; return 'json' } catch {}
	}
	if ($trim -match '(?i)^<!DOCTYPE\s+html|^<html\b') { return 'html' }
	if ($ct -match 'text/') { return 'text' }
	if ([string]::IsNullOrWhiteSpace($ct) -and $trim.Length -gt 0) {
		# Heuristic: high ratio of non-printables → binary
		$sample = if ($trim.Length -gt 512) { $trim.Substring(0, 512) } else { $trim }
		$ctrl = 0
		foreach ($ch in $sample.ToCharArray()) {
			$o = [int]$ch
			if ($o -lt 9 -or ($o -gt 13 -and $o -lt 32)) { $ctrl++ }
		}
		if ($sample.Length -gt 0 -and ($ctrl / $sample.Length) -gt 0.15) { return 'binary' }
		return 'text'
	}
	if ([string]::IsNullOrWhiteSpace($ct)) { return 'unknown' }
	return 'other'
}

function Invoke-MBHttpGetPage {
	# Shared GET for BrowsePage / SearchWeb. Returns status, body, final_url, content_type, headers, transport.
	param(
		[Parameter(Mandatory)][string]$Url,
		[bool]$VerifySsl = $false,
		[string]$UserAgent = '',
		[int]$TimeoutSec = 30,
		[hashtable]$ExtraHeaders = $null
	)
	$ua = if ($UserAgent) { $UserAgent } else { Get-MBDefaultBrowserUserAgent }
	$headers = @{
		'User-Agent' = $ua
		'Accept'     = 'text/html,application/xhtml+xml,application/xml;q=0.9,application/json;q=0.8,*/*;q=0.7'
		'Accept-Language' = 'en-US,en;q=0.9'
	}
	if ($ExtraHeaders) {
		foreach ($k in @($ExtraHeaders.Keys)) { $headers[[string]$k] = [string]$ExtraHeaders[$k] }
	}
	$result = [ordered]@{
		ok           = $false
		status_code  = 0
		body         = ''
		final_url    = $Url
		content_type = ''
		headers      = @{}
		transport    = ''
		error        = $null
	}
	if ((-not $VerifySsl) -and ($Url -match '^(?i)https:')) {
		$curl = Resolve-MBCurlExe
		if (-not $curl) {
			$result.error = 'Bad/self-signed HTTPS needs system curl.exe (System32). Install curl or pass verify_ssl=true.'
			return $result
		}
		$cr = Invoke-MBCurlHttp -CurlPath $curl -Method 'GET' -Url $Url -Headers $headers -TimeoutSec $TimeoutSec -VerifySsl $false
		$result.transport = 'curl'
		$result.status_code = [int]$(if ($cr.status_code) { $cr.status_code } else { 0 })
		$result.body = [string]$cr.body_text
		if ($cr.final_url) { $result.final_url = [string]$cr.final_url }
		if ($cr.content_type) { $result.content_type = [string]$cr.content_type }
		elseif ($cr.headers) {
			$ct = Get-MBHttpHeaderValueInsensitive -Headers $cr.headers -Name 'Content-Type'
			if ($ct) { $result.content_type = $ct }
		}
		if ($cr.headers) { $result.headers = $cr.headers }
		if (-not $cr.ok -and $result.status_code -lt 100) {
			$result.error = $(if ($cr.error) { $cr.error } else { 'curl failed' })
			return $result
		}
		$result.ok = $true
		return $result
	}
	$iwr = @{
		Uri             = $Url
		UseBasicParsing = $true
		TimeoutSec      = $TimeoutSec
		Headers         = $headers
	}
	Enable-MBHttpTls
	try {
		$resp = Invoke-WebRequest @iwr -ErrorAction Stop
		$result.transport = 'iwr'
		$result.ok = $true
		$result.status_code = [int]$resp.StatusCode
		$result.body = [string]$resp.Content
		try { $result.final_url = $resp.BaseResponse.ResponseUri.AbsoluteUri } catch {}
		$hdrs = @{}
		try {
			foreach ($h in $resp.Headers.GetEnumerator()) {
				$hdrs[[string]$h.Key] = ($h.Value -join ', ')
			}
		} catch {}
		$result.headers = $hdrs
		$ct = Get-MBHttpHeaderValueInsensitive -Headers $hdrs -Name 'Content-Type'
		if ($ct) { $result.content_type = $ct }
		return $result
	} catch {
		$result.transport = 'iwr'
		$result.error = $_.Exception.Message
		try {
			$respObj = $_.Exception.Response
			if ($respObj) {
				$result.status_code = [int]$respObj.StatusCode
				$errBody = Read-MBHttpErrorResponseBody -Response $respObj
				if ($errBody) { $result.body = $errBody; $result.ok = $true }
			}
		} catch {}
		return $result
	}
}

function Invoke-BrowsePage {
	param(
		[Parameter(Mandatory = $true)][string]$url,
		[int]$max_length = 8000,
		[object]$verify_ssl = $false,
		[string]$user_agent = $null,
		[bool]$extract_links = $true,
		[int]$max_links = 24
	)
	if (-not (Request-MBNetworkApproval -Method 'GET' -Url $url -HasCredentials $false -ToolName 'BrowsePage')) {
		return "BLOCKED BY USER: BrowsePage denied by operator."
	}
	$doVerify = $true
	try { $doVerify = Convert-MBToBool -Value $verify_ssl -Default $false } catch { $doVerify = $false }
	$url = ([string]$url).Trim()
	if ($url -notmatch '^(?i)https?://') {
		return ConvertTo-MBJson ([ordered]@{ success = $false; error = 'url must start with http:// or https://'; url = $url })
	}

	try {
		$got = Invoke-MBHttpGetPage -Url $url -VerifySsl $doVerify -UserAgent $user_agent -TimeoutSec 30
		if (-not $got.ok -and -not $got.body) {
			return ConvertTo-MBJson ([ordered]@{
				success = $false
				error   = $(if ($got.error) { $got.error } else { 'request failed' })
				url     = $url
				final_url = $got.final_url
				status_code = $got.status_code
				transport = $got.transport
			})
		}

		$finalUrl = if ($got.final_url) { [string]$got.final_url } else { $url }
		$body = [string]$got.body
		$ct = [string]$got.content_type
		$kind = Get-MBContentKindFromTypeAndBody -ContentType $ct -Body $body
		$status = [int]$got.status_code
		$okHttp = ($status -ge 200 -and $status -lt 400) -or ($status -eq 0 -and $body.Length -gt 0)

		$payload = [ordered]@{
			success       = [bool]$okHttp
			status_code   = $status
			url           = $url
			final_url     = $finalUrl
			content_type  = $ct
			content_kind  = $kind
			transport     = $got.transport
			verify_ssl    = [bool]$doVerify
		}
		if ($got.error -and -not $okHttp) { $payload['error'] = $got.error }

		switch ($kind) {
			'json' {
				$pack = ConvertFrom-MBHttpBodyPreferJson -BodyText $body -MaxChars $max_length
				$payload['title'] = 'JSON'
				$payload['text'] = $(if ($pack.text) { [string]$pack.text } else { $body })
				$payload['body'] = $pack.body
				$payload['truncated'] = [bool]$pack.truncated
				$payload['needs_render'] = $false
				$payload['links'] = @()
				$payload['hint'] = 'JSON response — use fields in body; no HTML extract.'
			}
			'binary' {
				$payload['title'] = 'Binary'
				$payload['text'] = ''
				$payload['truncated'] = $false
				$payload['needs_render'] = $false
				$payload['links'] = @()
				$payload['hint'] = 'Binary/non-text content. Use DownloadFile (files group) instead of BrowsePage.'
				$payload['success'] = $false
				$payload['error'] = "content_kind=binary ($ct). Prefer DownloadFile."
			}
			'image' {
				$payload['title'] = 'Image'
				$payload['text'] = ''
				$payload['needs_render'] = $false
				$payload['links'] = @()
				$payload['hint'] = 'Image URL — use DownloadFile or vision ReadImage, not BrowsePage text extract.'
				$payload['success'] = $false
				$payload['error'] = "content_kind=image ($ct)."
			}
			'pdf' {
				$payload['title'] = 'PDF'
				$payload['text'] = ''
				$payload['needs_render'] = $false
				$payload['links'] = @()
				$payload['hint'] = 'PDF — DownloadFile then ReadPdf (vision group).'
				$payload['success'] = $false
				$payload['error'] = "content_kind=pdf ($ct)."
			}
			'html' {
				$ex = Convert-MBHtmlToReadable -Html $body -BaseUrl $finalUrl -MaxLength $max_length -MaxLinks $max_links -ExtractLinks $extract_links
				$payload['title'] = $ex.title
				$payload['text'] = $ex.text
				$payload['text_length'] = $ex.text_length
				$payload['truncated'] = $ex.truncated
				$payload['links'] = $ex.links
				$payload['link_count'] = $ex.link_count
				$payload['needs_render'] = $ex.needs_render
				$payload['render_reasons'] = $ex.render_reasons
				# Hint only when extract failed / JS shell — skip success-path preaching
				if ($ex.needs_render) {
					$payload['hint'] = 'JS shell — text incomplete. Try another URL or raw/API page.'
				}
			}
			default {
				# plain text / markdown / other
				$t = $body
				$trunc = $false
				if ($t.Length -gt $max_length) {
					$t = $t.Substring(0, $max_length) + "`n`n[content truncated]"
					$trunc = $true
				}
				$payload['title'] = $(if ($kind -eq 'markdown') { 'Markdown' } else { 'Text' })
				$payload['text'] = $t
				$payload['text_length'] = $t.Length
				$payload['truncated'] = $trunc
				$payload['needs_render'] = $false
				$payload['links'] = @()
				$payload['hint'] = "content_kind=$kind"
			}
		}

		# Human-friendly block for models that skim string fields
		$summary = New-Object System.Collections.Generic.List[string]
		[void]$summary.Add(('**Title:** {0}' -f $payload['title']))
		[void]$summary.Add(('**URL:** {0}' -f $finalUrl))
		if ($payload['content_kind']) { [void]$summary.Add(('**Kind:** {0}' -f $payload['content_kind'])) }
		if ($payload['needs_render']) { [void]$summary.Add('**needs_render:** true (JS shell likely)') }
		if ($payload['text']) {
			[void]$summary.Add('')
			[void]$summary.Add('**Content:**')
			[void]$summary.Add([string]$payload['text'])
		}
		if ($payload['links'] -and @($payload['links']).Count -gt 0) {
			[void]$summary.Add('')
			[void]$summary.Add('**Links:**')
			foreach ($lk in @($payload['links'] | Select-Object -First 15)) {
				[void]$summary.Add(('- {0}: {1}' -f $lk.text, $lk.url))
			}
		}
		$payload['summary'] = ($summary -join "`n")

		return Limit-MBResult (ConvertTo-MBJson $payload -Depth 10)
	} catch {
		return ConvertTo-MBJson ([ordered]@{ success = $false; error = $_.Exception.Message; url = $url })
	}
}

function Test-MBSearchResultUrlKeep {
	# Keep external search hits; drop SERP chrome.
	param([string]$Url)
	if ([string]::IsNullOrWhiteSpace($Url)) { return $false }
	if ($Url -notmatch '^(?i)https?://') { return $false }
	# Drop pure DDG chrome; keep unwrapped external targets
	if ($Url -match '(?i)^https?://([^/]*\.)?duckduckgo\.com(/|$)') {
		# still on DDG after unwrap → not a real result
		if ($Url -notmatch '(?i)[?&]uddg=') { return $false }
	}
	if ($Url -match '(?i)duckduckgo\.com/(y\.js|html/?$|chrome_newtab)') { return $false }
	if ($Url -match '(?i)^https?://(www\.)?(bing|google|brave)\.com/(search|web|speller)') { return $false }
	return $true
}

function Invoke-SearchWeb {
	# Web search via Brave only (DDG/Bing dropped — unreliable / bot-blocked).
	param(
		[Parameter(Mandatory = $true)][string]$query,
		[int]$max_results = 8,
		[string]$engine = 'brave', # brave | auto (auto = brave)
		[object]$verify_ssl = $true,
		[string]$user_agent = $null
	)
	$q = ([string]$query).Trim()
	if ([string]::IsNullOrWhiteSpace($q)) {
		return ConvertTo-MBJson ([ordered]@{ success = $false; error = 'query required' })
	}
	if ($max_results -le 0) { $max_results = 8 }
	if ($max_results -gt 20) { $max_results = 20 }
	$doVerify = $true
	try { $doVerify = Convert-MBToBool -Value $verify_ssl -Default $true } catch { $doVerify = $true }
	# engine kept for schema compat; only brave is used
	$eng = ([string]$engine).Trim().ToLowerInvariant()
	if ($eng -in @('duckduckgo', 'ddg', 'bing')) {
		$eng = 'brave'
	}
	if ($eng -notin @('auto', 'brave')) { $eng = 'brave' }

	$probeUrl = 'https://search.brave.com/'
	if (-not (Request-MBNetworkApproval -Method 'GET' -Url $probeUrl -HasCredentials $false -ToolName 'SearchWeb')) {
		return "BLOCKED BY USER: SearchWeb denied by operator."
	}

	$results = New-Object System.Collections.ArrayList
	$seen = @{}
	$sourcesTried = New-Object System.Collections.ArrayList
	$notes = New-Object System.Collections.ArrayList
	$ua = if ($user_agent) { $user_agent } else { Get-MBDefaultBrowserUserAgent }

	$addHit = {
		param([string]$Title, [string]$Url, [string]$Snippet, [string]$Source)
		if ([string]::IsNullOrWhiteSpace($Url)) { return }
		$abs = Convert-MBResolveAbsoluteUrl -BaseUrl 'https://search.brave.com/' -Href $Url
		if (-not $abs) { $abs = $Url.Trim() }
		if ($abs -match '^//') { $abs = 'https:' + $abs }
		if ($abs -notmatch '^(?i)https?://') { return }
		if (-not (Test-MBSearchResultUrlKeep -Url $abs)) { return }
		$key = $abs.ToLowerInvariant()
		$key = $key -replace '#.*$', ''
		if ($seen.ContainsKey($key)) { return }
		if ($results.Count -ge $max_results) { return }
		$seen[$key] = $true
		$t = if ($Title) { ($Title -replace '\s+', ' ').Trim() } else { $abs }
		if ($t.Length -gt 160) { $t = $t.Substring(0, 157) + '...' }
		$s = if ($Snippet) { ($Snippet -replace '\s+', ' ').Trim() } else { '' }
		if ($s.Length -gt 280) { $s = $s.Substring(0, 277) + '...' }
		[void]$results.Add([ordered]@{
			title   = $t
			url     = $abs
			snippet = $s
			source  = $Source
		})
	}.GetNewClosure()

	try {
		$braveUrl = 'https://search.brave.com/search?q={0}&source=web' -f [uri]::EscapeDataString($q)
		[void]$sourcesTried.Add('brave_html')
		$pg = Invoke-MBHttpGetPage -Url $braveUrl -VerifySsl $doVerify -UserAgent $ua -TimeoutSec 25 -ExtraHeaders @{
			'Referer' = 'https://search.brave.com/'
		}
		if ($pg.ok -and $pg.body) {
			$html = [string]$pg.body
			$ms = [regex]::Matches($html, '(?is)<a[^>]+href=["''](https?://[^"'']+)["''][^>]*class=["''][^"'']*result-header[^"'']*["''][^>]*>(.*?)</a>')
			if ($ms.Count -eq 0) {
				$ms = [regex]::Matches($html, '(?is)<a[^>]+class=["''][^"'']*(?:result-header|title)[^"'']*["''][^>]+href=["''](https?://[^"'']+)["''][^>]*>(.*?)</a>')
			}
			if ($ms.Count -eq 0) {
				$ms = [regex]::Matches($html, '(?is)<div[^>]+class=["''][^"'']*snippet[^"'']*["''][^>]*>.*?<a[^>]+href=["''](https?://[^"'']+)["''][^>]*>(.*?)</a>')
			}
			foreach ($m in $ms) {
				if ($results.Count -ge $max_results) { break }
				$href = $m.Groups[1].Value
				if ($href -match '(?i)search\.brave\.com') { continue }
				$title = Convert-MBHtmlStripToText -HtmlChunk $m.Groups[2].Value
				& $addHit -Title $title -Url $href -Snippet '' -Source 'brave'
			}
			if ($results.Count -eq 0) { [void]$notes.Add('brave_html: no parseable results') }
		} else {
			[void]$notes.Add(('brave_html http fail status={0}' -f $(try { $pg.status_code } catch { '?' })))
		}
	} catch {
		[void]$notes.Add(('brave_html error: {0}' -f $_.Exception.Message))
	}

	$out = [ordered]@{
		success       = ($results.Count -gt 0)
		query         = $q
		engine        = 'brave'
		count         = $results.Count
		results       = @($results)
		sources_tried = @($sourcesTried)
	}
	if ($notes.Count -gt 0) { $out['notes'] = @($notes) }
	if ($results.Count -eq 0) {
		$out['hint'] = 'No hits from Brave. Try a more specific query, BrowsePage on a known URL, or SearchMicrosoftLearn for MS docs.'
	}
	return Limit-MBResult (ConvertTo-MBJson $out -Depth 8)
}

function Test-MBDocsAllowedHost {
	# Restrict docs tools to Microsoft Learn / SS64 only.
	param(
		[string]$Url,
		[switch]$Learn,
		[switch]$Ss64
	)
	try {
		$u = ([string]$Url).Trim()
		if ($u -notmatch '^(?i)https?://') { return $false }
		$uri = [uri]$u
		$h = $uri.Host.ToLowerInvariant()
		if ($Learn) {
			if ($h -eq 'learn.microsoft.com') { return $true }
			if ($h -eq 'docs.microsoft.com') { return $true }
			if ($h.EndsWith('.learn.microsoft.com')) { return $true }
			if ($h.EndsWith('.docs.microsoft.com')) { return $true }
		}
		if ($Ss64) {
			if ($h -eq 'ss64.com') { return $true }
			if ($h.EndsWith('.ss64.com')) { return $true }
		}
	} catch {}
	return $false
}

function Invoke-SearchMicrosoftLearn {
	param(
		[Parameter(Mandatory = $true)][string]$query,
		[int]$max_results = 8,
		[string]$locale = 'en-us'
	)
	$q = ([string]$query).Trim()
	if ([string]::IsNullOrWhiteSpace($q)) {
		return ConvertTo-MBJson ([ordered]@{ success = $false; error = 'query required' })
	}
	if ($max_results -le 0) { $max_results = 8 }
	if ($max_results -gt 15) { $max_results = 15 }
	$loc = ([string]$locale).Trim().ToLowerInvariant()
	if ([string]::IsNullOrWhiteSpace($loc)) { $loc = 'en-us' }

	$probe = 'https://learn.microsoft.com/api/search'
	if (-not (Request-MBNetworkApproval -Method 'GET' -Url $probe -HasCredentials $false -ToolName 'SearchMicrosoftLearn')) {
		return "BLOCKED BY USER: SearchMicrosoftLearn denied by operator."
	}

	$results = New-Object System.Collections.ArrayList
	$seen = @{}
	$sources = New-Object System.Collections.ArrayList
	$ua = Get-MBDefaultBrowserUserAgent

	$add = {
		param([string]$Title, [string]$Url, [string]$Snippet, [string]$Source)
		if ([string]::IsNullOrWhiteSpace($Url)) { return }
		$abs = [string]$Url.Trim()
		if ($abs -notmatch '^(?i)https?://') {
			if ($abs.StartsWith('/')) { $abs = 'https://learn.microsoft.com' + $abs }
			else { return }
		}
		if (-not (Test-MBDocsAllowedHost -Url $abs -Learn)) { return }
		$key = $abs.ToLowerInvariant()
		if ($seen.ContainsKey($key)) { return }
		if ($results.Count -ge $max_results) { return }
		$seen[$key] = $true
		$t = if ($Title) { ($Title -replace '\s+', ' ').Trim() } else { $abs }
		if ($t.Length -gt 180) { $t = $t.Substring(0, 177) + '...' }
		$s = if ($Snippet) { ($Snippet -replace '\s+', ' ').Trim() } else { '' }
		if ($s.Length -gt 320) { $s = $s.Substring(0, 317) + '...' }
		[void]$results.Add([ordered]@{ title = $t; url = $abs; snippet = $s; source = $Source })
	}.GetNewClosure()

	# Official Learn search API
	try {
		$apiUrl = 'https://learn.microsoft.com/api/search?search={0}&locale={1}&$top={2}' -f `
			[uri]::EscapeDataString($q), [uri]::EscapeDataString($loc), $max_results
		[void]$sources.Add('learn_api')
		$pg = Invoke-MBHttpGetPage -Url $apiUrl -VerifySsl $true -UserAgent $ua -TimeoutSec 25
		if ($pg.ok -and $pg.body) {
			$jo = $null
			try { $jo = $pg.body | ConvertFrom-Json -ErrorAction Stop } catch { $jo = $null }
			if ($jo) {
				$items = @()
				try {
					if ($jo.results) { $items = @($jo.results) }
					elseif ($jo.value) { $items = @($jo.value) }
					elseif ($jo.Results) { $items = @($jo.Results) }
				} catch { $items = @() }
				foreach ($it in $items) {
					if ($results.Count -ge $max_results) { break }
					try {
						$title = ''
						$url = ''
						$snip = ''
						try { $title = [string]$it.title } catch {}
						if (-not $title) { try { $title = [string]$it.Title } catch {} }
						try { $url = [string]$it.url } catch {}
						if (-not $url) { try { $url = [string]$it.Url } catch {} }
						if (-not $url) { try { $url = [string]$it.uri } catch {} }
						if (-not $url) { try { $url = [string]$it.documentLink } catch {} }
						try { $snip = [string]$it.description } catch {}
						if (-not $snip) { try { $snip = [string]$it.summary } catch {} }
						if (-not $snip) { try { $snip = [string]$it.snippet } catch {} }
						& $add -Title $title -Url $url -Snippet $snip -Source 'learn_api'
					} catch {}
				}
			}
		}
	} catch {}

	# Fallback: scoped web search
	if ($results.Count -lt [Math]::Max(2, [int]($max_results / 2))) {
		try {
			[void]$sources.Add('web_site_filter')
			$sq = 'site:learn.microsoft.com {0}' -f $q
			$raw = Invoke-SearchWeb -query $sq -max_results $max_results -engine 'auto' -verify_ssl $true
			$jo = $null
			try {
				if ($raw -is [string] -and $raw.TrimStart().StartsWith('{')) {
					$jo = $raw | ConvertFrom-Json -ErrorAction Stop
				}
			} catch { $jo = $null }
			if ($jo -and $jo.results) {
				foreach ($r in @($jo.results)) {
					if ($results.Count -ge $max_results) { break }
					try {
						& $add -Title ([string]$r.title) -Url ([string]$r.url) -Snippet ([string]$r.snippet) -Source 'web_site_filter'
					} catch {}
				}
			}
		} catch {}
	}

	$hint = if ($results.Count -gt 0) {
		'Pick the best learn.microsoft.com URL and call ReadMicrosoftLearn url=...'
	} else {
		'No Learn hits. Try a more specific query (cmdlet name, product + feature), or SearchWeb for non-MS sources.'
	}
	return Limit-MBResult (ConvertTo-MBJson ([ordered]@{
		success       = ($results.Count -gt 0)
		query         = $q
		locale        = $loc
		count         = $results.Count
		results       = @($results)
		sources_tried = @($sources)
		hint          = $hint
	}) -Depth 8)
}

function Invoke-ReadMicrosoftLearn {
	param(
		[Parameter(Mandatory = $true)][string]$url,
		[int]$max_length = 10000
	)
	$u = ([string]$url).Trim()
	if ($u -notmatch '^(?i)https?://') {
		return ConvertTo-MBJson ([ordered]@{ success = $false; error = 'url must start with http:// or https://'; url = $u })
	}
	if (-not (Test-MBDocsAllowedHost -Url $u -Learn)) {
		return ConvertTo-MBJson ([ordered]@{
			success = $false
			error   = 'url host must be learn.microsoft.com (or docs.microsoft.com). Use SearchMicrosoftLearn first, or BrowsePage for other sites.'
			url     = $u
		})
	}
	if ($max_length -le 0) { $max_length = 10000 }
	if ($max_length -gt 20000) { $max_length = 20000 }
	# Reuse BrowsePage (network approval + extract); stamp tool name in approval via wrapper path
	$raw = Invoke-BrowsePage -url $u -max_length $max_length -verify_ssl $true -extract_links $true -max_links 20
	# Relabel if string JSON so model sees docs context
	try {
		if ($raw -is [string] -and $raw.TrimStart().StartsWith('{')) {
			$jo = $raw | ConvertFrom-Json -ErrorAction Stop
			$od = [ordered]@{}
			foreach ($p in @($jo.PSObject.Properties)) {
				$od[$p.Name] = $p.Value
			}
			$od['docs_source'] = 'microsoft_learn'
			$od['hint'] = 'Microsoft Learn extract. Prefer official steps/cmdlets over inventing APIs. Follow links only on learn.microsoft.com via ReadMicrosoftLearn.'
			return Limit-MBResult (ConvertTo-MBJson $od -Depth 10)
		}
	} catch {}
	return $raw
}

function Invoke-SearchSs64 {
	param(
		[Parameter(Mandatory = $true)][string]$query,
		[int]$max_results = 8,
		[string]$scope = 'auto'
	)
	$q = ([string]$query).Trim()
	if ([string]::IsNullOrWhiteSpace($q)) {
		return ConvertTo-MBJson ([ordered]@{ success = $false; error = 'query required' })
	}
	if ($max_results -le 0) { $max_results = 8 }
	if ($max_results -gt 15) { $max_results = 15 }
	$sc = ([string]$scope).Trim().ToLowerInvariant()
	if ($sc -notin @('auto', 'ps', 'nt', 'bash', 'powershell', 'cmd', 'linux')) { $sc = 'auto' }
	if ($sc -eq 'powershell') { $sc = 'ps' }
	if ($sc -eq 'cmd') { $sc = 'nt' }
	if ($sc -eq 'linux') { $sc = 'bash' }

	$probe = 'https://ss64.com/'
	if (-not (Request-MBNetworkApproval -Method 'GET' -Url $probe -HasCredentials $false -ToolName 'SearchSs64')) {
		return "BLOCKED BY USER: SearchSs64 denied by operator."
	}

	$results = New-Object System.Collections.ArrayList
	$seen = @{}
	$sources = New-Object System.Collections.ArrayList

	$add = {
		param([string]$Title, [string]$Url, [string]$Snippet, [string]$Source)
		if ([string]::IsNullOrWhiteSpace($Url)) { return }
		$abs = [string]$Url.Trim()
		if ($abs -notmatch '^(?i)https?://') {
			if ($abs.StartsWith('/')) { $abs = 'https://ss64.com' + $abs }
			else { return }
		}
		if (-not (Test-MBDocsAllowedHost -Url $abs -Ss64)) { return }
		$key = $abs.ToLowerInvariant()
		if ($seen.ContainsKey($key)) { return }
		if ($results.Count -ge $max_results) { return }
		$seen[$key] = $true
		$t = if ($Title) { ($Title -replace '\s+', ' ').Trim() } else { $abs }
		if ($t.Length -gt 160) { $t = $t.Substring(0, 157) + '...' }
		$s = if ($Snippet) { ($Snippet -replace '\s+', ' ').Trim() } else { '' }
		if ($s.Length -gt 280) { $s = $s.Substring(0, 277) + '...' }
		[void]$results.Add([ordered]@{ title = $t; url = $abs; snippet = $s; source = $Source })
	}.GetNewClosure()

	# Direct command page guesses (fast path)
	$cmdGuess = ($q -replace '\s+', '').Trim().ToLowerInvariant()
	$cmdGuess = $cmdGuess -replace '[^a-z0-9\.\-_]', ''
	if ($cmdGuess.Length -ge 2) {
		$paths = New-Object System.Collections.ArrayList
		switch ($sc) {
			'ps'   { [void]$paths.Add(("https://ss64.com/ps/{0}.html" -f $cmdGuess)) }
			'nt'   { [void]$paths.Add(("https://ss64.com/nt/{0}.html" -f $cmdGuess)) }
			'bash' { [void]$paths.Add(("https://ss64.com/bash/{0}.html" -f $cmdGuess)) }
			default {
				[void]$paths.Add(("https://ss64.com/ps/{0}.html" -f $cmdGuess))
				[void]$paths.Add(("https://ss64.com/nt/{0}.html" -f $cmdGuess))
				[void]$paths.Add(("https://ss64.com/bash/{0}.html" -f $cmdGuess))
			}
		}
		[void]$sources.Add('direct_guess')
		foreach ($pu in @($paths)) {
			if ($results.Count -ge $max_results) { break }
			try {
				$chk = Invoke-MBHttpGetPage -Url $pu -VerifySsl $true -UserAgent (Get-MBDefaultBrowserUserAgent) -TimeoutSec 12
				if ($chk.ok -and $chk.status_code -ge 200 -and $chk.status_code -lt 400 -and $chk.body -and $chk.body.Length -gt 200) {
					$lab = switch -Regex ($pu) {
						'/ps/' { 'PowerShell' }
						'/nt/' { 'Windows CMD' }
						'/bash/' { 'bash' }
						default { 'SS64' }
					}
					& $add -Title ("{0} — {1}" -f $cmdGuess, $lab) -Url $pu -Snippet ("Direct SS64 page for {0}" -f $cmdGuess) -Source 'direct_guess'
				}
			} catch {}
		}
	}

	# Site-scoped search
	try {
		[void]$sources.Add('web_site_filter')
		$siteQ = switch ($sc) {
			'ps'   { 'site:ss64.com/ps {0}' -f $q }
			'nt'   { 'site:ss64.com/nt {0}' -f $q }
			'bash' { 'site:ss64.com/bash {0}' -f $q }
			default { 'site:ss64.com {0}' -f $q }
		}
		$raw = Invoke-SearchWeb -query $siteQ -max_results $max_results -engine 'auto' -verify_ssl $true
		$jo = $null
		try {
			if ($raw -is [string] -and $raw.TrimStart().StartsWith('{')) {
				$jo = $raw | ConvertFrom-Json -ErrorAction Stop
			}
		} catch { $jo = $null }
		if ($jo -and $jo.results) {
			foreach ($r in @($jo.results)) {
				if ($results.Count -ge $max_results) { break }
				try {
					& $add -Title ([string]$r.title) -Url ([string]$r.url) -Snippet ([string]$r.snippet) -Source 'web_site_filter'
				} catch {}
			}
		}
	} catch {}

	$hint = if ($results.Count -gt 0) {
		'Call ReadSs64 url=... (or command=name scope=ps|nt|bash) for the best hit.'
	} else {
		'No SS64 hits. Try scope=ps|nt|bash or a shorter command name.'
	}
	return Limit-MBResult (ConvertTo-MBJson ([ordered]@{
		success       = ($results.Count -gt 0)
		query         = $q
		scope         = $sc
		count         = $results.Count
		results       = @($results)
		sources_tried = @($sources)
		hint          = $hint
	}) -Depth 8)
}

function Invoke-ReadSs64 {
	param(
		[string]$url = '',
		[string]$command = '',
		[string]$scope = 'auto',
		[int]$max_length = 10000
	)
	$u = ([string]$url).Trim()
	$cmd = ([string]$command).Trim()
	$sc = ([string]$scope).Trim().ToLowerInvariant()
	if ($sc -notin @('auto', 'ps', 'nt', 'bash', 'powershell', 'cmd', 'linux')) { $sc = 'auto' }
	if ($sc -eq 'powershell') { $sc = 'ps' }
	if ($sc -eq 'cmd') { $sc = 'nt' }
	if ($sc -eq 'linux') { $sc = 'bash' }

	if ([string]::IsNullOrWhiteSpace($u) -and -not [string]::IsNullOrWhiteSpace($cmd)) {
		$c = ($cmd -replace '\s+', '').ToLowerInvariant() -replace '[^a-z0-9\.\-_]', ''
		if ($c.Length -lt 1) {
			return ConvertTo-MBJson ([ordered]@{ success = $false; error = 'command empty after normalize' })
		}
		$tryUrls = New-Object System.Collections.ArrayList
		switch ($sc) {
			'ps'   { [void]$tryUrls.Add(("https://ss64.com/ps/{0}.html" -f $c)) }
			'nt'   { [void]$tryUrls.Add(("https://ss64.com/nt/{0}.html" -f $c)) }
			'bash' { [void]$tryUrls.Add(("https://ss64.com/bash/{0}.html" -f $c)) }
			default {
				[void]$tryUrls.Add(("https://ss64.com/ps/{0}.html" -f $c))
				[void]$tryUrls.Add(("https://ss64.com/nt/{0}.html" -f $c))
				[void]$tryUrls.Add(("https://ss64.com/bash/{0}.html" -f $c))
			}
		}
		foreach ($tu in @($tryUrls)) {
			try {
				$chk = Invoke-MBHttpGetPage -Url $tu -VerifySsl $true -UserAgent (Get-MBDefaultBrowserUserAgent) -TimeoutSec 12
				if ($chk.ok -and $chk.status_code -ge 200 -and $chk.status_code -lt 400 -and $chk.body -and $chk.body.Length -gt 200) {
					$u = $tu
					break
				}
			} catch {}
		}
		if ([string]::IsNullOrWhiteSpace($u)) {
			return ConvertTo-MBJson ([ordered]@{
				success = $false
				error   = ("No SS64 page for command '{0}' (scope={1}). Use SearchSs64 first." -f $cmd, $sc)
				command = $cmd
				scope   = $sc
				tried   = @($tryUrls)
			})
		}
	}

	if ([string]::IsNullOrWhiteSpace($u)) {
		return ConvertTo-MBJson ([ordered]@{ success = $false; error = 'url or command required' })
	}
	if ($u -notmatch '^(?i)https?://') {
		return ConvertTo-MBJson ([ordered]@{ success = $false; error = 'url must start with http:// or https://'; url = $u })
	}
	if (-not (Test-MBDocsAllowedHost -Url $u -Ss64)) {
		return ConvertTo-MBJson ([ordered]@{
			success = $false
			error   = 'url host must be ss64.com. Use SearchSs64 first, or BrowsePage for other sites.'
			url     = $u
		})
	}
	if ($max_length -le 0) { $max_length = 10000 }
	if ($max_length -gt 20000) { $max_length = 20000 }

	$raw = Invoke-BrowsePage -url $u -max_length $max_length -verify_ssl $true -extract_links $true -max_links 16
	try {
		if ($raw -is [string] -and $raw.TrimStart().StartsWith('{')) {
			$jo = $raw | ConvertFrom-Json -ErrorAction Stop
			$od = [ordered]@{}
			foreach ($p in @($jo.PSObject.Properties)) {
				$od[$p.Name] = $p.Value
			}
			$od['docs_source'] = 'ss64'
			$od['hint'] = 'SS64 command reference. Prefer documented switches/flags; verify version differences vs local Get-Help when needed.'
			return Limit-MBResult (ConvertTo-MBJson $od -Depth 10)
		}
	} catch {}
	return $raw
}

function Invoke-ConvertGitHubUrl {
	param([string]$github_url)
	if (-not $github_url -or $github_url -notmatch 'github\.com') {
		return ConvertTo-MBJson @{ error = "Not a valid GitHub URL"; input = $github_url }
	}
	if ($github_url -match 'raw\.githubusercontent\.com') {
		return ConvertTo-MBJson @{ type = "raw"; raw_url = $github_url; message = "Already a raw URL" }
	}
	try {
		$uri = [System.Uri]$github_url
		$parts = @($uri.AbsolutePath.Trim('/').Split('/') | Where-Object { $_ })
		if ($parts.Count -lt 2) { throw "Invalid GitHub path" }
		$owner = $parts[0]; $repo = $parts[1]
		if ($parts.Count -eq 2) {
			return ConvertTo-MBJson @{
				type = "repo_root"; owner = $owner; repo = $repo
				suggested_raw_urls = @(
					"https://raw.githubusercontent.com/$owner/$repo/main/README.md",
					"https://raw.githubusercontent.com/$owner/$repo/master/README.md"
				)
			}
		}
		$action = $parts[2].ToLower()
		if ($action -in @('blob','tree') -and $parts.Count -ge 4) {
			$ref = $parts[3]
			$filePath = if ($parts.Count -gt 4) { $parts[4..($parts.Count-1)] -join '/' } else { '' }
			if ($action -eq 'tree') {
				return ConvertTo-MBJson @{
					type = "directory"
					raw_base = "https://raw.githubusercontent.com/$owner/$repo/$ref/$filePath/"
					message = "Directory listing - use ListGitHubDirectory or BrowsePage"
				}
			}
			$rawUrl = "https://raw.githubusercontent.com/$owner/$repo/$ref/$filePath"
			return ConvertTo-MBJson @{ type = "file"; raw_url = $rawUrl; owner = $owner; repo = $repo; ref = $ref; path = $filePath }
		}
		return ConvertTo-MBJson @{ type = "other"; message = "Use BrowsePage on the original URL" }
	} catch {
		return ConvertTo-MBJson @{ error = $_.Exception.Message; input = $github_url }
	}
}

function Invoke-GetGitHubRawFile {
	param([string]$github_url, [int]$max_length = 15000)
	$convertResult = Invoke-ConvertGitHubUrl -github_url $github_url | ConvertFrom-Json
	if ($convertResult.error) { return "ERROR: $($convertResult.error)" }
	$rawUrl = $null
	if ($convertResult.raw_url) { $rawUrl = $convertResult.raw_url }
	elseif ($convertResult.suggested_raw_urls) { $rawUrl = @($convertResult.suggested_raw_urls)[0] }
	else { return "Could not determine raw URL. Original: $github_url" }
	try {
		$content = Invoke-BrowsePage -url $rawUrl -max_length $max_length -extract_links $false
		$text = [string]$content
		if ($text.TrimStart().StartsWith('{')) {
			try {
				$jo = $text | ConvertFrom-Json -ErrorAction Stop
				if ($jo.text) { $text = [string]$jo.text }
				elseif ($jo.summary) { $text = [string]$jo.summary }
				if ($jo.final_url) { $rawUrl = [string]$jo.final_url }
			} catch {}
		}
		return "Successfully fetched: $rawUrl`n`n$text"
	} catch {
		return "Failed to fetch $rawUrl`nError: $($_.Exception.Message)"
	}
}

function Invoke-ListGitHubDirectory {
	param([string]$github_url, [string]$ref = "main")
	try {
		$owner = $null; $repo = $null; $subPath = ''
		if ($github_url -match 'github\.com/([^/]+)/([^/]+)(?:/(?:tree|blob)/([^/]+)(?:/(.*))?)?') {
			$owner = $matches[1]
			$repo = $matches[2]
			if ($matches[3]) { $ref = $matches[3] }
			if ($matches[4]) { $subPath = ($matches[4] -replace '/$', '') }
		} else {
			return "ERROR: Invalid GitHub repository URL"
		}
		$testUrls = @(
			"https://api.github.com/repos/$owner/$repo/git/trees/${ref}?recursive=1",
			"https://api.github.com/repos/$owner/$repo/git/trees/main?recursive=1",
			"https://api.github.com/repos/$owner/$repo/git/trees/master?recursive=1"
		)
		$content = $null
		$usedRef = $ref
		foreach ($u in $testUrls) {
			$result = Invoke-MakeHttpRequest -method "GET" -url $u
			$data = $result | ConvertFrom-Json
			if ($data.success -and $data.body.tree) {
				$content = $data.body
				if ($u -match '/trees/([^/?]+)') { $usedRef = $matches[1] }
				break
			}
		}
		if (-not $content) {
			$htmlUrl = "https://github.com/$owner/$repo/tree/$ref$(if ($subPath) { '/' + $subPath })"
			$br = Invoke-BrowsePage -url $htmlUrl -max_length 8000
			$bt = [string]$br
			if ($bt.TrimStart().StartsWith('{')) {
				try {
					$jo = $bt | ConvertFrom-Json -ErrorAction Stop
					if ($jo.summary) { $bt = [string]$jo.summary }
					elseif ($jo.text) { $bt = [string]$jo.text }
				} catch {}
			}
			return "API access limited. Try:`n$htmlUrl`n`n$bt"
		}
		$tree = @($content.tree)
		if ($subPath) {
			$prefix = $subPath.Trim('/') + '/'
			$tree = @($tree | Where-Object {
				$_.path -eq $subPath -or $_.path.StartsWith($prefix)
			} | ForEach-Object {
				$p = [string]$_.path
				if ($p -eq $subPath) { $_ }
				else {
					$rel = $p.Substring($prefix.Length)
					[pscustomobject]@{ type = $_.type; path = $rel; size = $_.size }
				}
			})
		}
		$items = @($tree | ForEach-Object {
			[pscustomobject]@{
				type = $_.type
				path = $_.path
				size_kb = if ($_.size) { [math]::Round($_.size/1024, 1) } else { $null }
			}
		} | Sort-Object type, path | Select-Object -First 400)
		return Limit-MBResult (ConvertTo-MBJson @{
			repo = "$owner/$repo"
			ref = $usedRef
			path = $(if ($subPath) { $subPath } else { '/' })
			total_items = $items.Count
			files = @($items | Where-Object type -eq 'blob').Count
			directories = @($items | Where-Object type -eq 'tree').Count
			items = $items
		} -Depth 4)
	} catch {
		return "ERROR: $($_.Exception.Message)"
	}
}

function Test-MBModelsApiResponse {
	param($Response)
	if (-not $Response) { return $false }
	try {
		$ct = [string]$Response.Headers['Content-Type']
		if ($ct -and $ct -notmatch '(?i)json') {
			if ($ct -match '(?i)html|text/html') { return $false }
		}
	} catch {}
	$body = $null
	try { $body = [string]$Response.Content } catch { return $false }
	if ([string]::IsNullOrWhiteSpace($body)) { return $false }
	$trim = $body.TrimStart()
	if ($trim.StartsWith('<')) { return $false }
	if (-not ($trim.StartsWith('{') -or $trim.StartsWith('['))) { return $false }
	try {
		$obj = $body | ConvertFrom-Json -ErrorAction Stop
		if ($null -eq $obj) { return $false }
		if ($obj.data) { return $true }
		if ($obj.models) { return $true }
		if ($obj -is [System.Array] -and $obj.Count -gt 0) { return $true }
		if ($obj.id -or $obj.model) { return $true }
		return $false
	} catch {
		return $false
	}
}

function Test-ModelConnection {
	[CmdletBinding()]
	param(
		[string]$BaseUrl,
		[string]$Username,
		[string]$Password,
		[string]$BearerToken = '',
		[int]$TimeoutSeconds = 3
	)
	$raw = [string]$BaseUrl
	if ([string]::IsNullOrWhiteSpace($raw)) {
		try { $raw = [string]$script:BaseUrl } catch { $raw = '' }
	}
	if ([string]::IsNullOrWhiteSpace($raw)) { $raw = [string](Get-Variable -Name BaseUrl -ValueOnly -ErrorAction SilentlyContinue) }
	if ([string]::IsNullOrWhiteSpace($raw)) { $raw = 'http://127.0.0.1:8080' }
	$raw = $raw.Trim()
	while ($raw.EndsWith('/')) { $raw = $raw.Substring(0, $raw.Length - 1) }
	$raw = $raw -replace '/chat/completions\s*$', '' -replace '/models\s*$', ''
	$raw = $raw -replace '/v1/chat/completions\s*$', '' -replace '/v1/models\s*$', ''
	while ($raw.EndsWith('/')) { $raw = $raw.Substring(0, $raw.Length - 1) }

	$bases = New-Object System.Collections.Generic.List[string]
	# Prefer /v1 first for vLLM / Unsloth / OpenAI-compat
	if ($raw -match '/v1$') {
		[void]$bases.Add($raw)
		$root = $raw -replace '/v1$', ''
		if ($root -and -not $bases.Contains($root)) { [void]$bases.Add($root) }
	} else {
		[void]$bases.Add($raw + '/v1')
		[void]$bases.Add($raw)
	}

	$headers = @{}
	$authType = 'None'
	$auth = Get-MBAuthHeaderValue -BaseUrl $raw -BearerToken $BearerToken
	if ($auth) {
		$headers['Authorization'] = $auth
		$authType = Format-MBAuthDisplayLabel -BaseUrl $raw -AuthHeader $auth -Short
	} elseif ($Username -and $Password) {
		$credBytes = [System.Text.Encoding]::UTF8.GetBytes("${Username}:${Password}")
		$headers['Authorization'] = "Basic " + [Convert]::ToBase64String($credBytes)
		$authType = 'Basic (NPM)'
	} else {
		$authType = Format-MBAuthDisplayLabel -Mode 'none' -BaseUrl $raw -Short
	}

	$stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
	$lastFail = $null
	# Total budget across URL variants so boot cannot sit on two full timeouts
	$deadline = [Environment]::TickCount + ([Math]::Max(1, $TimeoutSeconds) * 1000) + 350
	foreach ($base in $bases) {
		$leftMs = $deadline - [Environment]::TickCount
		if ($leftMs -lt 250) { break }
		$tSec = [Math]::Max(1, [Math]::Min($TimeoutSeconds, [int][Math]::Ceiling($leftMs / 1000.0)))
		$testUrl = "$base/models"
		try {
			$resp = Invoke-MBHttpGetQuick -Url $testUrl -Headers $headers -TimeoutSeconds $tSec
			$sc = 0
			try { $sc = [int]$resp.StatusCode } catch { $sc = 0 }
			if ($sc -in 401, 403) {
				$stopwatch.Stop()
				return [pscustomobject]@{
					Success    = $false
					StatusCode = $sc
					Message    = "Authentication failed ($sc) for $base"
					AuthType   = $authType
					ElapsedMs  = $stopwatch.ElapsedMilliseconds
					BaseUrl    = $base
				}
			}
			if (-not $resp.Ok -or $sc -ne 200) {
				$msg = if ($resp.TimedOut) {
					"Timed out connecting to: $testUrl"
				} elseif ($sc -gt 0) {
					"HTTP $sc from $testUrl"
				} else {
					$err = if ($resp.Error) { [string]$resp.Error } else { 'connection failed' }
					"$err`nFailed to connect to: $testUrl"
				}
				$lastFail = [pscustomobject]@{
					Success = $false; StatusCode = $(if ($sc -gt 0) { $sc } else { $null })
					Message = $msg
					AuthType = $authType; ElapsedMs = $stopwatch.ElapsedMilliseconds; BaseUrl = $base
				}
				continue
			}
			$body = [string]$resp.Content
			if ([string]::IsNullOrWhiteSpace($body) -or $body.TrimStart().StartsWith('<')) {
				$lastFail = [pscustomobject]@{
					Success = $false; StatusCode = 200
					Message = "Got HTTP 200 from $testUrl but body is not a models API (need OpenAI JSON from vLLM/Unsloth/llama.cpp, not HTML). Use the API base (e.g. :8000/v1 or :8081), not a web UI port."
					AuthType = $authType; ElapsedMs = $stopwatch.ElapsedMilliseconds; BaseUrl = $base
				}
				continue
			}
			try {
				$obj = $body | ConvertFrom-Json -ErrorAction Stop
				if (-not ($obj.data -or $obj.models -or $obj.id -or $obj.model -or $obj -is [System.Array])) {
					throw 'not models json'
				}
			} catch {
				$lastFail = [pscustomobject]@{
					Success = $false; StatusCode = 200
					Message = "Got HTTP 200 from $testUrl but body is not a models API (need OpenAI JSON from vLLM/Unsloth/llama.cpp, not HTML). Use the API base (e.g. :8000/v1 or :8081), not a web UI port."
					AuthType = $authType; ElapsedMs = $stopwatch.ElapsedMilliseconds; BaseUrl = $base
				}
				continue
			}
			$stopwatch.Stop()
			try { $script:MB.ResolvedApiBase = $base } catch {}
			return [pscustomobject]@{
				Success    = $true
				StatusCode = 200
				Message    = "Connection successful ($($stopwatch.ElapsedMilliseconds) ms) -> $base"
				AuthType   = $authType
				ElapsedMs  = $stopwatch.ElapsedMilliseconds
				BaseUrl    = $base
			}
		} catch {
			$lastFail = [pscustomobject]@{
				Success = $false; StatusCode = $null
				Message = "Unexpected error on $testUrl : $($_.Exception.Message)"
				AuthType = $authType; ElapsedMs = $stopwatch.ElapsedMilliseconds; BaseUrl = $base
			}
		}
	}
	if ($stopwatch.IsRunning) { try { $stopwatch.Stop() | Out-Null } catch {} }
	if ($lastFail) { return $lastFail }
	return [pscustomobject]@{
		Success = $false; StatusCode = $null
		Message = "Failed to connect to: $raw"
		AuthType = $authType; ElapsedMs = 0; BaseUrl = $raw
	}
}

function Invoke-ModelStreaming {
	param(
		[array]$Messages,
		[int]$RetryCount = 4
	)

	try {
	Write-MBDebugLog -Step 'STREAM_BEGIN' -Detail ("msgs={0}" -f @($Messages).Count)
	$apiBase = Get-MBApiBaseUrl
	$completionsUrl = "$apiBase/chat/completions"
	Write-MBDebugLog -Step 'STREAM_URL' -Detail $completionsUrl

	try { Write-Host "" } catch {}
	Write-MBDebugLog -Step 'STREAM_THINK_START'
	try { Start-MBThinkingAnimation -Name $AgentName } catch {
		Write-MBDebugLog -Step 'STREAM_THINK_START_ERR' -Detail $_.Exception.Message
	}

	$attempt = 0
	$lastError = $null
	$didHardCompact = $false
	$workMessages = @($Messages)

	try {
		Write-MBDebugLog -Step 'STREAM_BUDGET_BEGIN'
		try { Stop-MBAnimation } catch {}
		$workMessages = @(Ensure-MBPromptBudget -Messages $workMessages -TargetPct 0.72)
		$script:Messages = $workMessages
		Write-MBDebugLog -Step 'STREAM_BUDGET_OK' -Detail ("msgs={0}" -f @($workMessages).Count)
		try { Start-MBThinkingAnimation -Name $AgentName } catch {}
	} catch {
		Write-MBDebugLog -Step 'STREAM_BUDGET_ERR' -Detail $_.Exception.Message
		try { Start-MBThinkingAnimation -Name $AgentName } catch {}
	}

	while ($attempt -le $RetryCount) {
		$attempt++
		$startedOutput = $false
		$fullContent   = ""
		$toolCalls     = @{}
		$hasToolCalls  = $false
		$finishReason  = $null
		$streamParseDrops = 0
		$haveUsageThisStream = $false
		$script:MB.LastServerCompletionTokens = 0
		try { Reset-MBStreamSpeedState } catch {}
		$client = $null
		$stream = $null
		$reader = $null
		$httpResponse = $null
		$script:MB.StreamCancel = $false

		$body = $null
		Write-MBDebugLog -Step 'STREAM_ATTEMPT' -Detail ("n={0}" -f $attempt)
		try {
			$activeModelName = Get-MBActiveModel
			if ([string]::IsNullOrWhiteSpace($activeModelName)) {
				Stop-MBAnimation
				Write-MBWarn 'Select a model in the title bar (PoweredBy) before chatting.'
				return [pscustomobject]@{
					choices       = @(@{ message = @{ role = 'assistant'; content = '' } })
					ok            = $false
					finish_reason = 'error'
					error         = 'no model selected'
				}
			}
			$workMessages = @(Ensure-MBPromptBudget -Messages $workMessages -TargetPct $(if ($attempt -gt 2) { 0.55 } else { 0.70 }))
			$workMessages = @(Repair-MBMessagesEncoding -Messages $workMessages)
			$activeTools = @(Get-MBActiveTools)
			Write-MBDebugLog -Step 'STREAM_BODY_BUILD' -Detail ("tools={0}" -f @($activeTools).Count)
			$reqMaxTok = Get-MBRequestMaxTokens -Messages $workMessages
			$body = New-MBChatRequestBody -Messages $workMessages -Tools $activeTools -ModelName $activeModelName -Temp $Temperature -MaxTok $reqMaxTok -Stream $true
			$script:MB.LastBodyChars = $body.Length
			Write-MBDebugLog -Step 'STREAM_BODY_OK' -Detail ("chars={0} max_tokens={1}" -f $body.Length, $reqMaxTok)
		} catch {
			$lastError = "Failed to build request body: $($_.Exception.Message)"
			Write-MBDebugLog -Step 'STREAM_BODY_ERR' -Detail $lastError
			Stop-MBAnimation
			if (-not $didHardCompact) {
				$didHardCompact = $true
				Write-MBWarn "Body build failed - hard-compacting context and retrying..."
				try {
					$workMessages = @(Manage-MBContext -Messages $workMessages -ForceCompact)
					$script:Messages = $workMessages
				} catch {}
				Start-Sleep -Milliseconds 300
				Start-MBThinkingAnimation -Name $AgentName
				continue
			}
			Write-MBErr $lastError
			return $null
		}

		if ([string]::IsNullOrWhiteSpace($body) -or -not $body.Trim().StartsWith('{')) {
			$lastError = "Request body empty or not JSON"
			Write-MBDebugLog -Step 'STREAM_BODY_INVALID'
			Stop-MBAnimation
			Write-MBErr $lastError
			return $null
		}

		$cts = $null
		try {
			Write-MBDebugLog -Step 'STREAM_HTTP_BEGIN'
			$client = Get-MBSharedHttpClient
			$cts = New-Object System.Threading.CancellationTokenSource
			$script:MB.ActiveHttpClient = $client
			$script:MB.ActiveCts = $cts

			$request = New-Object System.Net.Http.HttpRequestMessage([System.Net.Http.HttpMethod]::Post, $completionsUrl)

			$authHdr = Get-MBAuthHeaderValue -BaseUrl $apiBase
			if ($authHdr -match '^(?i)Basic\s+(.+)$') {
				$request.Headers.Authorization = New-Object System.Net.Http.Headers.AuthenticationHeaderValue("Basic", $Matches[1].Trim())
			} elseif ($authHdr -match '^(?i)Bearer\s+(.+)$') {
				$request.Headers.Authorization = New-Object System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", $Matches[1].Trim())
			}

			try {
				[void]$request.Headers.Accept.Add([System.Net.Http.Headers.MediaTypeWithQualityHeaderValue]::Parse("text/event-stream"))
				[void]$request.Headers.Accept.Add([System.Net.Http.Headers.MediaTypeWithQualityHeaderValue]::Parse("application/json"))
			} catch {}

			# Body as UTF-8 bytes (Get-MBUtf8JsonBytes)
			# PS 5.1 ByteArrayContent: avoid New-Object unpack of byte[]
			$bodyBytes = Get-MBUtf8JsonBytes -Json ([string]$body)
			$request.Content = New-Object System.Net.Http.ByteArrayContent (,[byte[]]$bodyBytes)
			$request.Content.Headers.ContentType = New-Object System.Net.Http.Headers.MediaTypeHeaderValue ("application/json")
			$request.Content.Headers.ContentType.CharSet = "utf-8"

			Write-MBDebugLog -Step 'STREAM_SENDASYNC'
			$sendTask = $client.SendAsync(
				$request,
				[System.Net.Http.HttpCompletionOption]::ResponseHeadersRead,
				$cts.Token
			)
			while (-not $sendTask.IsCompleted) {
				if ((Test-MBInterrupt)) {
					try { $cts.Cancel() } catch {}
					try { $client.CancelPendingRequests() } catch {}
					break
				}
				Start-Sleep -Milliseconds 5
			}

			if ($script:MB.Interrupt -or $sendTask.IsCanceled) {
				Write-MBDebugLog -Step 'STREAM_SEND_CANCELLED'
				throw [OperationCanceledException]::new("aborted by user")
			}
			if ($sendTask.IsFaulted) {
				Write-MBDebugLog -Step 'STREAM_SEND_FAULTED'
				if ($sendTask.Exception) { throw $sendTask.Exception.GetBaseException() }
				throw "SendAsync failed"
			}

			$httpResponse = $sendTask.Result
			# Wall-clock prefill window starts when headers arrive (SSE body follows prompt eval).
			$script:MB.StreamHeadersTick = [Environment]::TickCount
			Write-MBDebugLog -Step 'STREAM_HEADERS' -Detail ("status={0}" -f ([int]$httpResponse.StatusCode))

			if (-not $httpResponse.IsSuccessStatusCode) {
				$errBody = ""
				try { $errBody = $httpResponse.Content.ReadAsStringAsync().Result } catch {}
				if ($errBody.Length -gt 500) { $errBody = $errBody.Substring(0, 500) + '...' }
				$code = [int]$httpResponse.StatusCode
				$hint = ""
				if ($code -eq 405) {
					$hint = " - wrong API base (often Open-WebUI web UI port). Use llama.cpp/OpenAI base that serves POST /chat/completions (e.g. http://HOST:8081), not the web UI."
				}
				throw ("HTTP {0} {1} {2}{3} [{4}]" -f $code, $httpResponse.ReasonPhrase, $errBody, $hint, $completionsUrl)
			}

			$stream = $httpResponse.Content.ReadAsStreamAsync().Result
			# Larger buffer + aggressive drain reduces chunk latency vs 8KB + 30ms poll.
			$reader = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8, $true, 65536, $true)
			$script:MB.ActiveStream = $stream
			$script:MB.ActiveReader = $reader
			Write-MBDebugLog -Step 'STREAM_READ_LOOP'

			# Mutable bag so nested helpers can update stream state reliably (PS closure assign pitfalls).
			$st = @{
				FullContent   = ''
				StartedOut    = $false
				FinishReason  = $null
				HasTools      = $false
				HaveUsage     = $false
				ParseDrops    = 0
				ToolCalls     = $toolCalls
				ToolUiStarted = $false
				ToolUiLastTick = 0
				ToolArgChars  = 0
			}
			# Tool-call-only streams never emit content — without this the chat looks frozen while llama.cpp burns tokens.
			$noteToolStreamUi = {
				param($Bag)
				try {
					$now = [Environment]::TickCount
					if (-not [bool]$Bag.ToolUiStarted) {
						$Bag.ToolUiStarted = $true
						if ([int]$script:MB.StreamFirstTokTick -eq 0) { $script:MB.StreamFirstTokTick = $now }
						if ([int]$script:MB.FirstTokenTick -eq 0) { $script:MB.FirstTokenTick = $now }
						try { Stop-MBAnimation } catch {}
						$script:MB.WorkStartTick = $now
						try { if ($script:MB.Wpf) { $script:MB.Wpf.StatusBusySince = $now } } catch {}
						Write-MBDebugLog -Step 'STREAM_TOOL_FIRST' -Detail 'tool_calls delta (no content yet)'
					}
					# Throttle sticky refresh (~4/s) so huge arg streams stay responsive
					$last = 0
					try { $last = [int]$Bag.ToolUiLastTick } catch { $last = 0 }
					if ($last -ne 0 -and ((($now - $last) -band 0x7fffffff) -lt 250)) { return }
					$Bag.ToolUiLastTick = $now
					$names = New-Object System.Collections.ArrayList
					$argN = 0
					foreach ($k in @($Bag.ToolCalls.Keys)) {
						$tc = $Bag.ToolCalls[$k]
						$nm = ''
						try { $nm = [string]$tc.function.name } catch { $nm = '' }
						if (-not [string]::IsNullOrWhiteSpace($nm)) {
							if (-not ($names -contains $nm)) { [void]$names.Add($nm) }
						}
						try { $argN += ([string]$tc.function.arguments).Length } catch {}
					}
					$Bag.ToolArgChars = $argN
					$namesShow = New-Object System.Collections.ArrayList
					foreach ($nm0 in @($names)) {
						$n0 = [string]$nm0
						if ($n0 -match '^(?i)TaskBoard|todo_write|todo|checklist|task_board|taskboard$') { continue }
						try {
							$res0 = Resolve-MBToolName -Name $n0
							if ($res0 -eq 'TaskBoard') { continue }
						} catch {}
						[void]$namesShow.Add($n0)
					}
					$lab = if ($namesShow.Count -gt 0) { ($namesShow -join '+') } else { '' }
					if ([string]::IsNullOrWhiteSpace($lab) -and $names.Count -gt 0) {
						try {
							Update-MBWpfSticky -Status 'working' -Hint ("esc interrupt  {0}  taskboard" -f ([char]0x00B7))
						} catch {}
						return
					}
					if ([string]::IsNullOrWhiteSpace($lab)) { $lab = 'tools' }
					$hint = ("esc interrupt  {0}  preparing {1}" -f ([char]0x00B7), $lab)
					if ($argN -gt 0) {
						if ($argN -ge 1000) {
							$hint = ("esc interrupt  {0}  {1} args ~{2:N0}k" -f ([char]0x00B7), $lab, [math]::Round($argN / 1000.0, 1))
						} else {
							$hint = ("esc interrupt  {0}  {1} args {2}" -f ([char]0x00B7), $lab, $argN)
						}
					}
					try {
						Update-MBWpfSticky -Status 'working' -Hint $hint
					} catch {}
				} catch {}
			}.GetNewClosure()

			while ($true) {
				if ((Test-MBInterrupt)) { break }

				$line = $null
				# Drain already-buffered lines without async hop (much lower latency).
				$peekOk = $false
				try { $peekOk = ($reader.Peek() -ge 0) } catch { $peekOk = $false }
				if ($peekOk) {
					try { $line = $reader.ReadLine() } catch {
						if ($script:MB.Interrupt) { break }
						break
					}
				} else {
					$readTask = $null
					try {
						$readTask = $reader.ReadLineAsync()
					} catch {
						if ($script:MB.Interrupt) { break }
						throw
					}

					while ($readTask -and -not $readTask.IsCompleted) {
						if ((Test-MBInterrupt)) {
							try { $cts.Cancel() } catch {}
							try { $client.CancelPendingRequests() } catch {}
							try { $reader.Dispose() } catch {}
							try { $stream.Dispose() } catch {}
							break
						}
						Start-Sleep -Milliseconds 1
					}

					if ($script:MB.Interrupt) { break }
					if (-not $readTask) { break }
					if ($readTask.IsCanceled) { break }
					if ($readTask.IsFaulted) {
						if ($script:MB.Interrupt) { break }
						$exMsg = ""
						try { $exMsg = $readTask.Exception.GetBaseException().Message } catch {}
						if ($exMsg -match 'cancel|abort|disposed|closed') { break }
						throw $readTask.Exception.GetBaseException()
					}

					try { $line = $readTask.Result } catch {
						if ($script:MB.Interrupt) { break }
						break
					}
				}

				if ($null -eq $line) { break }
				if ([string]::IsNullOrWhiteSpace($line)) { continue }
				if ($line -eq "data: [DONE]" -or $line.Trim() -eq "data: [DONE]") { break }
				if (-not $line.StartsWith("data: ")) { continue }

				$json = $line.Substring(6).Trim()
				if ([string]::IsNullOrWhiteSpace($json)) { continue }

				$chunk = $null
				try {
					$chunk = $json | ConvertFrom-Json -ErrorAction Stop
				} catch {
					$st.ParseDrops++
					$rescued = $null
					try {
						if ($json -match '"content"\s*:\s*"((?:\\.|[^"\\])*)"') {
							try {
								$rescued = ('"' + $matches[1] + '"') | ConvertFrom-Json -ErrorAction Stop
							} catch {
								$rescued = [regex]::Replace([string]$matches[1], '\\([\\"/bfnrt])', {
									param($m)
									switch ($m.Groups[1].Value) {
										'\' { '\' } '"' { '"' } '/' { '/' }
										'b' { "`b" } 'f' { "`f" } 'n' { "`n" } 'r' { "`r" } 't' { "`t" }
										default { $m.Value }
									}
								})
								$rescued = [regex]::Replace([string]$rescued, '\\u([0-9a-fA-F]{4})', {
									param($m)
									[char][int]('0x' + $m.Groups[1].Value)
								})
							}
						}
					} catch {}
					if ($rescued) {
						$nowTok = [Environment]::TickCount
						if ([int]$script:MB.StreamFirstTokTick -eq 0) { $script:MB.StreamFirstTokTick = $nowTok }
						if ([int]$script:MB.FirstTokenTick -eq 0) { $script:MB.FirstTokenTick = $nowTok }
						if (-not [bool]$st.StartedOut) {
							Write-MBDebugLog -Step 'STREAM_FIRST_TOKEN' -Detail ("len={0}" -f $rescued.Length)
							try { Stop-MBAnimation } catch {}
							try { Write-MBThoughtStamp } catch {}
							$script:MB.WorkStartTick = $nowTok
							try { if ($script:MB.Wpf) { $script:MB.Wpf.StatusBusySince = $nowTok } } catch {}
							try { Reset-MBMdStream } catch {}
							try { Write-MBBrand -NoNewline; Write-Host " " -NoNewline } catch {}
							$st.StartedOut = $true
						}
						Write-MBStreamChunk -Text $rescued
						$st.FullContent = [string]$st.FullContent + $rescued
					}
					continue
				}

				try { Update-MBStreamTimingsFromChunk -Chunk $chunk } catch {}

				$choice0 = $null
				if ($chunk.choices -and @($chunk.choices).Count -gt 0) {
					$choice0 = $chunk.choices[0]
				}
				if ($choice0) {
					$fr = Get-MBProp $choice0 'finish_reason'
					if (-not $fr) { $fr = Get-MBProp (Get-MBProp $choice0 'delta') 'finish_reason' }
					if ($fr -and [string]$fr -ne '' -and [string]$fr -ne 'null') {
						$st.FinishReason = [string]$fr
					}
				}

				$usage = Get-MBProp $chunk 'usage'
				if ($usage) {
					$pt = Get-MBProp $usage 'prompt_tokens'
					$ct = Get-MBProp $usage 'completion_tokens'
					if ($null -ne $pt) {
						$script:MB.LastServerPromptTokens = [int]$pt
						$script:MB.TokenCountSource = 'usage'
						$script:MB.TokCacheKey = ''
						$script:MB.LastCtxTokens = [int]$pt
						try { Set-MBContextBarReady } catch {}
					}
					if ($null -ne $ct) {
						$script:MB.LastServerCompletionTokens = [int]$ct
						$st.HaveUsage = $true
					}
					try { Update-MBStreamTimingsFromChunk -Chunk $usage } catch {}
				}

				if (-not $choice0) { continue }
				$delta = Get-MBProp $choice0 'delta'

				if ($delta -and $delta.tool_calls) {
					$st.HasTools = $true
					foreach ($tc in @($delta.tool_calls)) {
						$idx = 0
						if ($null -ne $tc.index) { $idx = [int]$tc.index }
						if (-not $st.ToolCalls.ContainsKey($idx)) {
							$st.ToolCalls[$idx] = @{
								id = $(if ($tc.id) { $tc.id } else { "call_$idx" })
								type = $(if ($tc.type) { $tc.type } else { "function" })
								function = @{ name = ""; arguments = "" }
							}
						}
						if ($tc.id) { $st.ToolCalls[$idx].id = $tc.id }
						if ($tc.type) { $st.ToolCalls[$idx].type = $tc.type }
						if ($tc.function) {
							if ($tc.function.name) { $st.ToolCalls[$idx].function.name += [string]$tc.function.name }
							if ($null -ne $tc.function.arguments) { $st.ToolCalls[$idx].function.arguments += [string]$tc.function.arguments }
						}
					}
					try { & $noteToolStreamUi $st } catch {}
				}

				$piece = $null
				if ($delta -and $null -ne (Get-MBProp $delta 'content') -and [string](Get-MBProp $delta 'content') -ne '') {
					$piece = [string](Get-MBProp $delta 'content')
				} else {
					$msgObj = Get-MBProp $choice0 'message'
					if ($msgObj) {
						$mc = Get-MBProp $msgObj 'content'
						if ($mc -is [string] -and $mc.Length -gt 0) {
							$fc = [string]$st.FullContent
							if ($fc.Length -eq 0) {
								$piece = $mc
							} elseif ($mc.Length -gt $fc.Length -and $mc.StartsWith($fc)) {
								$piece = $mc.Substring($fc.Length)
							}
						}
					}
				}

				if ($null -ne $piece -and $piece.Length -gt 0) {
					$nowTok = [Environment]::TickCount
					if ([int]$script:MB.StreamFirstTokTick -eq 0) { $script:MB.StreamFirstTokTick = $nowTok }
					if ([int]$script:MB.FirstTokenTick -eq 0) { $script:MB.FirstTokenTick = $nowTok }
					if (-not [bool]$st.StartedOut) {
						Write-MBDebugLog -Step 'STREAM_FIRST_TOKEN' -Detail ("len={0}" -f $piece.Length)
						try { Stop-MBAnimation } catch { Write-MBDebugLog -Step 'STREAM_STOP_ANIM_ERR' -Detail $_.Exception.Message }
						try { Write-MBThoughtStamp } catch {}
						$script:MB.WorkStartTick = $nowTok
						try { if ($script:MB.Wpf) { $script:MB.Wpf.StatusBusySince = $nowTok } } catch {}
						try {
							Write-MBDebugLog -Step 'STREAM_WRITE_BRAND'
							try { Reset-MBMdStream } catch {}
							Write-MBBrand -NoNewline
							Write-Host " " -NoNewline
							Write-MBDebugLog -Step 'STREAM_WRITE_BRAND_OK'
						} catch {
							Write-MBDebugLog -Step 'STREAM_WRITE_BRAND_ERR' -Detail $_.Exception.Message
						}
						$st.StartedOut = $true
					}
					try { Write-MBStreamChunk -Text $piece } catch {
						Write-MBDebugLog -Step 'STREAM_CHUNK_ERR' -Detail $_.Exception.Message
					}
					$st.FullContent = [string]$st.FullContent + $piece
				}
			}

			$fullContent = [string]$st.FullContent
			$startedOutput = [bool]$st.StartedOut
			$finishReason = $st.FinishReason
			$hasToolCalls = [bool]$st.HasTools
			$haveUsageThisStream = [bool]$st.HaveUsage
			$streamParseDrops = [int]$st.ParseDrops
			$toolCalls = $st.ToolCalls
			# Finalize speeds at stream end — before markdown flush / UI (those were padding t/s down).
			try {
				$script:MB.LastReplyChars = $(if ($null -eq $fullContent) { 0 } else { $fullContent.Length })
			} catch { $script:MB.LastReplyChars = 0 }
			try { Complete-MBStreamSpeedMetrics } catch {}
			try {
				Write-MBDebugLog -Step 'STREAM_SPEED' -Detail ("src={0} pp={1:0.0} tg={2:0.0} prefill={3:0.000}s gen={4:0.000}s pt={5} ct={6}" -f `
					$(try { [string]$script:MB.SpeedSource } catch { '?' }),
					$(try { [double]$script:MB.ServerPpS } catch { 0 }),
					$(try { [double]$script:MB.ServerTgS } catch { 0 }),
					$(try { [double]$script:MB.LastPrefillSec } catch { 0 }),
					$(try { [double]$script:MB.LastGenSec } catch { 0 }),
					$(try { [int]$script:MB.LastServerPromptTokens } catch { 0 }),
					$(try { [int]$script:MB.LastServerCompletionTokens } catch { 0 }))
			} catch {}

			if ($script:MB.IsThinking -or $script:MB.AnimPs) {
				Stop-MBAnimation
			} else {
				$script:MB.IsThinking = $false
			}
			if ($startedOutput) {
				try { [Console]::Out.Flush() } catch {}
				try { Write-MBMdStreamFlush } catch {
					Write-MBDebugLog -Step 'STREAM_MARKDOWN_FLUSH_ERR' -Detail $_.Exception.Message
				}
				Write-Host ""
				try {
					if (-not $script:MB.Interrupt) { Write-MBWorkedStamp }
				} catch {}
			} elseif ($hasToolCalls -and -not $script:MB.Interrupt) {
				$boardOnly = $false
				try { $boardOnly = [bool](Test-MBToolCallsAreTaskBoardOnly -ToolCalls $toolCalls) } catch { $boardOnly = $false }
				if ($boardOnly) {
					try { Clear-MBThoughtStampQuiet } catch {}
				} else {
					try { Write-MBThoughtStamp } catch {}
				}
			}

			$ctDone = [int]$script:MB.LastServerCompletionTokens
			if ($finishReason) { $script:MB.LastFinishReason = [string]$finishReason }
			$truncated = Test-MBReplyIncomplete -Text $fullContent -FinishReason $finishReason `
				-HasToolCalls $hasToolCalls -CompletionTokens $ctDone -HaveUsage $haveUsageThisStream
			if ($truncated -and $fullContent.Length -gt 0 -and -not $hasToolCalls) {
				$frShow = if ($finishReason) { $finishReason } else { 'unknown' }
				Write-MBReplyStatus -Title 'reply incomplete' -Meta @(
					('finish: {0}' -f $frShow)
					('{0:N0} chars' -f $fullContent.Length)
					('{0:N0} tok' -f $ctDone)
				) -Hint 'auto-continue if enabled' -DebugOnly -Muted
			} elseif ($streamParseDrops -gt 0 -and $fullContent.Length -gt 0) {
				Write-MBReplyStatus -Title 'stream recovered' -Meta @(
					('{0} malformed chunk(s)' -f $streamParseDrops)
				) -Muted -DebugOnly
			}

			if ($script:MB.Interrupt) {
				$hasToolCalls = $false
				$toolCalls.Clear()
				return [pscustomobject]@{
					choices     = @(@{ message = @{ role = 'assistant'; content = (Sanitize-MBText -Text $(if ($fullContent) { $fullContent } else { '' })) } })
					ok          = $false
					interrupted = $true
					finish_reason = $finishReason
				}
			}

			if ($workMessages -ne $Messages -and $script:Messages) {
			}

			$finalMessage = @{
				role    = 'assistant'
				content = Sanitize-MBText -Text $(if ($fullContent) { $fullContent } else { "" })
			}
			if ($hasToolCalls -and $toolCalls.Count -gt 0) {
				$tcList = New-Object System.Collections.ArrayList
				foreach ($key in ($toolCalls.Keys | Sort-Object)) {
					$tc = $toolCalls[$key]
					if ([string]::IsNullOrWhiteSpace($tc.function.name)) { continue }
					$argStr = Sanitize-MBText -Text ([string]$tc.function.arguments)
					if ([string]::IsNullOrWhiteSpace($argStr)) { $argStr = '{}' }
					[void]$tcList.Add(@{
						id       = Sanitize-MBText -Text ([string]$tc.id)
						type     = 'function'
						function = @{
							name      = Sanitize-MBText -Text ([string]$tc.function.name)
							arguments = $argStr
						}
					})
				}
				if ($tcList.Count -gt 0) {
					$finalMessage['tool_calls'] = @($tcList.ToArray())
				}
			}

			if ($script:MB.PendingVision) {
				Clear-MBPendingVision
			}

			Write-MBDebugLog -Step 'STREAM_SUCCESS' -Detail ("chars={0} tools={1} finish={2}" -f $fullContent.Length, $hasToolCalls, $finishReason)
			return [pscustomobject]@{
				choices       = @(@{ message = $finalMessage })
				ok            = $true
				finish_reason = $finishReason
				truncated     = [bool]$truncated
				completion_tokens = $ctDone
			}
		}
		catch {
			$lastError = Get-MBDeepErrorMessage $_
			Write-MBDebugLog -Step 'STREAM_HTTP_CATCH' -Detail $lastError
			Stop-MBAnimation

			if ($script:MB.Interrupt -or $lastError -match 'abort|cancel|OperationCanceled') {
				$script:MB.Interrupt = $true
				Write-MBDebugLog -Step 'STREAM_INTERRUPTED'
				return [pscustomobject]@{ choices = @(@{ message = @{ role = 'assistant'; content = '' } }); ok = $false; interrupted = $true }
			}

			$script:MB.ApiFailures++

			$isTransient = $false
			$isPayload   = $false
			$isUtf8Poison = $false
			if ($lastError -match 'HTTP (408|429|500|502|503|504)\b') { $isTransient = $true }
			if ($lastError -match 'timed out|timeout|connection.*(reset|closed|refused)|unable to connect|actively refused|NameResolution|SSL/TLS|TaskCanceled|HttpRequestException') {
				$isTransient = $true
			}
			if ($lastError -match 'HTTP 400\b|context|too (large|long)|token|payload|invalid_request') {
				$isPayload = $true
			}
			# Scrub history before compact on encoding error
			if ($lastError -match 'ill-formed UTF-8|invalid UTF-8|parse_error\.101|invalid string:\s*ill-formed') {
				$isUtf8Poison = $true
				$isPayload = $true
			}

			$canRetry = ($attempt -le $RetryCount) -and ($isTransient -or $isPayload -or $attempt -le 2)

			if ($canRetry) {
				$waitMs = [math]::Min(8000, 500 * [math]::Pow(2, [math]::Min($attempt, 4)))
				$waitMs = [int]($waitMs + (Get-Random -Minimum 0 -Maximum 400))

				if ($isUtf8Poison) {
					Write-MBWarn "Server rejected request (ill-formed UTF-8 in JSON) - scrubbing message encoding..."
					try {
						$workMessages = @(Repair-MBMessagesEncoding -Messages $workMessages)
						$script:Messages = $workMessages
					} catch {}
				}

				$looksLikeOom = ($lastError -match 'HTTP 500\b|ggml|memory pool|GGML_ASSERT|out of memory|OOM|not enough space')
				if ((-not $isUtf8Poison -and ($isPayload -or $looksLikeOom -or ($lastError -match 'HTTP 500\b'))) -or ($isUtf8Poison -and $attempt -gt 1)) {
					$didHardCompact = $true
					Write-MBWarn "Server error - trimming context and retrying..."
					try {
						$workMessages = @(Ensure-MBPromptBudget -Messages $workMessages -TargetPct 0.45 -MaxPasses 8)
						$workMessages = @(Manage-MBContext -Messages $workMessages -ForceCompact)
						$workMessages = @(Ensure-MBPromptBudget -Messages $workMessages -TargetPct 0.50 -MaxPasses 4)
						$workMessages = @(Repair-MBMessagesEncoding -Messages $workMessages)
						$script:Messages = $workMessages
					} catch {
						try {
							$workMessages = @(Compact-MBHistory -Messages $workMessages -Aggressive)
							$workMessages = @(Repair-MBMessagesEncoding -Messages $workMessages)
							$script:Messages = $workMessages
						} catch {}
					}
				}

				$shortErr = $lastError
				if ($shortErr.Length -gt 180) { $shortErr = $shortErr.Substring(0, 177) + '...' }
				Write-MBWarn ("Request failed (attempt {0}/{1}): {2}" -f $attempt, ($RetryCount + 1), $shortErr)
				Write-Host ("  retrying in {0}ms  ->  {1}" -f $waitMs, $completionsUrl) -ForegroundColor DarkGray
				Start-Sleep -Milliseconds $waitMs
				Start-MBThinkingAnimation -Name $AgentName
				continue
			}
		}
		finally {
			if ($reader) { try { $reader.Dispose() } catch {} }
			if ($stream) { try { $stream.Dispose() } catch {} }
			if ($httpResponse) { try { $httpResponse.Dispose() } catch {} }
			if ($cts) { try { $cts.Dispose() } catch {} }
			Clear-MBActiveHttp
		}
	}

	Write-MBDebugLog -Step 'STREAM_FAILED_RETRIES' -Detail $lastError
	Write-MBErr "Model request failed after retries: $lastError"
	Write-Host "  endpoint: $completionsUrl" -ForegroundColor DarkGray
	Write-Host "  tip: 502 often means proxy/upstream overload - wait a moment and /retry" -ForegroundColor DarkGray
	return $null
	} catch {
		Write-MBDebugLog -Step 'STREAM_FATAL' -Detail $_.Exception.Message
		try { Stop-MBAnimation } catch {}
		try {
			Show-MBWpfError -Title 'Model stream error' -Message 'The model request crashed while streaming.' -Exception $_.Exception
		} catch {
			try { Write-MBErr "Model stream error: $($_.Exception.Message)" } catch {}
		}
		return $null
	} finally {
		Write-MBDebugLog -Step 'STREAM_FINALLY'
		try { Stop-MBAnimation } catch {}
	}
}

function Invoke-MBCompletion {
	param(
		[array]$Messages,
		[int]$MaxTok = 500,
		[double]$Temp = 0.15,
		[int]$TimeoutSec = 45
	)
	if (-not $Messages -or @($Messages).Count -eq 0) { return $null }
	$apiBase = Get-MBApiBaseUrl
	$completionsUrl = "$apiBase/chat/completions"
	try {
		$norm = @(Normalize-MBMessagesForApi -Messages $Messages)
		$req = @{
			model       = (Get-MBActiveModel)
			messages    = $norm
			temperature = $Temp
			max_tokens  = $MaxTok
			stream      = $false
		}
		$body = ConvertTo-MBRequestJson -Object $req -Depth 12
		$bodyBytes = Get-MBUtf8JsonBytes -Json ([string]$body)

		$client = Get-MBSharedHttpClient
		$cts = New-Object System.Threading.CancellationTokenSource
		try {
			$cts.CancelAfter([TimeSpan]::FromSeconds([math]::Max(10, $TimeoutSec)))
			$request = New-Object System.Net.Http.HttpRequestMessage([System.Net.Http.HttpMethod]::Post, $completionsUrl)
			$authHdr2 = Get-MBAuthHeaderValue -BaseUrl (Get-MBApiBaseUrl)
			if ($authHdr2 -match '^(?i)Basic\s+(.+)$') {
				$request.Headers.Authorization = New-Object System.Net.Http.Headers.AuthenticationHeaderValue("Basic", $Matches[1].Trim())
			} elseif ($authHdr2 -match '^(?i)Bearer\s+(.+)$') {
				$request.Headers.Authorization = New-Object System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", $Matches[1].Trim())
			}
			$request.Content = New-Object System.Net.Http.ByteArrayContent (,[byte[]]$bodyBytes)
			$request.Content.Headers.ContentType = New-Object System.Net.Http.Headers.MediaTypeHeaderValue ("application/json")
			$request.Content.Headers.ContentType.CharSet = "utf-8"

			$script:MB.ActiveHttpClient = $client
			$script:MB.ActiveCts = $cts
			$sendTask = $client.SendAsync($request, $cts.Token)
			while (-not $sendTask.IsCompleted) {
				if ((Test-MBInterrupt)) {
					try { $cts.Cancel() } catch {}
					return $null
				}
				Start-Sleep -Milliseconds 40
			}
			if ($sendTask.IsCanceled -or $script:MB.Interrupt) { return $null }
			if ($sendTask.IsFaulted) { return $null }
			$httpResponse = $sendTask.Result
			try {
				if (-not $httpResponse.IsSuccessStatusCode) { return $null }
				$text = $httpResponse.Content.ReadAsStringAsync().Result
				if ([string]::IsNullOrWhiteSpace($text)) { return $null }
				$obj = $text | ConvertFrom-Json -ErrorAction Stop
				$msg = $null
				if ($obj.choices -and @($obj.choices).Count -gt 0) {
					$msg = $obj.choices[0].message
				}
				$content = Get-MBProp $msg 'content'
				if ([string]::IsNullOrWhiteSpace([string]$content)) { return $null }
				return (Sanitize-MBText -Text ([string]$content)).Trim()
			} finally {
				if ($httpResponse) { try { $httpResponse.Dispose() } catch {} }
			}
		} finally {
			try { $cts.Dispose() } catch {}
			Clear-MBActiveHttp
		}
	} catch {
		return $null
	}
}

function Invoke-MBModelSummary {
	param(
		[string]$Material,
		[int]$MaxTok = 450
	)
	if (-not $script:MB.ModelCompact) { return $null }
	if ([string]::IsNullOrWhiteSpace($Material)) { return $null }
	$mat = Sanitize-MBText -Text $Material
	if ($mat.Length -gt 14000) {
		$mat = $mat.Substring(0, 7000) + "`n...\n" + $mat.Substring($mat.Length - 6000)
	}
	$msgs = @(
		@{
			role    = 'system'
			content = @'
You compress MiniBot agent history into a dense sticky digest. Plain text only. Max 14 short lines using these labels when known:
Goals: ...
CWD: ...
Task board: ...
Files: path (read|edit|write)
Errors: path — last error
Tools: names tried
Decisions: ...
Open asks: ...
No tools. No preamble. Prefer facts over narration.
'@
		}
		@{
			role    = 'user'
			content = "Summarize this excerpt for future context:`n`n$mat"
		}
	)
	return (Invoke-MBCompletion -Messages $msgs -MaxTok $MaxTok -Temp 0.1 -TimeoutSec 20)
}

function Get-MBToolFingerprint {
	param(
		[string]$Name,
		$ArgsObj
	)
	if (-not $ArgsObj) { $ArgsObj = [pscustomobject]@{} }
	$parts = New-Object System.Collections.ArrayList
	[void]$parts.Add(([string]$Name).ToLowerInvariant())

	switch -Regex ($Name) {
		'^RunCommand$' {
			$cmd = [string](Get-MBProp $ArgsObj 'command')
			$shell = [string](Get-MBProp $ArgsObj 'shell' 'powershell')
			$cmd = ($cmd -replace '\s+', ' ').Trim().ToLowerInvariant()
			[void]$parts.Add($shell.ToLowerInvariant())
			[void]$parts.Add($cmd)
		}
		'^TaskBoard$' {
			$act = ''
			try { $act = ([string](Get-MBProp $ArgsObj 'action')).Trim().ToLowerInvariant() } catch { $act = '' }
			if ([string]::IsNullOrWhiteSpace($act)) { $act = 'status' }
			[void]$parts.Add(('action={0}' -f $act))
			$idRaw = ''
			try { $idRaw = [string](Get-MBProp $ArgsObj 'id') } catch { $idRaw = '' }
			$idRes = $idRaw
			try { $idRes = Resolve-MBTaskBoardIdAlias -Id $idRaw } catch { $idRes = $idRaw }
			if ([string]::IsNullOrWhiteSpace($idRes)) { $idRes = $idRaw }
			if (-not [string]::IsNullOrWhiteSpace($idRes)) {
				[void]$parts.Add(('id={0}' -f $idRes.Trim().ToLowerInvariant()))
			}
			foreach ($k in @('status', 'title', 'note', 'goal', 'replace', 'epoch', 'verbose')) {
				if (Test-MBHasProp $ArgsObj $k) {
					$v = Get-MBProp $ArgsObj $k
					if ($null -ne $v -and "$v" -ne '') {
						$s = ([string]$v -replace '\s+', ' ').Trim()
						if ($s.Length -gt 200) { $s = $s.Substring(0, 200) }
						[void]$parts.Add(('{0}={1}' -f $k.ToLowerInvariant(), $s.ToLowerInvariant()))
					}
				}
			}
			# Full payload for items/updates/ids — never collapse to items=1 (17-item set vs 8-item set must differ)
			foreach ($bulkKey in @('items', 'updates', 'ids')) {
				if (-not (Test-MBHasProp $ArgsObj $bulkKey)) { continue }
				$bv = Get-MBProp $ArgsObj $bulkKey
				if ($null -eq $bv) { continue }
				$bs = ''
				try {
					if ($bv -is [string]) {
						$bs = ([string]$bv -replace '\s+', ' ').Trim()
					} elseif ($bv -is [System.Array] -or ($bv -is [System.Collections.IEnumerable] -and -not ($bv -is [string]))) {
						$nBulk = 0
						try { $nBulk = @($bv).Count } catch { $nBulk = 0 }
						[void]$parts.Add(('{0}_n={1}' -f $bulkKey, $nBulk))
						try {
							$bs = ($bv | ConvertTo-Json -Compress -Depth 6 -ErrorAction Stop)
						} catch {
							try { $bs = (@($bv) | ForEach-Object { "$_" }) -join '|' } catch { $bs = 'bulk' }
						}
					} else {
						try { $bs = ($bv | ConvertTo-Json -Compress -Depth 6 -ErrorAction Stop) } catch { $bs = [string]$bv }
					}
				} catch { $bs = [string]$bv }
				$bs = ([string]$bs -replace '\s+', ' ').Trim()
				if ($bs.Length -gt 0) {
					if ($bs.Length -le 800) {
						[void]$parts.Add(('{0}={1}' -f $bulkKey, $bs.ToLowerInvariant()))
					} else {
						# Long plans: count + hash so different item lists never collide
						$h = ''
						try {
							$sha = [System.Security.Cryptography.SHA256]::Create()
							try {
								$bytes = [System.Text.Encoding]::UTF8.GetBytes($bs.ToLowerInvariant())
								$h = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '').Substring(0, 16)
							} finally { try { $sha.Dispose() } catch {} }
						} catch { $h = ('len{0}' -f $bs.Length) }
						[void]$parts.Add(('{0}=#{1}' -f $bulkKey, $h))
					}
				}
			}
			try { [void]$parts.Add(('focus={0}' -f ([string](Get-MBTaskBoardNowId)).ToLowerInvariant())) } catch {}
			try { [void]$parts.Add(('board_epoch={0}' -f [int](Get-MBTaskBoardEpoch))) } catch {}
		}
		'^ReadFile$|^WriteFile$|^EditFile$|^ApplyPatch$|^ListDirectory$|^SearchFiles$|^FindFiles$|^DiffText$|^HexView$|^HexEdit$|^HexSearch$|^StringsScan$|^SandBox$|^SandBoxWrite$' {
			foreach ($k in @('path','path2','compare','search','replace','pattern','glob','globs','extensions','head','tail','offset','length','width','show_ascii','annotate','detail','next_diff','side_by_side','max_scan','disasm','trace','at_entry','max_insns','max_steps','follow_calls','prefer_branch','arch','dump_hex','hex','bytes','extend','backup','useRegex','replaceAll','occurrence','recursive','ignoreCase','maxResults','max','modified_within_days','min_bytes','max_bytes','patch','code','test_script','timeout_sec','expect_exit','expect_stdout','expect_stdout_regex','expect_stderr_empty','name','piece','save_as','compose','description','left','right','leftIsFile','rightIsFile','context','maxLines','content','edits','entropy','carve','rva','section','entropy_blocks','minLen','maxHits','encoding','filter','hash','functions','preset')) {
				if (Test-MBHasProp $ArgsObj $k) {
					$v = Get-MBProp $ArgsObj $k
					if ($null -ne $v) {
						$s = $null
						if ($v -is [System.Array] -or ($v -is [System.Collections.IEnumerable] -and -not ($v -is [string]))) {
							try { $s = (@($v) | ForEach-Object { "$_" }) -join ',' } catch { $s = [string]$v }
						} else { $s = [string]$v }
						if ($s.Length -gt 200) { $s = $s.Substring(0, 200) }
						[void]$parts.Add("$k=$s")
					}
				}
			}
			if (Test-MBHasProp $ArgsObj 'edits') {
				try {
					$ed = Get-MBProp $ArgsObj 'edits'
					$ej = $ed | ConvertTo-Json -Compress -Depth 4
					if ($ej.Length -gt 240) { $ej = $ej.Substring(0, 240) }
					[void]$parts.Add("edits=$ej")
				} catch {
					[void]$parts.Add('edits=1')
				}
			}
			if (Test-MBHasProp $ArgsObj 'assert') {
				try {
					$aj = (Get-MBProp $ArgsObj 'assert') | ConvertTo-Json -Compress -Depth 4
					if ($aj.Length -gt 200) { $aj = $aj.Substring(0, 200) }
					[void]$parts.Add("assert=$aj")
				} catch {
					[void]$parts.Add('assert=1')
				}
			}
			if (Test-MBHasProp $ArgsObj 'pieces') {
				try {
					$pj = (Get-MBProp $ArgsObj 'pieces') | ConvertTo-Json -Compress -Depth 4
					if ($pj.Length -gt 160) { $pj = $pj.Substring(0, 160) }
					[void]$parts.Add("pieces=$pj")
				} catch {
					[void]$parts.Add('pieces=1')
				}
			}
		}
		'^GetEventLogs$|^GetProcessList$|^GetServiceStatus$|^GetDriverInfo$|^GetScheduledTasks$|^GetDiskSpace$' {
			foreach ($p in $ArgsObj.PSObject.Properties) {
				if ($null -ne $p.Value -and "$($p.Value)" -ne '') {
					[void]$parts.Add("$($p.Name)=$($p.Value)")
				}
			}
		}
		'^MakeHttpRequest$|^BrowsePage$|^SearchWeb$|^GetGitHubRawFile$|^ListGitHubDirectory$|^ConvertGitHubUrl$|^DownloadFile$' {
			foreach ($k in @('method','url','github_url','ref','max_length','path','overwrite','max_mb','timeout_sec','query','max_results','engine','extract_links','max_links','verify_ssl')) {
				if (Test-MBHasProp $ArgsObj $k) {
					$v = Get-MBProp $ArgsObj $k
					if ($null -ne $v) { [void]$parts.Add("$k=$v") }
				}
			}
		}
		'^ControlService$|^ExpandArchive$|^CompressArchive$|^MakeCab$|^ExpandCab$|^MakeIso$|^MountIso$|^UnmountIso$|^BulkRename$|^FindDuplicates$|^FindPSModule$|^GetInstalledPSModule$|^InstallPSModule$|^UpdatePSModule$' {
			foreach ($k in @('name','action','startup_type','path','directory','source','destination','iso_path','cab_path','boot_file','title','force','include_folder','media','letter','files','recursive','compression','compression_level','compression_memory','version','scope','allow_prerelease','max_results','glob','find','replace','use_regex','template','start_index','dry_run','max','min_bytes','max_scan','max_groups','max_per_group')) {
				if (Test-MBHasProp $ArgsObj $k) {
					$v = Get-MBProp $ArgsObj $k
					if ($null -ne $v -and "$v" -ne '') { [void]$parts.Add("$k=$v") }
				}
			}
		}
		default {
			try {
				$j = ConvertTo-Json -InputObject $ArgsObj -Depth 6 -Compress
				[void]$parts.Add(($j -replace '\s+', ''))
			} catch {
				[void]$parts.Add('args')
			}
		}
	}

	return ($parts -join '||')
}

function Test-MBToolLoopGuard {
	param(
		[string]$Name,
		$ArgsObj
	)

	$fp = Get-MBToolFingerprint -Name $Name -ArgsObj $ArgsObj
	$preview = [string]$script:MB.LastToolPreview
	if ($preview.Length -gt 600) { $preview = $preview.Substring(0, 597) + '...' }
	if (-not $preview) { $preview = '(previous result not retained)' }

	# Repeated BLOCKED / NEED_INPUT for same fingerprint this turn → stop and ask
	try {
		if ($null -eq $script:MB.FpForceStop) { $script:MB.FpForceStop = @{} }
		if ($script:MB.FpForceStop.ContainsKey($fp) -and $script:MB.FpForceStop[$fp]) {
			$script:MB.LoopGuardsFired++
			Write-Host "    loop-guard: NEED_INPUT stop (blocked/need_input twice)" -ForegroundColor Red
			$msg = @"
LOOP GUARD HARD STOP: NEED_INPUT=1 TOOLS_DONE=1 NO_MORE_TOOLS=1 FINISH_TURN=1

Tool: $Name

This exact call already failed or was blocked twice this turn (operator deny, NEED_INPUT, or hard stop).
Further identical retries will not help.

Previous result (truncated):
$preview

REQUIRED: STOP all tools. Reply to the operator with what you need (credentials, approval, path, clarification). Do NOT call tools again until they answer.
"@
			return @{ Block = $true; Message = $msg; Fingerprint = $fp; NeedInput = $true }
		}
	} catch {}

	$alreadyConfirmedThisTurn = $false
	foreach ($x in @($script:MB.LoopConfirmedFps)) {
		if ($x -eq $fp) { $alreadyConfirmedThisTurn = $true; break }
	}

	if ($script:MB.LastToolFp -eq $fp -and ($alreadyConfirmedThisTurn -or $script:MB.LastToolAction -eq 'confirmed_ran')) {
		$script:MB.LoopGuardsFired++
		Write-Host "    loop-guard: HARD STOP (already retested once)" -ForegroundColor Red
		try {
			if ($null -eq $script:MB.FpForceStop) { $script:MB.FpForceStop = @{} }
			$script:MB.FpForceStop[$fp] = $true
		} catch {}
		$msg = @"
LOOP GUARD HARD STOP: TOOLS_DONE=1 NO_MORE_TOOLS=1 FINISH_TURN=1

You already re-ran this exact tool call once this turn (timing retest used up).

Tool: $Name

Repeating it again will NOT help. The same command with the same arguments produces the same result unless wall-clock time or external state changed - and you already spent your one retest.

Previous result (truncated):
$preview

REQUIRED: Stop calling this tool with these args. Do one of:
1) Use a DIFFERENT tool or DIFFERENT arguments
2) Synthesize an answer for the user from results you already have — end with DID / NEXT
3) NEED_INPUT: Ask the user what to do next

Do NOT reconfirm or re-request this same call.
"@
		$script:MB.LastToolAction = 'confirmed_ran'
		return @{ Block = $true; Message = $msg; Fingerprint = $fp }
	}

	if ($script:MB.LastToolFp -eq $fp -and $script:MB.LastToolAction -eq 'ran') {
		$script:MB.LastToolAction = 'warned'
		$script:MB.LoopGuardsFired++
		Write-Host "    loop-guard: blocked - same command will not magically change" -ForegroundColor Yellow

		$msg = @"
LOOP GUARD: You just ran this exact tool call. It was NOT executed again. (same command ⇒ same result)

Tool: $Name

IMPORTANT:
- Re-running the identical tool with identical arguments will NOT produce new information.
- Do NOT keep confirming or retrying this call expecting a different outcome.

The ONLY valid reason to run it again is a deliberate timing/poll check (DISM, download, service start) after real time passed.

Previous result (truncated) - USE THIS:
$preview

What to do instead:
1) Different tool or different args, or report findings (DID / NEXT)
2) ONLY if polling over time: call this exact tool ONE more time (allowed once). After that: TOOLS_DONE hard-block.
"@
		return @{ Block = $true; Message = $msg; Fingerprint = $fp }
	}

	if ($script:MB.LastToolFp -eq $fp -and $script:MB.LastToolAction -eq 'warned') {
		if ($alreadyConfirmedThisTurn) {
			$script:MB.LoopGuardsFired++
			try {
				if ($null -eq $script:MB.FpForceStop) { $script:MB.FpForceStop = @{} }
				$script:MB.FpForceStop[$fp] = $true
			} catch {}
			return @{
				Block = $true
				Fingerprint = $fp
				Message = "LOOP GUARD HARD STOP: TOOLS_DONE=1 NO_MORE_TOOLS=1 FINISH_TURN=1 Timing retest already used. Change approach or ASK the operator."
			}
		}
		Write-Host "    loop-guard: one timing retest allowed - executing" -ForegroundColor Green
		return @{ Block = $false; Confirmed = $true; Fingerprint = $fp }
	}

	return @{ Block = $false; Confirmed = $false; Fingerprint = $fp }
}

function Register-MBPathPin {
	# Sticky pin for files the agent read/edited/wrote this session (cheap path list).
	param(
		[string]$Path,
		[ValidateSet('read','edit','write','error')]$Action = 'read'
	)
	if ([string]::IsNullOrWhiteSpace($Path)) { return }
	try {
		$full = $Path
		try { $full = [System.IO.Path]::GetFullPath($Path) } catch { $full = $Path }
		$key = $full.ToLowerInvariant()
		if ($null -eq $script:MB.PinnedPaths) { $script:MB.PinnedPaths = [ordered]@{} }
		$entry = $null
		if ($script:MB.PinnedPaths.Contains($key)) {
			$entry = $script:MB.PinnedPaths[$key]
		} else {
			$entry = [ordered]@{ path = $full; actions = New-Object System.Collections.ArrayList; last = 0L }
			$script:MB.PinnedPaths[$key] = $entry
		}
		$acts = $entry.actions
		if ($acts -isnot [System.Collections.ArrayList]) {
			$acts = New-Object System.Collections.ArrayList
			foreach ($a in @($entry.actions)) { [void]$acts.Add($a) }
			$entry.actions = $acts
		}
		$al = $Action.ToLowerInvariant()
		$has = $false
		foreach ($x in @($acts)) { if ([string]$x -eq $al) { $has = $true; break } }
		if (-not $has) { [void]$acts.Add($al) }
		$entry.last = [datetime]::UtcNow.Ticks
		$entry.path = $full
		# Cap pins (keep newest 16)
		if ($script:MB.PinnedPaths.Count -gt 20) {
			$ordered = @($script:MB.PinnedPaths.GetEnumerator() | Sort-Object { $_.Value.last } -Descending)
			$keep = [ordered]@{}
			$n = 0
			foreach ($e in $ordered) {
				if ($n -ge 16) { break }
				$keep[$e.Key] = $e.Value
				$n++
			}
			$script:MB.PinnedPaths = $keep
		}
	} catch {}
}

function Register-MBToolErrorForPath {
	param([string]$Path, [string]$Snippet)
	if ([string]::IsNullOrWhiteSpace($Path)) { return }
	try {
		$full = $Path
		try { $full = [System.IO.Path]::GetFullPath($Path) } catch { $full = $Path }
		$key = $full.ToLowerInvariant()
		if ($null -eq $script:MB.ToolErrorsByPath) { $script:MB.ToolErrorsByPath = @{} }
		$s = ([string]$Snippet) -replace '\s+', ' '
		if ($s.Length -gt 280) { $s = $s.Substring(0, 277) + '...' }
		$script:MB.ToolErrorsByPath[$key] = [ordered]@{
			path    = $full
			error   = $s
			at      = [datetime]::UtcNow.Ticks
		}
		if ($script:MB.ToolErrorsByPath.Count -gt 24) {
			$ordered = @($script:MB.ToolErrorsByPath.GetEnumerator() | Sort-Object { $_.Value.at } -Descending)
			$keep = @{}
			$n = 0
			foreach ($e in $ordered) {
				if ($n -ge 16) { break }
				$keep[$e.Key] = $e.Value
				$n++
			}
			$script:MB.ToolErrorsByPath = $keep
		}
	} catch {}
}

function Get-MBToolArgPath {
	param($ArgsObj)
	if ($null -eq $ArgsObj) { return $null }
	foreach ($k in @('path', 'path2', 'left', 'right', 'destination', 'source', 'github_url')) {
		if (Test-MBHasProp $ArgsObj $k) {
			$v = [string](Get-MBProp $ArgsObj $k)
			if (-not [string]::IsNullOrWhiteSpace($v) -and $v -notmatch '^(?i)https?://') { return $v }
		}
	}
	return $null
}

function Register-MBToolOutcome {
	# After a tool runs: path pins, error retention, bad-outcome counts, turn summary.
	param(
		[string]$Name,
		$ArgsObj,
		[string]$Result,
		[string]$Fingerprint = ''
	)
	try {
		if ($null -eq $script:MB.TurnToolSummary) {
			$script:MB.TurnToolSummary = New-Object System.Collections.ArrayList
		}
		$r = [string]$Result
		$ok = $true
		$tag = 'ok'
		if ($r -match '(?i)^ERROR:|LOOP GUARD|BLOCKED BY USER|NEED_INPUT|TOOLS_DONE=1|remote_port_closed=1|remote_command_unavailable=1') {
			$ok = $false
			if ($r -match '(?i)BLOCKED BY USER') { $tag = 'blocked' }
			elseif ($r -match '(?i)NEED_INPUT') { $tag = 'need_input' }
			elseif ($r -match '(?i)LOOP GUARD') { $tag = 'loop_guard' }
			elseif ($r -match '(?i)TOOLS_DONE=1') { $tag = 'tools_done' }
			else { $tag = 'error' }
		} elseif ($r -match '(?i)^SUCCESS') {
			$tag = 'success'
		}

		$path = Get-MBToolArgPath -ArgsObj $ArgsObj
		$line = $Name
		if ($path) { $line += " $path" }
		$line += " [$tag]"
		if (-not $ok) {
			$snip = ($r -replace '\s+', ' ').Trim()
			if ($snip.Length -gt 100) { $snip = $snip.Substring(0, 97) + '...' }
			$line += " $snip"
		}
		[void]$script:MB.TurnToolSummary.Add($line)
		while ($script:MB.TurnToolSummary.Count -gt 24) { $script:MB.TurnToolSummary.RemoveAt(0) }

		# Path pins by tool class
		$nlow = ([string]$Name).ToLowerInvariant()
		if ($path) {
			if ($nlow -match 'readfile|hexview|hexsearch|stringsscan|list|searchfiles|findfiles|difftext') {
				Register-MBPathPin -Path $path -Action 'read'
			} elseif ($nlow -match 'editfile|applypatch|hexedit') {
				Register-MBPathPin -Path $path -Action $(if ($ok) { 'edit' } else { 'error' })
			} elseif ($nlow -match 'writefile|downloadfile') {
				Register-MBPathPin -Path $path -Action $(if ($ok) { 'write' } else { 'error' })
			}
			if (-not $ok) {
				Register-MBToolErrorForPath -Path $path -Snippet $r
				Register-MBPathPin -Path $path -Action 'error'
			}
		}

		# Bad outcome thrash → force stop next identical call
		if (-not $ok -and $Fingerprint -and $tag -in @('blocked', 'need_input', 'loop_guard', 'tools_done', 'error')) {
			if ($null -eq $script:MB.FpBadOutcomeHits) { $script:MB.FpBadOutcomeHits = @{} }
			$hits = 0
			if ($script:MB.FpBadOutcomeHits.ContainsKey($Fingerprint)) {
				$hits = [int]$script:MB.FpBadOutcomeHits[$Fingerprint]
			}
			$hits++
			$script:MB.FpBadOutcomeHits[$Fingerprint] = $hits
			# Two operator blocks / NEED_INPUT / hard stops → stop third try
			if ($hits -ge 2 -and $tag -in @('blocked', 'need_input', 'loop_guard', 'tools_done')) {
				if ($null -eq $script:MB.FpForceStop) { $script:MB.FpForceStop = @{} }
				$script:MB.FpForceStop[$Fingerprint] = $true
			}
			# Three plain errors (same call) also force stop
			if ($hits -ge 3 -and $tag -eq 'error') {
				if ($null -eq $script:MB.FpForceStop) { $script:MB.FpForceStop = @{} }
				$script:MB.FpForceStop[$Fingerprint] = $true
			}
		}
	} catch {}
}

function Get-MBPostToolTurnHint {
	# Slim turn nudge after a tool batch. Stored in SESSION STATE (LastTurnHygiene) — never
	# appended as mid-history system messages (local chat templates often reject those as invalid).
	# Board text lives in SESSION STATE; hint is slim.
	param([bool]$ForceFooter = $true)
	$lines = New-Object System.Collections.ArrayList
	[void]$lines.Add('[TURN_HYGIENE — follow before more tools or final reply]')

	$sum = @()
	try { $sum = @($script:MB.TurnToolSummary) } catch { $sum = @() }
	if ($sum.Count -gt 0) {
		[void]$lines.Add('Tools this turn:')
		foreach ($s in ($sum | Select-Object -Last 8)) {
			[void]$lines.Add(" - $s")
		}
	}

	$needBoard = $false
	try { $needBoard = -not (Test-MBTaskBoardHasOpen) -and [bool]$script:MB.PendingTaskBoardNudge } catch {}
	if ($needBoard) {
		# Only when multi-step was detected but no board yet (not every turn)
		[void]$lines.Add('TaskBoard empty for multi-step ask — action=set before more tools (or skip if one simple call).')
	} elseif (Test-MBTaskBoardHasOpen) {
		# Board already in SESSION STATE — focus pointer only (in_progress or blocked head)
		try {
			$nid = Get-MBTaskBoardNowId
			$nt = Get-MBTaskBoardNowTitle
			if ($nid) {
				$stFocus = ''
				foreach ($it in (Get-MBTaskBoardItemCollection)) {
					if ($null -eq $it) { continue }
					$iid = Get-MBTaskBoardItemField -Item $it -Name 'Id'
					if ([string]::Equals($iid, $nid, [StringComparison]::OrdinalIgnoreCase)) {
						$stFocus = (Get-MBTaskBoardItemField -Item $it -Name 'Status').ToLowerInvariant()
						break
					}
				}
				if ($stFocus -eq 'blocked') {
					[void]$lines.Add(("NOW (blocked): {0}: {1} — unblock/fix or ask operator; do not skip ahead." -f $nid, $nt))
				} else {
					[void]$lines.Add(("NOW: {0}: {1} — do only this; status=done when finished." -f $nid, $nt))
				}
			}
		} catch {}
	}

	$hasForce = $false
	try {
		if ($script:MB.FpForceStop) {
			foreach ($k in @($script:MB.FpForceStop.Keys)) {
				if ($script:MB.FpForceStop[$k]) { $hasForce = $true; break }
			}
		}
	} catch {}
	if ($hasForce) {
		[void]$lines.Add('STOP: A tool fingerprint is hard-stopped (TOOLS_DONE / NEED_INPUT). Do not retry it. Ask operator or change approach.')
	}

	if ($ForceFooter) {
		[void]$lines.Add('If no more tools: end your user-facing reply with short lines:')
		[void]$lines.Add('DID: <what worked>')
		[void]$lines.Add('NEXT: <follow-up>  OR  ASK: <what you need from the operator>')
	}
	return ($lines -join "`n")
}

function Test-MBUserMessageMultiStep {
	param([string]$Text)
	if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
	$t = $Text.ToLowerInvariant()
	# Heuristic: multi-clause goals / planning language
	if ($t -match '\b(and then|then |after that|first |next |finally |step\s*\d|multi-?step|end[- ]to[- ]end|one by one|in order)\b') { return $true }
	if ($t -match '\b(diagnose|investigate|troubleshoot|fix all|refactor|migrate|setup|configure|harden|audit|install and|find and|scan and|clean up|build|implement|wire up|create and)\b') { return $true }
	if ($t -match '\b(and)\b' -and $t -match '\b(then|also|plus|as well|after)\b') { return $true }
	if ($t -match '\b(several|multiple|all the|every |each |both )\b' -and $t -match '\b(file|host|share|service|error|issue|folder|machine|pc|user|path|tool|step|task)\b') { return $true }
	# Two+ distinct action verbs often means multi-step
	$verbs = @([regex]::Matches($t, '\b(read|write|edit|find|scan|fix|install|remove|map|share|check|test|update|create|delete|copy|move|rename|set|get|list|search|probe|connect)\b'))
	if ($verbs.Count -ge 3) { return $true }
	# Enumerated list
	if ($t -match '(?m)^\s*[-*]\s+\S' -or $t -match '(?m)^\s*\d+[.)]\s+\S') {
		$lines = @($t -split "`n" | Where-Object { $_ -match '^\s*([-*]|\d+[.)])\s+\S' })
		if ($lines.Count -ge 2) { return $true }
	}
	# Long asks with multiple clauses (commas / semicolons) tend to be multi-step
	if ($t.Length -gt 160 -and (($t -split '[;.]').Count -ge 3)) { return $true }
	return $false
}

function Register-MBMultiStepNudgeFromUser {
	param([string]$Text)
	try {
		$script:MB.PendingTaskBoardNudge = $false
		if (-not (Test-MBUserMessageMultiStep -Text $Text)) { return }
		if (Test-MBTaskBoardHasOpen) { return }
		$script:MB.PendingTaskBoardNudge = $true
		[void](Add-MBStickyNote -Text 'Multi-step ask detected - TaskBoard action=set (goal + ordered items) BEFORE other tools; then execute only now.' -Kind 'note')
	} catch {}
}

function Register-MBToolExecution {
	param(
		[string]$Fingerprint,
		[string]$ResultPreview,
		[bool]$WasConfirmed = $false,
		[string]$ToolName = '',
		$ArgsObj = $null
	)
	$script:MB.LastToolFp = $Fingerprint
	if ($WasConfirmed) {
		$script:MB.LastToolAction = 'confirmed_ran'
		$exists = $false
		foreach ($x in @($script:MB.LoopConfirmedFps)) {
			if ($x -eq $Fingerprint) { $exists = $true; break }
		}
		if (-not $exists) {
			[void]$script:MB.LoopConfirmedFps.Add($Fingerprint)
		}
	} else {
		$script:MB.LastToolAction = 'ran'
	}
	$prev = Sanitize-MBText -Text ([string]$ResultPreview)
	if ($prev.Length -gt 800) { $prev = $prev.Substring(0, 797) + '...' }
	$script:MB.LastToolPreview = $prev
	try {
		Register-MBToolOutcome -Name $ToolName -ArgsObj $ArgsObj -Result $ResultPreview -Fingerprint $Fingerprint
	} catch {}
}

function Reset-MBToolLoopGuard {
	$script:MB.LastToolFp = $null
	$script:MB.LastToolAction = $null
	$script:MB.LastToolPreview = ''
	try { $script:MB.LoopConfirmedFps.Clear() } catch {
		$script:MB.LoopConfirmedFps = New-Object System.Collections.ArrayList
	}
	try { $script:MB.RemotePortClosedBlocks = @{} } catch {}
	try { $script:MB.FpBadOutcomeHits = @{} } catch {}
	try { $script:MB.FpForceStop = @{} } catch {}
	try {
		if ($null -eq $script:MB.TurnToolSummary) {
			$script:MB.TurnToolSummary = New-Object System.Collections.ArrayList
		} else {
			$script:MB.TurnToolSummary.Clear()
		}
	} catch {
		$script:MB.TurnToolSummary = New-Object System.Collections.ArrayList
	}
	try { $script:MB.PendingTaskBoardNudge = $false } catch {}
	try { $script:MB.LastTurnHygiene = '' } catch {}
}

# Setup / tune and installer tools
function Ensure-MBAudioEndpoint {
	# Compiled at launch inside MiniBot.Core.
	if ($script:HasAudioEndpoint -or ('MiniBot.Core.AudioEndpoint' -as [type])) {
		$script:HasAudioEndpoint = $true
		return $true
	}
	return $false
}

function Invoke-AudioVolume {
	param(
		[string]$action = 'get',
		[int]$level = -1
	)
	$a = ([string]$action).Trim().ToLowerInvariant()
	if ([string]::IsNullOrWhiteSpace($a)) { $a = 'get' }
	if (-not (Ensure-MBAudioEndpoint)) {
		return ConvertTo-MBJson ([ordered]@{
			ok      = $false
			error   = 'Audio endpoint helper failed to load (Core Audio COM).'
			level   = $null
			mute    = $null
		})
	}
	try {
		if ($a -eq 'get') {
			$lv = 0.0
			$mu = $false
			$err = $null
			$role = -1
			$ok = [MiniBot.Core.AudioEndpoint]::TryGet([ref]$lv, [ref]$mu, [ref]$err, [ref]$role)
			if (-not $ok) {
				return ConvertTo-MBJson ([ordered]@{
					ok           = $false
					has_endpoint = $false
					error        = $(if ($err) { [string]$err } else { 'No default playback endpoint' })
					level        = $null
					mute         = $null
					note         = 'Common on headless sessions or when default device is missing after docking/undocking. Open Sound settings and set a default playback device.'
				})
			}
			$pct = [int][math]::Round(([double]$lv) * 100)
			$roleName = switch ([int]$role) {
				0 { 'console' }
				1 { 'multimedia' }
				2 { 'communications' }
				default { 'unknown' }
			}
			return ConvertTo-MBJson ([ordered]@{
				ok           = $true
				has_endpoint = $true
				level        = $pct
				mute         = [bool]$mu
				role         = $roleName
			})
		}
		if ($a -eq 'mute' -or $a -eq 'unmute' -or $a -eq 'set') {
			$details = switch ($a) {
				'mute' { 'Mute default playback device.' }
				'unmute' { 'Unmute default playback device.' }
				default {
					if ($level -lt 0 -or $level -gt 100) {
						return ConvertTo-MBJson ([ordered]@{ ok = $false; error = 'level must be 0-100 for action=set' })
					}
					"Set default playback volume to $level%."
				}
			}
			if (-not (Request-Confirmation -Title "AudioVolume requires approval" -Details $details)) {
				return ConvertTo-MBJson ([ordered]@{ ok = $false; error = 'AudioVolume denied by operator'; denied = $true })
			}
			$err = $null
			$setOk = $false
			if ($a -eq 'mute') {
				$setOk = [MiniBot.Core.AudioEndpoint]::TrySetMute($true, [ref]$err)
			} elseif ($a -eq 'unmute') {
				$setOk = [MiniBot.Core.AudioEndpoint]::TrySetMute($false, [ref]$err)
			} else {
				$setOk = [MiniBot.Core.AudioEndpoint]::TrySetLevel(([float]($level / 100.0)), [ref]$err)
				if ($setOk) {
					# Unmute when raising volume above 0
					$lv2 = 0.0; $mu2 = $false; $e2 = $null; $r2 = -1
					if ([MiniBot.Core.AudioEndpoint]::TryGet([ref]$lv2, [ref]$mu2, [ref]$e2, [ref]$r2)) {
						if ($mu2 -and $level -gt 0) {
							[void][MiniBot.Core.AudioEndpoint]::TrySetMute($false, [ref]$err)
						}
					}
				}
			}
			if (-not $setOk) {
				return ConvertTo-MBJson ([ordered]@{
					ok           = $false
					has_endpoint = $false
					action       = $a
					error        = $(if ($err) { [string]$err } else { 'Set failed' })
				})
			}
			$lv = 0.0; $mu = $false; $e3 = $null; $r3 = -1
			[void][MiniBot.Core.AudioEndpoint]::TryGet([ref]$lv, [ref]$mu, [ref]$e3, [ref]$r3)
			$pct = [int][math]::Round(([double]$lv) * 100)
			return ConvertTo-MBJson ([ordered]@{
				ok           = $true
				has_endpoint = $true
				action       = $a
				level        = $pct
				mute         = [bool]$mu
			})
		}
		return ConvertTo-MBJson ([ordered]@{ ok = $false; error = 'action must be get|set|mute|unmute' })
	} catch {
		return ConvertTo-MBJson ([ordered]@{
			ok    = $false
			error = $_.Exception.Message
			level = $null
			mute  = $null
		})
	}
}

function Invoke-DisplayBrightness {
	param(
		[string]$action = 'get',
		[int]$level = -1
	)
	$a = ([string]$action).Trim().ToLowerInvariant()
	if ([string]::IsNullOrWhiteSpace($a)) { $a = 'get' }
	try {
		$m = Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightness -ErrorAction SilentlyContinue |
			Select-Object -First 1
		$methods = Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightnessMethods -ErrorAction SilentlyContinue |
			Select-Object -First 1
		if (-not $m) {
			return ConvertTo-MBJson ([ordered]@{
				ok          = $false
				supported   = $false
				note        = 'No WmiMonitorBrightness instance (common on desktops / external monitors).'
			})
		}
		$cur = [int]$m.CurrentBrightness
		if ($a -eq 'get') {
			return ConvertTo-MBJson ([ordered]@{
				ok        = $true
				supported = $true
				level     = $cur
				levels    = @($m.Level)
			})
		}
		if ($a -ne 'set') { return "ERROR: action must be get|set." }
		if ($level -lt 0 -or $level -gt 100) { return "ERROR: level must be 0-100." }
		if (-not $methods) {
			return "ERROR: Brightness methods not available on this display."
		}
		if (-not (Request-Confirmation -Title "DisplayBrightness requires approval" -Details "Set internal display brightness to $level% (current $cur%).")) {
			return "BLOCKED BY USER: DisplayBrightness denied."
		}
		Invoke-CimMethod -InputObject $methods -MethodName WmiSetBrightness -Arguments @{ Timeout = 1; Brightness = [byte]$level } -ErrorAction Stop | Out-Null
		$m2 = Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightness -ErrorAction SilentlyContinue | Select-Object -First 1
		$now = if ($m2) { [int]$m2.CurrentBrightness } else { $level }
		return ConvertTo-MBJson ([ordered]@{ ok = $true; supported = $true; level = $now; requested = $level })
	} catch {
		return "ERROR: DisplayBrightness failed: $($_.Exception.Message)"
	}
}

function Get-MBWindowsOptionCatalog {
	return [ordered]@{
		'explorer.hidden_files' = @{ values = @('show','hide'); desc = 'Show/hide hidden files in Explorer' }
		'explorer.file_extensions' = @{ values = @('show','hide'); desc = 'Show/hide known file extensions' }
		'explorer.compact_mode' = @{ values = @('on','off'); desc = 'Win11 Explorer compact spacing' }
		'explorer.classic_context_menu' = @{ values = @('on','off'); desc = 'Win11 classic right-click menu' }
		'uac' = @{ values = @('enable','disable'); desc = 'UAC EnableLUA (reboot may be required)' }
		'power.max_performance' = @{ values = @('on'); desc = 'High performance plan + no sleep/hibernate + USB/PCI power tweaks' }
		'power.plan' = @{ values = @('high_performance','balanced','power_saver'); desc = 'Activate a built-in power scheme' }
		'boot.f8_legacy' = @{ values = @('on','off'); desc = 'bcdedit BOOTMENUPOLICY LEGACY/STANDARD' }
		'network.discovery' = @{ values = @('on','off'); desc = 'Firewall rule group Network Discovery' }
		'network.file_sharing' = @{ values = @('on','off'); desc = 'Firewall rule group File and Printer Sharing' }
		'timezone' = @{ values = @('<tzutil id>'); desc = 'tzutil /s e.g. Eastern Standard Time' }
		'time.sync' = @{ values = @('now'); desc = 'Resync Windows Time (w32tm)' }
		'bitlocker.off' = @{ values = @('off'); desc = 'manage-bde -off on drive (Device Encryption)' }
		'edge.web_widget' = @{ values = @('off','on'); desc = 'Edge WebWidgetAllowed policy' }
		'registry.periodic_backup' = @{ values = @('on','off'); desc = 'EnablePeriodicBackup for reg backups' }
		'cleanmgr.autoclean' = @{ values = @('run'); desc = 'CLEANMGR /Autoclean on drive' }
	}
}

function Invoke-ListWindowsOptions {
	$cat = Get-MBWindowsOptionCatalog
	$rows = @()
	foreach ($k in @($cat.Keys)) {
		$rows += [ordered]@{
			option = $k
			values = @($cat[$k].values)
			desc   = [string]$cat[$k].desc
		}
	}
	return ConvertTo-MBJson ([ordered]@{ ok = $true; options = $rows }) -Depth 6
}

function ConvertTo-MBProcessArgumentString {
	# One Args element = raw line; multi = quote tokens that need it.
	# Quote UNC / backslash paths so CreateProcess does not mangle \\server (net view help text bug).
	param([string[]]$ArgumentList)
	if ($null -eq $ArgumentList -or $ArgumentList.Count -eq 0) { return '' }
	if ($ArgumentList.Count -eq 1) { return [string]$ArgumentList[0] }
	$parts = New-Object System.Collections.ArrayList
	foreach ($a in $ArgumentList) {
		$s = if ($null -eq $a) { '' } else { [string]$a }
		$needQuote = $false
		if ($s -match '[\s"]') { $needQuote = $true }
		elseif ($s.StartsWith('\') -or $s.Contains('\')) { $needQuote = $true }
		if ($needQuote) {
			$s = '"' + ($s -replace '"', '""') + '"'
		}
		[void]$parts.Add($s)
	}
	return (($parts | ForEach-Object { $_ }) -join ' ')
}

function Get-MBPackageInstallArgs {
	param($Package)
	if (-not $Package) { return '' }
	try {
		if ($null -ne $Package.install) { return [string]$Package.install }
	} catch {}
	try {
		if ($null -ne $Package.args) { return [string]$Package.args }
	} catch {}
	return ''
}

function Test-MBPackageInteractive {
	param($Package)
	if (-not $Package) { return $false }
	try {
		if ($null -ne $Package.interactive) { return [bool]$Package.interactive }
	} catch {}
	try {
		if ($Package.runs_scan) { return $true }
	} catch {}
	try {
		if ([string]$Package.id -eq 'adwcleaner') { return $true }
	} catch {}
	return $false
}

function Invoke-MBSetupStartWait {
	# Wait for installer exit; no IO redirect. -Interactive = visible UI.
	param(
		[Parameter(Mandatory)]
		[string]$FilePath,
		[string]$InstallArgs = '',
		[int]$TimeoutSec = 1200,
		[switch]$Interactive
	)
	if ([string]::IsNullOrWhiteSpace($FilePath)) {
		return @{ ok = $false; exit = -1; out = ''; err = 'path required'; cmd = '' }
	}
	if (-not (Test-Path -LiteralPath $FilePath)) {
		return @{ ok = $false; exit = -1; out = ''; err = "missing: $FilePath"; cmd = '' }
	}
	if ($TimeoutSec -lt 1) { $TimeoutSec = 1 }
	$fp = ([string]$FilePath).Trim().Trim('"')
	$tail = ([string]$InstallArgs)
	if ($null -eq $tail) { $tail = '' }
	$tail = $tail.Trim()

	$isMsi = ($fp -match '(?i)\.msi$')
	$psi = New-Object System.Diagnostics.ProcessStartInfo
	if ($Interactive) {
		$psi.UseShellExecute = $true
		$psi.RedirectStandardOutput = $false
		$psi.RedirectStandardError = $false
		$psi.CreateNoWindow = $false
		$psi.WindowStyle = [System.Diagnostics.ProcessWindowStyle]::Normal
	} else {
		$psi.UseShellExecute = $false
		$psi.RedirectStandardOutput = $false
		$psi.RedirectStandardError = $false
		$psi.CreateNoWindow = $true
	}
	try { $psi.WorkingDirectory = [System.IO.Path]::GetDirectoryName($fp) } catch {}

	if ($isMsi) {
		$psi.FileName = 'msiexec.exe'
		$argLine = '/i "' + $fp + '"'
		if ($tail.Length -gt 0) { $argLine = $argLine + ' ' + $tail }
		$psi.Arguments = $argLine
	} else {
		$psi.FileName = $fp
		$psi.Arguments = $tail
	}
	$cmd = ('{0} {1}' -f $psi.FileName, $psi.Arguments).Trim()

	$p = New-Object System.Diagnostics.Process
	$p.StartInfo = $psi
	try {
		[void]$p.Start()
	} catch {
		return @{ ok = $false; exit = -1; out = ''; err = $_.Exception.Message; cmd = $cmd }
	}
	if ($Interactive) {
		try {
			Ensure-MBConNative
			Start-Sleep -Milliseconds 400
			if (-not $p.HasExited) {
				try { [void][MiniBot.WpfNative.MBCon]::AllowSetForegroundWindow(-1) } catch {}
				try { $p.Refresh() } catch {}
				for ($i = 0; $i -lt 15 -and -not $p.HasExited; $i++) {
					$h = [IntPtr]::Zero
					try { $h = $p.MainWindowHandle } catch { $h = [IntPtr]::Zero }
					if ($h -ne [IntPtr]::Zero) {
						try { [void][MiniBot.WpfNative.MBCon]::ShowWindow($h, 9) } catch {}
						try { [void][MiniBot.WpfNative.MBCon]::BringWindowToTop($h) } catch {}
						try { [void][MiniBot.WpfNative.MBCon]::SetForegroundWindow($h) } catch {}
						break
					}
					Start-Sleep -Milliseconds 200
					try { $p.Refresh() } catch {}
				}
			}
		} catch {}
	}
	$timedOut = $false
	if (-not $p.WaitForExit($TimeoutSec * 1000)) {
		$timedOut = $true
		try { $p.Kill() } catch {}
		try { [void]$p.WaitForExit(5000) } catch {}
	}
	if ($timedOut) {
		return @{ ok = $false; exit = -1; out = ''; err = 'timeout'; cmd = $cmd }
	}
	$exit = -1
	try { $exit = $p.ExitCode } catch {}
	# 3010 reboot required; 1641 reboot initiated
	$ok = ($exit -eq 0) -or ($exit -in @(3010, 1641))
	return @{ ok = $ok; exit = $exit; out = ''; err = ''; cmd = $cmd; interactive = [bool]$Interactive }
}

function Invoke-MBSetupNative {
	# Async stdout/stderr drain (sync ReadToEnd after WaitForExit can deadlock).
	param([string]$File, [string[]]$ArgumentList, [int]$TimeoutSec = 30)
	if ($TimeoutSec -lt 1) { $TimeoutSec = 1 }
	$psi = New-Object System.Diagnostics.ProcessStartInfo
	$psi.FileName = $File
	$psi.Arguments = ConvertTo-MBProcessArgumentString -ArgumentList $ArgumentList
	$psi.UseShellExecute = $false
	$psi.RedirectStandardOutput = $true
	$psi.RedirectStandardError = $true
	$psi.CreateNoWindow = $true
	$p = New-Object System.Diagnostics.Process
	$p.StartInfo = $psi
	try {
		[void]$p.Start()
	} catch {
		return @{ ok = $false; exit = -1; out = ''; err = $_.Exception.Message }
	}
	$outTask = $p.StandardOutput.ReadToEndAsync()
	$errTask = $p.StandardError.ReadToEndAsync()
	$timedOut = $false
	if (-not $p.WaitForExit($TimeoutSec * 1000)) {
		$timedOut = $true
		try { $p.Kill() } catch {}
		try { [void]$p.WaitForExit(3000) } catch {}
	}
	try { [void]$outTask.Wait(3000) } catch {}
	try { [void]$errTask.Wait(3000) } catch {}
	$o = ''
	$e = ''
	try { if ($outTask.IsCompleted) { $o = [string]$outTask.Result } } catch {}
	try { if ($errTask.IsCompleted) { $e = [string]$errTask.Result } } catch {}
	if ($timedOut) {
		return @{ ok = $false; exit = -1; out = $o; err = $(if ($e) { "timeout; $e" } else { 'timeout' }) }
	}
	$exit = -1
	try { $exit = $p.ExitCode } catch {}
	return @{ ok = ($exit -eq 0); exit = $exit; out = $o; err = $e }
}

function Enable-MBFirewallGroup {
	param(
		[Parameter(Mandatory)]
		[string]$GroupName,
		[int]$TimeoutSec = 15
	)
	$detail = ''
	try {
		$rules = @(Get-NetFirewallRule -DisplayGroup $GroupName -ErrorAction SilentlyContinue)
		if ($rules.Count -gt 0) {
			$rules | Enable-NetFirewallRule -ErrorAction SilentlyContinue
			return @{ ok = $true; method = 'Enable-NetFirewallRule'; group = $GroupName; rules = $rules.Count }
		}
		$detail = 'no rules for DisplayGroup'
	} catch {
		$detail = $_.Exception.Message
	}
	$arg = 'advfirewall firewall set rule group="{0}" new enable=Yes' -f $GroupName
	$r = Invoke-MBSetupNative -File 'netsh.exe' -ArgumentList @($arg) -TimeoutSec $TimeoutSec
	return @{
		ok     = $true
		method = 'netsh'
		group  = $GroupName
		exit   = $r.exit
		detail = $(if ($r.ok) { 'enabled' } elseif ($r.err) { [string]$r.err } else { $detail })
	}
}

function Get-MBWindowsOptionSnapshot {
	# Semantic before/after value for SetWindowsOption responses
	param(
		[string]$Option,
		[string]$Drive = 'C:'
	)
	$opt = ([string]$Option).Trim().ToLowerInvariant()
	try {
		switch -Regex ($opt) {
			'^explorer\.hidden_files$' {
				$v = $null
				try { $v = (Get-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name Hidden -ErrorAction SilentlyContinue).Hidden } catch {}
				if ($v -eq 1) { return 'show' }
				if ($v -eq 2) { return 'hide' }
				return $v
			}
			'^explorer\.file_extensions$' {
				$v = $null
				try { $v = (Get-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name HideFileExt -ErrorAction SilentlyContinue).HideFileExt } catch {}
				if ($v -eq 0) { return 'show' }
				if ($v -eq 1) { return 'hide' }
				return $v
			}
			'^explorer\.compact_mode$' {
				$v = $null
				try { $v = (Get-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name UseCompactMode -ErrorAction SilentlyContinue).UseCompactMode } catch {}
				if ($v -eq 1) { return 'on' }
				if ($v -eq 0) { return 'off' }
				return $v
			}
			'^explorer\.classic_context_menu$' {
				$p = 'HKCU:\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32'
				if (Test-Path -LiteralPath $p) { return 'on' }
				return 'off'
			}
			'^uac$' {
				$v = $null
				try { $v = (Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -Name EnableLUA -ErrorAction SilentlyContinue).EnableLUA } catch {}
				if ($v -eq 1) { return 'enable' }
				if ($v -eq 0) { return 'disable' }
				return $v
			}
			'^power\.plan$' {
				$r = Invoke-MBSetupNative -File 'powercfg.exe' -ArgumentList @('/getactivescheme') -TimeoutSec 10
				$blob = (([string]$r.out) + ' ' + ([string]$r.err))
				if ($blob -match '(?i)8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c') { return 'high_performance' }
				if ($blob -match '(?i)381b4222-f694-41f0-9685-ff5bb260df2e') { return 'balanced' }
				if ($blob -match '(?i)a1841308-3541-4fab-bc81-f71556f20b4a') { return 'power_saver' }
				return $(if ($blob.Trim()) { $blob.Trim().Substring(0, [math]::Min(120, $blob.Trim().Length)) } else { $null })
			}
			'^timezone$' {
				$r = Invoke-MBSetupNative -File 'tzutil.exe' -ArgumentList @('/g') -TimeoutSec 10
				return ([string]$r.out).Trim()
			}
			'^boot\.f8_legacy$' {
				$r = Invoke-MBSetupNative -File 'bcdedit.exe' -ArgumentList @('/enum', '{default}') -TimeoutSec 15
				$blob = ([string]$r.out)
				if ($blob -match '(?i)bootmenupolicy\s+Legacy') { return 'on' }
				if ($blob -match '(?i)bootmenupolicy\s+Standard') { return 'off' }
				return $null
			}
			default { return $null }
		}
	} catch { return $null }
}

function Format-MBSetWindowsOptionResult {
	param(
		[hashtable]$Body,
		$Before = $null,
		$After = $null
	)
	if ($null -eq $Body) { $Body = @{} }
	$ord = [ordered]@{}
	foreach ($k in @($Body.Keys)) { $ord[$k] = $Body[$k] }
	if (-not $ord.Contains('ok')) { $ord['ok'] = $true }
	$ord['before'] = $Before
	if ($null -eq $After) {
		if ($ord.Contains('value')) { $After = $ord['value'] }
		elseif ($ord.Contains('applied')) { $After = $ord['applied'] }
	}
	$ord['after'] = $After
	$b = if ($null -eq $Before) { '' } else { [string]$Before }
	$a = if ($null -eq $After) { '' } else { [string]$After }
	$ord['changed'] = ($b -ne $a)
	return ConvertTo-MBJson $ord -Depth 8
}

function Invoke-SetWindowsOption {
	param(
		[string]$option,
		[string]$value,
		[string]$drive = 'C:'
	)
	if ([string]::IsNullOrWhiteSpace($option)) { return "ERROR: option is required. Call ListWindowsOptions." }
	if ($null -eq $value) { $value = '' }
	$opt = $option.Trim().ToLowerInvariant()
	$val = ([string]$value).Trim()
	$valL = $val.ToLowerInvariant()
	$drv = ([string]$drive).Trim()
	if ([string]::IsNullOrWhiteSpace($drv)) { $drv = 'C:' }
	if ($drv -notmatch ':$') { $drv = $drv + ':' }

	$cat = Get-MBWindowsOptionCatalog
	if (-not $cat.Contains($opt) -and $opt -ne 'timezone') {
		if (-not $cat.Contains($opt)) {
			return "ERROR: Unknown option '$option'. Call ListWindowsOptions."
		}
	}

	$details = "SetWindowsOption`n  option = $opt`n  value  = $val`n  drive  = $drv"
	if (-not (Request-Confirmation -Title "SetWindowsOption requires approval" -Details $details)) {
		return "BLOCKED BY USER: SetWindowsOption denied."
	}

	$before = $null
	try { $before = Get-MBWindowsOptionSnapshot -Option $opt -Drive $drv } catch { $before = $null }

	try {
		switch -Regex ($opt) {
			'^explorer\.hidden_files$' {
				$d = if ($valL -in @('show','on','1','true')) { 1 } elseif ($valL -in @('hide','off','0','false')) { 2 } else { return "ERROR: value show|hide" }
				reg.exe add 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v Hidden /t REG_DWORD /d $d /f | Out-Null
				$after = Get-MBWindowsOptionSnapshot -Option $opt -Drive $drv
				return (Format-MBSetWindowsOptionResult -Body @{ ok = $true; option = $opt; value = $valL; applied = $d } -Before $before -After $after)
			}
			'^explorer\.file_extensions$' {
				$d = if ($valL -in @('show','on','1','true')) { 0 } elseif ($valL -in @('hide','off','0','false')) { 1 } else { return "ERROR: value show|hide" }
				reg.exe add 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v HideFileExt /t REG_DWORD /d $d /f | Out-Null
				$after = Get-MBWindowsOptionSnapshot -Option $opt -Drive $drv
				return (Format-MBSetWindowsOptionResult -Body @{ ok = $true; option = $opt; value = $valL; applied = $d } -Before $before -After $after)
			}
			'^explorer\.compact_mode$' {
				$d = if ($valL -in @('on','1','true','enable')) { 1 } elseif ($valL -in @('off','0','false','disable')) { 0 } else { return "ERROR: value on|off" }
				reg.exe add 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v UseCompactMode /t REG_DWORD /d $d /f | Out-Null
				$after = Get-MBWindowsOptionSnapshot -Option $opt -Drive $drv
				return (Format-MBSetWindowsOptionResult -Body @{ ok = $true; option = $opt; value = $valL } -Before $before -After $after)
			}
			'^explorer\.classic_context_menu$' {
				$key = 'HKCU\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32'
				if ($valL -in @('on','1','true','enable')) {
					reg.exe add $key /f /ve /d '' | Out-Null
				} elseif ($valL -in @('off','0','false','disable')) {
					reg.exe delete 'HKCU\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}' /f 2>$null | Out-Null
				} else { return "ERROR: value on|off" }
				$after = Get-MBWindowsOptionSnapshot -Option $opt -Drive $drv
				return (Format-MBSetWindowsOptionResult -Body @{ ok = $true; option = $opt; value = $valL; note = 'Explorer restart may be required' } -Before $before -After $after)
			}
			'^uac$' {
				$d = if ($valL -in @('enable','on','1','true')) { 1 } elseif ($valL -in @('disable','off','0','false')) { 0 } else { return "ERROR: value enable|disable" }
				reg.exe add 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' /v EnableLUA /t REG_DWORD /d $d /f | Out-Null
				$after = Get-MBWindowsOptionSnapshot -Option $opt -Drive $drv
				return (Format-MBSetWindowsOptionResult -Body @{ ok = $true; option = $opt; value = $valL; note = 'Reboot may be required for UAC change' } -Before $before -After $after)
			}
			'^power\.plan$' {
				$map = @{
					'high_performance' = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'
					'balanced'         = '381b4222-f694-41f0-9685-ff5bb260df2e'
					'power_saver'      = 'a1841308-3541-4fab-bc81-f71556f20b4a'
				}
				if (-not $map.ContainsKey($valL)) { return "ERROR: value high_performance|balanced|power_saver" }
				$r = Invoke-MBSetupNative -File 'powercfg.exe' -ArgumentList @('/setactive', $map[$valL])
				$after = Get-MBWindowsOptionSnapshot -Option $opt -Drive $drv
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $r.ok; option = $opt; value = $valL; exit = $r.exit; out = $r.out; err = $r.err }) -Before $before -After $after)
			}
			'^power\.max_performance$' {
				$cmds = @(
					@('/change','monitor-timeout-ac','0'),
					@('/change','monitor-timeout-dc','0'),
					@('/change','standby-timeout-ac','0'),
					@('/change','standby-timeout-dc','0'),
					@('/change','hibernate-timeout-ac','0'),
					@('/change','hibernate-timeout-dc','0'),
					@('/hibernate','off'),
					@('/setACvalueIndex','scheme_current','sub_buttons','lidAction','0'),
					@('/setDCvalueIndex','scheme_current','sub_buttons','lidAction','0'),
					@('/setACvalueindex','scheme_current','sub_pciexpress','ASPM','0'),
					@('/setDCvalueindex','scheme_current','sub_pciexpress','ASPM','0'),
					@('/setACvalueindex','scheme_current','2a737441-1930-4402-8d77-b2bebba308a3','48e6b7a6-50f5-4782-a5d4-53bb8f07e226','0'),
					@('/setDCvalueindex','scheme_current','2a737441-1930-4402-8d77-b2bebba308a3','48e6b7a6-50f5-4782-a5d4-53bb8f07e226','0'),
					@('/setactive','scheme_current')
				)
				$null = Invoke-MBSetupNative -File 'powercfg.exe' -ArgumentList @('/setactive','8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c')
				$steps = @()
				foreach ($c in $cmds) {
					$r = Invoke-MBSetupNative -File 'powercfg.exe' -ArgumentList $c
					$steps += [ordered]@{ args = ($c -join ' '); ok = $r.ok; exit = $r.exit }
				}
				$after = Get-MBWindowsOptionSnapshot -Option 'power.plan' -Drive $drv
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $true; option = $opt; value = 'on'; steps = $steps }) -Before $before -After $after)
			}
			'^boot\.f8_legacy$' {
				$pol = if ($valL -in @('on','1','true','legacy','enable')) { 'LEGACY' } elseif ($valL -in @('off','0','false','standard','disable')) { 'STANDARD' } else { return "ERROR: value on|off" }
				$r = Invoke-MBSetupNative -File 'bcdedit.exe' -ArgumentList @('/set','{default}','bootmenupolicy', $pol)
				$after = Get-MBWindowsOptionSnapshot -Option $opt -Drive $drv
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $r.ok; option = $opt; value = $(if ($pol -eq 'LEGACY') { 'on' } else { 'off' }); exit = $r.exit; out = $r.out; err = $r.err }) -Before $before -After $after)
			}
			'^network\.discovery$' {
				$en = if ($valL -in @('on','1','true','enable','yes')) { 'Yes' } elseif ($valL -in @('off','0','false','disable','no')) { 'No' } else { return "ERROR: value on|off" }
				if ($en -eq 'Yes') {
					$r = Enable-MBFirewallGroup -GroupName 'Network Discovery' -TimeoutSec 15
					return (Format-MBSetWindowsOptionResult -Body (@{ ok = $true; option = $opt; value = 'on'; method = $r.method; detail = $r.detail }) -Before $before -After 'on')
				}
				$arg = 'advfirewall firewall set rule group="Network Discovery" new enable=No'
				$r = Invoke-MBSetupNative -File 'netsh.exe' -ArgumentList @($arg) -TimeoutSec 15
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $r.ok; option = $opt; value = 'off'; exit = $r.exit; out = $r.out; err = $r.err }) -Before $before -After 'off')
			}
			'^network\.file_sharing$' {
				$en = if ($valL -in @('on','1','true','enable','yes')) { 'Yes' } elseif ($valL -in @('off','0','false','disable','no')) { 'No' } else { return "ERROR: value on|off" }
				if ($en -eq 'Yes') {
					$r = Enable-MBFirewallGroup -GroupName 'File and Printer Sharing' -TimeoutSec 15
					return (Format-MBSetWindowsOptionResult -Body (@{ ok = $true; option = $opt; value = 'on'; method = $r.method; detail = $r.detail }) -Before $before -After 'on')
				}
				$arg = 'advfirewall firewall set rule group="File and Printer Sharing" new enable=No'
				$r = Invoke-MBSetupNative -File 'netsh.exe' -ArgumentList @($arg) -TimeoutSec 15
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $r.ok; option = $opt; value = 'off'; exit = $r.exit; out = $r.out; err = $r.err }) -Before $before -After 'off')
			}
			'^timezone$' {
				if ([string]::IsNullOrWhiteSpace($val)) { return "ERROR: value must be a tzutil id (e.g. Eastern Standard Time)" }
				$r = Invoke-MBSetupNative -File 'tzutil.exe' -ArgumentList @('/s', $val)
				$after = Get-MBWindowsOptionSnapshot -Option $opt -Drive $drv
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $r.ok; option = $opt; value = $val; exit = $r.exit; out = $r.out; err = $r.err }) -Before $before -After $after)
			}
			'^time\.sync$' {
				$null = Invoke-MBSetupNative -File 'w32tm.exe' -ArgumentList @('/config','/manualpeerlist:time.windows.com')
				$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('stop','w32time')
				reg.exe add 'HKLM\SYSTEM\CurrentControlSet\Services\W32Time\Parameters' /v Type /t REG_SZ /d NTP /f | Out-Null
				$null = Invoke-MBSetupNative -File 'sc.exe' -ArgumentList @('config','w32time','start=','demand')
				$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('start','w32time')
				$r = Invoke-MBSetupNative -File 'w32tm.exe' -ArgumentList @('/resync')
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $r.ok; option = $opt; value = 'now'; exit = $r.exit; out = $r.out; err = $r.err }) -Before $before -After 'now')
			}
			'^bitlocker\.off$' {
				$r = Invoke-MBSetupNative -File 'manage-bde.exe' -ArgumentList @('-off', $drv) -TimeoutSec 300
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $r.ok; option = $opt; value = 'off'; drive = $drv; exit = $r.exit; out = $r.out; err = $r.err }) -Before $before -After 'off')
			}
			'^edge\.web_widget$' {
				$d = if ($valL -in @('off','0','false','disable')) { 0 } elseif ($valL -in @('on','1','true','enable')) { 1 } else { return "ERROR: value on|off" }
				reg.exe add 'HKLM\SOFTWARE\Policies\Microsoft\Edge' /v WebWidgetAllowed /t REG_DWORD /d $d /f | Out-Null
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $true; option = $opt; value = $valL }) -Before $before -After $valL)
			}
			'^registry\.periodic_backup$' {
				$d = if ($valL -in @('on','1','true','enable')) { 1 } elseif ($valL -in @('off','0','false','disable')) { 0 } else { return "ERROR: value on|off" }
				reg.exe add 'HKLM\SYSTEM\ControlSet001\Control\Session Manager\Configuration Manager' /v EnablePeriodicBackup /t REG_DWORD /d $d /f | Out-Null
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $true; option = $opt; value = $valL }) -Before $before -After $valL)
			}
			'^cleanmgr\.autoclean$' {
				$letter = $drv.TrimEnd(':')
				$r = Invoke-MBSetupNative -File 'cleanmgr.exe' -ArgumentList @("/d",$letter,'/Autoclean') -TimeoutSec 600
				return (Format-MBSetWindowsOptionResult -Body (@{ ok = $r.ok; option = $opt; value = 'run'; drive = $drv; exit = $r.exit }) -Before $before -After 'run')
			}
			default { return "ERROR: Unhandled option '$opt'." }
		}
	} catch {
		return "ERROR: SetWindowsOption failed: $($_.Exception.Message)"
	}
}

# --- Local Group Policy (registry-based Policies keys; not domain RSAT GPO editor) ---
function Get-MBGroupPolicyCatalog {
	# Common Administrative Template-style settings via Policies registry.
	# path = relative under SOFTWARE\Policies or full hive path; value name; type; on/off or free values.
	return [ordered]@{
		'windows.update.no_auto_update' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU'; name = 'NoAutoUpdate'
			type = 'DWord'; values = @('0','1'); desc = '1=disable automatic updates via policy; 0=allow'
		}
		'windows.update.au_options' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU'; name = 'AUOptions'
			type = 'DWord'; values = @('2','3','4','5'); desc = '2=notify 3=auto DL notify install 4=auto DL schedule 5=local admin choice'
		}
		'explorer.no_control_panel' = @{
			scope = 'user'; path = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer'; name = 'NoControlPanel'
			type = 'DWord'; values = @('0','1'); desc = '1=prohibit Control Panel access'
		}
		'explorer.no_run' = @{
			scope = 'user'; path = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer'; name = 'NoRun'
			type = 'DWord'; values = @('0','1'); desc = '1=remove Run from Start menu'
		}
		'explorer.disable_taskmgr' = @{
			scope = 'user'; path = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'; name = 'DisableTaskMgr'
			type = 'DWord'; values = @('0','1'); desc = '1=disable Task Manager'
		}
		'explorer.disable_cmd' = @{
			scope = 'user'; path = 'HKCU:\SOFTWARE\Policies\Microsoft\Windows\System'; name = 'DisableCMD'
			type = 'DWord'; values = @('0','1','2'); desc = '1=disable cmd 2=disable cmd+scripts 0=allow'
		}
		'system.disable_registry_tools' = @{
			scope = 'user'; path = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'; name = 'DisableRegistryTools'
			type = 'DWord'; values = @('0','1'); desc = '1=disable regedit (dangerous; hard to undo without policy remove)'
		}
		'system.legal_notice_caption' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'; name = 'LegalNoticeCaption'
			type = 'String'; values = @('<text>'); desc = 'Logon legal notice title'
		}
		'system.legal_notice_text' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'; name = 'LegalNoticeText'
			type = 'String'; values = @('<text>'); desc = 'Logon legal notice body'
		}
		'system.dontdisplaylastusername' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'; name = 'DontDisplayLastUserName'
			type = 'DWord'; values = @('0','1'); desc = '1=do not display last signed-in user at logon'
		}
		'system.inactivity_timeout_secs' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'; name = 'InactivityTimeoutSecs'
			type = 'DWord'; values = @('<seconds>'); desc = 'Interactive logon machine inactivity limit (seconds)'
		}
		'cloudcontent.disable_windows_consumer' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent'; name = 'DisableWindowsConsumerFeatures'
			type = 'DWord'; values = @('0','1'); desc = '1=turn off Microsoft consumer experiences'
		}
		'cloudcontent.disable_softlanding' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent'; name = 'DisableSoftLanding'
			type = 'DWord'; values = @('0','1'); desc = '1=disable Windows tips / soft landing'
		}
		'search.allow_cortana' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search'; name = 'AllowCortana'
			type = 'DWord'; values = @('0','1'); desc = '0=disable Cortana; 1=allow'
		}
		'search.disable_web_search' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search'; name = 'DisableWebSearch'
			type = 'DWord'; values = @('0','1'); desc = '1=disable web search from Start/search'
		}
		'search.connected_search_safe' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search'; name = 'ConnectedSearchUseWeb'
			type = 'DWord'; values = @('0','1'); desc = '0=don''t search the web; 1=allow'
		}
		'store.removepush' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsStore'; name = 'DisableStoreApps'
			type = 'DWord'; values = @('0','1'); desc = '1=turn off Store application (policy)'
		}
		'store.disable_os_upgrade' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsStore'; name = 'DisableOSUpgrade'
			type = 'DWord'; values = @('0','1'); desc = '1=block Store OS upgrade offers'
		}
		'edge.hide_first_run' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Edge'; name = 'HideFirstRunExperience'
			type = 'DWord'; values = @('0','1'); desc = '1=hide Edge first-run experience'
		}
		'chrome.homepage' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Google\Chrome'; name = 'HomepageLocation'
			type = 'String'; values = @('<url>'); desc = 'Chrome homepage URL (requires Chrome policy support)'
		}
		'password.minimum_length' = @{
			scope = 'machine'; path = 'HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters'; name = ''
			type = 'note'; values = @(); desc = 'Use action=export_security / domain policy; local password length is via secedit not this reg path'
		}
		'removable.deny_all' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\RemovableStorageDevices'; name = 'Deny_All'
			type = 'DWord'; values = @('0','1'); desc = '1=deny all removable storage (strong lock-down)'
		}
		'powershell.execution_policy' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell'; name = 'ExecutionPolicy'
			type = 'String'; values = @('Restricted','RemoteSigned','AllSigned','Unrestricted','Bypass'); desc = 'Machine PowerShell execution policy via GPO'
		}
		'powershell.script_block_logging' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging'; name = 'EnableScriptBlockLogging'
			type = 'DWord'; values = @('0','1'); desc = '1=enable PowerShell script block logging'
		}
		'defender.disable_antispyware' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender'; name = 'DisableAntiSpyware'
			type = 'DWord'; values = @('0','1'); desc = '1=disable Defender anti-spyware policy (not recommended)'
		}
		'telemetry.allow_telemetry' = @{
			scope = 'machine'; path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection'; name = 'AllowTelemetry'
			type = 'DWord'; values = @('0','1','2','3'); desc = '0=Security 1=Basic 2=Enhanced 3=Full (edition-limited)'
		}
	}
}

function Test-MBGroupPolicyPathAllowed {
	param([string]$Path)
	if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
	$p = $Path.Trim()
	# Only policy hives / well-known policy branches (prevents arbitrary registry as "GPO")
	if ($p -match '(?i)^(HKLM|HKCU|HKEY_LOCAL_MACHINE|HKEY_CURRENT_USER):\\SOFTWARE\\Policies\\') { return $true }
	if ($p -match '(?i)^(HKLM|HKCU|HKEY_LOCAL_MACHINE|HKEY_CURRENT_USER):\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\') { return $true }
	if ($p -match '(?i)^(HKLM|HKEY_LOCAL_MACHINE):\\SOFTWARE\\Microsoft\\Windows Defender\\') { return $true }
	if ($p -match '(?i)^(HKLM|HKEY_LOCAL_MACHINE):\\SOFTWARE\\Policies\\') { return $true }
	return $false
}

function ConvertTo-MBGroupPolicyRegPath {
	param([string]$Path)
	$p = ([string]$Path).Trim()
	if ([string]::IsNullOrWhiteSpace($p)) { return $null }
	$p = $p -replace '(?i)^HKEY_LOCAL_MACHINE\\', 'HKLM:\'
	$p = $p -replace '(?i)^HKEY_CURRENT_USER\\', 'HKCU:\'
	$p = $p -replace '(?i)^HKLM\\', 'HKLM:\'
	$p = $p -replace '(?i)^HKCU\\', 'HKCU:\'
	if ($p -notmatch '^(?i)(HKLM|HKCU):') {
		# Bare relative under Policies
		if ($p -match '(?i)^SOFTWARE\\') {
			$p = 'HKLM:\' + $p
		} else {
			$p = 'HKLM:\SOFTWARE\Policies\' + $p.TrimStart('\')
		}
	}
	return $p
}

function Get-MBGroupPolicyResolvedTarget {
	param(
		[string]$Key = '',
		[string]$Path = '',
		[string]$Name = '',
		[string]$Type = '',
		[string]$Scope = ''
	)
	$cat = Get-MBGroupPolicyCatalog
	if (-not [string]::IsNullOrWhiteSpace($Key)) {
		$k = $Key.Trim()
		if (-not $cat.Contains($k)) {
			# fuzzy
			$hit = $null
			foreach ($ck in @($cat.Keys)) {
				if ($ck -like "*$k*" -or $k -like "*$ck*") { $hit = $ck; break }
			}
			if (-not $hit) {
				return @{ ok = $false; error = "Unknown catalog key '$Key'. action=list_catalog for keys." }
			}
			$k = $hit
		}
		$e = $cat[$k]
		if ([string]$e.type -eq 'note') {
			return @{ ok = $false; error = "Catalog key '$k' is informational only: $($e.desc)" }
		}
		return @{
			ok    = $true
			key   = $k
			path  = [string]$e.path
			name  = [string]$e.name
			type  = [string]$e.type
			scope = [string]$e.scope
			desc  = [string]$e.desc
		}
	}
	$regPath = ConvertTo-MBGroupPolicyRegPath -Path $Path
	if (-not $regPath) {
		return @{ ok = $false; error = 'path= or key= required.' }
	}
	if (-not (Test-MBGroupPolicyPathAllowed -Path $regPath)) {
		return @{
			ok = $false
			error = "Path not allowed for GroupPolicy. Only SOFTWARE\\Policies\\... and SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\... (got $regPath)"
		}
	}
	$t = if ([string]::IsNullOrWhiteSpace($Type)) { 'DWord' } else { $Type.Trim() }
	return @{
		ok    = $true
		key   = $null
		path  = $regPath
		name  = [string]$Name
		type  = $t
		scope = $(if ($Scope) { $Scope } else { 'custom' })
		desc  = ''
	}
}

function Convert-MBGroupPolicyRegValue {
	param(
		[string]$Type,
		$value
	)
	$t = ([string]$Type).Trim().ToLowerInvariant() -replace '[\s_-]', ''
	switch -Regex ($t) {
		'^(dword|int|int32)$' {
			$n = 0
			if ($value -is [bool]) { return $(if ($value) { 1 } else { 0 }) }
			if (-not [int]::TryParse([string]$value, [ref]$n)) {
				if ([string]$value -match '^(?i)true|on|yes|enable') { return 1 }
				if ([string]$value -match '^(?i)false|off|no|disable') { return 0 }
				throw "Cannot parse DWord value: $value"
			}
			return [int]$n
		}
		'^(qword|int64)$' {
			$n = [int64]0
			if (-not [int64]::TryParse([string]$value, [ref]$n)) { throw "Cannot parse QWord: $value" }
			return [int64]$n
		}
		'^(string|sz|reg_sz)$' { return [string]$value }
		'^(expandstring|expand_sz)$' { return [string]$value }
		'^(multistring|multi_sz)$' {
			if ($value -is [System.Array]) { return @($value | ForEach-Object { [string]$_ }) }
			return @(([string]$value) -split '[;\r\n]+' | Where-Object { $_ })
		}
		default { throw "Unsupported type '$Type' (use DWord|String|ExpandString|MultiString|QWord)." }
	}
}

function Get-MBGroupPolicyRegTypeName {
	param([string]$Type)
	$t = ([string]$Type).Trim().ToLowerInvariant() -replace '[\s_-]', ''
	switch -Regex ($t) {
		'^(dword|int|int32)$' { return 'DWord' }
		'^(qword|int64)$' { return 'QWord' }
		'^(expandstring|expand_sz)$' { return 'ExpandString' }
		'^(multistring|multi_sz)$' { return 'MultiString' }
		default { return 'String' }
	}
}

function Invoke-GroupPolicy {
	param(
		[string]$action = 'status',
		[string]$key = '',
		[string]$path = '',
		[string]$name = '',
		$value = $null,
		[string]$type = 'DWord',
		[string]$scope = '',
		[string]$pattern = '',
		[int]$max = 80,
		[object]$gpupdate = $false
	)
	$a = ([string]$action).Trim().ToLowerInvariant()
	if ([string]::IsNullOrWhiteSpace($a)) { $a = 'status' }
	if ($max -le 0) { $max = 80 }
	if ($max -gt 300) { $max = 300 }
	$doGpu = $false
	if ($gpupdate -is [bool]) { $doGpu = $gpupdate }
	elseif ([string]$gpupdate -match '^(?i)1|true|yes|y|on$') { $doGpu = $true }

	$editionOk = $true
	try { $editionOk = [bool](Test-MBWindowsHasLocalGroupPolicy) } catch { $editionOk = $true }
	$editionWhy = ''
	try { $editionWhy = Get-MBGroupPolicyUnavailableReason } catch { $editionWhy = '' }
	$edSnap = $null
	try { $edSnap = Get-MBWindowsEditionSnapshot } catch { $edSnap = $null }

	# Mutating / deep actions blocked on Home/Core (UI paints tool orange). status still works.
	if (-not $editionOk -and $a -notmatch '^(status|info)$') {
		return ConvertTo-MBJson ([ordered]@{
			ok                    = $false
			supported             = $false
			unavailable           = $true
			action                = $a
			error                 = $(if ($editionWhy) { $editionWhy } else { 'Local Group Policy not available on this Windows edition (Home/Core).' })
			edition_id            = $(if ($edSnap) { $edSnap.EditionID } else { $null })
			product_name          = $(if ($edSnap) { $edSnap.ProductName } else { $null })
			caption               = $(if ($edSnap) { $edSnap.Caption } else { $null })
			gpedit_msc            = $(if ($edSnap) { [bool]$edSnap.GpeditMsc } else { $false })
			note                  = 'GroupPolicy requires Windows Pro or higher (Local Group Policy / gpedit). Tool stays listed but is unavailable (orange) on Home/Core.'
		}) -Depth 5
	}

	try {
		switch -Regex ($a) {
			'^(status|info)$' {
				$domain = $null
				$partOfDomain = $false
				try {
					$cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
					if ($cs) {
						$partOfDomain = [bool]$cs.PartOfDomain
						$domain = [string]$cs.Domain
					}
				} catch {}
				$gpedit = $false
				try {
					if ($edSnap) { $gpedit = [bool]$edSnap.GpeditMsc }
					else {
						$gp = Join-Path $env:SystemRoot 'System32\gpedit.msc'
						$gpedit = Test-Path -LiteralPath $gp
					}
				} catch {}
				$polRoots = @(
					'HKLM:\SOFTWARE\Policies',
					'HKCU:\SOFTWARE\Policies',
					'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies',
					'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies'
				)
				$counts = @{}
				if ($editionOk) {
					foreach ($r in $polRoots) {
						$n = 0
						try {
							if (Test-Path -LiteralPath $r) {
								$n = @(Get-ChildItem -LiteralPath $r -Recurse -ErrorAction SilentlyContinue | Select-Object -First 500).Count
							}
						} catch { $n = -1 }
						$counts[$r] = $n
					}
				}
				return ConvertTo-MBJson ([ordered]@{
					ok              = $true
					action          = 'status'
					supported       = [bool]$editionOk
					unavailable     = (-not $editionOk)
					unavailable_reason = $(if (-not $editionOk) { $editionWhy } else { $null })
					computer        = $env:COMPUTERNAME
					part_of_domain  = $partOfDomain
					domain          = $domain
					edition_id      = $(if ($edSnap) { $edSnap.EditionID } else { $null })
					product_name    = $(if ($edSnap) { $edSnap.ProductName } else { $null })
					caption         = $(if ($edSnap) { $edSnap.Caption } else { $null })
					gpedit_msc      = $gpedit
					note            = $(if ($editionOk) {
						'Local registry Policies editor (Administrative Template-style). Not RSAT domain GPO. Mutates write under Policies keys + optional gpupdate.'
					} else {
						'Local Group Policy editor not available on this edition (typically Windows Home/Core). Upgrade to Pro+ for gpedit / full GPO support. Tool shows orange in the UI when unsupported.'
					})
					policy_tree_sample_counts = $counts
					actions         = @('status','list_catalog','get','set','remove','list_key','search','gpupdate','export_security')
				}) -Depth 6
			}
			'^(list_catalog|catalog|list)$' {
				$cat = Get-MBGroupPolicyCatalog
				$rows = New-Object System.Collections.ArrayList
				$pat = ([string]$pattern).Trim()
				foreach ($k in @($cat.Keys)) {
					if ($pat -and ($k -notlike "*$pat*") -and ([string]$cat[$k].desc -notlike "*$pat*") -and ([string]$cat[$k].path -notlike "*$pat*")) {
						continue
					}
					[void]$rows.Add([ordered]@{
						key    = $k
						scope  = [string]$cat[$k].scope
						path   = [string]$cat[$k].path
						name   = [string]$cat[$k].name
						type   = [string]$cat[$k].type
						values = @($cat[$k].values)
						desc   = [string]$cat[$k].desc
					})
					if ($rows.Count -ge $max) { break }
				}
				return ConvertTo-MBJson ([ordered]@{
					ok      = $true
					action  = 'list_catalog'
					count   = $rows.Count
					entries = @($rows)
					hint    = 'get/set/remove with key=catalog_key OR path= + name=. set/remove ALWAYS prompt.'
				}) -Depth 6
			}
			'^(get|read)$' {
				$t = Get-MBGroupPolicyResolvedTarget -Key $key -Path $path -Name $name -Type $type -Scope $scope
				if (-not $t.ok) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; error = $t.error })
				}
				$regPath = [string]$t.path
				$valName = [string]$t.name
				if (-not (Test-Path -LiteralPath $regPath)) {
					return ConvertTo-MBJson ([ordered]@{
						ok      = $true
						exists  = $false
						key     = $t.key
						path    = $regPath
						name    = $valName
						value   = $null
						note    = 'Policy key path does not exist (policy not configured).'
					})
				}
				if ([string]::IsNullOrWhiteSpace($valName)) {
					# list value names on key
					$props = @()
					try {
						$item = Get-ItemProperty -LiteralPath $regPath -ErrorAction Stop
						foreach ($p in @($item.PSObject.Properties)) {
							if ($p.Name -match '^PS') { continue }
							$props += [ordered]@{ name = $p.Name; value = $p.Value; type = $p.TypeNameOfValue }
							if ($props.Count -ge $max) { break }
						}
					} catch {
						return ConvertTo-MBJson ([ordered]@{ ok = $false; error = $_.Exception.Message; path = $regPath })
					}
					return ConvertTo-MBJson ([ordered]@{
						ok     = $true
						exists = $true
						path   = $regPath
						values = $props
						count  = $props.Count
					}) -Depth 6
				}
				try {
					$raw = Get-ItemProperty -LiteralPath $regPath -Name $valName -ErrorAction Stop
					$v = $raw.$valName
					return ConvertTo-MBJson ([ordered]@{
						ok     = $true
						exists = $true
						key    = $t.key
						path   = $regPath
						name   = $valName
						value  = $v
						desc   = $t.desc
					}) -Depth 5
				} catch {
					return ConvertTo-MBJson ([ordered]@{
						ok     = $true
						exists = $false
						key    = $t.key
						path   = $regPath
						name   = $valName
						value  = $null
						note   = 'Value not present (not configured).'
					})
				}
			}
			'^(list_key|ls)$' {
				$regPath = ConvertTo-MBGroupPolicyRegPath -Path $(if ($path) { $path } elseif ($key) {
					$t0 = Get-MBGroupPolicyResolvedTarget -Key $key
					if ($t0.ok) { $t0.path } else { '' }
				} else { 'HKLM:\SOFTWARE\Policies' })
				if (-not $regPath) { return ConvertTo-MBJson ([ordered]@{ ok = $false; error = 'path= required' }) }
				if (-not (Test-MBGroupPolicyPathAllowed -Path $regPath)) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; error = "Path not allowed: $regPath" })
				}
				if (-not (Test-Path -LiteralPath $regPath)) {
					return ConvertTo-MBJson ([ordered]@{ ok = $true; path = $regPath; exists = $false; children = @(); values = @() })
				}
				$children = @()
				$vals = @()
				try {
					$children = @(Get-ChildItem -LiteralPath $regPath -ErrorAction SilentlyContinue |
						Select-Object -First $max |
						ForEach-Object { [ordered]@{ name = $_.PSChildName; path = $_.PSPath -replace 'Microsoft\.PowerShell\.Core\\Registry::','' } })
				} catch {}
				try {
					$item = Get-ItemProperty -LiteralPath $regPath -ErrorAction SilentlyContinue
					foreach ($p in @($item.PSObject.Properties)) {
						if ($p.Name -match '^PS') { continue }
						$vals += [ordered]@{ name = $p.Name; value = $p.Value }
						if ($vals.Count -ge $max) { break }
					}
				} catch {}
				return ConvertTo-MBJson ([ordered]@{
					ok       = $true
					path     = $regPath
					exists   = $true
					children = $children
					values   = $vals
				}) -Depth 6
			}
			'^(search)$' {
				$pat = ([string]$pattern).Trim()
				if ([string]::IsNullOrWhiteSpace($pat)) { $pat = ([string]$key).Trim() }
				if ([string]::IsNullOrWhiteSpace($pat)) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; error = 'pattern= (or key= as substring) required for search' })
				}
				# Catalog hits + shallow policy tree name match
				$cat = Get-MBGroupPolicyCatalog
				$hits = New-Object System.Collections.ArrayList
				# Support multi-token OR search: telemetry|update or "telemetry update"
				$tokens = @()
				foreach ($rawTok in @(($pat -split '[\|,;\s]+') | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
					$tokens += $rawTok.Trim()
				}
				if ($tokens.Count -eq 0) { $tokens = @($pat) }
				$matchAny = {
					param([string]$text)
					if ([string]::IsNullOrWhiteSpace($text)) { return $false }
					$tl = $text.ToLowerInvariant()
					foreach ($tk in $tokens) {
						if ($tl.Contains($tk.ToLowerInvariant())) { return $true }
					}
					return $false
				}
				foreach ($k in @($cat.Keys)) {
					$e = $cat[$k]
					$hay = (@($k, [string]$e.desc, [string]$e.path, [string]$e.name, [string]$e.scope) -join ' ')
					if (& $matchAny $hay) {
						[void]$hits.Add([ordered]@{ source = 'catalog'; key = $k; path = $e.path; name = $e.name; desc = $e.desc })
					}
					if ($hits.Count -ge $max) { break }
				}
				$roots = @(
					'HKLM:\SOFTWARE\Policies',
					'HKCU:\SOFTWARE\Policies',
					'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies',
					'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies'
				)
				foreach ($root in $roots) {
					if ($hits.Count -ge $max) { break }
					if (-not (Test-Path -LiteralPath $root)) { continue }
					try {
						Get-ChildItem -LiteralPath $root -Recurse -ErrorAction SilentlyContinue |
							Where-Object {
								$n = [string]$_.PSChildName
								$full = [string]$_.Name
								$okHit = $false
								foreach ($tk in $tokens) {
									if ($n -like "*$tk*" -or $full -like "*$tk*") { $okHit = $true; break }
								}
								$okHit
							} |
							Select-Object -First ([math]::Max(1, $max - $hits.Count)) |
							ForEach-Object {
								[void]$hits.Add([ordered]@{
									source = 'registry'
									path   = ($_.PSPath -replace 'Microsoft\.PowerShell\.Core\\Registry::','')
									name   = $_.PSChildName
								})
							}
					} catch {}
				}
				return ConvertTo-MBJson ([ordered]@{
					ok      = $true
					action  = 'search'
					pattern = $pat
					tokens  = @($tokens)
					count   = $hits.Count
					hits    = @($hits)
					note    = 'Catalog keys match any token (OR). Example: telemetry|update or windows.update'
				}) -Depth 6
			}
			'^(set|write)$' {
				$t = Get-MBGroupPolicyResolvedTarget -Key $key -Path $path -Name $name -Type $type -Scope $scope
				if (-not $t.ok) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; error = $t.error })
				}
				$regPath = [string]$t.path
				$valName = [string]$t.name
				if ([string]::IsNullOrWhiteSpace($valName)) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; error = 'name= (value name) required for set (or use catalog key= that defines name).' })
				}
				if ($null -eq $value -or ([string]$value -eq '' -and $t.type -notmatch '(?i)string')) {
					# allow empty string for String type
					if ($null -eq $value) {
						return ConvertTo-MBJson ([ordered]@{ ok = $false; error = 'value= required for set' })
					}
				}
				$regType = Get-MBGroupPolicyRegTypeName -Type $(if ($type) { $type } else { $t.type })
				try {
					$coerced = Convert-MBGroupPolicyRegValue -Type $regType -value $value
				} catch {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; error = $_.Exception.Message })
				}
				$details = @"
Local Group Policy registry set (Administrative Template-style):

  Catalog:  $(if ($t.key) { $t.key } else { '(custom path)' })
  Path:     $regPath
  Name:     $valName
  Type:     $regType
  Value:    $coerced
  Scope:    $($t.scope)
  gpupdate: $doGpu

Writes under Policies registry. Domain GPOs may override. Prefer catalog key= when possible.
"@
				if (-not (Request-Confirmation -Title "GroupPolicy set requires approval" -Details $details)) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; denied = $true; error = 'GroupPolicy set denied by operator' })
				}
				if (-not (Test-Path -LiteralPath $regPath)) {
					New-Item -Path $regPath -Force -ErrorAction Stop | Out-Null
				}
				# Remove if wrong type then set
				try {
					$existing = Get-ItemProperty -LiteralPath $regPath -Name $valName -ErrorAction SilentlyContinue
					if ($null -ne $existing) {
						Remove-ItemProperty -LiteralPath $regPath -Name $valName -Force -ErrorAction SilentlyContinue
					}
				} catch {}
				New-ItemProperty -LiteralPath $regPath -Name $valName -Value $coerced -PropertyType $regType -Force -ErrorAction Stop | Out-Null
				$after = (Get-ItemProperty -LiteralPath $regPath -Name $valName -ErrorAction Stop).$valName
				$gpuResult = $null
				if ($doGpu) {
					$gpuResult = Invoke-MBSetupNative -File 'gpupdate.exe' -ArgumentList @('/force') -TimeoutSec 120
				}
				$prefix = if ($script:MB.AutoApprove) { 'SUCCESS (auto-approved)' } else { 'SUCCESS' }
				return ConvertTo-MBJson ([ordered]@{
					ok      = $true
					message = "$prefix`: GroupPolicy set $valName"
					key     = $t.key
					path    = $regPath
					name    = $valName
					type    = $regType
					value   = $after
					gpupdate = $(if ($null -ne $gpuResult) {
						[ordered]@{ ok = $gpuResult.ok; exit = $gpuResult.exit; out = ([string]$gpuResult.out).Trim(); err = ([string]$gpuResult.err).Trim() }
					} else { $null })
					note    = 'Some policies need sign-out or reboot. Domain GPO may override local Policies keys.'
				}) -Depth 6
			}
			'^(remove|delete|clear)$' {
				$t = Get-MBGroupPolicyResolvedTarget -Key $key -Path $path -Name $name -Type $type -Scope $scope
				if (-not $t.ok) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; error = $t.error })
				}
				$regPath = [string]$t.path
				$valName = [string]$t.name
				if ([string]::IsNullOrWhiteSpace($valName)) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; error = 'name= required for remove (removes one value, not whole trees).' })
				}
				$details = "Remove Group Policy registry value:`n`n  Path: $regPath`n  Name: $valName`n  gpupdate: $doGpu"
				if (-not (Request-Confirmation -Title "GroupPolicy remove requires approval" -Details $details)) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; denied = $true; error = 'GroupPolicy remove denied by operator' })
				}
				if (-not (Test-Path -LiteralPath $regPath)) {
					return ConvertTo-MBJson ([ordered]@{ ok = $true; removed = $false; note = 'Path already absent'; path = $regPath; name = $valName })
				}
				try {
					Remove-ItemProperty -LiteralPath $regPath -Name $valName -Force -ErrorAction Stop
					$removed = $true
				} catch {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; error = $_.Exception.Message; path = $regPath; name = $valName })
				}
				$gpuResult = $null
				if ($doGpu) {
					$gpuResult = Invoke-MBSetupNative -File 'gpupdate.exe' -ArgumentList @('/force') -TimeoutSec 120
				}
				return ConvertTo-MBJson ([ordered]@{
					ok      = $true
					removed = $removed
					path    = $regPath
					name    = $valName
					gpupdate = $(if ($null -ne $gpuResult) {
						[ordered]@{ ok = $gpuResult.ok; exit = $gpuResult.exit }
					} else { $null })
				}) -Depth 5
			}
			'^(gpupdate|refresh)$' {
				$details = "Run gpupdate /force to refresh local/domain policy on this machine."
				if (-not (Request-Confirmation -Title "GroupPolicy gpupdate requires approval" -Details $details)) {
					return ConvertTo-MBJson ([ordered]@{ ok = $false; denied = $true; error = 'gpupdate denied by operator' })
				}
				$r = Invoke-MBSetupNative -File 'gpupdate.exe' -ArgumentList @('/force') -TimeoutSec 180
				$out = ([string]$r.out).Trim()
				if ($out.Length -gt 1200) { $out = $out.Substring($out.Length - 1200) }
				return ConvertTo-MBJson ([ordered]@{
					ok     = [bool]$r.ok
					action = 'gpupdate'
					exit   = $r.exit
					stdout = $out
					stderr = ([string]$r.err).Trim()
				}) -Depth 4
			}
			'^(export_security|secedit|security)$' {
				# Read-only dump of local security policy via secedit (not full gpedit)
				$tmp = Join-Path ([System.IO.Path]::GetTempPath()) ("mb-secpol-" + [guid]::NewGuid().ToString('N').Substring(0, 8) + '.inf')
				try {
					$r = Invoke-MBSetupNative -File 'secedit.exe' -ArgumentList @('/export', '/cfg', $tmp) -TimeoutSec 60
					if (-not (Test-Path -LiteralPath $tmp)) {
						return ConvertTo-MBJson ([ordered]@{
							ok = $false
							error = "secedit export failed (exit $($r.exit)). $($r.err)"
						})
					}
					$raw = [System.IO.File]::ReadAllText($tmp)
					# Cap for model context
					$cap = 12000
					$truncated = $false
					if ($raw.Length -gt $cap) {
						$raw = $raw.Substring(0, $cap) + "`n...[truncated]..."
						$truncated = $true
					}
					return ConvertTo-MBJson ([ordered]@{
						ok         = $true
						action     = 'export_security'
						exit       = $r.exit
						truncated = $truncated
						inf        = $raw
						note       = 'Local security policy export (secedit). Not the full gpedit.msc tree. Import/edit via secedit is out of band / high risk — not auto-applied.'
					}) -Depth 4
				} finally {
					try { if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } } catch {}
				}
			}
			default {
				return ConvertTo-MBJson ([ordered]@{
					ok = $false
					error = "Unknown action '$action'. Use: status|list_catalog|get|set|remove|list_key|search|gpupdate|export_security"
				})
			}
		}
	} catch {
		return ConvertTo-MBJson ([ordered]@{ ok = $false; error = $_.Exception.Message })
	}
}

function Invoke-SystemRestore {
	param(
		[string]$action,
		[string]$description = '',
		[string]$drive = 'C:'
	)
	$a = ([string]$action).Trim().ToLowerInvariant()
	if ([string]::IsNullOrWhiteSpace($a)) { return "ERROR: action required (status|enable|disable|create|list)." }
	$drv = ([string]$drive).Trim()
	if ([string]::IsNullOrWhiteSpace($drv)) { $drv = 'C:' }
	if ($drv -notmatch ':$') { $drv = $drv + ':' }

	try {
		if ($a -eq 'status' -or $a -eq 'list') {
			$pts = @()
			try {
				$pts = @(Get-ComputerRestorePoint -ErrorAction SilentlyContinue | Select-Object -First 25 SequenceNumber, Description, CreationTime, RestorePointType)
			} catch {}
			$enabled = $null
			try {
				$sr = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore' -ErrorAction SilentlyContinue
				$enabled = $sr
			} catch {}
			return ConvertTo-MBJson ([ordered]@{
				ok      = $true
				action  = $a
				drive   = $drv
				points  = $pts
			}) -Depth 5
		}
		if ($a -eq 'enable') {
			if (-not (Request-Confirmation -Title "SystemRestore requires approval" -Details "Enable System Restore on $drv")) {
				return "BLOCKED BY USER: SystemRestore enable denied."
			}
			Enable-ComputerRestore -Drive $drv -ErrorAction Stop
			return ConvertTo-MBJson @{ ok = $true; action = 'enable'; drive = $drv }
		}
		if ($a -eq 'disable') {
			if (-not (Request-Confirmation -Title "SystemRestore requires approval" -Details "Disable System Restore on $drv")) {
				return "BLOCKED BY USER: SystemRestore disable denied."
			}
			Disable-ComputerRestore -Drive $drv -ErrorAction Stop
			return ConvertTo-MBJson @{ ok = $true; action = 'disable'; drive = $drv }
		}
		if ($a -eq 'create') {
			$desc = if ([string]::IsNullOrWhiteSpace($description)) { "MiniBot restore point $(Get-Date -Format 'yyyy-MM-dd HH:mm')" } else { $description }
			if (-not (Request-Confirmation -Title "SystemRestore requires approval" -Details "Create restore point:`n  $desc")) {
				return "BLOCKED BY USER: SystemRestore create denied."
			}
			$beforeSeq = @()
			try {
				$beforeSeq = @(Get-ComputerRestorePoint -ErrorAction SilentlyContinue | ForEach-Object { [int]$_.SequenceNumber })
			} catch { $beforeSeq = @() }
			$createdAt = Get-Date
			Checkpoint-Computer -Description $desc -RestorePointType MODIFY_SETTINGS -ErrorAction Stop
			# Verify via list: find new sequence (not in before set), prefer matching description
			$seq = $null
			$matched = $null
			$verified = $false
			try {
				# SAM/SystemRestore can lag briefly
				for ($attempt = 0; $attempt -lt 6; $attempt++) {
					if ($attempt -gt 0) { try { Start-Sleep -Milliseconds 400 } catch {} }
					$pts = @()
					try { $pts = @(Get-ComputerRestorePoint -ErrorAction SilentlyContinue) } catch { $pts = @() }
					$candidates = @($pts | Where-Object {
						$sn = 0
						try { $sn = [int]$_.SequenceNumber } catch { $sn = 0 }
						-not ($beforeSeq -contains $sn)
					})
					if ($candidates.Count -eq 0) {
						# Fallback: match description on newest
						$candidates = @($pts | Where-Object {
							([string]$_.Description) -eq $desc -or ([string]$_.Description) -like "*$desc*"
						} | Sort-Object SequenceNumber -Descending | Select-Object -First 3)
					}
					if ($candidates.Count -gt 0) {
						$matched = $candidates | Sort-Object SequenceNumber -Descending | Select-Object -First 1
						try { $seq = [int]$matched.SequenceNumber } catch { $seq = $null }
						if ($null -ne $seq) {
							$verified = ($beforeSeq -notcontains $seq) -or (([string]$matched.Description) -like "*$desc*")
							if ($verified -or $seq -gt 0) { break }
						}
					}
				}
			} catch {}
			if ($null -eq $seq -or -not $verified) {
				return ConvertTo-MBJson ([ordered]@{
					ok          = $false
					action      = 'create'
					description = $desc
					sequence    = $seq
					verified    = $false
					error       = 'Checkpoint-Computer returned but new restore point was not found in Get-ComputerRestorePoint list yet (policy lag, SR disabled, or frequency limit).'
					hint        = 'Check action=list; System Restore may be off or limited to one point per 24h on some editions.'
				}) -Depth 5
			}
			return ConvertTo-MBJson ([ordered]@{
				ok          = $true
				action      = 'create'
				description = $desc
				sequence    = $seq
				verified    = $true
				creation_time = $(try { $matched.CreationTime.ToString('s') } catch { $createdAt.ToString('s') })
				point       = $(try {
					[ordered]@{
						SequenceNumber   = $seq
						Description      = [string]$matched.Description
						CreationTime     = $matched.CreationTime
						RestorePointType = [string]$matched.RestorePointType
					}
				} catch { $null })
			}) -Depth 5
		}
		return "ERROR: action must be status|enable|disable|create|list."
	} catch {
		return "ERROR: SystemRestore failed: $($_.Exception.Message)"
	}
}

function Invoke-UninstallSoftware {
	param(
		[string]$name,
		[string]$product_code = ''
	)
	if ([string]::IsNullOrWhiteSpace($name) -and [string]::IsNullOrWhiteSpace($product_code)) {
		return "ERROR: name or product_code required. Prefer GetInstalledSoftware first (system group)."
	}
	$roots = @(
		'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
		'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall',
		'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall'
	)
	$hits = New-Object System.Collections.ArrayList
	foreach ($root in $roots) {
		if (-not (Test-Path -LiteralPath $root)) { continue }
		Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue | ForEach-Object {
			try {
				$p = Get-ItemProperty -LiteralPath $_.PSPath -ErrorAction SilentlyContinue
				if (-not $p) { return }
				$dn = [string]$p.DisplayName
				if ([string]::IsNullOrWhiteSpace($dn)) { return }
				$guid = $_.PSChildName
				$match = $false
				if ($product_code -and ($guid -eq $product_code -or $guid -eq $product_code.Trim('{}'))) { $match = $true }
				elseif ($name -and $dn -like "*$name*") { $match = $true }
				if (-not $match) { return }
				[void]$hits.Add([ordered]@{
					name             = $dn
					version          = [string]$p.DisplayVersion
					publisher        = [string]$p.Publisher
					key              = $guid
					uninstall        = [string]$p.UninstallString
					quiet_uninstall  = [string]$p.QuietUninstallString
					path             = $_.PSPath
				})
			} catch {}
		}
	}
	if ($hits.Count -eq 0) {
		return "ERROR: No installed software matched name='$name' product_code='$product_code'."
	}
	if ($hits.Count -gt 1 -and -not $product_code) {
		$names = ($hits | ForEach-Object { $_.name }) -join '; '
		return "ERROR: Multiple matches ($($hits.Count)): $names. Narrow name= or pass product_code=."
	}
	$h = $hits[0]
	$cmd = if ($h.quiet_uninstall) { [string]$h.quiet_uninstall } else { [string]$h.uninstall }
	if ([string]::IsNullOrWhiteSpace($cmd)) {
		return "ERROR: No uninstall string for '$($h.name)'."
	}
	$details = "Uninstall software:`n  name = $($h.name)`n  version = $($h.version)`n  cmd = $cmd"
	if (-not (Request-Confirmation -Title "UninstallSoftware requires approval" -Details $details)) {
		return "BLOCKED BY USER: Uninstall denied."
	}
	try {
		if ($cmd -match '(?i)msiexec') {
			$r = Invoke-MBSetupNative -File 'cmd.exe' -ArgumentList @('/c', $cmd) -TimeoutSec 900
			return ConvertTo-MBJson ([ordered]@{ ok = $r.ok; name = $h.name; exit = $r.exit; out = $r.out; err = $r.err })
		}
		$r = Invoke-MBSetupNative -File 'cmd.exe' -ArgumentList @('/c', $cmd) -TimeoutSec 900
		return ConvertTo-MBJson ([ordered]@{ ok = $r.ok; name = $h.name; exit = $r.exit; out = $r.out; err = $r.err; note = 'Uninstall launched; some installers need GUI completion.' })
	} catch {
		return "ERROR: Uninstall failed: $($_.Exception.Message)"
	}
}

function Get-MBMaskedSecret {
	param([string]$Text)
	if ([string]::IsNullOrEmpty($Text)) { return '(empty)' }
	if ($Text.Length -le 2) { return '**' }
	return ('*' * [Math]::Min(12, $Text.Length))
}

function Test-MBLocalUserExists {
	# LocalAccounts -> ADSI -> short net user query.
	param([string]$Username)
	$user = ([string]$Username).Trim()
	if ([string]::IsNullOrWhiteSpace($user)) {
		return @{ exists = $false; method = 'empty'; enabled = $null }
	}
	if (Get-Command Get-LocalUser -ErrorAction SilentlyContinue) {
		try {
			$lu = Get-LocalUser -Name $user -ErrorAction Stop
			$en = $true
			try { $en = [bool]$lu.Enabled } catch {}
			return @{ exists = $true; method = 'Get-LocalUser'; enabled = $en }
		} catch {
			return @{ exists = $false; method = 'Get-LocalUser'; enabled = $null }
		}
	}
	try {
		$adsi = [ADSI]"WinNT://./$user,user"
		$null = $adsi.Name
		return @{ exists = $true; method = 'ADSI'; enabled = $null }
	} catch {}
	try {
		$chk = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user) -TimeoutSec 8
		$blob = (([string]$chk.out) + "`n" + ([string]$chk.err))
		if ($chk.ok -or $blob -match '(?i)User name\s+' -or $blob -match ('(?i)^\s*' + [regex]::Escape($user) + '\s*$')) {
			return @{ exists = $true; method = 'net user'; enabled = $null }
		}
		if ($blob -match '(?i)(The user name could not be found|does not exist|2221)') {
			return @{ exists = $false; method = 'net user'; enabled = $null }
		}
		if ($chk.exit -eq -1 -or $blob -match '(?i)timeout') {
			return @{ exists = $false; method = 'net user timeout'; enabled = $null; uncertain = $true }
		}
	} catch {}
	return @{ exists = $false; method = 'none'; enabled = $null }
}

function Test-MBNetUserAlreadyExistsMessage {
	param([string]$Text)
	$t = [string]$Text
	if ([string]::IsNullOrWhiteSpace($t)) { return $false }
	return [bool]($t -match '(?i)(already exists|2224|The account already exists|exists and is currently)')
}

function Invoke-AddLocalUser {
	param(
		[string]$username,
		[string]$password,
		[string]$full_name = '',
		[string]$description = '',
		[object]$admin = $false
	)
	$user = ([string]$username).Trim()
	$pass = [string]$password
	if ([string]::IsNullOrWhiteSpace($user)) { return "ERROR: username required." }
	if ($user -notmatch '^[A-Za-z0-9._-]{1,20}$') { return "ERROR: username must be 1-20 chars [A-Za-z0-9._-]." }
	if ([string]::IsNullOrEmpty($pass)) { return "ERROR: password required." }
	$isAdmin = $false
	if ($admin -is [bool]) { $isAdmin = $admin }
	elseif ([string]$admin -match '^(?i)1|true|yes|y|on$') { $isAdmin = $true }
	$fn = ([string]$full_name).Trim()
	$desc = ([string]$description).Trim()
	$details = "Create local user:`n  username = $user`n  password = $(Get-MBMaskedSecret $pass)`n  full_name = $(if ($fn) { $fn } else { '(none)' })`n  description = $(if ($desc) { $desc } else { '(none)' })`n  administrators = $isAdmin"
	if (-not (Request-Confirmation -Title "AddLocalUser requires approval" -Details $details)) {
		return "BLOCKED BY USER: AddLocalUser denied."
	}
	try {
		$ex = Test-MBLocalUserExists -Username $user
		if ($ex.exists) {
			return ConvertTo-MBJson ([ordered]@{
				ok             = $false
				exists         = $true
				username       = $user
				error          = "Local user '$user' already exists."
				check_method   = $ex.method
			}) -Depth 4
		}

		$sec = ConvertTo-SecureString -String $pass -AsPlainText -Force
		$created = $false
		$method = ''
		$addCmd = $null
		if (Get-Command New-LocalUser -ErrorAction SilentlyContinue) { $addCmd = 'New-LocalUser' }
		elseif (Get-Command Add-LocalUser -ErrorAction SilentlyContinue) { $addCmd = 'Add-LocalUser' }

		if ($addCmd) {
			$p = @{ Name = $user; Password = $sec; PasswordNeverExpires = $true; UserMayNotChangePassword = $false; ErrorAction = 'Stop' }
			if ($fn) { $p['FullName'] = $fn }
			if ($desc) { $p['Description'] = $desc }
			try {
				if ($addCmd -eq 'New-LocalUser') { New-LocalUser @p | Out-Null }
				else { Add-LocalUser @p | Out-Null }
				$created = $true
				$method = $addCmd
			} catch {
				$em = $_.Exception.Message
				if ($em -match '(?i)already exists|AccountAlreadyExists') {
					return ConvertTo-MBJson ([ordered]@{
						ok = $false; exists = $true; username = $user; error = "Local user '$user' already exists."; method = $addCmd
					})
				}
				throw
			}
			if ($isAdmin) {
				try { Add-LocalGroupMember -Group 'Administrators' -Member $user -ErrorAction Stop } catch {
					try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('localgroup', 'Administrators', $user, '/add') -TimeoutSec 12 } catch {}
				}
			}
		} else {
			# net user fallback
			$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user, $pass, '/add') -TimeoutSec 20
			$blob = (([string]$r.out) + "`n" + ([string]$r.err))
			if (-not $r.ok) {
				if (Test-MBNetUserAlreadyExistsMessage -Text $blob) {
					return ConvertTo-MBJson ([ordered]@{
						ok = $false; exists = $true; username = $user
						error = "Local user '$user' already exists."
						method = 'net user'; exit = $r.exit
					})
				}
				# Race: created between check and add, or slow DC — re-check
				$ex2 = Test-MBLocalUserExists -Username $user
				if ($ex2.exists) {
					return ConvertTo-MBJson ([ordered]@{
						ok = $false; exists = $true; username = $user
						error = "Local user '$user' already exists."
						method = 'net user'; exit = $r.exit
					})
				}
				return ConvertTo-MBJson ([ordered]@{
					ok = $false; username = $user; method = 'net user'
					exit = $r.exit; out = $r.out; err = $r.err
					error = $(if ($r.exit -eq -1) { 'net user timed out.' } else { "net user failed (exit $($r.exit))" })
				})
			}
			$created = $true
			$method = 'net user'
			if ($fn -or $desc) {
				try {
					$comment = $(if ($fn -and $desc) { "$fn; $desc" } elseif ($fn) { $fn } else { $desc })
					$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user, '/comment:' + $comment) -TimeoutSec 12
				} catch {}
			}
			if ($isAdmin) {
				$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('localgroup', 'Administrators', $user, '/add') -TimeoutSec 12
			}
		}
		try { Register-MBShareSessionUser -Username $user -Password $pass } catch {}
		return ConvertTo-MBJson ([ordered]@{
			ok             = $created
			exists         = $false
			username       = $user
			administrators = $isAdmin
			method         = $method
		})
	} catch {
		$em = $_.Exception.Message
		if ($em -match '(?i)already exists') {
			return ConvertTo-MBJson ([ordered]@{ ok = $false; exists = $true; username = $user; error = "Local user '$user' already exists." })
		}
		return "ERROR: AddLocalUser failed: $em"
	}
}

function Invoke-JoinDomain {
	param(
		[string]$domain,
		[string]$username,
		[string]$password,
		[string]$ou = '',
		[string]$new_name = '',
		[object]$reboot = $false
	)
	$dom = ([string]$domain).Trim()
	$user = ([string]$username).Trim()
	$pass = [string]$password
	$ouDn = ([string]$ou).Trim()
	$rename = ([string]$new_name).Trim()
	if ([string]::IsNullOrWhiteSpace($dom)) { return "ERROR: domain required (e.g. corp.example.com)." }
	if ([string]::IsNullOrWhiteSpace($user)) { return "ERROR: username required for domain join." }
	if ([string]::IsNullOrEmpty($pass)) { return "ERROR: password required." }
	$doReboot = $false
	if ($reboot -is [bool]) { $doReboot = $reboot }
	elseif ([string]$reboot -match '^(?i)1|true|yes|y|on$') { $doReboot = $true }
	$details = "Join domain:`n  domain = $dom`n  username = $user`n  password = $(Get-MBMaskedSecret $pass)`n  ou = $(if ($ouDn) { $ouDn } else { '(default)' })`n  new_name = $(if ($rename) { $rename } else { '(unchanged)' })`n  reboot = $doReboot`n`nRequires elevation and network access to a domain controller."
	if (-not (Request-Confirmation -Title "JoinDomain requires approval" -Details $details)) {
		return "BLOCKED BY USER: JoinDomain denied."
	}
	try {
		$sec = ConvertTo-SecureString -String $pass -AsPlainText -Force
		# Normalize DOMAIN\user or user@domain
		$credUser = $user
		if ($credUser -notmatch '[\\@]') { $credUser = "$dom\$user" }
		$cred = New-Object System.Management.Automation.PSCredential ($credUser, $sec)
		$joinParams = @{
			DomainName   = $dom
			Credential   = $cred
			Force        = $true
			ErrorAction  = 'Stop'
			PassThru     = $true
			WarningAction = 'SilentlyContinue'
		}
		if ($ouDn) { $joinParams['OUPath'] = $ouDn }
		if ($rename) { $joinParams['NewName'] = $rename }
		if ($doReboot) { $joinParams['Restart'] = $true }
		$result = Add-Computer @joinParams
		return ConvertTo-MBJson ([ordered]@{
			ok        = $true
			domain    = $dom
			username  = $user
			ou        = $ouDn
			new_name  = $rename
			reboot    = $doReboot
			result    = "$result"
			note      = $(if ($doReboot) { 'Restart initiated after join.' } else { 'Reboot recommended to finish domain join.' })
		})
	} catch {
		return "ERROR: JoinDomain failed: $($_.Exception.Message)"
	}
}

function Ensure-MBLogonHelper {
	if ('MiniBot.Native.MBLogon' -as [type]) { return }
	Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
namespace MiniBot.Native {
  public static class MBLogon {
    [DllImport("advapi32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    public static extern bool LogonUser(string lpszUsername, string lpszDomain, string lpszPassword, int dwLogonType, int dwLogonProvider, out IntPtr phToken);
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool CloseHandle(IntPtr hObject);
    public static bool ValidateLocalUser(string username, string password) {
      if (string.IsNullOrEmpty(username) || password == null) return false;
      IntPtr token = IntPtr.Zero;
      try {
        string machine = Environment.MachineName;
        // LOGON32_LOGON_INTERACTIVE=2, NETWORK=3, BATCH=4, NETWORK_CLEARTEXT=8
        int[] types = new int[] { 3, 2, 8, 4 };
        string[] domains = new string[] { ".", machine, "" };
        foreach (int t in types) {
          foreach (string d in domains) {
            if (token != IntPtr.Zero) { CloseHandle(token); token = IntPtr.Zero; }
            if (LogonUser(username, d, password, t, 0, out token)) return true;
          }
        }
        return false;
      } finally {
        if (token != IntPtr.Zero) CloseHandle(token);
      }
    }
  }
}
"@ -Language CSharp -ErrorAction Stop
}

function Clear-MBLocalUserLogonFlags {
	# After a password set, clear flags that break immediate LogonUser / SMB auth.
	param([string]$Username)
	$user = ([string]$Username).Trim()
	if ([string]::IsNullOrWhiteSpace($user)) { return }
	try { Enable-LocalUser -Name $user -ErrorAction SilentlyContinue } catch {}
	try { Set-LocalUser -Name $user -PasswordNeverExpires $true -ErrorAction SilentlyContinue } catch {}
	try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user, '/active:yes') -TimeoutSec 15 } catch {}
	try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user, '/passwordchg:yes') -TimeoutSec 15 } catch {}
	try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user, '/logonpasswordchg:no') -TimeoutSec 15 } catch {}
	try {
		$adsi = [ADSI]("WinNT://./$user,user")
		try {
			# Clear "password expired / must change at next logon"
			$adsi.Put('PasswordExpired', 0)
			$adsi.SetInfo()
		} catch {}
		try {
			$flags = 0
			try { $flags = [int]$adsi.UserFlags.Value } catch {
				try { $flags = [int]$adsi.UserFlags[0] } catch { $flags = 0 }
			}
			# UF_DONT_EXPIRE_PASSWD=0x10000; clear UF_ACCOUNTDISABLE=0x2 and UF_PASSWORD_EXPIRED=0x800000
			$flags = ($flags -bor 0x10000) -band (-bnot 0x2) -band (-bnot 0x800000)
			$adsi.Put('UserFlags', $flags)
			$adsi.SetInfo()
		} catch {}
	} catch {}
}

function Set-MBLocalUserPassword {
	# Best-effort password set for a local account (elevated). Returns detail for failures.
	param(
		[string]$Username,
		[string]$Password
	)
	$user = ([string]$Username).Trim()
	$pass = [string]$Password
	if ([string]::IsNullOrWhiteSpace($user)) { return @{ ok = $false; error = 'username required' } }
	if ($null -eq $pass) { return @{ ok = $false; error = 'password required' } }
	$errs = New-Object System.Collections.ArrayList
	# 1) Set-LocalUser
	if (Get-Command Set-LocalUser -ErrorAction SilentlyContinue) {
		try {
			$sec = ConvertTo-SecureString -String $pass -AsPlainText -Force
			Set-LocalUser -Name $user -Password $sec -ErrorAction Stop
			Clear-MBLocalUserLogonFlags -Username $user
			return @{ ok = $true; method = 'Set-LocalUser' }
		} catch {
			[void]$errs.Add(('Set-LocalUser: {0}' -f $_.Exception.Message))
		}
	}
	# 2) net user - single raw arg line so special chars in password are quoted safely
	try {
		$passEsc = $pass -replace '"', '""'
		$netLine = 'user {0} "{1}"' -f $user, $passEsc
		$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @($netLine) -TimeoutSec 30
		if ($r.ok) {
			Clear-MBLocalUserLogonFlags -Username $user
			return @{ ok = $true; method = 'net user'; detail = (([string]$r.out) + ' ' + ([string]$r.err)).Trim() }
		}
		[void]$errs.Add(('net user: exit={0} {1} {2}' -f $r.exit, $r.out, $r.err))
	} catch {
		[void]$errs.Add(('net user: {0}' -f $_.Exception.Message))
	}
	# 3) ADSI WinNT
	try {
		$adsi = [ADSI]("WinNT://./$user,user")
		$adsi.SetPassword($pass)
		$adsi.SetInfo()
		Clear-MBLocalUserLogonFlags -Username $user
		return @{ ok = $true; method = 'ADSI' }
	} catch {
		[void]$errs.Add(('ADSI: {0}' -f $_.Exception.Message))
	}
	return @{
		ok    = $false
		error = ('Could not set password for local user ''{0}''. {1} (Often: password policy complexity, not elevated, or account restrictions.)' -f $user, (($errs | ForEach-Object { $_ }) -join ' | '))
	}
}

function Get-MBLocalAdminAccounts {
	# Local (not domain) members of Administrators - enabled first.
	$list = New-Object System.Collections.ArrayList
	$seen = @{}
	$rawNames = New-Object System.Collections.ArrayList
	$machine = ([string]$env:COMPUTERNAME).ToUpperInvariant()

	if (Get-Command Get-LocalGroupMember -ErrorAction SilentlyContinue) {
		try {
			Get-LocalGroupMember -Group 'Administrators' -ErrorAction Stop | ForEach-Object {
				try {
					$oc = [string]$_.ObjectClass
					if ($oc -match '(?i)group') { return }
					$src = ''
					try { $src = [string]$_.PrincipalSource } catch {}
					$n = [string]$_.Name
					if ([string]::IsNullOrWhiteSpace($n)) { return }
					$userPart = $n
					$domPart = ''
					if ($n -match '^(?<d>[^\\]+)\\(?<u>.+)$') {
						$domPart = $Matches['d']
						$userPart = $Matches['u']
					}
					$domU = $domPart.ToUpperInvariant()
					$isLocal = $false
					if ($src -eq 'Local') { $isLocal = $true }
					elseif ($domU -eq $machine -or $domU -eq '.' -or $domU -eq 'BUILTIN' -or [string]::IsNullOrWhiteSpace($domPart)) { $isLocal = $true }
					# Domain principals: DOMAIN\user with PrincipalSource ActiveDirectory / not Local
					if (-not $isLocal) { return }
					if ($domU -eq 'BUILTIN' -and $userPart -match '(?i)^Administrators$') { return }
					[void]$rawNames.Add($userPart)
				} catch {}
			}
		} catch {}
	}
	if ($rawNames.Count -eq 0) {
		try {
			$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('localgroup', 'Administrators') -TimeoutSec 15
			$inMembers = $false
			foreach ($line in (([string]$r.out) -split "`r?`n")) {
				if ($line -match '----') { $inMembers = $true; continue }
				if (-not $inMembers) { continue }
				$t = $line.Trim()
				if ([string]::IsNullOrWhiteSpace($t)) { continue }
				if ($t -match '(?i)command completed') { break }
				if ($t -match '^(?<d>[^\\]+)\\(?<u>.+)$') {
					$domU = $Matches['d'].ToUpperInvariant()
					if ($domU -ne $machine -and $domU -ne '.') { continue }
					[void]$rawNames.Add($Matches['u'])
				} else {
					[void]$rawNames.Add($t)
				}
			}
		} catch {}
	}

	foreach ($an in $rawNames) {
		$key = $an.ToLowerInvariant()
		if ($seen.ContainsKey($key)) { continue }
		$seen[$key] = $true
		$enabled = $true
		$fn = ''
		$isLocalUser = $true
		if (Get-Command Get-LocalUser -ErrorAction SilentlyContinue) {
			try {
				$u = Get-LocalUser -Name $an -ErrorAction Stop
				$enabled = [bool]$u.Enabled
				$fn = [string]$u.FullName
			} catch {
				$isLocalUser = $false
			}
		}
		if (-not $isLocalUser) { continue }
		[void]$list.Add([pscustomobject]@{ name = $an; enabled = $enabled; full_name = $fn })
	}
	return @($list | Sort-Object @{ Expression = { -not $_.enabled } }, @{ Expression = { $_.name } })
}

function Test-MBLocalAdminCredential {
	param(
		[string]$Username,
		[string]$Password
	)
	$user = ([string]$Username).Trim()
	if ([string]::IsNullOrWhiteSpace($user)) { return $false }
	if ($null -eq $Password) { return $false }
	try { Ensure-MBLogonHelper } catch { return $false }
	$okLogon = $false
	try { $okLogon = [MiniBot.Native.MBLogon]::ValidateLocalUser($user, [string]$Password) } catch { $okLogon = $false }
	if (-not $okLogon) { return $false }
	$admins = @(Get-MBLocalAdminAccounts)
	foreach ($a in $admins) {
		if ([string]$a.name -eq $user) { return $true }
	}
	try {
		$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('localgroup', 'Administrators', $user) -TimeoutSec 10
		if ($r.ok -or ([string]$r.out + [string]$r.err) -match '(?i)is a member|The command completed') {
			return $true
		}
	} catch {}
	return $false
}

function Register-MBShareSessionUser {
	# Session cache of share users created/reset this run.
	param([string]$Username, [string]$Password)
	try {
		if ($null -eq $script:MB.ShareSessionUsers -or -not ($script:MB.ShareSessionUsers -is [hashtable])) {
			$script:MB.ShareSessionUsers = @{}
		}
		$key = ([string]$Username).Trim().ToLowerInvariant()
		if ($key) { $script:MB.ShareSessionUsers[$key] = [string]$Password }
	} catch {}
}

function Test-MBShareSessionUser {
	param([string]$Username, [string]$Password)
	try {
		if ($null -eq $script:MB.ShareSessionUsers -or -not ($script:MB.ShareSessionUsers -is [hashtable])) {
			return $false
		}
		$key = ([string]$Username).Trim().ToLowerInvariant()
		if (-not $key -or -not $script:MB.ShareSessionUsers.ContainsKey($key)) { return $false }
		return ([string]$script:MB.ShareSessionUsers[$key] -eq [string]$Password)
	} catch { return $false }
}

function Ensure-MBShareLocalUser {
	# Existing: verify password (or force reset). Missing: create.
	param(
		[string]$Username = 'share',
		[string]$Password,
		[object]$force_password_update = $false,
		[object]$reset_password = $false
	)
	$user = ([string]$Username).Trim()
	$pass = [string]$Password
	if ([string]::IsNullOrWhiteSpace($user)) {
		return @{ ok = $false; error = 'access username required' }
	}
	if ($user -notmatch '^[A-Za-z0-9._-]{1,20}$') {
		return @{ ok = $false; error = 'username must be 1-20 chars [A-Za-z0-9._-]' }
	}
	if ([string]::IsNullOrEmpty($pass)) {
		return @{ ok = $false; error = 'access password required' }
	}
	$forcePw = $false
	try { $forcePw = Convert-MBToBool -Value $force_password_update -Default $false } catch {}
	if (-not $forcePw) {
		try { $forcePw = Convert-MBToBool -Value $reset_password -Default $false } catch {}
	}
	try {
		$exInfo = Test-MBLocalUserExists -Username $user
		$exists = [bool]$exInfo.exists
		$enabled = $true
		if ($null -ne $exInfo.enabled) { $enabled = [bool]$exInfo.enabled }
		if ($exists) {
			if (-not $enabled) {
				try { Enable-LocalUser -Name $user -ErrorAction SilentlyContinue } catch {}
				try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user, '/active:yes') -TimeoutSec 12 } catch {}
			}
			# Verify password matches existing account (do not silently reset)
			$authOk = $false
			try { $authOk = [bool](Test-MBLocalUserCredential -Username $user -Password $pass) } catch { $authOk = $false }
			if (-not $authOk -and (Test-MBShareSessionUser -Username $user -Password $pass)) {
				$authOk = $true
				return @{
					ok       = $true
					username = $user
					created  = $false
					method   = 'session_recent'
					password_verified = $true
				}
			}
			if ($authOk) {
				try { Register-MBShareSessionUser -Username $user -Password $pass } catch {}
				return @{
					ok       = $true
					username = $user
					created  = $false
					method   = 'verified_existing'
					password_verified = $true
				}
			}
			if ($forcePw) {
				$set = Set-MBLocalUserPassword -Username $user -Password $pass
				if (-not $set.ok) {
					return @{
						ok         = $false
						need_input = $true
						missing    = @('access_password')
						error      = [string]$set.error
						username   = $user
						exists     = $true
					}
				}
				$auth2 = $false
				foreach ($delayMs in @(300, 700, 1200)) {
					try { Start-Sleep -Milliseconds $delayMs } catch {}
					try { $auth2 = [bool](Test-MBLocalUserCredential -Username $user -Password $pass) } catch { $auth2 = $false }
					if ($auth2) { break }
					try { Clear-MBLocalUserLogonFlags -Username $user } catch {}
				}
				if (-not $auth2) {
					try { Register-MBShareSessionUser -Username $user -Password $pass } catch {}
					return @{
						ok       = $true
						username = $user
						created  = $false
						method   = ('force_password_update:' + [string]$set.method)
						password_verified = $false
					}
				}
				try { Register-MBShareSessionUser -Username $user -Password $pass } catch {}
				return @{
					ok       = $true
					username = $user
					created  = $false
					method   = ('force_password_update:' + [string]$set.method)
					password_verified = $true
				}
			}
			return @{
				ok         = $false
				need_input = $true
				missing    = @('access_password')
				error      = "Local user '$user' exists but the password does not match. Ask for the correct password, or call again with force_password_update=true (or reset_password=true) to set a new password."
				username   = $user
				exists     = $true
				password_verified = $false
			}
		}
		$cr = New-MBLocalShareUserCore -username $user -password $pass -full_name 'Network share access'
		if (-not $cr.ok) {
			# Race / exists: treat as existing account and continue password verify path
			$already = $false
			try { if ($cr.exists) { $already = $true } } catch {}
			if (-not $already -and ("$($cr.error)" -match '(?i)already exists')) { $already = $true }
			if ($already) {
				$authRace = $false
				try { $authRace = [bool](Test-MBLocalUserCredential -Username $user -Password $pass) } catch {}
				if (-not $authRace -and (Test-MBShareSessionUser -Username $user -Password $pass)) { $authRace = $true }
				if ($authRace) {
					try { Register-MBShareSessionUser -Username $user -Password $pass } catch {}
					return @{
						ok = $true; username = $user; created = $false
						method = 'exists_after_create_attempt'; password_verified = $true
					}
				}
				if ($forcePw) {
					$set = Set-MBLocalUserPassword -Username $user -Password $pass
					if ($set.ok) {
						try { Register-MBShareSessionUser -Username $user -Password $pass } catch {}
						return @{
							ok = $true; username = $user; created = $false
							method = ('force_password_update:' + [string]$set.method)
							password_verified = $true
						}
					}
				}
				return @{
					ok = $false; need_input = $true; missing = @('access_password')
					error = "Local user '$user' already exists but the password does not match. Pass force_password_update=true to reset, or use the correct password."
					username = $user; exists = $true
				}
			}
			return $cr
		}
		try { Start-Sleep -Milliseconds 300 } catch {}
		$authNew = $false
		try { $authNew = [bool](Test-MBLocalUserCredential -Username $user -Password $pass) } catch { $authNew = $false }
		# Always remember session-created accounts so next CreateShare breath trusts same password
		try { Register-MBShareSessionUser -Username $user -Password $pass } catch {}
		return @{
			ok       = $true
			username = $user
			created  = $true
			method   = $cr.method
			password_verified = $authNew
		}
	} catch {
		return @{ ok = $false; error = $_.Exception.Message }
	}
}

function Invoke-LeaveDomain {
	param(
		[string]$workgroup = 'WORKGROUP',
		[object]$reboot = $false,
		[string]$local_username = '',
		[string]$local_password = ''
	)
	$cs = $null
	try {
		$cs = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
	} catch {
		try { $cs = Get-WmiObject -Class Win32_ComputerSystem -ErrorAction Stop } catch {}
	}
	if (-not $cs) { return "ERROR: Could not read computer domain membership." }
	$partOfDomain = $false
	try { $partOfDomain = [bool]$cs.PartOfDomain } catch {}
	$dom = [string]$cs.Domain
	if (-not $partOfDomain) {
		return "ERROR: This PC is not domain-joined (workgroup/domain label: $dom). Nothing to leave."
	}
	$wg = ([string]$workgroup).Trim()
	if ([string]::IsNullOrWhiteSpace($wg)) { $wg = 'WORKGROUP' }
	$doReboot = $false
	if ($reboot -is [bool]) { $doReboot = $reboot }
	elseif ([string]$reboot -match '^(?i)1|true|yes|y|on$') { $doReboot = $true }

	# Require local admin creds via tool args (chat). No UI credential popup.
	$verifiedUser = ''
	$verifiedPass = ''
	$createdAdmin = $false
	$lu = ([string]$local_username).Trim()
	$lp = [string]$local_password
	$adminNames = @()
	try {
		$adminNames = @(Get-MBLocalAdminAccounts | ForEach-Object { [string]$_.name } | Where-Object { $_ })
	} catch { $adminNames = @() }
	if ([string]::IsNullOrWhiteSpace($lu) -or [string]::IsNullOrEmpty($lp)) {
		return ConvertTo-MBJson ([ordered]@{
			ok         = $false
			need_input = $true
			missing    = @($(if (-not $lu) { 'local_username' }), $(if ([string]::IsNullOrEmpty($lp)) { 'local_password' }) | Where-Object { $_ })
			message    = 'NEED_INPUT: local_username and local_password are required (local admin that can sign in after leave). Ask the operator in chat. If none exist, use AddLocalUser admin=true with a password they choose, then LeaveDomain with those credentials. Show the password back so they know what was entered.'
			domain     = $dom
			local_admins = @($adminNames)
		}) -Depth 4
	}
	if (-not (Test-MBLocalAdminCredential -Username $lu -Password $lp)) {
		return ConvertTo-MBJson ([ordered]@{
			ok         = $false
			need_input = $true
			missing    = @('local_username', 'local_password')
			message    = "NEED_INPUT: credentials for local admin '$lu' failed verification. Ask the operator for a valid local admin username and password (or create one with AddLocalUser admin=true), then retry LeaveDomain."
			domain     = $dom
			tried_user = $lu
			local_admins = @($adminNames)
		}) -Depth 4
	}
	$verifiedUser = $lu
	$verifiedPass = $lp

	$details = @"
LEAVE DOMAIN (lockout-safe gate passed):
  current domain = $dom
  target workgroup = $wg
  verified local admin = $verifiedUser
  local admin created this run = $createdAdmin
  reboot after leave = $doReboot

After this, domain accounts cannot sign in. Use local\$verifiedUser (or other local accounts).
"@
	if (-not (Request-Confirmation -Title "LeaveDomain requires approval" -Details $details)) {
		return "BLOCKED BY USER: LeaveDomain denied."
	}
	try {
		$sec = ConvertTo-SecureString -String $verifiedPass -AsPlainText -Force
		$localCred = New-Object System.Management.Automation.PSCredential (".\$verifiedUser", $sec)
		$rmParams = @{
			WorkgroupName   = $wg
			LocalCredential = $localCred
			Force           = $true
			PassThru        = $true
			ErrorAction     = 'Stop'
			WarningAction   = 'SilentlyContinue'
		}
		if ($doReboot) { $rmParams['Restart'] = $true }
		$result = Remove-Computer @rmParams
		return ConvertTo-MBJson ([ordered]@{
			ok              = $true
			left_domain     = $dom
			workgroup       = $wg
			local_admin     = $verifiedUser
			created_admin   = $createdAdmin
			reboot          = $doReboot
			result          = "$result"
			note            = $(if ($doReboot) { 'Restart initiated after leave.' } else { 'Reboot recommended to finish leaving the domain. Sign in with the verified local admin.' })
		})
	} catch {
		return "ERROR: LeaveDomain failed: $($_.Exception.Message)"
	}
}

function Resolve-MBWindowsAccountName {
	# Normalize HOST\user for net use / New-SmbMapping (JSON often doubles backslashes).
	param(
		[string]$Username = '',
		[string]$Domain = ''
	)
	$u = ([string]$Username).Trim().Trim('"').Trim("'")
	$d = ([string]$Domain).Trim().Trim('"').Trim("'").TrimEnd('\')
	if ([string]::IsNullOrWhiteSpace($u)) { return '' }
	# Collapse accidental multi-backslashes from JSON (keep single \)
	while ($u.Contains('\\')) { $u = $u.Replace('\\', '\') }
	$u = $u -replace '/', '\'
	# Strip leading .\ or \\
	if ($u.StartsWith('.\')) { $u = $u.Substring(2) }
	if ($u.StartsWith('\\') -and $u -match '^\\\\(?<host>[^\\]+)\\(?<user>.+)$') {
		# \\server\user form
		return ($Matches['host'] + '\' + $Matches['user'])
	}
	if (-not [string]::IsNullOrWhiteSpace($d)) {
		if ($u -match '^(?<h>[^\\]+)\\(?<n>.+)$') {
			# already qualified - keep as-is unless domain was meant to override host part
			return $u
		}
		if ($u -match '@') { return $u }
		return ($d + '\' + $u)
	}
	return $u
}

function Normalize-MBUncPath {
	param([string]$Path)
	$p = ([string]$Path).Trim().Trim('"').Trim("'")
	if ([string]::IsNullOrWhiteSpace($p)) { return $p }
	# JSON often produces \\\\server\\share -> normalize to \\server\share
	while ($p -match '\\\\\\') { $p = $p -replace '\\\\', '\' } # too aggressive?
	# Safer: replace runs of 2+ backslashes with single, then ensure leading \\
	$p = [regex]::Replace($p, '\\{2,}', '\')
	if ($p.StartsWith('\')) {
		# \server\share -> \\server\share
		if (-not $p.StartsWith('\\')) { $p = '\' + $p }
		else {
			# became \server\share after collapse of \\\\server -> need \\
			# After {2,} -> \, leading \\ becomes \ - fix UNC root
			if ($p -match '^\\[^\\]') { $p = '\' + $p }
		}
	} elseif ($p -match '^[A-Za-z0-9._-]+\\.+') {
		$p = '\\' + $p
	}
	# Final: must start with \\ for UNC
	if ($p -match '^\\[^\\]') { $p = '\' + $p }
	# Local hostnames -> 127.0.0.1 for reliable loopback
	try {
		if ($p -match '^\\\\(?<host>[^\\]+)\\(?<rest>.+)$') {
			$h = [string]$Matches['host']
			$rest = [string]$Matches['rest']
			$isLocal = $false
			try { $isLocal = [bool](Test-MBIsLocalHostTarget -HostName $h) } catch { $isLocal = $false }
			if ($isLocal -and $h -notmatch '^(?i)127\.0\.0\.1$') {
				$p = '\\127.0.0.1\' + $rest
			}
		}
	} catch {}
	return $p
}

function Test-MBDriveLetterFreeForMap {
	# Free only if the letter has no root and is not CD-ROM (empty optical looks free without media).
	param([string]$Letter)
	$L = ([string]$Letter).Trim().TrimEnd(':').ToUpperInvariant()
	if ($L -notmatch '^[A-Z]$') { return $false }

	try {
		if (Test-Path -LiteralPath "${L}:\") { return $false }
		if ([System.IO.Directory]::Exists("${L}:\")) { return $false }
	} catch {
		return $false
	}

	try {
		$r = Invoke-MBSetupNative -File 'fsutil.exe' -ArgumentList @('fsinfo', 'drivetype', "${L}:") -TimeoutSec 5
		$blob = ((([string]$r.out) + ' ' + ([string]$r.err)).Trim())
		if (-not $blob) { throw 'empty fsutil' }
		if ($blob -match '(?i)CD-ROM') { return $false }
		if ($blob -match '(?i)No such') { return $true }
		return $false
	} catch {
		try {
			$di = New-Object System.IO.DriveInfo ("${L}:")
			if ($di.DriveType -eq [System.IO.DriveType]::CDRom) { return $false }
			if ($di.DriveType -eq [System.IO.DriveType]::NoRootDirectory) { return $true }
			return $false
		} catch {
			return $false
		}
	}
}

function Get-MBAvailableDriveLetter {
	# Scan D–Z for a free letter; Prefer= used first when free. Never auto-picks A/B/C.
	param([string]$Prefer = '')
	$pref = ([string]$Prefer).Trim().TrimEnd(':').ToUpperInvariant()
	$order = New-Object System.Collections.ArrayList
	if ($pref -match '^[A-Z]$' -and $pref -notin @('A', 'B', 'C')) { [void]$order.Add($pref) }
	foreach ($code in 68..90) { # D=68 .. Z=90
		$ch = [string][char]$code
		if ($ch -ne $pref) { [void]$order.Add($ch) }
	}
	foreach ($L in @($order)) {
		if (Test-MBDriveLetterFreeForMap -Letter $L) { return $L }
	}
	return $null
}

function Invoke-MapNetworkDrive {
	param(
		[string]$letter = '',
		[string]$path,
		[string]$username = '',
		[string]$domain = '',
		[string]$password = '',
		[object]$persistent = $true,
		[object]$force = $false
	)
	$want = ([string]$letter).Trim().TrimEnd(':').ToUpperInvariant()
	$unc = Normalize-MBUncPath -Path $path
	if ($unc -notmatch '^\\\\[^\\]+\\.+') {
		return "ERROR: path must be a UNC share (\\\\server\\share). Got: $unc"
	}

	# Prefer requested letter if free; else auto-pick (skip CD/DVD reserved)
	$autoLetter = $false
	$let = $null
	if ($want -match '^[A-Z]$') {
		if (Test-MBDriveLetterFreeForMap -Letter $want) {
			$let = $want
		} elseif ($force) {
			# force = reclaim requested letter
			$let = $want
		} else {
			$let = Get-MBAvailableDriveLetter -Prefer $want
			$autoLetter = $true
			if (-not $let) {
				return "ERROR: letter ${want}: is not free (in use or CD/DVD reserved) and no other free letter found."
			}
		}
	} else {
		$let = Get-MBAvailableDriveLetter
		$autoLetter = $true
		if (-not $let) {
			return "ERROR: no free drive letter available (checked D-Z; CD/DVD reserved letters skipped)."
		}
	}

	$user = Resolve-MBWindowsAccountName -Username $username -Domain $domain
	$pass = if ($null -eq $password) { '' } else { [string]$password }
	$persist = $true
	if ($persistent -is [bool]) { $persist = $persistent }
	elseif ([string]$persistent -match '^(?i)0|false|no|off$') { $persist = $false }
	$doForce = $false
	if ($force -is [bool]) { $doForce = $force }
	elseif ([string]$force -match '^(?i)1|true|yes|y|on$') { $doForce = $true }

	$details = "Map network drive:`n  letter = ${let}:$(if ($autoLetter) { ' (auto-picked free letter; CD/DVD reserved skipped)' } else { '' })`n  path = $unc`n  username = $(if ($user) { $user } else { '(current user)' })`n  password = $(if ($user) { $pass } else { '(n/a)' })`n  persistent = $persist`n  force = $doForce"
	if (-not (Request-Confirmation -Title "MapNetworkDrive requires approval" -Details $details)) {
		return "BLOCKED BY USER: MapNetworkDrive denied."
	}
	try {
		if ($doForce) {
			try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('use', "${let}:", '/delete', '/y') -TimeoutSec 15 } catch {}
			try {
				if (Get-Command Remove-SmbMapping -ErrorAction SilentlyContinue) {
					Remove-SmbMapping -LocalPath "${let}:" -Force -UpdateProfile -ErrorAction SilentlyContinue
				}
			} catch {}
			try { Remove-PSDrive -Name $let -Force -ErrorAction SilentlyContinue } catch {}
		}

		$method = ''
		$ok = $false
		$out = ''
		$err = ''
		$exit = 0

		# Prefer New-SmbMapping - UserName as PowerShell string (HOST\user safe)
		if (Get-Command New-SmbMapping -ErrorAction SilentlyContinue) {
			try {
				$mapParams = @{
					LocalPath   = "${let}:"
					RemotePath  = $unc
					Persistent  = $persist
					ErrorAction = 'Stop'
				}
				if ($user) {
					$mapParams['UserName'] = $user
					$mapParams['Password'] = $pass
				}
				New-SmbMapping @mapParams | Out-Null
				$ok = $true
				$method = 'New-SmbMapping'
			} catch {
				$err = $_.Exception.Message
				$method = 'New-SmbMapping-failed'
			}
		}

		# Fallback: net use (same shape as manual: net use M: \\IP\temp /user:share pass /persistent:yes)
		if (-not $ok) {
			$netArgs = New-Object System.Collections.ArrayList
			[void]$netArgs.Add('use')
			[void]$netArgs.Add("${let}:")
			[void]$netArgs.Add($unc)
			if ($user) {
				[void]$netArgs.Add('/user:' + $user)
				[void]$netArgs.Add($(if ($null -eq $pass) { '' } else { $pass }))
			}
			[void]$netArgs.Add($(if ($persist) { '/persistent:yes' } else { '/persistent:no' }))
			$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @($netArgs.ToArray()) -TimeoutSec 60
			$ok = [bool]$r.ok
			$exit = $r.exit
			$out = [string]$r.out
			$err = if ($err -and -not $r.ok) { ($err + '; ' + [string]$r.err) } else { [string]$r.err }
			$method = if ($method -eq 'New-SmbMapping-failed') { 'net use (after New-SmbMapping failed)' } else { 'net use' }
		}

		$verify = $null
		$card = ''
		$psDriveOk = $false
		if ($ok) {
			# Remember mapping for this MiniBot session so ListDirectory/S:\ can rewrite to UNC
			# when the letter is invisible to elevated / isolated agent process.
			try { Register-MBSessionDriveMap -Letter $let -Unc $unc } catch {}
			# Process-local PSDrive so Test-Path/Get-ChildItem work in this process even if S:\ is missing
			try {
				if (Get-PSDrive -Name $let -ErrorAction SilentlyContinue) {
					try { Remove-PSDrive -Name $let -Force -ErrorAction SilentlyContinue } catch {}
				}
				$pd = @{
					Name        = $let
					PSProvider  = 'FileSystem'
					Root        = $unc
					ErrorAction = 'Stop'
				}
				# Scope Global so tool calls in same runspace see it
				New-PSDrive @pd -Scope 'Global' | Out-Null
				$psDriveOk = $true
			} catch {
				try {
					if ($user) {
						$sec = New-MBPlainToSecureString -PlainText $pass
						$cred = New-Object System.Management.Automation.PSCredential ($user, $sec)
						New-PSDrive -Name $let -PSProvider FileSystem -Root $unc -Credential $cred -Scope Global -ErrorAction Stop | Out-Null
						$psDriveOk = $true
					}
				} catch { $psDriveOk = $false }
			}
			$verify = Test-MBMappedDrivePresent -Letter $let -Unc $unc
			try { [void](Add-MBStickyNote -Text ("Mapped ${let}: -> $unc") -Kind finding) } catch {}
			$card = Write-MBOperatorCard -Title 'DRIVE MAPPED' -Fields ([ordered]@{
				Letter     = "${let}:"
				UNC        = $unc
				Username   = $(if ($user) { $user } else { '(current user)' })
				Persistent = $persist
				Method     = $method
				Verified   = $(if ($verify.ok) { 'yes (' + $verify.detail + ')' } else { 'NO - ' + $verify.detail })
				AgentPath  = $(if ($psDriveOk) { "${let}: (PSDrive)" } else { $unc })
			}) -Notes @(
				$(if ($autoLetter) { 'Letter was auto-picked (CD/DVD reserved letters skipped).' } else { '' }),
				'If ListDirectory on the letter fails, use the UNC path (local shares prefer \\127.0.0.1\share).'
			)
		}

		return ConvertTo-MBJson ([ordered]@{
			ok            = $ok
			letter        = "${let}:"
			letter_auto   = $autoLetter
			path          = $unc
			username      = $user
			persistent    = $persist
			method        = $method
			exit          = $exit
			out           = $out
			err           = $err
			verified      = $(if ($verify) { [bool]$verify.ok } else { $false })
			verify_detail = $(if ($verify) { [string]$verify.detail } else { '' })
			psdrive       = [bool]$psDriveOk
			session_map   = $true
			access_hint   = $unc
			operator_card = $card
		})
	} catch {
		return "ERROR: MapNetworkDrive failed: $($_.Exception.Message)"
	}
}

function Invoke-AddNetworkPrinter {
	param(
		[string]$path,
		[string]$name = '',
		[object]$set_default = $false
	)
	$unc = ([string]$path).Trim()
	$friendly = ([string]$name).Trim()
	if ($unc -notmatch '^\\\\') { return "ERROR: path must be a printer share UNC (\\\\server\\printer)." }
	$makeDefault = $false
	if ($set_default -is [bool]) { $makeDefault = $set_default }
	elseif ([string]$set_default -match '^(?i)1|true|yes|y|on$') { $makeDefault = $true }
	$details = "Add network printer:`n  path = $unc`n  name = $(if ($friendly) { $friendly } else { '(driver/share default)' })`n  set_default = $makeDefault"
	if (-not (Request-Confirmation -Title "AddNetworkPrinter requires approval" -Details $details)) {
		return "BLOCKED BY USER: AddNetworkPrinter denied."
	}
	try {
		$method = ''
		if (Get-Command Add-Printer -ErrorAction SilentlyContinue) {
			$p = @{ ConnectionName = $unc; ErrorAction = 'Stop' }
			if ($friendly) { $p['Name'] = $friendly }
			Add-Printer @p
			$method = 'Add-Printer'
			$printName = if ($friendly) { $friendly } else { $unc }
			if ($makeDefault -and (Get-Command Set-Printer -ErrorAction SilentlyContinue)) {
				try {
					# Resolve installed name
					$inst = Get-Printer -ErrorAction SilentlyContinue | Where-Object {
						$_.Name -eq $printName -or $_.Name -eq $unc -or $_.ComputerName
					} | Select-Object -First 1
					if (-not $inst) {
						$inst = Get-Printer -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "*$([System.IO.Path]::GetFileName($unc.TrimEnd('\')))*" } | Select-Object -First 1
					}
					if ($inst) {
						$null = Invoke-MBSetupNative -File 'rundll32.exe' -ArgumentList @('printui.dll,PrintUIEntry', '/y', '/n', $inst.Name) -TimeoutSec 30
					}
				} catch {}
			} elseif ($makeDefault) {
				$null = Invoke-MBSetupNative -File 'rundll32.exe' -ArgumentList @('printui.dll,PrintUIEntry', '/y', '/n', $unc) -TimeoutSec 30
			}
		} else {
			$r = Invoke-MBSetupNative -File 'rundll32.exe' -ArgumentList @('printui.dll,PrintUIEntry', '/in', '/n', $unc) -TimeoutSec 120
			if (-not $r.ok) {
				return ConvertTo-MBJson ([ordered]@{ ok = $false; path = $unc; method = 'printui'; exit = $r.exit; out = $r.out; err = $r.err })
			}
			$method = 'printui'
			if ($makeDefault) {
				$null = Invoke-MBSetupNative -File 'rundll32.exe' -ArgumentList @('printui.dll,PrintUIEntry', '/y', '/n', $unc) -TimeoutSec 30
			}
		}
		return ConvertTo-MBJson ([ordered]@{
			ok          = $true
			path        = $unc
			name        = $friendly
			set_default = $makeDefault
			method      = $method
		})
	} catch {
		return "ERROR: AddNetworkPrinter failed: $($_.Exception.Message)"
	}
}

function Test-MBLocalUserCredential {
	# Logon check only (not admin membership). LogonUser first, then local IPC$ net use (SMB path).
	param(
		[string]$Username,
		[string]$Password
	)
	$user = ([string]$Username).Trim()
	if ([string]::IsNullOrWhiteSpace($user)) { return $false }
	if ($null -eq $Password) { return $false }
	$pass = [string]$Password
	try { Ensure-MBLogonHelper } catch {}
	try {
		if ([bool][MiniBot.Native.MBLogon]::ValidateLocalUser($user, $pass)) { return $true }
	} catch {}
	# Fallback: network-style auth used by shares (helps when INTERACTIVE is restricted)
	try {
		$hostName = $env:COMPUTERNAME
		if ([string]::IsNullOrWhiteSpace($hostName)) { $hostName = 'localhost' }
		$ipc = ('\\{0}\IPC$' -f $hostName)
		try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('use', $ipc, '/delete', '/y') -TimeoutSec 8 } catch {}
		$passEsc = $pass -replace '"', '""'
		$userSpec = '.\{0}' -f $user
		$line = 'use {0} /user:{1} "{2}"' -f $ipc, $userSpec, $passEsc
		$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @($line) -TimeoutSec 20
		try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('use', $ipc, '/delete', '/y') -TimeoutSec 8 } catch {}
		if ($r.ok) { return $true }
		# Bare local user form
		try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('use', $ipc, '/delete', '/y') -TimeoutSec 8 } catch {}
		$line2 = 'use {0} /user:{1} "{2}"' -f $ipc, $user, $passEsc
		$r2 = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @($line2) -TimeoutSec 20
		try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('use', $ipc, '/delete', '/y') -TimeoutSec 8 } catch {}
		if ($r2.ok) { return $true }
	} catch {}
	return $false
}

function New-MBLocalShareUserCore {
	# Non-admin local user for share access (caller already confirmed intent).
	param(
		[string]$username,
		[string]$password,
		[string]$full_name = ''
	)
	$user = ([string]$username).Trim()
	$pass = [string]$password
	if ([string]::IsNullOrWhiteSpace($user)) { return @{ ok = $false; error = 'username required' } }
	if ($user -notmatch '^[A-Za-z0-9._-]{1,20}$') { return @{ ok = $false; error = 'username must be 1-20 chars [A-Za-z0-9._-]' } }
	if ([string]::IsNullOrEmpty($pass)) { return @{ ok = $false; error = 'password required' } }
	$fn = ([string]$full_name).Trim()
	if (-not $fn) { $fn = 'MiniBot share access' }
	try {
		$ex = Test-MBLocalUserExists -Username $user
		if ($ex.exists) {
			return @{
				ok     = $false
				exists = $true
				error  = "Local user '$user' already exists"
				method = $ex.method
			}
		}

		$sec = ConvertTo-SecureString -String $pass -AsPlainText -Force
		$addCmd = $null
		if (Get-Command New-LocalUser -ErrorAction SilentlyContinue) { $addCmd = 'New-LocalUser' }
		elseif (Get-Command Add-LocalUser -ErrorAction SilentlyContinue) { $addCmd = 'Add-LocalUser' }

		if ($addCmd) {
			$p = @{
				Name                     = $user
				Password                 = $sec
				FullName                 = $fn
				Description              = 'MiniBot network share access account'
				PasswordNeverExpires     = $true
				UserMayNotChangePassword = $false
				ErrorAction              = 'Stop'
			}
			try {
				if ($addCmd -eq 'New-LocalUser') { New-LocalUser @p | Out-Null }
				else { Add-LocalUser @p | Out-Null }
			} catch {
				$em = $_.Exception.Message
				if ($em -match '(?i)already exists|AccountAlreadyExists') {
					return @{ ok = $false; exists = $true; error = "Local user '$user' already exists"; method = $addCmd }
				}
				$ex2 = Test-MBLocalUserExists -Username $user
				if ($ex2.exists) {
					return @{ ok = $false; exists = $true; error = "Local user '$user' already exists"; method = $addCmd }
				}
				return @{ ok = $false; error = $em; method = $addCmd }
			}
			try { Remove-LocalGroupMember -Group 'Administrators' -Member $user -ErrorAction SilentlyContinue } catch {}
			return @{ ok = $true; username = $user; method = $addCmd; admin = $false; exists = $false }
		}

		# net user fallback only when LocalAccounts missing
		$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user, $pass, '/add') -TimeoutSec 20
		$blob = (([string]$r.out) + "`n" + ([string]$r.err))
		if (-not $r.ok) {
			if (Test-MBNetUserAlreadyExistsMessage -Text $blob) {
				return @{ ok = $false; exists = $true; error = "Local user '$user' already exists"; method = 'net user'; exit = $r.exit }
			}
			$ex3 = Test-MBLocalUserExists -Username $user
			if ($ex3.exists) {
				return @{ ok = $false; exists = $true; error = "Local user '$user' already exists"; method = 'net user'; exit = $r.exit }
			}
			$msg = if ($r.exit -eq -1) {
				'net user timed out creating account.'
			} else {
				"net user failed (exit $($r.exit)): $($r.err) $($r.out)"
			}
			return @{ ok = $false; error = $msg; method = 'net user'; exit = $r.exit }
		}
		try { $null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user, '/comment:MiniBot network share access') -TimeoutSec 12 } catch {}
		return @{ ok = $true; username = $user; method = 'net user'; admin = $false; exists = $false }
	} catch {
		$em = $_.Exception.Message
		if ($em -match '(?i)already exists') {
			return @{ ok = $false; exists = $true; error = "Local user '$user' already exists" }
		}
		return @{ ok = $false; error = $em }
	}
}

function Enable-MBPasswordProtectedSharing {
	# Win10/11 Advanced sharing: password protected sharing ON (not Guest/simple sharing).
	$steps = New-Object System.Collections.ArrayList
	try {
		$lsa = 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa'
		if (Test-Path -LiteralPath $lsa) {
			Set-ItemProperty -LiteralPath $lsa -Name 'ForceGuest' -Value 0 -Type DWord -Force -ErrorAction Stop
			[void]$steps.Add('ForceGuest=0')
			try {
				Set-ItemProperty -LiteralPath $lsa -Name 'everyoneincludesanonymous' -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
				[void]$steps.Add('everyoneincludesanonymous=0')
			} catch {}
		}
	} catch {
		[void]$steps.Add(('Lsa reg failed: {0}' -f $_.Exception.Message))
	}
	# Guest account off
	try {
		if (Get-Command Disable-LocalUser -ErrorAction SilentlyContinue) {
			try { Disable-LocalUser -Name 'Guest' -ErrorAction Stop; [void]$steps.Add('Guest disabled') } catch {
				$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', 'Guest', '/active:no') -TimeoutSec 15
				[void]$steps.Add('Guest /active:no')
			}
		} else {
			$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', 'Guest', '/active:no') -TimeoutSec 15
			[void]$steps.Add('Guest /active:no')
		}
	} catch {
		[void]$steps.Add(('Guest disable note: {0}' -f $_.Exception.Message))
	}
	return @{ ok = $true; steps = @($steps) }
}

function Enable-MBLanmanServer {
	try {
		$svc = Get-Service -Name 'LanmanServer' -ErrorAction Stop
		if ($svc.StartType -eq 'Disabled') {
			try { Set-Service -Name 'LanmanServer' -StartupType Automatic -ErrorAction Stop } catch {}
		}
		if ($svc.Status -ne 'Running') {
			Start-Service -Name 'LanmanServer' -ErrorAction Stop
		}
		return @{ ok = $true; status = 'Running' }
	} catch {
		$r = Invoke-MBSetupNative -File 'sc.exe' -ArgumentList @('config', 'LanmanServer', 'start=', 'auto') -TimeoutSec 15
		$r2 = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('start', 'Server') -TimeoutSec 30
		return @{ ok = [bool]($r2.ok); status = $(if ($r2.ok) { 'Running' } else { 'unknown' }); detail = "$($r.out) $($r2.out) $($r2.err)" }
	}
}

function Get-MBSmb1Status {
	# Report whether SMBv1 client/server bits look enabled (older devices sometimes need it).
	$info = [ordered]@{
		ok              = $true
		enabled         = $false
		server_protocol = $null
		feature_state   = ''
		detail          = ''
	}
	try {
		if (Get-Command Get-SmbServerConfiguration -ErrorAction SilentlyContinue) {
			$cfg = Get-SmbServerConfiguration -ErrorAction SilentlyContinue
			if ($null -ne $cfg -and $null -ne $cfg.EnableSMB1Protocol) {
				$info.server_protocol = [bool]$cfg.EnableSMB1Protocol
				if ($cfg.EnableSMB1Protocol) { $info.enabled = $true }
			}
		}
	} catch {
		$info.detail = $_.Exception.Message
	}
	try {
		if (Get-Command Get-WindowsOptionalFeature -ErrorAction SilentlyContinue) {
			$f = Get-WindowsOptionalFeature -Online -FeatureName 'SMB1Protocol' -ErrorAction SilentlyContinue
			if ($f) {
				$info.feature_state = [string]$f.State
				if ("$($f.State)" -match '(?i)Enabled') { $info.enabled = $true }
			}
		}
	} catch {
		if (-not $info.detail) { $info.detail = $_.Exception.Message }
	}
	# Registry fallback (LanmanServer parameters)
	if ($null -eq $info.server_protocol) {
		try {
			$v = Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters' -Name 'SMB1' -ErrorAction SilentlyContinue
			if ($null -ne $v -and $null -ne $v.SMB1) {
				$info.server_protocol = ([int]$v.SMB1 -ne 0)
				if ($v.SMB1 -ne 0) { $info.enabled = $true }
			}
		} catch {}
	}
	return $info
}

function Enable-MBSmb1Protocol {
	# Best-effort enable SMBv1 server + optional feature (may need reboot on some builds).
	$steps = New-Object System.Collections.ArrayList
	$ok = $false
	try {
		if (Get-Command Set-SmbServerConfiguration -ErrorAction SilentlyContinue) {
			Set-SmbServerConfiguration -EnableSMB1Protocol $true -Force -ErrorAction Stop
			[void]$steps.Add('Set-SmbServerConfiguration EnableSMB1Protocol=true')
			$ok = $true
		}
	} catch {
		[void]$steps.Add(('Set-SmbServerConfiguration failed: {0}' -f $_.Exception.Message))
	}
	try {
		if (Get-Command Enable-WindowsOptionalFeature -ErrorAction SilentlyContinue) {
			$f = Enable-WindowsOptionalFeature -Online -FeatureName 'SMB1Protocol' -All -NoRestart -ErrorAction Stop
			[void]$steps.Add(('Enable-WindowsOptionalFeature SMB1Protocol state={0}' -f $f.State))
			if ("$($f.State)" -match '(?i)Enabled|EnablePending') { $ok = $true }
			if ($f.RestartNeeded) { [void]$steps.Add('restart_needed=true') }
		}
	} catch {
		[void]$steps.Add(('OptionalFeature enable note: {0}' -f $_.Exception.Message))
		# DISM fallback
		$r = Invoke-MBSetupNative -File 'dism.exe' -ArgumentList @('/Online', '/Enable-Feature', '/FeatureName:SMB1Protocol', '/All', '/NoRestart') -TimeoutSec 300
		[void]$steps.Add(('dism SMB1Protocol exit={0}' -f $r.exit))
		if ($r.ok -or $r.exit -eq 3010) { $ok = $true }
		if ($r.exit -eq 3010) { [void]$steps.Add('restart_needed=true') }
	}
	try {
		reg.exe add 'HKLM\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters' /v SMB1 /t REG_DWORD /d 1 /f 2>$null | Out-Null
		[void]$steps.Add('reg LanmanServer\\Parameters SMB1=1')
	} catch {}
	$after = Get-MBSmb1Status
	if ($after.enabled) { $ok = $true }
	return @{
		ok      = $ok
		enabled = [bool]$after.enabled
		steps   = @($steps)
		status  = $after
	}
}

function Request-MBSmb1ForShare {
	# If SMBv1 is off, ask whether older clients need it; enable only on Yes.
	$st = Get-MBSmb1Status
	if ($st.enabled) {
		return @{
			ok       = $true
			enabled  = $true
			action   = 'already_on'
			message  = 'SMBv1 already enabled'
			status   = $st
		}
	}
	$ask = Request-Confirmation -Title "Enable SMBv1 for this share?" -Details @"
SMBv1 is currently OFF on this PC.

Some older devices (legacy printers, NAS, media players, older Windows) still need SMBv1 to connect to a share.
Modern Windows/PCs usually do not (SMBv2/v3 is enough).

Enable SMBv1 now?
  Yes = turn on SMBv1 (may need a reboot later on some systems)
  No  = leave SMBv1 off and continue creating the share with SMBv2/v3 only
"@
	if (-not $ask) {
		return @{
			ok       = $true
			enabled  = $false
			action   = 'left_off'
			message  = 'Operator declined SMBv1; share will use SMBv2/v3 only'
			status   = $st
		}
	}
	$en = Enable-MBSmb1Protocol
	return @{
		ok       = [bool]$en.ok
		enabled  = [bool]$en.enabled
		action   = $(if ($en.enabled) { 'enabled' } else { 'enable_attempted' })
		message  = $(if ($en.enabled) { 'SMBv1 enabled' } else { 'SMBv1 enable attempted (may need reboot or admin)' })
		steps    = $en.steps
		status   = $en.status
	}
}

function Resolve-MBShareAccessRight {
	# Normalize to SMB AccessRight: Full | Change | Read. Default Full when blank/unknown.
	param([string]$Right = '')
	$r = ([string]$Right).Trim().ToLowerInvariant()
	if ([string]::IsNullOrWhiteSpace($r)) { return 'Full' }
	if ($r -match '^(full|f|modify|all)$') { return 'Full' }
	if ($r -match '^(change|c|write|rw|readwrite|read_write|edit)$') { return 'Change' }
	if ($r -match '^(read|r|readonly|read_only|ro)$') { return 'Read' }
	return 'Full'
}

function Grant-MBNtfsAccess {
	# icacls rights: F=Full, M=Modify (~Change), RX=Read+Execute
	param(
		[string]$Path,
		[string]$Identity,
		[string]$AccessRight = 'Full'
	)
	$id = ([string]$Identity).Trim()
	if ([string]::IsNullOrWhiteSpace($id)) { return @{ ok = $false; error = 'identity required' } }
	$smbRight = Resolve-MBShareAccessRight -Right $AccessRight
	$ica = switch ($smbRight) {
		'Change' { 'M' }
		'Read'   { 'RX' }
		default  { 'F' }
	}
	$p = [string]$Path
	$grant = '{0}:(OI)(CI){1}' -f $id, $ica
	$r = Invoke-MBSetupNative -File 'icacls.exe' -ArgumentList @($p, '/grant', $grant, '/C') -TimeoutSec 60
	return @{ ok = $r.ok; identity = $id; right = $smbRight; icacls = $ica; exit = $r.exit; out = $r.out; err = $r.err }
}

function Grant-MBSmbShareAccess {
	param(
		[string]$ShareName,
		[string]$Account,
		[string]$AccessRight = 'Full'
	)
	$acct = ([string]$Account).Trim()
	$name = ([string]$ShareName).Trim()
	$right = Resolve-MBShareAccessRight -Right $AccessRight
	if (Get-Command Grant-SmbShareAccess -ErrorAction SilentlyContinue) {
		try {
			Grant-SmbShareAccess -Name $name -AccountName $acct -AccessRight $right -Force -ErrorAction Stop | Out-Null
			return @{ ok = $true; method = 'Grant-SmbShareAccess'; account = $acct; right = $right }
		} catch {
			return @{ ok = $false; method = 'Grant-SmbShareAccess'; account = $acct; right = $right; error = $_.Exception.Message }
		}
	}
	$netRight = $right.ToUpperInvariant() # FULL | CHANGE | READ
	$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('share', $name, ('/GRANT:{0},{1}' -f $acct, $netRight)) -TimeoutSec 30
	return @{ ok = $r.ok; method = 'net share /GRANT'; account = $acct; right = $right; exit = $r.exit; out = $r.out; err = $r.err }
}

function Format-MBShareAccessHowTo {
	param(
		[string]$HostName,
		[string]$ShareName,
		[string[]]$Users,
		[string[]]$CreatedUsers = @(),
		[hashtable]$CreatedPass = @{},
		[bool]$EveryoneFull = $true
	)
	$uncHost = "\\$HostName\$ShareName"
	$ipList = New-Object System.Collections.ArrayList
	try {
		$ips = @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue |
			Where-Object {
				$_.IPAddress -notlike '127.*' -and
				$_.IPAddress -notlike '169.254.*' -and
				$_.PrefixOrigin -ne 'WellKnown'
			} |
			Select-Object -ExpandProperty IPAddress -Unique)
		foreach ($ip in $ips) {
			if ($ip) { [void]$ipList.Add([string]$ip) }
		}
	} catch {}
	if ($ipList.Count -eq 0) {
		try {
			$cfg = @(Get-CimInstance Win32_NetworkAdapterConfiguration -ErrorAction SilentlyContinue |
				Where-Object { $_.IPEnabled -and $_.IPAddress })
			foreach ($c in $cfg) {
				foreach ($a in @($c.IPAddress)) {
					if ($a -match '^\d+\.\d+\.\d+\.\d+$' -and $a -notlike '127.*' -and $a -notlike '169.254.*') {
						if (-not ($ipList -contains $a)) { [void]$ipList.Add([string]$a) }
					}
				}
			}
		} catch {}
	}
	$primaryIp = if ($ipList.Count -gt 0) { [string]$ipList[0] } else { '' }
	$uncIp = if ($primaryIp) { "\\$primaryIp\$ShareName" } else { '' }
	$ipAllUnc = if ($ipList.Count -gt 0) { ($ipList | ForEach-Object { "\\$_\$ShareName" }) -join '  |  ' } else { '' }

	$lines = New-Object System.Collections.ArrayList
	[void]$lines.Add('HOW TO OPEN THIS SHARE FROM ANOTHER PC')
	[void]$lines.Add('1. Both PCs on the same LAN (prefer Private network profile).')
	[void]$lines.Add('2. On the other PC, File Explorer address bar (hostname):')
	[void]$lines.Add("     $uncHost")
	if ($uncIp) {
		[void]$lines.Add('   If hostname fails (DNS / name resolution), use IP instead:')
		[void]$lines.Add("     $uncIp")
		if ($ipList.Count -gt 1) {
			[void]$lines.Add("   Other local IPs on this PC: $ipAllUnc")
		}
	} else {
		[void]$lines.Add(("   Note: if hostname fails (DNS issues), retry with \\THIS-PC-IP\{0} (check ipconfig on this machine)." -f $ShareName))
	}
	[void]$lines.Add('3. Windows will prompt for credentials (password-protected sharing is ON).')
	[void]$lines.Add('   Use one of these verified accounts:')
	foreach ($u in @($Users)) {
		[void]$lines.Add("     Username: $u   (or $HostName\$u)")
	}
	if ($primaryIp -and $Users -and @($Users).Count -gt 0) {
		$u0 = [string]$Users[0]
		[void]$lines.Add("   When using the IP path, still sign in as $HostName\$u0 (not IP\$u0).")
	} elseif ($primaryIp) {
		[void]$lines.Add("   When using the IP path, still sign in as $HostName\\USER (not IP\\USER).")
	}
	[void]$lines.Add('   Password: the password you just verified for that account.')
	if ($CreatedUsers -and @($CreatedUsers).Count -gt 0) {
		[void]$lines.Add('   New share users created this run:')
		foreach ($cu in @($CreatedUsers)) {
			$pw = if ($CreatedPass -and $CreatedPass.ContainsKey($cu)) { [string]$CreatedPass[$cu] } else { '(set during create)' }
			[void]$lines.Add("     $HostName\$cu  password=$pw")
		}
	}
	[void]$lines.Add('4. Optional map drive (Command Prompt on client):')
	$first = if ($Users -and $Users.Count -gt 0) { $Users[0] } else { 'USERNAME' }
	[void]$lines.Add("     net use Z: $uncHost /user:$HostName\$first *")
	if ($uncIp) {
		[void]$lines.Add("     net use Z: $uncIp /user:$HostName\$first *")
		[void]$lines.Add('     (prefer the IP line when hostname mapping fails due to DNS)')
	}
	[void]$lines.Add('5. Guest is off. Do not use blank passwords.')
	if ($EveryoneFull) {
		[void]$lines.Add('ACL: Everyone=Full on share+NTFS, plus explicit Full for each verified user (Everyone alone often fails).')
	} else {
		[void]$lines.Add('ACL: Everyone not granted; explicit Full for each verified user only.')
	}
	return ($lines -join "`n")
}

function Invoke-CreateShare {
	param(
		[string]$path,
		[string]$name,
		[string]$access_username = '',
		[string]$access_password = '',
		[string]$share_password = '',
		[string]$access_right = '',
		[string]$permission = '',
		[string]$description = '',
		[object]$everyone_full = $null,
		[object]$force_password_update = $false,
		[object]$reset_password = $false,
		[object]$ensure_network = $true,
		[object]$ensure_discovery = $true,
		[object]$ensure_folder = $true,
		[object]$force = $false
	)
	$folder = ([string]$path).Trim().Trim('"')
	$shareName = ([string]$name).Trim()
	$desc = ([string]$description).Trim()
	# Specific local user for share+NTFS grant (created if missing). Not fixed to "share".
	$shareUser = ([string]$access_username).Trim()
	# Password for that access account (share_password kept as alias)
	$pass = [string]$access_password
	if ([string]::IsNullOrEmpty($pass) -and -not [string]::IsNullOrEmpty([string]$share_password)) {
		$pass = [string]$share_password
	}
	# Permission level: Full (default) | Change | Read - not forced Full if caller passes another right
	$rightRaw = ([string]$access_right).Trim()
	if ([string]::IsNullOrWhiteSpace($rightRaw)) { $rightRaw = ([string]$permission).Trim() }
	$accessRight = Resolve-MBShareAccessRight -Right $rightRaw
	if ([string]::IsNullOrWhiteSpace($folder)) { return "ERROR: path required (any local folder to share)." }
	if ([string]::IsNullOrWhiteSpace($shareName)) { return "ERROR: name required (share name for \\\\PC\\name)." }
	if ($shareName -notmatch '^[A-Za-z0-9][A-Za-z0-9._$-]{0,79}$') {
		return "ERROR: share name must be 1-80 chars starting with letter/digit [A-Za-z0-9._$-]."
	}

	# everyone_full is REQUIRED (no silent default) - Windows often needs an explicit user grant
	$missing = New-Object System.Collections.ArrayList
	$everyoneProvided = $false
	$everyoneFull = $false
	if ($null -ne $everyone_full -and "$everyone_full" -ne '') {
		$everyoneProvided = $true
		if ($everyone_full -is [bool]) { $everyoneFull = [bool]$everyone_full }
		elseif ([string]$everyone_full -match '^(?i)1|true|yes|y|on$') { $everyoneFull = $true }
		elseif ([string]$everyone_full -match '^(?i)0|false|no|off$') { $everyoneFull = $false }
		else { $everyoneProvided = $false }
	}
	if (-not $everyoneProvided) { [void]$missing.Add('everyone_full') }
	if ([string]::IsNullOrWhiteSpace($shareUser)) { [void]$missing.Add('access_username') }
	if ([string]::IsNullOrEmpty($pass)) { [void]$missing.Add('access_password') }
	if ($missing.Count -gt 0) {
		return ConvertTo-MBJson ([ordered]@{
			ok         = $false
			need_input = $true
			missing    = @($missing)
			message    = @'
NEED_INPUT: CreateShare needs explicit access choice from the operator (ask in chat, no popup):
  1) everyone_full = true|false  - ALWAYS ask: "Everyone access, or only a specific user?" (Everyone alone often fails on Win10/11; we still grant a named local user the same right.)
  2) access_username - local account for share+NTFS grant (create if missing; e.g. share, bob, tech)
  3) access_password (alias share_password) - password for that account; show it back to the operator
Optional: access_right / permission = Full|Change|Read (default Full if omitted).
Then call CreateShare with path, name, everyone_full, access_username, access_password [, access_right].
'@
			path = $folder
			name = $shareName
			access_right_default = 'Full'
			hint = 'Recommended: everyone_full=true AND a specific access_username. Default permission is Full if not specified.'
		}) -Depth 4
	}
	if ($shareUser -match '^(?i)everyone$') {
		return ConvertTo-MBJson ([ordered]@{
			ok         = $false
			need_input = $true
			missing    = @('access_username')
			message    = 'NEED_INPUT: access_username cannot be Everyone. Set everyone_full=true for Everyone, and pick a real local username (e.g. share) for the explicit grant.'
		}) -Depth 4
	}

	$doNet = $true
	if ($ensure_network -is [bool]) { $doNet = $ensure_network }
	elseif ([string]$ensure_network -match '^(?i)0|false|no|off$') { $doNet = $false }
	$doDisc = $true
	if ($ensure_discovery -is [bool]) { $doDisc = $ensure_discovery }
	elseif ([string]$ensure_discovery -match '^(?i)0|false|no|off$') { $doDisc = $false }
	$doFolder = $true
	if ($ensure_folder -is [bool]) { $doFolder = $ensure_folder }
	elseif ([string]$ensure_folder -match '^(?i)0|false|no|off$') { $doFolder = $false }
	$doForce = $false
	if ($force -is [bool]) { $doForce = $force }
	elseif ([string]$force -match '^(?i)1|true|yes|y|on$') { $doForce = $true }

	try {
		if (-not [System.IO.Path]::IsPathRooted($folder)) {
			$folder = [System.IO.Path]::GetFullPath((Join-Path $script:MB.WorkingDir $folder))
		} else {
			$folder = [System.IO.Path]::GetFullPath($folder)
		}
	} catch {
		return "ERROR: invalid path: $($_.Exception.Message)"
	}

	$hostName = $env:COMPUTERNAME
	try { $hostName = [System.Net.Dns]::GetHostName() } catch {}
	if ([string]::IsNullOrWhiteSpace($hostName)) { $hostName = $env:COMPUTERNAME }

	$aclNote = if ($everyoneFull) {
		"Everyone $accessRight + explicit $accessRight for local user $shareUser (create if missing)"
	} else {
		"ONLY explicit $accessRight for local user $shareUser (create if missing); Everyone NOT granted"
	}
	$details = @"
Create SMB share (password-protected):
  folder            = $folder
  share name        = $shareName
  UNC               = \\$hostName\$shareName
  access username   = $shareUser  (create or update local non-admin)
  access password   = $pass
  access right      = $accessRight  (Full|Change|Read; default Full)
  everyone_full     = $everyoneFull  (Everyone gets same access right when true)
  ACL plan          = $aclNote
  ensure_folder     = $doFolder  (existing paths OK)
  ensure network    = $doNet
  ensure discovery  = $doDisc
  force replace     = $doForce
"@
	if (-not (Request-Confirmation -Title "CreateShare requires approval" -Details $details)) {
		return "BLOCKED BY USER: CreateShare denied."
	}

	$steps = New-Object System.Collections.ArrayList
	$aclLog = New-Object System.Collections.ArrayList
	$chkTotal = 6
	try {
		Write-MBJobChecklist -Job 'CreateShare' -Step 1 -Total $chkTotal -Label 'folder' -Phase start
		# Any existing folder is fine; only create when missing + ensure_folder
		if (-not (Test-Path -LiteralPath $folder)) {
			if (-not $doFolder) {
				return "ERROR: folder does not exist: $folder. Pass an existing path, or ensure_folder=true to create it."
			}
			New-Item -ItemType Directory -Path $folder -Force -ErrorAction Stop | Out-Null
			[void]$steps.Add("created folder $folder")
		} else {
			[void]$steps.Add("using existing folder $folder")
		}
		if (-not (Test-Path -LiteralPath $folder -PathType Container)) {
			return "ERROR: path is not a folder: $folder"
		}
		Write-MBJobChecklist -Job 'CreateShare' -Step 1 -Total $chkTotal -Label 'folder' -Phase ok

		Write-MBJobChecklist -Job 'CreateShare' -Step 2 -Total $chkTotal -Label ("local user $shareUser") -Phase start
		$forcePw = Convert-MBToBool -Value $force_password_update -Default $false
		if (-not $forcePw) {
			try { $forcePw = Convert-MBToBool -Value $reset_password -Default $false } catch {}
		}
		$acct = Ensure-MBShareLocalUser -Username $shareUser -Password $pass -force_password_update $forcePw -reset_password $forcePw
		if (-not $acct.ok) {
			Write-MBJobChecklist -Job 'CreateShare' -Step 2 -Total $chkTotal -Label ("local user $shareUser") -Phase fail
			if ($acct.need_input -or ($acct.error -match '(?i)password does not match|exists but|Could not set password|policy')) {
				return ConvertTo-MBJson ([ordered]@{
					ok         = $false
					need_input = $true
					missing    = @('access_password')
					message    = $(if ($acct.error) { [string]$acct.error } else { "Password for existing user '$shareUser' failed verification." })
					username   = $shareUser
					exists     = $true
					hint       = 'Correct password, or force_password_update=true / reset_password=true to set a new password (must meet local password policy).'
				}) -Depth 4
			}
			return "ERROR: could not prepare local user '$shareUser': $($acct.error)"
		}
		$userStep = if ($acct.created) { 'created' } elseif ($acct.method -eq 'verified_existing') { 'exists (password verified)' } elseif ("$($acct.method)" -match 'force_password') { 'password reset' } else { [string]$acct.method }
		if ($acct.warning) { [void]$steps.Add(('WARN: {0}' -f $acct.warning)) }
		[void]$steps.Add(("local user $shareUser : {0}" -f $userStep))
		Write-MBJobChecklist -Job 'CreateShare' -Step 2 -Total $chkTotal -Label ("local user $shareUser") -Phase ok

		Write-MBJobChecklist -Job 'CreateShare' -Step 3 -Total $chkTotal -Label 'sharing services' -Phase start
		$pps = Enable-MBPasswordProtectedSharing
		[void]$steps.Add(('password-protected sharing: {0}' -f (($pps.steps) -join '; ')))

		$srv = Enable-MBLanmanServer
		[void]$steps.Add(('LanmanServer: {0}' -f $srv.status))

		# SMBv1: check first; if off, ask whether older devices need it
		$smb1 = Request-MBSmb1ForShare
		[void]$steps.Add(('SMBv1: {0} ({1})' -f $smb1.action, $smb1.message))
		if ($smb1.steps) {
			foreach ($s1 in @($smb1.steps)) { [void]$steps.Add(('  SMBv1 step: {0}' -f $s1)) }
		}

		if ($doNet) {
			$fw = Enable-MBFirewallGroup -GroupName 'File and Printer Sharing' -TimeoutSec 15
			[void]$steps.Add(('firewall File and Printer Sharing: {0}' -f $fw.method))
		}
		if ($doDisc) {
			$fw2 = Enable-MBFirewallGroup -GroupName 'Network Discovery' -TimeoutSec 15
			[void]$steps.Add(('firewall Network Discovery: {0}' -f $fw2.method))
		}
		Write-MBJobChecklist -Job 'CreateShare' -Step 3 -Total $chkTotal -Label 'sharing services' -Phase ok

		$exists = $false
		if (Get-Command Get-SmbShare -ErrorAction SilentlyContinue) {
			try { $null = Get-SmbShare -Name $shareName -ErrorAction Stop; $exists = $true } catch { $exists = $false }
		} else {
			$chk = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('share', $shareName) -TimeoutSec 15
			if ($chk.ok -or ($chk.out -match [regex]::Escape($shareName))) { $exists = $true }
		}
		if ($exists) {
			if (-not $doForce) {
				return "ERROR: share '$shareName' already exists. Pass force=true to replace, or pick another name."
			}
			if (Get-Command Remove-SmbShare -ErrorAction SilentlyContinue) {
				try { Remove-SmbShare -Name $shareName -Force -ErrorAction Stop } catch {}
			} else {
				$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('share', $shareName, '/delete', '/y') -TimeoutSec 30
			}
			[void]$steps.Add("removed existing share $shareName")
		}

		# Grant access_username the chosen right (default Full). Everyone optional (same right).
		$grantAccounts = New-Object System.Collections.ArrayList
		if ($everyoneFull) { [void]$grantAccounts.Add('Everyone') }
		[void]$grantAccounts.Add("$hostName\$shareUser")
		$netGrant = $accessRight.ToUpperInvariant() # FULL|CHANGE|READ for net share

		Write-MBJobChecklist -Job 'CreateShare' -Step 4 -Total $chkTotal -Label 'publish share' -Phase start
		$shareMethod = ''
		if (Get-Command New-SmbShare -ErrorAction SilentlyContinue) {
			try {
				$np = @{
					Name        = $shareName
					Path        = $folder
					ErrorAction = 'Stop'
				}
				# Map right to New-SmbShare access lists
				if ($accessRight -eq 'Read') {
					$np['ReadAccess'] = @($grantAccounts)
				} elseif ($accessRight -eq 'Change') {
					$np['ChangeAccess'] = @($grantAccounts)
				} else {
					$np['FullAccess'] = @($grantAccounts)
				}
				if ($desc) { $np['Description'] = $desc }
				try { $np['CachingMode'] = 'None' } catch {}
				New-SmbShare @np | Out-Null
				$shareMethod = 'New-SmbShare'
			} catch {
				try {
					$np2 = @{ Name = $shareName; Path = $folder; ErrorAction = 'Stop' }
					if ($desc) { $np2['Description'] = $desc }
					New-SmbShare @np2 | Out-Null
					$shareMethod = 'New-SmbShare+Grant'
				} catch {
					Write-MBJobChecklist -Job 'CreateShare' -Step 4 -Total $chkTotal -Label 'publish share' -Phase fail
					return "ERROR: New-SmbShare failed: $($_.Exception.Message)"
				}
			}
		} else {
			$netArgs = New-Object System.Collections.ArrayList
			[void]$netArgs.Add('share')
			[void]$netArgs.Add(('{0}={1}' -f $shareName, $folder))
			if ($desc) { [void]$netArgs.Add(('/REMARK:{0}' -f $desc)) }
			foreach ($a in @($grantAccounts)) { [void]$netArgs.Add(('/GRANT:{0},{1}' -f $a, $netGrant)) }
			$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @($netArgs.ToArray()) -TimeoutSec 60
			if (-not $r.ok) {
				Write-MBJobChecklist -Job 'CreateShare' -Step 4 -Total $chkTotal -Label 'publish share' -Phase fail
				return ConvertTo-MBJson ([ordered]@{ ok = $false; error = 'net share failed'; exit = $r.exit; out = $r.out; err = $r.err })
			}
			$shareMethod = 'net share'
		}
		[void]$steps.Add("share created ($shareMethod) right=$accessRight")
		Write-MBJobChecklist -Job 'CreateShare' -Step 4 -Total $chkTotal -Label 'publish share' -Phase ok

		Write-MBJobChecklist -Job 'CreateShare' -Step 5 -Total $chkTotal -Label 'access ACL' -Phase start
		if ($everyoneFull) {
			$g = Grant-MBSmbShareAccess -ShareName $shareName -Account 'Everyone' -AccessRight $accessRight
			[void]$aclLog.Add([ordered]@{ layer = 'share'; account = 'Everyone'; right = $accessRight; ok = $g.ok; detail = $(if ($g.error) { $g.error } else { $g.method }) })
			$n = Grant-MBNtfsAccess -Path $folder -Identity 'Everyone' -AccessRight $accessRight
			[void]$aclLog.Add([ordered]@{ layer = 'ntfs'; account = 'Everyone'; right = $accessRight; ok = $n.ok; detail = $(if ($n.err) { $n.err } else { "exit $($n.exit)" }) })
		}
		# Explicit grant for the access user (always - Windows often needs a named principal)
		$userShareOk = $false
		foreach ($acct in @("$hostName\$shareUser", $shareUser, ".\$shareUser")) {
			$g = Grant-MBSmbShareAccess -ShareName $shareName -Account $acct -AccessRight $accessRight
			if ($g.ok) {
				[void]$aclLog.Add([ordered]@{ layer = 'share'; account = $acct; right = $accessRight; ok = $true; detail = $g.method })
				$userShareOk = $true
				break
			} else {
				[void]$aclLog.Add([ordered]@{ layer = 'share'; account = $acct; right = $accessRight; ok = $false; detail = $(if ($g.error) { $g.error } else { $g.method }) })
			}
		}
		$n = Grant-MBNtfsAccess -Path $folder -Identity $shareUser -AccessRight $accessRight
		if (-not $n.ok) {
			$n = Grant-MBNtfsAccess -Path $folder -Identity "$hostName\$shareUser" -AccessRight $accessRight
		}
		[void]$aclLog.Add([ordered]@{ layer = 'ntfs'; account = $shareUser; right = $accessRight; ok = $n.ok; detail = $(if ($n.err) { $n.err } else { "exit $($n.exit)" }) })
		if (-not $userShareOk) {
			[void]$steps.Add("WARN: could not grant share $accessRight to $shareUser (Everyone may still work if enabled)")
		}
		Write-MBJobChecklist -Job 'CreateShare' -Step 5 -Total $chkTotal -Label 'access ACL' -Phase ok

		Write-MBJobChecklist -Job 'CreateShare' -Step 6 -Total $chkTotal -Label 'verify' -Phase start
		$createdList = @()
		$createdPass = @{}
		if ($acct.created) {
			$createdList = @($shareUser)
			$createdPass[$shareUser] = $pass
		}
		$uncOut = "\\$hostName\$shareName"
		$uncLoop = "\\127.0.0.1\$shareName"
		$verify = Test-MBLocalSharePresent -ShareName $shareName
		$clipOk = $false
		if ($verify.ok) {
			Write-MBJobChecklist -Job 'CreateShare' -Step 6 -Total $chkTotal -Label 'verify' -Phase ok
		} else {
			Write-MBJobChecklist -Job 'CreateShare' -Step 6 -Total $chkTotal -Label 'verify' -Phase fail
		}
		try { [void](Add-MBStickyNote -Text ("Share $uncOut (user $shareUser)") -Kind finding) } catch {}
		$how = Format-MBShareAccessHowTo -HostName $hostName -ShareName $shareName -Users @($shareUser) -CreatedUsers $createdList -CreatedPass $createdPass -EveryoneFull $everyoneFull
		$accessSummary = @($aclLog | Where-Object { $_.ok } | ForEach-Object { '{0}/{1}={2}' -f $_.layer, $_.account, $_.right })
		$card = Write-MBOperatorCard -Title 'SHARE CREATED' -Fields ([ordered]@{
			UNC             = $uncOut
			'UNC (loopback)' = $uncLoop
			Folder          = $folder
			'Access user'   = $shareUser
			Password        = $pass
			Permission      = $accessRight
			'User created'  = [bool]$acct.created
			Everyone        = $everyoneFull
			Verified        = $(if ($verify.ok) { 'yes (' + $verify.detail + ')' } else { 'NO - ' + $verify.detail })
			Clipboard       = 'not copied'
			Access          = ($accessSummary -join '; ')
		}) -Notes @(
			'Map with: MapNetworkDrive path=' + $uncLoop + ' username=' + $shareUser + ' password=(above)'
		)
		$report = [ordered]@{
			ok                 = $true
			path               = $folder
			name               = $shareName
			unc                = $uncOut
			unc_loopback       = $uncLoop
			hostname           = $hostName
			access_username    = $shareUser
			access_user        = $shareUser
			access_password    = $pass
			share_password     = $pass
			access_right       = $accessRight
			share_user_created = [bool]$acct.created
			everyone_full      = $everyoneFull
			password_protected = $true
			smb1               = $(if ($smb1) { [ordered]@{ action = $smb1.action; enabled = $smb1.enabled; message = $smb1.message } } else { $null })
			method             = $shareMethod
			steps              = @($steps)
			acl                = @($aclLog)
			access_summary     = @($accessSummary)
			verified           = [bool]$verify.ok
			verify_detail      = [string]$verify.detail
			clipboard_unc      = $false
			operator_card      = $card
			how_to_access      = $how
		}
		$json = ConvertTo-MBJson $report -Depth 8
		return @"
$card

$how

---
$json
"@
	} catch {
		return "ERROR: CreateShare failed: $($_.Exception.Message)"
	}
}

function Resolve-MBLocalSharePath {
	# Best-effort path for an existing local share name.
	param([string]$ShareName)
	$nm = ([string]$ShareName).Trim()
	if (-not $nm) { return '' }
	try {
		if (Get-Command Get-SmbShare -ErrorAction SilentlyContinue) {
			$s = Get-SmbShare -Name $nm -ErrorAction Stop
			return [string]$s.Path
		}
	} catch {}
	try {
		$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('share', $nm) -TimeoutSec 15
		$blob = (([string]$r.out) + "`n" + ([string]$r.err))
		foreach ($line in ($blob -split "`r?`n")) {
			if ($line -match '(?i)^\s*Path\s+(.+?)\s*$') { return $Matches[1].Trim() }
			if ($line -match '(?i)^\s*Path\s*=\s*(.+?)\s*$') { return $Matches[1].Trim() }
		}
	} catch {}
	return ''
}

function Test-MBIsProtectedShareName {
	param([string]$ShareName)
	$nm = ([string]$ShareName).Trim()
	if ([string]::IsNullOrWhiteSpace($nm)) { return $true }
	# Drive roots C$ D$, admin shares, IPC, PRINT$, FAX$, etc.
	if ($nm -match '^[A-Za-z]\$$') { return $true }
	if ($nm -match '^(?i)(IPC|ADMIN|PRINT|FAX|NETLOGON|SYSVOL)\$$') { return $true }
	if ($nm -match '^(?i)(IPC|ADMIN|PRINT|FAX)$') { return $true }
	return $false
}

function Invoke-RemoveShare {
	param(
		[string]$name = '',
		[string]$share = '',
		[object]$force = $true
	)
	$shareName = ([string]$name).Trim()
	if ([string]::IsNullOrWhiteSpace($shareName)) { $shareName = ([string]$share).Trim() }
	if ([string]::IsNullOrWhiteSpace($shareName)) {
		return ConvertTo-MBJson ([ordered]@{
			ok         = $false
			need_input = $true
			missing    = @('name')
			message    = 'NEED_INPUT: RemoveShare requires name= (share name). Call GetLocalShares first if unknown.'
		}) -Depth 4
	}
	# Accept UNC \\host\share or bare name
	if ($shareName -match '^\\\\[^\\]+\\([^\\]+)\\?$') {
		$shareName = $Matches[1]
	} elseif ($shareName -match '[\\/]') {
		return "ERROR: name must be the share name only (e.g. temp), or UNC \\\\PC\\temp. Not a folder path."
	}
	$shareName = $shareName.Trim().TrimEnd('\')
	if (Test-MBIsProtectedShareName -ShareName $shareName) {
		return "ERROR: refusing to remove special/admin share '$shareName' (C`$/ADMIN`$/IPC`$/PRINT`$ etc.)."
	}

	$doForce = $true
	try { $doForce = Convert-MBToBool -Value $force -Default $true } catch {}

	$hostName = $env:COMPUTERNAME
	try { $hostName = [System.Net.Dns]::GetHostName() } catch {}
	if ([string]::IsNullOrWhiteSpace($hostName)) { $hostName = $env:COMPUTERNAME }

	$present = Test-MBLocalSharePresent -ShareName $shareName
	if (-not $present.ok) {
		return ConvertTo-MBJson ([ordered]@{
			ok      = $false
			error   = "Share '$shareName' not found on this PC."
			name    = $shareName
			hint    = 'Call GetLocalShares to list local shares, then RemoveShare name=...'
		}) -Depth 4
	}
	$folder = [string]$present.path
	if ([string]::IsNullOrWhiteSpace($folder)) {
		$folder = Resolve-MBLocalSharePath -ShareName $shareName
	}
	$uncOut = "\\$hostName\$shareName"

	$details = @"
Remove SMB share (unpublish only - folder stays):
  share name     = $shareName
  UNC            = $uncOut
  folder         = $(if ($folder) { $folder } else { '(path unknown)' })
  force sessions = $doForce
"@
	if (-not (Request-Confirmation -Title "RemoveShare requires approval" -Details $details)) {
		return "BLOCKED BY USER: RemoveShare denied."
	}

	$steps = New-Object System.Collections.ArrayList
	$chkTotal = 2
	try {
		Write-MBJobChecklist -Job 'RemoveShare' -Step 1 -Total $chkTotal -Label 'close sessions' -Phase start
		$sessionClosed = 0
		$fileClosed = 0
		if ($doForce) {
			# Close open files under this share folder only (when path known). Remove-SmbShare -Force still runs.
			try {
				if ($folder -and (Get-Command Get-SmbOpenFile -ErrorAction SilentlyContinue)) {
					$folderPrefix = $folder.TrimEnd('\') + '\'
					$files = @(Get-SmbOpenFile -ErrorAction SilentlyContinue | Where-Object {
						try {
							$p = [string]$_.Path
							if ([string]::IsNullOrWhiteSpace($p)) { return $false }
							return ($p.Equals($folder.TrimEnd('\'), [System.StringComparison]::OrdinalIgnoreCase) -or
								$p.StartsWith($folderPrefix, [System.StringComparison]::OrdinalIgnoreCase))
						} catch { return $false }
					})
					$touchedSessions = @{}
					foreach ($f in $files) {
						try {
							Close-SmbOpenFile -FileId $f.FileId -Force -ErrorAction Stop
							$fileClosed++
							try {
								$sid = [string]$f.SessionId
								if ($sid -and -not $touchedSessions.ContainsKey($sid)) { $touchedSessions[$sid] = $true }
							} catch {}
						} catch {}
					}
					if ((Get-Command Close-SmbSession -ErrorAction SilentlyContinue) -and $touchedSessions.Count -gt 0) {
						foreach ($sid in @($touchedSessions.Keys)) {
							try {
								Close-SmbSession -SessionId $sid -Force -ErrorAction Stop
								$sessionClosed++
							} catch {
								try { Close-SmbSession -SessionId $sid -ErrorAction SilentlyContinue; $sessionClosed++ } catch {}
							}
						}
					}
				}
			} catch {}
		}
		[void]$steps.Add(("closed open_files={0} sessions={1}" -f $fileClosed, $sessionClosed))
		Write-MBJobChecklist -Job 'RemoveShare' -Step 1 -Total $chkTotal -Label 'close sessions' -Phase ok

		Write-MBJobChecklist -Job 'RemoveShare' -Step 2 -Total $chkTotal -Label ("remove $shareName") -Phase start
		$method = ''
		$removeErr = ''
		if (Get-Command Remove-SmbShare -ErrorAction SilentlyContinue) {
			try {
				Remove-SmbShare -Name $shareName -Force -ErrorAction Stop
				$method = 'Remove-SmbShare'
			} catch {
				$removeErr = $_.Exception.Message
			}
		}
		if (-not $method) {
			try {
				$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('share', $shareName, '/delete', '/y') -TimeoutSec 30
				if ($r.ok) {
					$method = 'net share /delete'
				} else {
					$removeErr = ("net share /delete exit={0} {1} {2}" -f $r.exit, $r.out, $r.err)
				}
			} catch {
				if (-not $removeErr) { $removeErr = $_.Exception.Message }
			}
		}
		if (-not $method) {
			Write-MBJobChecklist -Job 'RemoveShare' -Step 2 -Total $chkTotal -Label ("remove $shareName") -Phase fail
			return ConvertTo-MBJson ([ordered]@{
				ok     = $false
				error  = "Failed to remove share '$shareName': $removeErr"
				name   = $shareName
				path   = $folder
			}) -Depth 4
		}
		[void]$steps.Add(("removed share via $method"))
		try { Start-Sleep -Milliseconds 250 } catch {}
		$still = Test-MBLocalSharePresent -ShareName $shareName
		if ($still.ok) {
			Write-MBJobChecklist -Job 'RemoveShare' -Step 2 -Total $chkTotal -Label ("remove $shareName") -Phase fail
			return ConvertTo-MBJson ([ordered]@{
				ok            = $false
				error         = "Share remove reported success ($method) but share still present."
				name          = $shareName
				path          = $folder
				verify_detail = [string]$still.detail
			}) -Depth 4
		}
		Write-MBJobChecklist -Job 'RemoveShare' -Step 2 -Total $chkTotal -Label ("remove $shareName") -Phase ok

		$card = Write-MBOperatorCard -Title 'SHARE REMOVED' -Fields ([ordered]@{
			Share    = $shareName
			UNC      = $uncOut
			Folder   = $(if ($folder) { $folder } else { '(unknown)' })
			Method   = $method
			Verified = 'gone'
		}) -Notes @(
			'Share is unpublished; other PCs can no longer map it.',
			'Folder left on disk (RemoveShare never deletes the folder).'
		)

		$report = [ordered]@{
			ok              = $true
			name            = $shareName
			unc             = $uncOut
			path            = $folder
			method          = $method
			sessions_closed = $sessionClosed
			files_closed    = $fileClosed
			verified        = $true
			verify_detail   = 'share not found after remove'
			steps           = @($steps)
			operator_card   = $card
		}
		$json = ConvertTo-MBJson $report -Depth 8
		return @"
$card

---
$json
"@
	} catch {
		return "ERROR: RemoveShare failed: $($_.Exception.Message)"
	}
}

function Invoke-RemoveMappedDrive {
	param(
		[string]$letter = '',
		[string]$path = '',
		[object]$force = $true
	)
	$let = ([string]$letter).Trim().TrimEnd(':').ToUpperInvariant()
	$uncHint = ([string]$path).Trim()
	if ($let -notmatch '^[A-Z]$') {
		return ConvertTo-MBJson ([ordered]@{
			ok         = $false
			need_input = $true
			missing    = @('letter')
			message    = 'NEED_INPUT: RemoveMappedDrive requires letter= (e.g. Z). Call GetMappedDrives first if unknown.'
		}) -Depth 4
	}
	$doForce = $true
	try { $doForce = Convert-MBToBool -Value $force -Default $true } catch {}

	$present = Test-MBMappedDrivePresent -Letter $let -Unc $uncHint
	if (-not $present.ok) {
		return ConvertTo-MBJson ([ordered]@{
			ok     = $false
			error  = "No network mapping found on ${let}:."
			letter = "${let}:"
			hint   = 'Call GetMappedDrives to list mappings.'
		}) -Depth 4
	}
	$unc = [string]$present.unc
	if ([string]::IsNullOrWhiteSpace($unc) -and $uncHint) { $unc = $uncHint }

	$details = @"
Remove mapped network drive:
  letter = ${let}:
  UNC    = $(if ($unc) { $unc } else { '(unknown)' })
  force  = $doForce
"@
	if (-not (Request-Confirmation -Title "RemoveMappedDrive requires approval" -Details $details)) {
		return "BLOCKED BY USER: RemoveMappedDrive denied."
	}

	try {
		$method = ''
		$errs = New-Object System.Collections.ArrayList
		if (Get-Command Remove-SmbMapping -ErrorAction SilentlyContinue) {
			try {
				Remove-SmbMapping -LocalPath "${let}:" -Force -UpdateProfile -ErrorAction Stop
				$method = 'Remove-SmbMapping'
			} catch {
				[void]$errs.Add(('Remove-SmbMapping: {0}' -f $_.Exception.Message))
			}
		}
		if (-not $method) {
			$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('use', "${let}:", '/delete', '/y') -TimeoutSec 30
			if ($r.ok) {
				$method = 'net use /delete'
			} else {
				[void]$errs.Add(('net use: exit={0} {1} {2}' -f $r.exit, $r.out, $r.err))
			}
		}
		try { Remove-PSDrive -Name $let -Force -PSProvider FileSystem -ErrorAction SilentlyContinue } catch {}
		try { Start-Sleep -Milliseconds 200 } catch {}
		$still = Test-MBMappedDrivePresent -Letter $let
		if ($still.ok -and -not $method) {
			return ConvertTo-MBJson ([ordered]@{
				ok     = $false
				error  = "Failed to remove mapping ${let}: $(($errs | ForEach-Object { $_ }) -join ' | ')"
				letter = "${let}:"
				unc    = $unc
			}) -Depth 4
		}
		if ($still.ok) {
			# Method reported success but still present - try net again
			try {
				$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('use', "${let}:", '/delete', '/y') -TimeoutSec 30
			} catch {}
			try { Start-Sleep -Milliseconds 200 } catch {}
			$still = Test-MBMappedDrivePresent -Letter $let
		}
		$ok = -not $still.ok
		$card = Write-MBOperatorCard -Title 'DRIVE UNMAPPED' -Fields ([ordered]@{
			Letter   = "${let}:"
			UNC      = $(if ($unc) { $unc } else { '(was mapped)' })
			Method   = $(if ($method) { $method } else { 'attempted' })
			Verified = $(if ($ok) { 'gone' } else { 'STILL MAPPED - ' + $still.detail })
		}) -Notes @('Mapping removed from this PC only; remote share is unchanged.')

		return ConvertTo-MBJson ([ordered]@{
			ok            = $ok
			letter        = "${let}:"
			unc           = $unc
			method        = $method
			verified      = $ok
			verify_detail = $(if ($ok) { 'mapping not found after remove' } else { [string]$still.detail })
			errors        = @($errs)
			operator_card = $card
		}) -Depth 6
	} catch {
		return "ERROR: RemoveMappedDrive failed: $($_.Exception.Message)"
	}
}

function Invoke-StopProcess {
	param(
		# Do not name a param $pid - shadows automatic $PID
		[object]$process_id = $null,
		[string]$name = '',
		[object]$force = $true
	)
	$procId = 0
	try {
		if ($null -ne $process_id -and "$process_id" -ne '') { $procId = [int](Convert-MBToInt -Value $process_id -Default 0) }
	} catch { $procId = 0 }
	$procName = ([string]$name).Trim()
	if ($procName -match '\.exe$') { $procName = $procName.Substring(0, $procName.Length - 4) }
	if ($procId -le 0 -and [string]::IsNullOrWhiteSpace($procName)) {
		return ConvertTo-MBJson ([ordered]@{
			ok         = $false
			need_input = $true
			missing    = @('pid', 'name')
			message    = 'NEED_INPUT: StopProcess needs pid= (preferred) and/or name= process name (without .exe). Call GetProcessList first.'
		}) -Depth 4
	}
	$doForce = $true
	try { $doForce = Convert-MBToBool -Value $force -Default $true } catch {}

	# Critical system processes - never kill
	$protected = @(
		'System', 'Idle', 'smss', 'csrss', 'wininit', 'winlogon', 'services', 'lsass',
		'svchost', 'Registry', 'Memory Compression', 'Secure System', 'fontdrvhost',
		'dwm', 'LsaIso', 'SecurityHealthService'
	)
	$targets = New-Object System.Collections.ArrayList
	try {
		if ($procId -gt 0) {
			$p = Get-Process -Id $procId -ErrorAction Stop
			[void]$targets.Add($p)
		} else {
			$found = @(Get-Process -Name $procName -ErrorAction SilentlyContinue)
			if ($found.Count -eq 0) {
				return ConvertTo-MBJson ([ordered]@{
					ok    = $false
					error = "No process named '$procName' found."
					name  = $procName
					hint  = 'Call GetProcessList; use exact ProcessName or pid=.'
				}) -Depth 4
			}
			foreach ($p in $found) { [void]$targets.Add($p) }
		}
	} catch {
		return ConvertTo-MBJson ([ordered]@{
			ok    = $false
			error = "Process not found: $($_.Exception.Message)"
			pid   = $procId
			name  = $procName
		}) -Depth 4
	}

	$selfPid = [int]$PID
	$blocked = New-Object System.Collections.ArrayList
	$killable = New-Object System.Collections.ArrayList
	foreach ($p in $targets) {
		$n = [string]$p.ProcessName
		$id = [int]$p.Id
		if ($id -eq $selfPid -or $id -eq 0) {
			[void]$blocked.Add([ordered]@{ pid = $id; name = $n; reason = 'refusing to kill MiniBot / system idle' })
			continue
		}
		$isProt = $false
		foreach ($pr in $protected) {
			if ($n -eq $pr) { $isProt = $true; break }
		}
		if ($isProt) {
			[void]$blocked.Add([ordered]@{ pid = $id; name = $n; reason = 'protected system process' })
			continue
		}
		[void]$killable.Add($p)
	}
	if ($killable.Count -eq 0) {
		return ConvertTo-MBJson ([ordered]@{
			ok      = $false
			error   = 'No safe process targets to stop.'
			blocked = @($blocked)
		}) -Depth 6
	}

	$lines = New-Object System.Collections.ArrayList
	foreach ($p in $killable) {
		[void]$lines.Add(('  pid={0} name={1} ws_mb={2}' -f $p.Id, $p.ProcessName, [math]::Round($p.WorkingSet64 / 1MB, 1)))
	}
	$details = "Stop process(es):`n$(($lines | ForEach-Object { $_ }) -join "`n")`n  force = $doForce"
	if ($blocked.Count -gt 0) {
		$details += "`n  blocked (skipped): " + (($blocked | ForEach-Object { '{0}({1})' -f $_.name, $_.pid }) -join ', ')
	}
	if (-not (Request-Confirmation -Title "StopProcess requires approval" -Details $details)) {
		return "BLOCKED BY USER: StopProcess denied."
	}

	$results = New-Object System.Collections.ArrayList
	foreach ($p in $killable) {
		$id = [int]$p.Id
		$n = [string]$p.ProcessName
		try {
			if ($doForce) {
				Stop-Process -Id $id -Force -ErrorAction Stop
			} else {
				Stop-Process -Id $id -ErrorAction Stop
			}
			try { Start-Sleep -Milliseconds 150 } catch {}
			$alive = $false
			try { $null = Get-Process -Id $id -ErrorAction Stop; $alive = $true } catch { $alive = $false }
			[void]$results.Add([ordered]@{
				ok     = (-not $alive)
				pid    = $id
				name   = $n
				method = $(if ($doForce) { 'Stop-Process -Force' } else { 'Stop-Process' })
				verified = (-not $alive)
			})
		} catch {
			# taskkill fallback (tree + force)
			try {
				$r = Invoke-MBSetupNative -File 'taskkill.exe' -ArgumentList @('/PID', [string]$id, '/T', '/F') -TimeoutSec 20
				try { Start-Sleep -Milliseconds 200 } catch {}
				$alive = $false
				try { $null = Get-Process -Id $id -ErrorAction Stop; $alive = $true } catch { $alive = $false }
				[void]$results.Add([ordered]@{
					ok     = ($r.ok -or -not $alive)
					pid    = $id
					name   = $n
					method = 'taskkill'
					verified = (-not $alive)
					detail = (([string]$r.out) + ' ' + ([string]$r.err)).Trim()
					error  = $(if ($alive) { $_.Exception.Message } else { $null })
				})
			} catch {
				[void]$results.Add([ordered]@{
					ok    = $false
					pid   = $id
					name  = $n
					error = $_.Exception.Message
				})
			}
		}
	}
	$allOk = ($results | Where-Object { -not $_.ok }).Count -eq 0
	$card = Write-MBOperatorCard -Title 'PROCESS STOPPED' -Fields ([ordered]@{
		Count    = $results.Count
		OK       = @($results | Where-Object { $_.ok }).Count
		Targets  = (($results | ForEach-Object { '{0}({1})' -f $_.name, $_.pid }) -join ', ')
		Verified = $(if ($allOk) { 'yes' } else { 'partial/fail' })
	}) -Notes @('Protected system processes are never killed.')

	return ConvertTo-MBJson ([ordered]@{
		ok            = $allOk
		results       = @($results)
		blocked       = @($blocked)
		operator_card = $card
	}) -Depth 8
}

function Invoke-RemoveLocalUser {
	param(
		[string]$username = '',
		[string]$name = ''
	)
	$user = ([string]$username).Trim()
	if ([string]::IsNullOrWhiteSpace($user)) { $user = ([string]$name).Trim() }
	if ([string]::IsNullOrWhiteSpace($user)) {
		return ConvertTo-MBJson ([ordered]@{
			ok         = $false
			need_input = $true
			missing    = @('username')
			message    = 'NEED_INPUT: RemoveLocalUser requires username=.'
		}) -Depth 4
	}
	if ($user -match '\\') {
		if ($user -match '^(?<d>[^\\]+)\\(?<u>.+)$') {
			$dom = $Matches['d']
			$u = $Matches['u']
			$machine = $env:COMPUTERNAME
			if ($dom -ne '.' -and $dom -ne $machine -and $dom -ne ($machine + '$')) {
				return "ERROR: RemoveLocalUser only removes local accounts (not domain: $user)."
			}
			$user = $u
		}
	}
	if ($user -notmatch '^[A-Za-z0-9._-]{1,20}$') {
		return "ERROR: username must be 1-20 chars [A-Za-z0-9._-]."
	}

	$protectedUsers = @('Administrator', 'Guest', 'DefaultAccount', 'WDAGUtilityAccount', 'systemprofile', 'LocalService', 'NetworkService')
	foreach ($pu in $protectedUsers) {
		if ($user -eq $pu) {
			return "ERROR: refusing to remove protected account '$user'."
		}
	}
	$current = $env:USERNAME
	if ($current -and ($user -eq $current)) {
		return "ERROR: refusing to remove the currently logged-on user '$user'."
	}

	$exists = $false
	if (Get-Command Get-LocalUser -ErrorAction SilentlyContinue) {
		try { $null = Get-LocalUser -Name $user -ErrorAction Stop; $exists = $true } catch { $exists = $false }
	} else {
		$chk = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user) -TimeoutSec 15
		if ($chk.ok -or (([string]$chk.out) -match '(?i)User name')) { $exists = $true }
	}
	if (-not $exists) {
		return ConvertTo-MBJson ([ordered]@{
			ok    = $false
			error = "Local user '$user' not found."
			username = $user
		}) -Depth 4
	}

	$details = "Remove local user account:`n  username = $user`n  (does not delete user profile folder)"
	if (-not (Request-Confirmation -Title "RemoveLocalUser requires approval" -Details $details)) {
		return "BLOCKED BY USER: RemoveLocalUser denied."
	}

	try {
		$method = ''
		$err = ''
		if (Get-Command Remove-LocalUser -ErrorAction SilentlyContinue) {
			try {
				Remove-LocalUser -Name $user -ErrorAction Stop
				$method = 'Remove-LocalUser'
			} catch {
				$err = $_.Exception.Message
			}
		}
		if (-not $method) {
			$r = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('user', $user, '/delete') -TimeoutSec 30
			if ($r.ok) {
				$method = 'net user /delete'
			} else {
				$err = ("net user /delete exit={0} {1} {2}" -f $r.exit, $r.out, $r.err)
			}
		}
		if (-not $method) {
			return ConvertTo-MBJson ([ordered]@{
				ok       = $false
				error    = "Failed to remove user '$user': $err"
				username = $user
			}) -Depth 4
		}
		$still = $false
		if (Get-Command Get-LocalUser -ErrorAction SilentlyContinue) {
			try { $null = Get-LocalUser -Name $user -ErrorAction Stop; $still = $true } catch { $still = $false }
		}
		$card = Write-MBOperatorCard -Title 'LOCAL USER REMOVED' -Fields ([ordered]@{
			Username = $user
			Method   = $method
			Verified = $(if (-not $still) { 'gone' } else { 'STILL EXISTS' })
		}) -Notes @('User profile folder under C:\Users remains (not deleted).')

		return ConvertTo-MBJson ([ordered]@{
			ok            = (-not $still)
			username      = $user
			method        = $method
			verified      = (-not $still)
			operator_card = $card
		}) -Depth 6
	} catch {
		return "ERROR: RemoveLocalUser failed: $($_.Exception.Message)"
	}
}

function Invoke-Reboot {
	param(
		[string]$action = 'reboot',
		[object]$delay_sec = 60,
		[string]$reason = '',
		[object]$force = $true
	)
	$act = ([string]$action).Trim().ToLowerInvariant()
	if ([string]::IsNullOrWhiteSpace($act)) { $act = 'reboot' }
	if ($act -match '^(restart|reboot|r)$') { $act = 'reboot' }
	elseif ($act -match '^(shutdown|poweroff|halt|s)$') { $act = 'shutdown' }
	elseif ($act -match '^(abort|cancel|a)$') { $act = 'abort' }
	else {
		return "ERROR: action must be reboot | shutdown | abort (got '$action')."
	}

	$delay = 60
	try { $delay = [int](Convert-MBToInt -Value $delay_sec -Default 60) } catch { $delay = 60 }
	if ($delay -lt 0) { $delay = 0 }
	if ($delay -gt 86400) { $delay = 86400 }
	$doForce = $true
	try { $doForce = Convert-MBToBool -Value $force -Default $true } catch {}
	$why = ([string]$reason).Trim()
	if ([string]::IsNullOrWhiteSpace($why)) {
		$why = if ($act -eq 'shutdown') { 'MiniBot scheduled shutdown' } else { 'MiniBot scheduled reboot' }
	}
	# shutdown.exe /c max ~512 chars
	if ($why.Length -gt 200) { $why = $why.Substring(0, 200) }

	if ($act -eq 'abort') {
		$details = "Abort pending shutdown/reboot on this PC."
		if (-not (Request-Confirmation -Title "Reboot abort requires approval" -Details $details)) {
			return "BLOCKED BY USER: Reboot abort denied."
		}
		try {
			$r = Invoke-MBSetupNative -File 'shutdown.exe' -ArgumentList @('/a') -TimeoutSec 15
			$ok = $r.ok -or (([string]$r.err + [string]$r.out) -match '(?i)no.*shutdown|was aborted|1116')
			# exit 1116 = no shutdown in progress - treat as ok-ish
			$blob = (([string]$r.out) + ' ' + ([string]$r.err)).Trim()
			$card = Write-MBOperatorCard -Title 'SHUTDOWN ABORTED' -Fields ([ordered]@{
				Action = 'abort'
				Result = $(if ($r.ok) { 'aborted pending shutdown' } elseif ($blob -match '(?i)1116|no') { 'none was pending' } else { $blob })
			})
			return ConvertTo-MBJson ([ordered]@{
				ok            = $true
				action        = 'abort'
				exit          = $r.exit
				out           = $r.out
				err           = $r.err
				operator_card = $card
			}) -Depth 6
		} catch {
			return "ERROR: Reboot abort failed: $($_.Exception.Message)"
		}
	}

	$label = if ($act -eq 'shutdown') { 'SHUTDOWN' } else { 'REBOOT' }
	$details = @"
Schedule PC ${label}:
  action    = $act
  delay_sec = $delay  (0 = immediate)
  force     = $doForce  (close apps)
  reason    = $why
  abort later with: Reboot action=abort
"@
	if (-not (Request-Confirmation -Title "Reboot requires approval" -Details $details)) {
		return "BLOCKED BY USER: Reboot denied."
	}

	try {
		$args = New-Object System.Collections.ArrayList
		if ($act -eq 'shutdown') { [void]$args.Add('/s') } else { [void]$args.Add('/r') }
		[void]$args.Add('/t')
		[void]$args.Add([string]$delay)
		if ($doForce) { [void]$args.Add('/f') }
		[void]$args.Add('/c')
		[void]$args.Add($why)
		$r = Invoke-MBSetupNative -File 'shutdown.exe' -ArgumentList @($args.ToArray()) -TimeoutSec 20
		if (-not $r.ok) {
			return ConvertTo-MBJson ([ordered]@{
				ok     = $false
				action = $act
				error  = "shutdown.exe failed exit=$($r.exit)"
				out    = $r.out
				err    = $r.err
			}) -Depth 4
		}
		$card = Write-MBOperatorCard -Title $label -Fields ([ordered]@{
			Action = $act
			Delay  = "${delay}s"
			Force  = $doForce
			Reason = $why
		}) -Notes @(
			"PC will $act in ${delay}s.",
			'Abort with Reboot action=abort before the timer expires.'
		)
		return ConvertTo-MBJson ([ordered]@{
			ok            = $true
			action        = $act
			delay_sec     = $delay
			force         = $doForce
			reason        = $why
			method        = 'shutdown.exe'
			operator_card = $card
		}) -Depth 6
	} catch {
		return "ERROR: Reboot failed: $($_.Exception.Message)"
	}
}

function Invoke-GetPrinters {
	param(
		[object]$include_remote = $true,
		[object]$max = 80
	)
	$incRemote = $true
	try { $incRemote = Convert-MBToBool -Value $include_remote -Default $true } catch {}
	$limit = 80
	try { $limit = [int](Convert-MBToInt -Value $max -Default 80) } catch { $limit = 80 }
	if ($limit -lt 1) { $limit = 1 }
	if ($limit -gt 300) { $limit = 300 }

	$list = New-Object System.Collections.ArrayList
	try {
		if (Get-Command Get-Printer -ErrorAction SilentlyContinue) {
			$printers = @(Get-Printer -ErrorAction Stop)
			foreach ($p in $printers) {
				if ($list.Count -ge $limit) { break }
				try {
					$type = ''
					try { $type = [string]$p.Type } catch {}
					$port = ''
					try { $port = [string]$p.PortName } catch {}
					$shared = $false
					try { $shared = [bool]$p.Shared } catch {}
					$default = $false
					try { $default = [bool]$p.Default } catch {}
					$driver = ''
					try { $driver = [string]$p.DriverName } catch {}
					$computer = ''
					try { $computer = [string]$p.ComputerName } catch {}
					if (-not $incRemote -and $port -match '^\\\\') { continue }
					[void]$list.Add([ordered]@{
						name         = [string]$p.Name
						share_name   = $(try { [string]$p.ShareName } catch { '' })
						port         = $port
						driver       = $driver
						type         = $type
						shared       = $shared
						is_default   = $default
						computer     = $computer
						published    = $(try { [bool]$p.Published } catch { $false })
					})
				} catch {}
			}
		} else {
			# WMI fallback
			$printers = @(Get-CimInstance Win32_Printer -ErrorAction Stop)
			foreach ($p in $printers) {
				if ($list.Count -ge $limit) { break }
				$port = [string]$p.PortName
				if (-not $incRemote -and $port -match '^\\\\') { continue }
				[void]$list.Add([ordered]@{
					name       = [string]$p.Name
					share_name = [string]$p.ShareName
					port       = $port
					driver     = [string]$p.DriverName
					type       = $(if ($p.Network) { 'Connection' } else { 'Local' })
					shared     = [bool]$p.Shared
					is_default = [bool]$p.Default
					computer   = [string]$p.SystemName
				})
			}
		}
	} catch {
		return "ERROR: GetPrinters failed: $($_.Exception.Message)"
	}

	return ConvertTo-MBJson ([ordered]@{
		ok       = $true
		count    = $list.Count
		printers = @($list)
		note     = 'Local + network printers on THIS PC. Remove with RemoveNetworkPrinter name=...'
	}) -Depth 8
}

function Invoke-RemoveNetworkPrinter {
	param(
		[string]$name = '',
		[string]$path = ''
	)
	$printerName = ([string]$name).Trim()
	if ([string]::IsNullOrWhiteSpace($printerName)) { $printerName = ([string]$path).Trim() }
	if ([string]::IsNullOrWhiteSpace($printerName)) {
		return ConvertTo-MBJson ([ordered]@{
			ok         = $false
			need_input = $true
			missing    = @('name')
			message    = 'NEED_INPUT: RemoveNetworkPrinter requires name= (printer name from GetPrinters) or path= UNC.'
		}) -Depth 4
	}

	# Resolve exact name if possible
	$resolved = $printerName
	$found = $null
	try {
		if (Get-Command Get-Printer -ErrorAction SilentlyContinue) {
			$found = Get-Printer -Name $printerName -ErrorAction SilentlyContinue | Select-Object -First 1
			if (-not $found) {
				$found = Get-Printer -ErrorAction SilentlyContinue | Where-Object {
					$_.Name -eq $printerName -or $_.Name -eq $printerName.TrimEnd('\') -or
					($_.ShareName -and $_.ShareName -eq $printerName) -or
					($_.PortName -and $_.PortName -eq $printerName)
				} | Select-Object -First 1
			}
			if ($found) { $resolved = [string]$found.Name }
		}
	} catch {}

	if (-not $found -and $printerName -notmatch '^\\\\' ) {
		# still allow remove attempt by name
	}

	$details = "Remove printer:`n  name = $resolved`n  (requested: $printerName)"
	if (-not (Request-Confirmation -Title "RemoveNetworkPrinter requires approval" -Details $details)) {
		return "BLOCKED BY USER: RemoveNetworkPrinter denied."
	}

	try {
		$method = ''
		$err = ''
		if (Get-Command Remove-Printer -ErrorAction SilentlyContinue) {
			try {
				Remove-Printer -Name $resolved -ErrorAction Stop
				$method = 'Remove-Printer'
			} catch {
				$err = $_.Exception.Message
			}
		}
		if (-not $method) {
			$r = Invoke-MBSetupNative -File 'rundll32.exe' -ArgumentList @('printui.dll,PrintUIEntry', '/dl', '/n', $resolved) -TimeoutSec 60
			if ($r.ok) {
				$method = 'printui /dl'
			} else {
				# try UNC form
				if ($printerName -match '^\\\\') {
					$r2 = Invoke-MBSetupNative -File 'rundll32.exe' -ArgumentList @('printui.dll,PrintUIEntry', '/dn', '/n', $printerName) -TimeoutSec 60
					if ($r2.ok) {
						$method = 'printui /dn'
					} else {
						$err = ("printui exit={0} {1} {2}" -f $r.exit, $r.out, $r.err)
					}
				} else {
					$err = ("printui exit={0} {1} {2}" -f $r.exit, $r.out, $r.err)
				}
			}
		}
		if (-not $method) {
			return ConvertTo-MBJson ([ordered]@{
				ok    = $false
				error = "Failed to remove printer '$resolved': $err"
				name  = $resolved
			}) -Depth 4
		}
		$still = $false
		try {
			if (Get-Command Get-Printer -ErrorAction SilentlyContinue) {
				$still = [bool](Get-Printer -Name $resolved -ErrorAction SilentlyContinue)
			}
		} catch { $still = $false }

		$card = Write-MBOperatorCard -Title 'PRINTER REMOVED' -Fields ([ordered]@{
			Name     = $resolved
			Method   = $method
			Verified = $(if (-not $still) { 'gone' } else { 'STILL PRESENT' })
		})

		return ConvertTo-MBJson ([ordered]@{
			ok            = (-not $still)
			name          = $resolved
			method        = $method
			verified      = (-not $still)
			operator_card = $card
		}) -Depth 6
	} catch {
		return "ERROR: RemoveNetworkPrinter failed: $($_.Exception.Message)"
	}
}

function Get-MBInstallerCatalog {
	if ($script:MBInstallerCatalog -and @($script:MBInstallerCatalog.Keys).Count -gt 0) {
		return $script:MBInstallerCatalog
	}
	return [ordered]@{}
}

function Write-MBSetupProgress {
	# Progress: settings same-line OK/FAIL; software blank + Installed/Not Installed
	param(
		[ValidateSet('start','ok','fail','info')]
		[string]$Phase,
		[int]$Index = 0,
		[int]$Total = 0,
		[string]$Title = '',
		[string]$Detail = '',
		[switch]$Software
	)
	$title = ([string]$Title).Trim()
	if ($title.Length -eq 0) { $title = 'step' }
	$startLabel = $title
	if ($Phase -eq 'start') {
		if ($startLabel -match '^(?i)Enable\s+(.+)$') { $startLabel = "Enabling $($Matches[1])" }
		elseif ($startLabel -match '^(?i)Disable\s+(.+)$') { $startLabel = "Disabling $($Matches[1])" }
		elseif ($startLabel -match '^(?i)Create\s+(.+)$') { $startLabel = "Creating $($Matches[1])" }
		elseif ($startLabel -match '^(?i)Show\s+(.+)$') { $startLabel = "Showing $($Matches[1])" }
		elseif ($startLabel -match '^(?i)Set\s+(.+)$') { $startLabel = "Setting $($Matches[1])" }
		elseif ($startLabel -match '^(?i)Sync\s+(.+)$') { $startLabel = "Syncing $($Matches[1])" }
		elseif ($startLabel -match '^(?i)SOFTWARE:\s*(.+)$') { $startLabel = $Matches[1] }
	}
	$prefix = if ($Total -gt 0 -and $Index -gt 0) {
		"{0}/{1}" -f $Index, $Total
	} else {
		''
	}
	$detail = ([string]$Detail).Trim()
	if ($null -eq $script:MB.SetupProgressOpenLine) { $script:MB.SetupProgressOpenLine = $false }
	try {
		switch ($Phase) {
			'start' {
				if ($script:MB.SetupProgressOpenLine) {
					Write-Host ''
					$script:MB.SetupProgressOpenLine = $false
				}
				$msg = if ($prefix) { "{0} {1}..." -f $prefix, $startLabel } else { "{0}..." -f $startLabel }
				Write-Host ("  {0}" -f $msg) -ForegroundColor Cyan -NoNewline
				$script:MB.SetupProgressOpenLine = $true
			}
			'ok' {
				if ($Software) {
					if ($script:MB.SetupProgressOpenLine) {
						Write-Host ''
						$script:MB.SetupProgressOpenLine = $false
					}
					Write-Host ''
					$msg = if ($detail) { "  Installed  ($detail)" } else { '  Installed' }
					Write-Host $msg -ForegroundColor Green
					Write-Host ''
				} else {
					$msg = if ($detail) { " OK  ($detail)" } else { ' OK' }
					if ($script:MB.SetupProgressOpenLine) {
						Write-Host $msg -ForegroundColor Green
						$script:MB.SetupProgressOpenLine = $false
					} else {
						Write-Host ("  {0}" -f $msg.TrimStart()) -ForegroundColor Green
					}
				}
			}
			'fail' {
				if ($Software) {
					if ($script:MB.SetupProgressOpenLine) {
						Write-Host ''
						$script:MB.SetupProgressOpenLine = $false
					}
					Write-Host ''
					$msg = if ($detail) { "  Not Installed  - $detail" } else { '  Not Installed' }
					Write-Host $msg -ForegroundColor Red
					Write-Host ''
				} else {
					$msg = if ($detail) { " FAIL - $detail" } else { ' FAIL' }
					if ($script:MB.SetupProgressOpenLine) {
						Write-Host $msg -ForegroundColor Red
						$script:MB.SetupProgressOpenLine = $false
					} else {
						Write-Host ("  {0}" -f $msg.TrimStart()) -ForegroundColor Red
					}
				}
			}
			'info' {
				if ($script:MB.SetupProgressOpenLine) {
					Write-Host ''
					$script:MB.SetupProgressOpenLine = $false
				}
				$msg = if ($detail) { "{0}: {1}" -f $title, $detail } else { $title }
				Write-Host ("    {0}" -f $msg) -ForegroundColor DarkGray
			}
		}
	} catch {}
}

function Get-MBSevenZipPath {
	@(
		"${env:ProgramFiles}\7-Zip\7z.exe",
		"${env:ProgramFiles(x86)}\7-Zip\7z.exe"
	) | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -First 1
}

function Invoke-MBEnsureSevenZipForExtract {
	param(
		[string]$Reason = 'extract a package archive',
		[bool]$SkipExtraApprovals = $false
	)
	$z7 = Get-MBSevenZipPath
	if ($z7) {
		if (-not $SkipExtraApprovals) {
			$details = "Use installed 7-Zip to $Reason`n  path = $z7"
			if (-not (Request-Confirmation -Title "Use 7-Zip for extraction?" -Details $details)) {
				return @{ ok = $false; error = 'operator denied use of 7-Zip for extraction' }
			}
		}
		return @{ ok = $true; path = $z7; installed = $false }
	}

	if ($SkipExtraApprovals) {
		return @{ ok = $false; error = '7-Zip not installed and extra approvals skipped' }
	}
	$details = @(
		"7-Zip is required to $Reason (built-in .NET zip extract failed or is unavailable)."
		"MiniBot can download and silent-install 7-Zip from the catalog at the top of MiniBot.ps1, then continue."
		"Temp files are cleaned up after."
	) -join "`n"
	if (-not (Request-Confirmation -Title "Install 7-Zip for extraction?" -Details $details)) {
		return @{ ok = $false; error = 'operator denied 7-Zip install for extraction' }
	}
	$cat = Get-MBInstallerCatalog
	if (-not $cat.Contains('7zip')) {
		return @{ ok = $false; error = '7zip package missing from MBInstallerCatalog (top of script)' }
	}
	$work = New-MBTempDir -Prefix 'MiniBot7z'
	try {
		$r = Invoke-MBSetupInstallPackage -Package $cat['7zip'] -WorkDir $work -Cleanup $true -SkipExtraApprovals $true
		if (-not $r.ok) {
			return @{ ok = $false; error = "7-Zip install failed: $($r.error)$($r.err)" }
		}
		$z7 = Get-MBSevenZipPath
		if (-not $z7) {
			return @{ ok = $false; error = '7-Zip install finished but 7z.exe was not found' }
		}
		return @{ ok = $true; path = $z7; installed = $true }
	} finally {
		try { Remove-MBTempPath -Path $work } catch {}
	}
}

function Get-MBNewMachineSoftwareManifest {
	param([string]$Profile)
	# Release: full default catalog every time (profile only affects settings notes).
	$cat = Get-MBInstallerCatalog
	$list = New-Object System.Collections.ArrayList
	foreach ($key in @($cat.Keys)) {
		[void]$list.Add($cat[$key])
	}
	return @($list)
}

function Invoke-MBSetupDownloadFile {
	param(
		[string]$Url,
		[string]$OutPath,
		[int]$TimeoutSec = 900,
		[string]$Label = ''
	)
	if ([string]::IsNullOrWhiteSpace($Url) -or [string]::IsNullOrWhiteSpace($OutPath)) {
		return @{ ok = $false; error = 'url/out required' }
	}
	$lab = ([string]$Label).Trim()
	if ($lab.Length -eq 0) {
		$leaf = [System.IO.Path]::GetFileName($OutPath)
		$lab = if ($leaf) { "Downloading $leaf" } else { 'Downloading' }
	} elseif ($lab -notmatch '(?i)^download') {
		$lab = "Downloading $lab"
	}
	$r = Invoke-MBHttpDownload -Url $Url -OutPath $OutPath -TimeoutSec $TimeoutSec `
		-UserAgent 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) MiniBot-Installers' `
		-Label $lab -ShowProgress
	if (-not $r.ok) {
		return @{ ok = $false; error = $(if ($r.error) { $r.error } else { 'download failed' }) }
	}
	if (-not (Test-Path -LiteralPath $OutPath)) {
		return @{ ok = $false; error = 'download failed or file missing' }
	}
	$len = [int64]$r.bytes
	try { $len = (Get-Item -LiteralPath $OutPath).Length } catch {}
	if ($len -lt 64) { return @{ ok = $false; error = "download too small ($len bytes)" } }
	return @{ ok = $true; path = $OutPath; bytes = $len; final_url = $r.final_url }
}

function Invoke-MBSetupInstallPackage {
	param(
		$Package,
		[string]$WorkDir,
		[bool]$Cleanup = $true,
		[bool]$SkipExtraApprovals = $false
	)
	if (-not $Package) { return @{ ok = $false; error = 'no package' } }
	$kind = [string]$Package.kind
	$name = [string]$Package.name
	$created = New-Object System.Collections.ArrayList
	$ownWorkDir = $false

	try {
		if ($kind -eq 'open_url') {
			Write-MBSetupProgress -Phase info -Title $name -Detail 'opening URL'
			try {
				Start-Process -FilePath ([string]$Package.url) -ErrorAction Stop | Out-Null
				return @{ ok = $true; name = $name; kind = 'open_url'; url = [string]$Package.url }
			} catch {
				try {
					Start-Process -FilePath 'cmd.exe' -ArgumentList @('/c', 'start', '', [string]$Package.url) -WindowStyle Hidden | Out-Null
					return @{ ok = $true; name = $name; kind = 'open_url'; url = [string]$Package.url }
				} catch {
					return @{ ok = $false; name = $name; kind = 'open_url'; error = $_.Exception.Message }
				}
			}
		}

		if ([string]::IsNullOrWhiteSpace($WorkDir)) {
			$WorkDir = New-MBTempDir -Prefix 'MiniBotInstall'
			$ownWorkDir = $true
		} else {
			if (-not (Test-Path -LiteralPath $WorkDir)) {
				New-Item -ItemType Directory -Path $WorkDir -Force | Out-Null
			}
			try { Register-MBTempPath -Path $WorkDir } catch {}
		}

		$out = Join-Path $WorkDir ([string]$Package.file)
		$dl = Invoke-MBSetupDownloadFile -Url ([string]$Package.url) -OutPath $out -TimeoutSec 900 -Label $name
		if (-not $dl.ok) {
			return @{ ok = $false; name = $name; phase = 'download'; error = $dl.error }
		}
		[void]$created.Add($out)
		Write-MBSetupProgress -Phase info -Title $name -Detail ("downloaded {0}" -f (Format-MBByteSize ([int64]$dl.bytes)))

		if ($kind -eq 'zip_msi') {
			$entry = [string]$Package.zip_entry
			if ([string]::IsNullOrWhiteSpace($entry)) { $entry = 'GoogleChromeStandaloneEnterprise64.msi' }
			$msiPath = Join-Path $WorkDir $entry
			$extracted = $false
			$netErr = $null
			try {
				Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
				$zip = [System.IO.Compression.ZipFile]::OpenRead($out)
				try {
					foreach ($e in $zip.Entries) {
						if ($e.Name -eq $entry -or ($e.FullName -replace '\\','/') -like "*/$entry" -or $e.FullName -eq $entry) {
							[System.IO.Compression.ZipFileExtensions]::ExtractToFile($e, $msiPath, $true)
							$extracted = $true
							break
						}
					}
					if (-not $extracted) {
						foreach ($e in $zip.Entries) {
							if ($e.Name -match '\.msi$') {
								$msiPath = Join-Path $WorkDir $e.Name
								[System.IO.Compression.ZipFileExtensions]::ExtractToFile($e, $msiPath, $true)
								$extracted = $true
								break
							}
						}
					}
					if (-not $extracted) { throw "zip missing $entry" }
				} finally { $zip.Dispose() }
			} catch {
				$netErr = $_.Exception.Message
				$extracted = $false
			}

			if (-not $extracted) {
				$ens = Invoke-MBEnsureSevenZipForExtract -Reason "extract MSI from $name zip" -SkipExtraApprovals $SkipExtraApprovals
				if (-not $ens.ok) {
					return @{ ok = $false; name = $name; phase = 'extract'; error = $ens.error; net_error = $netErr }
				}
				$r7 = Invoke-MBSetupNative -File $ens.path -ArgumentList @('e', '-y', "-o$WorkDir", $out, $entry) -TimeoutSec 300
				if (-not (Test-Path -LiteralPath $msiPath)) {
					$msiPath = Get-ChildItem -LiteralPath $WorkDir -Filter *.msi -ErrorAction SilentlyContinue | Select-Object -First 1 -ExpandProperty FullName
				}
				if (-not $msiPath -or -not (Test-Path -LiteralPath $msiPath)) {
					return @{ ok = $false; name = $name; phase = 'extract'; error = "7z extract failed: $($r7.err)"; exit = $r7.exit }
				}
			}
			[void]$created.Add($msiPath)
			Write-MBSetupProgress -Phase info -Title $name -Detail 'installing MSI (silent)'
			$inst = Get-MBPackageInstallArgs -Package $Package
			$r = Invoke-MBSetupStartWait -FilePath $msiPath -InstallArgs $inst -TimeoutSec 1200
			$okExit = $r.ok -or ($r.exit -in @(0, 3010, 1641))
			return @{
				ok = $okExit; name = $name; phase = 'install'; kind = 'zip_msi'
				exit = $r.exit; err = $r.err; out = $r.out; final_url = $dl.final_url
				msi = $msiPath; cmd = $r.cmd
			}
		}

		if ($kind -eq 'msi') {
			Write-MBSetupProgress -Phase info -Title $name -Detail 'installing MSI (silent)'
			$inst = Get-MBPackageInstallArgs -Package $Package
			$r = Invoke-MBSetupStartWait -FilePath $out -InstallArgs $inst -TimeoutSec 1200
			$okExit = $r.ok -or ($r.exit -in @(0, 3010, 1641))
			return @{
				ok = $okExit; name = $name; phase = 'install'; kind = 'msi'
				exit = $r.exit; err = $r.err; final_url = $dl.final_url; cmd = $r.cmd
			}
		}

		$isInteractive = Test-MBPackageInteractive -Package $Package
		$runLabel = if ($isInteractive -or $Package.runs_scan -or $Package.id -eq 'adwcleaner') {
			'running scan/clean (interactive UI)'
		} else {
			'installing (silent)'
		}
		Write-MBSetupProgress -Phase info -Title $name -Detail $runLabel
		$inst = Get-MBPackageInstallArgs -Package $Package
		if ($isInteractive) {
			$r = Invoke-MBSetupStartWait -FilePath $out -InstallArgs $inst -TimeoutSec 1200 -Interactive
		} else {
			$r = Invoke-MBSetupStartWait -FilePath $out -InstallArgs $inst -TimeoutSec 1200
		}
		$okExit = $r.ok -or ($r.exit -in @(0, 3010, 1641))
		return @{
			ok = $okExit; name = $name; phase = 'install'; kind = 'exe'
			exit = $r.exit; err = $r.err; final_url = $dl.final_url; cmd = $r.cmd
			interactive = $isInteractive
		}
	} catch {
		return @{ ok = $false; name = $name; phase = 'install'; error = $_.Exception.Message }
	} finally {
		if ($Cleanup) {
			foreach ($f in @($created)) {
				try { if ($f) { Remove-MBTempPath -Path $f } } catch {}
			}
			if ($ownWorkDir -and $WorkDir) {
				try { Remove-MBTempPath -Path $WorkDir } catch {}
			} elseif ($WorkDir) {
				# Caller-owned dir may still hold payload files; unregister only if empty after file cleanup
				try {
					$left = @(Get-ChildItem -LiteralPath $WorkDir -Force -ErrorAction SilentlyContinue)
					if ($left.Count -eq 0) { Remove-MBTempPath -Path $WorkDir }
				} catch {}
			}
		}
	}
}

function Invoke-ListInstallers {
	param([string]$profile = 'all')
	# Default catalog: list every package (profile filter ignored).
	$cat = Get-MBInstallerCatalog
	$rows = @()
	foreach ($key in @($cat.Keys)) {
		$p = $cat[$key]
		$runsScan = $false
		try { $runsScan = [bool]$p.runs_scan } catch { $runsScan = ($p.id -eq 'adwcleaner') }
		$rows += [ordered]@{
			id        = [string]$p.id
			name      = [string]$p.name
			kind      = [string]$p.kind
			install   = (Get-MBPackageInstallArgs -Package $p)
			runs_scan = $runsScan
			note      = [string]$p.note
		}
	}
	return ConvertTo-MBJson ([ordered]@{
		ok       = $true
		count    = $rows.Count
		note     = 'Silent installs; temp files cleaned after each package. ADWCleaner runs a scan/clean.'
		packages = $rows
	}) -Depth 6
}

function Invoke-InstallPackage {
	param(
		[string]$package = '',
		$packages = $null
	)
	$ids = New-Object System.Collections.ArrayList
	if ($packages) {
		foreach ($x in @($packages)) {
			if ($x -and [string]$x -ne '') { [void]$ids.Add(([string]$x).Trim().ToLowerInvariant()) }
		}
	}
	if (-not [string]::IsNullOrWhiteSpace($package)) {
		[void]$ids.Add($package.Trim().ToLowerInvariant())
	}
	$ids = @($ids | Select-Object -Unique)
	if ($ids.Count -eq 0) {
		return "ERROR: package= or packages= required. Call ListInstallers for ids (7zip, chrome, adobe_reader, adwcleaner, vlc)."
	}

	$cat = Get-MBInstallerCatalog
	$unknown = @()
	$plan = @()
	foreach ($id in $ids) {
		if (-not $cat.Contains($id)) { $unknown += $id; continue }
		$plan += $cat[$id]
	}
	if ($unknown.Count -gt 0) {
		return "ERROR: Unknown package id(s): $($unknown -join ', '). Call ListInstallers."
	}

	$detail = New-Object System.Collections.ArrayList
	[void]$detail.Add('Silent install from catalog (temp downloads cleaned after):')
	[void]$detail.Add('')
	foreach ($p in $plan) {
		$runsScan = $false
		try { $runsScan = [bool]$p.runs_scan } catch { $runsScan = ($p.id -eq 'adwcleaner') }
		$line = " - $($p.id): $($p.name) [$($p.kind)] $(Get-MBPackageInstallArgs -Package $p)"
		if ($runsScan) { $line += '  ** will run a scan **' }
		elseif ($p.kind -eq 'open_url') { $line += '  (open URL only)' }
		[void]$detail.Add($line)
	}
	if (-not (Request-Confirmation -Title "InstallPackage requires approval" -Details (($detail | ForEach-Object { $_ }) -join "`n"))) {
		return "BLOCKED BY USER: InstallPackage denied."
	}

	$workRoot = New-MBTempDir -Prefix 'MiniBotInstall'
	$results = New-Object System.Collections.ArrayList
	$total = $plan.Count
	$idx = 0
	try {
		Write-Host ("  InstallPackage: {0} package(s), silent" -f $total) -ForegroundColor DarkCyan
		foreach ($pkg in $plan) {
			$idx++
			$label = [string]$pkg.name
			Write-MBSetupProgress -Phase start -Index $idx -Total $total -Title $label
			$sub = Join-Path $workRoot ([string]$pkg.id)
			New-Item -ItemType Directory -Path $sub -Force | Out-Null
			try { Register-MBTempPath -Path $sub } catch {}
			$r = Invoke-MBSetupInstallPackage -Package $pkg -WorkDir $sub -Cleanup $true
			$row = [ordered]@{ id = [string]$pkg.id; name = [string]$pkg.name }
			foreach ($k in @($r.Keys)) { $row[$k] = $r[$k] }
			[void]$results.Add($row)
			if ($row.ok) {
				# Verify via uninstall registry when we have a display name
				$v = Test-MBSoftwareInstalledHint -NameHint ([string]$pkg.name)
				$row['verified'] = [bool]$v.ok
				$row['verify_detail'] = [string]$v.detail
				if ($v.ok) {
					$row['verified_name'] = [string]$v.name
					$row['verified_version'] = [string]$v.version
				}
				Write-MBSetupProgress -Phase ok -Index $idx -Total $total -Title $label -Software
			} else {
				$err = if ($row.error) { [string]$row.error } elseif ($row.err) { [string]$row.err } else { 'failed' }
				$row['verified'] = $false
				Write-MBSetupProgress -Phase fail -Index $idx -Total $total -Title $label -Detail $err -Software
			}
			try { Remove-MBTempPath -Path $sub } catch {}
		}
	} finally {
		try { Remove-MBTempPath -Path $workRoot } catch {}
	}
	$okN = @($results | Where-Object { $_.ok }).Count
	$verN = @($results | Where-Object { $_.verified }).Count
	Write-Host ("  InstallPackage done: {0}/{1} Installed (verified {2})" -f $okN, $total, $verN) -ForegroundColor $(if ($okN -eq $total) { 'Green' } else { 'Yellow' })
	$cardNotes = @($results | ForEach-Object {
		$st = if ($_.ok) { 'OK' } else { 'FAIL' }
		$vd = if ($_.verified) { ' verified' } elseif ($_.ok) { ' (not in registry yet)' } else { '' }
		'{0}: {1}{2}' -f $_.id, $st, $vd
	})
	$card = Write-MBOperatorCard -Title 'INSTALL PACKAGE' -Fields ([ordered]@{
		Passed   = ('{0}/{1}' -f $okN, $results.Count)
		Verified = $verN
	}) -Notes @($cardNotes)
	return ConvertTo-MBJson ([ordered]@{
		ok            = ($okN -eq $results.Count)
		passed        = $okN
		total         = $results.Count
		verified      = $verN
		operator_card = $card
		note          = 'Silent installs; downloads cleaned after each package. verified= found in uninstall registry after install.'
		results       = @($results)
	}) -Depth 8
}

function Invoke-NewMachineSetup {
	param(
		[string]$profile = 'residential',
		[bool]$dry_run = $false,
		[string]$timezone = '',
		[bool]$skip_restore_point = $false,
		[bool]$skip_software = $false
	)
	$prof = ([string]$profile).Trim().ToLowerInvariant()
	if ($prof -in @('normal','home','consumer','residential')) { $prof = 'residential' }
	elseif ($prof -in @('business','biz','work','corp','commercial')) { $prof = 'business' }
	else { return "ERROR: profile must be residential or business." }

	$steps = New-Object System.Collections.ArrayList
	$add = {
		param($list, $id, $title, $scriptblock, $section = 'settings')
		[void]$list.Add([ordered]@{ id = $id; title = $title; run = $scriptblock; section = $section })
	}
	if (-not $skip_restore_point) {
		& $add $steps 'restore_enable' 'Enable System Restore on C:' { Enable-ComputerRestore -Drive 'C:\' -ErrorAction SilentlyContinue; @{ ok = $true } }
		& $add $steps 'restore_point' 'Create restore point' {
			Checkpoint-Computer -Description "MiniBot NewMachineSetup $prof $(Get-Date -Format 'yyyy-MM-dd HH:mm')" -RestorePointType MODIFY_SETTINGS -ErrorAction SilentlyContinue
			@{ ok = $true }
		}
	}
	& $add $steps 'boot_f8' 'Enable legacy F8 boot menu' {
		$r = Invoke-MBSetupNative -File 'bcdedit.exe' -ArgumentList @('/set','{default}','bootmenupolicy','LEGACY')
		@{ ok = $r.ok; exit = $r.exit; detail = $r.out }
	}
	& $add $steps 'power_max' 'Max performance power settings' {
		@{ ok = $true }
	}
	& $add $steps 'explorer_hidden' 'Show hidden files' {
		reg.exe add 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v Hidden /t REG_DWORD /d 1 /f | Out-Null
		@{ ok = $true }
	}
	& $add $steps 'explorer_ext' 'Show file extensions' {
		reg.exe add 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v HideFileExt /t REG_DWORD /d 0 /f | Out-Null
		@{ ok = $true }
	}
	& $add $steps 'win11_explorer' 'Win11 compact mode + classic context menu (if Win11)' {
		$cap = (Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue).Caption
		if ($cap -match 'Windows 11') {
			reg.exe add 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v UseCompactMode /t REG_DWORD /d 1 /f | Out-Null
			reg.exe add 'HKCU\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32' /f /ve /d '' | Out-Null
			@{ ok = $true; win11 = $true }
		} else { @{ ok = $true; win11 = $false; skipped = $true } }
	}
	& $add $steps 'edge_widget' 'Disable Edge web widget' {
		reg.exe add 'HKLM\SOFTWARE\Policies\Microsoft\Edge' /v WebWidgetAllowed /t REG_DWORD /d 0 /f | Out-Null
		@{ ok = $true }
	}
	& $add $steps 'reg_backup' 'Enable periodic registry backups' {
		reg.exe add 'HKLM\SYSTEM\ControlSet001\Control\Session Manager\Configuration Manager' /v EnablePeriodicBackup /t REG_DWORD /d 1 /f | Out-Null
		@{ ok = $true }
	}
	& $add $steps 'network_discovery' 'Enable Network Discovery' {
		Enable-MBFirewallGroup -GroupName 'Network Discovery' -TimeoutSec 15
	}
	& $add $steps 'file_sharing' 'Enable File and Printer Sharing' {
		Enable-MBFirewallGroup -GroupName 'File and Printer Sharing' -TimeoutSec 15
	}
	if (-not [string]::IsNullOrWhiteSpace($timezone)) {
		$tz = [string]$timezone
		$tzSb = {
			$r = Invoke-MBSetupNative -File 'tzutil.exe' -ArgumentList @('/s', $tz)
			@{ ok = $r.ok; exit = $r.exit }
		}.GetNewClosure()
		& $add $steps 'timezone' "Set timezone: $tz" $tzSb
	}
	& $add $steps 'time_sync' 'Sync Windows time' {
		$null = Invoke-MBSetupNative -File 'w32tm.exe' -ArgumentList @('/config','/manualpeerlist:time.windows.com')
		$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('stop','w32time')
		reg.exe add 'HKLM\SYSTEM\CurrentControlSet\Services\W32Time\Parameters' /v Type /t REG_SZ /d NTP /f | Out-Null
		$null = Invoke-MBSetupNative -File 'net.exe' -ArgumentList @('start','w32time')
		$r = Invoke-MBSetupNative -File 'w32tm.exe' -ArgumentList @('/resync')
		@{ ok = $true; resync_exit = $r.exit }
	}
	& $add $steps 'bitlocker_off' 'Disable Device Encryption on C: (manage-bde -off)' {
		$r = Invoke-MBSetupNative -File 'manage-bde.exe' -ArgumentList @('-off', 'C:') -TimeoutSec 300
		@{ ok = $r.ok; exit = $r.exit; out = $r.out; err = $r.err }
	}

	# Portable = form factor / use pattern, not desktop vs laptop labels.
	# Always recommend re-enabling encryption when portable; stress it more for business.
	$portableEncryptNote = 'If this machine is portable, re-enable Device Encryption / BitLocker after setup.'

	$software = @()
	if (-not $skip_software) {
		$software = @(Get-MBNewMachineSoftwareManifest -Profile $prof)
		foreach ($pkg in $software) {
			$stepId = 'sw_' + [string]$pkg.id
			$runsScan = $false
			try { $runsScan = [bool]$pkg.runs_scan } catch { $runsScan = $false }
			if ($pkg.kind -eq 'open_url') {
				$title = "SOFTWARE: Open $($pkg.name)"
			} elseif ($runsScan -or $pkg.id -eq 'adwcleaner') {
				$title = "SOFTWARE: Download + run $($pkg.name) (will run a scan)"
			} else {
				$title = "SOFTWARE: Download + install $($pkg.name)"
			}
			& $add $steps $stepId $title { @{ ok = $true } } 'software'
		}
	}

	$plan = @($steps | ForEach-Object { [ordered]@{ id = $_.id; title = $_.title; section = $_.section } })
	$dryNote = "Device Encryption is turned OFF during setup. $portableEncryptNote ADWCleaner will run a scan if software is included. UAC is not changed by this profile."
	if ($dry_run) {
		return ConvertTo-MBJson ([ordered]@{
			ok             = $true
			dry_run        = $true
			profile        = $prof
			skip_software  = [bool]$skip_software
			note           = $dryNote
			recommendation = $portableEncryptNote
			settings_steps = @($plan | Where-Object { $_.section -ne 'software' })
			software       = @($software | ForEach-Object {
				$rs = $false
				try { $rs = [bool]$_.runs_scan } catch { $rs = ($_.id -eq 'adwcleaner') }
				[ordered]@{ id = $_.id; name = $_.name; runs_scan = $rs }
			})
			steps          = $plan
		}) -Depth 6
	}

	$detailLines = New-Object System.Collections.ArrayList
	[void]$detailLines.Add("NewMachineSetup profile=$prof")
	[void]$detailLines.Add('This will change Windows settings' + $(if (-not $skip_software) { ' and download/install software' } else { ' only (software skipped)' }) + '.')
	[void]$detailLines.Add('')
	[void]$detailLines.Add('SETTINGS:')
	foreach ($p in $plan) {
		if ($p.section -eq 'software') { continue }
		[void]$detailLines.Add("  - $($p.title)")
	}
	[void]$detailLines.Add('')
	[void]$detailLines.Add('NOTE: Device Encryption will be disabled for setup.')
	[void]$detailLines.Add("  $portableEncryptNote")
	if (-not $skip_software) {
		[void]$detailLines.Add('')
		[void]$detailLines.Add('SOFTWARE (full catalog) - silent download/install:')
		foreach ($pkg in $software) {
			$runsScan = $false
			try { $runsScan = [bool]$pkg.runs_scan } catch { $runsScan = ($pkg.id -eq 'adwcleaner') }
			if ($pkg.kind -eq 'open_url') {
				[void]$detailLines.Add("  - $($pkg.name) (open URL)")
			} elseif ($runsScan) {
				[void]$detailLines.Add("  - $($pkg.name) (will run a scan)")
			} else {
				[void]$detailLines.Add("  - $($pkg.name)")
			}
		}
	}
	if (-not (Request-Confirmation -Title "NewMachineSetup requires approval" -Details (($detailLines | ForEach-Object { $_ }) -join "`n"))) {
		return "BLOCKED BY USER: NewMachineSetup denied."
	}

	$workDir = $null
	if (-not $skip_software) {
		try { $workDir = New-MBTempDir -Prefix 'MiniBotSetup' } catch { $workDir = $null }
	}

	$results = New-Object System.Collections.ArrayList
	$pkgById = @{}
	foreach ($pkg in $software) { $pkgById['sw_' + [string]$pkg.id] = $pkg }

	$totalSteps = $steps.Count
	$stepIdx = 0
	Write-Host ("  NewMachineSetup profile={0}: {1} step(s), silent installers" -f $prof, $totalSteps) -ForegroundColor DarkCyan
	Write-MBJobChecklist -Job 'NewMachineSetup' -Step 0 -Total $totalSteps -Label ("checklist ready ({0})" -f $prof) -Phase info

	try {
		foreach ($s in $steps) {
			$stepIdx++
			$row = [ordered]@{ id = $s.id; title = $s.title; section = $s.section; ok = $false }
			Write-MBSetupProgress -Phase start -Index $stepIdx -Total $totalSteps -Title ([string]$s.title)
			try {
				if ($s.id -eq 'power_max') {
					$null = Invoke-MBSetupNative -File 'powercfg.exe' -ArgumentList @('/setactive','8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c')
					foreach ($c in @(
						@('/change','monitor-timeout-ac','0'),
						@('/change','monitor-timeout-dc','0'),
						@('/change','standby-timeout-ac','0'),
						@('/change','standby-timeout-dc','0'),
						@('/change','hibernate-timeout-ac','0'),
						@('/change','hibernate-timeout-dc','0'),
						@('/hibernate','off'),
						@('/setACvalueIndex','scheme_current','sub_buttons','lidAction','0'),
						@('/setDCvalueIndex','scheme_current','sub_buttons','lidAction','0'),
						@('/setACvalueindex','scheme_current','sub_pciexpress','ASPM','0'),
						@('/setDCvalueindex','scheme_current','sub_pciexpress','ASPM','0'),
						@('/setACvalueindex','scheme_current','2a737441-1930-4402-8d77-b2bebba308a3','48e6b7a6-50f5-4782-a5d4-53bb8f07e226','0'),
						@('/setDCvalueindex','scheme_current','2a737441-1930-4402-8d77-b2bebba308a3','48e6b7a6-50f5-4782-a5d4-53bb8f07e226','0'),
						@('/setactive','scheme_current')
					)) { $null = Invoke-MBSetupNative -File 'powercfg.exe' -ArgumentList $c }
					$row.ok = $true
				} elseif ($s.section -eq 'software' -and $pkgById.ContainsKey($s.id)) {
					$inst = Invoke-MBSetupInstallPackage -Package $pkgById[$s.id] -WorkDir $workDir
					foreach ($k in @($inst.Keys)) { $row[$k] = $inst[$k] }
					if ($null -eq $row.ok) { $row.ok = [bool]$inst.ok }
				} else {
					$r = & $s.run
					if ($r -is [hashtable] -or $r -is [System.Collections.IDictionary]) {
						foreach ($k in @($r.Keys)) { $row[$k] = $r[$k] }
						if ($null -eq $row.ok) { $row.ok = $true }
					} else { $row.ok = $true }
				}
			} catch {
				$row.ok = $false
				$row.error = $_.Exception.Message
			}
			$isSoftware = ($s.section -eq 'software')
			if ($row.ok) {
				if ($isSoftware) {
					Write-MBSetupProgress -Phase ok -Index $stepIdx -Total $totalSteps -Title ([string]$s.title) -Software
				} else {
					Write-MBSetupProgress -Phase ok -Index $stepIdx -Total $totalSteps -Title ([string]$s.title)
				}
			} else {
				$err = if ($row.error) { [string]$row.error } elseif ($row.err) { [string]$row.err } else { 'failed' }
				if ($isSoftware) {
					Write-MBSetupProgress -Phase fail -Index $stepIdx -Total $totalSteps -Title ([string]$s.title) -Detail $err -Software
				} else {
					Write-MBSetupProgress -Phase fail -Index $stepIdx -Total $totalSteps -Title ([string]$s.title) -Detail $err
				}
			}
			[void]$results.Add($row)
		}
	} finally {
		if ($workDir) { try { Remove-MBTempPath -Path $workDir } catch {} }
	}

	$okN = @($results | Where-Object { $_.ok }).Count
	$swOk = @($results | Where-Object { $_.section -eq 'software' -and $_.ok }).Count
	$swTotal = @($results | Where-Object { $_.section -eq 'software' }).Count
	$doneNote = "Device Encryption was turned OFF during setup. $portableEncryptNote ADWCleaner runs a scan when included. Failed downloads often mean a vendor URL changed."
	for ($i = 0; $i -lt $results.Count; $i++) {
		if ([string]$results[$i].id -eq 'bitlocker_off') {
			$results[$i]['recommendation'] = $portableEncryptNote
			break
		}
	}
	Write-Host ("  NewMachineSetup done: {0}/{1} OK" -f $okN, $totalSteps) -ForegroundColor $(if ($okN -eq $totalSteps) { 'Green' } else { 'Yellow' })
	$card = Write-MBOperatorCard -Title 'NEW MACHINE SETUP' -Fields ([ordered]@{
		Profile = $prof
		Passed  = ('{0}/{1}' -f $okN, $totalSteps)
		Software = ('{0}/{1}' -f $swOk, $swTotal)
	}) -Notes @($doneNote)
	try { [void](Add-MBStickyNote -Text ("NewMachineSetup $prof $okN/$totalSteps OK") -Kind finding) } catch {}
	return ConvertTo-MBJson ([ordered]@{
		ok             = ($okN -eq $results.Count)
		profile        = $prof
		passed         = $okN
		total          = $results.Count
		operator_card  = $card
		software_ok    = $swOk
		software_total = $swTotal
		skip_software  = [bool]$skip_software
		note           = $doneNote
		recommendation = $portableEncryptNote
		results        = @($results)
	}) -Depth 8
}

function Invoke-MBTool {
	param(
		[string]$Name,
		$ArgsObj
	)
	if (-not $ArgsObj) { $ArgsObj = [pscustomobject]@{} }
	$sw = [System.Diagnostics.Stopwatch]::StartNew()

	$resolvedName = Resolve-MBToolName -Name $Name
	if ($resolvedName -and $resolvedName -ne $Name) {
		$Name = $resolvedName
	}

	if ($Name -and -not (Test-MBToolNameActive -Name $Name)) {
		$allNames = @($Tools | ForEach-Object { $_.function.name })
		$sw.Stop()
		$script:MB.LastToolMs = $sw.ElapsedMilliseconds
		$script:MB.ToolCalls++
		try { Update-MBWpfLiveChrome } catch {}
		$match = $null
		foreach ($n in $allNames) {
			if ($n -eq $Name -or $n.ToLowerInvariant() -eq $Name.ToLowerInvariant()) { $match = $n; break }
		}
		if (-not $match) { $match = Resolve-MBToolName -Name $Name }
		if ($match) {
			if ((Test-MBToolNeedsVision -Name $match) -and -not (Test-MBModelHasVision)) {
				return "ERROR: Tool '$match' requires vision. Current model has no 'vision' ability - do not call ReadImage, ReadPdf, or ViewScreen."
			}
			$hint = Get-MBToolEnableHint -ToolName $match
			return "ERROR: Tool '$match' is not in the active tool list. $hint"
		}
		return "ERROR: Unknown tool '$Name'. Prefer ROUTER in system prompt (volume->AudioVolume, brightness->DisplayBrightness). For gated tools: EnableToolGroup using MAP then real tool name. Do not invent tools or shell COM for OS UX knobs."
	}

	$guard = Test-MBToolLoopGuard -Name $Name -ArgsObj $ArgsObj
	if ($guard.Block) {
		$sw.Stop()
		$script:MB.LastToolMs = $sw.ElapsedMilliseconds
		$script:MB.ToolCalls++
		try { Update-MBWpfLiveChrome } catch {}
		$blockMsg = [string]$guard.Message
		try {
			Register-MBToolOutcome -Name $Name -ArgsObj $ArgsObj -Result $blockMsg -Fingerprint ([string]$guard.Fingerprint)
		} catch {}
		return $blockMsg
	}
	$fp = $guard.Fingerprint

	try {
		$result = switch ($Name) {
			"ReadFile" {
				$p = @{ path = (Get-MBProp $ArgsObj 'path') }
				if (Test-MBHasProp $ArgsObj 'head')   { $p['head']   = [int](Get-MBProp $ArgsObj 'head') }
				if (Test-MBHasProp $ArgsObj 'tail')   { $p['tail']   = [int](Get-MBProp $ArgsObj 'tail') }
				if (Test-MBHasProp $ArgsObj 'offset') { $p['offset'] = [int](Get-MBProp $ArgsObj 'offset') }
				if (Test-MBHasProp $ArgsObj 'length') { $p['length'] = [int](Get-MBProp $ArgsObj 'length') }
				Invoke-ReadFile @p
			}
			"WriteFile" {
				$p = @{
					path    = (Get-MBProp $ArgsObj 'path')
					content = (Get-MBProp $ArgsObj 'content')
				}
				if (Test-MBHasProp $ArgsObj 'backup') { $p['backup'] = [bool](Get-MBProp $ArgsObj 'backup') }
				Invoke-WriteFile @p
			}
			"EditFile" {
				$p = @{
					path    = [string](Get-MBProp $ArgsObj 'path' '')
					search  = [string](Get-MBProp $ArgsObj 'search' '')
					replace = [string](Get-MBProp $ArgsObj 'replace' '')
				}
				if (Test-MBHasProp $ArgsObj 'useRegex') { $p['useRegex'] = (Convert-MBToBool (Get-MBProp $ArgsObj 'useRegex') $false) }
				if (Test-MBHasProp $ArgsObj 'replaceAll') { $p['replaceAll'] = (Convert-MBToBool (Get-MBProp $ArgsObj 'replaceAll') $false) }
				if (Test-MBHasProp $ArgsObj 'occurrence') { $p['occurrence'] = (Convert-MBToInt (Get-MBProp $ArgsObj 'occurrence') 0) }
				if (Test-MBHasProp $ArgsObj 'backup') { $p['backup'] = (Convert-MBToBool (Get-MBProp $ArgsObj 'backup') $true) }
				if (Test-MBHasProp $ArgsObj 'edits') { $p['edits'] = (Get-MBProp $ArgsObj 'edits') }
				Invoke-EditFile @p
			}
			"ApplyPatch" {
				$p = @{ patch = [string](Get-MBProp $ArgsObj 'patch' '') }
				if (Test-MBHasProp $ArgsObj 'path') { $p['path'] = [string](Get-MBProp $ArgsObj 'path' '') }
				if (Test-MBHasProp $ArgsObj 'backup') { $p['backup'] = (Convert-MBToBool (Get-MBProp $ArgsObj 'backup') $true) }
				Invoke-ApplyPatch @p
			}
			"RunCommand" {
				$cmd = Get-MBProp $ArgsObj 'command'
				$shell = Get-MBProp $ArgsObj 'shell' 'powershell'
				$tsec = 0
				if (Test-MBHasProp $ArgsObj 'timeout_sec') { $tsec = [int](Get-MBProp $ArgsObj 'timeout_sec') }

				if (Test-IsSafeCommand $cmd) {
					Write-Host "    auto (whitelist)" -ForegroundColor Green
					Invoke-RunCommand -command $cmd -shell $shell -timeout_sec $tsec
				} else {
					$cmdDetails = "Shell: $shell`nNot on the safe whitelist; may modify system state."
					$codeLang = if ([string]$shell -match '^(?i)cmd') { 'bat' } else { 'ps' }
					if (-not (Request-Confirmation -Title "RunCommand requires approval" -Details $cmdDetails -Code ([string]$cmd) -CodeLang $codeLang)) {
						Write-Host "    denied" -ForegroundColor Red
						"BLOCKED BY USER: Operator denied this RunCommand. Do NOT retry the same shell approach. Re-read ROUTER/MAP: volume/mute->EnableToolGroup sound + AudioVolume; speak->sound + SpeakText; brightness->system + DisplayBrightness; services->system + ControlService. EnableToolGroup then call specialized tool same turn."
					} else {
						if ($script:MB.AutoApprove) {
							if ($script:MB.ModeSwitch) { $script:MB.ModeSwitch = $false }
							else { Write-Host "    auto-approve" -ForegroundColor Green }
						} else {
							Write-Host "    approved" -ForegroundColor Green
						}
						Invoke-RunCommand -command $cmd -shell $shell -timeout_sec $tsec
					}
				}
			}
			"RemoteCommand" {
				# Domain-admin tool: soft-block before ports/approval when host/user not on a domain.
				try {
					if (-not (Test-MBHostOnDomain)) {
						Write-Host "    remote command unavailable (not on domain)" -ForegroundColor DarkYellow
						return (Get-MBRemoteCommandDomainBlockMessage)
					}
				} catch {
					Write-Host "    remote command unavailable (domain check failed)" -ForegroundColor DarkYellow
					return (Get-MBRemoteCommandDomainBlockMessage)
				}
				# Never splat a key named 'host' — binds to automatic $Host and throws read-only/constant.
				$p = @{}
				$rh = ''
				if (Test-MBHasProp $ArgsObj 'host') { $rh = [string](Get-MBProp $ArgsObj 'host') }
				if ([string]::IsNullOrWhiteSpace($rh) -and (Test-MBHasProp $ArgsObj 'computer')) {
					$rh = [string](Get-MBProp $ArgsObj 'computer')
				}
				if (-not [string]::IsNullOrWhiteSpace($rh)) { $p['RemoteHost'] = $rh.Trim() }
				if (Test-MBHasProp $ArgsObj 'command') { $p['command'] = (Get-MBProp $ArgsObj 'command') }
				if (Test-MBHasProp $ArgsObj 'transport') { $p['transport'] = (Get-MBProp $ArgsObj 'transport') }
				if (Test-MBHasProp $ArgsObj 'shell') { $p['shell'] = (Get-MBProp $ArgsObj 'shell') }
				if (Test-MBHasProp $ArgsObj 'username') { $p['username'] = (Get-MBProp $ArgsObj 'username') }
				if (Test-MBHasProp $ArgsObj 'user') { $p['username'] = (Get-MBProp $ArgsObj 'user') }
				if (Test-MBHasProp $ArgsObj 'password') { $p['password'] = (Get-MBProp $ArgsObj 'password') }
				if (Test-MBHasProp $ArgsObj 'port') {
					try {
						$pv = Get-MBProp $ArgsObj 'port'
						if ($pv -is [System.Array]) { $p['port'] = [int](@($pv)[0]) }
						else { $p['port'] = [int]$pv }
					} catch {}
				}
				if (Test-MBHasProp $ArgsObj 'timeout_sec') {
					try { $p['timeout_sec'] = [int](Get-MBProp $ArgsObj 'timeout_sec') } catch {}
				}
				if (Test-MBHasProp $ArgsObj 'use_ssl') { $p['use_ssl'] = (Get-MBProp $ArgsObj 'use_ssl') }

				$hShow = ''
				try { $hShow = [string]$p['RemoteHost'] } catch {}
				$txShow = 'winrm'
				try { if ($p['transport']) { $txShow = [string]$p['transport'] } } catch {}
				$shShow = 'powershell'
				try { if ($p['shell']) { $shShow = [string]$p['shell'] } } catch {}
				$uShow = '(default)'
				try { if ($p['username']) { $uShow = [string]$p['username'] } } catch {}
				$cmdShow = ''
				try { $cmdShow = [string]$p['command'] } catch {}
				$portShow = 0
				try {
					if ($p.ContainsKey('port')) {
						$pv = $p['port']
						if ($pv -is [System.Array]) { $portShow = [int](@($pv)[0]) }
						else { $portShow = [int]$pv }
					}
				} catch { $portShow = 0 }
				$sslShow = $false
				try { if ($p.ContainsKey('use_ssl')) { $sslShow = [bool](Convert-MBToBool -Value $p['use_ssl'] -Default $false) } } catch {}

				# Port check FIRST (before approval). Closed ports => STOP message, no thrashing.
				try {
					$prior = Get-MBRemotePortClosedBlock -Target $hShow -Transport $txShow
					if (-not [string]::IsNullOrWhiteSpace($prior)) {
						# Short harness status only — full text is tool result for the model, not chat chrome
						Write-Host ("    remote port closed ({0} {1}) — already reported" -f $txShow, $hShow) -ForegroundColor DarkGray
						try { Write-MBDebugLog -Step 'REMOTE_PORT_CLOSED' -Detail ("already host={0} tx={1}" -f $hShow, $txShow) } catch {}
						return (
							"ERROR: remote_port_closed=1 already_reported=1 host=$hShow transport=$txShow`n" +
							"TOOLS_DONE=1 NO_MORE_TOOLS=1 FINISH_TURN=1`n" +
							"You already got a port-closed result for this host. Do NOT call more tools. Reply to the operator with the status below.`n`n" +
							$prior
						)
					}
					$gate = Test-MBRemoteCommandPortGate -RemoteHost $hShow -Transport $txShow -Port $portShow -UseSsl $sslShow
					if (-not [string]::IsNullOrWhiteSpace($gate)) {
						Write-Host ("    remote port closed ({0} {1})" -f $txShow, $hShow) -ForegroundColor DarkGray
						try { Write-MBDebugLog -Step 'REMOTE_PORT_CLOSED' -Detail ("host={0} tx={1}" -f $hShow, $txShow) } catch {}
						# Return to model only — do not Write-Host the full gate (leaks into chat as yellow ERROR)
						return $gate
					}
				} catch {
					Write-Host ("    remote port probe failed ({0})" -f $hShow) -ForegroundColor DarkGray
					return ("ERROR: remote_port_probe_failed host={0} detail={1}" -f $hShow, $_.Exception.Message)
				}

				$details = "Host: $hShow`nTransport: $txShow`nShell: $shShow`nUser: $uShow`nRuns on the REMOTE machine (not this PC)."
				$codeLang = if ([string]$shShow -match '^(?i)cmd') { 'bat' } else { 'ps' }
				if (-not (Request-Confirmation -Title "RemoteCommand requires approval" -Details $details -Code $cmdShow -CodeLang $codeLang)) {
					Write-Host "    denied" -ForegroundColor Red
					"BLOCKED BY USER: Operator denied RemoteCommand to $hShow. Do not retry the same remote command without a new request. Prefer read-only checks first if the goal was inventory."
				} else {
					if ($script:MB.AutoApprove) {
						if ($script:MB.ModeSwitch) { $script:MB.ModeSwitch = $false }
						else { Write-Host "    auto-approve" -ForegroundColor Green }
					} else {
						Write-Host "    approved" -ForegroundColor Green
					}
					Invoke-RemoteCommand @p
				}
			}
			"ListDirectory" { Invoke-ListDirectory -path (Get-MBProp $ArgsObj 'path' '.') }
			"SearchFiles" {
				$p = @{
					path    = (Get-MBProp $ArgsObj 'path')
					pattern = (Get-MBProp $ArgsObj 'pattern')
				}
				if (Test-MBHasProp $ArgsObj 'glob')       { $p['glob'] = (Get-MBProp $ArgsObj 'glob') }
				if (Test-MBHasProp $ArgsObj 'recursive')  { $p['recursive'] = [bool](Get-MBProp $ArgsObj 'recursive') }
				if (Test-MBHasProp $ArgsObj 'ignoreCase') { $p['ignoreCase'] = [bool](Get-MBProp $ArgsObj 'ignoreCase') }
				if (Test-MBHasProp $ArgsObj 'maxResults') { $p['maxResults'] = [int](Get-MBProp $ArgsObj 'maxResults') }
				Invoke-SearchFiles @p
			}
			"FindFiles" {
				$p = @{ path = (Get-MBProp $ArgsObj 'path' '.') }
				if (Test-MBHasProp $ArgsObj 'glob') { $p['glob'] = (Get-MBProp $ArgsObj 'glob') }
				if (Test-MBHasProp $ArgsObj 'globs') { $p['globs'] = (Get-MBProp $ArgsObj 'globs') }
				if (Test-MBHasProp $ArgsObj 'extensions') { $p['extensions'] = (Get-MBProp $ArgsObj 'extensions') }
				if (Test-MBHasProp $ArgsObj 'modified_within_days') { $p['modified_within_days'] = [int](Get-MBProp $ArgsObj 'modified_within_days') }
				if (Test-MBHasProp $ArgsObj 'min_bytes') { $p['min_bytes'] = [long](Get-MBProp $ArgsObj 'min_bytes') }
				if (Test-MBHasProp $ArgsObj 'max_bytes') { $p['max_bytes'] = [long](Get-MBProp $ArgsObj 'max_bytes') }
				if (Test-MBHasProp $ArgsObj 'recursive') { $p['recursive'] = [bool](Get-MBProp $ArgsObj 'recursive') }
				if (Test-MBHasProp $ArgsObj 'max') { $p['max'] = [int](Get-MBProp $ArgsObj 'max') }
				Invoke-FindFiles @p
			}
			"HexView" {
				$p = @{ path = (Get-MBProp $ArgsObj 'path') }
				if (Test-MBHasProp $ArgsObj 'path2') { $p['path2'] = (Get-MBProp $ArgsObj 'path2') }
				elseif (Test-MBHasProp $ArgsObj 'compare') { $p['compare'] = (Get-MBProp $ArgsObj 'compare') }
				if (Test-MBHasProp $ArgsObj 'offset') { $p['offset'] = (Get-MBProp $ArgsObj 'offset') }
				if (Test-MBHasProp $ArgsObj 'length') { $p['length'] = [int](Get-MBProp $ArgsObj 'length') }
				if (Test-MBHasProp $ArgsObj 'width') { $p['width'] = [int](Get-MBProp $ArgsObj 'width') }
				if (Test-MBHasProp $ArgsObj 'show_ascii') { $p['show_ascii'] = [bool](Get-MBProp $ArgsObj 'show_ascii') }
				if (Test-MBHasProp $ArgsObj 'annotate') { $p['annotate'] = [bool](Get-MBProp $ArgsObj 'annotate') }
				if (Test-MBHasProp $ArgsObj 'detail') { $p['detail'] = [string](Get-MBProp $ArgsObj 'detail') }
				if (Test-MBHasProp $ArgsObj 'next_diff') { $p['next_diff'] = [bool](Get-MBProp $ArgsObj 'next_diff') }
				if (Test-MBHasProp $ArgsObj 'side_by_side') { $p['side_by_side'] = [bool](Get-MBProp $ArgsObj 'side_by_side') }
				if (Test-MBHasProp $ArgsObj 'max_scan') { $p['max_scan'] = [int](Get-MBProp $ArgsObj 'max_scan') }
				if (Test-MBHasProp $ArgsObj 'disasm') { $p['disasm'] = [bool](Get-MBProp $ArgsObj 'disasm') }
				if (Test-MBHasProp $ArgsObj 'trace') { $p['trace'] = [bool](Get-MBProp $ArgsObj 'trace') }
				if (Test-MBHasProp $ArgsObj 'at_entry') { $p['at_entry'] = [bool](Get-MBProp $ArgsObj 'at_entry') }
				if (Test-MBHasProp $ArgsObj 'rva') { $p['rva'] = (Get-MBProp $ArgsObj 'rva') }
				if (Test-MBHasProp $ArgsObj 'section') { $p['section'] = [string](Get-MBProp $ArgsObj 'section') }
				if (Test-MBHasProp $ArgsObj 'max_insns') { $p['max_insns'] = [int](Get-MBProp $ArgsObj 'max_insns') }
				if (Test-MBHasProp $ArgsObj 'max_steps') { $p['max_steps'] = [int](Get-MBProp $ArgsObj 'max_steps') }
				if (Test-MBHasProp $ArgsObj 'follow_calls') { $p['follow_calls'] = [bool](Get-MBProp $ArgsObj 'follow_calls') }
				if (Test-MBHasProp $ArgsObj 'prefer_branch') { $p['prefer_branch'] = [string](Get-MBProp $ArgsObj 'prefer_branch') }
