				$p = @{}
				if (Test-MBHasProp $ArgsObj 'group') { $p['Group'] = [string](Get-MBProp $ArgsObj 'group') }
				if (Test-MBHasProp $ArgsObj 'groups') { $p['groups'] = (Get-MBProp $ArgsObj 'groups') }
				Enable-MBToolGroup @p
			}
			"ListToolGroups"  { Get-MBToolGroupsStatus }
			"TaskBoard" {
				$p = @{ action = (Get-MBProp $ArgsObj 'action' 'status') }
				if (Test-MBHasProp $ArgsObj 'goal') { $p['goal'] = (Get-MBProp $ArgsObj 'goal') }
				if (Test-MBHasProp $ArgsObj 'items') { $p['items'] = (Get-MBProp $ArgsObj 'items') }
				if (Test-MBHasProp $ArgsObj 'id') { $p['id'] = (Get-MBProp $ArgsObj 'id') }
				if (Test-MBHasProp $ArgsObj 'status') { $p['status'] = (Get-MBProp $ArgsObj 'status') }
				if (Test-MBHasProp $ArgsObj 'title') { $p['title'] = (Get-MBProp $ArgsObj 'title') }
				if (Test-MBHasProp $ArgsObj 'note') { $p['note'] = (Get-MBProp $ArgsObj 'note') }
				if (Test-MBHasProp $ArgsObj 'replace') { $p['replace'] = (Get-MBProp $ArgsObj 'replace') }
				if (Test-MBHasProp $ArgsObj 'updates') { $p['updates'] = (Get-MBProp $ArgsObj 'updates') }
				if (Test-MBHasProp $ArgsObj 'ids') { $p['ids'] = (Get-MBProp $ArgsObj 'ids') }
				if (Test-MBHasProp $ArgsObj 'epoch') { $p['epoch'] = (Get-MBProp $ArgsObj 'epoch') }
				if (Test-MBHasProp $ArgsObj 'verbose') {
					try { if ([bool](Get-MBProp $ArgsObj 'verbose')) { $p['verbose'] = $true } } catch {}
				}
				$r = Invoke-TaskBoard @p
				try { $script:MB.PendingStickyLedgerSync = $true } catch {}
				$r
			}
			default {
				$hint = Get-MBToolEnableHint -ToolName $Name
				$resolved = Resolve-MBToolName -Name $Name
				if ($resolved) {
					"ERROR: Tool '$resolved' is not dispatched (inactive group or typo). $hint"
				} else {
					"ERROR: Unknown tool '$Name'. $hint"
				}
			}
		}
	} catch {
		$exType = try { $_.Exception.GetType().FullName } catch { 'Exception' }
		$stack = ''
		try {
			if ($_.InvocationInfo -and $_.InvocationInfo.PositionMessage) {
				$stack = [string]$_.InvocationInfo.PositionMessage
			}
		} catch {}
		$result = "ERROR in ${Name}: [$exType] $($_.Exception.Message)"
		if ($stack) { $result += "`n$stack" }
		if ("$($_.Exception.Message)" -match 'types do not match|cannot convert|parameterbinding') {
			$result += "`nHINT: SandBox tools read args via `$script:MB_ToolArgs (no typed params). If you still see this, an internal helper is typed - report the stack above."
		}
	}

	$sw.Stop()
	$script:MB.LastToolMs = $sw.ElapsedMilliseconds
	$script:MB.ToolCalls++
	try { Add-MBUsedToolName -Name $Name } catch {}
	try { Update-MBWpfLiveChrome } catch {}

	$text = if ($null -eq $result) { "" } elseif ($result -is [string]) { $result } else { ($result | Out-String).Trim() }
	$text = Limit-MBResult $text

	if ($guard -and -not $guard.Block) {
		$previewNote = $text
		$wasConfirmed = $false
		if ($guard.Confirmed) {
			$previewNote = "[timing retest - one-shot]`n" + $text
			$wasConfirmed = $true
		}
		Register-MBToolExecution -Fingerprint $fp -ResultPreview $previewNote -WasConfirmed $wasConfirmed -ToolName $Name -ArgsObj $ArgsObj
	} elseif ($guard -and $guard.Block) {
		# Count blocked loop-guard as bad outcome (drives NEED_INPUT after repeat)
		try {
			Register-MBToolOutcome -Name $Name -ArgsObj $ArgsObj -Result $text -Fingerprint $fp
		} catch {}
	}

	return $text
}


function Get-MBAuthHeaders {
	$h = @{
		'Content-Type' = 'application/json'
		'Accept'       = 'application/json'
	}
	$auth = Get-MBAuthHeaderValue -BaseUrl (Get-MBApiBaseUrl)
	if ($auth) { $h['Authorization'] = $auth }
	return $h
}

function Invoke-MBServerJson {
	param(
		[string]$Method = 'POST',
		[Parameter(Mandatory = $true)][string]$Path,
		$BodyObject = $null,
		[int]$TimeoutSec = 20
	)
	$apiBase = (Get-MBApiBaseUrl).TrimEnd('/')
	$path = '/' + ($Path.TrimStart('/'))
	$url = $apiBase + $path
	$headers = Get-MBAuthHeaders
	if ($headers -is [hashtable] -and $headers.ContainsKey('Content-Type')) {
		$headers.Remove('Content-Type')
	}
	$iwr = @{
		Uri             = $url
		Method          = $Method.ToUpper()
		Headers         = $headers
		UseBasicParsing = $true
		TimeoutSec      = $TimeoutSec
	}
	if ($null -ne $BodyObject -and $Method.ToUpper() -ne 'GET') {
		$json = ConvertTo-MBRequestJson -Object $BodyObject -Depth 30
		$iwr['Body'] = [byte[]](Get-MBUtf8JsonBytes -Json $json)
		$iwr['ContentType'] = 'application/json; charset=utf-8'
	}
	$prev = $Global:ProgressPreference
	try {
		$Global:ProgressPreference = 'SilentlyContinue'
		$resp = Invoke-WebRequest @iwr -ErrorAction Stop
		$text = [string]$resp.Content
		if ([string]::IsNullOrWhiteSpace($text)) { return $null }
		try { return ($text | ConvertFrom-Json -ErrorAction Stop) } catch { return $text }
	} finally {
		$Global:ProgressPreference = $prev
	}
}

function Get-MBTokenizeCount {
	param([AllowNull()][string]$Text)
	if ($null -eq $Text) { $Text = '' }
	if ($script:MB.ServerTokenize -eq $false) { return -1 }
	$Text = Sanitize-MBText -Text ([string]$Text)

	$body = @{
		content       = $Text
		add_special   = $false
		parse_special = $true
	}
	foreach ($path in @('tokenize', 'v1/tokenize')) {
		try {
			$obj = Invoke-MBServerJson -Method POST -Path $path -BodyObject $body -TimeoutSec 30
			if ($null -eq $obj) { continue }
			$tokens = Get-MBProp $obj 'tokens'
			if ($null -eq $tokens) { continue }
			$arr = @($tokens)
			$script:MB.ServerTokenize = $true
			return [int]$arr.Count
		} catch {
			continue
		}
	}
	return -1
}

function Get-MBApplyTemplatePrompt {
	param([array]$Messages)
	$norm = @(Normalize-MBMessagesForApi -Messages $Messages)
	$body = @{ messages = $norm }
	foreach ($path in @('apply-template', 'v1/apply-template')) {
		try {
			$obj = Invoke-MBServerJson -Method POST -Path $path -BodyObject $body -TimeoutSec 30
			if ($null -eq $obj) { continue }
			$p = Get-MBProp $obj 'prompt'
			if ($p) { return [string]$p }
		} catch {
			continue
		}
	}
	return $null
}

function Get-MBEstimatedPromptTokens {
	param(
		[int]$MsgChars,
		[int]$ToolPayloadChars,
		[int]$ToolsTok
	)
	$toolTokEst = [math]::Ceiling([math]::Max(0, $ToolPayloadChars) / 2.5)
	$otherChars = [math]::Max(0, $MsgChars - $ToolPayloadChars)
	$otherTokEst = [math]::Ceiling($otherChars / 3.0)
	return [int]($toolTokEst + $otherTokEst + [math]::Max(0, $ToolsTok))
}

function Get-MBAccuratePromptTokens {
	param(
		[array]$Messages,
		[int]$MsgChars = 0,
		[int]$ToolPayloadChars = 0
	)

	$toolsTok = [int]$script:MB.ToolsOverheadTok
	$cacheKey = '{0}|{1}|{2}|{3}' -f @($Messages).Count, $MsgChars, $toolsTok, $script:MB.WorkingDir
	$now = Get-Date
	if ($script:MB.TokCacheKey -eq $cacheKey -and $script:MB.TokCacheTokens -gt 0) {
		$age = ($now - [datetime]$script:MB.TokCacheAt).TotalSeconds
		$maxAge = 8
		try {
			if ([string]$script:MB.TokenCountSource -eq 'usage') { $maxAge = 86400 }
		} catch { $maxAge = 8 }
		if ($age -ge 0 -and $age -lt $maxAge) {
			return [pscustomobject]@{ Tokens = [int]$script:MB.TokCacheTokens; Source = [string]$script:MB.TokenCountSource }
		}
	}

	if ($script:MB.ServerTokenize -ne $false) {
		try {
			$prompt = Get-MBApplyTemplatePrompt -Messages $Messages
			if (-not $prompt) {
				$parts = New-Object System.Collections.ArrayList
				foreach ($m in @(Normalize-MBMessagesForApi -Messages $Messages)) {
					$r = [string](Get-MBProp $m 'role')
					$c = Sanitize-MBText -Text ([string](Get-MBProp $m 'content'))
					[void]$parts.Add("${r}: $c")
					$tcs = Get-MBProp $m 'tool_calls'
					if ($tcs) {
						try { [void]$parts.Add((ConvertTo-MBRequestJson -Object $tcs -Depth 8)) } catch {}
					}
				}
				$prompt = ($parts -join "`n")
			}
			$n = Get-MBTokenizeCount -Text $prompt
			if ($n -ge 0) {
				$total = $n + [math]::Max(0, $toolsTok)
				$script:MB.TokCacheKey = $cacheKey
				$script:MB.TokCacheTokens = $total
				$script:MB.TokCacheAt = $now
				$script:MB.TokenCountSource = 'server'
				return [pscustomobject]@{ Tokens = $total; Source = 'server' }
			}
		} catch {}
		if ($null -eq $script:MB.ServerTokenize) {
			$script:MB.ServerTokenize = $false
		}
	}

	if ([int]$script:MB.LastServerPromptTokens -gt 0) {
		$script:MB.TokenCountSource = 'usage'
		return [pscustomobject]@{ Tokens = [int]$script:MB.LastServerPromptTokens; Source = 'usage' }
	}

	$est = Get-MBEstimatedPromptTokens -MsgChars $MsgChars -ToolPayloadChars $ToolPayloadChars -ToolsTok $toolsTok
	$script:MB.TokenCountSource = 'estimate'
	$script:MB.TokCacheKey = $cacheKey
	$script:MB.TokCacheTokens = $est
	$script:MB.TokCacheAt = $now
	return [pscustomobject]@{ Tokens = $est; Source = 'estimate' }
}

function Get-MBEffectivePromptBudget {
	$window = [math]::Max(2048, [int]$script:MB.ContextWindow)
	$reserve = Get-MBCompletionReserve
	$usable = $window - $reserve
	if ($usable -lt 1024) { $usable = [math]::Max(1024, $window - 512) }
	return $usable
}

function Get-MBCompletionReserve {
	$window = [math]::Max(2048, [int]$script:MB.ContextWindow)
	$want = [math]::Max(1024, [int](Get-MBEffectiveMaxTokens))
	# Allow large MaxTokens on large context windows
	$maxShare = [math]::Floor($window * 0.60)
	if ($maxShare -lt 1024) { $maxShare = [math]::Floor($window * 0.45) }
	if ($want -gt $maxShare) { $want = $maxShare }
	if ($want -lt 512) { $want = 512 }
	return [int]$want
}

function Get-MBRequestMaxTokens {
	param(
		[array]$Messages,
		[int]$Floor = 1024
	)
	$cap = [math]::Max(256, [int](Get-MBEffectiveMaxTokens))
	$window = [math]::Max(2048, [int]$script:MB.ContextWindow)
	$promptTok = 0
	try {
		$est = Get-MBContextEstimate -Messages $Messages
		$promptTok = [int]$est.PromptTokens
	} catch {
		try { $promptTok = [int]$script:MB.LastCtxTokens } catch { $promptTok = 0 }
	}
	if ($promptTok -lt 0) { $promptTok = 0 }
	$overhead = 256
	try {
		$to = [int]$script:MB.ToolsOverheadTok
		if ($to -gt 0) { $overhead = [math]::Max(256, [math]::Min(8000, [int]($to * 0.15) + 256)) }
	} catch {}
	$room = $window - $promptTok - $overhead
	if ($room -lt $Floor) { $room = $Floor }
	$use = [math]::Min($cap, $room)
	if ($use -lt $Floor -and $room -ge $Floor) { $use = $Floor }
	if ($use -lt 256) { $use = 256 }
	try { $script:MB.LastRequestMaxTokens = [int]$use } catch {}
	return [int]$use
}

function Initialize-MBToolsOverhead {
	try {
		# Prefer frozen tools snapshot when wire-frozen (stable overhead = stable cache budget)
		$activeTools = $null
		try {
			if ([bool]$script:MB.WireStateFrozen -and $null -ne $script:MB.FrozenTools -and @($script:MB.FrozenTools).Count -gt 0) {
				$activeTools = @($script:MB.FrozenTools)
			}
		} catch {}
		if ($null -eq $activeTools) { $activeTools = @(Get-MBActiveTools) }
		$tj = ConvertTo-Json -InputObject $activeTools -Depth 20 -Compress
		$script:MB.ToolsOverheadChars = $tj.Length
		$n = Get-MBTokenizeCount -Text $tj
		if ($n -ge 0) {
			$script:MB.ToolsOverheadTok = $n
		} else {
			$script:MB.ToolsOverheadTok = [math]::Ceiling($tj.Length / 2.4)
		}
	} catch {
		$script:MB.ToolsOverheadChars = 40000
		$script:MB.ToolsOverheadTok = 16000
	}
}

function Initialize-MBTokenCounting {
	try {
		$n = Get-MBTokenizeCount -Text 'hello'
		if ($n -ge 0) {
			$script:MB.ServerTokenize = $true
			$script:MB.TokenizeProbeTok = $n
		} else {
			$script:MB.ServerTokenize = $false
			$script:MB.TokenizeProbeTok = -1
		}
	} catch {
		$script:MB.ServerTokenize = $false
		$script:MB.TokenizeProbeTok = -1
	}
}

function Get-MBMessageCharCount {
	param($Message)
	if ($null -eq $Message) { return 0 }
	$n = 0
	$c = Get-MBProp $Message 'content'
	if ($null -ne $c) { $n += ([string]$c).Length }
	$role = Get-MBProp $Message 'role'
	if ($role) { $n += ([string]$role).Length + 8 }
	$tcid = Get-MBProp $Message 'tool_call_id'
	if ($tcid) { $n += ([string]$tcid).Length + 16 }
	$tcs = Get-MBProp $Message 'tool_calls'
	if ($tcs) {
		try {
			$n += (ConvertTo-Json -InputObject $tcs -Depth 8 -Compress).Length
		} catch {
			$n += 200
		}
	}
	return $n
}

function Get-MBContextEstimate {
	param(
		[array]$Messages,
		[switch]$ForceRefresh
	)

	$msgChars = 0
	$byRole = @{ system = 0; user = 0; assistant = 0; tool = 0; other = 0 }
	$msgCount = 0
	$chatMsgCount = 0
	$toolPayloadChars = 0

	foreach ($m in @($Messages)) {
		if ($null -eq $m) { continue }
		$msgCount++
		$ch = Get-MBMessageCharCount -Message $m
		$msgChars += $ch
		$role = [string](Get-MBProp $m 'role')
		if (-not $role) { $role = 'other' }
		if ($byRole.ContainsKey($role)) { $byRole[$role] += $ch } else { $byRole['other'] += $ch }
		# Message count excludes system/sticky
		if ($role -ne 'system') { $chatMsgCount++ }
		if ($role -eq 'tool') {
			$tc = Get-MBProp $m 'content'
			if ($tc) { $toolPayloadChars += ([string]$tc).Length }
		}
	}

	$toolsChars = [int]$script:MB.ToolsOverheadChars
	$toolsTok   = [int]$script:MB.ToolsOverheadTok
	$totalChars = $msgChars + $toolsChars

	if ($ForceRefresh) {
		$script:MB.TokCacheKey = ''
		$script:MB.TokCacheTokens = 0
	}

	$acc = Get-MBAccuratePromptTokens -Messages $Messages -MsgChars $msgChars -ToolPayloadChars $toolPayloadChars
	$promptTokens = [int]$acc.Tokens
	$tokSource = [string]$acc.Source

	$window = [math]::Max(2048, [int]$script:MB.ContextWindow)
	$reserve = Get-MBCompletionReserve
	# Prompt budget = n_ctx minus completion reserve
	$usable = Get-MBEffectivePromptBudget

	$pct = if ($usable -gt 0) { [math]::Min(3.0, $promptTokens / [double]$usable) } else { 1.0 }

	$level = 'ok'
	if ($pct -ge [double]$script:MB.ContextHardPct) { $level = 'hard' }
	elseif ($pct -ge [double]$script:MB.ContextSoftPct) { $level = 'soft' }

	$script:MB.LastCtxChars  = $totalChars
	$script:MB.LastCtxTokens = $promptTokens
	$script:MB.LastCtxPct    = $pct
	$script:MB.LastCtxLevel  = $level
	$script:MB.TokenCountSource = $tokSource

	return [pscustomobject]@{
		MessageCount     = $msgCount
		ChatMessageCount = $chatMsgCount
		MessageChars     = $msgChars
		ToolPayloadChars = $toolPayloadChars
		ToolsChars       = $toolsChars
		ToolsTokens      = $toolsTok
		TotalChars       = $totalChars
		PromptTokens     = $promptTokens
		UsableTokens     = $usable
		WindowTokens     = $window
		ReserveTokens    = $reserve
		Pct              = $pct
		Level            = $level
		ByRoleChars      = $byRole
		TokenSource      = $tokSource
	}
}

function New-MBTaskBoardItemList {
	# Always ArrayList — PS 5.1 @() / foreach over List[object] throws
	# "Argument types do not match" when enumerating.
	return ,(New-Object System.Collections.ArrayList)
}

function Get-MBTaskBoardObject {
	$tb = $null
	try { $tb = $script:MB.TaskBoard } catch { $tb = $null }
	if ($null -eq $tb) {
		$empty = New-Object System.Collections.ArrayList
		$tb = [ordered]@{
			Goal    = ''
			Items   = $empty
			Updated = ''
		}
		$script:MB.TaskBoard = $tb
	} else {
		# Repair corrupt / typed Items so later code never hits List[object]+@() trap
		try {
			$raw = $tb.Items
			if ($null -eq $raw) {
				$tb.Items = New-Object System.Collections.ArrayList
			} elseif ($raw -is [System.Collections.ArrayList]) {
				# good
			} else {
				# Normalize anything else (List[object], Object[], single row, [[]]) into ArrayList
				$fixed = New-Object System.Collections.ArrayList
				try {
					if ($raw -is [System.Collections.IList] -and -not ($raw -is [string])) {
						for ($i = 0; $i -lt $raw.Count; $i++) {
							$el = $null
							try { $el = $raw[$i] } catch { $el = $null }
							if ($null -eq $el) { continue }
							# Skip nested empty arrays from corrupt state items=[[]]
							if ($el -is [System.Array] -and $el.Length -eq 0) { continue }
							if ($el -is [System.Collections.IList] -and -not ($el -is [string]) -and
								-not ($el -is [System.Collections.IDictionary]) -and $el.Count -eq 0) { continue }
							[void]$fixed.Add($el)
						}
					} elseif ($raw -is [System.Collections.IDictionary] -or $raw -is [pscustomobject]) {
						[void]$fixed.Add($raw)
					} elseif ($raw -is [System.Collections.IEnumerable] -and -not ($raw -is [string])) {
						$en = $raw.GetEnumerator()
						try {
							while ($en.MoveNext()) {
								if ($null -ne $en.Current) { [void]$fixed.Add($en.Current) }
							}
						} finally {
							if ($en -is [System.IDisposable]) { try { $en.Dispose() } catch {} }
						}
					}
				} catch {}
				$tb.Items = $fixed
			}
		} catch {
			try { $tb.Items = New-Object System.Collections.ArrayList } catch {}
		}
	}
	return $tb
}

function Get-MBTaskBoardItemCollection {
	# Type-safe board item enumerator for PS 5.1.
	# NEVER use @($tb.Items) — throws ArgumentException on List[object].
	# Returns ArrayList of row objects via Write-Output -NoEnumerate.
	$out = New-Object System.Collections.ArrayList
	$tb = $null
	try { $tb = Get-MBTaskBoardObject } catch { $tb = $null }
	if ($null -eq $tb) { Write-Output -NoEnumerate $out; return }
	$raw = $null
	try { $raw = $tb.Items } catch { $raw = $null }
	if ($null -eq $raw) { Write-Output -NoEnumerate $out; return }

	# Unwrapped single step row (Id/Title/Status shape)
	if ($raw -is [System.Collections.IDictionary] -or ($raw -is [pscustomobject] -and -not ($raw -is [System.Collections.IList]))) {
		$looksLikeRow = $false
		try {
			if ($raw -is [System.Collections.IDictionary]) {
				foreach ($k in @($raw.Keys)) {
					if ([string]$k -match '^(?i)id|title|status|note$') { $looksLikeRow = $true; break }
				}
			} else {
				if ($raw.PSObject.Properties['Id'] -or $raw.PSObject.Properties['id'] -or
					$raw.PSObject.Properties['Title'] -or $raw.PSObject.Properties['title']) {
					$looksLikeRow = $true
				}
			}
		} catch {}
		if ($looksLikeRow) {
			[void]$out.Add($raw)
			Write-Output -NoEnumerate $out; return
		}
	}

	# IList path: index access (safe for ArrayList, List[T], arrays)
	if ($raw -is [System.Collections.IList] -and -not ($raw -is [string])) {
		$n = 0
		try { $n = [int]$raw.Count } catch { $n = 0 }
		for ($i = 0; $i -lt $n; $i++) {
			$el = $null
			try { $el = $raw[$i] } catch { continue }
			if ($null -eq $el) { continue }
			# Drop corrupt nested empties
			if ($el -is [System.Array] -and $el.Length -eq 0) { continue }
			if ($el -is [System.Collections.IList] -and -not ($el -is [string]) -and
				-not ($el -is [System.Collections.IDictionary]) -and
				-not ($el -is [pscustomobject])) {
				try { if ($el.Count -eq 0) { continue } } catch {}
			}
			[void]$out.Add($el)
		}
		Write-Output -NoEnumerate $out; return
	}

	if ($raw -is [string] -or $raw -is [ValueType]) { Write-Output -NoEnumerate $out; return }

	if ($raw -is [System.Collections.IEnumerable]) {
		try {
			$en = $raw.GetEnumerator()
			try {
				while ($en.MoveNext()) {
					if ($null -ne $en.Current) { [void]$out.Add($en.Current) }
				}
			} finally {
				if ($en -is [System.IDisposable]) { try { $en.Dispose() } catch {} }
			}
		} catch {}
		Write-Output -NoEnumerate $out; return
	}

	[void]$out.Add($raw)
	Write-Output -NoEnumerate $out; return
}

function Format-MBTaskBoardText {
	$tb = Get-MBTaskBoardObject
	$items = Get-MBTaskBoardItemCollection
	if ($items.Count -eq 0 -and [string]::IsNullOrWhiteSpace([string]$tb.Goal)) { return '' }
	$paused = $false
	try { $paused = [bool]$script:MB.TaskBoardPaused } catch { $paused = $false }
	$lines = New-Object System.Collections.ArrayList
	$goal = [string]$tb.Goal
	if ([string]::IsNullOrWhiteSpace($goal)) { $goal = '(no goal set)' }
	$ep = 0
	try { $ep = [int](Get-MBTaskBoardEpoch) } catch { $ep = 0 }
	if ($paused) {
		[void]$lines.Add(("Task board (PAUSED - operator Stop/Esc): {0}" -f $goal))
	} else {
		[void]$lines.Add(("Task board: {0}" -f $goal))
	}
	if ($ep -gt 0) { [void]$lines.Add(("board_epoch={0}" -f $ep)) }
	$open = 0
	$current = ''
	$currentId = ''
	$nItems = 0
	try { $nItems = [int]$items.Count } catch { $nItems = 0 }
	for ($ii = 0; $ii -lt $nItems; $ii++) {
		$it = $null
		try { $it = $items[$ii] } catch { continue }
		if ($null -eq $it) { continue }
		$id = Get-MBTaskBoardItemField -Item $it -Name 'Id'
		$title = Get-MBTaskBoardItemField -Item $it -Name 'Title'
		$st = (Get-MBTaskBoardItemField -Item $it -Name 'Status').ToLowerInvariant()
		$note = Get-MBTaskBoardItemField -Item $it -Name 'Note'
		if ([string]::IsNullOrWhiteSpace($title)) { $title = $id }
		$mark = '[ ]'
		if ($st -in @('done', 'complete', 'completed', 'finished', 'ok')) { $mark = '[x]'; $st = 'done' }
		elseif ($st -in @('in_progress', 'active', 'doing', 'wip', 'working')) {
			$mark = '[>]'
			$st = 'in_progress'
			$open++
			if (-not $current) { $current = $title; $currentId = $id }
		}
		elseif ($st -eq 'blocked') { $mark = '[!]'; $open++ }
		else { $st = 'pending'; $open++ }
		$line = (" {0} {1}: {2}" -f $mark, $id, $title)
		if ($st -eq 'blocked' -and $note) { $line += (" (blocked: {0})" -f $note) }
		elseif ($note -and $st -ne 'done') { $line += (" ({0})" -f $note) }
		[void]$lines.Add($line)
	}
	# Sequential focus = first non-done (in_progress or blocked)
	if ($current) {
		if ($currentId) {
			[void]$lines.Add(("NOW: {0}: {1}" -f $currentId, $current))
		} else {
			[void]$lines.Add(("NOW: {0}" -f $current))
		}
	} elseif ($open -gt 0) {
		$waitId = ''; $waitTitle = ''; $waitSt = ''
		for ($jj = 0; $jj -lt $nItems; $jj++) {
			$it2 = $null
			try { $it2 = $items[$jj] } catch { continue }
			if ($null -eq $it2) { continue }
			$st2 = (Get-MBTaskBoardItemField -Item $it2 -Name 'Status').ToLowerInvariant()
			if ($st2 -in @('done', 'complete', 'completed', 'cancelled', 'canceled', 'finished', 'ok')) { continue }
			$waitId = Get-MBTaskBoardItemField -Item $it2 -Name 'Id'
			$waitTitle = Get-MBTaskBoardItemField -Item $it2 -Name 'Title'
			$waitSt = $st2
			break
		}
		if ($waitId) {
			$lab = if ($waitTitle) { $waitTitle } else { $waitId }
			if ($waitSt -eq 'blocked') {
				[void]$lines.Add(("NOW: blocked {0}: {1} (unblock/fix this item — later steps stay frozen)" -f $waitId, $lab))
			} else {
				[void]$lines.Add(("NOW: {0}: {1}" -f $waitId, $lab))
			}
		}
	}
	if ($paused) {
		[void]$lines.Add('PAUSED: Operator stopped mid-board. Sticky shows only the stopped task (kept for resume).')
		[void]$lines.Add('DEFAULT after stop: TaskBoard action=clear then action=set a NEW board for any new request.')
		[void]$lines.Add('RESUME only if operator explicitly asked to continue/resume this plan - then TaskBoard update from the NOW item and keep going (do not clear).')
	} elseif ($open -gt 0) {
		[void]$lines.Add(("Open: {0}" -f $open))
	}
	return ($lines -join "`n")
}

function Suspend-MBTaskBoardForInterrupt {
	# Stop/Esc: collapse sticky to the active task (yellow); keep full board data for resume.
	try {
		if (-not (Test-MBTaskBoardHasOpen)) { return }
	} catch { return }
	try { $script:MB.TaskBoardPaused = $true } catch {}
	try {
		if ($script:MB.Wpf) { $script:MB.Wpf.TaskBoardLastFp = '' }
	} catch {}
	try { Update-MBWpfTaskBoardSticky -Action 'pause' } catch {}
	try {
		Update-MBWpfSticky -Status 'ready' -Hint ("stopped  {0}  taskboard paused (resume or clear)" -f ([char]0x00B7))
	} catch {}
}

function Test-MBUserWantsTaskBoardResume {
	param([string]$Text)
	if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
	$t = $Text.ToLowerInvariant()
	if ($t -match '\b(continue|resume|keep going|pick up where|where you left|finish the (board|plan|list)|carry on|go on)\b') { return $true }
	if ($t -match '^\s*(continue|resume|go)\s*[.!?]?\s*$') { return $true }
	return $false
}

function ConvertTo-MBTaskBoardStatus {
	# Normalize free-form status strings to pending|in_progress|done|blocked (or '').
	param([string]$Status)
	$st = ([string]$Status).Trim().ToLowerInvariant()
	if ([string]::IsNullOrWhiteSpace($st)) { return '' }
	if ($st -in @('active', 'doing', 'wip', 'working', 'start', 'now', 'focus')) { return 'in_progress' }
	if ($st -in @('complete', 'completed', 'finished', 'ok', 'finish', 'closed')) { return 'done' }
	if ($st -in @('fail', 'stuck', 'waiting', 'wait', 'blocked')) { return 'blocked' }
	if ($st -in @('todo', 'open', 'next', 'queued', 'park', 'parked')) { return 'pending' }
	if ($st -in @('pending', 'in_progress', 'done', 'blocked')) { return $st }
	return ''
}

function Get-MBTaskBoardWorkingList {
	# Ordered mutable clone of board items as ArrayList of ordered rows.
	# Index-walk only (never @($tb.Items) / never rely on pipeline enum).
	$out = New-Object System.Collections.ArrayList
	$col = Get-MBTaskBoardItemCollection
	# Peel accidental Object[]{ArrayList} from unary-comma return
	if ($col -is [System.Collections.IList] -and -not ($col -is [string])) {
		try {
			if ($col.Count -eq 1 -and $col[0] -is [System.Collections.IList] -and
				-not ($col[0] -is [string]) -and -not ($col[0] -is [System.Collections.IDictionary])) {
				$col = $col[0]
			}
		} catch {}
	}
	$n = 0
	try { $n = [int]$col.Count } catch { $n = 0 }
	for ($i = 0; $i -lt $n; $i++) {
		$it = $null
		try { $it = $col[$i] } catch { continue }
		if ($null -eq $it) { continue }
		$st = ConvertTo-MBTaskBoardStatus (Get-MBTaskBoardItemField -Item $it -Name 'Status')
		if ([string]::IsNullOrWhiteSpace($st)) { $st = 'pending' }
		[void]$out.Add([ordered]@{
			Id     = Get-MBTaskBoardItemField -Item $it -Name 'Id'
			Title  = Get-MBTaskBoardItemField -Item $it -Name 'Title'
			Status = $st
			Note   = Get-MBTaskBoardItemField -Item $it -Name 'Note'
		})
	}
	# -NoEnumerate keeps empty/1/N ArrayList intact (no Object[]{list} Count=1 trap)
	Write-Output -NoEnumerate $out
}

function Find-MBTaskBoardIndex {
	param($List, [string]$Id)
	if ($null -eq $List -or [string]::IsNullOrWhiteSpace($Id)) { return -1 }
	for ($i = 0; $i -lt $List.Count; $i++) {
		$iid = [string]$List[$i].Id
		if ([string]::Equals($iid, $Id, [StringComparison]::OrdinalIgnoreCase)) { return $i }
	}
	return -1
}

function Test-MBTaskBoardPrefixDone {
	# True if every item in [0..Index-1] is done (terminal).
	param($List, [int]$Index)
	if ($Index -le 0) { return $true }
	for ($j = 0; $j -lt $Index; $j++) {
		if ([string]$List[$j].Status -ne 'done') { return $false }
	}
	return $true
}

function Get-MBTaskBoardFocusIndex {
	# First non-done item index, or -1 if all done / empty.
	param($List)
	if ($null -eq $List -or $List.Count -eq 0) { return -1 }
	for ($i = 0; $i -lt $List.Count; $i++) {
		if ([string]$List[$i].Status -ne 'done') { return $i }
	}
	return -1
}

function Invoke-MBTaskBoardAutoAdvance {
	# Enforce list-order focus after mutations:
	#  done-prefix + single head (in_progress or blocked). Pending head -> promote.
	#  Does not auto-skip blocked. Returns focus id (or '').
	param($List)
	if ($null -eq $List -or $List.Count -eq 0) { return '' }
	# Collapse illegal multi-focus: keep earliest non-done semantics
	$head = Get-MBTaskBoardFocusIndex -List $List
	if ($head -lt 0) { return '' }
	for ($i = 0; $i -lt $List.Count; $i++) {
		$st = [string]$List[$i].Status
		if ($i -lt $head) {
			# Prefix must be terminal
			if ($st -ne 'done') { $List[$i].Status = 'done' }
		} elseif ($i -eq $head) {
			if ($st -eq 'pending') {
				$List[$i].Status = 'in_progress'
			} elseif ($st -eq 'in_progress' -or $st -eq 'blocked') {
				# keep
			} else {
				$List[$i].Status = 'in_progress'
			}
		} else {
			# Suffix: pending only (never in_progress/done/blocked ahead of gate)
			if ($st -eq 'in_progress' -or $st -eq 'blocked' -or $st -eq 'done') {
				$List[$i].Status = 'pending'
				# clear stale blocked notes on demoted suffix
				if ($st -eq 'blocked' -and $List[$i].Note) {
					# leave note; status pending is enough
				}
			} else {
				$List[$i].Status = 'pending'
			}
		}
	}
	$st0 = [string]$List[$head].Status
	if ($st0 -eq 'in_progress' -or $st0 -eq 'blocked') {
		return [string]$List[$head].Id
	}
	return [string]$List[$head].Id
}

function Test-MBTaskBoardSequentialInvariants {
	# Strict open-board shape: [done*][in_progress|blocked][pending*]
	# Returns @{ ok; code; message; index }
	param($List)
	$result = [ordered]@{ ok = $true; code = ''; message = ''; index = -1 }
	if ($null -eq $List -or $List.Count -eq 0) { return $result }
	$seenHead = $false
	for ($i = 0; $i -lt $List.Count; $i++) {
		$st = [string]$List[$i].Status
		if ($st -notin @('pending', 'in_progress', 'done', 'blocked')) {
			$result.ok = $false
			$result.code = 'invalid_status'
			$result.message = ("Invalid status '{0}' on item {1}." -f $st, $List[$i].Id)
			$result.index = $i
			return $result
		}
		if (-not $seenHead) {
			if ($st -eq 'done') { continue }
			# First non-done is the head
			if ($st -in @('in_progress', 'blocked')) {
				$seenHead = $true
				continue
			}
			# pending as head is soft-illegal before auto-advance; after advance it should not remain
			$result.ok = $false
			$result.code = 'sequential_gate'
			$result.message = ("Focus item {0} must be in_progress or blocked (got pending). Update the NOW item only." -f $List[$i].Id)
			$result.index = $i
			return $result
		} else {
			# After head: only pending
			if ($st -ne 'pending') {
				$result.ok = $false
				$result.code = 'sequential_gate'
				$result.message = ("Out-of-order status on {0}: only the focus item may be in_progress/blocked/done; later items stay pending until the gate advances." -f $List[$i].Id)
				$result.index = $i
				return $result
			}
		}
	}
	# All done is valid (complete)
	return $result
}

function Save-MBTaskBoardItems {
	param(
		$List,
		# Untyped on purpose: [string]$Goal=$null becomes '' in PS and wiped the goal on every Ensure/status save.
		$Goal = $null
	)
	$goalKeep = ''
	if ($PSBoundParameters.ContainsKey('Goal')) {
		$goalKeep = [string]$Goal
	} else {
		try { $goalKeep = [string](Get-MBTaskBoardObject).Goal } catch { $goalKeep = '' }
	}
	# ArrayList only — List[object] + @()/foreach blows up on PS 5.1
	$store = New-Object System.Collections.ArrayList
	if ($null -ne $List) {
		# Prefer index walk when IList (avoids enumerator quirks)
		if ($List -is [System.Collections.IList] -and -not ($List -is [string])) {
			$n = 0
			try { $n = [int]$List.Count } catch { $n = 0 }
			for ($i = 0; $i -lt $n; $i++) {
				$row = $null
				try { $row = $List[$i] } catch { continue }
				if ($null -eq $row) { continue }
				# Skip accidental nested empty arrays
				if ($row -is [System.Collections.IList] -and -not ($row -is [string]) -and
					-not ($row -is [System.Collections.IDictionary]) -and -not ($row -is [pscustomobject])) {
					continue
				}
				[void]$store.Add([ordered]@{
					Id     = [string](Get-MBTaskBoardItemField -Item $row -Name 'Id')
					Title  = [string](Get-MBTaskBoardItemField -Item $row -Name 'Title')
					Status = [string](Get-MBTaskBoardItemField -Item $row -Name 'Status')
					Note   = [string](Get-MBTaskBoardItemField -Item $row -Name 'Note')
				})
			}
		} else {
			foreach ($row in $List) {
				if ($null -eq $row) { continue }
				[void]$store.Add([ordered]@{
					Id     = [string](Get-MBTaskBoardItemField -Item $row -Name 'Id')
					Title  = [string](Get-MBTaskBoardItemField -Item $row -Name 'Title')
					Status = [string](Get-MBTaskBoardItemField -Item $row -Name 'Status')
					Note   = [string](Get-MBTaskBoardItemField -Item $row -Name 'Note')
				})
			}
		}
	}
	$script:MB.TaskBoard = [ordered]@{
		Goal    = [string]$goalKeep
		Items   = $store
		Updated = (Get-Date).ToString('o')
	}
}

function Ensure-MBTaskBoardProgress {
	# Sequential repair: done-prefix + single focus (in_progress|blocked). Promote pending head.
	# -NoPromote: leave pending head as-is (rare; resume still promotes unless blocked).
	# Returns focus id (or '').
	param([switch]$NoPromote)
	$list = Get-MBTaskBoardWorkingList
	if ($list.Count -eq 0) { return '' }
	if ($NoPromote) {
		# Only demote illegal multi-focus / suffix; do not promote pending head
		$head = Get-MBTaskBoardFocusIndex -List $list
		if ($head -ge 0) {
			for ($i = 0; $i -lt $list.Count; $i++) {
				if ($i -lt $head -and [string]$list[$i].Status -ne 'done') { $list[$i].Status = 'done' }
				if ($i -gt $head -and [string]$list[$i].Status -ne 'pending') { $list[$i].Status = 'pending' }
			}
		}
		Save-MBTaskBoardItems -List $list
		if ($head -ge 0) { return [string]$list[$head].Id }
		return ''
	}
	$fid = Invoke-MBTaskBoardAutoAdvance -List $list
	Save-MBTaskBoardItems -List $list
	return $fid
}

function Get-MBTaskBoardItemsStructured {
	# Flat ArrayList of row objects (id/title/status/note). Never nested.
	# Callers that need JSON should wrap with New-MBJsonArrayBox / ConvertTo-MBJsonArray.
	$out = New-Object System.Collections.ArrayList
	$col = Get-MBTaskBoardItemCollection
	$n = 0
	try { $n = [int]$col.Count } catch { $n = 0 }
	for ($i = 0; $i -lt $n; $i++) {
		$it = $null
		try { $it = $col[$i] } catch { continue }
		if ($null -eq $it) { continue }
		$st = ConvertTo-MBTaskBoardStatus (Get-MBTaskBoardItemField -Item $it -Name 'Status')
		if ([string]::IsNullOrWhiteSpace($st)) { $st = 'pending' }
		$note = Get-MBTaskBoardItemField -Item $it -Name 'Note'
		$row = [ordered]@{
			id     = Get-MBTaskBoardItemField -Item $it -Name 'Id'
			title  = Get-MBTaskBoardItemField -Item $it -Name 'Title'
			status = $st
		}
		if (-not [string]::IsNullOrWhiteSpace($note)) { $row['note'] = $note }
		[void]$out.Add([pscustomobject]$row)
	}
	return $out
}

function ConvertTo-MBJsonArray {
	# Returns MB.JsonArray box → always serializes as flat JSON [].
	param($Items)
	return (New-MBJsonArrayBox -Items $Items)
}

function Get-MBTaskBoardCounts {
	# Authoritative counters from live board items (not from JSON-wrapper .Count).
	# open = not done (pending + in_progress + blocked).
	$doneN = 0; $openN = 0; $totalN = 0
	$col = Get-MBTaskBoardItemCollection
	$n = 0
	try { $n = [int]$col.Count } catch { $n = 0 }
	for ($i = 0; $i -lt $n; $i++) {
		$it = $null
		try { $it = $col[$i] } catch { continue }
		if ($null -eq $it) { continue }
		$totalN++
		$st = ConvertTo-MBTaskBoardStatus (Get-MBTaskBoardItemField -Item $it -Name 'Status')
		if ([string]::IsNullOrWhiteSpace($st)) { $st = 'pending' }
		if ($st -eq 'done') { $doneN++ } else { $openN++ }
	}
	return [ordered]@{
		done_count  = [int]$doneN
		open_count  = [int]$openN
		total_count = [int]$totalN
		item_count  = [int]$totalN
		progress    = ('{0}/{1}' -f $doneN, $totalN)
	}
}

function Get-MBTaskBoardOpenCount {
	$c = Get-MBTaskBoardCounts
	return [int]$c.open_count
}

function Get-MBTaskBoardNowId {
	# Focus = first non-done (in_progress or blocked). Sequential board has exactly one.
	$col = Get-MBTaskBoardItemCollection
	$n = 0
	try { $n = [int]$col.Count } catch { $n = 0 }
	for ($i = 0; $i -lt $n; $i++) {
		$it = $null
		try { $it = $col[$i] } catch { continue }
		if ($null -eq $it) { continue }
		$st = ConvertTo-MBTaskBoardStatus (Get-MBTaskBoardItemField -Item $it -Name 'Status')
		if ([string]::IsNullOrWhiteSpace($st)) { $st = 'pending' }
		if ($st -eq 'done') { continue }
		return (Get-MBTaskBoardItemField -Item $it -Name 'Id')
	}
	return ''
}

function Get-MBTaskBoardNowTitle {
	$nid = Get-MBTaskBoardNowId
	if ([string]::IsNullOrWhiteSpace($nid)) { return '' }
	$col = Get-MBTaskBoardItemCollection
	$n = 0
	try { $n = [int]$col.Count } catch { $n = 0 }
	for ($i = 0; $i -lt $n; $i++) {
		$it = $null
		try { $it = $col[$i] } catch { continue }
		if ($null -eq $it) { continue }
		$iid = Get-MBTaskBoardItemField -Item $it -Name 'Id'
		if ([string]::Equals($iid, $nid, [StringComparison]::OrdinalIgnoreCase)) {
			$t = Get-MBTaskBoardItemField -Item $it -Name 'Title'
			if ([string]::IsNullOrWhiteSpace($t)) { return $nid }
			return $t
		}
	}
	return $nid
}

function Resolve-MBTaskBoardIdAlias {
	# Map id=now / . / current → real focus id.
	param([string]$Id)
	$raw = ([string]$Id).Trim()
	if ([string]::IsNullOrWhiteSpace($raw)) { return '' }
	if ($raw -match '^(?i)(now|\.|current|focus|active)$') {
		$nid = Get-MBTaskBoardNowId
		if (-not [string]::IsNullOrWhiteSpace($nid)) { return $nid }
	}
	return $raw
}

function Get-MBTaskBoardGoal {
	try { return [string](Get-MBTaskBoardObject).Goal } catch { return '' }
}

function New-MBTaskBoardErrorJson {
	param(
		[string]$Code,
		[string]$Message,
		[string]$Hint = '',
		$Extra = $null
	)
	$counts = Get-MBTaskBoardCounts
	$pay = [ordered]@{
		ok          = $false
		error       = $Code
		code        = $Code
		message     = $Message
		goal        = (Get-MBTaskBoardGoal)
		now         = (Get-MBTaskBoardNowId)
		now_title   = (Get-MBTaskBoardNowTitle)
		epoch       = (Get-MBTaskBoardEpoch)
		open_count  = [int]$counts.open_count
		done_count  = [int]$counts.done_count
		total_count = [int]$counts.total_count
		item_count  = [int]$counts.item_count
		progress    = [string]$counts.progress
		items       = (Get-MBTaskBoardItemsStructured)
	}
	if (-not [string]::IsNullOrWhiteSpace($Hint)) { $pay['hint'] = $Hint }
	if ($null -ne $Extra -and ($Extra -is [hashtable] -or $Extra -is [System.Collections.IDictionary])) {
		foreach ($ek in @($Extra.Keys)) { $pay[$ek] = $Extra[$ek] }
	}
	return (ConvertTo-MBTaskBoardJson $pay -Depth 8)
}

function New-MBTaskBoardEmptyPayload {
	# Stable empty-board snapshot. Live counters are 0/0; last-run lives under final_* only.
	param(
		[string]$ActionName = 'status',
		[string]$Note = '',
		[switch]$LastComplete,
		[switch]$Complete
	)
	$pay = [ordered]@{
		ok          = $true
		action      = $ActionName
		empty       = $true
		goal        = ''
		now         = $null
		now_title   = $null
		epoch       = (Get-MBTaskBoardEpoch)
		items       = (New-Object System.Collections.ArrayList)
		open_count  = 0
		done_count  = 0
		total_count = 0
		item_count  = 0
		progress    = '0/0'
		complete    = [bool]$Complete
	}
	if ($LastComplete) {
		try {
			$lc = $script:MB.TaskBoardLastComplete
			if ($lc -and $lc.Items) {
				$fi = $lc.Items
				$nFi = 0
				try { $nFi = [int]$fi.Count } catch {
					try { $nFi = @(Expand-MBJsonFlatList $fi).Count } catch { $nFi = 0 }
				}
				if ($nFi -gt 0) {
					$pay['last_complete'] = $true
					$pay['complete'] = $true
					$pay['final_items'] = $fi
					$fg = ''
					try { $fg = [string]$lc.Goal } catch {}
					$pay['final_goal'] = $fg
					if ($lc.Board) { $pay['final_board'] = [string]$lc.Board }
					# Live board empty — counters stay 0/0; snapshot size under final_*
					$pay['final_count'] = $nFi
					$pay['instruction'] = 'Plan finished. Do not invent a new board unless the operator asks.'
					if ([string]::IsNullOrWhiteSpace($Note)) {
						$Note = 'No open board. final_items is last completed snapshot. clear drops this snapshot.'
					}
				}
			}
		} catch {}
	}
	if (-not [string]::IsNullOrWhiteSpace($Note)) { $pay['note'] = $Note }
	return $pay
}

function Resume-MBTaskBoardUi {
	# Expand full sticky again; ensure an active in_progress row for paint.
	try { $script:MB.TaskBoardPaused = $false } catch {}
	$hi = ''
	try { $hi = Ensure-MBTaskBoardProgress } catch { $hi = '' }
	try {
		if ($script:MB.Wpf) { $script:MB.Wpf.TaskBoardLastFp = '' }
	} catch {}
	try { Update-MBWpfTaskBoardSticky -Action 'status' -HighlightId $hi } catch {}
	try {
		if ($hi) {
			Update-MBWpfSticky -Status 'working' -Hint ("esc interrupt  {0}  task: {1}" -f ([char]0x00B7), $hi)
		}
	} catch {}
}

function Write-MBTaskBoardInline {
	# Operator UI: sticky flyout under tool chips only (no chat / console lines).
	# Model still gets the JSON tool result from Invoke-TaskBoard.
	param(
		[string]$Action = '',
		[string]$HighlightId = ''
	)
	try {
		$act = ([string]$Action).Trim().ToLowerInvariant()
		# Always drive the sticky flyout when WPF is up
		try { Update-MBWpfTaskBoardSticky -Action $act -HighlightId $HighlightId } catch {}

		$tb = Get-MBTaskBoardObject
		$goal = ''
		try { $goal = [string]$tb.Goal } catch {}
		$items = Get-MBTaskBoardItemCollection
		$empty = ($act -eq 'clear') -or ($items.Count -eq 0 -and [string]::IsNullOrWhiteSpace($goal))

		# Status-bar hint only (not chat log) — same field reader as listview snapshot
		try {
			if ($empty) {
				Update-MBWpfSticky -Status 'working' -Hint ("esc interrupt  {0}  taskboard empty" -f ([char]0x00B7))
			} else {
				$progTitle = ''
				$progIdHint = ''
				$openN = 0; $total = 0
				for ($ii = 0; $ii -lt $items.Count; $ii++) {
					$it = $items[$ii]
					if ($null -eq $it) { continue }
					$total++
					$st = (Get-MBTaskBoardItemField -Item $it -Name 'Status').ToLowerInvariant()
					if ($st -in @('active', 'doing', 'wip', 'working')) { $st = 'in_progress' }
					if ($st -in @('complete', 'completed', 'finished')) { $st = 'done' }
					if ($st -eq 'done') { continue }
					$openN++
					if ($st -eq 'in_progress' -and -not $progTitle) {
						$progIdHint = Get-MBTaskBoardItemField -Item $it -Name 'Id'
						$progTitle = Get-MBTaskBoardItemField -Item $it -Name 'Title'
						if (-not $progTitle) { $progTitle = $progIdHint }
					}
				}
				if ($progTitle) {
					$label = $progTitle
					if ($progIdHint) { $label = ('{0} {1}' -f $progIdHint, $progTitle) }
					$hint = ("esc interrupt  {0}  task: {1}" -f ([char]0x00B7), $label)
					if ($hint.Length -gt 72) { $hint = $hint.Substring(0, 69) + '...' }
					Update-MBWpfSticky -Status 'working' -Hint $hint
				} elseif ($openN -eq 0 -and $total -gt 0) {
					Update-MBWpfSticky -Status 'working' -Hint ("esc interrupt  {0}  taskboard complete" -f ([char]0x00B7))
				}
			}
		} catch {}

		# No console/chat dump — sticky flyout (WPF) is the only operator view
	} catch {}
}

function Test-MBTaskBoardHasOpen {
	# True when the board has items and at least one is not done/cancelled.
	$items = Get-MBTaskBoardItemCollection
	if ($items.Count -eq 0) { return $false }
	for ($i = 0; $i -lt $items.Count; $i++) {
		$it = $items[$i]
		if ($null -eq $it) { continue }
		$st = (Get-MBTaskBoardItemField -Item $it -Name 'Status').ToLowerInvariant()
		if ($st -in @('active', 'doing', 'wip', 'working')) { $st = 'in_progress' }
		if ($st -in @('complete', 'completed', 'finished', 'ok')) { $st = 'done' }
		if ($st -notin @('done', 'cancelled', 'canceled')) { return $true }
	}
	return $false
}

function Test-MBTaskBoardAllDone {
	# Board exists with items and every item is done/cancelled.
	$items = Get-MBTaskBoardItemCollection
	if ($items.Count -eq 0) { return $false }
	return -not (Test-MBTaskBoardHasOpen)
}

function Test-MBReplySignalsTaskBoardDone {
	param([string]$Text)
	if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
	$t = $Text.ToLowerInvariant()
	if ($t -match 'all\s+passed|all\s+\d+\s+(smoke\s+)?(test|tests|item|items|check|checks|categor(?:y|ies))\s+(passed|complete|ok|verified)') { return $true }
	if ($t -match '✅\s*all|all\s+(tests?|items?|checks?)\s+(passed|complete)|smoke\s+tests?\s+.*\bpass') { return $true }
	if ($t -match '\bdid:\s*.{0,80}\b(pass|complete|verified|functional)\b' -and $t -match '\b(all|complete|done)\b') { return $true }
	if ($t -match 'board\s+complete|open\s+items:\s*0|task\s*board\s+(cleared|complete)') { return $true }
	if ($t -match '\b(summary|final\s+report|report\s+complete|work\s+complete|job\s+complete|plan\s+complete)\b' -and
		$t -match '\b(done|complete|finished|success|passed|all set|ready)\b') { return $true }
	if ($t -match '\b(that\s+(completes?|finishes?)|everything\s+is\s+(done|complete|finished)|no\s+further\s+(action|steps?)\b)') { return $true }
	if ($t -match '(?m)^\s*(did|done|complete|completed)\s*[:\-]' -and $t.Length -gt 400) { return $true }
	return $false
}

function Get-MBTaskBoardIncompleteNudgeText {
	$nowId = ''
	$nowTitle = ''
	$openN = 0
	$total = 0
	$progress = ''
	$epoch = 0
	try { $nowId = [string](Get-MBTaskBoardNowId) } catch { $nowId = '' }
	try { $nowTitle = [string](Get-MBTaskBoardNowTitle) } catch { $nowTitle = '' }
	try {
		$c = Get-MBTaskBoardCounts
		$openN = [int]$c.open_count
		$total = [int]$c.total_count
		$progress = [string]$c.progress
	} catch {}
	try { $epoch = [int](Get-MBTaskBoardEpoch) } catch { $epoch = 0 }
	if ([string]::IsNullOrWhiteSpace($nowId)) { $nowId = 'now' }
	$nowLab = $nowId
	if (-not [string]::IsNullOrWhiteSpace($nowTitle)) { $nowLab = ('{0}: {1}' -f $nowId, $nowTitle) }
	$progBit = if ($progress) { $progress } else { ('{0} open' -f $openN) }
	$epBit = if ($epoch -gt 0) { (' epoch={0}' -f $epoch) } else { '' }
	$isLastOpen = ($openN -le 1 -and $total -gt 0)

	if ($isLastOpen) {
		return @(
			('[TASKBOARD] Plan nearly finished ({0}). Board still open on {1}.' -f $progBit, $nowLab)
			'If that step (and the overall work) is already done: TaskBoard update id=now status=done' + $epBit + ' then TaskBoard action=clear.'
			'If it is NOT done: continue ONLY that step from where you left off — do not restart earlier steps and do not repeat a full report already given.'
			'Then end normally (short DID/NEXT or final cleanup only).'
		) -join ' '
	}

	return @(
		('[TASKBOARD] Board still open ({0}). NOW = {1}.' -f $progBit, $nowLab)
		('If NOW is already finished: TaskBoard update id=now status=done{0} and continue with the next pending step only.' -f $epBit)
		'If NOW is not finished: resume that step where you left off (tools as needed).'
		'Do not restate prior findings or re-run completed steps. Do not give another full report until the board is clear.'
	) -join ' '
}

function Complete-MBTaskBoard {
	# Mark any remaining open items done, paint once, then clear so sticky resets cleanly.
	param(
		[switch]$ForceMarkDone,
		[string]$Reason = 'complete'
	)
	$tb = Get-MBTaskBoardObject
	$items = Get-MBTaskBoardItemCollection
	if ($items.Count -eq 0) {
		try { Write-MBTaskBoardInline -Action 'clear' } catch {}
		return $false
	}
	if ($ForceMarkDone) {
		for ($i = 0; $i -lt $items.Count; $i++) {
			$it = $items[$i]
			if ($null -eq $it) { continue }
			$st = (Get-MBTaskBoardItemField -Item $it -Name 'Status').ToLowerInvariant()
			if ($st -notin @('done', 'complete', 'completed', 'cancelled', 'canceled')) {
				Set-MBTaskBoardItemField -Item $it -Name 'Status' -Value 'done'
			}
		}
	}
	$goalKeep = ''
	try { $goalKeep = [string]$tb.Goal } catch {}
	$norm = New-Object System.Collections.ArrayList
	for ($i = 0; $i -lt $items.Count; $i++) {
		$it = $items[$i]
		if ($null -eq $it) { continue }
		$nst = (Get-MBTaskBoardItemField -Item $it -Name 'Status').ToLowerInvariant()
		if ($nst -in @('complete', 'completed', 'finished', 'ok')) { $nst = 'done' }
		if ($nst -notin @('pending', 'in_progress', 'done', 'blocked')) { $nst = 'done' }
		[void]$norm.Add([ordered]@{
			Id     = (Get-MBTaskBoardItemField -Item $it -Name 'Id')
			Title  = (Get-MBTaskBoardItemField -Item $it -Name 'Title')
			Status = $nst
			Note   = (Get-MBTaskBoardItemField -Item $it -Name 'Note')
		})
	}
	Save-MBTaskBoardItems -List $norm -Goal $goalKeep
	try { $script:MB.TaskBoardPaused = $false } catch {}
	# Snapshot for audit BEFORE clear (must not fail closed — final_items needed on complete response)
	$snapItems = New-Object System.Collections.ArrayList
	for ($i = 0; $i -lt $norm.Count; $i++) {
		$fi = $norm[$i]
		if ($null -eq $fi) { continue }
		[void]$snapItems.Add([ordered]@{
			id     = [string](Get-MBTaskBoardItemField -Item $fi -Name 'Id')
			title  = [string](Get-MBTaskBoardItemField -Item $fi -Name 'Title')
			status = [string](Get-MBTaskBoardItemField -Item $fi -Name 'Status')
			note   = [string](Get-MBTaskBoardItemField -Item $fi -Name 'Note')
		})
	}
	$boardText = ''
	try { $boardText = [string](Format-MBTaskBoardText) } catch { $boardText = '' }
	$script:MB.TaskBoardLastComplete = [ordered]@{
		Goal    = $goalKeep
		Items   = $snapItems
		Reason  = $Reason
		At      = (Get-Date).ToString('o')
		Board   = $boardText
		Count   = [int]$snapItems.Count
	}
	# Show completed board briefly, then clear sticky + data
	try {
		if ($script:MB.Wpf) { $script:MB.Wpf.TaskBoardLastFp = '' }
	} catch {}
	try { Write-MBTaskBoardInline -Action 'status' } catch {}
	# Clear data so incomplete-nudge cannot fire again and sticky fully resets
	$script:MB.TaskBoard = [ordered]@{
		Goal    = ''
		Items   = (New-Object System.Collections.ArrayList)
		Updated = (Get-Date).ToString('o')
	}
	try { $script:MB.TaskBoardPaused = $false } catch {}
	try { $script:MB.PendingTaskBoardNudge = $false } catch {}
	try { Write-MBTaskBoardInline -Action 'clear' } catch {}
	# Board gone — release hold so turn end can thaw; do not rewrite system mid-loop
	try { $script:MB.WireFreezeHeldForBoard = $false } catch {}
	# Do NOT Freeze-MBWireState -Refresh / Sync mid tool-loop here.
	return $true
}

function Stop-MBWpfTaskBoardPulse {
	# Clear color/opacity pulses on sticky TaskBoard rows (UI thread).
	try {
		$W = $script:MB.Wpf
		if (-not $W) { return }
		foreach ($el in @($W.TaskBoardPulseEls)) {
			if ($null -eq $el) { continue }
			try {
				if ($el -is [System.Windows.Media.SolidColorBrush]) {
					Stop-MBBrushColorPulse -Brush $el
				} else {
					Stop-MBElementOpacityPulse -Element $el -RestOpacity 1.0
				}
			} catch {}
		}
		$W.TaskBoardPulseEls = New-Object System.Collections.ArrayList
	} catch {}
}

function Get-MBTaskBoardItemField {
	# Robust field read for OrderedDictionary / PSCustomObject / mixed case keys.
	param($Item, [string]$Name)
	if ($null -eq $Item -or [string]::IsNullOrWhiteSpace($Name)) { return '' }
	try {
		if ($Item -is [System.Collections.IDictionary]) {
			if ($Item.Contains($Name)) {
				$v = $Item[$Name]
				if ($null -ne $v) { return [string]$v }
			}
			foreach ($k in @($Item.Keys)) {
				if ([string]::Equals([string]$k, $Name, [StringComparison]::OrdinalIgnoreCase)) {
					$v = $Item[$k]
					if ($null -ne $v) { return [string]$v }
				}
			}
		}
	} catch {}
	try {
		$v = $Item.$Name
		if ($null -ne $v) { return [string]$v }
	} catch {}
	return ''
}

function Set-MBTaskBoardItemField {
	param($Item, [string]$Name, $Value)
	if ($null -eq $Item -or [string]::IsNullOrWhiteSpace($Name)) { return }
	try {
		if ($Item -is [System.Collections.IDictionary]) {
			$key = $Name
			foreach ($k in @($Item.Keys)) {
				if ([string]::Equals([string]$k, $Name, [StringComparison]::OrdinalIgnoreCase)) { $key = $k; break }
			}
			$Item[$key] = $Value
		}
	} catch {}
	try { $Item.$Name = $Value } catch {}
}

function Request-MBWpfTaskBoardPaint {
	param($Snap)
	if ($null -eq $Snap) { return }
	try {
		if (-not $script:MB.Wpf) { return }
		try { $script:MB.Wpf.TaskBoardLastFp = '' } catch {}
		try { $script:MB.Wpf.TaskBoardPaintUrgent = $true } catch {}
		try { $script:MB.Wpf.TaskBoardPaintRetry = 0 } catch {}
		$sq = 0
		try { $sq = [int]$Snap.Seq } catch { $sq = 0 }
		# LiveSnap is always the latest board picture. Pending is only a dirty flag.
		# STA must paint LiveSnap (not a dequeued older Pending) or the sticky lags 1-2 steps.
		try {
			if ($sq -gt 0) {
				$script:MB.Wpf.TaskBoardWantSeq = $sq
				$script:MB.Wpf.TaskBoardLiveGen = $sq
			}
		} catch {}
		$script:MB.Wpf.TaskBoardLiveSnap = $Snap
		$script:MB.Wpf.PendingTaskBoard = $Snap
		# STA kick (Action created on WPF thread). Priority-first BeginInvoke overload
		# (Delegate, priority) can mis-bind and pass priority as an Action arg.
		try {
			$d = $null
			try { $d = $script:MB.Wpf.Dispatcher } catch { $d = $null }
			$kick = $null
			try { $kick = $script:MB.Wpf.KickTaskBoardPaint } catch { $kick = $null }
			if ($null -ne $d -and $null -ne $kick) {
				$prio = [System.Windows.Threading.DispatcherPriority]::Send
				if ($kick -is [System.Action]) {
					if ($d.CheckAccess()) { try { $kick.Invoke() } catch {} }
					else { [void]$d.BeginInvoke($prio, $kick) }
				} elseif ($kick -is [scriptblock]) {
					if ($d.CheckAccess()) { try { & $kick } catch {} }
					else { [void]$d.BeginInvoke($prio, $kick) }
				}
			}
		} catch {}
	} catch {}
}

function Update-MBWpfTaskBoardSticky {
	# Build TaskBoard sticky snapshot for STA paint.
	param(
		[string]$Action = '',
		[string]$HighlightId = ''
	)
	if (-not $script:MB.Wpf) { return }
	try {
		if (-not [bool]$script:MB.Wpf.Ready -and -not $script:MB.Wpf.Window) { return }
	} catch {}
	$tb = $null
	try { $tb = Get-MBTaskBoardObject } catch { $tb = $null }
	$goal = ''
	$items = New-Object System.Collections.ArrayList
	try { $goal = [string]$tb.Goal } catch {}
	try { $items = Get-MBTaskBoardItemCollection } catch { $items = New-Object System.Collections.ArrayList }
	$act = ([string]$Action).Trim().ToLowerInvariant()
	if ($act -in @('pause', 'suspend', 'stop')) { $act = 'pause' }
	# Single yellow "paused" row ONLY for explicit pause action — not residual TaskBoardPaused
	# during update/status after resume (that stuck the active purple row).
	$collapsePause = ($act -eq 'pause')
	$pausedFlag = $false
	try { $pausedFlag = [bool]$script:MB.TaskBoardPaused } catch { $pausedFlag = $false }
	if ($collapsePause) { $pausedFlag = $true }
	# Live work paints (update/set/status/clear) always expand full board
	if ($act -in @('update', 'set', 'status', 'clear', 'retract') -and $act -ne 'pause') {
		$collapsePause = $false
		# Keep data flag until resume/update clears it; UI still shows full list
	}
	$empty = ($act -eq 'clear') -or ($act -eq 'retract') -or ($items.Count -eq 0 -and [string]::IsNullOrWhiteSpace($goal))

	$rows = New-Object System.Collections.ArrayList
	$doneN = 0; $openN = 0; $blockN = 0; $progTitle = ''; $progId = ''; $progNote = ''
	$firstOpen = $null
	if (-not $empty) {
		for ($ti = 0; $ti -lt $items.Count; $ti++) {
			$it = $items[$ti]
			if ($null -eq $it) { continue }
			$id = Get-MBTaskBoardItemField -Item $it -Name 'Id'
			$title = Get-MBTaskBoardItemField -Item $it -Name 'Title'
			$st = (Get-MBTaskBoardItemField -Item $it -Name 'Status').ToLowerInvariant()
			$note = Get-MBTaskBoardItemField -Item $it -Name 'Note'
			if ([string]::IsNullOrWhiteSpace($st)) { $st = 'pending' }
			if ([string]::IsNullOrWhiteSpace($title)) { $title = $id }
			if ($st -in @('active', 'doing', 'wip', 'working')) { $st = 'in_progress' }
			if ($st -in @('complete', 'completed', 'finished', 'ok')) { $st = 'done' }
			if ($st -eq 'done') { $doneN++ }
			elseif ($st -eq 'blocked') {
				$blockN++; $openN++
				if ($null -eq $firstOpen) {
					$firstOpen = [pscustomobject]@{ Id = $id; Title = $title; Status = 'blocked'; Note = $note }
				}
			}
			elseif ($st -eq 'in_progress') {
				$openN++
				if (-not $progTitle) {
					$progTitle = $title
					$progId = $id
					$progNote = $note
				}
				if ($null -eq $firstOpen) {
					$firstOpen = [pscustomobject]@{ Id = $id; Title = $title; Status = 'in_progress'; Note = $note }
				}
			} else {
				$st = 'pending'
				$openN++
				if ($null -eq $firstOpen) {
					$firstOpen = [pscustomobject]@{ Id = $id; Title = $title; Status = 'pending'; Note = $note }
				}
			}
			# Always collect full rows; pause collapse rebuilds below
			[void]$rows.Add([pscustomobject]@{
				Id = [string]$id; Title = [string]$title; Status = [string]$st; Note = [string]$note
			})
		}
	}
	# Pause sticky: single yellow row ONLY on explicit Stop/Esc paint (action=pause)
	if ($collapsePause -and -not $empty) {
		$rows = New-Object System.Collections.ArrayList
		$stopId = $progId
		$stopTitle = $progTitle
		$stopNote = $progNote
		if ([string]::IsNullOrWhiteSpace($stopTitle) -and $firstOpen) {
			try { $stopId = [string]$firstOpen.Id } catch {}
			try { $stopTitle = [string]$firstOpen.Title } catch {}
			try { $stopNote = [string]$firstOpen.Note } catch {}
		}
		if ([string]::IsNullOrWhiteSpace($stopTitle)) { $stopTitle = 'stopped' }
		if ([string]::IsNullOrWhiteSpace($stopId)) { $stopId = 'stop' }
		[void]$rows.Add([pscustomobject]@{
			Id = [string]$stopId
			Title = [string]$stopTitle
			Status = 'paused'
			Note = $(if ($stopNote) { $stopNote } else { 'operator stop' })
		})
	}
	if ([string]::IsNullOrWhiteSpace($goal) -and -not $empty) { $goal = '(no goal set)' }
	$totalAll = 0
	try { $totalAll = [int]$items.Count } catch { $totalAll = $rows.Count }
	$total = $rows.Count
	$sum = ''
	$showPausedChrome = $collapsePause
	if (-not $empty) {
		if ($showPausedChrome) {
			$sum = ('paused  {0}/{1} done' -f $doneN, $totalAll)
			if ($progTitle) { $sum += ('  |  stop: {0}' -f $progTitle) }
			else { $sum += '  |  stop here' }
		} else {
			$sum = ('{0}/{1} done' -f $doneN, $totalAll)
			if ($openN -gt 0) { $sum += (', {0} open' -f $openN) }
			if ($blockN -gt 0) { $sum += (', {0} blocked' -f $blockN) }
			if ($progTitle) { $sum += ('  |  now: {0}' -f $progTitle) }
			elseif ($openN -eq 0 -and $totalAll -gt 0) { $sum += '  |  complete' }
		}
	}
	$wantShow = (-not $empty) -and ($total -gt 0 -or -not [string]::IsNullOrWhiteSpace($goal) -or $showPausedChrome)
	$wantRetract = $false
	if ($act -eq 'clear' -or $act -eq 'retract') {
		$wantShow = $false
		$wantRetract = $true
		$showPausedChrome = $false
	} elseif ($wantShow -and -not $showPausedChrome -and $openN -eq 0 -and $totalAll -gt 0) {
		# Complete: show then auto-retract
		$wantRetract = $true
	}

	# Focus active in_progress row (HighlightId only if still active).
	$focusId = ''
	$firstProgId = ''
	foreach ($rr0 in @($rows)) {
		try {
			$rs0 = [string]$rr0.Status
			$rid0 = [string]$rr0.Id
			if (($rs0 -eq 'in_progress' -or $rs0 -eq 'paused') -and -not [string]::IsNullOrWhiteSpace($rid0)) {
				if (-not $firstProgId) { $firstProgId = $rid0 }
			}
		} catch {}
	}
	$hiIn = ([string]$HighlightId).Trim()
	if (-not [string]::IsNullOrWhiteSpace($hiIn)) {
		foreach ($rr1 in @($rows)) {
			try {
				if ([string]::Equals([string]$rr1.Id, $hiIn, [StringComparison]::OrdinalIgnoreCase) -and
					(([string]$rr1.Status) -eq 'in_progress' -or ([string]$rr1.Status) -eq 'paused')) {
					$focusId = [string]$rr1.Id
					break
				}
			} catch {}
		}
	}
	if ([string]::IsNullOrWhiteSpace($focusId)) { $focusId = $firstProgId }
	# Monotonic paint seq (never TickCount — that poisons AppliedSeq and freezes later paints).
	$seq = 1
	try {
		$prevSeq = 0
		try { $prevSeq = [int]$script:MB.Wpf.TaskBoardSeqCounter } catch { $prevSeq = 0 }
		if ($prevSeq -lt 0) { $prevSeq = 0 }
		$seq = $prevSeq + 1
		$script:MB.Wpf.TaskBoardSeqCounter = $seq
	} catch { $seq = 1 }
	# Snapshot rows for STA paint (plain Hashtable — STA bag / cross-runspace safe).
	$rowCopies = New-Object System.Collections.ArrayList
	foreach ($rCopy in @($rows)) {
		if ($null -eq $rCopy) { continue }
		$cId = ''; $cTitle = ''; $cSt = ''; $cNote = ''
		try { $cId = [string]$rCopy.Id } catch {}
		try { $cTitle = [string]$rCopy.Title } catch {}
		try { $cSt = [string]$rCopy.Status } catch {}
		try { $cNote = [string]$rCopy.Note } catch {}
		$rh = New-Object System.Collections.Hashtable
		$rh['Id'] = $cId
		$rh['Title'] = $cTitle
		$rh['Status'] = $cSt
		$rh['Note'] = $cNote
		[void]$rowCopies.Add($rh)
	}
	$snap = New-Object System.Collections.Hashtable
	$snap['WantShow'] = [bool]$wantShow
	$snap['WantRetract'] = [bool]$wantRetract
	$snap['Empty'] = [bool]$empty
	$snap['Paused'] = [bool]$showPausedChrome
	$snap['Goal'] = [string]$goal
	$snap['Summary'] = [string]$sum
	$snap['Rows'] = @($rowCopies.ToArray())
	$snap['Action'] = [string]$act
	$snap['OpenN'] = [int]$openN
	$snap['DoneN'] = [int]$doneN
	$snap['Total'] = [int]$totalAll
	$snap['FocusId'] = [string]$focusId
	$snap['Seq'] = [int]$seq
	try { Request-MBWpfTaskBoardPaint -Snap $snap } catch {
		try {
			$script:MB.Wpf.TaskBoardLiveSnap = $snap
			$script:MB.Wpf.TaskBoardLiveGen = $seq
			$script:MB.Wpf.PendingTaskBoard = $snap
			$script:MB.Wpf.TaskBoardPaintUrgent = $true
			$script:MB.Wpf.TaskBoardLastFp = ''
		} catch {}
	}
}

function Apply-MBWpfTaskBoardSticky {
	# Queues PendingTaskBoard for STA ApplyTaskBoardSticky.
	param($S)
	if ($null -eq $S) { return }
	try {
		if ($script:MB.Wpf) { $script:MB.Wpf.PendingTaskBoard = $S }
	} catch {}
}

function Invoke-TaskBoard {
	# Ordered execution cursor: done-prefix + single focus (now).
	# Sequential gate, transactional batch update, auto-advance on done.
	# Single-flight: one TaskBoard mutation per agent turn (do not parallel status/update/clear).
	param(
		[string]$action = 'status',
		[string]$goal = '',
		$items = $null,
		[string]$id = '',
		[string]$status = '',
		[string]$title = '',
		[string]$note = '',
		$replace = $false,
		$updates = $null,
		$ids = $null,
		# Monotonic epoch from last response — pass through so id=now+done is not loop-guarded
		$epoch = $null,
		[switch]$verbose
	)
	$act = ([string]$action).Trim().ToLowerInvariant()
	if ([string]::IsNullOrWhiteSpace($act)) { $act = 'status' }
	if ($act -in @('show', 'get', 'list', 'read')) { $act = 'status' }
	if ($act -in @('reset', 'wipe')) { $act = 'clear' }
	if ($act -in @('replace', 'new', 'create', 'plan')) { $act = 'set' }
	if ($act -in @('patch', 'mark', 'complete', 'finish', 'start')) { $act = 'update' }
	$doReplace = $false
	try { $doReplace = [bool](Convert-MBToBool -Value $replace -Default $false) } catch {
		try { $doReplace = [bool]$replace } catch { $doReplace = $false }
	}

	$buildStatePayload = {
		param(
			[string]$ActionName,
			[string]$FocusId = '',
			[switch]$Complete,
			[string]$ItemNote = '',
			[switch]$IncludeBoardText,
			$Extra = $null,
			[switch]$Coerced
		)
		$counts = Get-MBTaskBoardCounts
		$goal = Get-MBTaskBoardGoal
		$nowId = Get-MBTaskBoardNowId
		$nowTitle = Get-MBTaskBoardNowTitle
		$itemsList = Get-MBTaskBoardItemsStructured
		# On complete, sticky is cleared — do not resurrect FocusId as now
		if ($Complete) {
			$nowId = $null
			$nowTitle = $null
			$itemsList = New-Object System.Collections.ArrayList
		} elseif ([string]::IsNullOrWhiteSpace($nowId) -and $FocusId) {
			$nowId = $FocusId
		}
		$epoch = Get-MBTaskBoardEpoch
		$pay = [ordered]@{
			ok          = $true
			action      = $ActionName
			goal        = $goal
			now         = $nowId
			now_title   = $nowTitle
			epoch       = [int]$epoch
			open_count  = [int]$counts.open_count
			done_count  = [int]$counts.done_count
			total_count = [int]$counts.total_count
			item_count  = [int]$counts.item_count
			progress    = [string]$counts.progress
			complete    = [bool]$Complete
			items       = $itemsList
		}
		# updated_id = item touched this call; now = focus after auto-promote
		if (-not $Complete -and -not [string]::IsNullOrWhiteSpace($FocusId)) {
			$pay['updated_id'] = $FocusId
		}
		if (-not [string]::IsNullOrWhiteSpace($ItemNote)) { $pay['item_note'] = $ItemNote }
		if ($Coerced) { $pay['coerced'] = $true }
		if (-not $Complete -and -not [string]::IsNullOrWhiteSpace($nowTitle)) {
			$pay['instruction'] = ('Do only: {0}' -f $nowTitle)
		}
		if ($IncludeBoardText -or $verbose) {
			try { $pay['board'] = (Format-MBTaskBoardText) } catch {}
		}
		if ($Complete) {
			# Live board is empty: counters 0/0. Snapshot only under final_*.
			$pay['now'] = $null
			$pay['now_title'] = $null
			$pay['items'] = (New-Object System.Collections.ArrayList)
			$pay['open_count'] = 0
			$pay['done_count'] = 0
			$pay['total_count'] = 0
			$pay['item_count'] = 0
			$pay['progress'] = '0/0'
			$pay['complete'] = $true
			$pay['empty'] = $true
			try {
				$lc = $script:MB.TaskBoardLastComplete
				if ($lc) {
					$pay['final_items'] = $lc.Items
					$fiN = 0
					try { $fiN = [int]$lc.Items.Count } catch { $fiN = 0 }
					if ($lc.Goal) {
						$pay['final_goal'] = [string]$lc.Goal
						$pay['goal'] = [string]$lc.Goal
					}
					if ($lc.Board) { $pay['final_board'] = [string]$lc.Board }
					$pay['final_count'] = $fiN
				}
			} catch {}
			$pay['note'] = 'Board complete - sticky cleared (final_items snapshot kept until clear).'
			$pay['instruction'] = 'Plan finished. Do not invent a new board unless the operator asks.'
		}
		if ($null -ne $Extra -and ($Extra -is [hashtable] -or $Extra -is [System.Collections.IDictionary])) {
			foreach ($ek in @($Extra.Keys)) { $pay[$ek] = $Extra[$ek] }
		}
		return (ConvertTo-MBTaskBoardJson $pay -Depth 8)
	}.GetNewClosure()

	if ($act -eq 'clear') {
		# Prefer open board; if already empty after complete, drop last-complete snapshot and report it
		$clearedGoal = Get-MBTaskBoardGoal
		$clearedItems = Get-MBTaskBoardItemsStructured
		$clearedCounts = Get-MBTaskBoardCounts
		$fromLast = $false
		if ([int]$clearedCounts.total_count -eq 0) {
			try {
				$lc = $script:MB.TaskBoardLastComplete
				if ($lc -and $lc.Items) {
					$nLc = 0
					try { $nLc = [int]$lc.Items.Count } catch { $nLc = 0 }
					if ($nLc -gt 0) {
						$clearedGoal = [string]$lc.Goal
						$clearedItems = $lc.Items
						$clearedCounts = [ordered]@{ total_count = $nLc }
						$fromLast = $true
					}
				}
			} catch {}
		}
		$script:MB.TaskBoard = [ordered]@{
			Goal = ''; Items = (New-Object System.Collections.ArrayList); Updated = (Get-Date).ToString('o')
		}
		try { $script:MB.TaskBoardLastComplete = $null } catch {}
		try { $script:MB.TaskBoardPaused = $false } catch {}
		try { Write-MBTaskBoardInline -Action 'clear' } catch {}
		$pay = New-MBTaskBoardEmptyPayload -ActionName 'clear' -Complete `
			-Note $(if ($fromLast) {
				'Board cleared (hard reset; dropped last-complete final_items snapshot).'
			} else {
				'Board cleared (hard reset; final_items snapshot dropped).'
			})
		$pay['board'] = 'empty'
		$pay['cleared_goal'] = $clearedGoal
		$pay['cleared_items'] = $clearedItems
		$pay['cleared_total'] = [int]$clearedCounts.total_count
		return (ConvertTo-MBTaskBoardJson $pay -Depth 8)
	}

	if ($act -eq 'status') {
		try { $script:MB.TaskBoardPaused = $false } catch {}
		try { $null = Ensure-MBTaskBoardProgress } catch {}
		$counts = Get-MBTaskBoardCounts
		if ([int]$counts.total_count -eq 0) {
			try { Write-MBTaskBoardInline -Action 'status' } catch {}
			$pay = New-MBTaskBoardEmptyPayload -ActionName 'status' -LastComplete -Complete
			if (-not $pay.Contains('last_complete')) {
				$pay['complete'] = $true
				$pay['note'] = 'No TaskBoard yet. Multi-step: action=set goal=... items=[...] (ordered plan; execute only now).'
			}
			return (ConvertTo-MBTaskBoardJson $pay -Depth 8)
		}
		try {
			if ($script:MB.Wpf) { $script:MB.Wpf.TaskBoardLastFp = '' }
		} catch {}
		try { Write-MBTaskBoardInline -Action 'status' } catch {}
		return (& $buildStatePayload -ActionName 'status' -IncludeBoardText)
	}

	if ($act -eq 'set') {
		$g = ([string]$goal).Trim()
		$rawItems = New-Object System.Collections.ArrayList
		if ($null -ne $items) {
			if ($items -is [string]) {
				foreach ($p in ($items -split '[\r\n;|]+')) {
					if ($p.Trim()) { [void]$rawItems.Add($p.Trim()) }
				}
			} else {
				foreach ($x in @($items)) {
					if ($null -eq $x) { continue }
					[void]$rawItems.Add($x)
				}
			}
		}
		if ($rawItems.Count -eq 0) {
			return (New-MBTaskBoardErrorJson -Code 'empty_items' `
				-Message 'set requires non-empty items=[...]. Goal-only or empty set is refused (would wipe the board).' `
				-Hint 'Pass items as ordered strings or {id,title}. To replace an open board: replace=true with goal+items.')
		}
		# Soft cap (tiny models); refuse novels
		if ($rawItems.Count -gt 12) {
			return (New-MBTaskBoardErrorJson -Code 'batch_conflict' `
				-Message ('Too many items ({0}). Cap is 12 steps for this harness.' -f $rawItems.Count) `
				-Hint 'Split into a smaller ordered plan (max 12).')
		}
		$priorSnap = $null
		try {
			if ((Test-MBTaskBoardHasOpen) -and -not $doReplace) {
				return (New-MBTaskBoardErrorJson -Code 'board_open_use_replace' `
					-Message 'TaskBoard already has open items. Pass replace=true to overwrite, or action=update / action=clear.' `
					-Hint ('Open goal: "{0}". now={1}. Use replace=true only for a true replan; otherwise update id={1} status=done|blocked.' -f (Get-MBTaskBoardGoal), (Get-MBTaskBoardNowId)))
			}
			if ($doReplace -and (Test-MBTaskBoardHasOpen)) {
				$pc = Get-MBTaskBoardCounts
				$priorSnap = [ordered]@{
					goal     = (Get-MBTaskBoardGoal)
					now      = (Get-MBTaskBoardNowId)
					progress = [string]$pc.progress
					items    = (Get-MBTaskBoardItemsStructured)
				}
			}
		} catch {}

		$list = New-Object System.Collections.ArrayList
		$coerced = $false
		$n = 0
		foreach ($x in $rawItems) {
			$n++
			$iid = ''; $ititle = ''; $istRaw = ''
			if ($x -is [string]) {
				$ititle = $x.Trim()
				$iid = ('t{0}' -f $n)
			} else {
				try { $iid = [string](Get-MBProp $x 'id') } catch {}
				try { if (-not $iid) { $iid = [string](Get-MBProp $x 'Id') } } catch {}
				try { $ititle = [string](Get-MBProp $x 'title') } catch {}
				try { if (-not $ititle) { $ititle = [string](Get-MBProp $x 'Title') } } catch {}
				try { if (-not $ititle) { $ititle = [string](Get-MBProp $x 'text') } } catch {}
				try { if (-not $ititle) { $ititle = [string](Get-MBProp $x 'name') } } catch {}
				try { $istRaw = [string](Get-MBProp $x 'status') } catch {}
				if ([string]::IsNullOrWhiteSpace($ititle)) { $ititle = [string]$x }
				if ([string]::IsNullOrWhiteSpace($iid)) { $iid = ('t{0}' -f $n) }
			}
			# Legal initial state: only index 0 in_progress; everything else pending (coerce)
			$want = if ($n -eq 1) { 'in_progress' } else { 'pending' }
			$got = ConvertTo-MBTaskBoardStatus $istRaw
			if (-not [string]::IsNullOrWhiteSpace($got) -and $got -ne $want) { $coerced = $true }
			[void]$list.Add([ordered]@{
				Id     = $iid.Trim()
				Title  = $ititle.Trim()
				Status = $want
				Note   = ''
			})
		}
		Save-MBTaskBoardItems -List $list -Goal $g
		$null = Step-MBTaskBoardEpoch
		try { $script:MB.TaskBoardPaused = $false } catch {}
		try { $script:MB.PendingTaskBoardNudge = $false } catch {}
		try {
			if ([bool]$script:MB.WireStateFrozen) {
				if (Set-MBFrozenToolsFullCatalog) {
					$script:MB.PendingCacheWarmAfterEnable = $true
					$script:MB.WireFreezeHeldForBoard = $true
				}
			}
		} catch {}
		$firstId = ''
		try { if ($list.Count -gt 0) { $firstId = [string]$list[0].Id } } catch {}
		try { Write-MBTaskBoardInline -Action 'set' -HighlightId $firstId } catch {}
		$extra = [ordered]@{ replaced = $doReplace }
		if ($null -ne $priorSnap) {
			$extra['prior_goal'] = [string]$priorSnap.goal
			$extra['prior_now'] = [string]$priorSnap.now
			$extra['prior_progress'] = [string]$priorSnap.progress
			$extra['prior_items'] = $priorSnap.items
		}
		return (& $buildStatePayload -ActionName 'set' -IncludeBoardText -FocusId $firstId `
			-Coerced:$coerced -Extra $extra)
	}

	if ($act -eq 'update') {
		try { $script:MB.TaskBoardPaused = $false } catch {}
		$work = Get-MBTaskBoardWorkingList
		if ($work.Count -eq 0) {
			return (New-MBTaskBoardErrorJson -Code 'empty_items' `
				-Message 'No TaskBoard items. action=set with goal+items first.' `
				-Hint 'Ordered plan: action=set goal=... items=[step1, step2, ...]')
		}

		# Collect ops: updates[] / ids[] / single id
		$ops = New-Object System.Collections.ArrayList
		if ($null -ne $updates) {
			foreach ($u in @($updates)) {
				if ($null -eq $u) { continue }
				if ($u -is [string]) {
					[void]$ops.Add([ordered]@{ id = $u.Trim(); status = $status; title = $title; note = $note })
				} else {
					$oid = ''; $ost = ''; $oti = ''; $onote = ''
					try { $oid = [string](Get-MBProp $u 'id') } catch {}
					try { if (-not $oid) { $oid = [string](Get-MBProp $u 'Id') } } catch {}
					try { $ost = [string](Get-MBProp $u 'status') } catch {}
					try { $oti = [string](Get-MBProp $u 'title') } catch {}
					try { $onote = [string](Get-MBProp $u 'note') } catch {}
					if ([string]::IsNullOrWhiteSpace($oid)) { continue }
					[void]$ops.Add([ordered]@{ id = $oid.Trim(); status = $ost; title = $oti; note = $onote })
				}
			}
		}
		if ($ops.Count -eq 0 -and $null -ne $ids) {
			$idArr = New-Object System.Collections.ArrayList
			if ($ids -is [string]) {
				foreach ($p in ($ids -split '[,;\s]+')) { if ($p.Trim()) { [void]$idArr.Add($p.Trim()) } }
			} else {
				foreach ($x in @($ids)) { if ($x) { [void]$idArr.Add([string]$x) } }
			}
			foreach ($oid in $idArr) {
				[void]$ops.Add([ordered]@{ id = $oid; status = $status; title = $title; note = $note })
			}
		}
		if ($ops.Count -eq 0) {
			$tid0 = ([string]$id).Trim()
			if ([string]::IsNullOrWhiteSpace($tid0)) {
				return (New-MBTaskBoardErrorJson -Code 'batch_conflict' `
					-Message 'update needs id= or updates=[{id,status},...] or ids=[...].' `
					-Hint 'Prefer: update id=<now> status=done when the current step is finished.')
			}
			[void]$ops.Add([ordered]@{ id = $tid0; status = $status; title = $title; note = $note })
		}

		# Resolve id aliases (now / . / current) then validate (transactional)
		$focusIdx = Get-MBTaskBoardFocusIndex -List $work
		$focusIdLive = ''
		if ($focusIdx -ge 0) { $focusIdLive = [string]$work[$focusIdx].Id }

		foreach ($op in $ops) {
			$tidRaw = [string]$op.id
			$tid = Resolve-MBTaskBoardIdAlias -Id $tidRaw
			$op['id'] = $tid
			$idx = Find-MBTaskBoardIndex -List $work -Id $tid
			if ($idx -lt 0) {
				return (New-MBTaskBoardErrorJson -Code 'unknown_id' `
					-Message ("Unknown item id '{0}'." -f $tidRaw) `
					-Hint 'Use id=now (current focus) or a concrete id from items[] / status.now. Board unchanged.')
			}
			$stIn = [string]$op.status
			if (-not [string]::IsNullOrWhiteSpace($stIn)) {
				$nst = ConvertTo-MBTaskBoardStatus $stIn
				if ([string]::IsNullOrWhiteSpace($nst)) {
					return (New-MBTaskBoardErrorJson -Code 'invalid_status' `
						-Message ("Invalid status '{0}'. Use pending|in_progress|done|blocked." -f $stIn) `
						-Hint 'When current task is finished: status=done (auto-advances). If stuck: status=blocked + note.')
				}
				$prevSt0 = [string]$work[$idx].Status
				# Policy A: no status mutation on items before focus (no rewind/demote)
				if ($focusIdx -ge 0 -and $idx -lt $focusIdx) {
					return (New-MBTaskBoardErrorJson -Code 'immutable_completed' `
						-Message ("Cannot change status of '{0}' — it is before now ({1}). Earlier steps are immutable." -f $tid, $focusIdLive) `
						-Hint 'Only update now (and optional contiguous forward batch). To replan: action=set replace=true.' `
						-Extra ([ordered]@{ attempted_id = $tid; now = $focusIdLive }))
				}
				# Policy A: non-now items may only advance forward as done (contiguous batch from now)
				# Setting pending/blocked/in_progress on a later item is rejected
				if ($focusIdx -ge 0 -and $idx -gt $focusIdx) {
					if ($nst -ne 'done') {
						return (New-MBTaskBoardErrorJson -Code 'sequential_gate' `
							-Message ("Cannot set '{0}' to {1} while now is '{2}'. Only forward done from now is allowed in batch." -f $tid, $nst, $focusIdLive) `
							-Hint ('Update id=now status=done first (or batch contiguous dones from {0}).' -f $focusIdLive) `
							-Extra ([ordered]@{ attempted_id = $tid; attempted_status = $nst; blocked_by = $focusIdLive }))
					}
				}
				# Downgrade of done → pending/in_progress/blocked on any item: reject
				if ($prevSt0 -eq 'done' -and $nst -ne 'done') {
					return (New-MBTaskBoardErrorJson -Code 'immutable_completed' `
						-Message ("Cannot reopen completed item '{0}' (status was done). Use replace=true to replan." -f $tid) `
						-Hint 'Completed steps stay done. Full replan: action=set replace=true goal=... items=[...]')
				}
				# blocked requires a note (reason)
				if ($nst -eq 'blocked') {
					$noteNeed = [string]$op.note
					if ([string]::IsNullOrWhiteSpace($noteNeed)) {
						$prevNote = ''
						try { $prevNote = [string]$work[$idx].Note } catch {}
						if (-not ($prevSt0 -eq 'blocked' -and -not [string]::IsNullOrWhiteSpace($prevNote))) {
							return (New-MBTaskBoardErrorJson -Code 'note_required' `
								-Message ("status=blocked on '{0}' requires note= (short reason)." -f $tid) `
								-Hint 'Example: update id=now status=blocked note=waiting for credentials')
						}
					}
				}
				$op['status'] = $nst
			} else {
				$op['status'] = ''
			}
			$op['_index'] = $idx
		}

		# Apply in plan order (sort by index), not request order
		$sorted = @($ops | Sort-Object { [int]$_._index })

		# Contiguous-from-now check for multi-done batches (no skipping)
		if ($focusIdx -ge 0) {
			$doneTargets = New-Object System.Collections.ArrayList
			foreach ($op in $sorted) {
				if ([string]$op.status -eq 'done') { [void]$doneTargets.Add([int]$op._index) }
			}
			if ($doneTargets.Count -gt 0) {
				$expect = $focusIdx
				$maxDone = -1
				foreach ($di in $doneTargets) {
					if ([int]$di -gt $maxDone) { $maxDone = [int]$di }
				}
				$missing = New-Object System.Collections.ArrayList
				foreach ($di in $doneTargets) {
					if ([int]$di -ne $expect) {
						# Collect missing ids between expect and this target
						for ($mi = $expect; $mi -lt [int]$di; $mi++) {
							try { [void]$missing.Add([string]$work[$mi].Id) } catch {}
						}
						$skipId = ''
						try { $skipId = [string]$work[$expect].Id } catch { $skipId = ('index {0}' -f $expect) }
						return (New-MBTaskBoardErrorJson -Code 'sequential_gate' `
							-Message ("Batch skips '{0}' — only contiguous done from now is allowed." -f $skipId) `
							-Hint 'Include every step from now through the last done id, in order.' `
							-Extra ([ordered]@{ blocked_by = $skipId; missing_ids = $missing }))
					}
					$expect++
				}
			}
		}

		# Clone for transactional apply (ArrayList — not List[object])
		$clone = New-Object System.Collections.ArrayList
		for ($wi = 0; $wi -lt $work.Count; $wi++) {
			$row = $work[$wi]
			if ($null -eq $row) { continue }
			[void]$clone.Add([ordered]@{
				Id = [string]$row.Id; Title = [string]$row.Title
				Status = [string]$row.Status; Note = [string]$row.Note
			})
		}

		$lastId = ''
		$lastStatus = ''
		$lastNoteEcho = ''
		$anyStatusChange = $false

		foreach ($op in $sorted) {
			$idx = [int]$op._index
			$tid = [string]$op.id
			$row = $clone[$idx]
			$prevSt = [string]$row.Status
			$st = [string]$op.status

			if (-not [string]::IsNullOrWhiteSpace($st)) {
				# Sequential gate: item i may become in_progress/done/blocked only if 0..i-1 are done
				if ($st -in @('in_progress', 'done', 'blocked')) {
					if (-not (Test-MBTaskBoardPrefixDone -List $clone -Index $idx)) {
						$blocker = ''
						for ($j = 0; $j -lt $idx; $j++) {
							if ([string]$clone[$j].Status -ne 'done') {
								$blocker = [string]$clone[$j].Id
								break
							}
						}
						return (New-MBTaskBoardErrorJson -Code 'sequential_gate' `
							-Message ("Out-of-order: cannot set {0} to {1} while earlier item {2} is still open. Execute only now." -f $tid, $st, $blocker) `
							-Hint ('Update id={0} (the NOW item) first. Board unchanged (transaction rolled back).' -f (Get-MBTaskBoardNowId)) `
							-Extra ([ordered]@{ attempted_id = $tid; attempted_status = $st; blocked_by = $blocker }))
					}
				}
				# Setting a later item to pending when it is already pending is fine;
				# setting focus backward to pending parks it (allowed) but suffix stays pending.
				# Reject done on non-prefix-ready already handled.
				# Reject marking suffix done while head open: covered by prefix check.

				# Leaving blocked: clear stale note unless new note provided
				$opNote = [string]$op.note
				if ($prevSt -eq 'blocked' -and $st -ne 'blocked') {
					if ([string]::IsNullOrWhiteSpace($opNote)) { $row.Note = '' }
				}
				$row.Status = $st
				$anyStatusChange = $true
				$lastStatus = $st
			}

			$oti = [string]$op.title
			if (-not [string]::IsNullOrWhiteSpace($oti)) {
				# Title rename only allowed on the focus (now) item
				if ($focusIdx -ge 0 -and $idx -ne $focusIdx) {
					return (New-MBTaskBoardErrorJson -Code 'immutable_completed' `
						-Message ("Cannot rename '{0}' while now is '{1}'. Title edits only on now." -f $tid, $focusIdLive) `
						-Hint 'Update id=now title=... or finish/replan first.')
				}
				$row.Title = $oti.Trim()
			}
			$onote = [string]$op.note
			if (-not [string]::IsNullOrWhiteSpace($onote)) {
				# Notes allowed on now only (blocked reason / progress note)
				if ($focusIdx -ge 0 -and $idx -ne $focusIdx -and [string]::IsNullOrWhiteSpace($st)) {
					return (New-MBTaskBoardErrorJson -Code 'immutable_completed' `
						-Message ("Cannot set note on '{0}' while now is '{1}'. Notes only on now." -f $tid, $focusIdLive) `
						-Hint 'Update id=now note=...')
				}
				$row.Note = $onote.Trim()
				$lastNoteEcho = $onote.Trim()
			}
			$lastId = $tid
			$clone[$idx] = $row
		}

		# After batch: auto-advance (done chain -> next pending in_progress; blocked stays focus)
		if ($anyStatusChange) {
			$null = Invoke-MBTaskBoardAutoAdvance -List $clone
		}

		# Final invariants (all-or-nothing)
		$inv = Test-MBTaskBoardSequentialInvariants -List $clone
		# All-done is ok (complete path)
		$allDone = $true
		foreach ($r in $clone) {
			if ([string]$r.Status -ne 'done') { $allDone = $false; break }
		}
		if (-not $inv.ok -and -not $allDone) {
			return (New-MBTaskBoardErrorJson -Code $inv.code `
				-Message $inv.message `
				-Hint 'Batch rejected. Prefer single-step: update id=<now> status=done. Board unchanged.')
		}

		# Commit
		$goalKeep = ''
		try { $goalKeep = [string](Get-MBTaskBoardObject).Goal } catch {}
		Save-MBTaskBoardItems -List $clone -Goal $goalKeep

		$hi = Get-MBTaskBoardNowId
		if ([string]::IsNullOrWhiteSpace($lastNoteEcho) -and $lastId) {
			foreach ($r in $clone) {
				if ([string]::Equals([string]$r.Id, $lastId, [StringComparison]::OrdinalIgnoreCase)) {
					if ($r.Note) { $lastNoteEcho = [string]$r.Note }
					break
				}
			}
		}
		if ([string]::IsNullOrWhiteSpace($lastStatus) -and $lastId) {
			foreach ($r in $clone) {
				if ([string]::Equals([string]$r.Id, $lastId, [StringComparison]::OrdinalIgnoreCase)) {
					$lastStatus = [string]$r.Status
					break
				}
			}
		}

		$boardComplete = $false
		$stillOpen = [bool](Test-MBTaskBoardHasOpen)
		if (-not $stillOpen -and $clone.Count -gt 0) {
			try {
				$boardComplete = [bool](Complete-MBTaskBoard -Reason 'all-done-on-update')
			} catch { $boardComplete = $false }
			$hi = ''
		}

		try { if ($script:MB.Wpf) { $script:MB.Wpf.TaskBoardLastFp = '' } } catch {}
		try { Write-MBTaskBoardInline -Action 'update' -HighlightId $hi } catch {}

		# Bump epoch so next id=now status=done is a distinct fingerprint for loop-guard
		$null = Step-MBTaskBoardEpoch

		$extra = [ordered]@{ status = $lastStatus }
		if ($ops.Count -gt 1) {
			$idList = New-Object System.Collections.ArrayList
			foreach ($sop in $sorted) {
				if ($sop -and $sop.id) { [void]$idList.Add([string]$sop.id) }
			}
			$extra['updated'] = $idList
		}
		return (& $buildStatePayload -ActionName 'update' -FocusId $lastId -Complete:$boardComplete `
			-ItemNote $lastNoteEcho -Extra $extra)
	}

	return (New-MBTaskBoardErrorJson -Code 'invalid_status' `
		-Message 'TaskBoard action must be set|update|status|clear.' `
		-Hint 'Ordered plan: set items, then update id=now status=done as you finish each step.')
}


function Build-MBStickySystemContentLive {
	$lines = New-Object System.Collections.ArrayList
	[void]$lines.Add("Machine: $env:COMPUTERNAME  User: $env:USERNAME")
	[void]$lines.Add("CWD: $($script:MB.WorkingDir)")
	[void]$lines.Add("AutoApprove: $($script:MB.AutoApprove)")

	$tbText = ''
	try { $tbText = Format-MBTaskBoardText } catch { $tbText = '' }
	if (-not [string]::IsNullOrWhiteSpace($tbText)) {
		[void]$lines.Add($tbText)
	}

	try {
		if ($script:MB.PinnedPaths -and $script:MB.PinnedPaths.Count -gt 0) {
			[void]$lines.Add('Pinned files (session):')
			$pins = @($script:MB.PinnedPaths.GetEnumerator() | Sort-Object { $_.Value.last } -Descending | Select-Object -First 12)
			foreach ($pe in $pins) {
				$pv = $pe.Value
				$acts = @($pv.actions) -join ','
				[void]$lines.Add((' - [{0}] {1}' -f $acts, $pv.path))
			}
		}
	} catch {}

	try {
		if ($script:MB.ToolErrorsByPath -and $script:MB.ToolErrorsByPath.Count -gt 0) {
			[void]$lines.Add('Open file errors (last):')
			$errs = @($script:MB.ToolErrorsByPath.GetEnumerator() | Sort-Object { $_.Value.at } -Descending | Select-Object -First 8)
			foreach ($ee in $errs) {
				[void]$lines.Add((' - {0}: {1}' -f $ee.Value.path, $ee.Value.error))
			}
		}
	} catch {}

	$findings = @($script:MB.StickyFindings)
	if ($findings.Count -gt 0) {
		[void]$lines.Add("Findings:")
		foreach ($f in $findings) { [void]$lines.Add(" - $f") }
	} else {
		[void]$lines.Add("Findings: (none pinned)")
	}

	$notes = @($script:MB.StickyNotes)
	if ($notes.Count -gt 0) {
		[void]$lines.Add("Notes:")
		foreach ($n in $notes) { [void]$lines.Add(" - $n") }
	}

	if ($script:MB.StickyExtra) {
		[void]$lines.Add("Session summary:")
		[void]$lines.Add([string]$script:MB.StickyExtra)
	}

	return ($lines -join "`n")
}

function Get-MBStickySystemContent {
	return (Build-MBStickySystemContentLive)
}

function Get-MBStickyVersionFromContent {
	param([string]$Content)
	if ([string]::IsNullOrWhiteSpace($Content)) { return 0 }
	$first = ''
	try { $first = ([string]($Content -split "`r?`n", 2)[0]) } catch { $first = $Content }
	if ($first -match '(?i)\[SESSION STATE[^\n]*?\bv=(\d+)') {
		try { return [int]$Matches[1] } catch { return 0 }
	}
	if ($Content -match '(?im)\[SESSION STATE[^\n]*?\bv=(\d+)') {
		try { return [int]$Matches[1] } catch { return 0 }
	}
	if ($Content.StartsWith($script:MB_STATE_MARKER)) { return 1 }
	return 0
}

function Get-MBStickyActiveVersionFromContent {
	param([string]$Content)
	if ([string]::IsNullOrWhiteSpace($Content)) { return 0 }
	if ($Content -match '(?im)\bactive_v=(\d+)') {
		try { return [int]$Matches[1] } catch { return 0 }
	}
	$ledger = @(Get-MBStickyLedgerIndexFromContent -Content $Content)
	if ($ledger.Count -gt 0) {
		$max = 0
		foreach ($n in $ledger) { if ([int]$n -gt $max) { $max = [int]$n } }
		return $max
	}
	return (Get-MBStickyVersionFromContent -Content $Content)
}

function Get-MBStickyLedgerIndexFromContent {
	param([string]$Content)
	$out = New-Object System.Collections.ArrayList
	if ([string]::IsNullOrWhiteSpace($Content)) { return @() }
	$raw = ''
	if ($Content -match '(?im)\bactive_ledger\s*=\s*\[([^\]]*)\]') {
		$raw = [string]$Matches[1]
	} elseif ($Content -match '(?im)\bactive_ledger\s*=\s*([0-9,\s]+)') {
		$raw = [string]$Matches[1]
	} elseif ($Content -match '(?im)\bactive_ledger\s*=\s*max_v\b') {
		$v = Get-MBStickyVersionFromContent -Content $Content
		if ($v -gt 0) { [void]$out.Add($v) }
		return @($out.ToArray())
	}
	if (-not [string]::IsNullOrWhiteSpace($raw)) {
		foreach ($p in ($raw -split '[,;\s]+')) {
			if ($p -match '^\d+$') {
				$n = [int]$p
				if ($n -gt 0 -and -not ($out -contains $n)) { [void]$out.Add($n) }
			}
		}
	}
	return @($out.ToArray())
}

function Get-MBStickyLedgerBodyFromContent {
	param([string]$Content)
	if ([string]::IsNullOrWhiteSpace($Content)) { return '' }
	$lines = @($Content -split "`r?`n")
	$out = New-Object System.Collections.ArrayList
	foreach ($ln in $lines) {
		if ($ln -match '(?i)^\[SESSION STATE') { continue }
		if ($ln -match '(?i)^Trust only the SESSION STATE') { continue }
		if ($ln -match '(?i)^Trust only active_v') { continue }
		if ($ln -match '(?i)^active_ledger\s*=') { continue }
		if ($ln -match '(?i)^active_v\s*=') { continue }
		if ($ln -match '(?i)^valid_stickies\s*=') { continue }
		if ($ln -match '(?i)^Older v= blocks') { continue }
		[void]$out.Add($ln)
	}
	return (($out -join "`n").Trim())
}

function New-MBStickyLedgerMessage {
	param(
		[int]$Version,
		[string]$Body,
		[int[]]$ValidVersions = $null
	)
	if ($Version -lt 1) { $Version = 1 }
	$body = ([string]$Body).Trim()
	$valid = New-Object System.Collections.ArrayList
	if ($null -ne $ValidVersions) {
		foreach ($n in @($ValidVersions)) {
			try {
				$i = [int]$n
				if ($i -gt 0 -and -not ($valid -contains $i)) { [void]$valid.Add($i) }
			} catch {}
		}
	}
	if ($valid.Count -eq 0) { [void]$valid.Add($Version) }
	elseif (-not ($valid -contains $Version)) { [void]$valid.Add($Version) }
	$sorted = @($valid | Sort-Object)
	$ledgerCsv = ($sorted -join ',')
	$hdr = '{0} v={1} active_v={1} active_ledger=[{2}]]' -f $script:MB_STATE_MARKER, $Version, $ledgerCsv
	$trust = ('Trust only active_v={0} (listed in active_ledger=[{1}]). Older SESSION STATE blocks not in active_ledger are historical — ignore them for board/goals/cwd.' -f $Version, $ledgerCsv)
	return @{
		role    = 'system'
		content = ($hdr + "`n" + $trust + "`n" + $body)
	}
}

function Freeze-MBWireState {
	param([switch]$Refresh)
	try {
		$need = $Refresh -or -not [bool]$script:MB.WireStateFrozen
		if ([bool]$script:MB.WireStateFrozen -and [bool]$script:MB.WireFreezeHeldForBoard -and -not $Refresh) {
			$need = $false
		}
		if (-not $need) {
			if ([string]::IsNullOrEmpty([string]$script:MB.FrozenStickyContent)) { $need = $true }
			if ([string]::IsNullOrEmpty([string]$script:MB.FrozenBaseContent)) { $need = $true }
			try {
				if ($null -eq $script:MB.FrozenTools -or @($script:MB.FrozenTools).Count -eq 0) { $need = $true }
			} catch { $need = $true }
			if ($Refresh -and [bool]$script:MB.WireFreezeHeldForBoard) {
				try {
					if (Test-MBShouldHoldWireFreeze) { $need = $false }
				} catch {}
			}
		}
		if ($need) {
			$script:MB.WireStateFrozen = $false
			$script:MB.FrozenBaseContent = Build-MBSystemPromptLive
			$script:MB.FrozenStickyContent = ''
			$boardOpen = $false
			try { $boardOpen = [bool](Test-MBTaskBoardHasOpen) } catch { $boardOpen = $false }
			if ($boardOpen) {
				$script:MB.FrozenTools = @(Get-MBWireStableTools)
				$script:MB.FrozenToolsIsFullCatalog = $true
				$script:MB.WireFreezeHeldForBoard = $true
			} else {
				$script:MB.FrozenTools = @(Get-MBActiveToolsLive)
				$script:MB.FrozenToolsIsFullCatalog = $false
				$script:MB.WireFreezeHeldForBoard = $false
			}
			$script:MB.WireStateFrozen = $true
			try {
				Initialize-MBToolsOverhead
				$script:MB.FrozenToolsOverheadTok = [int]$script:MB.ToolsOverheadTok
				$script:MB.FrozenToolsOverheadChars = [int]$script:MB.ToolsOverheadChars
			} catch {}
		} else {
			$script:MB.WireStateFrozen = $true
			try {
				if (Test-MBShouldHoldWireFreeze) { $script:MB.WireFreezeHeldForBoard = $true }
			} catch {}
			try {
				if ([int]$script:MB.FrozenToolsOverheadTok -gt 0) {
					$script:MB.ToolsOverheadTok = [int]$script:MB.FrozenToolsOverheadTok
					$script:MB.ToolsOverheadChars = [int]$script:MB.FrozenToolsOverheadChars
				}
			} catch {}
		}
	} catch {
		try { $script:MB.WireStateFrozen = $false } catch {}
	}
}

function Thaw-MBWireState {
	param(
		# Force=true always thaws (board complete, /clear, hard compact). Default respects board hold.
		[switch]$Force
	)
	if (-not $Force) {
		try {
			if (Test-MBShouldHoldWireFreeze) {
				$script:MB.WireFreezeHeldForBoard = $true
				$script:MB.WireStateFrozen = $true
				return
			}
		} catch {}
	}
	try { $script:MB.WireStateFrozen = $false } catch {}
	try { $script:MB.WireFreezeHeldForBoard = $false } catch {}
	try { $script:MB.FrozenStickyContent = '' } catch {}
	try { $script:MB.FrozenBaseContent = '' } catch {}
	try { $script:MB.FrozenTools = $null } catch {}
	try { $script:MB.FrozenToolsIsFullCatalog = $false } catch {}
	try { $script:MB.FrozenToolsOverheadTok = 0 } catch {}
	try { $script:MB.FrozenToolsOverheadChars = 0 } catch {}
	try { $script:MB.PendingCacheWarmAfterEnable = $false } catch {}
	try { $script:MB.PendingStickyLedgerSync = $false } catch {}
	try {
		if ([bool]$script:MB.PendingToolGroupPromptSync) {
			try { $script:SystemPrompt = (Build-MBSystemPromptLive) } catch {}
			try { Initialize-MBToolsOverhead } catch {}
		}
	} catch {}
}

function Test-MBIsStateMessage {
	param($Message)
	$c = Get-MBProp $Message 'content'
	$r = Get-MBProp $Message 'role'
	if ($r -ne 'system') { return $false }
	if ($null -eq $c) { return $false }
	return ([string]$c).StartsWith($script:MB_STATE_MARKER)
}

function Test-MBIsBaseSystemMessage {
	param($Message)
	$r = Get-MBProp $Message 'role'
	if ($r -ne 'system') { return $false }
	if (Test-MBIsStateMessage $Message) { return $false }
	$c = [string](Get-MBProp $Message 'content')
	# Main system prompt starts with agent identity
	return $c.StartsWith("You are $AgentName") -or $c.StartsWith("You are ")
}

function Sync-MBSystemMessages {
	param([array]$Messages)

	$baseContent = Get-MBSystemPrompt
	$liveBody = Get-MBStickyLedgerBodyFromContent (Get-MBStickySystemContent)

	$prevBase = $null
	$rest = New-Object System.Collections.ArrayList
	$byVer = @{}
	$maxV = 0
	$lastStickyContent = ''
	$lastStickyV = 0
	foreach ($m in @($Messages)) {
		if ($null -eq $m) { continue }
		if (Test-MBIsBaseSystemMessage $m) {
			$prevBase = $m
			continue
		}
		$c = [string](Get-MBProp $m 'content')
		$r = Get-MBProp $m 'role'
		if ($r -eq 'system' -and $c.StartsWith('[Context compacted:')) { continue }
		if (Test-MBIsTurnHygieneMessage $m) { continue }
		if (Test-MBIsStateMessage $m) {
			$v = Get-MBStickyVersionFromContent -Content $c
			if ($v -le 0) { $v = 1 }
			$byVer[$v] = Get-MBStickyLedgerBodyFromContent -Content $c
			if ($v -gt $maxV) { $maxV = $v }
			$lastStickyContent = $c
			$lastStickyV = $v
			[void]$rest.Add($m)
			continue
		}
		[void]$rest.Add($m)
	}

	$validSet = New-Object System.Collections.ArrayList
	$activeV = 0
	if (-not [string]::IsNullOrWhiteSpace($lastStickyContent)) {
		foreach ($n in @(Get-MBStickyLedgerIndexFromContent -Content $lastStickyContent)) {
			if ([int]$n -gt 0 -and -not ($validSet -contains [int]$n)) { [void]$validSet.Add([int]$n) }
		}
		$activeV = Get-MBStickyActiveVersionFromContent -Content $lastStickyContent
	}
	if ($validSet.Count -eq 0 -and $maxV -gt 0) {
		for ($i = 1; $i -le $maxV; $i++) { [void]$validSet.Add($i) }
		$activeV = $maxV
	}
	if ($activeV -le 0) { $activeV = $maxV }
	if ($activeV -le 0 -and $lastStickyV -gt 0) { $activeV = $lastStickyV }

	$lastBody = ''
	if ($activeV -gt 0 -and $byVer.ContainsKey($activeV)) {
		$lastBody = [string]$byVer[$activeV]
	} elseif ($maxV -gt 0 -and $byVer.ContainsKey($maxV)) {
		$lastBody = [string]$byVer[$maxV]
	}

	if ($prevBase -and ([string](Get-MBProp $prevBase 'content') -eq $baseContent)) {
		$baseSystem = $prevBase
	} else {
		$baseSystem = @{ role = 'system'; content = $baseContent }
	}

	$out = New-Object System.Collections.ArrayList
	[void]$out.Add($baseSystem)
	foreach ($m in $rest) { [void]$out.Add($m) }

	$needSticky = $false
	if ($maxV -le 0) {
		$needSticky = $true
	} elseif (-not [string]::Equals(([string]$lastBody).Trim(), ([string]$liveBody).Trim(), [StringComparison]::Ordinal)) {
		$needSticky = $true
	}
	try {
		if ([bool]$script:MB.PendingStickyLedgerSync) { $needSticky = $true }
	} catch {}
	if ($needSticky) {
		$nextV = 1
		if ($maxV -gt 0) { $nextV = $maxV + 1 }
		[void]$out.Add((New-MBStickyLedgerMessage -Version $nextV -Body $liveBody -ValidVersions @($nextV)))
		try { $script:MB.PendingStickyLedgerSync = $false } catch {}
	}

	return $out.ToArray()
}

function Add-MBStickyNote {
	param([string]$Text, [ValidateSet('note','finding')]$Kind = 'note')
	$Text = ($Text -replace '\s+', ' ').Trim()
	if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
	if ($Text.Length -gt 400) { $Text = $Text.Substring(0, 397) + '...' }

	$list = if ($Kind -eq 'finding') { $script:MB.StickyFindings } else { $script:MB.StickyNotes }
	foreach ($x in @($list)) {
		if ([string]$x -eq $Text) { return $false }
	}
	[void]$list.Add($Text)
	while ($list.Count -gt 12) { $list.RemoveAt(0) }
	return $true
}

function Clear-MBSticky {
	$script:MB.StickyNotes.Clear()
	$script:MB.StickyFindings.Clear()
	$script:MB.StickyExtra = ''
	try {
		$script:MB.TaskBoard = [ordered]@{ Goal = ''; Items = (New-Object System.Collections.ArrayList); Updated = '' }
	} catch {}
	try { $script:MB.TaskBoardPaused = $false } catch {}
	try { $script:MB.PinnedPaths = [ordered]@{} } catch {}
	try { $script:MB.ToolErrorsByPath = @{} } catch {}
	try { $script:MB.RecentFileReads = @{} } catch {}
	try { $script:MB.PendingTaskBoardNudge = $false } catch {}
	try { $script:MB.LastTurnHygiene = '' } catch {}
	try { Thaw-MBWireState -Force } catch {}
	try { Update-MBWpfTaskBoardSticky -Action 'clear' } catch {}
}

function Get-MBToolResultDigest {
	# Compact old tool payloads while preserving outcome + paths/errors.
	param(
		[string]$Content,
		[int]$MaxChars = 400
	)
	$s = [string]$Content
	if ([string]::IsNullOrEmpty($s)) { return '' }
	$status = 'ok'
	if ($s -match '(?i)BLOCKED BY USER') { $status = 'blocked' }
	elseif ($s -match '(?i)NEED_INPUT') { $status = 'need_input' }
	elseif ($s -match '(?i)LOOP GUARD') { $status = 'loop_guard' }
	elseif ($s -match '(?i)^ERROR:|TOOLS_DONE=1') { $status = 'error' }
	elseif ($s -match '(?i)^SUCCESS') { $status = 'success' }

	$pathHint = ''
	if ($s -match '(?i)(?:File|Path|path|CREATE|UPDATE|Written)\s*[:=]?\s*([A-Za-z]:\\[^\s\r\n"'']+)') {
		$pathHint = $Matches[1]
	} elseif ($s -match '(?i)"path"\s*:\s*"([^"]+)"') {
		$pathHint = $Matches[1]
	}

	$head = ($s -replace '\s+', ' ').Trim()
	if ($head.Length -gt 220) { $head = $head.Substring(0, 217) + '...' }
	$dig = "[tool digest status=$status"
	if ($pathHint) { $dig += " path=$pathHint" }
	$dig += "] $head"
	if ($dig.Length -gt $MaxChars) { $dig = $dig.Substring(0, $MaxChars - 3) + '...' }
	return $dig
}

function Shrink-MBToolPayloads {
	param(
		[array]$Messages,
		[int]$RecentKeep = 6,
		[int]$OldMaxChars = 2500,
		[int]$RecentMaxChars = 12000
	)
	# Protect last ERROR tool message per path (never shrink away the final failure)
	$protectedIds = @{}
	try {
		$lastErrByPath = @{}
		$idx = 0
		foreach ($m in @($Messages)) {
			$idx++
			$role = Get-MBProp $m 'role'
			if ($role -ne 'tool') { continue }
			$c = [string](Get-MBProp $m 'content')
			if ($c -notmatch '(?i)^ERROR:|BLOCKED BY USER|NEED_INPUT') { continue }
			$path = $null
			if ($c -match '(?i)([A-Za-z]:\\[^\s\r\n"'']+)') { $path = $Matches[1].ToLowerInvariant() }
			elseif ($c -match '(?i)"path"\s*:\s*"([^"]+)"') { $path = $Matches[1].ToLowerInvariant() }
			if (-not $path) { $path = '__nopath__' }
			$tcid = [string](Get-MBProp $m 'tool_call_id')
			if (-not $tcid) { $tcid = "idx_$idx" }
			$lastErrByPath[$path] = $tcid
		}
		foreach ($k in @($lastErrByPath.Keys)) { $protectedIds[$lastErrByPath[$k]] = $true }
	} catch {}

	$out = New-Object System.Collections.ArrayList
	$total = @($Messages).Count
	$i = 0
	foreach ($m in @($Messages)) {
		$i++
		$role = Get-MBProp $m 'role'
		$content = Get-MBProp $m 'content'
		$isRecent = ($i -gt ($total - $RecentKeep))
		if ($role -eq 'tool' -and $content) {
			$s = [string]$content
			$tcid = [string](Get-MBProp $m 'tool_call_id')
			$isProtected = $false
			if ($tcid -and $protectedIds.ContainsKey($tcid)) { $isProtected = $true }
			$cap = if ($isRecent) { $RecentMaxChars } else { $OldMaxChars }
			if ($isProtected) {
				# Keep more of last path error
				$cap = [math]::Max($cap, [math]::Min(6000, $RecentMaxChars))
			}
			if ($s.Length -gt $cap) {
				if ($isRecent -or $isProtected) {
					$body = Limit-MBResult $s $cap
				} else {
					# Older tools: structured digest, not arbitrary truncate mid-JSON
					$body = Get-MBToolResultDigest -Content $s -MaxChars ([math]::Min(500, $OldMaxChars))
				}
				[void]$out.Add(@{
					role         = 'tool'
					tool_call_id = $tcid
					content      = $body
				})
				continue
			}
		}
		[void]$out.Add($m)
	}
	return $out.ToArray()
}

function Build-MBStructuredCompactDigest {
	# Goals / files / errors / CWD / board — for StickyExtra and model digest material.
	param(
		[array]$DroppedMessages,
		[string]$ExtractiveFallback = ''
	)
	$bits = New-Object System.Collections.ArrayList
	[void]$bits.Add(('CWD: {0}' -f $script:MB.WorkingDir))

	$tb = ''
	try { $tb = Format-MBTaskBoardText } catch {}
	if ($tb) {
		[void]$bits.Add('Task board:')
		foreach ($ln in ($tb -split "`n" | Select-Object -First 10)) { [void]$bits.Add("  $ln") }
	}

	try {
		if ($script:MB.PinnedPaths -and $script:MB.PinnedPaths.Count -gt 0) {
			[void]$bits.Add('Files touched:')
			foreach ($pe in @($script:MB.PinnedPaths.GetEnumerator() | Sort-Object { $_.Value.last } -Descending | Select-Object -First 10)) {
				$actStr = (@($pe.Value.actions) -join ',')
				[void]$bits.Add(('  [{0}] {1}' -f $actStr, $pe.Value.path))
			}
		}
	} catch {}

	try {
		if ($script:MB.ToolErrorsByPath -and $script:MB.ToolErrorsByPath.Count -gt 0) {
			[void]$bits.Add('Open errors:')
			foreach ($ee in @($script:MB.ToolErrorsByPath.GetEnumerator() | Sort-Object { $_.Value.at } -Descending | Select-Object -First 6)) {
				[void]$bits.Add(('  {0}: {1}' -f $ee.Value.path, $ee.Value.error))
			}
		}
	} catch {}

	$users = New-Object System.Collections.ArrayList
	$tools = New-Object System.Collections.ArrayList
	foreach ($m in @($DroppedMessages)) {
		$r = Get-MBProp $m 'role'
		$c = [string](Get-MBProp $m 'content')
		if ($r -eq 'user' -and $c) {
			$line = ($c -replace '\s+', ' ').Trim()
			if ($line.Length -gt 140) { $line = $line.Substring(0, 137) + '...' }
			[void]$users.Add($line)
		} elseif ($r -eq 'assistant') {
			$tcs = Get-MBProp $m 'tool_calls'
			if ($tcs) {
				try {
					foreach ($tc in @($tcs)) {
						$tn = Get-MBProp (Get-MBProp $tc 'function') 'name'
						if ($tn) { [void]$tools.Add([string]$tn) }
					}
				} catch {}
			}
		}
	}
	if ($users.Count -gt 0) {
		[void]$bits.Add('Goals / user asks (dropped window):')
		foreach ($u in ($users | Select-Object -First 5)) { [void]$bits.Add("  - $u") }
	}
	if ($tools.Count -gt 0) {
		$uniq = @($tools | Select-Object -Unique | Select-Object -First 12)
		[void]$bits.Add(('Tools used: {0}' -f ($uniq -join ', ')))
	}
	if ($ExtractiveFallback) {
		[void]$bits.Add('Highlights:')
		[void]$bits.Add($ExtractiveFallback)
	}
	$out = $bits -join "`n"
	if ($out.Length -gt 1400) { $out = $out.Substring(0, 1397) + '...' }
	return $out
}

function Enter-MBCompacting {
	try {
		$script:MB.CompactingDepth = [int]$script:MB.CompactingDepth + 1
		$script:MB.IsCompacting = $true
		if (Test-MBWpfActive) {
			Update-MBWpfSticky -Status 'auto-compacting'
		}
	} catch {}
}

function Exit-MBCompacting {
	try {
		$d = [int]$script:MB.CompactingDepth - 1
		if ($d -lt 0) { $d = 0 }
		$script:MB.CompactingDepth = $d
		if ($d -le 0) {
			$script:MB.IsCompacting = $false
			if (Test-MBWpfActive) {
				$st = if ($script:MB.IsThinking) { 'thinking...' } elseif ($script:MB.IsWorking) { 'working' } else { 'ready' }
				Update-MBWpfSticky -Status $st
				try { Update-MBWpfLiveChrome -Force } catch {}
			}
		}
	} catch {}
}

function Compact-MBHistory {
	param(
		[array]$Messages,
		[int]$KeepLast = 24,
		[switch]$Aggressive,
		[switch]$PreferModelDigest
	)
	try { Sync-MBAutoCompactFromWpf } catch {}

	# Compact: keep system/state; drop middle turns
	$Messages = @(Sync-MBSystemMessages -Messages $Messages)

	if ($Aggressive) { $KeepLast = [math]::Min($KeepLast, 12) }

	$head = New-Object System.Collections.ArrayList
	$rest = New-Object System.Collections.ArrayList
	foreach ($m in @($Messages)) {
		$r = Get-MBProp $m 'role'
		if ($r -eq 'system' -and ($head.Count -lt 2)) {
			[void]$head.Add($m)
		} else {
			[void]$rest.Add($m)
		}
	}

	if ($rest.Count -le $KeepLast) {
		$shrunk = @(Shrink-MBToolPayloads -Messages (@($head) + @($rest)) -RecentKeep 8 -OldMaxChars 2000)
		try { $shrunk = @(Repair-MBToolMessageSequence -Messages $shrunk) } catch {}
		return $shrunk
	}

	Enter-MBCompacting
	try {
	$keepStart = Get-MBSafeHistoryKeepStart -Rest @($rest) -KeepLast $KeepLast
	$dropped = $keepStart
	$kept = @()
	if ($keepStart -lt $rest.Count) {
		$kept = @($rest[$keepStart..($rest.Count - 1)])
	}

	$summaryBits = New-Object System.Collections.ArrayList
	$materialBits = New-Object System.Collections.ArrayList
	$droppedArr = @($rest | Select-Object -First $dropped)
	foreach ($m in $droppedArr) {
		$r = Get-MBProp $m 'role'
		$c = [string](Get-MBProp $m 'content')
		if (-not $c) {
			$tcs = Get-MBProp $m 'tool_calls'
			if ($tcs) {
				try {
					$names = @($tcs | ForEach-Object { (Get-MBProp (Get-MBProp $_ 'function') 'name') }) -join ','
					$c = "[tools: $names]"
				} catch { $c = '' }
			}
		}
		if ($r -eq 'user' -and $c) {
			$line = $c -replace '\s+', ' '
			$full = $line
			if ($line.Length -gt 160) { $line = $line.Substring(0, 157) + '...' }
			[void]$summaryBits.Add("User: $line")
			if ($full.Length -gt 400) { $full = $full.Substring(0, 397) + '...' }
			[void]$materialBits.Add("User: $full")
		} elseif ($r -eq 'assistant' -and $c) {
			$line = $c -replace '\s+', ' '
			$full = $line
			if ($line.Length -gt 160) { $line = $line.Substring(0, 157) + '...' }
			if ($line.Trim().Length -gt 0) { [void]$summaryBits.Add("Agent: $line") }
			if ($full.Trim().Length -gt 0) {
				if ($full.Length -gt 400) { $full = $full.Substring(0, 397) + '...' }
				[void]$materialBits.Add("Agent: $full")
			}
		} elseif ($r -eq 'tool' -and $c) {
			$line = Get-MBToolResultDigest -Content $c -MaxChars 220
			[void]$materialBits.Add("Tool: $line")
		}
		if ($summaryBits.Count -ge 10) { break }
	}
	$extractive = if ($summaryBits.Count -gt 0) { ($summaryBits -join ' | ') } else { '(tool-heavy stretch)' }
	if ($extractive.Length -gt 900) { $extractive = $extractive.Substring(0, 897) + '...' }

	# Structured digest always (CWD / board / pins / errors / goals)
	$structured = Build-MBStructuredCompactDigest -DroppedMessages $droppedArr -ExtractiveFallback $extractive

	$digest = $structured
	$digestSource = 'structured'
	$canModel = $script:MB.ModelCompact -and $PreferModelDigest -and $materialBits.Count -gt 0 -and ([int]$script:MB.ApiFailures -lt 2)
	if ($canModel) {
		try {
			$material = "STRUCTURED STATE:`n$structured`n`nEXCERPT:`n" + ($materialBits -join "`n")
			$modelDigest = Invoke-MBModelSummary -Material $material -MaxTok 450
			if ($modelDigest -and $modelDigest.Trim().Length -gt 40) {
				$digest = $modelDigest.Trim()
				$digestSource = 'model+structured'
				if ($digest.Length -gt 1100) { $digest = $digest.Substring(0, 1097) + '...' }
			}
		} catch {
			$digest = $structured
			$digestSource = 'structured'
		}
	}

	$script:MB.StickyExtra = "Earlier conversation compressed ($dropped msgs, $digestSource):`n$digest"
	if ($script:MB.StickyExtra.Length -gt 1600) {
		$script:MB.StickyExtra = $script:MB.StickyExtra.Substring(0, 1597) + '...'
	}

	$notice = @{
		role    = 'system'
		content = "[Context compacted: dropped $dropped earlier messages ($digestSource digest). SESSION STATE holds goals/files/errors/board. CWD=$($script:MB.WorkingDir)]"
	}

	# Body only — Sync-MBSystemMessages reuses the base system object when unchanged (prompt-cache friendly).
	# Sticky/state content changes after StickyExtra update (expected cache break at state, not whole history).
	# Note: Sync strips old "[Context compacted:…]" systems; re-inject notice after base+state.
	$out = New-Object System.Collections.ArrayList
	foreach ($m in $kept) {
		if (Test-MBIsStateMessage $m) { continue }
		if (Test-MBIsBaseSystemMessage $m) { continue }
		[void]$out.Add($m)
	}

	$script:MB.CompactionCount++
	$script:MB.LastCompactReason = ("dropped {0} msgs, keep last {1} ({2})" -f $dropped, $KeepLast, $digestSource)

	$synced = @(Sync-MBSystemMessages -Messages $out.ToArray())
	$final = New-Object System.Collections.ArrayList
	$sysN = 0
	foreach ($m in $synced) {
		[void]$final.Add($m)
		$r = Get-MBProp $m 'role'
		if ($r -eq 'system') {
			$sysN++
			if ($sysN -eq 2) { [void]$final.Add($notice) }
		}
	}
	if ($sysN -lt 2) { [void]$final.Add($notice) }
	$finalArr = @(Shrink-MBToolPayloads -Messages $final.ToArray() -RecentKeep 6 -OldMaxChars 1800 -RecentMaxChars 8000)
	try { $finalArr = @(Repair-MBToolMessageSequence -Messages $finalArr) } catch {}
	return $finalArr
	} finally {
		Exit-MBCompacting
	}
}

function Optimize-MBHistory {
	param([array]$Messages)
	$Messages = @(Sync-MBSystemMessages -Messages $Messages)

	if ($Messages.Count -gt $MaxHistoryMessages) {
		return Compact-MBHistory -Messages $Messages -KeepLast ([math]::Floor($MaxHistoryMessages * 0.55))
	}

	return @(Shrink-MBToolPayloads -Messages $Messages -RecentKeep 8 -OldMaxChars 4000 -RecentMaxChars $MaxToolResultChars)
}

function Ensure-MBPromptBudget {
	param(
		[array]$Messages,
		[double]$TargetPct = 0.72,
		[int]$MaxPasses = 6,
		[switch]$Verbose
	)

	$Messages = @(Sync-MBSystemMessages -Messages $Messages)
	$budget = Get-MBEffectivePromptBudget
	$targetTok = [math]::Floor($budget * $TargetPct)
	$beforeTok = (Get-MBContextEstimate -Messages $Messages).PromptTokens
	$useModelDigest = $false
	try { $useModelDigest = [bool]$script:MB.ModelCompact } catch { $useModelDigest = $false }

	# Under wire freeze, skip soft shrink (preserves prompt-cache prefix).
	# EnableToolGroup mid-loop inflates ToolsOverheadTok; that must NOT rewrite history
	# (would invalidate cache during TaskBoard / multi-step). Only emergency overflow trims.
	try {
		if ([bool]$script:MB.WireStateFrozen) {
			$emerg = [math]::Floor($budget * 1.02)
			if ($beforeTok -le $emerg) {
				return $Messages
			}
			# Absolute overflow: fall through to trim (intentional cache break beats OOM)
		}
	} catch {}

	$pass = 0
	while ($pass -lt $MaxPasses) {
		$pass++
		$est = Get-MBContextEstimate -Messages $Messages
		if ($est.PromptTokens -le $targetTok) { break }

		if ($Verbose) {
			Write-Host ("  ~ prompt ~{0:N0} tok > target ~{1:N0} - trim pass {2}..." -f `
				$est.PromptTokens, $targetTok, $pass) -ForegroundColor DarkGray
		}

		if ($pass -eq 1) {
			# Shrink tools first (fast). If still over budget after this pass, drop turns next.
			$Messages = @(Shrink-MBToolPayloads -Messages $Messages -RecentKeep 5 -OldMaxChars 1500 -RecentMaxChars 5000)
		} elseif ($pass -eq 2) {
			$Messages = @(Shrink-MBToolPayloads -Messages $Messages -RecentKeep 3 -OldMaxChars 800 -RecentMaxChars 3000)
			if ($useModelDigest) {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 18 -PreferModelDigest)
			} else {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 18)
			}
		} elseif ($pass -eq 3) {
			if ($useModelDigest) {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 12 -Aggressive -PreferModelDigest)
			} else {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 12 -Aggressive)
			}
			$Messages = @(Shrink-MBToolPayloads -Messages $Messages -RecentKeep 2 -OldMaxChars 500 -RecentMaxChars 2000)
		} elseif ($pass -eq 4) {
			if ($useModelDigest) {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 8 -Aggressive -PreferModelDigest)
			} else {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 8 -Aggressive)
			}
			$Messages = @(Shrink-MBToolPayloads -Messages $Messages -RecentKeep 2 -OldMaxChars 400 -RecentMaxChars 1200)
		} else {
			if ($useModelDigest) {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 6 -Aggressive -PreferModelDigest)
			} else {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 6 -Aggressive)
			}
			$Messages = @(Shrink-MBToolPayloads -Messages $Messages -RecentKeep 1 -OldMaxChars 300 -RecentMaxChars 800)
		}
		$Messages = @(Sync-MBSystemMessages -Messages $Messages)
	}

	$final = Get-MBContextEstimate -Messages $Messages
	if ($final.PromptTokens -lt $beforeTok -and [string]::IsNullOrWhiteSpace([string]$script:MB.LastCompactReason)) {
		$script:MB.LastCompactReason = ("silent trim ~{0:N0}->{1:N0} tok" -f $beforeTok, $final.PromptTokens)
	}
	if ($final.PromptTokens -gt $budget) {
		Write-MBWarn ("Context still ~{0:N0} tok over usable n_ctx room {1:N0} - consider /clear or /compact" -f $final.PromptTokens, $budget)
	}
	return $Messages
}

function Manage-MBContext {
	param(
		[array]$Messages,
		[switch]$ForceCompact,
		# Tool-loop path: keep system/state bytes identical; only append-friendly Sync.
		# Mutating SESSION STATE or shrinking older tool bodies invalidates llama.cpp
		[switch]$AppendOnly
	)
	try { Sync-MBAutoCompactFromWpf } catch {}

	$wireFrozen = $false
	try { $wireFrozen = [bool]$script:MB.WireStateFrozen } catch { $wireFrozen = $false }
	if ($AppendOnly -or ($wireFrozen -and -not $ForceCompact)) {
		# When frozen, Sync only reuses frozen system/sticky bytes (no EnableToolGroup rewrite).
		$Messages = @(Sync-MBSystemMessages -Messages $Messages)
		$estAO = Get-MBContextEstimate -Messages $Messages
		$budgetAO = Get-MBEffectivePromptBudget
		# Mid-loop tools growth can push estimate up; only emergency compact when truly over budget.
		# Soft 0.95 was too aggressive after EnableToolGroup inflated ToolsOverheadTok.
		$overHard = ($estAO.Level -eq 'hard') -or ($estAO.Pct -ge 1.0) -or ($estAO.PromptTokens -gt [math]::Floor($budgetAO * 1.02))
		if ($ForceCompact -or $overHard) {
			# Emergency only — breaks incremental board KV intentionally
			try { Thaw-MBWireState -Force } catch {}
			$Messages = @(Ensure-MBPromptBudget -Messages $Messages -TargetPct 0.68)
			try {
				Freeze-MBWireState -Refresh
				$Messages = @(Sync-MBSystemMessages -Messages $Messages)
			} catch {}
		}
		return $Messages
	}

	$Messages = @(Sync-MBSystemMessages -Messages $Messages)
	$est = Get-MBContextEstimate -Messages $Messages
	$useModelDigest = $false
	try { $useModelDigest = [bool]$script:MB.ModelCompact } catch { $useModelDigest = $false }

	if ($ForceCompact) {
		try { Thaw-MBWireState -Force } catch {}
		$Messages = @(Shrink-MBToolPayloads -Messages $Messages -RecentKeep 3 -OldMaxChars 800 -RecentMaxChars 2500)
		if ($useModelDigest) {
			$Messages = @(Compact-MBHistory -Messages $Messages -Aggressive -PreferModelDigest)
		} else {
			$Messages = @(Compact-MBHistory -Messages $Messages -Aggressive)
		}
		$Messages = @(Sync-MBSystemMessages -Messages $Messages)
		$Messages = @(Ensure-MBPromptBudget -Messages $Messages -TargetPct 0.65)
		try { Freeze-MBWireState -Refresh } catch {}
		return $Messages
	}

	if (-not $script:MB.AutoCompact) {
		if ($est.PromptTokens -gt (Get-MBEffectivePromptBudget)) {
			return @(Ensure-MBPromptBudget -Messages $Messages -TargetPct 0.70)
		}
		return $Messages
	}

	if ($est.Level -eq 'hard' -or $est.Pct -ge 0.92 -or $est.PromptTokens -gt (Get-MBEffectivePromptBudget)) {
		# Real compact (drop turns + optional model digest), not tool-trim alone
		return @(Ensure-MBPromptBudget -Messages $Messages -TargetPct 0.68)
	}

	if ($est.Level -eq 'soft') {
		# Soft used to only Shrink-MBToolPayloads — context % fell instantly while full turn
		# history remained, so the next request rebuilt prompt cache over nearly the same log.
		$Messages = @(Shrink-MBToolPayloads -Messages $Messages -RecentKeep 5 -OldMaxChars 1800 -RecentMaxChars ([math]::Min(8000, $MaxToolResultChars)))
		$est2 = Get-MBContextEstimate -Messages $Messages
		# Drop middle turns when still soft/hard or history is long
		$needDrop = ($est2.Level -ne 'ok') -or ($est2.Pct -ge [double]$script:MB.ContextSoftPct) -or (@($Messages).Count -gt [math]::Max(28, [int]($MaxHistoryMessages * 0.85)))
		if ($needDrop) {
			if ($useModelDigest) {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 20 -PreferModelDigest)
			} else {
				$Messages = @(Compact-MBHistory -Messages $Messages -KeepLast 20)
			}
		}
		$Messages = @(Sync-MBSystemMessages -Messages $Messages)
		[void](Get-MBContextEstimate -Messages $Messages)
		return $Messages
	}

	return $Messages
}

function Show-MBContextDetail {
	param([array]$Messages)
	$est = Get-MBContextEstimate -Messages $Messages
	Write-Host ""
	Write-MBRule -Label "context"
	Write-Host ("  Level          : {0}" -f $est.Level.ToUpper()) -ForegroundColor $(
		switch ($est.Level) { 'hard' { 'Red' } 'soft' { 'Yellow' } default { 'Green' } }
	)
	Write-Host ("  Budget used    : {0:P1}  (~{1:N0} / {2:N0} usable prompt tok)" -f $est.Pct, $est.PromptTokens, $est.UsableTokens) -ForegroundColor Gray
	$ctxSrc = 'config'
	try { $ctxSrc = [string]$script:MB.ContextSource } catch {}
	Write-Host ("  Model n_ctx    : {0:N0} tok ({1})" -f $est.WindowTokens, $ctxSrc) -ForegroundColor Gray
	Write-Host ("  Usable prompt  : {0:N0} tok (n_ctx minus completion reserve)" -f $est.UsableTokens) -ForegroundColor Gray
	Write-Host ("  Reserved       : {0:N0} tok reserved for completion (MaxTokens)" -f $est.ReserveTokens) -ForegroundColor Gray
	$srcLabel = switch ([string]$est.TokenSource) {
		'server' { 'server /tokenize' }
		'usage'  { 'last completion usage' }
		default  { 'local estimate' }
	}
	Write-Host ("  Token source   : {0}" -f $srcLabel) -ForegroundColor $(if ($est.TokenSource -eq 'estimate') { 'Yellow' } else { 'Green' })
	Write-Host ("  Messages       : {0}  ({1:N0} chars)" -f $est.MessageCount, $est.MessageChars) -ForegroundColor Gray
	Write-Host ("  Tool payloads  : {0:N0} chars in role=tool bodies" -f $est.ToolPayloadChars) -ForegroundColor Gray
	Write-Host ("  Tools schema   : ~{0:N0} chars / ~{1:N0} tok" -f $est.ToolsChars, $est.ToolsTokens) -ForegroundColor Gray
	Write-Host ("  By role chars  : system={0:N0} user={1:N0} assistant={2:N0} tool={3:N0}" -f `
		$est.ByRoleChars['system'], $est.ByRoleChars['user'], $est.ByRoleChars['assistant'], $est.ByRoleChars['tool']) -ForegroundColor DarkGray
	Write-Host ("  Soft / Hard    : {0:P0} / {1:P0}  |  AutoCompact: {2}  |  Runs: {3}" -f `
		$script:MB.ContextSoftPct, $script:MB.ContextHardPct, $script:MB.AutoCompact, $script:MB.CompactionCount) -ForegroundColor Gray
	if ($script:MB.LastCompactReason) {
		Write-Host "  Last compact   : $($script:MB.LastCompactReason)" -ForegroundColor DarkGray
	}
	Write-Host ""
	Write-Host "  Sticky findings:" -ForegroundColor Cyan
	$findings = @($script:MB.StickyFindings)
	if ($findings.Count -eq 0) { Write-Host "    (none - /find <text> to pin)" -ForegroundColor DarkGray }
	else { foreach ($f in $findings) { Write-Host "    - $f" -ForegroundColor Gray } }
	Write-Host "  Sticky notes:" -ForegroundColor Cyan
	$notes = @($script:MB.StickyNotes)
	if ($notes.Count -eq 0) { Write-Host "    (none - /note <text> to pin)" -ForegroundColor DarkGray }
	else { foreach ($n in $notes) { Write-Host "    - $n" -ForegroundColor Gray } }
	if ($script:MB.StickyExtra) {
		Write-Host "  Compressed digest:" -ForegroundColor Cyan
		Write-Host "    $($script:MB.StickyExtra)" -ForegroundColor DarkGray
	}
	Write-Host ""
	Write-Host "  Tip: tool results dominate context. Prefer GetBSODInfo over dumping .dmp bytes." -ForegroundColor DarkGray
	Write-Host ""
}

function Test-MBSpeechUiOk {
	if (Test-MBWpfActive) { return $true }
	if ($script:MB.HostUi -eq 'wpf') { return $true }
	return $false
}

function Test-MBSpeechPttDown {
	try {
		if ($script:HasNative -and ("MiniBot.Core.Native" -as [type])) {
			return [bool][MiniBot.Core.Native]::IsSpeechPttDown()
		}
	} catch {}
	return $false
}

function Initialize-MBSpeech {
	if ($script:MB.SpeechReady -and $script:MB.SpeechSynth) {
		return $true
	}
	$script:MB.SpeechInitError = ''
	try {
		Add-Type -AssemblyName System.Speech -ErrorAction Stop
	} catch {
		$script:MB.SpeechInitError = "System.Speech not available: $($_.Exception.Message)"
		$script:MB.SpeechReady = $false
		return $false
	}

	try {
		if (-not $script:MB.SpeechSynth) {
			$script:MB.SpeechSynth = New-Object System.Speech.Synthesis.SpeechSynthesizer
			try { $script:MB.SpeechSynth.SetOutputToDefaultAudioDevice() } catch {}
			try { $script:MB.SpeechSynth.Rate = 1 } catch {}
			try { $script:MB.SpeechSynth.Volume = 100 } catch {}
		}
	} catch {
		$script:MB.SpeechInitError = "Speech synthesizer failed: $($_.Exception.Message)"
		$script:MB.SpeechReady = $false
		return $false
	}

	try {
		if (-not $script:MB.SpeechEngine) {
			$eng = $null
			$cultures = @(
				[System.Globalization.CultureInfo]::CurrentUICulture,
				[System.Globalization.CultureInfo]::CurrentCulture,
				[System.Globalization.CultureInfo]::GetCultureInfo('en-US')
			)
			foreach ($c in $cultures) {
				try {
					$eng = New-Object System.Speech.Recognition.SpeechRecognitionEngine($c)
					if ($eng) { break }
				} catch { $eng = $null }
			}
			if (-not $eng) {
				$eng = New-Object System.Speech.Recognition.SpeechRecognitionEngine
			}
			$eng.SetInputToDefaultAudioDevice()

			$dict = New-Object System.Speech.Recognition.DictationGrammar
			$dict.Enabled = $true
			$eng.LoadGrammar($dict)
			try {
				$spell = New-Object System.Speech.Recognition.DictationGrammar 'grammar:dictation#spelling'
				$spell.Enabled = $true
				$eng.LoadGrammar($spell)
			} catch {}

			try { $eng.InitialSilenceTimeout = [TimeSpan]::FromSeconds(15) } catch {}
			try { $eng.BabbleTimeout = [TimeSpan]::FromSeconds(0) } catch {}
			try { $eng.EndSilenceTimeout = [TimeSpan]::FromSeconds(1.2) } catch {}
			try { $eng.EndSilenceTimeoutAmbiguous = [TimeSpan]::FromSeconds(1.5) } catch {}
			try { $eng.MaxAlternates = 3 } catch {}

			$script:MB.SpeechEngine = $eng
		}
	} catch {
		$script:MB.SpeechInitError = "Speech recognition failed (mic/language pack?): $($_.Exception.Message)"
		$script:MB.SpeechEngine = $null
	}

	$script:MB.SpeechReady = [bool]$script:MB.SpeechSynth
	return [bool]$script:MB.SpeechReady
}

function Stop-MBSpeech {
	try { Stop-MBSpeechWaveVisualizer } catch {}
	try {
		if ($script:MB.SpeechSynth) {
			try { $script:MB.SpeechSynth.SpeakAsyncCancelAll() } catch {}
			try { $script:MB.SpeechSynth.Dispose() } catch {}
		}
	} catch {}
	try {
		if ($script:MB.SpeechEngine) {
			try { $script:MB.SpeechEngine.RecognizeAsyncCancel() } catch {}
			try { $script:MB.SpeechEngine.Dispose() } catch {}
		}
	} catch {}
	try {
		Get-EventSubscriber -ErrorAction SilentlyContinue |
			Where-Object { $_.SourceIdentifier -like 'MB.Speech.*' } |
			ForEach-Object { Unregister-Event -SourceIdentifier $_.SourceIdentifier -Force -ErrorAction SilentlyContinue }
	} catch {}
	$script:MB.SpeechSynth = $null
	$script:MB.SpeechEngine = $null
	$script:MB.SpeechReady = $false
	$script:MB.SpeechListening = $false
}

function ConvertTo-MBSpeakableText {
	param([string]$Text)
	if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
	$t = [string]$Text
	$t = [regex]::Replace($t, '(?s)```.*?```', ' (code block) ')
	$t = [regex]::Replace($t, '`([^`]+)`', '$1')
	$t = [regex]::Replace($t, '\[([^\]]+)\]\([^\)]+\)', '$1')
	$t = $t -replace '[\*]{1,3}', '' -replace '_{1,3}', ''
	$t = $t -replace '(?m)^\s{0,3}#+\s*', '' -replace '(?m)^\s*[-*+]\s+', ''
	$t = $t -replace '\s+', ' '
	$t = $t.Trim()
	if ($t.Length -gt 1200) {
		$t = $t.Substring(0, 1197) + '...'
	}
	return $t
}

function Invoke-MBSpeak {
	param(
		[string]$Text,
		[int]$Rate = 1,
		[bool]$Async = $true
	)
	if (-not (Initialize-MBSpeech)) {
		return "ERROR: Speech TTS unavailable. $($script:MB.SpeechInitError)"
	}
	$speakable = ConvertTo-MBSpeakableText -Text $Text
	if ([string]::IsNullOrWhiteSpace($speakable)) {
		return "ERROR: Nothing speakable after cleanup."
	}
	try {
		if ($null -ne $Rate -and $Rate -ge -10 -and $Rate -le 10) {
			try { $script:MB.SpeechSynth.Rate = $Rate } catch {}
		}
		try { $script:MB.SpeechSynth.SpeakAsyncCancelAll() } catch {}
		try { Stop-MBSpeechWavePlayback } catch {}

		# WPF: synthesize TTS to WAV -> play + high-FPS wave scrub.
		# Always wait for playback to finish so the agent turn cannot race ahead of speech.
		$useWave = $false
		try { $useWave = [bool](Test-MBWpfActive) } catch { $useWave = $false }
		if ($useWave) {
			$ms = $null
			try {
				$ms = New-Object System.IO.MemoryStream
				$script:MB.SpeechSynth.SetOutputToWaveStream($ms)
				$script:MB.SpeechSynth.Speak($speakable)
			} finally {
				try { $script:MB.SpeechSynth.SetOutputToDefaultAudioDevice() } catch {}
			}
			$bytes = $null
			try { $bytes = $ms.ToArray() } catch { $bytes = $null }
			try { if ($ms) { $ms.Dispose() } } catch {}
			$pcm = $null
			if ($bytes) { $pcm = ConvertFrom-MBWavBytes -Bytes $bytes }
			if ($pcm -and $pcm.Ok -and $pcm.Samples -and $pcm.Samples.Length -gt 2) {
				Start-MBSpeechWaveFromPcm -Samples $pcm.Samples -SampleRate ([int]$pcm.SampleRate) -DurationMs ([int]$pcm.DurationMs) -WavBytes $bytes
				# Block until audio+wave complete (pump UI so CompositionTarget keeps firing)
				Wait-MBSpeechWavePlayback
				try {
					if (-not [bool]$script:MB.SpeechEnabled) { Stop-MBSpeechWaveVisualizer }
				} catch {}
				return ("SUCCESS: Spoke ({0} chars, tts-wave {1}ms)." -f $speakable.Length, [int]$pcm.DurationMs)
			}
			try { Start-MBSpeechWaveVisualizer -ForceSpeaking } catch {}
		}

		# Fallback: device TTS (no sample wave)
		if ($Async) {
			[void]$script:MB.SpeechSynth.SpeakAsync($speakable)
			return "SUCCESS: Speaking ($($speakable.Length) chars, async)."
		} else {
			$script:MB.SpeechSynth.Speak($speakable)
			try {
				if (-not [bool]$script:MB.SpeechEnabled) { Stop-MBSpeechWaveVisualizer }
			} catch {}
			return "SUCCESS: Spoke ($($speakable.Length) chars)."
		}
	} catch {
		try { $script:MB.SpeechSynth.SetOutputToDefaultAudioDevice() } catch {}
		return "ERROR: TTS failed: $($_.Exception.Message)"
	}
}

function Invoke-MBSpeechListen {
	param(
		[int]$MaxSeconds = 90,
		[scriptblock]$UpdatePrompt = $null
	)
	if (-not (Test-MBSpeechUiOk)) {
		return @{ ok = $false; text = ''; error = 'speech_requires_wpf_host' }
	}
	if (-not (Initialize-MBSpeech)) {
		return @{ ok = $false; text = ''; error = $script:MB.SpeechInitError }
	}
	if (-not $script:MB.SpeechEngine) {
		return @{ ok = $false; text = ''; error = "Dictation engine not available. $($script:MB.SpeechInitError)" }
	}

	$eng = $script:MB.SpeechEngine
	$script:MB.SpeechListening = $true

	$global:MB_SpeechParts = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
	$global:MB_SpeechHypo = ''

	$paint = {
		param([string]$msg)
		if ($UpdatePrompt) {
			try { & $UpdatePrompt $msg } catch {}
		}
	}

	try {
		foreach ($sid in @('MB.Speech.Rec', 'MB.Speech.Hyp')) {
			try { Unregister-Event -SourceIdentifier $sid -Force -ErrorAction SilentlyContinue } catch {}
			try { Get-Event -SourceIdentifier $sid -ErrorAction SilentlyContinue | Remove-Event -ErrorAction SilentlyContinue } catch {}
		}
		try { $eng.RecognizeAsyncCancel() } catch {}

		try {
			while ([Console]::KeyAvailable) { [void][Console]::ReadKey($true) }
		} catch {}

		& $paint '● REC  hold Right-Ctrl... release to stop'

		$null = Register-ObjectEvent -InputObject $eng -EventName SpeechRecognized -SourceIdentifier 'MB.Speech.Rec' -Action {
			try {
				$txt = [string]$Event.SourceEventArgs.Result.Text
				if (-not [string]::IsNullOrWhiteSpace($txt)) {
					[void]$global:MB_SpeechParts.Add($txt.Trim())
					$global:MB_SpeechHypo = ''
				}
			} catch {}
		}
		$null = Register-ObjectEvent -InputObject $eng -EventName SpeechHypothesized -SourceIdentifier 'MB.Speech.Hyp' -Action {
			try {
				$global:MB_SpeechHypo = [string]$Event.SourceEventArgs.Result.Text
			} catch {}
		}

		$eng.RecognizeAsync([System.Speech.Recognition.RecognizeMode]::Multiple)

		$sw = [System.Diagnostics.Stopwatch]::StartNew()
		$lastPaint = ''
		$cancelled = $false
		# Debounce PTT key-down
		$armed = $false
		$armWait = [System.Diagnostics.Stopwatch]::StartNew()
		while ($armWait.ElapsedMilliseconds -lt 400 -and -not $armed) {
			if (Test-MBSpeechPttDown) { $armed = $true; break }
			Start-Sleep -Milliseconds 15
		}
		if (-not $armed -and -not (Test-MBSpeechPttDown)) {
			& $paint ''
			return @{ ok = $false; text = ''; error = 'ptt_not_held' }
		}

		while ($sw.Elapsed.TotalSeconds -lt $MaxSeconds) {
			if ((Test-MBInterrupt)) { $cancelled = $true; break }

			try {
				if ([Console]::KeyAvailable) {
					$kk = [Console]::ReadKey($true)
					if ($kk.Key -eq [ConsoleKey]::Escape) { $cancelled = $true; break }
				}
			} catch {}

			if (-not (Test-MBSpeechPttDown) -and $sw.ElapsedMilliseconds -gt 150) {
				break
			}

			$committed = (@($global:MB_SpeechParts) -join ' ').Trim()
			$hyp = [string]$global:MB_SpeechHypo
			$show = if ($committed -and $hyp) {
				"● REC  $committed $hyp"
			} elseif ($committed) {
				"● REC  $committed"
			} elseif ($hyp) {
				"● REC  $hyp"
			} else {
				'● REC  hold Right-Ctrl... release to stop'
			}
			if ($show -ne $lastPaint) {
				& $paint $show
				$lastPaint = $show
			}

			Start-Sleep -Milliseconds 30
		}

		try { $eng.RecognizeAsyncStop() } catch {
			try { $eng.RecognizeAsyncCancel() } catch {}
		}
		$flush = [System.Diagnostics.Stopwatch]::StartNew()
		while ($flush.ElapsedMilliseconds -lt 450) {
			Start-Sleep -Milliseconds 30
		}

		foreach ($sid in @('MB.Speech.Rec', 'MB.Speech.Hyp')) {
			try { Unregister-Event -SourceIdentifier $sid -Force -ErrorAction SilentlyContinue } catch {}
			try { Get-Event -SourceIdentifier $sid -ErrorAction SilentlyContinue | Remove-Event -ErrorAction SilentlyContinue } catch {}
		}

		$upWait = [System.Diagnostics.Stopwatch]::StartNew()
		while ((Test-MBSpeechPttDown) -and $upWait.ElapsedMilliseconds -lt 2000) {
			Start-Sleep -Milliseconds 20
		}
		try {
			while ([Console]::KeyAvailable) { [void][Console]::ReadKey($true) }
		} catch {}

		if ($cancelled) {
			& $paint ''
			return @{ ok = $false; text = ''; error = 'cancelled' }
		}

		$joined = (@($global:MB_SpeechParts) -join ' ').Trim()
		$hyp = [string]$global:MB_SpeechHypo
		if ($hyp -and ($joined -notlike "*$hyp*")) {
			if ($joined) { $joined = "$joined $hyp" } else { $joined = $hyp }
			$joined = $joined.Trim()
		}
		$script:MB.SpeechLastHeard = $joined

		if ($joined) {
			& $paint $joined
			return @{ ok = $true; text = $joined; error = '' }
		}
		& $paint ''
		return @{ ok = $false; text = ''; error = 'no_speech' }
	} catch {
		try { & $paint '' } catch {}
		return @{ ok = $false; text = ''; error = $_.Exception.Message }
	} finally {
		$script:MB.SpeechListening = $false
		try { $eng.RecognizeAsyncCancel() } catch {}
		foreach ($sid in @('MB.Speech.Rec', 'MB.Speech.Hyp')) {
			try { Unregister-Event -SourceIdentifier $sid -Force -ErrorAction SilentlyContinue } catch {}
		}
		try {
			while ([Console]::KeyAvailable) { [void][Console]::ReadKey($true) }
		} catch {}
	}
}

function Enable-MBSpeechMode {
	param([bool]$On = $true)
	if ($On -and -not (Test-MBSpeechUiOk)) {
		$script:MB.SpeechEnabled = $false
		return "Speech requires the WPF host."
	}
	if (-not $On) {
		$script:MB.SpeechListening = $false
		try {
			if ($script:MB.SpeechEngine) { $script:MB.SpeechEngine.RecognizeAsyncCancel() }
		} catch {}
		try {
			if ($script:MB.SpeechSynth) { $script:MB.SpeechSynth.SpeakAsyncCancelAll() }
		} catch {}
		try { Stop-MBSpeechWaveVisualizer } catch {}
	}
	$script:MB.SpeechEnabled = [bool]$On
	if ($On) {
		if (-not (Initialize-MBSpeech)) {
			return "Speech mode ON but init failed: $($script:MB.SpeechInitError)"
		}
		try {
			if (-not ($script:MB.ActiveToolGroups -contains 'sound')) {
				[void]$script:MB.ActiveToolGroups.Add('sound')
				try { Sync-MBPromptAfterToolGroups } catch { try { Initialize-MBToolsOverhead } catch {} }
			}
		} catch {}
		try { Start-MBSpeechWaveVisualizer } catch {}
		$dict = if ($script:MB.SpeechEngine) { 'dictation OK' } else { 'dictation UNAVAILABLE (TTS only)' }
		$auto = if ($script:MB.SpeechAutoReply) { 'ON' } else { 'off' }
		return "Speech mode ON ($dict). Hold Right-Ctrl to talk, release to stop. Typing works when RCtrl is up. Auto-speak: $auto. Tool: SpeakText (group sound)."
	} else {
		try {
			if ($script:MB.ActiveToolGroups -contains 'sound') {
				[void]$script:MB.ActiveToolGroups.Remove('sound')
				try { Sync-MBPromptAfterToolGroups } catch { try { Initialize-MBToolsOverhead } catch {} }
			}
		} catch {}
		return "Speech mode OFF."
	}
}



# Speech codebox: real SAPI PCM (WaveStream) + SoundPlayer + CompositionTarget.Rendering (high FPS).
# No WASAPI / no Add-Type audio COM.
function Resolve-MBSpeechWaveControls {
	$W = $script:MB.Wpf
	if (-not $W) { return $false }
	try {
		if (-not $W.SpeechWaveBox -and $W.Window) {
			$W.SpeechWaveBox = $W.Window.FindName('SpeechWaveBox')
			$W.SpeechWaveCanvas = $W.Window.FindName('SpeechWaveCanvas')
			$W.SpeechWaveLine = $W.Window.FindName('SpeechWaveLine')
			$W.SpeechWaveStatus = $W.Window.FindName('SpeechWaveStatus')
			$W.SpeechWaveLang = $W.Window.FindName('SpeechWaveLang')
		}
	} catch {}
	return [bool]$W.SpeechWaveBox
}

function ConvertFrom-MBWavBytes {
	param([byte[]]$Bytes)
	$result = @{
		Ok         = $false
		Samples    = [float[]]@()
		SampleRate = 22050
		Channels   = 1
		Bits       = 16
		DurationMs = 0
	}
	if (-not $Bytes -or $Bytes.Length -lt 44) { return $result }
	try {
		if ([char]$Bytes[0] -ne 'R' -or [char]$Bytes[8] -ne 'W') { return $result }
		$pos = 12
		$fmtCh = 1
		$fmtRate = 22050
		$fmtBits = 16
		$fmtTag = 1
		$dataOff = -1
		$dataLen = 0
		while (($pos + 8) -le $Bytes.Length) {
			$id = [Text.Encoding]::ASCII.GetString($Bytes, $pos, 4)
			$size = [BitConverter]::ToInt32($Bytes, $pos + 4)
			if ($size -lt 0) { break }
			$chunk = $pos + 8
			if ($id -eq 'fmt ' -and ($chunk + 16) -le $Bytes.Length) {
				$fmtTag = [BitConverter]::ToUInt16($Bytes, $chunk)
				$fmtCh = [BitConverter]::ToUInt16($Bytes, $chunk + 2)
				$fmtRate = [BitConverter]::ToInt32($Bytes, $chunk + 4)
				$fmtBits = [BitConverter]::ToUInt16($Bytes, $chunk + 14)
			} elseif ($id -eq 'data') {
				$dataOff = $chunk
				$dataLen = $size
				break
			}
			$pos = $chunk + $size
			if (($pos % 2) -eq 1) { $pos++ }
		}
		if ($dataOff -lt 0 -or $dataLen -le 0) { return $result }
		if (($dataOff + $dataLen) -gt $Bytes.Length) { $dataLen = $Bytes.Length - $dataOff }
		if ($fmtCh -lt 1) { $fmtCh = 1 }
		if ($fmtRate -lt 1) { $fmtRate = 22050 }
		$bytesPer = [Math]::Max(1, [int]($fmtBits / 8))
		$frame = $bytesPer * $fmtCh
		if ($frame -lt 1) { return $result }
		$nFrames = [int][Math]::Floor($dataLen / $frame)
		if ($nFrames -lt 2) { return $result }
		# True duration from original stream (never from downsampled rate)
		$durationMs = [int][Math]::Round(1000.0 * $nFrames / [double]$fmtRate)
		if ($durationMs -lt 80) { $durationMs = 80 }

		# Keep denser samples for smooth scrub (~48k max)
		$target = 48000
		$step = 1
		if ($nFrames -gt $target) { $step = [int][Math]::Ceiling($nFrames / [double]$target) }
		$outN = [int][Math]::Ceiling($nFrames / [double]$step)
		$samples = New-Object 'System.Single[]' $outN
		$oi = 0
		for ($f = 0; $f -lt $nFrames -and $oi -lt $outN; $f += $step) {
			$sum = 0.0
			for ($c = 0; $c -lt $fmtCh; $c++) {
				$off = $dataOff + ($f * $frame) + ($c * $bytesPer)
				if (($off + $bytesPer) -gt $Bytes.Length) { break }
				$s = 0.0
				if ($fmtTag -eq 3 -and $fmtBits -eq 32) {
					$s = [BitConverter]::ToSingle($Bytes, $off)
				} elseif ($fmtBits -eq 16) {
					$s = [BitConverter]::ToInt16($Bytes, $off) / 32768.0
				} elseif ($fmtBits -eq 8) {
					$s = ($Bytes[$off] - 128) / 128.0
				} elseif ($fmtBits -eq 32 -and $fmtTag -eq 1) {
					$s = [BitConverter]::ToInt32($Bytes, $off) / 2147483648.0
				} else {
					$s = [BitConverter]::ToInt16($Bytes, $off) / 32768.0
				}
				$sum += $s
			}
			$samples[$oi] = [float]($sum / $fmtCh)
			$oi++
		}
		if ($oi -lt $outN) {
			$trim = New-Object 'System.Single[]' $oi
			[Array]::Copy($samples, $trim, $oi)
			$samples = $trim
		}
		$result.Ok = $true
		$result.Samples = $samples
		$result.SampleRate = $fmtRate
		$result.Channels = $fmtCh
		$result.Bits = $fmtBits
		$result.DurationMs = $durationMs
		return $result
	} catch {
		return $result
	}
}

function Stop-MBSpeechWavePlayback {
	$W = $script:MB.Wpf
	if (-not $W) { return }
	try {
		if ($W.SpeechWavePlayer) {
			try { $W.SpeechWavePlayer.Stop() } catch {}
			try { $W.SpeechWavePlayer.Dispose() } catch {}
		}
	} catch {}
	try {
		if ($W.SpeechWavePlayStream) { $W.SpeechWavePlayStream.Dispose() }
	} catch {}
	try { $W.SpeechWavePlayer = $null } catch {}
	try { $W.SpeechWavePlayStream = $null } catch {}
	try { $W.SpeechWavePlaying = $false } catch {}
	try {
		if ($W.SpeechWaveClock) { $W.SpeechWaveClock.Stop() }
	} catch {}
}

function Start-MBSpeechWaveRenderLoop {
	# CompositionTarget.Rendering ≈ display refresh (very smooth)
	if (-not (Test-MBWpfActive)) { return }
	$W = $script:MB.Wpf
	if (-not $W) { return }
	$ui = {
		try {
			if ([bool]$W.SpeechWaveRenderHooked) { return }
			$handler = [System.EventHandler] {
				param($s, $e)
				try { Update-MBSpeechWaveFrame } catch {}
			}
			$W.SpeechWaveRenderHandler = $handler
			[System.Windows.Media.CompositionTarget]::add_Rendering($handler)
			$W.SpeechWaveRenderHooked = $true
		} catch {
			# Fallback timer ~120fps if CompositionTarget unavailable
			try {
				if (-not $W.SpeechWaveTimer) {
					$tm = New-Object System.Windows.Threading.DispatcherTimer
					$tm.Interval = [TimeSpan]::FromMilliseconds(8)
					$tm.add_Tick({
						param($s2, $e2)
						try { Update-MBSpeechWaveFrame } catch {}
					}.GetNewClosure())
					$W.SpeechWaveTimer = $tm
				}
				if (-not $W.SpeechWaveTimer.IsEnabled) { $W.SpeechWaveTimer.Start() }
			} catch {}
		}
	}.GetNewClosure()
	try { Invoke-MBWpf -Action $ui } catch { try { & $ui } catch {} }
}

function Stop-MBSpeechWaveRenderLoop {
	$W = $script:MB.Wpf
	if (-not $W) { return }
	$ui = {
		try {
			if ([bool]$W.SpeechWaveRenderHooked -and $W.SpeechWaveRenderHandler) {
				[System.Windows.Media.CompositionTarget]::remove_Rendering($W.SpeechWaveRenderHandler)
			}
		} catch {}
		try { $W.SpeechWaveRenderHooked = $false } catch {}
		try { $W.SpeechWaveRenderHandler = $null } catch {}
		try {
			if ($W.SpeechWaveTimer) { $W.SpeechWaveTimer.Stop() }
		} catch {}
	}.GetNewClosure()
	try { Invoke-MBWpf -Action $ui } catch { try { & $ui } catch {} }
}

function Start-MBSpeechWaveVisualizer {
	param([switch]$ForceSpeaking)
	if (-not (Test-MBWpfActive)) { return }
	$W = $script:MB.Wpf
	if (-not $W) { return }
	if ($ForceSpeaking) {
		try { $W.SpeechWaveForceSpeaking = $true } catch {}
		try { $W.SpeechWaveForceUntil = [Environment]::TickCount + 600 } catch {}
	}
	$ui = {
		try {
			if (-not (Resolve-MBSpeechWaveControls)) { return }
			$box = $W.SpeechWaveBox
			$box.Visibility = [System.Windows.Visibility]::Visible
			try { [System.Windows.Controls.Panel]::SetZIndex($box, 8) } catch {}
			if ($W.SpeechWaveLang) { $W.SpeechWaveLang.Text = 'speech' }
			if ($ForceSpeaking -and $W.SpeechWaveStatus) {
				$W.SpeechWaveStatus.Text = 'speaking'
				try {
					$bc = New-Object System.Windows.Media.BrushConverter
					$W.SpeechWaveStatus.Foreground = $bc.ConvertFromString('#00BFFF')
				} catch {}
			}
		} catch {}
	}.GetNewClosure()
	try { Invoke-MBWpf -Action $ui } catch { try { & $ui } catch {} }
	try { Start-MBSpeechWaveRenderLoop } catch {}
}

function Start-MBSpeechWaveFromPcm {
	param(
		[float[]]$Samples,
		[int]$SampleRate = 22050,
		[int]$DurationMs = 0,
		[byte[]]$WavBytes = $null
	)
	if (-not (Test-MBWpfActive)) { return }
	$W = $script:MB.Wpf
	if (-not $W) { return }
	if (-not $Samples -or $Samples.Length -lt 2) { return }

	try { Stop-MBSpeechWavePlayback } catch {}
	$W.SpeechWaveSamples = $Samples
	$W.SpeechWaveSampleRate = [Math]::Max(1, $SampleRate)
	if ($DurationMs -gt 0) {
		$W.SpeechWaveDurationMs = $DurationMs
	} else {
		$W.SpeechWaveDurationMs = [int][Math]::Max(80, [Math]::Round(1000.0 * $Samples.Length / [double]$W.SpeechWaveSampleRate))
	}
	$W.SpeechWaveForceSpeaking = $false
	$W.SpeechWaveIdleTicks = 0

	$clock = New-Object System.Diagnostics.Stopwatch
	$W.SpeechWaveClock = $clock
	$W.SpeechWavePlaying = $true

	if ($WavBytes -and $WavBytes.Length -gt 44) {
		try {
			$playMs = New-Object System.IO.MemoryStream (,$WavBytes)
			$playMs.Position = 0
			$player = New-Object System.Media.SoundPlayer
			$player.Stream = $playMs
			$player.Load()
			$W.SpeechWavePlayStream = $playMs
			$W.SpeechWavePlayer = $player
			$clock.Restart()
			$player.Play()
		} catch {
			$clock.Restart()
		}
	} else {
		$clock.Restart()
	}

	try { Start-MBSpeechWaveVisualizer } catch {}
	$ui = {
		try {
			if ($W.SpeechWaveLang) { $W.SpeechWaveLang.Text = ('speech {0} tts' -f ([char]0x00B7)) }
			if ($W.SpeechWaveStatus) {
				$W.SpeechWaveStatus.Text = 'speaking'
				$bc = New-Object System.Windows.Media.BrushConverter
				$W.SpeechWaveStatus.Foreground = $bc.ConvertFromString('#00BFFF')
			}
		} catch {}
	}.GetNewClosure()
	try { Invoke-MBWpf -Action $ui } catch { try { & $ui } catch {} }
}

function Wait-MBSpeechWavePlayback {
	param([int]$PadMs = 40)
	$W = $script:MB.Wpf
	if (-not $W) { return }
	$dur = 0
	try { $dur = [int]$W.SpeechWaveDurationMs } catch { $dur = 0 }
	if ($dur -lt 1) { $dur = 1 }
	$limit = $dur + [Math]::Max(0, $PadMs)
	$sw = [System.Diagnostics.Stopwatch]::StartNew()
	$d = $null
	try { $d = $W.Dispatcher } catch { $d = $null }
	while ($sw.ElapsedMilliseconds -lt $limit) {
		$still = $true
		try {
			if ($W.SpeechWaveClock -and $W.SpeechWaveClock.IsRunning) {
				if ($W.SpeechWaveClock.ElapsedMilliseconds -ge $dur) { $still = $false }
			} elseif (-not [bool]$W.SpeechWavePlaying) {
				$still = $false
			}
		} catch {}
		if (-not $still) { break }
		# Pump UI so CompositionTarget.Rendering keeps updating the wave
		try {
			if ($d) {
				if ($d.CheckAccess()) {
					try { Update-MBSpeechWaveFrame } catch {}
				} else {
					[void]$d.Invoke([Action]{
						try { Update-MBSpeechWaveFrame } catch {}
					}, [System.Windows.Threading.DispatcherPriority]::Render)
				}
			}
		} catch {}
		Start-Sleep -Milliseconds 4
	}
	try { $W.SpeechWavePlaying = $false } catch {}
	try {
		if ($W.SpeechWaveClock) { $W.SpeechWaveClock.Stop() }
	} catch {}
}

function Stop-MBSpeechWaveVisualizer {
	if (-not $script:MB.Wpf) { return }
	$W = $script:MB.Wpf
	try { $W.SpeechWaveForceSpeaking = $false } catch {}
	try { $W.SpeechWavePlaying = $false } catch {}
	try { Stop-MBSpeechWavePlayback } catch {}
	try { Stop-MBSpeechWaveRenderLoop } catch {}
	try { $W.SpeechWaveSamples = $null } catch {}
	$ui = {
		try { if ($W.SpeechWaveBox) { $W.SpeechWaveBox.Visibility = [System.Windows.Visibility]::Collapsed } } catch {}
		try {
			if ($W.SpeechWaveLine) { $W.SpeechWaveLine.Points = (New-Object System.Windows.Media.PointCollection) }
		} catch {}
		try {
			if ($W.SpeechWaveStatus) {
				$W.SpeechWaveStatus.Text = 'idle'
				$bc = New-Object System.Windows.Media.BrushConverter
				$W.SpeechWaveStatus.Foreground = $bc.ConvertFromString('#6A6A76')
			}
		} catch {}
		try { if ($W.SpeechWaveLang) { $W.SpeechWaveLang.Text = 'speech' } } catch {}
	}.GetNewClosure()
	try { Invoke-MBWpf -Action $ui } catch { try { & $ui } catch {} }
}

function Update-MBSpeechWaveFrame {
	# UI thread - high frequency via CompositionTarget.Rendering
	if (-not $script:MB.Wpf) { return }
	$W = $script:MB.Wpf
	if (-not (Resolve-MBSpeechWaveControls)) { return }
	if ($W.SpeechWaveBox.Visibility -ne [System.Windows.Visibility]::Visible) { return }
	$canvas = $W.SpeechWaveCanvas
	$line = $W.SpeechWaveLine
	if (-not $canvas -or -not $line) { return }

	$ww = [double]$canvas.ActualWidth
	$hh = [double]$canvas.ActualHeight
	if ($ww -lt 8 -or $hh -lt 8 -or [double]::IsNaN($ww) -or [double]::IsNaN($hh)) {
		try { $ww = [Math]::Max(8.0, [double]$W.SpeechWaveBox.ActualWidth - 24.0) } catch { $ww = 320.0 }
		$hh = 84.0
	}
	if ($ww -lt 8) { $ww = 320.0 }
	if ($hh -lt 8) { $hh = 84.0 }

	$samples = $null
	try { $samples = $W.SpeechWaveSamples } catch { $samples = $null }
	$playing = $false
	try { $playing = [bool]$W.SpeechWavePlaying } catch { $playing = $false }
	$listening = $false
	try {
		if ((Test-MBSpeechPttDown) -and [bool]$script:MB.SpeechEnabled) { $listening = $true }
	} catch {}
	try {
		if (-not $listening -and [bool]$script:MB.SpeechListening) { $listening = $true }
	} catch {}

	$playhead = 0.0
	$dur = 0
	try { $dur = [int]$W.SpeechWaveDurationMs } catch { $dur = 0 }
	$elapsed = 0
	try {
		if ($W.SpeechWaveClock) { $elapsed = [int]$W.SpeechWaveClock.ElapsedMilliseconds }
	} catch { $elapsed = 0 }

	if ($playing -and $dur -gt 0) {
		if ($elapsed -ge $dur) {
			$playhead = 1.0
			$W.SpeechWavePlaying = $false
			$playing = $false
			try { if ($W.SpeechWaveClock) { $W.SpeechWaveClock.Stop() } } catch {}
		} else {
			$playhead = $elapsed / [double]$dur
			if ($playhead -lt 0) { $playhead = 0 }
			if ($playhead -gt 1) { $playhead = 1 }
		}
	}

	$speaking = $playing
	if (-not $speaking -and $samples -and $elapsed -gt 0 -and $elapsed -lt $dur) { $speaking = $true }

	# Auto-hide after TTS when speech mode is off (leave a short tail)
	try {
		if (-not $speaking -and -not $listening -and -not [bool]$script:MB.SpeechEnabled) {
			$idleN = 0
			try { $idleN = [int]$W.SpeechWaveIdleTicks } catch { $idleN = 0 }
			$idleN++
			$W.SpeechWaveIdleTicks = $idleN
			# CompositionTarget is ~60fps -> ~0.5s tail
			if ($idleN -gt 30) {
				try { Stop-MBSpeechWaveRenderLoop } catch {}
				$W.SpeechWaveBox.Visibility = [System.Windows.Visibility]::Collapsed
				$W.SpeechWaveIdleTicks = 0
				try { $W.SpeechWaveSamples = $null } catch {}
				return
			}
		} else {
			$W.SpeechWaveIdleTicks = 0
		}
	} catch {}

	$st = 'idle'
	$stHex = '#6A6A76'
	if ($speaking) { $st = 'speaking'; $stHex = '#00BFFF' }
	elseif ($listening) { $st = 'listening'; $stHex = '#9ECE6A' }
	try {
		if ($W.SpeechWaveStatus -and [string]$W.SpeechWaveStatus.Text -ne $st) {
			$W.SpeechWaveStatus.Text = $st
			$bc = New-Object System.Windows.Media.BrushConverter
			$W.SpeechWaveStatus.Foreground = $bc.ConvertFromString($stHex)
		}
	} catch {}

	$n = 220
	$mid = $hh * 0.5
	$ampScale = $hh * 0.47
	$pts = New-Object System.Windows.Media.PointCollection

	if ($samples -and $samples.Length -gt 2 -and ($speaking -or ($playhead -gt 0 -and $playhead -lt 1))) {
		$len = $samples.Length
		$center = [int][Math]::Floor($playhead * ($len - 1))
		if ($center -lt 0) { $center = 0 }
		if ($center -ge $len) { $center = $len - 1 }
		# ~100ms window of audio at original rate, mapped through downsampled buffer
		$win = [Math]::Min($len, [Math]::Max(320, [int]($len * 0.06)))
		$a = $center - [int]($win / 2)
		if ($a -lt 0) { $a = 0 }
		$b = $a + $win
		if ($b -gt $len) { $b = $len; $a = [Math]::Max(0, $b - $win) }
		$span = [Math]::Max(1, $b - $a - 1)
		for ($i = 0; $i -lt $n; $i++) {
			$t = $i / [double][Math]::Max(1, $n - 1)
			$x = $t * $ww
			$i0 = $a + [int]($t * $span)
			$i1 = $a + [int]((($i + 1) / [double]$n) * $span)
			if ($i1 -le $i0) { $i1 = $i0 + 1 }
			if ($i1 -gt $b) { $i1 = $b }
			$peak = 0.0
			$signed = 0.0
			for ($j = $i0; $j -lt $i1; $j++) {
				$v = [double]$samples[$j]
				$av = [Math]::Abs($v)
				if ($av -gt $peak) { $peak = $av; $signed = $v }
			}
			$v = $signed * 3.0
			if ($v -gt 1) { $v = 1 }
			if ($v -lt -1) { $v = -1 }
			$y = $mid - ($v * $ampScale)
			if ($y -lt 1.5) { $y = 1.5 }
			if ($y -gt ($hh - 1.5)) { $y = $hh - 1.5 }
			[void]$pts.Add((New-Object System.Windows.Point($x, $y)))
		}
	} else {
		$ph = 0.0
		try { $ph = [double]$W.SpeechWavePhase } catch { $ph = 0.0 }
		if ($listening) { $ph += 0.22 } else { $ph += 0.08 }
		$W.SpeechWavePhase = $ph
		for ($i = 0; $i -lt $n; $i++) {
			$t = $i / [double][Math]::Max(1, $n - 1)
			$x = $t * $ww
			if ($listening) {
				$v = [Math]::Sin(($t * 11.0) + $ph) * 0.12
				$v += [Math]::Sin(($t * 27.0) - $ph) * 0.06
			} else {
				$v = [Math]::Sin(($t * 6.283185) + $ph * 0.35) * 0.04
			}
			$y = $mid - ($v * $ampScale)
			if ($y -lt 1.5) { $y = 1.5 }
			if ($y -gt ($hh - 1.5)) { $y = $hh - 1.5 }
			[void]$pts.Add((New-Object System.Windows.Point($x, $y)))
		}
	}
	try { $line.Points = $pts } catch {}
}

function Invoke-SpeakText {
	param(
		[string]$text,
		[int]$rate = 1,
		[bool]$wait = $false
	)
	if ([string]::IsNullOrWhiteSpace($text)) { return "ERROR: text is required." }
	return (Invoke-MBSpeak -Text $text -Rate $rate -Async (-not $wait))
}

function Add-MBInputHistory {
	param([string]$Text)
	if ([string]::IsNullOrWhiteSpace($Text)) { return }
	if ($script:MB.InputHistory.Count -gt 0) {
		$last = [string]$script:MB.InputHistory[$script:MB.InputHistory.Count - 1]
		if ($last -eq $Text) { return }
	}
	[void]$script:MB.InputHistory.Add($Text)
	while ($script:MB.InputHistory.Count -gt 80) {
		$script:MB.InputHistory.RemoveAt(0)
	}
}

function Read-MBUserInput {
	if (-not (Test-MBWpfActive)) {
		if ($script:MB.Wpf -and $script:MB.Wpf.ExitRequested) {
			return ([string][char]0x1B + 'WPF_CLOSE')
		}
		return ""
	}
	if ($script:MB.Wpf.ExitRequested) { return ([string][char]0x1B + 'WPF_CLOSE') }
	try { Sync-MBCwdFromWpf } catch {}
	# UI-injected slash commands
	try {
		$pend = [string]$script:MB.Wpf.PendingUiCommand
		if (-not [string]::IsNullOrWhiteSpace($pend)) {
			$script:MB.Wpf.PendingUiCommand = $null
			Add-MBInputHistory -Text $pend
			return $pend
		}
	} catch {}
	try { Refresh-MBWpfStickyFromSession } catch {}
	$result = Read-MBWpfUserInput
	if ($null -eq $result) { $result = "" }
	try { Sync-MBCwdFromWpf } catch {}
	# Re-check inject while we waited for input
	try {
		$pend2 = [string]$script:MB.Wpf.PendingUiCommand
		if (-not [string]::IsNullOrWhiteSpace($pend2) -and [string]::IsNullOrWhiteSpace($result)) {
			$script:MB.Wpf.PendingUiCommand = $null
			$result = $pend2
		}
	} catch {}
	Add-MBInputHistory -Text $result
	return $result
}

function Get-MBSessionFormat {
	param([string]$Path)
	# .md / .markdown = transcript markdown; everything else (incl. default) = JSON
	$ext = ''
	try { $ext = [System.IO.Path]::GetExtension([string]$Path) } catch { $ext = '' }
	if ($ext -match '^(?i)\.(md|markdown)$') { return 'md' }
	return 'json'
}

function Ensure-MBSessionScanType {
	if ('MiniBot.SessionScan' -as [type]) { return }
	# Background thread + Join(timeout) - never call Directory.GetFiles on the WPF UI thread.
	$code = @'
using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;

namespace MiniBot
{
	public static class SessionScan
	{
		public static List<string[]> ListSessions(string dir, int max, int timeoutMs)
		{
			List<string[]> empty = new List<string[]>();
			if (string.IsNullOrWhiteSpace(dir) || max < 1) return empty;
			if (!Directory.Exists(dir)) return empty;
			if (timeoutMs < 200) timeoutMs = 200;
			if (timeoutMs > 15000) timeoutMs = 15000;
			string[] files = null;
			try
			{
				// Dedicated thread so callers (incl. UI) can time out cleanly without Task/sync-context traps.
				Thread th = new Thread((ThreadStart)delegate {
					try { files = Directory.GetFiles(dir); } catch { files = null; }
				});
				th.IsBackground = true;
				th.Start();
				if (!th.Join(timeoutMs)) return empty;
			}
			catch { return empty; }
			if (files == null || files.Length == 0) return empty;
			List<Tuple<long, string[]>> acc = new List<Tuple<long, string[]>>();
			int i;
			for (i = 0; i < files.Length; i++)
			{
				string fp = files[i];
				string ext = null;
				try { ext = Path.GetExtension(fp); } catch { continue; }
				if (string.IsNullOrEmpty(ext)) continue;
				ext = ext.ToLowerInvariant();
				if (ext != ".json" && ext != ".md" && ext != ".markdown") continue;
				FileInfo fi = null;
				try { fi = new FileInfo(fp); if (!fi.Exists) continue; } catch { continue; }
				long n = fi.Length;
				string sz;
				if (n < 1024L) sz = n.ToString() + " B";
				else if (n < 1048576L) sz = (n / 1024.0).ToString("0.0") + " KB";
				else sz = (n / 1048576.0).ToString("0.0") + " MB";
				string type = ext.TrimStart('.');
				if (type == "markdown") type = "md";
				string mod = fi.LastWriteTime.ToString("yyyy-MM-dd HH:mm:ss");
				string line = mod + "  |  " + fi.Name + "  |  " + sz;
				acc.Add(Tuple.Create(fi.LastWriteTime.Ticks, new string[] { fi.Name, fi.FullName, mod, sz, type, line }));
			}
			acc.Sort(delegate(Tuple<long, string[]> a, Tuple<long, string[]> b) { return b.Item1.CompareTo(a.Item1); });
			List<string[]> result = new List<string[]>();
			int take = Math.Min(max, acc.Count);
			for (i = 0; i < take; i++) result.Add(acc[i].Item2);
			return result;
		}
	}
}
'@
	try {
		Add-Type -TypeDefinition $code -ReferencedAssemblies @('System.dll', 'System.Core.dll') -ErrorAction Stop
	} catch {
		try { Add-Type -TypeDefinition $code -ErrorAction Stop } catch { throw }
	}
}

function Suspend-MBWpfForModal {
	# Pause host UI timers/loops so modal dialogs (session picker) stay smooth.
	if (-not (Test-MBWpfActive)) { return }
	try { $script:MB.Wpf.ModalUi = $true } catch {}
	$d = $null
	try { $d = $script:MB.Wpf.Dispatcher } catch {}
	if (-not $d) { return }
	$act = {
		try {
			$t = $null
			try { $t = $script:MB.Wpf.PumpTimer } catch {}
			if ($null -ne $t) {
				try { $script:MB.Wpf.PumpWasRunning = [bool]$t.IsEnabled } catch { $script:MB.Wpf.PumpWasRunning = $true }
				try { if ($t.IsEnabled) { $t.Stop() } } catch {}
			} else {
				try { $script:MB.Wpf.PumpWasRunning = $true } catch {}
			}
		} catch {}
		try { Stop-MBAnimation } catch {}
	}.GetNewClosure()
	try {
		if ($d.CheckAccess()) { & $act }
		else { [void]$d.Invoke([Action]$act, [System.Windows.Threading.DispatcherPriority]::Send) }
	} catch {
		try { & $act } catch {}
	}
}

function Resume-MBWpfForModal {
	# Restart host UI after modal closes (Open / Cancel / X).
	if (-not $script:MB.Wpf) { return }
	try { $script:MB.Wpf.ModalUi = $false } catch {}
	$d = $null
	try { $d = $script:MB.Wpf.Dispatcher } catch {}
	if (-not $d) { return }
	$act = {
		try {
			$want = $true
			try { $want = [bool]$script:MB.Wpf.PumpWasRunning } catch { $want = $true }
			$t = $null
			try { $t = $script:MB.Wpf.PumpTimer } catch {}
			if ($null -ne $t -and $want -and -not $t.IsEnabled) {
				$t.Start()
			}
		} catch {}
	}.GetNewClosure()
	try {
		if ($d.CheckAccess()) { & $act }
		else { [void]$d.Invoke([Action]$act, [System.Windows.Threading.DispatcherPriority]::Normal) }
	} catch {
		try {
			$t = $script:MB.Wpf.PumpTimer
			if ($t -and -not $t.IsEnabled) { $t.Start() }
		} catch {}
	}
}

function Get-MBSessionFileRows {
	param([string]$Dir, [int]$Max = 400, [int]$TimeoutMs = 2000)
	# Timed scan only - bare Directory.GetFiles freezes the UI on Desktop/OneDrive.
	$rows = New-Object System.Collections.ArrayList
	if ([string]::IsNullOrWhiteSpace($Dir)) { return @() }
	try { Ensure-MBSessionScanType } catch {}
	try {
		if ('MiniBot.SessionScan' -as [type]) {
			$found = [MiniBot.SessionScan]::ListSessions([string]$Dir, [int]$Max, [int]$TimeoutMs)
			if ($found) {
				foreach ($r in @($found)) {
					if ($null -eq $r -or $r.Length -lt 6) { continue }
					[void]$rows.Add(@{
						Name = [string]$r[0]; Path = [string]$r[1]; Modified = [string]$r[2]
						Size = [string]$r[3]; Type = [string]$r[4]; Line = [string]$r[5]
					})
				}
			}
		}
	} catch {}
	return @($rows)
}

function Hide-MBSessionPickerOverlay {
	if (-not $script:MB.Wpf) { return }
	$W = $script:MB.Wpf
	$d = $W.Dispatcher
	if (-not $d) { return }
	$hide = {
		try {
			if ($W.SessionPickerOverlay) {
				$W.SessionPickerOverlay.Visibility = [System.Windows.Visibility]::Collapsed
				$W.SessionPickerOverlay.IsHitTestVisible = $false
			}
			if ($W.SessionPickerOk) {
				try { $W.SessionPickerOk.IsDefault = $false } catch {}
			}
			if ($W.SessionPickerCancel) {
				try { $W.SessionPickerCancel.IsCancel = $false } catch {}
			}
		} catch {}
	}.GetNewClosure()
	try {
		# Sync hide when possible so the popup cannot stick around after Save/Load.
		if ($d.CheckAccess()) { & $hide }
		else { [void]$d.Invoke([Action]$hide, [System.Windows.Threading.DispatcherPriority]::Send) }
	} catch {
		try { [void]$d.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Send, [Action]$hide) } catch {}
	}
}

function Show-MBSessionFilePicker {
	param(
		[ValidateSet('Open', 'Save')]
		[string]$Mode = 'Open',
		[string]$Title = '',
		[string]$FileName = '',
		[string]$InitialDirectory = ''
	)
	# Simple model:
	#  1) scan files on agent thread (timed C# helper - never touches UI)
	#  2) BeginInvoke paint + show overlay (never Dispatcher.Invoke - no UI deadlock)
	#  3) WaitOne for Save/Open/Cancel
	$agentTitle = try { Get-MBAgentDisplayTitle } catch { '[{0}-Agent]' -f $(if ($AgentName) { $AgentName } else { 'MiniBot' }) }
	if ([string]::IsNullOrWhiteSpace($Title)) {
		$Title = if ($Mode -eq 'Save') { ("{0} Save session" -f $agentTitle) } else { ("{0} Load session" -f $agentTitle) }
	}
	if ([string]::IsNullOrWhiteSpace($FileName) -and $Mode -eq 'Save') {
		$safe = try { [string]$AgentName } catch { 'MiniBot' }
		if ([string]::IsNullOrWhiteSpace($safe)) { $safe = 'MiniBot' }
		$FileName = ("{0}-session-{1:yyyyMMdd-HHmmss}.json" -f $safe, (Get-Date))
	}
	if ([string]::IsNullOrWhiteSpace($InitialDirectory)) {
		# Prefer Documents over Desktop (OneDrive Desktop listing is a common hang source)
		try { $InitialDirectory = [Environment]::GetFolderPath('MyDocuments') } catch { $InitialDirectory = '' }
		if ([string]::IsNullOrWhiteSpace($InitialDirectory)) {
			try { $InitialDirectory = [string]$env:USERPROFILE } catch { $InitialDirectory = [string]$env:TEMP }
		}
	}
	if ([string]::IsNullOrWhiteSpace($InitialDirectory)) { $InitialDirectory = [string]$env:TEMP }

	if (Test-MBWpfActive) {
		$W = $script:MB.Wpf
		# Re-resolve overlay if bag pointer was lost
		if (-not $W.SessionPickerOverlay -and $W.Window) {
			try { $W.SessionPickerOverlay = $W.Window.FindName('SessionPickerOverlay') } catch {}
			try { if (-not $W.SessionPickerList) { $W.SessionPickerList = $W.Window.FindName('SessionPickerList') } } catch {}
			try { if (-not $W.SessionPickerPath) { $W.SessionPickerPath = $W.Window.FindName('SessionPickerPath') } } catch {}
			try { if (-not $W.SessionPickerName) { $W.SessionPickerName = $W.Window.FindName('SessionPickerName') } } catch {}
			try { if (-not $W.SessionPickerOk) { $W.SessionPickerOk = $W.Window.FindName('SessionPickerOk') } } catch {}
			try { if (-not $W.SessionPickerCancel) { $W.SessionPickerCancel = $W.Window.FindName('SessionPickerCancel') } } catch {}
			try { if (-not $W.SessionPickerTitle) { $W.SessionPickerTitle = $W.Window.FindName('SessionPickerTitle') } } catch {}
			try { if (-not $W.SessionPickerStatus) { $W.SessionPickerStatus = $W.Window.FindName('SessionPickerStatus') } } catch {}
		}
	}
	if (Test-MBWpfActive -and $script:MB.Wpf.SessionPickerOverlay) {
		$W = $script:MB.Wpf
		$d = $null
		try { $d = $W.Dispatcher } catch { $d = $null }
		if (-not $d) { return $null }

		try { Ensure-MBSessionScanType } catch {}
		$W.SessionPickerResult = $null
		$W.SessionPickerMode = [string]$Mode
		try { [void]$W.SessionPickerWait.Reset() } catch {
			$W.SessionPickerWait = New-Object System.Threading.ManualResetEvent $false
		}

		$modeL = [string]$Mode
		$titleL = [string]$Title
		$fileL = [string]$FileName
		$initL = [string]$InitialDirectory

		# List files on agent thread (timed). UI only paints.
		$preRows = @()
		try { $preRows = @(Get-MBSessionFileRows -Dir $initL -Max 400 -TimeoutMs 1500) } catch { $preRows = @() }

		$paint = {
			try {
				if ($W.SessionPickerTitle) { $W.SessionPickerTitle.Text = $titleL }
				if ($W.SessionPickerPath) { $W.SessionPickerPath.Text = $initL }
				if ($W.SessionPickerName) {
					$W.SessionPickerName.Text = $(if ($modeL -eq 'Save') { $fileL } else { '' })
					$W.SessionPickerName.IsReadOnly = ($modeL -ne 'Save')
				}
				if ($W.SessionPickerOk) {
					$W.SessionPickerOk.Content = $(if ($modeL -eq 'Save') { 'Save' } else { 'Open' })
					try { $W.SessionPickerOk.IsDefault = $true } catch {}
				}
				if ($W.SessionPickerCancel) {
					try { $W.SessionPickerCancel.IsCancel = $true } catch {}
				}
				$W.SessionPickerRows = New-Object System.Collections.ArrayList
				if ($W.SessionPickerList) {
					$W.SessionPickerList.Items.Clear()
					if (@($preRows).Count -eq 0) {
						[void]$W.SessionPickerList.Items.Add('(none)')
						if ($W.SessionPickerStatus) {
							$W.SessionPickerStatus.Text = 'No .json/.md listed - type a name (or Go to rescan)'
							try {
								$bc = New-Object System.Windows.Media.BrushConverter
								$W.SessionPickerStatus.Foreground = $bc.ConvertFromString('#6A6A76')
							} catch {}
						}
					} else {
						foreach ($r in @($preRows)) {
							[void]$W.SessionPickerRows.Add($r)
							try { [void]$W.SessionPickerList.Items.Add([string]$r.Line) } catch {
								try { [void]$W.SessionPickerList.Items.Add([string]$r['Line']) } catch {}
							}
						}
						if ($W.SessionPickerStatus) {
							$W.SessionPickerStatus.Text = ('{0} session(s)  |  newest first' -f $W.SessionPickerRows.Count)
							try {
								$bc = New-Object System.Windows.Media.BrushConverter
								$W.SessionPickerStatus.Foreground = $bc.ConvertFromString('#6A6A76')
							} catch {}
						}
					}
				}
				# Show last so a paint error above cannot skip visibility
				if ($W.SessionPickerOverlay) {
					$W.SessionPickerOverlay.Visibility = [System.Windows.Visibility]::Visible
					$W.SessionPickerOverlay.Opacity = 1.0
					$W.SessionPickerOverlay.IsHitTestVisible = $true
					try { [System.Windows.Controls.Panel]::SetZIndex($W.SessionPickerOverlay, 999) } catch {}
				}
				try { if ($W.Window) { [void]$W.Window.Activate() } } catch {}
				try {
					if ($modeL -eq 'Save' -and $W.SessionPickerName) {
						[void]$W.SessionPickerName.Focus()
						try { $W.SessionPickerName.SelectAll() } catch {}
					} elseif ($W.SessionPickerList) {
						[void]$W.SessionPickerList.Focus()
					}
				} catch {}
			} catch {
				try { Write-MBDebugLog -Step 'SESSION_PICKER_PAINT_FAIL' -Detail $_.Exception.Message } catch {}
			}
		}.GetNewClosure()

		# Same pattern as Auth overlay (works): synchronous Invoke for a light paint.
		# Scan already finished on agent thread - this Invoke is instant.
		try {
			if ($d.CheckAccess()) {
				& $paint
			} else {
				[void]$d.Invoke([Action]$paint, [System.Windows.Threading.DispatcherPriority]::Normal)
			}
		} catch {
			try { Write-MBDebugLog -Step 'SESSION_PICKER_INVOKE_FAIL' -Detail $_.Exception.Message } catch {}
			try { & $paint } catch {}
		}

		try {
			while ($true) {
				if ($W.ExitRequested) { return $null }
				if ($W.SessionPickerWait.WaitOne(50)) { break }
			}
			$path = $null
			try { $path = [string]$W.SessionPickerResult } catch { $path = $null }
			if ([string]::IsNullOrWhiteSpace($path)) { return $null }
			return $path
		} finally {
			try { Hide-MBSessionPickerOverlay } catch {}
			try { $script:MB.Wpf.ModalUi = $false } catch {}
		}
	}

	# Fallback: STA WinForms common dialog
	$filter = 'MiniBot session (*.json)|*.json|Markdown transcript (*.md;*.markdown)|*.md;*.markdown|All files (*.*)|*.*'
	$rs = $null; $ps = $null
	try {
		try { Suspend-MBWpfForModal } catch { try { if ($script:MB.Wpf) { $script:MB.Wpf.ModalUi = $true } } catch {} }
		$rs = [runspacefactory]::CreateRunspace()
		$rs.ApartmentState = 'STA'
		$rs.ThreadOptions = 'ReuseThread'
		$rs.Open()
		$ps = [powershell]::Create()
		$ps.Runspace = $rs
		[void]$ps.AddScript({
			param($Mode, $Title, $FileName, $InitDir, $Filter)
			Add-Type -AssemblyName System.Windows.Forms
			if ($Mode -eq 'Save') {
				$dlg = New-Object System.Windows.Forms.SaveFileDialog
				$dlg.FileName = $FileName
				$dlg.OverwritePrompt = $true
				$dlg.AddExtension = $true
				$dlg.CheckPathExists = $true
			} else {
				$dlg = New-Object System.Windows.Forms.OpenFileDialog
				$dlg.CheckFileExists = $true
				$dlg.Multiselect = $false
			}
			$dlg.Title = $Title
			$dlg.Filter = $Filter
			$dlg.FilterIndex = 1
			$dlg.DefaultExt = 'json'
			$dlg.RestoreDirectory = $true
			if ($InitDir -and (Test-Path -LiteralPath $InitDir)) { $dlg.InitialDirectory = $InitDir }
			if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { return [string]$dlg.FileName }
			return $null
		})
		[void]$ps.AddArgument([string]$Mode)
		[void]$ps.AddArgument([string]$Title)
		[void]$ps.AddArgument([string]$FileName)
		[void]$ps.AddArgument([string]$InitialDirectory)
		[void]$ps.AddArgument([string]$filter)
		$out = $ps.Invoke()
		if ($ps.HadErrors) {
			$errMsgs = @($ps.Streams.Error | ForEach-Object { "$_" }) -join '; '
			if ($errMsgs) { throw $errMsgs }
		}
		$path = $null
		if ($out -and @($out).Count -gt 0) { $path = [string]@($out)[-1] }
		if ([string]::IsNullOrWhiteSpace($path) -or $path -eq 'null') { return $null }
		return $path
	} catch {
		throw "File picker failed: $($_.Exception.Message)"
	} finally {
		try { Resume-MBWpfForModal } catch { try { if ($script:MB.Wpf) { $script:MB.Wpf.ModalUi = $false } } catch {} }
		try { if ($ps) { $ps.Dispose() } } catch {}
		try { if ($rs) { $rs.Close(); $rs.Dispose() } } catch {}
	}
}

function Save-MBSessionJson {
	param([array]$Messages, [string]$Path)
	$Path = Resolve-MBPath $Path
	$activeTools = @('core')
	try {
		$activeTools = @(
			@($script:MB.ActiveToolGroups) |
				ForEach-Object { ([string]$_).Trim().ToLowerInvariant() } |
				Where-Object { $_ }
		)
		if ($activeTools.Count -eq 0) { $activeTools = @('core') }
	} catch { $activeTools = @('core') }
	# Flatten messages first - raw ConvertTo-Json -Depth 30 on live PSObjects can peg CPU after Save.
	$plainMsgs = New-Object System.Collections.ArrayList
	foreach ($m in @($Messages)) {
		if ($null -eq $m) { continue }
		try {
			[void]$plainMsgs.Add((Convert-MBJsonReady -Object $m -Depth 14))
		} catch {
			try {
				[void]$plainMsgs.Add(@{
					role    = [string](Get-MBProp $m 'role')
					content = [string](Get-MBProp $m 'content')
				})
			} catch {}
		}
	}
	$payload = [ordered]@{
		version     = [string]$Version
		savedAt     = (Get-Date).ToString('o')
		model       = (Get-MBActiveModel)
		baseUrl     = [string]$BaseUrl
		cwd         = [string]$script:MB.WorkingDir
		messages    = @($plainMsgs.ToArray())
		tools       = @($activeTools)
		toolProfile = [string]$script:MB.ToolProfile
		context     = [ordered]@{
			windowTokens = [int]$script:MB.ContextWindow
			lastPct      = $script:MB.LastCtxPct
			lastTokens   = $script:MB.LastCtxTokens
			compactions  = [int]$script:MB.CompactionCount
		}
		sticky      = [ordered]@{
			notes    = @($script:MB.StickyNotes | ForEach-Object { [string]$_ })
			findings = @($script:MB.StickyFindings | ForEach-Object { [string]$_ })
			extra    = [string]$script:MB.StickyExtra
			taskboard = $(
				try {
					$tb = Get-MBTaskBoardObject
					$tbRows = New-Object System.Collections.ArrayList
					foreach ($trit in (Get-MBTaskBoardItemCollection)) {
						if ($null -eq $trit) { continue }
						[void]$tbRows.Add([ordered]@{
							id     = [string](Get-MBTaskBoardItemField -Item $trit -Name 'Id')
							title  = [string](Get-MBTaskBoardItemField -Item $trit -Name 'Title')
							status = [string](Get-MBTaskBoardItemField -Item $trit -Name 'Status')
							note   = [string](Get-MBTaskBoardItemField -Item $trit -Name 'Note')
						})
					}
					[ordered]@{
						goal  = [string]$tb.Goal
						items = @($tbRows.ToArray())
					}
				} catch { $null }
			)
		}
	}
	$json = $null
	try {
		$safe = Convert-MBJsonReady -Object $payload -Depth 18
		$json = ConvertTo-Json -InputObject $safe -Depth 16 -Compress
	} catch {
		try { $json = ConvertTo-MBJson $payload -Depth 12 } catch {
			throw "Session JSON serialize failed: $($_.Exception.Message)"
		}
	}
	if ([string]::IsNullOrWhiteSpace($json)) { throw 'Session JSON serialize produced empty output' }
	$dir = [System.IO.Path]::GetDirectoryName($Path)
	if ($dir -and -not [System.IO.Directory]::Exists($dir)) {
		[void][System.IO.Directory]::CreateDirectory($dir)
	}
	$utf8NoBom = New-Object System.Text.UTF8Encoding $false
	[System.IO.File]::WriteAllText($Path, $json, $utf8NoBom)
	return $Path
}

function Save-MBSessionMarkdown {
	param([array]$Messages, [string]$Path)
	$Path = Resolve-MBPath $Path
	$sb = New-Object System.Text.StringBuilder
	[void]$sb.AppendLine("# MiniBot Transcript")
	[void]$sb.AppendLine(("Model: {0}" -f (Get-MBActiveModel)))
	[void]$sb.AppendLine("Agent: $AgentName")
	[void]$sb.AppendLine("Cwd: $($script:MB.WorkingDir)")
	$toolsList = @('core')
	try {
		$toolsList = @(
			@($script:MB.ActiveToolGroups) |
				ForEach-Object { ([string]$_).Trim().ToLowerInvariant() } |
				Where-Object { $_ }
		)
		if ($toolsList.Count -eq 0) { $toolsList = @('core') }
		if ($toolsList -notcontains 'core') { $toolsList = @('core') + $toolsList }
	} catch { $toolsList = @('core') }
	[void]$sb.AppendLine(('Tools: {0}' -f ($toolsList -join ', ')))
	try {
		$tp = [string]$script:MB.ToolProfile
		if (-not [string]::IsNullOrWhiteSpace($tp)) {
			[void]$sb.AppendLine(('ToolProfile: {0}' -f $tp))
		}
	} catch {}
	[void]$sb.AppendLine("Saved: $((Get-Date).ToString('o'))")
	[void]$sb.AppendLine("")
	foreach ($m in $Messages) {
		if ($m.role -eq 'system') { continue }
		if ($m.role -eq 'user') {
			[void]$sb.AppendLine("## You")
			[void]$sb.AppendLine([string]$m.content)
		} elseif ($m.role -eq 'assistant') {
			[void]$sb.AppendLine("## $AgentName")
			if ($m.content) { [void]$sb.AppendLine([string]$m.content) }
			if ($m.tool_calls) {
				foreach ($tc in @($m.tool_calls)) {
					$fn = Get-MBProp $tc 'function'
					$tn = if ($fn) { [string](Get-MBProp $fn 'name') } else { '' }
					$ta = if ($fn) { [string](Get-MBProp $fn 'arguments') } else { '' }
					if (-not $tn) { $tn = [string](Get-MBProp $tc 'name') }
					[void]$sb.AppendLine(('- tool: {0} `{1}`' -f $tn, ($ta -replace '`', "'")))
				}
			}
		} elseif ($m.role -eq 'tool') {
			$tn = [string](Get-MBProp $m 'name')
			if ($tn) {
				[void]$sb.AppendLine("### tool result ($tn)")
			} else {
				[void]$sb.AppendLine("### tool result")
			}
			$c = [string]$m.content
			if ($c.Length -gt 8000) { $c = $c.Substring(0, 8000) + "..." }
			[void]$sb.AppendLine('```')
			[void]$sb.AppendLine($c)
			[void]$sb.AppendLine('```')
		}
		[void]$sb.AppendLine("")
	}
	$utf8NoBom = New-Object System.Text.UTF8Encoding $false
	[System.IO.File]::WriteAllText($Path, $sb.ToString(), $utf8NoBom)
	return $Path
}

function Save-MBSession {
	param([array]$Messages, [string]$Path)
	if ([string]::IsNullOrWhiteSpace($Path)) {
		$desktop = [Environment]::GetFolderPath('Desktop')
		$Path = Join-Path $desktop ("MiniBot-session-{0:yyyyMMdd-HHmmss}.json" -f (Get-Date))
	}
	$fmt = Get-MBSessionFormat -Path $Path
	if ($fmt -eq 'md') {
		return (Save-MBSessionMarkdown -Messages $Messages -Path $Path)
	}
	return (Save-MBSessionJson -Messages $Messages -Path $Path)
}

function Load-MBSessionJson {
	param(
		[string]$Path,
		[switch]$NoPaint
	)
	$lp = Resolve-MBPath $Path
	if (-not (Test-Path -LiteralPath $lp)) { throw "File not found: $lp" }
	$obj = Get-Content -LiteralPath $lp -Raw -Encoding UTF8 | ConvertFrom-Json
	if ($obj.sticky) {
		Clear-MBSticky
		foreach ($n in @($obj.sticky.notes)) {
			if ($n) { [void]$script:MB.StickyNotes.Add([string]$n) }
		}
		foreach ($f in @($obj.sticky.findings)) {
			if ($f) { [void]$script:MB.StickyFindings.Add([string]$f) }
		}
		if ($obj.sticky.extra) { $script:MB.StickyExtra = [string]$obj.sticky.extra }
		try {
			$tbIn = $null
			try { $tbIn = $obj.sticky.taskboard } catch { $tbIn = $null }
			if ($tbIn) {
				$g = ''
				try { $g = [string]$tbIn.goal } catch {}
				$its = New-Object System.Collections.ArrayList
				foreach ($it in @($tbIn.items)) {
					if ($null -eq $it) { continue }
					[void]$its.Add([ordered]@{
						Id     = $(try { [string]$it.id } catch { '' })
						Title  = $(try { [string]$it.title } catch { '' })
						Status = $(try { [string]$it.status } catch { 'pending' })
						Note   = $(try { [string]$it.note } catch { '' })
					})
				}
				# ArrayList keeps count=1 as collection (Object[] unwraps in PS 5.1)
				$storeItems = New-Object System.Collections.ArrayList
				foreach ($row in $its) { if ($null -ne $row) { [void]$storeItems.Add($row) } }
				$script:MB.TaskBoard = [ordered]@{
					Goal    = $g
					Items   = $storeItems
					Updated = (Get-Date).ToString('o')
				}
			}
		} catch {}
	}
	if ($obj.tools) {
		try { $null = Set-MBActiveToolGroupsFromList -Groups @($obj.tools) } catch {}
	}
	if ($obj.toolProfile) {
		try {
			$tp = [string]$obj.toolProfile
			if ($tp -match '^(?i)core|full$') { $script:MB.ToolProfile = $tp.ToLowerInvariant() }
		} catch {}
	}
	$rawMsgs = @($obj.messages)
	$script:Messages = @(Repair-MBMessagesEncoding -Messages @(Sync-MBSystemMessages -Messages $rawMsgs))
	if ($obj.cwd) {
		try { Invoke-SetWorkingDirectory -path $obj.cwd | Out-Null } catch {}
	}
	# Last user for /retry
	try {
		for ($i = $rawMsgs.Count - 1; $i -ge 0; $i--) {
			if ([string](Get-MBProp $rawMsgs[$i] 'role') -eq 'user') {
				$script:LastUserMessage = [string](Get-MBProp $rawMsgs[$i] 'content')
				break
			}
		}
	} catch {}
	try { Sync-MBPromptAfterToolGroups } catch {}
	if (-not $NoPaint) {
		$paint = New-Object System.Collections.ArrayList
		foreach ($m in $rawMsgs) {
			$r = [string](Get-MBProp $m 'role')
			if ($r -and $r -ne 'system') { [void]$paint.Add($m) }
		}
		try { Show-MBImportedMessages -Messages @($paint) -Label 'loaded' } catch {}
	}
	try { Refresh-MBWpfStickyFromSession } catch {}
	try {
		if (Test-MBTaskBoardHasOpen) {
			Update-MBWpfTaskBoardSticky -Action 'status'
		} else {
			Update-MBWpfTaskBoardSticky -Action 'clear'
		}
	} catch {}
	return [pscustomobject]@{
		Path   = $lp
		Format = 'json'
		Count  = @($script:Messages).Count
		Tools  = @($script:MB.ActiveToolGroups)
		Cwd    = $script:MB.WorkingDir
	}
}

function Load-MBSession {
	param(
		[Parameter(Mandatory = $true)][string]$Path,
		[switch]$Append,
		[switch]$NoPaint
	)
	$lp = Resolve-MBPath $Path
	if (-not (Test-Path -LiteralPath $lp)) { throw "File not found: $lp" }
	$fmt = Get-MBSessionFormat -Path $lp
	# Sniff: .md by extension, else if file starts with # MiniBot Transcript treat as md
	if ($fmt -ne 'md') {
		try {
			$head = Get-Content -LiteralPath $lp -TotalCount 3 -ErrorAction SilentlyContinue
			$joined = ($head -join "`n")
			if ($joined -match '(?i)MiniBot\s+Transcript') { $fmt = 'md' }
		} catch {}
	}
	if ($fmt -eq 'md') {
		$r = Import-MBTranscript -Path $lp -Append:$Append -NoPaint:$NoPaint
		return [pscustomobject]@{
			Path   = $r.Path
			Format = 'md'
			Count  = $r.Total
			Turns  = $r.Count
			Tools  = @($r.Tools)
			Cwd    = $r.Cwd
			Model  = $r.Model
			Appended = [bool]$r.Appended
		}
	}
	if ($Append) {
		# JSON append: merge message lists after load of sticky/tools from file would clobber;
		# for simplicity, JSON load always replaces (markdown supports append).
		throw "Append is only supported for .md transcripts. Use /load path.md with append, or /load file.json to replace."
	}
	return (Load-MBSessionJson -Path $lp -NoPaint:$NoPaint)
}

function ConvertFrom-MBTranscriptMarkdown {
	param(
		[Parameter(Mandatory = $true)][string]$Text
	)
	# Parse MiniBot transcript markdown into chat messages for context continue.
	$raw = [string]$Text
	if ($raw.Length -gt 0 -and [int][char]$raw[0] -eq 0xFEFF) {
		$raw = $raw.Substring(1)
	}
	$raw = $raw -replace "`r`n", "`n" -replace "`r", "`n"
	$lines = @($raw -split "`n", -1)

	$agent = [string]$AgentName
	$metaModel = $null
	$metaCwd = $null
	$metaAgent = $null
	$metaTools = @()
	$metaToolProfile = $null

	$out = New-Object System.Collections.ArrayList
	$role = $null          # user | assistant | tool
	$body = New-Object System.Collections.ArrayList
	$toolCalls = New-Object System.Collections.ArrayList
	$toolName = ''
	$inFence = $false
	$tcId = 0

	foreach ($line in $lines) {
		# Meta (before first message section)
		if (-not $role -and $line -match '^(?i)Model:\s*(.+)$') {
			$metaModel = $Matches[1].Trim(); continue
		}
		if (-not $role -and $line -match '^(?i)Agent:\s*(.+)$') {
			$metaAgent = $Matches[1].Trim()
			if ($metaAgent) { $agent = $metaAgent }
			continue
		}
		if (-not $role -and $line -match '^(?i)Cwd:\s*(.+)$') {
			$metaCwd = $Matches[1].Trim(); continue
		}
		if (-not $role -and $line -match '^(?i)Tools?:\s*(.+)$') {
			$metaTools = @(
				$Matches[1] -split '[,;\s]+' |
					ForEach-Object { $_.Trim().ToLowerInvariant() } |
					Where-Object { $_ }
			)
			continue
		}
		if (-not $role -and $line -match '^(?i)ToolProfile:\s*(.+)$') {
			$metaToolProfile = $Matches[1].Trim().ToLowerInvariant(); continue
		}
		if (-not $role -and $line -match '^(?i)Saved:\s*') { continue }
		if ($line -match '^(?i)#\s+MiniBot\s+Transcript\s*$') { continue }

		$isHeader = $false
		$nextRole = $null
		$nextToolName = ''

		if (-not $inFence -and $line -match '^(?i)##\s+You\s*$') {
			$isHeader = $true; $nextRole = 'user'
		} elseif (-not $inFence -and $line -match '^(?i)##\s+User\s*$') {
			$isHeader = $true; $nextRole = 'user'
		} elseif (-not $inFence -and $line -match '^(?i)##\s+(Assistant|Agent|MiniBot)\s*$') {
			$isHeader = $true; $nextRole = 'assistant'
		} elseif (-not $inFence -and $line -match '^(?i)###\s+tool\s+result(?:\s*\(([^)]+)\))?\s*$') {
			$isHeader = $true; $nextRole = 'tool'
			if ($Matches[1]) { $nextToolName = $Matches[1].Trim() }
		} elseif (-not $inFence -and $line -match '^(?i)##\s+(.+?)\s*$') {
			$hdr = $Matches[1].Trim()
			$hdrBare = $hdr -replace '^\[|\]$', '' -replace '-Agent$', ''
			$isAgent = $false
			if ($agent -and ($hdr -eq $agent -or $hdrBare -eq $agent)) { $isAgent = $true }
			elseif ($hdr -match '(?i)agent$') { $isAgent = $true }
			if ($isAgent) {
				$isHeader = $true; $nextRole = 'assistant'
			}
		}

		if ($isHeader) {
			# flush current section
			if ($role) {
				$text = (($body | ForEach-Object { $_ }) -join "`n").TrimEnd()
				if ($text.StartsWith("`n")) { $text = $text.Substring(1) }
				if ($role -eq 'user') {
					if ($text.Length -gt 0) {
						[void]$out.Add(@{ role = 'user'; content = (Sanitize-MBText -Text $text) })
					}
				} elseif ($role -eq 'assistant') {
					if ($text.Length -gt 0 -or $toolCalls.Count -gt 0) {
						$msg = @{ role = 'assistant'; content = (Sanitize-MBText -Text $text) }
						if ($toolCalls.Count -gt 0) { $msg['tool_calls'] = @($toolCalls.ToArray()) }
						[void]$out.Add($msg)
					}
				} elseif ($role -eq 'tool') {
					if ($text.Length -gt 0) {
						$tcId++
						$tm = @{
							role         = 'tool'
							content      = (Sanitize-MBText -Text $text.Trim())
							tool_call_id = ('import_tool_{0}' -f $tcId)
						}
						if ($toolName) { $tm['name'] = $toolName }
						[void]$out.Add($tm)
					}
				}
			}
			$role = $nextRole
			$body = New-Object System.Collections.ArrayList
			$toolCalls = New-Object System.Collections.ArrayList
			$toolName = $nextToolName
			$inFence = $false
			continue
		}

		# Tool call lines under assistant
		if ($role -eq 'assistant' -and -not $inFence -and $line -match '^\s*-\s*tool:\s*(\S+)\s+`([^`]*)`\s*$') {
			$tcId++
			[void]$toolCalls.Add(@{
				id       = ('import_call_{0}' -f $tcId)
				type     = 'function'
				function = @{ name = $Matches[1]; arguments = $Matches[2] }
			})
			continue
		}
		if ($role -eq 'assistant' -and -not $inFence -and $line -match '^\s*-\s*tool:\s*(\S+)\s*$') {
			$tcId++
			[void]$toolCalls.Add(@{
				id       = ('import_call_{0}' -f $tcId)
				type     = 'function'
				function = @{ name = $Matches[1]; arguments = '{}' }
			})
			continue
		}

		# Fenced code in tool results: drop fence lines, keep content
		if ($line -match '^```') {
			$inFence = -not $inFence
			if ($role -eq 'tool') { continue }
			if ($role) { [void]$body.Add($line) }
			continue
		}

		if ($role) { [void]$body.Add($line) }
	}

	# final flush
	if ($role) {
		$text = (($body | ForEach-Object { $_ }) -join "`n").TrimEnd()
		if ($text.StartsWith("`n")) { $text = $text.Substring(1) }
		if ($role -eq 'user' -and $text.Length -gt 0) {
			[void]$out.Add(@{ role = 'user'; content = (Sanitize-MBText -Text $text) })
		} elseif ($role -eq 'assistant' -and ($text.Length -gt 0 -or $toolCalls.Count -gt 0)) {
			$msg = @{ role = 'assistant'; content = (Sanitize-MBText -Text $text) }
			if ($toolCalls.Count -gt 0) { $msg['tool_calls'] = @($toolCalls.ToArray()) }
			[void]$out.Add($msg)
		} elseif ($role -eq 'tool' -and $text.Length -gt 0) {
			$tcId++
			$tm = @{
				role         = 'tool'
				content      = (Sanitize-MBText -Text $text.Trim())
				tool_call_id = ('import_tool_{0}' -f $tcId)
			}
			if ($toolName) { $tm['name'] = $toolName }
			[void]$out.Add($tm)
		}
	}

	return [pscustomobject]@{
		Messages    = @($out.ToArray())
		Model       = $metaModel
		Agent       = $metaAgent
		Cwd         = $metaCwd
		Tools       = @($metaTools)
		ToolProfile = $metaToolProfile
		Count       = $out.Count
	}
}

function Set-MBActiveToolGroupsFromList {
	param(
		[string[]]$Groups,
		[switch]$Merge
	)
	# Restore ActiveToolGroups from transcript meta (or merge when appending).
	$order = @(Get-MBToolGroupOrder)
	$want = New-Object System.Collections.ArrayList
	[void]$want.Add('core')
	foreach ($g in @($Groups)) {
		$gl = ([string]$g).Trim().ToLowerInvariant()
		if ([string]::IsNullOrWhiteSpace($gl)) { continue }
		if ($gl -in @('full', 'all', 'everything')) {
			foreach ($n in $order) {
				if (-not ($want -contains $n)) { [void]$want.Add($n) }
			}
			continue
		}
		$resolved = $null
		try { $resolved = Resolve-MBToolGroupName -Group $gl } catch { $resolved = $null }
		if (-not $resolved) { $resolved = $gl }
		if ($resolved -in @('full', 'all')) {
			foreach ($n in $order) {
				if (-not ($want -contains $n)) { [void]$want.Add($n) }
			}
			continue
		}
		if ($resolved -eq 'core') { continue }
		if ($script:MBToolCatalog -and $script:MBToolCatalog.Contains($resolved)) {
			if (-not ($want -contains $resolved)) { [void]$want.Add($resolved) }
		}
	}
	if ($Merge) {
		foreach ($g in @($script:MB.ActiveToolGroups)) {
			$gl = ([string]$g).Trim().ToLowerInvariant()
			if ($gl -and -not ($want -contains $gl)) { [void]$want.Add($gl) }
		}
	}
	if (-not $script:MB.ActiveToolGroups) {
		$script:MB.ActiveToolGroups = New-Object System.Collections.ArrayList
	}
	$script:MB.ActiveToolGroups.Clear()
	foreach ($g in @($want)) {
		[void]$script:MB.ActiveToolGroups.Add($g)
	}
	try { Sync-MBPromptAfterToolGroups } catch {}
	return @($script:MB.ActiveToolGroups)
}

function Show-MBImportedMessages {
	param(
		[array]$Messages,
		[string]$Label = 'loaded'
	)
	# Console replay only: user turns + assistant text (what the operator saw).
	# Tool JSON / tool results stay in $script:Messages for the model - not painted.
	if (-not $Messages -or $Messages.Count -eq 0) { return }
	try {
		Write-Host ""
		Write-MBRule -Label $Label
	} catch {
		Write-Host ""
	}
	foreach ($m in @($Messages)) {
		$r = [string](Get-MBProp $m 'role')
		if ($r -eq 'system' -or $r -eq 'tool') { continue }
		$c = [string](Get-MBProp $m 'content')
		if ($null -eq $c) { $c = '' }
		if ($r -eq 'user') {
			try { Write-MBUserMessage -Text $c } catch {
				Write-Host "[user]" -ForegroundColor Cyan
				Write-Host $c -ForegroundColor Gray
			}
			continue
		}
		if ($r -ne 'assistant') { continue }
		# Skip pure tool-call turns with no visible reply text
		$hasText = -not [string]::IsNullOrWhiteSpace($c)
		if (-not $hasText) { continue }
		try {
			try { Reset-MBMdStream } catch {}
			Write-MBBrand -NoNewline
			Write-Host ""
			if (Test-MBWpfActive) {
				$norm = $c -replace "`r`n", "`n" -replace "`r", "`n"
				if (-not $norm.EndsWith("`n")) { $norm += "`n" }
				$pos = 0
				$len = $norm.Length
				$chunk = 480
				while ($pos -lt $len) {
					$n = [math]::Min($chunk, $len - $pos)
					$piece = $norm.Substring($pos, $n)
					$pos += $n
					if ($pos -lt $len) {
						$nl = $piece.LastIndexOf("`n")
						if ($nl -gt 80) {
							$pos -= ($piece.Length - $nl - 1)
							$piece = $piece.Substring(0, $nl + 1)
						}
					}
					Write-MBMdStreamAppend -Text $piece
					try { Write-MBMdStreamFlush } catch {}
				}
				try { Write-MBMdStreamFlush } catch {}
			} else {
				Write-Host $c -ForegroundColor Gray
			}
		} catch {
			Write-Host ("[{0}]" -f $AgentName) -ForegroundColor DarkRed
			Write-Host $c -ForegroundColor Gray
		}
	}
	try { Write-Host "" } catch {}
	try { Update-MBWpfLiveChrome -Force } catch {}
}

function Import-MBTranscript {
	param(
		[Parameter(Mandatory = $true)][string]$Path,
		[switch]$NoPaint,
		[switch]$Append
	)
	$lp = Resolve-MBPath $Path
	if (-not (Test-Path -LiteralPath $lp)) {
		throw "File not found: $lp"
	}
	$bytes = [System.IO.File]::ReadAllBytes($lp)
	$offset = 0
	if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
		$offset = 3
	}
	$text = [System.Text.Encoding]::UTF8.GetString($bytes, $offset, $bytes.Length - $offset)
	$parsed = ConvertFrom-MBTranscriptMarkdown -Text $text
	if (-not $parsed.Messages -or @($parsed.Messages).Count -eq 0) {
		throw "No chat turns found in markdown (expected ## You / ## $AgentName sections)."
	}

	$imported = @($parsed.Messages)

	# Restore tool groups from export header (merge when appending)
	$toolsRestored = @()
	if ($parsed.Tools -and @($parsed.Tools).Count -gt 0) {
		try {
			$toolsRestored = @(Set-MBActiveToolGroupsFromList -Groups @($parsed.Tools) -Merge:$Append)
		} catch {
			$toolsRestored = @($script:MB.ActiveToolGroups)
		}
	} elseif (-not $Append) {
		# No Tools: line in older transcripts - leave current groups alone
		$toolsRestored = @($script:MB.ActiveToolGroups)
	} else {
		$toolsRestored = @($script:MB.ActiveToolGroups)
	}
	if ($parsed.ToolProfile -and -not $Append) {
		try {
			if ($parsed.ToolProfile -match '^(?i)core|full$') {
				$script:MB.ToolProfile = $parsed.ToolProfile
			}
		} catch {}
	}

	if ($Append) {
		# Keep prior non-system turns, then append import
		$prior = @()
		foreach ($m in @($script:Messages)) {
			$r = [string](Get-MBProp $m 'role')
			if ($r -and $r -ne 'system') { $prior += $m }
		}
		$merged = @($prior) + @($imported)
		$script:Messages = @(Repair-MBMessagesEncoding -Messages @(Sync-MBSystemMessages -Messages $merged))
	} else {
		$script:Messages = @(Repair-MBMessagesEncoding -Messages @(Sync-MBSystemMessages -Messages $imported))
	}

	if ($parsed.Cwd) {
		try { Invoke-SetWorkingDirectory -path $parsed.Cwd | Out-Null } catch {}
	}

	# Last user text for /retry
	for ($i = $imported.Count - 1; $i -ge 0; $i--) {
		if ([string](Get-MBProp $imported[$i] 'role') -eq 'user') {
			$script:LastUserMessage = [string](Get-MBProp $imported[$i] 'content')
			break
		}
	}

	if (-not $NoPaint) {
		try { Show-MBImportedMessages -Messages $imported -Label 'loaded' } catch {}
	}
	try { Sync-MBPromptAfterToolGroups } catch {}
	try { Refresh-MBWpfStickyFromSession } catch {}

	return [pscustomobject]@{
		Path     = $lp
		Count    = $imported.Count
		Total    = @($script:Messages).Count
		Model    = $parsed.Model
		Cwd      = $parsed.Cwd
		Tools    = @($toolsRestored)
		Appended = [bool]$Append
	}
}


function Test-MBWpfDotNetReady {
	try {
		$frameworks = Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP' -Recurse |
			Get-ItemProperty -Name Version -EA 0 |
			Where-Object { $_.PSChildName -Match '^(?!S)\p{L}' } |
			Select-Object -ExpandProperty Version
		if (-not $frameworks -or @($frameworks).Count -eq 0) {
			return $true
		}
		$highestVersion = $frameworks | ForEach-Object { [version]$_ } | Measure-Object -Maximum | Select-Object -ExpandProperty Maximum
		if ($highestVersion -lt [version]'3.0') { return $false }
		return $true
	} catch {
		return $true
	}
}

function Test-MBWpfAvailable {
	try {
		if ($PSVersionTable.PSEdition -eq 'Core' -and $IsLinux) { return $false }
		if ($PSVersionTable.PSEdition -eq 'Core' -and $IsMacOS) { return $false }
		if (-not (Test-MBWpfDotNetReady)) { return $false }
		Add-Type -AssemblyName PresentationFramework -ErrorAction Stop
		Add-Type -AssemblyName PresentationCore -ErrorAction Stop
		Add-Type -AssemblyName WindowsBase -ErrorAction Stop
		return $true
	} catch { return $false }
}

function Resolve-MBHostUi {
	$script:MB.HostUi = 'wpf'
	return 'wpf'
}

function Test-MBWpfActive {
	return ($script:MB.HostUi -eq 'wpf' -and $script:MB.Wpf -and $script:MB.Wpf.Ready)
}

function Show-MBWpfError {
	param(
		[string]$Title = 'MiniBot error',
		[string]$Message,
		[System.Exception]$Exception = $null
	)
	$detail = [string]$Message
	if ($Exception) {
		$detail = ($detail + "`n`n" + $Exception.GetType().FullName + ": " + $Exception.Message).Trim()
		try {
			if ($Exception.InnerException) {
				$detail += "`nInner: " + $Exception.InnerException.Message
			}
		} catch {}
	}
	if ([string]::IsNullOrWhiteSpace($detail)) { $detail = '(no details)' }
	try { Write-MBDebugLog -Step 'ERROR_POPUP' -Detail ("{0} | {1}" -f $Title, $detail) } catch {}

	try {
		Write-Host ""
		Write-Host ("  ERROR: {0}" -f $Title) -ForegroundColor Red
		foreach ($line in ($detail -split "`r?`n")) {
			Write-Host ("    {0}" -f $line) -ForegroundColor DarkYellow
		}
		Write-Host ""
	} catch {}

	if ((Test-MBWpfActive) -and $script:MB.Wpf -and $script:MB.Wpf.Dispatcher) {
		$t = $Title
		$m = $detail
		$d = $script:MB.Wpf.Dispatcher
		$show = {
			try {
				[System.Windows.MessageBox]::Show(
					$m,
					$t,
					[System.Windows.MessageBoxButton]::OK,
					[System.Windows.MessageBoxImage]::Error
				) | Out-Null
			} catch {}
		}.GetNewClosure()
		try {
			if ($d.CheckAccess()) {
				& $show
			} else {
				[void]$d.Invoke([Action]$show, [System.Windows.Threading.DispatcherPriority]::Send)
			}
		} catch {
			try {
				Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
				[System.Windows.Forms.MessageBox]::Show($detail, $Title) | Out-Null
			} catch {}
		}
		return
	}
	try {
		Add-Type -AssemblyName PresentationFramework -ErrorAction SilentlyContinue
		[System.Windows.MessageBox]::Show($detail, $Title, 'OK', 'Error') | Out-Null
	} catch {
		try {
			$w = New-Object -ComObject Wscript.Shell
			[void]$w.Popup($detail, 0, $Title, 16)
		} catch {}
	}
}


function ConvertTo-MBWpfSafeText {
	param([AllowNull()][string]$Text)
	if ($null -eq $Text -or $Text.Length -eq 0) { return '' }
	$sb = New-Object System.Text.StringBuilder ($Text.Length + 4)
	foreach ($ch in $Text.ToCharArray()) {
		$code = [int][char]$ch
		if ($code -eq 9 -or $code -eq 10 -or $code -eq 13) {
			[void]$sb.Append($ch)
			continue
		}
		# Drop other C0, DEL, C1 controls, BOM, replacement char
		if ($code -lt 32) { continue }
		if ($code -eq 0x7F) { continue }
		if ($code -ge 0x80 -and $code -le 0x9F) { continue }
		if ($code -eq 0xFEFF -or $code -eq 0xFFFD) { continue }
		if ($code -eq 0x00AD -or $code -eq 0x2060 -or $code -eq 0x200B) { continue }
		if ($code -eq 0x00A0) { [void]$sb.Append(' '); continue }
		[void]$sb.Append($ch)
	}
	return $sb.ToString()
}

function Get-MBWpfCtxBarColor {
	param([string]$Level = 'ok')
	switch -Regex ([string]$Level) {
		'hard' { return '#F05C5C' }
		'soft' { return '#E0AF68' }
		default { return '#9ECE6A' }
	}
}

function Set-MBContextBarReady {
	param([switch]$Off)
	try {
		if ($Off) {
			$script:MB.CtxBarReady = $false
			$script:MB.LastCtxTokens = 0
			$script:MB.LastCtxPct = 0
			$script:MB.LastCtxLevel = 'ok'
			return
		}
		$script:MB.CtxBarReady = $true
	} catch {}
}

function Get-MBWpfContextBarDisplay {
	param($Est = $null)
	$ready = $false
	try { $ready = [bool]$script:MB.CtxBarReady } catch { $ready = $false }
	if (-not $ready) {
		return [pscustomobject]@{
			Pct     = 0.0
			PctText = '0%'
			TokText = 'Initializing...'
			Color   = '#6A6A76'
			Level   = 'init'
		}
	}
	if ($null -eq $Est) {
		try { $Est = Get-MBContextEstimate -Messages @($script:Messages) } catch { $Est = $null }
	}
	$pct = 0.0
	$level = 'ok'
	$pt = 0
	$usable = 0
	try { if ($null -ne $Est) { $pct = [double]$Est.Pct } } catch { $pct = 0.0 }
	try { if ($null -ne $Est) { $level = [string]$Est.Level } } catch { $level = 'ok' }
	try { if ($null -ne $Est) { $pt = [int]$Est.PromptTokens } } catch {
		try { $pt = [int]$script:MB.LastCtxTokens } catch { $pt = 0 }
	}
	try { if ($null -ne $Est) { $usable = [int]$Est.UsableTokens } } catch {
		try { $usable = [int](Get-MBEffectivePromptBudget) } catch { $usable = 0 }
	}
	$pctStr = ('{0,3:P0}' -f $pct).Trim()
	$tokStr = '{0:N0}/{1:N0}' -f $pt, $usable
	return [pscustomobject]@{
		Pct     = $pct
		PctText = $pctStr
		TokText = $tokStr
		Color   = (Get-MBWpfCtxBarColor -Level $level)
		Level   = $level
	}
}

function Invoke-MBWpf {
	param(
		[scriptblock]$Action,
		[switch]$Async
	)
	if (-not (Test-MBWpfActive)) { return }
	$d = $null
	try { $d = $script:MB.Wpf.Dispatcher } catch { $d = $null }
	if (-not $d) { return }
	# Window close / BeginInvokeShutdown cancels pending Invoke — not a real failure
	try {
		if ($d.HasShutdownStarted -or $d.HasShutdownFinished) { return }
	} catch {}
	try {
		if ($d.CheckAccess()) {
			& $Action
			return
		}
	} catch {
		return
	}
	$act = [Action]$Action
	try {
		if ($Async) {
			[void]$d.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Normal, $act)
		} else {
			try {
				if ($d.HasShutdownStarted -or $d.HasShutdownFinished) { return }
			} catch {}
			[void]$d.Invoke($act, [System.Windows.Threading.DispatcherPriority]::Background)
		}
	} catch {
		# TaskCanceledException / OperationCanceledException when dispatcher dies mid-Invoke
		$msg = ''
		try { $msg = [string]$_.Exception.Message } catch {}
		try {
			if ($_.Exception.InnerException) { $msg = $msg + ' ' + $_.Exception.InnerException.Message }
		} catch {}
		if ($msg -match '(?i)cancel') { return }
		throw
	}
}


function Reset-MBMdStream {
	if ([bool]$script:MB.MdVizActive -and (Test-MBWpfActive)) {
		try {
			$code = [string]$script:MB.MdVizBuf
			try {
				Write-MBDebugLog -Step 'VIZ_FLUSH_INCOMPLETE' -Detail ("bufChars={0} preview={1}" -f $code.Length, (Get-MBVizDebugPreview -Text $code -Max 160))
			} catch {}
			Write-MBMdViz -Markup $code -Lang 'iv'
		} catch {
			try { Write-MBDebugLog -Step 'VIZ_FLUSH_INCOMPLETE_ERR' -Detail $_.Exception.Message } catch {}
		}
	} elseif ([bool]$script:MB.MdFence -and (Test-MBWpfActive)) {
		try { Write-MBMdCodeClose } catch {}
	}
	$script:MB.MdPending = ''
	$script:MB.MdHold = ''
	$script:MB.MdBold = $false
	$script:MB.MdItalic = $false
	$script:MB.MdStrike = $false
	$script:MB.MdCode = $false
	$script:MB.MdFence = $false
	$script:MB.MdFenceLang = ''
	$script:MB.MdFenceBuf = ''
	$script:MB.MdVizActive = $false
	$script:MB.MdVizBuf = ''
	$script:MB.MdLineBold = $false
	$script:MB.MdLineItalic = $false
	$script:MB.MdHeadLevel = 0
	$script:MB.MdFontSize = 0
	$script:MB.MdAtLineStart = $true
	$script:MB.MdSkipBlankAfterBlock = $false
	$script:MB.MdInList = $false
	$script:MB.MdInTable = $false
	$script:MB.MdTableLine = ''
	$script:MB.MdTableRows = New-Object System.Collections.ArrayList
	$script:MB.MdTableHasSep = $false
}

function Write-MBWpfStyled {
	param(
		[AllowNull()][string]$Text,
		[switch]$Bold,
		[switch]$Italic,
		[switch]$Strike,
		[switch]$Code,
		[switch]$NoNewline,
		[string]$Color = 'Gray',
		[double]$FontSize = 0,
		[int]$HeadLevel = 0
	)
	if (-not (Test-MBWpfActive)) { return }
	if ($null -eq $Text -or $Text.Length -eq 0) {
		if ($NoNewline) { return }
		$Text = ''
	}
	try { $Text = ConvertTo-MBWpfSafeText -Text $Text } catch {}
	if (-not $script:MB.Wpf.WriteQueue) {
		$script:MB.Wpf.WriteQueue = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
	}
	$fs = [double]$FontSize
	if ($fs -le 0 -and $HeadLevel -gt 0) {
		switch ($HeadLevel) {
			1 { $fs = 16 }
			2 { $fs = 14.5 }
			3 { $fs = 13.5 }
			default { $fs = 13 }
		}
	}
	$script:MB.Wpf.WriteQueue.Enqueue([pscustomobject]@{
		Kind       = 'text'
		Text       = $Text
		Color      = $Color
		NoNewline  = [bool]$NoNewline
		MdBold     = $(if ($Bold) { 1 } else { 0 })
		MdItalic   = $(if ($Italic) { 1 } else { 0 })
		MdStrike   = $(if ($Strike) { 1 } else { 0 })
		MdCode     = $(if ($Code) { 1 } else { 0 })
		MdFontSize = $fs
		MdHead     = [int]$HeadLevel
		MdNoLinks  = 0
		Brand      = $(try { [string]$AgentName } catch { 'MiniBot' })
	})
}

function Write-MBMdEmit {
	param(
		[string]$Text,
		[switch]$NoNewline,
		[string]$Color = ''
	)
	if ($null -eq $Text) { $Text = '' }
	if ($Text.Length -eq 0 -and $NoNewline) { return }
	$b = [bool]$script:MB.MdBold -or [bool]$script:MB.MdLineBold
	$i = [bool]$script:MB.MdItalic -or [bool]$script:MB.MdLineItalic
	$s = [bool]$script:MB.MdStrike
	$c = [bool]$script:MB.MdCode
	$hl = [int]$script:MB.MdHeadLevel
	$fs = [double]$script:MB.MdFontSize
	$col = $Color
	if ([string]::IsNullOrEmpty($col)) {
		if ($c) { $col = 'Cyan' }
		elseif ($hl -gt 0) { $col = 'Cyan' }
		elseif ($b) { $col = 'White' }
		else { $col = 'Gray' }
	}
	Write-MBWpfStyled -Text $Text -NoNewline:$NoNewline `
		-Bold:$b -Italic:$i -Strike:$s -Code:$c `
		-Color $col -FontSize $fs -HeadLevel $hl
}

function Test-MBMdMarkerAt {
	param([string]$S, [int]$I)
	if ($I -lt 0 -or $I -ge $S.Length) { return $null }
	$n = $S.Length - $I
	$c0 = $S[$I]
	if ($c0 -eq [char]'~') {
		if ($n -ge 2 -and $S[$I + 1] -eq [char]'~') { return @{ Kind = 's'; Len = 2 } }
		return $null
	}
	if ($c0 -eq [char]'`') { return @{ Kind = 'c'; Len = 1 } }
	if ($c0 -eq [char]'*') {
		if ($n -ge 3 -and $S[$I + 1] -eq [char]'*' -and $S[$I + 2] -eq [char]'*') {
			return @{ Kind = 'bi'; Len = 3 }
		}
		if ($n -ge 2 -and $S[$I + 1] -eq [char]'*') { return @{ Kind = 'b'; Len = 2 } }
		return @{ Kind = 'i'; Len = 1 }
	}
	if ($c0 -eq [char]'_') {
		if ($n -ge 3 -and $S[$I + 1] -eq [char]'_' -and $S[$I + 2] -eq [char]'_') {
			return @{ Kind = 'bi'; Len = 3 }
		}
		if ($n -ge 2 -and $S[$I + 1] -eq [char]'_') { return @{ Kind = 'b'; Len = 2 } }
		return @{ Kind = 'i'; Len = 1 }
	}
	return $null
}

function Invoke-MBMdToggle {
	param([string]$Kind)
	switch ($Kind) {
		'b'  { $script:MB.MdBold = -not [bool]$script:MB.MdBold }
		'i'  { $script:MB.MdItalic = -not [bool]$script:MB.MdItalic }
		'bi' {
			$on = -not ([bool]$script:MB.MdBold -and [bool]$script:MB.MdItalic)
			$script:MB.MdBold = $on
			$script:MB.MdItalic = $on
		}
		's'  { $script:MB.MdStrike = -not [bool]$script:MB.MdStrike }
		'c'  { $script:MB.MdCode = -not [bool]$script:MB.MdCode }
	}
}

function Test-MBMdStyleOn {
	param([string]$Kind)
	switch ($Kind) {
		'b'  { return [bool]$script:MB.MdBold }
		'i'  { return [bool]$script:MB.MdItalic }
		'bi' { return ([bool]$script:MB.MdBold -and [bool]$script:MB.MdItalic) }
		's'  { return [bool]$script:MB.MdStrike }
		'c'  { return [bool]$script:MB.MdCode }
		default { return $false }
	}
}

function Find-MBMdBalancedParenClose {
	# Index of the ) that closes a markdown ( ... ) target, allowing nested () in Windows paths
	# e.g. C:\Music\Song (remix).mp3
	param(
		[string]$S,
		[int]$OpenAfter  # index of first char AFTER the opening '('
	)
	if ([string]::IsNullOrEmpty($S) -or $OpenAfter -lt 0 -or $OpenAfter -ge $S.Length) { return -1 }
	# Angle-bracket path: <C:\path with (parens) and spaces\file.mp3>
	if ($S[$OpenAfter] -eq [char]'<') {
		$gt = $S.IndexOf([char]'>', $OpenAfter + 1)
		if ($gt -lt 0) { return -1 }
		# optional whitespace then closing )
		$j = $gt + 1
		while ($j -lt $S.Length -and [char]::IsWhiteSpace($S[$j])) { $j++ }
		if ($j -lt $S.Length -and $S[$j] -eq [char]')') { return $j }
		return -1
	}
	$depth = 1
	for ($i = $OpenAfter; $i -lt $S.Length; $i++) {
		$ch = $S[$i]
		if ($ch -eq [char]'(') { $depth++ }
		elseif ($ch -eq [char]')') {
			$depth--
			if ($depth -eq 0) { return $i }
		}
	}
	return -1
}

function Test-MBMdLinkHoldOpen {
	# True while an incomplete markdown link/image is buffered across stream chunks.
	param([string]$S)
	if ([string]::IsNullOrEmpty($S)) { return $false }
	$idx = 0
	$len = $S.Length
	while ($idx -lt $len) {
		# Image: ![alt](...  — paths may contain spaces and ()
		if ($S[$idx] -eq [char]'!' -and ($idx + 1) -lt $len -and $S[$idx + 1] -eq [char]'[') {
			$close = $S.IndexOf([char]']', $idx + 2)
			if ($close -lt 0) { return $true }
			if (($close + 1) -ge $len) { return $true }
			if ($S[$close + 1] -ne [char]'(') {
				$idx = $idx + 2
				continue
			}
			$urlStart = $close + 2
			$paren = Find-MBMdBalancedParenClose -S $S -OpenAfter $urlStart
			if ($paren -lt 0) { return $true }
			$idx = $paren + 1
			continue
		}
		$open = $S.IndexOf([char]'[', $idx)
		if ($open -lt 0) { break }
		# skip if this [ is part of ![ already handled
		if ($open -gt 0 -and $S[$open - 1] -eq [char]'!') {
			$idx = $open + 1
			continue
		}
		$close = $S.IndexOf([char]']', $open + 1)
		if ($close -lt 0) { return $true }
		if (($close + 1) -ge $len) { return $true }
		if ($S[$close + 1] -ne [char]'(') {
			$idx = $open + 1
			continue
		}
		# Hold buffer only if URL looks like a link start
		$urlStart = $close + 2
		$paren = Find-MBMdBalancedParenClose -S $S -OpenAfter $urlStart
		if ($paren -lt 0) {
			$partial = ''
			if ($urlStart -lt $len) { $partial = $S.Substring($urlStart) }
			# Still typing URL, or empty after ](
			if ($partial.Length -eq 0) { return $true }
			if ($partial -match '^(?i)https?://' -or $partial -match '^(?i)www\.') { return $true }
			# ](something that is clearly not a URL - do not hold forever
			if ($partial -match '\s' -or $partial.Length -gt 12) {
				$idx = $open + 1
				continue
			}
			return $true
		}
		$idx = $paren + 1
	}
	return $false
}

function Test-MBMdHoldOpen {
	param([string]$S)
	if ([string]::IsNullOrEmpty($S)) { return $false }
	if ($S.EndsWith('~') -and -not $S.EndsWith('~~')) { return $true }
	if ($S -eq '*' -or $S -eq '_' -or $S -eq '~' -or $S -eq '`' ) { return $true }
	if ($S -eq '**' -or $S -eq '__' -or $S -eq '~~' -or $S -eq '***' -or $S -eq '___') { return $true }
	# Buffer incomplete markdown links so [label](https://...) is not split on spaces
	if (Test-MBMdLinkHoldOpen -S $S) { return $true }

	$bold = $false; $italic = $false; $strike = $false; $code = $false
	$i = 0
	$len = $S.Length
	while ($i -lt $len) {
		if ($code) {
			if ($S[$i] -eq [char]'`') { $code = $false }
			$i++
			continue
		}
		$mk = Test-MBMdMarkerAt -S $S -I $i
		if ($null -eq $mk) { $i++; continue }
		$kind = [string]$mk.Kind
		$mlen = [int]$mk.Len
		$prevIsWord = ($i -gt 0 -and $S[$i - 1] -match '[A-Za-z0-9]')
		$nextIsWord = (($i + $mlen) -lt $len -and $S[$i + $mlen] -match '[A-Za-z0-9]')
		$styleOn = $false
		switch ($kind) {
			'b'  { $styleOn = $bold }
			'i'  { $styleOn = $italic }
			'bi' { $styleOn = ($bold -and $italic) }
			's'  { $styleOn = $strike }
			'c'  { $styleOn = $code }
		}
		$can = $true
		if (-not $styleOn) { if ($prevIsWord) { $can = $false } }
		else { if ($nextIsWord) { $can = $false } }
		if ($can) {
			switch ($kind) {
				'b'  { $bold = -not $bold }
				'i'  { $italic = -not $italic }
				'bi' {
					$on = -not ($bold -and $italic)
					$bold = $on; $italic = $on
				}
				's'  { $strike = -not $strike }
				'c'  { $code = -not $code }
			}
			$i += $mlen
			continue
		}
		$i++
	}
	if ($bold -or $italic -or $strike -or $code) { return $true }
	return $false
}

function Write-MBMdProcessInline {
	param([string]$Text)
	if ($null -eq $Text) { $Text = '' }
	if ($Text.Length -eq 0) { return }
	$work = $Text
	$i = 0
	$len = $work.Length
	$buf = New-Object System.Text.StringBuilder
	while ($i -lt $len) {
		if ([bool]$script:MB.MdCode) {
			if ($work[$i] -eq [char]'`') {
				if ($buf.Length -gt 0) {
					Write-MBMdEmit -Text $buf.ToString() -NoNewline
					[void]$buf.Clear()
				}
				$script:MB.MdCode = $false
				$i++
				continue
			}
			[void]$buf.Append($work[$i])
			$i++
			continue
		}
		# Inline markdown media: ![alt](path-or-url) — spaces in Windows paths allowed
		if ($work[$i] -eq [char]'!' -and ($i + 1) -lt $len -and $work[$i + 1] -eq [char]'[') {
			$rest = $work.Substring($i)
			$mk = Test-MBMdMediaMarkup -Text $rest
			if ($mk -and $mk.Ok) {
				if ($buf.Length -gt 0) {
					Write-MBMdEmit -Text $buf.ToString() -NoNewline
					[void]$buf.Clear()
				}
				Write-MBWpfMedia -Path ([string]$mk.Path) -Alt ([string]$mk.Alt) -Kind ([string]$mk.Kind)
				$i += [int]$mk.Length
				continue
			}
		}
		$mk = Test-MBMdMarkerAt -S $work -I $i
		if ($null -ne $mk) {
			$kind = [string]$mk.Kind
			$mlen = [int]$mk.Len
			$canToggle = $true
			$prevIsWord = ($i -gt 0 -and $work[$i - 1] -match '[A-Za-z0-9]')
			$nextIsWord = (($i + $mlen) -lt $len -and $work[$i + $mlen] -match '[A-Za-z0-9]')
			$styleOn = Test-MBMdStyleOn -Kind $kind
			if (-not $styleOn) {
				if ($prevIsWord) { $canToggle = $false }
			} else {
				if ($nextIsWord) { $canToggle = $false }
			}
			if ($canToggle) {
				if ($buf.Length -gt 0) {
					Write-MBMdEmit -Text $buf.ToString() -NoNewline
					[void]$buf.Clear()
				}
				Invoke-MBMdToggle -Kind $kind
				$i += $mlen
				continue
			}
		}
		[void]$buf.Append($work[$i])
		$i++
	}
	if ($buf.Length -gt 0) {
		Write-MBMdEmit -Text $buf.ToString() -NoNewline
	}
}

function Test-MBMdTableSeparator {
	param([string]$Line)
	$L = ([string]$Line).Trim() -replace [string][char]0x2502, '|' -replace [string][char]0x2503, '|'
	return ($L -match '^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$')
}

function Get-MBMdTableCells {
	param([string]$Line)
	$raw = ([string]$Line).Trim()
	if ($raw.Length -eq 0) { return [string[]]@() }
	# Normalize box-drawing vertical bars to ASCII pipe
	$raw = $raw -replace [string][char]0x2502, '|'
	$raw = $raw -replace [string][char]0x2503, '|'
	if ($raw.StartsWith('|')) { $raw = $raw.Substring(1) }
	if ($raw.EndsWith('|') -and $raw.Length -gt 0) { $raw = $raw.Substring(0, $raw.Length - 1) }
	$parts = $raw -split '\|'
	$list = New-Object System.Collections.Generic.List[string]
	foreach ($p in @($parts)) {
		$list.Add((([string]$p).Trim()))
	}
	return ,([string[]]$list.ToArray())
}

function ConvertFrom-MBMdCellText {
	param([string]$Text)
	if ($null -eq $Text) { return '' }
	$t = [string]$Text
	$t = [regex]::Replace($t, '`([^`]*)`', '$1')
	$t = [regex]::Replace($t, '\[([^\]]+)\]\(\s*https?://[^)\s]+\s*(?:\"[^\"]*\")?\s*\)', '$1')
	$t = [regex]::Replace($t, '\*\*\*([^*]+)\*\*\*', '$1')
	$t = [regex]::Replace($t, '\*\*([^*]+)\*\*', '$1')
	$t = [regex]::Replace($t, '(?<!\*)\*([^*]+)\*(?!\*)', '$1')
	$t = [regex]::Replace($t, '~~([^~]+)~~', '$1')
	$t = [regex]::Replace($t, '__([^_]+)__', '$1')
	$t = [regex]::Replace($t, '(?<!_)_([^_]+)_(?!_)', '$1')
	return $t
}

function Complete-MBMdTableIfAny {
	if ($null -eq $script:MB.MdTableRows) {
		$script:MB.MdTableRows = New-Object System.Collections.ArrayList
	}
	if ([int]$script:MB.MdTableRows.Count -eq 0) {
		$script:MB.MdInTable = $false
		$script:MB.MdTableHasSep = $false
		return
	}
	$rows = @($script:MB.MdTableRows.ToArray())
	$script:MB.MdTableRows = New-Object System.Collections.ArrayList
	$script:MB.MdInTable = $false
	$script:MB.MdTableHasSep = $false
	Write-MBMdEmitTable -Rows $rows
}

function Write-MBMdEmitTable {
	param([object[]]$Rows)
	if (-not (Test-MBWpfActive)) { return }
	if ($null -eq $Rows -or @($Rows).Count -eq 0) { return }
	if (-not $script:MB.Wpf.WriteQueue) {
		$script:MB.Wpf.WriteQueue = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
	}
	$sep = [string][char]0x1F  # unit separator - not used in normal cell text
	$payload = New-Object System.Collections.ArrayList
	foreach ($r in @($Rows)) {
		if ($null -eq $r) { continue }
		$cells = New-Object System.Collections.Generic.List[string]
		$isHdr = $false
		try {
			try { $isHdr = [bool]$r.IsHeader } catch { $isHdr = $false }
			$joined = $null
			try { $joined = [string]$r.CellsJoined } catch { $joined = $null }
			if (-not [string]::IsNullOrEmpty($joined)) {
				foreach ($p in ($joined -split [char]0x1F)) { $cells.Add([string]$p) }
			} else {
				$cellSrc = $null
				try { $cellSrc = $r.Cells } catch { $cellSrc = $null }
				if ($null -ne $cellSrc) {
					if ($cellSrc -is [string]) {
						$cells.Add([string]$cellSrc)
					} elseif ($cellSrc -is [System.Array]) {
						for ($ci = 0; $ci -lt $cellSrc.Length; $ci++) {
							$x = $cellSrc.GetValue($ci)
							$cells.Add($(if ($null -eq $x) { '' } else { [string]$x }))
						}
					} elseif ($cellSrc -is [System.Collections.IList]) {
						for ($ci = 0; $ci -lt $cellSrc.Count; $ci++) {
							$x = $cellSrc[$ci]
							$cells.Add($(if ($null -eq $x) { '' } else { [string]$x }))
						}
					} else {
						$cells.Add([string]$cellSrc)
					}
				}
			}
		} catch {
			$cells.Clear()
			$cells.Add('')
			$isHdr = $false
		}
		if ($cells.Count -eq 0) { $cells.Add('') }
		$clean = New-Object System.Collections.Generic.List[string]
		foreach ($c in $cells) {
			$s = if ($null -eq $c) { '' } else { [string]$c }
			try { $s = ConvertFrom-MBMdCellText -Text $s } catch {}
			$clean.Add($s)
		}
		[void]$payload.Add([pscustomobject]@{
			CellsJoined = [string]::Join($sep, $clean.ToArray())
			ColCount    = [int]$clean.Count
			IsHeader    = [bool]$isHdr
		})
	}
	if ($payload.Count -eq 0) { return }
	$script:MB.Wpf.WriteQueue.Enqueue([pscustomobject]@{
		Kind       = 'md-table'
		Text       = ''
		Color      = 'Gray'
		NoNewline  = $true
		Rows       = @($payload.ToArray())
		MdBold     = 0
		MdItalic   = 0
		MdStrike   = 0
		MdCode     = 0
		MdFontSize = 0
		MdHead     = 0
		Brand      = $(try { [string]$AgentName } catch { 'MiniBot' })
	})
}

function Write-MBMdFinishTableLine {
	param([string]$Line)
	if ($null -eq $script:MB.MdTableRows) {
		$script:MB.MdTableRows = New-Object System.Collections.ArrayList
	}
	if (Test-MBMdTableSeparator -Line $Line) {
		$script:MB.MdTableHasSep = $true
		$script:MB.MdInTable = $true
		for ($ri = 0; $ri -lt $script:MB.MdTableRows.Count; $ri++) {
			try { $script:MB.MdTableRows[$ri].IsHeader = $true } catch {}
		}
		return
	}
	$cellArr = Get-MBMdTableCells -Line $Line
	if ($null -eq $cellArr) { return }
	$colN = 0
	try { $colN = [int]$cellArr.Length } catch { try { $colN = @($cellArr).Count } catch { $colN = 0 } }
	if ($colN -eq 0) { return }

	$isHdr = ($script:MB.MdTableRows.Count -eq 0)
	if ([bool]$script:MB.MdTableHasSep) { $isHdr = $false }

	$sep = [string][char]0x1F
	$joined = [string]::Join($sep, [string[]]$cellArr)
	[void]$script:MB.MdTableRows.Add([pscustomobject]@{
		Cells       = [string[]]$cellArr
		CellsJoined = $joined
		ColCount    = $colN
		IsHeader    = $isHdr
	})
	$script:MB.MdInTable = $true
}

