function Start-MBElementOpacityPulse {
	param(
		$Element,
		[double]$From = 0.4,
		[double]$To = 1.0,
		[int]$Ms = 900
	)
	if (-not $Element) { return }
	try {
		$anim = New-Object System.Windows.Media.Animation.DoubleAnimation
		$anim.From = $From
		$anim.To = $To
		$anim.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds([Math]::Max(200, $Ms)))
		$anim.AutoReverse = $true
		$anim.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
		try {
			$ease = New-Object System.Windows.Media.Animation.SineEase
			$ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
			$anim.EasingFunction = $ease
		} catch {}
		$Element.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $anim)
	} catch {}
}

function Stop-MBElementOpacityPulse {
	param($Element, [double]$RestOpacity = 1.0)
	if (-not $Element) { return }
	try {
		$Element.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
		$Element.Opacity = $RestOpacity
	} catch {}
}

function Start-MBBrushColorPulse {
	param(
		$Brush,
		[string]$FromHex,
		[string]$ToHex,
		[int]$Ms = 1100
	)
	if (-not $Brush) { return }
	try {
		$conv = New-Object System.Windows.Media.BrushConverter
		$fromC = ([System.Windows.Media.SolidColorBrush]$conv.ConvertFromString($FromHex)).Color
		$toC = ([System.Windows.Media.SolidColorBrush]$conv.ConvertFromString($ToHex)).Color
		$anim = New-Object System.Windows.Media.Animation.ColorAnimation
		$anim.From = $fromC
		$anim.To = $toC
		$anim.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds([Math]::Max(250, $Ms)))
		$anim.AutoReverse = $true
		$anim.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
		try {
			$ease = New-Object System.Windows.Media.Animation.SineEase
			$ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
			$anim.EasingFunction = $ease
		} catch {}
		$Brush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $anim)
	} catch {}
}

function Stop-MBBrushColorPulse {
	param($Brush, [string]$RestHex = '')
	if (-not $Brush) { return }
	try {
		$Brush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $null)
		if (-not [string]::IsNullOrWhiteSpace($RestHex)) {
			try {
				$conv = New-Object System.Windows.Media.BrushConverter
				$c = ([System.Windows.Media.SolidColorBrush]$conv.ConvertFromString($RestHex)).Color
				$Brush.Color = $c
			} catch {}
		}
	} catch {}
}

function Get-MBEffectiveMaxTurns {
	# Unlimited: no practical cap (Esc/Stop still works)
	if (Test-MBUnlimitedTurns) { return 1000000 }
	$cfg = Get-MBConfiguredMaxTurns
	# After ∞ ends mid-flight: allow resumeTurn0 + frozen remaining more iterations
	try {
		if ([bool]$script:MB.TurnsInFlight -and $null -ne $script:MB.TurnsResumeTurn0 -and $null -ne $script:MB.TurnsLeftFrozen) {
			$t0 = [int]$script:MB.TurnsResumeTurn0
			$fr = [int]$script:MB.TurnsLeftFrozen
			if ($t0 -lt 0) { $t0 = 0 }
			if ($fr -lt 0) { $fr = 0 }
			$cap = $t0 + $fr
			if ($cap -lt 1) { $cap = 1 }
			return $cap
		}
	} catch {}
	return $cfg
}

function Get-MBWpfTurnsDisplayValue {
	# In-flight: remaining. Idle: configured max.
	try {
		if ($script:MB.Wpf -and [bool]$script:MB.Wpf.TurnsInFlight) {
			$left = 0
			try { $left = [int]$script:MB.Wpf.TurnsLeft } catch { $left = 0 }
			if ($left -lt 0) { $left = 0 }
			return $left
		}
	} catch {}
	try {
		if ([bool]$script:MB.TurnsInFlight) {
			$left = [int]$script:MB.TurnsLeft
			if ($left -lt 0) { $left = 0 }
			return $left
		}
	} catch {}
	return (Get-MBEffectiveMaxTurns)
}

function Update-MBWpfTurnsNumText {
	param([int]$Value)
	try {
		if (-not $script:MB.Wpf) { return }
		$tb = $null
		try { $tb = $script:MB.Wpf.AaTurnsNumTb } catch { $tb = $null }
		if (-not $tb) { return }
		$txt = [string][Math]::Max(0, [int]$Value)
		$d = $null
		try { $d = $script:MB.Wpf.Dispatcher } catch { $d = $null }
		if (-not $d) { return }
		$paint = {
			try { if ($null -ne $tb) { $tb.Text = $txt } } catch {}
		}.GetNewClosure()
		try {
			if ($d.CheckAccess()) {
				& $paint
			} else {
				# Marshal to WPF STA (off-thread Text= is ignored / throws)
				[void]$d.BeginInvoke([Action]$paint, [System.Windows.Threading.DispatcherPriority]::Normal)
			}
		} catch {
			try { [void]$d.BeginInvoke([Action]$paint, [System.Windows.Threading.DispatcherPriority]::Background) } catch {}
		}
	} catch {}
}

function Update-MBTurnsCountdown {
	param([int]$Turn = 0, [switch]$Idle)
	try {
		$unlim = Test-MBUnlimitedTurns
		$cfgMax = Get-MBConfiguredMaxTurns

		if ($Idle) {
			$script:MB.TurnsInFlight = $false
			$script:MB.TurnsUsed = 0
			$script:MB.TurnsResumeTurn0 = $null
			if ($unlim) {
				# New user message under ∞: park a full configured budget for when ∞ ends
				$script:MB.TurnsLeftFrozen = $cfgMax
				$script:MB.TurnsLeft = $cfgMax
			} else {
				$script:MB.TurnsLeft = $cfgMax
				$script:MB.TurnsLeftFrozen = $null
			}
		} else {
			$script:MB.TurnsInFlight = $true
			$script:MB.TurnsUsed = [int]$Turn
			if ($unlim) {
				# Frozen: do not count down while ∞ is on
				$fr = $null
				try { $fr = $script:MB.TurnsLeftFrozen } catch { $fr = $null }
				if ($null -eq $fr) {
					try { $fr = [int]$script:MB.TurnsLeft } catch { $fr = $cfgMax }
				}
				try { $fr = [int]$fr } catch { $fr = $cfgMax }
				if ($fr -lt 0) { $fr = 0 }
				if ($fr -gt $cfgMax) { $fr = $cfgMax }
				$script:MB.TurnsLeftFrozen = $fr
				$script:MB.TurnsLeft = $fr
			} else {
				$t0 = $null
				try { $t0 = $script:MB.TurnsResumeTurn0 } catch { $t0 = $null }
				$fr = $null
				try { $fr = $script:MB.TurnsLeftFrozen } catch { $fr = $null }
				if ($null -ne $t0 -and $null -ne $fr) {
					# Resumed after ∞: burn only from the frozen remainder
					$left = [int]$fr - ([int]$Turn - [int]$t0)
					if ($left -lt 0) { $left = 0 }
					$script:MB.TurnsLeft = $left
				} else {
					$left = $cfgMax - [int]$Turn
					if ($left -lt 0) { $left = 0 }
					$script:MB.TurnsLeft = $left
				}
			}
		}
		if ($script:MB.Wpf) {
			$script:MB.Wpf.TurnsLeft = [int]$script:MB.TurnsLeft
			$script:MB.Wpf.TurnsUsed = [int]$script:MB.TurnsUsed
			$script:MB.Wpf.TurnsInFlight = [bool]$script:MB.TurnsInFlight
			try { $script:MB.Wpf.MaxTurnsSetting = $cfgMax } catch {}
			if (-not $unlim) {
				$disp = if ($Idle) { $cfgMax } else { [int]$script:MB.TurnsLeft }
				if ($disp -lt 0) { $disp = 0 }
				if ($disp -gt 200) { $disp = $cfgMax }
				Update-MBWpfTurnsNumText -Value $disp
			}
		}
	} catch {}
}

function Get-MBWpfLowerRightText {
	try { Sync-MBAutoApproveFromWpf } catch {}
	try { Sync-MBAutoCompactFromWpf } catch {}
	try { Sync-MBMaxTurnsFromWpf } catch {}
	try { Sync-MBActiveModelFromWpf } catch {}
	try {
		if ($script:MB.Wpf -and [bool]$script:MB.Wpf.RemoteModelsRefreshWanted) {
			$script:MB.Wpf.RemoteModelsRefreshWanted = $false
			$null = Refresh-MBRemoteModels -Force
			try { Update-MBWpfWindowTitle } catch {}
		}
	} catch {}
	$dot = [string][char]0x00B7
	$parts = New-Object System.Collections.ArrayList
	$n = 0
	try { $n = [int]$script:MB.CompactionCount } catch { $n = 0 }
	# Compaction count chip
	if ($n -gt 0) {
		[void]$parts.Add(("x{0}" -f $n))
	}
	$acOn = [bool]$script:MB.AutoCompact
	[void]$parts.Add($(if ($acOn) { 'auto-compact: ON' } else { 'auto-compact: OFF' }))
	$autoOn = [bool]$script:MB.AutoApprove
	[void]$parts.Add($(if ($autoOn) { 'auto-approve: ON' } else { 'auto-approve: OFF' }))
	[void]$parts.Add(("tools used {0}" -f [int]$script:MB.ToolCalls))
	return ($parts -join ("  {0}  " -f $dot))
}

function Get-MBWpfAutoCompactLine {
	# AutoCompact status text
	if ($script:MB.AutoCompact) { return 'AutoCompact: ON' }
	return 'AutoCompact: OFF'
}

function Update-MBWpfWindowTitle {
	# Update custom titlebar brand, path, and model picker label
	if (-not (Test-MBWpfActive)) { return }
	$W = $script:MB.Wpf
	if (-not $W) { return }
	try {
		$agent = if ($AgentName) { [string]$AgentName } else { 'MiniBot' }
		$brand = "[{0}-Agent]" -f $agent
		$path = ''
		try { $path = Get-MBShortPath -Path $script:MB.WorkingDir -MaxLen 56 } catch { $path = [string]$script:MB.WorkingDir }
		$active = ''
		try { $active = Get-MBActiveModel } catch { $active = '' }
		$powered = ''
		if (-not [string]::IsNullOrWhiteSpace($active)) {
			$powered = ("PoweredBy: {0}" -f $active.Trim())
		} else {
			$powered = 'PoweredBy: Select Model'
		}
		$dot = [string][char]0x00B7
		$parts = New-Object System.Collections.ArrayList
		[void]$parts.Add($brand)
		if (-not [string]::IsNullOrWhiteSpace($path)) { [void]$parts.Add($path) }
		if ($powered) { [void]$parts.Add($powered) }
		$W.PendingWindowTitle = ($parts -join ("  {0}  " -f $dot))
		$W.PendingTitleBrand = $brand
		$W.PendingTitleBrandName = $agent
		$W.PendingTitlePath = $(if ($path) { [string]$path } else { '' })
		$W.PendingTitlePoweredBy = $powered
		# Keep picker bag in sync (do not bump seq here — callers bump when the list changes)
		try { $W.ActiveModel = [string]$script:MB.ActiveModel } catch {}
		try { $W.ActiveModelBase = [string]$script:MB.ActiveModelBase } catch {}
		try { $W.ActiveModelKey = [string]$script:MB.ActiveModelKey } catch {}
		try { $W.RemoteModels = @($script:MB.RemoteModels) } catch {}
		try { $W.RemoteModelEntries = @($script:MB.RemoteModelEntries) } catch {}
		try { $W.CurrentCwd = [string]$script:MB.WorkingDir } catch {}
	} catch {}
}

function Sync-MBCwdFromWpf {
	# Apply cwd from titlebar popup
	if (-not $script:MB.Wpf) { return }
	try {
		if (-not [bool]$script:MB.Wpf.CwdDirty) { return }
		$p = [string]$script:MB.Wpf.PendingCwd
		$script:MB.Wpf.CwdDirty = $false
		if ([string]::IsNullOrWhiteSpace($p)) { return }
		$p = $p.Trim().Trim('"')
		if (-not [System.IO.Directory]::Exists($p)) {
			try {
				if ($script:MB.Wpf.WriteQueue) {
					$script:MB.Wpf.WriteQueue.Enqueue([pscustomobject]@{
						Kind = 'text'; Text = ("`n  Folder not found: {0}`n" -f $p); Color = 'Yellow'; NoNewline = $false
						Brand = $(try { [string]$AgentName } catch { 'MiniBot' })
					})
				}
			} catch {}
			return
		}
		$full = [System.IO.Path]::GetFullPath($p)
		$script:MB.WorkingDir = $full
		try { Set-Location -LiteralPath $full } catch {}
		try { $script:MB.Wpf.CurrentCwd = $full } catch {}
		try {
			if ($script:MB.Wpf.WriteQueue) {
				$script:MB.Wpf.WriteQueue.Enqueue([pscustomobject]@{
					Kind = 'text'; Text = ("`n  WORKING_DIR: {0}`n" -f $full); Color = 'Green'; NoNewline = $false
					Brand = $(try { [string]$AgentName } catch { 'MiniBot' })
				})
			}
		} catch {}
		try { Update-MBWpfWindowTitle } catch {}
		try { Refresh-MBWpfStickyFromSession } catch {}
	} catch {
		try { $script:MB.Wpf.CwdDirty = $false } catch {}
	}
}

function Update-MBWpfLiveChrome {
	param(
		[switch]$Force
	)
	if (-not (Test-MBWpfActive)) { return }
	try {
		try { Sync-MBCwdFromWpf } catch {}
		if ($script:MB.Wpf.NeedPathBudgetRefresh) {
			$script:MB.Wpf.NeedPathBudgetRefresh = $false
			try { Refresh-MBWpfStickyFromSession } catch {}
		}
		try { Update-MBWpfWindowTitle } catch {}
		$now = [Environment]::TickCount
		$last = 0
		try { $last = [int]$script:MB.WpfLiveChromeTick } catch { $last = 0 }
		$doCtx = $Force -or ($last -eq 0) -or ((($now - $last) -band 0x7fffffff) -ge 120)
		$right = Get-MBWpfLowerRightText
		if (-not $doCtx) {
			Update-MBWpfSticky -Right $right
			return
		}
		$script:MB.WpfLiveChromeTick = $now
		$est = $null
		$ready = $false
		try { $ready = [bool]$script:MB.CtxBarReady } catch { $ready = $false }
		if ($ready) {
			try { $est = Get-MBContextEstimate -Messages @($script:Messages) } catch { $est = $null }
		}
		$bar = Get-MBWpfContextBarDisplay -Est $est
		Update-MBWpfSticky -Right $right `
			-CtxPct ([double]$bar.Pct) -CtxColor ([string]$bar.Color) `
			-CtxPctText ([string]$bar.PctText) -CtxTokText ([string]$bar.TokText)
	} catch {}
}

function Refresh-MBWpfStickyFromSession {
	param([string]$Hint = '')
	if (-not (Test-MBWpfActive)) { return }
	try {
		$est = $null
		$ready = $false
		try { $ready = [bool]$script:MB.CtxBarReady } catch { $ready = $false }
		if ($ready) {
			try { $est = Get-MBContextEstimate -Messages @($script:Messages) } catch { $est = $null }
		}
		$bar = Get-MBWpfContextBarDisplay -Est $est
		$dot = [string][char]0x00B7  # middot separator
		try { Update-MBWpfWindowTitle } catch {}
		$right = Get-MBWpfLowerRightText
		if (-not $Hint) {
			$Hint = "Enter send  {0}  Ctrl+Enter newline  {0}  Esc interrupt  {0}  /help" -f $dot
		}
		$st = if ($script:MB.IsCompacting) { 'auto-compacting' } `
			elseif ($script:MB.IsThinking) { 'thinking...' } `
			elseif ($script:MB.IsWorking) { 'working' } `
			else { 'ready' }
		Update-MBWpfSticky -Right $right -Hint $Hint -Status $st `
			-CtxPct ([double]$bar.Pct) -CtxColor ([string]$bar.Color) `
			-CtxPctText ([string]$bar.PctText) -CtxTokText ([string]$bar.TokText)
		try { Update-MBWpfToolGroupBar } catch {}
		try { $script:MB.WpfLiveChromeTick = [Environment]::TickCount } catch {}
	} catch {}
}

function Set-MBWpfPromptEnabled {
	param(
		[bool]$Enabled,
		[switch]$Focus
	)
	if (-not (Test-MBWpfActive)) { return }
	$script:MB.Wpf.PromptArmed = [bool]$Enabled
	$script:MB.Wpf.PendingPromptEnabled = [bool]$Enabled
	if ($Enabled -and $Focus) {
		try { $script:MB.Wpf.PendingPromptFocus = $true } catch {}
	}
}

function Focus-MBWpfPrompt {
	if (-not (Test-MBWpfActive)) { return }
	try { if ([bool]$script:MB.Wpf.ModalUi) { return } } catch {}
	$promptRef = $null
	$winRef = $null
	$d = $null
	try { $promptRef = $script:MB.Wpf.Prompt } catch {}
	try { $winRef = $script:MB.Wpf.Window } catch {}
	try { $d = $script:MB.Wpf.Dispatcher } catch {}
	if (-not $promptRef -or -not $d) { return }

	try {
		$script:MB.Wpf.PromptArmed = $true
		$script:MB.Wpf.PendingPromptEnabled = $true
		$script:MB.Wpf.PendingPromptFocus = $false
	} catch {}

	$sb = {
		$p = $promptRef
		$w = $winRef
		if (-not $p) { return }
		try {
			try {
				if ([bool]$script:MB.Wpf.ModalUi) { return }
				if ([bool]$script:MB.Wpf.AuthActive) { return }
				if ($script:MB.Wpf.AuthOverlay -and $script:MB.Wpf.AuthOverlay.Visibility -eq [System.Windows.Visibility]::Visible) { return }
				if ($script:MB.Wpf.AddEndpointOverlay -and $script:MB.Wpf.AddEndpointOverlay.Visibility -eq [System.Windows.Visibility]::Visible) { return }
				if ($script:MB.Wpf.ConfirmOverlay -and $script:MB.Wpf.ConfirmOverlay.Visibility -eq [System.Windows.Visibility]::Visible) { return }
			} catch {}
			$p.IsEnabled = $true
			$p.Focusable = $true
			$p.IsReadOnly = $false
			try {
				if ($script:MB.Wpf.SyncSendBtn) { & $script:MB.Wpf.SyncSendBtn $true }
			} catch {}
			try {
				if ($w -and $w.WindowState -eq [System.Windows.WindowState]::Minimized) {
					$w.WindowState = [System.Windows.WindowState]::Normal
				}
				if ($w) { [void]$w.Activate() }
			} catch {}
			try { [void]$p.Focus() } catch {}
			try { [void][System.Windows.Input.Keyboard]::Focus($p) } catch {}
			try {
				if ($null -ne $p.Text) { $p.CaretIndex = $p.Text.Length }
				else { $p.CaretIndex = 0 }
			} catch {}
		} catch {}
	}.GetNewClosure()

	try {
		if ($d.CheckAccess()) { & $sb }
		else { [void]$d.Invoke([Action]$sb, [System.Windows.Threading.DispatcherPriority]::Send) }
	} catch {
		try { Invoke-MBWpf -Action $sb } catch {}
	}
}

function Read-MBWpfUserInput {
	try {
		Write-MBDebugLog -Step 'READ_WPF_INPUT_BEGIN'
		if (-not (Test-MBWpfActive)) {
			Write-MBDebugLog -Step 'READ_WPF_INPUT_NOT_ACTIVE'
			return ""
		}
		try { Refresh-MBWpfStickyFromSession -Hint ("enter send  {0}  Ctrl+Enter newline  {0}  Esc interrupt  {0}  /help" -f ([char]0x00B7)) } catch {}
		Set-MBWpfPromptEnabled -Enabled $true -Focus
		try { Focus-MBWpfPrompt } catch {}
		Write-MBDebugLog -Step 'READ_WPF_INPUT_ARMED'
		$script:MB.Wpf.InputResult = $null
		$script:MB.Wpf.InterruptFlag = $false
		try { [void]$script:MB.Wpf.InputWait.Reset() } catch {}
		$script:MB.Wpf.InputResult = $null
		try {
			while ($true) {
				if ($script:MB.Wpf.ExitRequested) {
					Write-MBDebugLog -Step 'READ_WPF_INPUT_EXIT_REQUESTED'
					return [string][char]0x1B + 'WPF_CLOSE'
				}
				if ($script:MB.Wpf.InterruptFlag) {
					$script:MB.Wpf.InterruptFlag = $false
					$script:MB.Interrupt = $true
					Write-MBDebugLog -Step 'READ_WPF_INPUT_INTERRUPT_FLAG'
				}
				$signaled = $false
				try { $signaled = $script:MB.Wpf.InputWait.WaitOne(20) } catch { $signaled = $false }
				try { Sync-MBCwdFromWpf } catch {}
				# Apply PoweredBy model switch / Add-endpoint while idle (do not wait for next typed line)
				try { Sync-MBActiveModelFromWpf } catch {}
				try {
					if ($script:MB.Wpf -and [bool]$script:MB.Wpf.RemoteModelsRefreshWanted) {
						$script:MB.Wpf.RemoteModelsRefreshWanted = $false
						$null = Refresh-MBRemoteModels -Force
						try { Update-MBWpfWindowTitle } catch {}
					}
				} catch {}
				if ($signaled) {
					if ($script:MB.Wpf.ExitRequested) {
						Write-MBDebugLog -Step 'READ_WPF_INPUT_EXIT_AFTER_SIGNAL'
						return [string][char]0x1B + 'WPF_CLOSE'
					}
					$r = [string]$script:MB.Wpf.InputResult
					$script:MB.Wpf.InputResult = $null
					Write-MBDebugLog -Step 'READ_WPF_INPUT_RECEIVED' -Detail ("len={0}" -f $(if ($null -eq $r) { -1 } else { $r.Length }))
					Set-MBWpfPromptEnabled -Enabled $false
					try {
						Refresh-MBWpfStickyFromSession -Hint ("esc interrupt  {0}  model working..." -f ([char]0x00B7))
					} catch {}
					Write-MBDebugLog -Step 'READ_WPF_INPUT_RETURN'
					return $r
				}
			}
		} finally {
			try { Set-MBWpfPromptEnabled -Enabled $false } catch {}
			Write-MBDebugLog -Step 'READ_WPF_INPUT_FINALLY'
		}
	} catch {
		Write-MBDebugLog -Step 'READ_WPF_INPUT_ERROR' -Detail $_.Exception.Message
		Show-MBWpfError -Title 'Prompt error' -Message 'Failed while waiting for input.' -Exception $_.Exception
		return ""
	}
}

function Restore-MBWpfStickyAfterApproval {
	if (-not (Test-MBWpfActive)) { return }
	$dot = [string][char]0x00B7
	try {
		if ($script:MB.IsCompacting) {
			Refresh-MBWpfStickyFromSession -Hint ("esc interrupt  {0}  auto-compacting..." -f $dot)
			Update-MBWpfSticky -Status 'compacting'
		} elseif ($script:MB.IsThinking) {
			Refresh-MBWpfStickyFromSession -Hint ("esc interrupt  {0}  model thinking..." -f $dot)
			Update-MBWpfSticky -Status 'thinking'
		} elseif ($script:MB.IsWorking) {
			Refresh-MBWpfStickyFromSession -Hint ("esc interrupt  {0}  model working..." -f $dot)
			Update-MBWpfSticky -Status 'working'
		} else {
			Refresh-MBWpfStickyFromSession
			Update-MBWpfSticky -Status 'ready'
		}
	} catch {
		try { Refresh-MBWpfStickyFromSession } catch {}
	}
}

function Request-MBWpfConfirmation {
	param(
		[string]$Title,
		[string]$Details = "",
		[string]$Code = "",
		[string]$CodeLang = "ps"
	)
	if (-not (Test-MBWpfActive)) { return $null }
	$safeTitle = ([string]$Title).Trim()
	try { $safeTitle = ConvertTo-MBWpfSafeText -Text $safeTitle } catch {}
	Write-MBWpfRaw -Text "" -Color DarkGray
	Write-MBWpfApprovalBanner -Label 'approval'
	Write-MBWpfRaw -Text "" -Color DarkGray
	if (-not [string]::IsNullOrWhiteSpace($safeTitle)) {
		Write-MBWpfRaw -Text ("  {0}" -f $safeTitle) -Color White
	}
	# Body goes in a code box (highlight + Copy); short meta stays as grey notes above
	$codeText = ''
	$metaLines = New-Object System.Collections.ArrayList
	try {
		if (-not [string]::IsNullOrWhiteSpace($Code)) {
			$codeText = ([string]$Code) -replace "`r`n", "`n" -replace "`r", "`n"
		}
		if ($Details) {
			$detailLines = @(($Details -split "`r?`n"))
			foreach ($line in $detailLines) {
				$t = [string]$line
				try { $t = ConvertTo-MBWpfSafeText -Text $t } catch {}
				if ([string]::IsNullOrWhiteSpace($t)) {
					if ($metaLines.Count -gt 0) { [void]$metaLines.Add('') }
					continue
				}
				# Promote "Command: ..." into the code box when Code= was not passed
				if ([string]::IsNullOrWhiteSpace($codeText) -and $t -match '^(?i)\s*Command\s*:\s*(.+)$') {
					$codeText = [string]$Matches[1]
					continue
				}
				[void]$metaLines.Add($t)
			}
			# No Code= and multi-line / long details → put the whole details block in the code box
			if ([string]::IsNullOrWhiteSpace($codeText)) {
				$joined = ($detailLines -join "`n").Trim()
				try { $joined = ConvertTo-MBWpfSafeText -Text $joined } catch {}
				$lineN = @($detailLines | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }).Count
				if ($lineN -ge 3 -or $joined.Length -gt 160) {
					$codeText = $joined
					try { $metaLines.Clear() } catch { $metaLines = New-Object System.Collections.ArrayList }
					if ([string]::IsNullOrWhiteSpace($CodeLang) -or $CodeLang -eq 'ps') {
						$CodeLang = 'text'
					}
				}
			}
		}
	} catch {}
	foreach ($line in @($metaLines)) {
		if ([string]::IsNullOrWhiteSpace($line)) {
			Write-MBWpfRaw -Text "" -Color DarkGray
		} else {
			Write-MBWpfRaw -Text ("  {0}" -f $line) -Color DarkGray
		}
	}
	if (-not [string]::IsNullOrWhiteSpace($codeText)) {
		$lang = ([string]$CodeLang).Trim()
		if ([string]::IsNullOrWhiteSpace($lang)) { $lang = 'text' }
		# Code box header: approval title (path/tool) + lang — sanitize avoids mojibake
		$codeTitle = $safeTitle
		if ([string]::IsNullOrWhiteSpace($codeTitle)) { $codeTitle = $lang }
		Write-MBWpfSynText -Text $codeText -Lang $lang -Title $codeTitle
	}
	Write-MBWpfApprovalButtons
	Write-MBWpfRaw -Text "" -Color DarkGray
	Update-MBWpfSticky -Hint "approval: Y / N / A  (buttons or keyboard)"
	Set-MBWpfPromptEnabled -Enabled $true -Focus
	try { Focus-MBWpfPrompt } catch {}
	$script:MB.Wpf.InputResult = $null
	try {
		while ($true) {
			if ($script:MB.Wpf.ExitRequested) { return $false }
			try { Sync-MBActiveModelFromWpf } catch {}
			if ($script:MB.Wpf.InputWait.WaitOne(20)) {
				$c = ([string]$script:MB.Wpf.InputResult).Trim().ToLowerInvariant()
				$script:MB.Wpf.InputResult = $null
				Set-MBWpfPromptEnabled -Enabled $false
				try { Disable-MBWpfActiveApprovalButtons } catch {}
				switch -Regex ($c) {
					'^(y|yes)$' { $script:MB.ApprovalsGranted++; return $true }
					'^(n|no)$'  { $script:MB.ApprovalsDenied++; return $false }
					'^(a|all|yes to all|yestoall)$' {
						$script:MB.AutoApprove = $true
						try {
							if ($script:MB.Wpf) {
								$script:MB.Wpf.AutoApproveOn = $true
								$script:MB.Wpf.AutoApproveDirty = $false
								$script:MB.Wpf.LowerRightSig = ''
							}
						} catch {}
						$script:MB.ApprovalsGranted++
						$script:MB.ModeSwitch = $true
						Write-MBWpfRaw -Text "  Auto-Approve ENABLED for this session." -Color Green
						try { Update-MBWpfLiveChrome -Force } catch {}
						return $true
					}
					default {
						Write-MBWpfRaw -Text "  Enter Y, N, or A - or use the buttons." -Color Yellow
						Write-MBWpfApprovalButtons
						Set-MBWpfPromptEnabled -Enabled $true -Focus
						try { Focus-MBWpfPrompt } catch {}
					}
				}
			}
		}
	} finally {
		try { Disable-MBWpfActiveApprovalButtons } catch {}
		try { Set-MBWpfPromptEnabled -Enabled $false } catch {}
		try { Restore-MBWpfStickyAfterApproval } catch {}
	}
}

function Ensure-MBConNative {
	try {
		if (-not ('MiniBot.WpfNative.MBCon' -as [type])) {
			Add-Type -MemberDefinition @"
[DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
[DllImport("kernel32.dll")] public static extern uint GetCurrentThreadId();
[DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
[DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
[DllImport("user32.dll")] public static extern bool BringWindowToTop(IntPtr hWnd);
[DllImport("user32.dll")] public static extern bool IsWindow(IntPtr hWnd);
[DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
[DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
[DllImport("user32.dll")] public static extern bool AttachThreadInput(uint idAttach, uint idAttachTo, bool fAttach);
[DllImport("user32.dll")] public static extern bool AllowSetForegroundWindow(int dwProcessId);
[DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags);
"@ -Name 'MBCon' -Namespace 'MiniBot.WpfNative' -ErrorAction Stop
		}
	} catch {}
}

function Hide-MBNativeConsole {
	# No-op when -HideConsole:$false (or default flipped at top of script)
	try {
		if ($null -ne $script:MB_HideConsole -and -not [bool]$script:MB_HideConsole) { return }
	} catch {}
	try {
		Ensure-MBConNative
		$hwnd = [MiniBot.WpfNative.MBCon]::GetConsoleWindow()
		if ($hwnd -eq [IntPtr]::Zero) {
			try { $hwnd = [IntPtr]$script:MB_HiddenConsoleHwnd } catch { $hwnd = [IntPtr]::Zero }
		}
		if ($hwnd -ne [IntPtr]::Zero) {
			$script:MB_HiddenConsoleHwnd = $hwnd
			[void][MiniBot.WpfNative.MBCon]::ShowWindow($hwnd, 0)  # SW_HIDE
		}
	} catch {}
}

function Invoke-MBWpfBringToFront {
	param([switch]$StayTopmost)
	if (-not (Test-MBWpfActive)) { return }
	try { if ([bool]$script:MB.Wpf.ModalUi) { return } } catch {}
	try { Ensure-MBConNative } catch {}
	$keep = [bool]$StayTopmost
	try {
		if ($script:MB.Wpf) { $script:MB.Wpf.BootstrapTopmost = $keep }
	} catch {}
	$winRef = $null
	try { $winRef = $script:MB.Wpf.Window } catch { $winRef = $null }
	$d = $null
	try { $d = $script:MB.Wpf.Dispatcher } catch { $d = $null }
	if (-not $winRef -or -not $d) { return }

	# Build closure before [Action] so captured locals stick
	$sb = {
		$w = $winRef
		$keepTop = $keep
		if (-not $w) { return }
		try {
			try { if ([bool]$script:MB.Wpf.ModalUi) { return } } catch {}
			if ($w.WindowState -eq [System.Windows.WindowState]::Minimized) {
				$w.WindowState = [System.Windows.WindowState]::Normal
			}
			try { [void]$w.Show() } catch {}
			try {
				$w.Topmost = $false
				$w.Topmost = $true
			} catch { try { $w.Topmost = $true } catch {} }
			try { [void]$w.Activate() } catch {}
			try { [void]$w.Focus() } catch {}
			try {
				if ('MiniBot.WpfNative.MBCon' -as [type]) {
					$helper = New-Object System.Windows.Interop.WindowInteropHelper($w)
					$hwnd = $helper.Handle
					if ($hwnd -eq [IntPtr]::Zero) {
						try { $hwnd = $helper.EnsureHandle() } catch {}
					}
					if ($hwnd -ne [IntPtr]::Zero) {
						[void][MiniBot.WpfNative.MBCon]::ShowWindow($hwnd, 9)
						[void][MiniBot.WpfNative.MBCon]::BringWindowToTop($hwnd)
						try {
							$fg = [MiniBot.WpfNative.MBCon]::GetForegroundWindow()
							$dummy = [uint32]0
							$fgTid = [MiniBot.WpfNative.MBCon]::GetWindowThreadProcessId($fg, [ref]$dummy)
							$curTid = [MiniBot.WpfNative.MBCon]::GetCurrentThreadId()
							if ($fgTid -ne 0 -and $fgTid -ne $curTid) {
								[void][MiniBot.WpfNative.MBCon]::AttachThreadInput($curTid, $fgTid, $true)
								[void][MiniBot.WpfNative.MBCon]::SetForegroundWindow($hwnd)
								[void][MiniBot.WpfNative.MBCon]::AttachThreadInput($curTid, $fgTid, $false)
							} else {
								[void][MiniBot.WpfNative.MBCon]::SetForegroundWindow($hwnd)
							}
						} catch {
							try { [void][MiniBot.WpfNative.MBCon]::SetForegroundWindow($hwnd) } catch {}
						}
						try {
							[void][MiniBot.WpfNative.MBCon]::SetWindowPos($hwnd, [IntPtr](-1), 0, 0, 0, 0, ([uint32](0x0001 -bor 0x0002 -bor 0x0040)))
							if (-not $keepTop) {
								[void][MiniBot.WpfNative.MBCon]::SetWindowPos($hwnd, [IntPtr](-2), 0, 0, 0, 0, ([uint32](0x0001 -bor 0x0002 -bor 0x0040)))
							}
						} catch {}
					}
				}
			} catch {}
			if (-not $keepTop) {
				try {
					$w.Topmost = $true
					$w.Topmost = $false
				} catch { try { $w.Topmost = $false } catch {} }
				try { [void]$w.Activate() } catch {}
			}
		} catch {}
	}.GetNewClosure()
	$act = [Action]$sb

	try {
		if ($d.CheckAccess()) { & $sb }
		else { [void]$d.Invoke($act, [System.Windows.Threading.DispatcherPriority]::Send) }
	} catch {
		try { Invoke-MBWpf -Action $sb } catch {}
	}
}

function Clear-MBWpfBootstrapTopmost {
	if (-not (Test-MBWpfActive)) { return }
	try {
		if ($script:MB.Wpf) { $script:MB.Wpf.BootstrapTopmost = $false }
	} catch {}
	try { Ensure-MBConNative } catch {}
	$winRef = $null
	try { $winRef = $script:MB.Wpf.Window } catch { $winRef = $null }
	$d = $null
	try { $d = $script:MB.Wpf.Dispatcher } catch { $d = $null }
	if (-not $winRef -or -not $d) { return }

	$sb = {
		$w = $winRef
		if (-not $w) { return }
		try {
			$w.Topmost = $true
			$w.Topmost = $false
			$w.Topmost = $false
		} catch {
			try { $w.Topmost = $false } catch {}
		}
		try {
			if ('MiniBot.WpfNative.MBCon' -as [type]) {
				$helper = New-Object System.Windows.Interop.WindowInteropHelper($w)
				$hwnd = $helper.Handle
				if ($hwnd -ne [IntPtr]::Zero) {
					[void][MiniBot.WpfNative.MBCon]::SetWindowPos(
						$hwnd, [IntPtr](-2), 0, 0, 0, 0,
						([uint32](0x0001 -bor 0x0002 -bor 0x0040))
					)
				}
			}
		} catch {}
	}.GetNewClosure()
	$act = [Action]$sb

	try {
		if ($d.CheckAccess()) { & $sb }
		else { [void]$d.Invoke($act, [System.Windows.Threading.DispatcherPriority]::Send) }
	} catch {
		try { Invoke-MBWpf -Action $sb } catch {}
	}

	try {
		$sb2 = {
			try {
				$w2 = $winRef
				if (-not $w2) { return }
				if ($w2.Topmost) {
					$w2.Topmost = $true
					$w2.Topmost = $false
				}
				try {
					if ('MiniBot.WpfNative.MBCon' -as [type]) {
						$helper = New-Object System.Windows.Interop.WindowInteropHelper($w2)
						$hwnd = $helper.Handle
						if ($hwnd -ne [IntPtr]::Zero) {
							[void][MiniBot.WpfNative.MBCon]::SetWindowPos(
								$hwnd, [IntPtr](-2), 0, 0, 0, 0,
								([uint32](0x0001 -bor 0x0002 -bor 0x0040))
							)
						}
					}
				} catch {}
			} catch {}
		}.GetNewClosure()
		[void]$d.BeginInvoke([System.Windows.Threading.DispatcherPriority]::ApplicationIdle, [Action]$sb2)
	} catch {}
}


function Start-MBWpfHost {
	if ($script:MB.Wpf -and $script:MB.Wpf.Ready) { return $true }

	if (-not (Test-MBWpfDotNetReady)) {
		try {
			$dotnetchecker = New-Object -ComObject Wscript.Shell
			$dotnetchecker.Popup(
				"dotNET 3.0 or higher is required for the MiniBot WPF host.",
				0,
				'MiniBot WPF',
				0x0
			) | Out-Null
		} catch {}
		Write-Warning "WPF requires .NET Framework 3.0+; not starting WPF host."
		return $false
	}

	if (-not (Test-MBWpfAvailable)) { return $false }

	# Shared state for UI and agent runspaces
	$wpf = [hashtable]::Synchronized(@{
		Ready         = $false
		Failed        = $false
		FailMsg       = ''
		Dispatcher    = $null
		Window        = $null
		Log           = $null
		Prompt        = $null
		HdrLine1      = $null
		HdrLine1Shadow = $null
		HdrLine2      = $null
		HdrLine2Shadow = $null
		HdrToolGroups = $null
		ToolGroupsFp  = ''
		ToolGroupsBuilt = $false
		ToolGroupsDirty = $true
		ToolGroupsData  = $null
		TaskBoardSticky = $null
		TaskBoardStickyScroll = $null
		TaskBoardStickyInner = $null
		TaskBoardStickyHeader = $null
		TaskBoardStickyItems = $null
		TaskBoardStickyGoal = $null
		TaskBoardStickySum = $null
		TaskBoardStickyLabel = $null
		TaskBoardMaxScrollH = 260.0
		TaskBoardPulseEls = $null
		TaskBoardExpanded = $false
		TaskBoardRetractTimer = $null
		TaskBoardSeqCounter = 0
		TaskBoardAppliedSeq = 0
		TaskBoardWantSeq = 0
		TaskBoardLiveGen = 0
		TaskBoardLiveSnap = $null
		TaskBoardPaintRetry = 0
		TaskBoardPaintBusy = $false
		TaskBoardPaintQueued = $false
		TaskBoardPaintUrgent = $false
		TaskBoardLastFp = ''
		PendingTaskBoard = $null
		PendingClearLog = $false
		HdrBrandAccent = $null
		BrandAccentShimmerOn = $false
		BrandAccentTranslate = $null
		HdrPoweredBy  = $null
		HdrPoweredByShadow = $null
		HdrPoweredByHost = $null
		HdrAutoCompact = $null
		HdrAutoCompactShadow = $null
		HdrLeft       = $null
		HdrCenter     = $null
		HdrRight      = $null
		HintBar       = $null
		HintBarBorder = $null
		StatusDot     = $null
		LowerCenter   = $null
		LowerRight    = $null
		CtxBarFill    = $null
		CtxPctText    = $null
		CtxTokText    = $null
		CtxBarMaxW    = 120
		MonoFont      = $null
		EmojiFont     = $null
		LogMaxLineChars = 0
		LogLineCharRun  = 0   # chars on the current (open) paragraph
		LogWordWrap     = $true
		WordWrapToggle  = $null
		ReplyStartBlock = -1
		ActiveCodeBox   = $null
		ActiveCodeBorder = $null
		StatusMode    = 'ready'     # ready | thinking | working | compacting
		StatusLabel   = 'ready'
		SpinIdx       = 0
		SpinLastTick  = 0
		StatusBusySince = 0         # Environment.TickCount when busy mode started
		StatusTimer   = $null       # TextBlock for elapsed seconds
		InputWait     = New-Object System.Threading.AutoResetEvent $false
		InputResult   = $null
		PromptArmed   = $false
		ExitRequested = $false
		# all exits hard-kill the process (single-instance lock)
		SoftClose     = $false
		CloseKind     = ''          # always treated as user_x on close
		ForceProcessExit = $false
		AuthActive    = $false      # true while login overlay is visible (blocks prompt focus)
		AuthFocusTicks = 0          # re-apply username focus for a few timer frames
		AuthNeedActivate = $false   # keep forcing OS foreground until window is active
		BootstrapTopmost = $true    # Topmost until main screen loads; then cleared
		ModalUi       = $false      # true while file picker / modal blocks Activate steals
		History       = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
		HistIndex     = -1
		ReadyWait     = New-Object System.Threading.ManualResetEvent $false
		InterruptFlag = $false
		SendBtn       = $null
		SendMode      = 'send'      # send | stop
		AgentName     = [string]$AgentName
		Version       = [string]$Version
		ModelAlias    = $(try { [string]$ModelAlias } catch { '' })
		ActiveModel   = $(try { [string]$script:MB.ActiveModel } catch { try { [string]$Model } catch { '' } })
		ActiveModelBase = $(try { [string]$script:MB.ActiveModelBase } catch { '' })
		ActiveModelKey = $(try { [string]$script:MB.ActiveModelKey } catch { '' })
		RemoteModels  = $(try { @($script:MB.RemoteModels) } catch { @() })
		RemoteModelEntries = $(try { @($script:MB.RemoteModelEntries) } catch { @() })
		ExtraApiBases = $(try { @($script:MB.ExtraApiBases) } catch { @() })
		ExtraApiKeys = $(try { if ($script:MB.ExtraApiKeys -is [hashtable]) { $script:MB.ExtraApiKeys } else { @{} } } catch { @{} })
		ExtraApiAuth = $(try { if ($script:MB.ExtraApiAuth -is [hashtable]) { $script:MB.ExtraApiAuth } else { @{} } } catch { @{} })
		NpmUser = $(try { [string]$script:MB.NpmUser } catch { '' })
		NpmPass = $(try { [string]$script:MB.NpmPass } catch { '' })
		RemoteModelsSeq = 0
		RemoteModelsSeqApplied = 0
		RemoteModelsRefreshWanted = $false
		PendingAddBaseUrl = ''
		PendingAddBaseApiKey = ''
		PendingAddBaseAuthMode = 'apikey'
		PendingAddBaseDirty = $false
		PendingAddBaseResult = $null
		AddEndpointOverlay = $null
		AddEndpointBusy = $false
		KnownApiBases = $(try { @(Get-MBLiveApiBases) } catch { @() })
		ModelDirty    = $false
		ModelPickerUpdating = $false
		AutoCompactOn = $(try { [bool]$script:MB.AutoCompact } catch { $true })
		AutoApproveOn = $(try { [bool]$script:MB.AutoApprove } catch { $false })
		AutoApproveDirty = $false
		AutoCompactDirty = $false
		MaxTurnsSetting = $(try { [int]$script:MB.MaxTurns } catch { try { [int]$MaxTurns } catch { 30 } })
		MaxTurnsDirty = $false
		UnlimitedTurns = $(try { [bool]$script:MB.UnlimitedTurns } catch { $false })
		UnlimitedTurnsDirty = $false
		TurnsLeft = $(try { [int]$script:MB.TurnsLeft } catch { try { [int]$MaxTurns } catch { 30 } })
		TurnsUsed = 0
		TurnsInFlight = $false
		AaTurnsNumTb = $null
		AaTurnsMidHost = $null
		AaInfinityHost = $null
		AaInfinityPath = $null
		AaApprovePopup = $null
		AaLabel = $null
		AaPopupWantOpen = $false
		AaUnlimOffSeg = $null
		AaUnlimOnSeg = $null
		AaUnlimHit = $null
		BtnAaMinus = $null
		BtnAaPlus = $null
		ToolsUsedTb = $null
		PendingUiCommand = $null
		PendingWindowTitle = $null
		CurrentCwd    = $(try { [string]$script:MB.WorkingDir } catch { '' })
		PendingCwd    = ''
		CwdDirty      = $false
		CwdPopup      = $null
		LowerRightSig = ''
		Ps            = $null
		Runspace      = $null
		WriteQueue    = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
		PendingSticky = $null
		PendingPromptEnabled = $null
		PendingPromptFocus = $false   # true => focus PromptBox when arming
		ActiveApprovalHost = $null    # inline Yes/No/All button strip in log
		NeedPathBudgetRefresh = $false
		LastPathBudgetTick = 0
		BrushCache    = @{}
		MdStretchElements = New-Object System.Collections.ArrayList
		CredWait      = New-Object System.Threading.ManualResetEvent $false
		CredResult    = $null
		AuthOverlay   = $null
		AuthUser      = $null
		AuthPass      = $null
		AuthError     = $null
		AuthTitle     = $null
		AuthSubtitle  = $null
		AuthOk        = $null
		AuthCancel    = $null
		AuthSaveCreds = $null
		ConfirmWait   = New-Object System.Threading.ManualResetEvent $false
		ConfirmResult = $null
		ConfirmOverlay = $null
		ConfirmTitle  = $null
		ConfirmPrompt = $null
		ConfirmYes    = $null
		ConfirmNo     = $null
		ConfirmAccentBar = $null
		SessionPickerWait = New-Object System.Threading.ManualResetEvent $false
		SessionPickerResult = $null
		SessionPickerMode = 'Open'
		SessionPickerRows = $null
		SessionPickerReload = $null
		SessionPickerOverlay = $null
		InitStoreCreds = $false
		DebugLogPath  = (Get-MBDebugLogPath)
		DebugLogEnabled = [bool]$(try { [bool]$script:MB.DebugLogEnabled } catch { $false })
	})
	$script:MB.Wpf = $wpf
	# Default OSD volume (0–1); STA AddScript / StartInline read this from the bag
	try { $wpf['VideoDefaultVolume'] = 1.0 } catch {}
	# Fresh-bind video helpers as UNBOUND scriptblocks + source text for STA rebuild
	try {
		Set-MBVideoScriptGlobals | Out-Null
		Register-MBVideoApi | Out-Null
		$apiV = $null
		try { $apiV = $global:MB_VideoApi } catch {}
		if ($null -ne $apiV) {
			if ($null -ne $apiV['StartInline']) { $wpf['VideoStartInline'] = $apiV['StartInline'] }
			if ($null -ne $apiV['StopInline']) { $wpf['VideoStopInline'] = $apiV['StopInline'] }
			if ($null -ne $apiV['Toggle']) { $wpf['VideoToggle'] = $apiV['Toggle'] }
			if ($null -ne $apiV['PopOut']) { $wpf['VideoPopOut'] = $apiV['PopOut'] }
			if ($null -ne $apiV['Resolve']) { $wpf['VideoResolve'] = $apiV['Resolve'] }
			$wpf['VideoApi'] = $apiV
		}
		# Source text — STA AddScript re-[scriptblock]::Create these so New-Object works there
		if ($global:MB_Video_StartInlineText) { $wpf['VideoStartInlineText'] = $global:MB_Video_StartInlineText }
		if ($global:MB_Video_StopInlineText) { $wpf['VideoStopInlineText'] = $global:MB_Video_StopInlineText }
		if ($global:MB_Video_ToggleText) { $wpf['VideoToggleText'] = $global:MB_Video_ToggleText }
		if ($global:MB_Video_PopOutText) { $wpf['VideoPopOutText'] = $global:MB_Video_PopOutText }
		if ($global:MB_Video_ResolveText) { $wpf['VideoResolveText'] = $global:MB_Video_ResolveText }
	} catch {}
	# Shared robot path catalog for UI runspace
	try {
		$wpf.RobotCatalog = Get-MBRobotPathCatalog
		$wpf.RobotGeomCache = @{}
		$wpf.RobotMood = ''
		$wpf.SetRobotMood = $null
	} catch {}
	try { Write-MBDebugLog -Step 'WPF_HOST_STARTING' -Detail $wpf.DebugLogPath } catch {}

	$rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
	$rs.ApartmentState = [System.Threading.ApartmentState]::STA
	$rs.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
	$rs.Open()
	$ps = [PowerShell]::Create()
	$ps.Runspace = $rs
	$wpf.Runspace = $rs
	$wpf.Ps = $ps

	[void]$ps.AddScript({
		param($W)
		try {
			Add-Type -AssemblyName PresentationFramework
			Add-Type -AssemblyName PresentationCore
			Add-Type -AssemblyName WindowsBase
			Add-Type -AssemblyName System.Xaml

			# Rebuild video Start/Stop/etc in THIS STA runspace (unbound). Bag scriptblocks from
			# the main runspace lose New-Object/Test-Path; Create() here fixes that.
			try {
				if ($W -is [hashtable]) {
					if (-not $W.ContainsKey('VideoDefaultVolume') -or $null -eq $W['VideoDefaultVolume']) {
						$W['VideoDefaultVolume'] = 1.0
					}
					foreach ($pair in @(
						@{ T = 'VideoStartInlineText'; K = 'VideoStartInline' },
						@{ T = 'VideoStopInlineText';  K = 'VideoStopInline' },
						@{ T = 'VideoToggleText';      K = 'VideoToggle' },
						@{ T = 'VideoPopOutText';      K = 'VideoPopOut' },
						@{ T = 'VideoResolveText';     K = 'VideoResolve' }
					)) {
						$txt = $W[$pair.T]
						if ([string]::IsNullOrWhiteSpace([string]$txt)) { continue }
						try {
							$W[$pair.K] = [scriptblock]::Create([string]$txt)
						} catch {}
					}
					try {
						if ($W['VideoApi'] -is [hashtable]) {
							if ($W['VideoStartInline']) { $W['VideoApi']['StartInline'] = $W['VideoStartInline'] }
							if ($W['VideoStopInline'])  { $W['VideoApi']['StopInline']  = $W['VideoStopInline'] }
							if ($W['VideoToggle'])      { $W['VideoApi']['Toggle']      = $W['VideoToggle'] }
							if ($W['VideoPopOut'])      { $W['VideoApi']['PopOut']      = $W['VideoPopOut'] }
							if ($W['VideoResolve'])     { $W['VideoApi']['Resolve']     = $W['VideoResolve'] }
						}
					} catch {}
				}
			} catch {}

			$xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        xmlns:shell="clr-namespace:System.Windows.Shell;assembly=PresentationFramework"
        Title="MiniBot"
        Width="980" Height="640"
        MinWidth="640" MinHeight="400"
        WindowStartupLocation="CenterScreen"
        ShowActivated="True"
        Topmost="True"
        WindowStyle="None"
        ResizeMode="CanResize"
        AllowsTransparency="True"
        Background="Transparent"
        Foreground="#C8C8D0"
        FontFamily="Consolas, Cascadia Mono, Courier New"
        FontSize="13">
  <!-- Transparent HWND so MainChromeBorder CornerRadius shows (opaque bg painted square corners). -->
  <shell:WindowChrome.WindowChrome>
    <shell:WindowChrome CaptionHeight="36"
                        ResizeBorderThickness="6"
                        GlassFrameThickness="0"
                        CornerRadius="8,8,8,8"
                        UseAeroCaptionButtons="False"/>
  </shell:WindowChrome.WindowChrome>
  <Window.Resources>
    <!-- NoMouseOver button template -->
    <ControlTemplate x:Key="NoMouseOverButtonTemplate" TargetType="Button">
      <Border Background="{TemplateBinding Background}"
              BorderBrush="{TemplateBinding BorderBrush}"
              BorderThickness="{TemplateBinding BorderThickness}"
              Padding="{TemplateBinding Padding}"
              CornerRadius="4"
              SnapsToDevicePixels="True">
        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
      </Border>
      <ControlTemplate.Triggers>
        <Trigger Property="IsEnabled" Value="False">
          <Setter Property="Opacity" Value="0.45"/>
        </Trigger>
      </ControlTemplate.Triggers>
    </ControlTemplate>
 <!-- Dark scrollbar -->
    <SolidColorBrush x:Key="MbScrollTrack" Color="#1A1A1E"/>
    <SolidColorBrush x:Key="MbScrollThumb" Color="#3A3A42"/>
    <SolidColorBrush x:Key="MbScrollThumbHover" Color="#52525C"/>
    <SolidColorBrush x:Key="MbScrollThumbDrag" Color="#6A6A76"/>
    <SolidColorBrush x:Key="MbScrollBtn" Color="#2A2A30"/>
    <Style x:Key="MbScrollBarThumb" TargetType="Thumb">
      <Setter Property="OverridesDefaultStyle" Value="True"/>
      <Setter Property="IsTabStop" Value="False"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Thumb">
            <Border x:Name="Bd" Background="{StaticResource MbScrollThumb}" CornerRadius="3" Margin="1"/>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="{StaticResource MbScrollThumbHover}"/>
              </Trigger>
              <Trigger Property="IsDragging" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="{StaticResource MbScrollThumbDrag}"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="MbScrollRepeat" TargetType="RepeatButton">
      <Setter Property="OverridesDefaultStyle" Value="True"/>
      <Setter Property="Focusable" Value="False"/>
      <Setter Property="IsTabStop" Value="False"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="RepeatButton">
            <Border Background="{StaticResource MbScrollTrack}"/>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="MbDarkCheckBox" TargetType="CheckBox">
      <Setter Property="Foreground" Value="#C8C8D0"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Focusable" Value="False"/>
      <Setter Property="SnapsToDevicePixels" Value="True"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="CheckBox">
            <StackPanel Orientation="Horizontal" Background="Transparent">
              <Border x:Name="Box" Width="13" Height="13" Background="#121216"
                      BorderBrush="#52525C" BorderThickness="1" CornerRadius="2"
                      VerticalAlignment="Center" Margin="0,0,6,0">
                <Path x:Name="CheckMark" Data="M1.5,6.5 L4.8,10 L11.5,2.5"
                      Stroke="#9ECE6A" StrokeThickness="1.7" Visibility="Collapsed"
                      Stretch="None" HorizontalAlignment="Center" VerticalAlignment="Center"/>
              </Border>
              <ContentPresenter VerticalAlignment="Center" RecognizesAccessKey="True"/>
            </StackPanel>
            <ControlTemplate.Triggers>
              <Trigger Property="IsChecked" Value="True">
                <Setter TargetName="CheckMark" Property="Visibility" Value="Visible"/>
                <Setter TargetName="Box" Property="BorderBrush" Value="#6A6A76"/>
                <Setter TargetName="Box" Property="Background" Value="#1A1A1E"/>
              </Trigger>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Box" Property="BorderBrush" Value="#8A8A96"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <!-- Login primary button -->
    <Style x:Key="MbAuthPrimaryBtn" TargetType="Button">
      <Setter Property="Background" Value="#4A4A56"/>
      <Setter Property="Foreground" Value="#E0E0E8"/>
      <Setter Property="BorderThickness" Value="0"/>
      <Setter Property="FontWeight" Value="Bold"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="SnapsToDevicePixels" Value="True"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border x:Name="Bd" Background="{TemplateBinding Background}"
                    CornerRadius="3" SnapsToDevicePixels="True">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="#5C5C6A"/>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="#3A3A48"/>
              </Trigger>
              <Trigger Property="IsEnabled" Value="False">
                <Setter TargetName="Bd" Property="Opacity" Value="0.5"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <!-- Login secondary button -->
    <Style x:Key="MbAuthSecondaryBtn" TargetType="Button">
      <Setter Property="Background" Value="#2A2A30"/>
      <Setter Property="Foreground" Value="#C8C8D0"/>
      <Setter Property="BorderBrush" Value="#3A3A42"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="SnapsToDevicePixels" Value="True"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border x:Name="Bd" Background="{TemplateBinding Background}"
                    BorderBrush="{TemplateBinding BorderBrush}"
                    BorderThickness="{TemplateBinding BorderThickness}"
                    CornerRadius="3" SnapsToDevicePixels="True">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="#363640"/>
                <Setter TargetName="Bd" Property="BorderBrush" Value="#5A5A66"/>
              </Trigger>
              <Trigger Property="IsPressed" Value="True">
                <Setter TargetName="Bd" Property="Background" Value="#222228"/>
                <Setter TargetName="Bd" Property="BorderBrush" Value="#4A4A56"/>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style TargetType="ScrollBar">
      <Setter Property="Background" Value="{StaticResource MbScrollTrack}"/>
      <Setter Property="Foreground" Value="{StaticResource MbScrollThumb}"/>
      <Setter Property="Width" Value="12"/>
      <Setter Property="MinWidth" Value="12"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ScrollBar">
            <Grid Background="{StaticResource MbScrollTrack}">
              <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
                <RowDefinition Height="Auto"/>
              </Grid.RowDefinitions>
              <Border Grid.Row="0" Height="12" Background="{StaticResource MbScrollBtn}"/>
              <Track x:Name="PART_Track" Grid.Row="1" IsDirectionReversed="True">
                <Track.DecreaseRepeatButton>
                  <RepeatButton Command="ScrollBar.PageUpCommand" Style="{StaticResource MbScrollRepeat}"/>
                </Track.DecreaseRepeatButton>
                <Track.Thumb>
                  <Thumb Style="{StaticResource MbScrollBarThumb}"/>
                </Track.Thumb>
                <Track.IncreaseRepeatButton>
                  <RepeatButton Command="ScrollBar.PageDownCommand" Style="{StaticResource MbScrollRepeat}"/>
                </Track.IncreaseRepeatButton>
              </Track>
              <Border Grid.Row="2" Height="12" Background="{StaticResource MbScrollBtn}"/>
            </Grid>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
      <Style.Triggers>
        <Trigger Property="Orientation" Value="Horizontal">
          <Setter Property="Width" Value="Auto"/>
          <Setter Property="Height" Value="12"/>
          <Setter Property="MinHeight" Value="12"/>
          <Setter Property="Template">
            <Setter.Value>
              <ControlTemplate TargetType="ScrollBar">
                <Grid Background="{StaticResource MbScrollTrack}">
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                  </Grid.ColumnDefinitions>
                  <Border Grid.Column="0" Width="12" Background="{StaticResource MbScrollBtn}"/>
                  <Track x:Name="PART_Track" Grid.Column="1" IsDirectionReversed="False">
                    <Track.DecreaseRepeatButton>
                      <RepeatButton Command="ScrollBar.PageLeftCommand" Style="{StaticResource MbScrollRepeat}"/>
                    </Track.DecreaseRepeatButton>
                    <Track.Thumb>
                      <Thumb Style="{StaticResource MbScrollBarThumb}"/>
                    </Track.Thumb>
                    <Track.IncreaseRepeatButton>
                      <RepeatButton Command="ScrollBar.PageRightCommand" Style="{StaticResource MbScrollRepeat}"/>
                    </Track.IncreaseRepeatButton>
                  </Track>
                  <Border Grid.Column="2" Width="12" Background="{StaticResource MbScrollBtn}"/>
                </Grid>
              </ControlTemplate>
            </Setter.Value>
          </Setter>
        </Trigger>
      </Style.Triggers>
    </Style>
 <!-- Dark ScrollViewer -->
    <Style TargetType="ScrollViewer">
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="ScrollViewer">
            <Grid Background="{TemplateBinding Background}">
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
              </Grid.ColumnDefinitions>
              <Grid.RowDefinitions>
                <RowDefinition Height="*"/>
                <RowDefinition Height="Auto"/>
              </Grid.RowDefinitions>
              <ScrollContentPresenter Grid.Column="0" Grid.Row="0"
                                      Margin="{TemplateBinding Padding}"
                                      Content="{TemplateBinding Content}"
                                      ContentTemplate="{TemplateBinding ContentTemplate}"
                                      CanContentScroll="{TemplateBinding CanContentScroll}"/>
              <ScrollBar x:Name="PART_VerticalScrollBar" Grid.Column="1" Grid.Row="0"
                         Orientation="Vertical"
                         ViewportSize="{TemplateBinding ViewportHeight}"
                         Maximum="{TemplateBinding ScrollableHeight}"
                         Value="{TemplateBinding VerticalOffset}"
                         Visibility="{TemplateBinding ComputedVerticalScrollBarVisibility}"/>
              <ScrollBar x:Name="PART_HorizontalScrollBar" Grid.Column="0" Grid.Row="1"
                         Orientation="Horizontal"
                         ViewportSize="{TemplateBinding ViewportWidth}"
                         Maximum="{TemplateBinding ScrollableWidth}"
                         Value="{TemplateBinding HorizontalOffset}"
                         Visibility="{TemplateBinding ComputedHorizontalScrollBarVisibility}"/>
 <!-- Scrollbar corner -->
              <Rectangle Grid.Column="1" Grid.Row="1" Fill="{StaticResource MbScrollTrack}"/>
            </Grid>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
  </Window.Resources>
  <!-- WindowRoot: chrome + full-window overlays as SIBLINGS (not inside 2-row title/body grid). -->
  <Grid x:Name="WindowRoot">
  <!-- Outer rounded chrome -->
  <Border x:Name="MainChromeBorder" BorderBrush="#2A2A30" BorderThickness="1" Background="#121216"
          CornerRadius="8" ClipToBounds="True" SnapsToDevicePixels="True">
    <Grid x:Name="RootOuter">
      <Grid.RowDefinitions>
        <RowDefinition Height="36"/>
        <RowDefinition Height="*"/>
      </Grid.RowDefinitions>
 <!-- Custom titlebar -->
      <Border x:Name="CustomTitleBar" Grid.Row="0" Background="#2A2A30" BorderBrush="#3A3A42"
              BorderThickness="0,0,0,1" Padding="10,0,0,0" CornerRadius="8,8,0,0"
              SnapsToDevicePixels="True">
        <Grid>
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="*"/>
            <ColumnDefinition Width="Auto"/>
            <ColumnDefinition Width="Auto"/>
          </Grid.ColumnDefinitions>
          <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center" Margin="0,0,8,0">
            <!-- Titlebar robot -->
            <Grid x:Name="TitleRobotHost" Width="26" Height="26" Margin="4,0,0,0"
                  VerticalAlignment="Center" ToolTip="MiniBot"
                  shell:WindowChrome.IsHitTestVisibleInChrome="True">
              <Path x:Name="TitleRobotPath" Width="22" Height="22" Stretch="Uniform"
                    HorizontalAlignment="Center" VerticalAlignment="Center"
                    Data="M12,2A2,2 0 0,1 14,4C14,4.74 13.6,5.39 13,5.73V7H14A7,7 0 0,1 21,14H22A1,1 0 0,1 23,15V18A1,1 0 0,1 22,19H21V20A2,2 0 0,1 19,22H5A2,2 0 0,1 3,20V19H2A1,1 0 0,1 1,18V15A1,1 0 0,1 2,14H3A7,7 0 0,1 10,7H11V5.73C10.4,5.39 10,4.74 10,4A2,2 0 0,1 12,2M7.5,13A2.5,2.5 0 0,0 5,15.5A2.5,2.5 0 0,0 7.5,18A2.5,2.5 0 0,0 10,15.5A2.5,2.5 0 0,0 7.5,13M16.5,13A2.5,2.5 0 0,0 14,15.5A2.5,2.5 0 0,0 16.5,18A2.5,2.5 0 0,0 19,15.5A2.5,2.5 0 0,0 16.5,13Z">
                <Path.Fill>
                  <LinearGradientBrush StartPoint="0.15,0" EndPoint="0.9,1">
                    <GradientStop x:Name="TitleRobotStop0" Color="#C8C8D0" Offset="0"/>
                    <GradientStop x:Name="TitleRobotStop1" Color="#6A6A74" Offset="0.48"/>
                    <GradientStop x:Name="TitleRobotStop2" Color="#3A3A42" Offset="1"/>
                  </LinearGradientBrush>
                </Path.Fill>
                <Path.Effect>
                  <DropShadowEffect x:Name="TitleRobotShadow" Color="#000000" BlurRadius="3.5" ShadowDepth="1.25"
                                    Opacity="0.72" Direction="315"/>
                </Path.Effect>
                <Path.RenderTransform>
                  <TranslateTransform x:Name="TitleRobotTranslate" X="0" Y="0"/>
                </Path.RenderTransform>
              </Path>
            </Grid>
            <Ellipse x:Name="TitleDotBrand" Width="3.5" Height="3.5" Fill="#8A8A96"
                     Margin="9,1,9,0" VerticalAlignment="Center" Opacity="0.9"
                     SnapsToDevicePixels="False">
              <Ellipse.Effect>
                <DropShadowEffect Color="#000000" BlurRadius="1.5" ShadowDepth="0.5" Opacity="0.45" Direction="270"/>
              </Ellipse.Effect>
            </Ellipse>
            <!-- Brand name -->
            <StackPanel x:Name="TitleBrand" Orientation="Horizontal" VerticalAlignment="Center" MaxWidth="240">
              <TextBlock Text="[" Foreground="#A0A0AA" FontSize="13" FontWeight="SemiBold"
                         VerticalAlignment="Center"/>
              <Grid VerticalAlignment="Center" MaxWidth="140">
                <TextBlock x:Name="TitleBrandNameShadow" Text="MiniBot" Foreground="#000000"
                           FontSize="13" FontWeight="SemiBold"
                           TextTrimming="CharacterEllipsis" MaxWidth="140"
                           Margin="1.2,1.2,0,0" Opacity="0.9" IsHitTestVisible="False">
                  <TextBlock.Effect>
                    <DropShadowEffect Color="#000000" BlurRadius="3.5" ShadowDepth="0"
                                      Opacity="0.85" Direction="0"/>
                  </TextBlock.Effect>
                </TextBlock>
                <TextBlock x:Name="TitleBrandName" Text="MiniBot" Foreground="#B80F0A"
                           FontSize="13" FontWeight="SemiBold"
                           TextTrimming="CharacterEllipsis" MaxWidth="140">
                  <TextBlock.Effect>
                    <DropShadowEffect Color="#FF3A1A" BlurRadius="10" ShadowDepth="0"
                                      Opacity="0.72" Direction="0"/>
                  </TextBlock.Effect>
                </TextBlock>
              </Grid>
              <TextBlock Text="-" Foreground="#A0A0AA" FontSize="13" FontWeight="SemiBold"
                         VerticalAlignment="Center"/>
              <Grid VerticalAlignment="Center">
                <TextBlock Text="Agent" Foreground="#000000" FontSize="13" FontWeight="SemiBold"
                           Margin="1.2,1.2,0,0" Opacity="0.9" IsHitTestVisible="False">
                  <TextBlock.Effect>
                    <DropShadowEffect Color="#000000" BlurRadius="3.5" ShadowDepth="0"
                                      Opacity="0.85" Direction="0"/>
                  </TextBlock.Effect>
                </TextBlock>
                <TextBlock Text="Agent" Foreground="#B80F0A" FontSize="13" FontWeight="SemiBold">
                  <TextBlock.Effect>
                    <DropShadowEffect Color="#FF3A1A" BlurRadius="10" ShadowDepth="0"
                                      Opacity="0.55" Direction="0"/>
                  </TextBlock.Effect>
                </TextBlock>
              </Grid>
              <TextBlock Text="]" Foreground="#A0A0AA" FontSize="13" FontWeight="SemiBold"
                         VerticalAlignment="Center"/>
            </StackPanel>
            <Ellipse x:Name="TitleDotPath" Width="3.5" Height="3.5" Fill="#8A8A96"
                     Margin="9,1,9,0" VerticalAlignment="Center" Opacity="0.9"
                     SnapsToDevicePixels="False">
              <Ellipse.Effect>
                <DropShadowEffect Color="#000000" BlurRadius="1.5" ShadowDepth="0.5" Opacity="0.45" Direction="270"/>
              </Ellipse.Effect>
            </Ellipse>
            <Grid VerticalAlignment="Center" MaxWidth="520">
              <TextBlock x:Name="TitlePathShadow" Text="" Foreground="#000000" FontSize="12"
                         VerticalAlignment="Center" Margin="1.2,1.2,0,0" Opacity="0.9"
                         TextTrimming="CharacterEllipsis" MaxWidth="520" IsHitTestVisible="False">
                <TextBlock.Effect>
                  <DropShadowEffect Color="#000000" BlurRadius="3.5" ShadowDepth="0"
                                    Opacity="0.85" Direction="0"/>
                </TextBlock.Effect>
              </TextBlock>
              <TextBlock x:Name="TitlePath" Text="" Foreground="#C8C8D0" FontSize="12"
                         VerticalAlignment="Center" Cursor="Hand"
                         TextTrimming="CharacterEllipsis" MaxWidth="520"
                         shell:WindowChrome.IsHitTestVisibleInChrome="True"/>
            </Grid>
          </StackPanel>
          <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center"
                      HorizontalAlignment="Right" Margin="12,0,10,0" MaxWidth="320">
            <TextBlock x:Name="TitlePoweredByLabel" Text="PoweredBy: " Foreground="#8A8A96" FontSize="12"
                       VerticalAlignment="Center" Margin="0,0,4,0"/>
            <!-- Themed model chip (tool-group style): click toggles dark ContextMenu -->
            <Border x:Name="TitleModelPicker" Background="#3A3A42" BorderBrush="#4A4A56"
                    BorderThickness="1" CornerRadius="3" Padding="7,2,6,2"
                    VerticalAlignment="Center" Cursor="Hand" MaxWidth="230"
                    SnapsToDevicePixels="True"
                    shell:WindowChrome.IsHitTestVisibleInChrome="True">
              <StackPanel Orientation="Horizontal">
                <TextBlock x:Name="TitleModelPickerText" Text="Select Model"
                           Foreground="#BB9AF7" FontSize="11" FontWeight="SemiBold"
                           VerticalAlignment="Center" TextTrimming="CharacterEllipsis"
                           MaxWidth="195"/>
                <TextBlock Text=" &#x25BE;" Foreground="#8A8A96" FontSize="10"
                           VerticalAlignment="Center" Margin="1,0,0,0"/>
              </StackPanel>
            </Border>
            <TextBlock x:Name="TitlePoweredBy" Visibility="Collapsed"/>
            <TextBlock x:Name="TitlePoweredByShadow" Visibility="Collapsed"/>
          </StackPanel>
          <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Stretch">
            <!-- Window buttons -->
            <Button x:Name="TitleBtnMin" Width="46" Height="36"
                    Background="Transparent" BorderThickness="0" Cursor="Hand"
                    Focusable="False" shell:WindowChrome.IsHitTestVisibleInChrome="True"
                    ToolTip="Minimize" Template="{StaticResource NoMouseOverButtonTemplate}">
              <Path x:Name="TitleBtnMinPath" Width="10" Height="1" Stretch="Fill"
                    Stroke="#C8C8D0" StrokeThickness="1" Data="M0,0 L10,0"
                    HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Button>
            <Button x:Name="TitleBtnMax" Width="46" Height="36"
                    Background="Transparent" BorderThickness="0" Cursor="Hand"
                    Focusable="False" shell:WindowChrome.IsHitTestVisibleInChrome="True"
                    ToolTip="Maximize" Template="{StaticResource NoMouseOverButtonTemplate}">
              <Path x:Name="TitleBtnMaxPath" Width="10" Height="10" Stretch="Uniform"
                    Stroke="#C8C8D0" StrokeThickness="1" Fill="Transparent"
                    Data="M0.5,0.5 H9.5 V9.5 H0.5 Z"
                    HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Button>
            <Button x:Name="TitleBtnClose" Width="46" Height="36"
                    Background="Transparent" BorderThickness="0" Cursor="Hand"
                    Focusable="False" shell:WindowChrome.IsHitTestVisibleInChrome="True"
                    ToolTip="Close" Template="{StaticResource NoMouseOverButtonTemplate}">
              <Path x:Name="TitleBtnClosePath" Width="10" Height="10" Stretch="Uniform"
                    Stroke="#C8C8D0" StrokeThickness="1.15"
                    Data="M0,0 L10,10 M10,0 L0,10"
                    HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Button>
          </StackPanel>
        </Grid>
      </Border>
 <!-- Main console chrome -->
      <Grid x:Name="RootGrid" Grid.Row="1">
        <Grid.RowDefinitions>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="*"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

 <!-- Tool groups header -->
        <Border Grid.Row="0" Panel.ZIndex="3" Background="#2A2A30" BorderBrush="#3A3A42"
                BorderThickness="0,0,0,0" Padding="12,8,12,6">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <Grid Grid.Row="0">
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*" MinWidth="80"/>
                <ColumnDefinition Width="Auto"/>
              </Grid.ColumnDefinitions>
              <!-- Tool group chips: fixed catalog order, wrap across rows; title bar holds brand/path/PoweredBy -->
              <WrapPanel x:Name="HdrToolGroups" Grid.Column="0" Orientation="Horizontal"
                         VerticalAlignment="Center" Margin="0,0,12,0"
                         ItemWidth="76" ItemHeight="24" MaxHeight="76"
                         SnapsToDevicePixels="True" UseLayoutRounding="True"
                         ClipToBounds="False"/>
              <!-- Legacy header nodes (collapsed) -->
              <TextBlock x:Name="HdrLine1" Visibility="Collapsed"/>
              <TextBlock x:Name="HdrLine1Shadow" Visibility="Collapsed"/>
              <TextBlock x:Name="HdrPoweredBy" Visibility="Collapsed"/>
              <TextBlock x:Name="HdrPoweredByShadow" Visibility="Collapsed"/>
              <Grid x:Name="HdrPoweredByHost" Visibility="Collapsed"/>
              <TextBlock x:Name="HdrAutoCompact" Visibility="Collapsed"/>
              <TextBlock x:Name="HdrAutoCompactShadow" Visibility="Collapsed"/>
              <CheckBox x:Name="WordWrapToggle" Grid.Column="1" Style="{StaticResource MbDarkCheckBox}"
                        VerticalAlignment="Bottom" HorizontalAlignment="Right" Margin="4,0,0,0"
                        IsChecked="True" ToolTip="Wrap long log lines">
                <CheckBox.Content>
                  <TextBlock x:Name="WordWrapLabel" Text="wrap" Foreground="#C8C8D0" FontSize="12"
                             FontFamily="Consolas, Cascadia Mono, Courier New"
                             VerticalAlignment="Center" Margin="0,-2,0,0"/>
                </CheckBox.Content>
              </CheckBox>
            </Grid>
 <!-- Brand accent: dark idle; TaskBoard open = subtle dark shimmer (not red/blue) -->
            <Rectangle x:Name="HdrBrandAccent" Grid.Row="1" Height="2" Margin="0,6,0,0"
                       RadiusX="1" RadiusY="1" Fill="#25252C"/>
            <!-- TaskBoard sticky: header stays fixed; only task rows scroll (see ApplyTaskBoardSticky) -->
            <Border x:Name="TaskBoardSticky" Grid.Row="2" Visibility="Collapsed"
                    Background="#16161C" BorderBrush="#3A3A42" BorderThickness="0,1,0,0"
                    ClipToBounds="True" MaxHeight="0" Margin="0,0,0,0"
                    SnapsToDevicePixels="True">
              <Grid x:Name="TaskBoardStickyInner">
                <Grid.RowDefinitions>
                  <RowDefinition Height="Auto"/>
                  <RowDefinition Height="*"/>
                </Grid.RowDefinitions>
                <!-- Title banner: not inside ScrollViewer so it stays visible while rows scroll -->
                <Border x:Name="TaskBoardStickyHeader" Grid.Row="0" Background="#16161C"
                        Padding="10,8,10,4" BorderBrush="#2A2A30" BorderThickness="0,0,0,1"
                        SnapsToDevicePixels="True">
                  <Grid>
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="*"/>
                      <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel Orientation="Horizontal" VerticalAlignment="Center" Margin="0,0,8,0">
                      <TextBlock x:Name="TaskBoardStickyLabel" Text="TaskBoard" Foreground="#7DCFFF"
                                 FontSize="11.5" FontWeight="SemiBold"
                                 FontFamily="Consolas, Cascadia Mono, Courier New"
                                 VerticalAlignment="Center" Margin="0,0,8,0"/>
                      <TextBlock x:Name="TaskBoardStickyGoal" Text="" Foreground="#C8C8D0"
                                 FontSize="11.5"
                                 FontFamily="Consolas, Cascadia Mono, Courier New"
                                 VerticalAlignment="Center" TextTrimming="CharacterEllipsis"
                                 MaxWidth="520"/>
                    </StackPanel>
                    <TextBlock x:Name="TaskBoardStickySum" Grid.Column="1" Text=""
                               Foreground="#6A6A76" FontSize="11"
                               FontFamily="Consolas, Cascadia Mono, Courier New"
                               VerticalAlignment="Center" Margin="8,0,0,0"/>
                  </Grid>
                </Border>
                <!-- Only the checklist scrolls; cap ~5 visible rows -->
                <ScrollViewer x:Name="TaskBoardStickyScroll" Grid.Row="1"
                              VerticalScrollBarVisibility="Auto"
                              HorizontalScrollBarVisibility="Disabled"
                              CanContentScroll="False"
                              MaxHeight="140"
                              Focusable="False"
                              PanningMode="VerticalOnly"
                              Padding="0">
                  <StackPanel x:Name="TaskBoardStickyItems" Orientation="Vertical" Margin="10,4,10,6"/>
                </ScrollViewer>
              </Grid>
            </Border>
          </Grid>
        </Border>
        <Rectangle Grid.Row="1" Height="1" Fill="#3A3A42" Panel.ZIndex="2"/>

 <!-- Log -->
        <RichTextBox x:Name="LogBox" Grid.Row="2" IsReadOnly="True" IsDocumentEnabled="True"
                     IsUndoEnabled="False"
                     VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled"
                     BorderThickness="0" Background="#121216" Foreground="#C8C8D0"
                     Padding="12,6" AcceptsReturn="True" CaretBrush="#8A8A96"
                     FontFamily="Consolas, Cascadia Mono, Courier New">
          <RichTextBox.Resources>
            <Style TargetType="Paragraph">
              <Setter Property="Margin" Value="0"/>
              <Setter Property="Padding" Value="0"/>
              <Setter Property="LineHeight" Value="16"/>
            </Style>
          </RichTextBox.Resources>
          <FlowDocument PagePadding="0" LineHeight="16"
                        FontFamily="Consolas, Cascadia Mono, Courier New"/>
        </RichTextBox>

 <!-- Speech visualizer (real TTS PCM from SAPI WaveStream - no WASAPI) -->
        <Border x:Name="SpeechWaveBox" Grid.Row="3" Visibility="Collapsed"
                Background="#1A1A1E" BorderBrush="#3A3A42" BorderThickness="1"
                CornerRadius="6" Margin="12,8,12,6" HorizontalAlignment="Stretch"
                SnapsToDevicePixels="True" ClipToBounds="True">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="84"/>
            </Grid.RowDefinitions>
            <Border Grid.Row="0" Background="#252530" Padding="10,5,10,5"
                    CornerRadius="5,5,0,0" SnapsToDevicePixels="True">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <TextBlock x:Name="SpeechWaveLang" Grid.Column="0" Text="speech"
                           Foreground="#8A8A96" FontSize="11"
                           FontFamily="Consolas, Cascadia Mono, Courier New"
                           VerticalAlignment="Center"/>
                <TextBlock x:Name="SpeechWaveStatus" Grid.Column="1" Text="idle"
                           Foreground="#6A6A76" FontSize="11"
                           FontFamily="Consolas, Cascadia Mono, Courier New"
                           VerticalAlignment="Center" Margin="12,0,0,0"/>
              </Grid>
            </Border>
            <Border Grid.Row="1" Background="#121216" CornerRadius="0,0,5,5" ClipToBounds="True">
              <Canvas x:Name="SpeechWaveCanvas" Background="Transparent" ClipToBounds="True">
                <Polyline x:Name="SpeechWaveLine" Stroke="#00BFFF" StrokeThickness="1.35"
                          StrokeLineJoin="Round" StrokeStartLineCap="Round" StrokeEndLineCap="Round"
                          SnapsToDevicePixels="False"/>
              </Canvas>
            </Border>
          </Grid>
        </Border>

 <!-- Lower status: status+timer (dynamic width by mode) | ctx | meta
             ready -> compact (ctx far left); thinking/working -> same reserved band + timer;
             auto-compacting -> label may grow and shift ctx once. -->
        <Border Grid.Row="4" Background="#1E1E24" BorderBrush="#2A2A30" BorderThickness="0,1,0,0" Padding="12,4">
          <Grid>
            <Grid.ColumnDefinitions>
              <ColumnDefinition Width="Auto"/>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <StackPanel x:Name="StatusBand" Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center" Margin="0,0,14,0">
              <TextBlock x:Name="StatusDot" Text="* ready" Foreground="#9ECE6A"
                         VerticalAlignment="Center" Margin="0,0,0,0" FontWeight="SemiBold"
                         FontFamily="Consolas, Cascadia Mono, Segoe UI Symbol, Courier New"/>
              <TextBlock x:Name="StatusTimer" Text="" Foreground="#6A6A76"
                         VerticalAlignment="Center" HorizontalAlignment="Left"
                         FontWeight="SemiBold"
                         FontFamily="Consolas, Cascadia Mono, Courier New"/>
            </StackPanel>
            <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
              <TextBlock Text="ctx " Foreground="#6A6A76" VerticalAlignment="Center"/>
              <Border Width="120" Height="12" Background="#2A2A30" CornerRadius="2"
                      VerticalAlignment="Center" Margin="0,0,8,0" ClipToBounds="True">
                <Rectangle x:Name="CtxBarFill" Width="0" Height="12" HorizontalAlignment="Left" Fill="#9ECE6A"/>
              </Border>
              <TextBlock x:Name="CtxPctText" Text="0%" Foreground="#6A6A76"
                         VerticalAlignment="Center" Margin="0,0,10,0" FontWeight="SemiBold"/>
              <TextBlock x:Name="CtxTokText" Text="Initializing..." Foreground="#6A6A76" VerticalAlignment="Center"/>
            </StackPanel>
            <StackPanel x:Name="LowerRight" Grid.Column="2" Orientation="Horizontal"
                        VerticalAlignment="Center" HorizontalAlignment="Right" Margin="12,0,0,0"/>
          </Grid>
        </Border>

 <!-- Prompt -->
        <Border Grid.Row="5" Background="#1A1A1E" BorderBrush="#2A2A30" BorderThickness="0,1,0,0" Padding="10,8">
          <Grid>
            <Grid.ColumnDefinitions>
              <ColumnDefinition Width="Auto"/>
              <ColumnDefinition Width="*"/>
              <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <TextBlock Grid.Column="0" Text="> " Foreground="#8A8A96" FontSize="14" VerticalAlignment="Top" Margin="0,6,4,0"/>
            <Border x:Name="PromptHost" Grid.Column="1" BorderBrush="#3A3A42" BorderThickness="1"
                    CornerRadius="4" Background="#121216" Padding="8,6" Margin="0,0,8,0"
                    VerticalAlignment="Stretch" MinHeight="42">
              <TextBox x:Name="PromptBox" AcceptsReturn="True" TextWrapping="Wrap"
                       MinHeight="28" MaxHeight="140" VerticalScrollBarVisibility="Auto"
                       BorderThickness="0" Background="Transparent" Foreground="#E0E0E8"
                       CaretBrush="#C8C8D0" FontFamily="Consolas, Cascadia Mono, Courier New"
                       FontSize="13" IsEnabled="True" IsReadOnly="True" Focusable="True"/>
            </Border>
            <Button x:Name="SendBtn" Grid.Column="2" Width="88" MinHeight="41"
                    VerticalAlignment="Stretch" Cursor="Hand" ToolTip="Send"
                    HorizontalContentAlignment="Center" VerticalContentAlignment="Center"
                    Background="#2A2A30" Foreground="#8A8A96" BorderBrush="#3A3A42" BorderThickness="1"
                    Padding="6,0" Margin="0,0,3,1" IsEnabled="False"
                    Template="{StaticResource NoMouseOverButtonTemplate}">
              <!-- Send icon -->
              <Path x:Name="SendBtnPath" Width="20" Height="20" Stretch="Uniform"
                    HorizontalAlignment="Center" VerticalAlignment="Center"
                    Data="M12,2A10,10 0 0,1 22,12A10,10 0 0,1 12,22A10,10 0 0,1 2,12A10,10 0 0,1 12,2M8,7.71V11.05L15.14,12L8,12.95V16.29L18,12L8,7.71Z">
                <Path.Fill>
                  <LinearGradientBrush StartPoint="0.2,0" EndPoint="0.85,1">
                    <GradientStop x:Name="SendBtnGrad0" Color="#C0C0C8" Offset="0"/>
                    <GradientStop x:Name="SendBtnGrad1" Color="#8A8A96" Offset="0.5"/>
                    <GradientStop x:Name="SendBtnGrad2" Color="#5A5A66" Offset="1"/>
                  </LinearGradientBrush>
                </Path.Fill>
                <Path.Effect>
                  <DropShadowEffect x:Name="SendBtnShadow" BlurRadius="4" ShadowDepth="1.5"
                                    Opacity="0.75" Direction="315" Color="Black"/>
                </Path.Effect>
              </Path>
            </Button>
          </Grid>
        </Border>

 <!-- Hints (bottom corners match chrome when restored) -->
        <Border x:Name="HintBarBorder" Grid.Row="6" Background="#16161A" BorderBrush="#2A2A30"
                BorderThickness="0,1,0,0" Padding="12,4"
                CornerRadius="0,0,8,8" SnapsToDevicePixels="True">
          <TextBlock x:Name="HintBar" Text="enter send  |  Ctrl+Enter newline  |  Esc / Stop interrupt  |  /help"
                     Foreground="#5A5A66" FontSize="11"/>
        </Border>
      </Grid>
    </Grid>
  </Border>

 <!-- Overlays -->
      <Grid x:Name="AuthOverlay" Visibility="Collapsed" Panel.ZIndex="200">
        <Border Background="#E6121216"/>
        <Border Width="420" HorizontalAlignment="Center" VerticalAlignment="Center"
                Background="#121216" BorderBrush="#2A2A30" BorderThickness="1" CornerRadius="8"
                ClipToBounds="True" SnapsToDevicePixels="True">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="36"/>
              <RowDefinition Height="*"/>
            </Grid.RowDefinitions>
            <Border Grid.Row="0" Background="#2A2A30" BorderBrush="#3A3A42" BorderThickness="0,0,0,1"
                    CornerRadius="8,8,0,0" Padding="10,0,0,0">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                  <TextBlock VerticalAlignment="Center" FontSize="13" FontWeight="SemiBold">
                    <Run Text="[" Foreground="#A0A0AA"/><Run x:Name="AuthBarBrandName" Text="MiniBot" Foreground="#B80F0A"/><Run Text="-" Foreground="#A0A0AA"/><Run Text="Agent" Foreground="#B80F0A"/><Run Text="]" Foreground="#A0A0AA"/>
                  </TextBlock>
                  <Ellipse Width="3.5" Height="3.5" Fill="#8A8A96"
                           Margin="9,1,9,0" VerticalAlignment="Center" Opacity="0.9"
                           SnapsToDevicePixels="False">
                    <Ellipse.Effect>
                      <DropShadowEffect Color="#000000" BlurRadius="1.5" ShadowDepth="0.5" Opacity="0.45" Direction="270"/>
                    </Ellipse.Effect>
                  </Ellipse>
                  <TextBlock Text="Login" Foreground="#C8C8D0" FontSize="12" VerticalAlignment="Center"/>
                </StackPanel>
                <Button x:Name="AuthTitleClose" Grid.Column="1" Width="46" Height="36"
                        Background="Transparent" BorderThickness="0" Cursor="Hand" Focusable="False"
                        Template="{StaticResource NoMouseOverButtonTemplate}" ToolTip="Close">
                  <Path Width="10" Height="10" Stretch="Uniform" Stroke="#C8C8D0" StrokeThickness="1.15"
                        Data="M0,0 L10,10 M10,0 L0,10" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Button>
              </Grid>
            </Border>
            <Border Grid.Row="1" Background="#121216" Padding="22,18,22,14"
                    CornerRadius="0,0,8,8" SnapsToDevicePixels="True">
              <Grid>
                <Grid.RowDefinitions>
                  <RowDefinition Height="Auto"/>
                  <RowDefinition Height="18"/>
                  <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>
                <StackPanel Grid.Row="0">
                  <TextBlock x:Name="AuthTitle" Text="Authentication required" Foreground="#E0E0E8"
                             FontSize="16" FontWeight="Bold" Margin="0,0,0,6"/>
                  <TextBlock x:Name="AuthSubtitle" Text="" Foreground="#8A8A96" TextWrapping="Wrap"
                             FontSize="12" Margin="0,0,0,10" MaxHeight="40" TextTrimming="CharacterEllipsis"/>
                  <TextBlock Text="Username" Foreground="#A0A0AA" FontSize="11" Margin="0,0,0,4"/>
                  <TextBox x:Name="AuthUser" Height="32" Padding="8,6" Margin="0,0,0,8"
                           Background="#121216" Foreground="#E0E0E8" CaretBrush="#C8C8D0"
                           BorderBrush="#3A3A42" BorderThickness="1"
                           FontFamily="Consolas, Cascadia Mono, Courier New" FontSize="13"
                           Focusable="True" IsTabStop="True" TabIndex="0"/>
                  <TextBlock Text="Password" Foreground="#A0A0AA" FontSize="11" Margin="0,0,0,4"/>
                  <PasswordBox x:Name="AuthPass" Height="32" Padding="8,6" Margin="0,0,0,6"
                               Background="#121216" Foreground="#E0E0E8" CaretBrush="#C8C8D0"
                               BorderBrush="#3A3A42" BorderThickness="1"
                               FontFamily="Consolas, Cascadia Mono, Courier New" FontSize="13"
                               Focusable="True" IsTabStop="True" TabIndex="1"/>
                  <CheckBox x:Name="AuthSaveCreds" Style="{StaticResource MbDarkCheckBox}"
                            Margin="0,0,0,0" Cursor="Hand" Focusable="True" IsTabStop="True"
                            TabIndex="2" IsChecked="False">
                    <CheckBox.Content>
                      <TextBlock Text="Save credentials" Foreground="#A0A0AA" FontSize="12"
                                 Margin="0,-1,0,0"/>
                    </CheckBox.Content>
                  </CheckBox>
                </StackPanel>
                <TextBlock x:Name="AuthError" Grid.Row="1" Text="" Foreground="#F05C5C" FontSize="11"
                           TextWrapping="NoWrap" TextTrimming="CharacterEllipsis" VerticalAlignment="Center"/>
                <StackPanel Grid.Row="2" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,2,0,0">
                  <Button x:Name="AuthOk" Style="{StaticResource MbAuthPrimaryBtn}"
                          Content="Sign in" Width="96" Height="30" Margin="0,0,8,0"
                          IsDefault="False" TabIndex="3"/>
                  <Button x:Name="AuthCancel" Style="{StaticResource MbAuthSecondaryBtn}"
                          Content="Quit" Width="88" Height="30" TabIndex="4"/>
                </StackPanel>
              </Grid>
            </Border>
          </Grid>
        </Border>
      </Grid>
      <!-- Mid-session + Add endpoint: own overlay on the chat host (show/hide only; never boot login window) -->
      <Grid x:Name="AddEndpointOverlay" Visibility="Collapsed" Panel.ZIndex="250">
        <Border Background="#E6121216"/>
        <Border Width="440" HorizontalAlignment="Center" VerticalAlignment="Center"
                Background="#121216" BorderBrush="#2A2A30" BorderThickness="1" CornerRadius="8"
                ClipToBounds="True" SnapsToDevicePixels="True">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="36"/>
              <RowDefinition Height="*"/>
            </Grid.RowDefinitions>
            <Border Grid.Row="0" Background="#2A2A30" BorderBrush="#3A3A42" BorderThickness="0,0,0,1"
                    CornerRadius="8,8,0,0" Padding="10,0,0,0">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                  <TextBlock VerticalAlignment="Center" FontSize="13" FontWeight="SemiBold">
                    <Run Text="[" Foreground="#A0A0AA"/><Run x:Name="AddEpBarBrandName" Text="MiniBot" Foreground="#B80F0A"/><Run Text="-" Foreground="#A0A0AA"/><Run Text="Agent" Foreground="#B80F0A"/><Run Text="]" Foreground="#A0A0AA"/>
                  </TextBlock>
                  <Ellipse Width="3.5" Height="3.5" Fill="#8A8A96"
                           Margin="9,1,9,0" VerticalAlignment="Center" Opacity="0.9"
                           SnapsToDevicePixels="False">
                    <Ellipse.Effect>
                      <DropShadowEffect Color="#000000" BlurRadius="1.5" ShadowDepth="0.5" Opacity="0.45" Direction="270"/>
                    </Ellipse.Effect>
                  </Ellipse>
                  <TextBlock Text="Add endpoint" Foreground="#C8C8D0" FontSize="12" VerticalAlignment="Center"/>
                </StackPanel>
                <Button x:Name="AddEpTitleClose" Grid.Column="1" Width="46" Height="36"
                        Background="Transparent" BorderThickness="0" Cursor="Hand" Focusable="False"
                        Template="{StaticResource NoMouseOverButtonTemplate}" ToolTip="Cancel">
                  <Path Width="10" Height="10" Stretch="Uniform" Stroke="#C8C8D0" StrokeThickness="1.15"
                        Data="M0,0 L10,10 M10,0 L0,10" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Button>
              </Grid>
            </Border>
            <Border Grid.Row="1" Background="#121216" Padding="22,18,22,14"
                    CornerRadius="0,0,8,8" SnapsToDevicePixels="True">
              <Grid>
                <Grid.RowDefinitions>
                  <RowDefinition Height="Auto"/>
                  <RowDefinition Height="18"/>
                  <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>
                <StackPanel Grid.Row="0">
                  <TextBlock x:Name="AddEpHeading" Text="Add an OpenAI-compatible endpoint"
                             Foreground="#E0E0E8" FontSize="16" FontWeight="Bold" Margin="0,0,0,6"/>
                  <TextBlock x:Name="AddEpSubtitle"
                             Text="Add another API base for the model picker. Example: http://127.0.0.1:8080/v1"
                             Foreground="#8A8A96" TextWrapping="Wrap" FontSize="12" Margin="0,0,0,10"
                             MaxHeight="56" TextTrimming="CharacterEllipsis"/>
                  <TextBlock Text="Endpoint URL" Foreground="#A0A0AA" FontSize="11" Margin="0,0,0,4"/>
                  <TextBox x:Name="AddEpUrl" Height="32" Padding="8,6" Margin="0,0,0,8"
                           Background="#121216" Foreground="#E0E0E8" CaretBrush="#C8C8D0"
                           BorderBrush="#3A3A42" BorderThickness="1"
                           FontFamily="Consolas, Cascadia Mono, Courier New" FontSize="13"
                           Focusable="True" IsTabStop="True" TabIndex="0"/>
                  <TextBlock Text="Auth mode" Foreground="#A0A0AA" FontSize="11" Margin="0,0,0,4"/>
                  <StackPanel Orientation="Horizontal" Margin="0,0,0,8">
                    <RadioButton x:Name="AddEpAuthNone" Content="None" GroupName="MbAddEndpointAuth"
                                 IsChecked="True" Foreground="#C8C8D0" FontSize="12" Margin="0,0,16,0" Cursor="Hand"/>
                    <RadioButton x:Name="AddEpAuthKey" Content="API" GroupName="MbAddEndpointAuth"
                                 Foreground="#C8C8D0" FontSize="12" Margin="0,0,16,0" Cursor="Hand"/>
                    <RadioButton x:Name="AddEpAuthNpm" Content="Basic (NPM)" GroupName="MbAddEndpointAuth"
                                 Foreground="#C8C8D0" FontSize="12" Cursor="Hand"/>
                  </StackPanel>
                  <TextBlock x:Name="AddEpKeyLbl" Text="API token (when Auth = API)" Foreground="#A0A0AA"
                             FontSize="11" Margin="0,0,0,4"/>
                  <PasswordBox x:Name="AddEpKey" Height="32" Padding="8,6" Margin="0,0,0,6"
                               Background="#121216" Foreground="#E0E0E8" CaretBrush="#C8C8D0"
                               BorderBrush="#3A3A42" BorderThickness="1"
                               FontFamily="Consolas, Cascadia Mono, Courier New" FontSize="13"
                               Focusable="True" IsTabStop="True" TabIndex="1"/>
                </StackPanel>
                <TextBlock x:Name="AddEpError" Grid.Row="1" Text="" Foreground="#F05C5C" FontSize="11"
                           TextWrapping="NoWrap" TextTrimming="CharacterEllipsis" VerticalAlignment="Center"/>
                <StackPanel Grid.Row="2" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,2,0,0">
                  <Button x:Name="AddEpConnect" Style="{StaticResource MbAuthPrimaryBtn}"
                          Content="Connect" Width="96" Height="30" Margin="0,0,8,0"
                          IsDefault="True" TabIndex="2"/>
                  <Button x:Name="AddEpCancel" Style="{StaticResource MbAuthSecondaryBtn}"
                          Content="Cancel" Width="88" Height="30" IsCancel="True" TabIndex="3"/>
                </StackPanel>
              </Grid>
            </Border>
          </Grid>
        </Border>
      </Grid>
      <Grid x:Name="ConfirmOverlay" Visibility="Collapsed" Panel.ZIndex="300">
        <Border Background="#E6121216"/>
        <Border Width="420" HorizontalAlignment="Center" VerticalAlignment="Center"
                Background="#121216" BorderBrush="#2A2A30" BorderThickness="1" CornerRadius="8"
                ClipToBounds="True" SnapsToDevicePixels="True">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="36"/>
              <RowDefinition Height="*"/>
            </Grid.RowDefinitions>
            <Border Grid.Row="0" Background="#2A2A30" BorderBrush="#3A3A42" BorderThickness="0,0,0,1"
                    CornerRadius="8,8,0,0" Padding="10,0,0,0">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                  <TextBlock VerticalAlignment="Center" FontSize="13" FontWeight="SemiBold">
                    <Run Text="[" Foreground="#A0A0AA"/><Run x:Name="ConfirmBarBrandName" Text="MiniBot" Foreground="#B80F0A"/><Run Text="-" Foreground="#A0A0AA"/><Run Text="Agent" Foreground="#B80F0A"/><Run Text="]" Foreground="#A0A0AA"/>
                  </TextBlock>
                  <Ellipse Width="3.5" Height="3.5" Fill="#8A8A96"
                           Margin="9,1,9,0" VerticalAlignment="Center" Opacity="0.9"
                           SnapsToDevicePixels="False">
                    <Ellipse.Effect>
                      <DropShadowEffect Color="#000000" BlurRadius="1.5" ShadowDepth="0.5" Opacity="0.45" Direction="270"/>
                    </Ellipse.Effect>
                  </Ellipse>
                  <TextBlock Text="Confirm" Foreground="#C8C8D0" FontSize="12" VerticalAlignment="Center"/>
                </StackPanel>
                <Button x:Name="ConfirmTitleClose" Grid.Column="1" Width="46" Height="36"
                        Background="Transparent" BorderThickness="0" Cursor="Hand" Focusable="False"
                        Template="{StaticResource NoMouseOverButtonTemplate}" ToolTip="Close">
                  <Path Width="10" Height="10" Stretch="Uniform" Stroke="#C8C8D0" StrokeThickness="1.15"
                        Data="M0,0 L10,10 M10,0 L0,10" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Button>
              </Grid>
            </Border>
            <Border Grid.Row="1" Background="#121216" Padding="22,18,22,16"
                    CornerRadius="0,0,8,8" SnapsToDevicePixels="True">
              <Grid>
                <Grid.RowDefinitions>
                  <RowDefinition Height="Auto"/>
                  <RowDefinition Height="Auto"/>
                  <RowDefinition Height="Auto"/>
                  <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>
                <TextBlock x:Name="ConfirmTitle" Text="Invalid Entry" Foreground="#E0E0E8"
                           FontSize="16" FontWeight="Bold" Margin="0,0,0,6"/>
                <Rectangle x:Name="ConfirmAccentBar" Grid.Row="1" Height="3" Margin="0,0,0,14"
                           RadiusX="1.5" RadiusY="1.5" Opacity="0.55">
                  <Rectangle.Fill>
                    <LinearGradientBrush StartPoint="0,0" EndPoint="1,0">
                      <GradientStop Color="#7DCFFF" Offset="0"/>
                      <GradientStop Color="#FFFFFF" Offset="0.5"/>
                      <GradientStop Color="#7DCFFF" Offset="1"/>
                    </LinearGradientBrush>
                  </Rectangle.Fill>
                </Rectangle>
                <TextBlock x:Name="ConfirmPrompt" Grid.Row="2" Text="" Foreground="#C8C8D0"
                           FontSize="13" TextWrapping="Wrap" Margin="0,0,0,18" LineHeight="20"/>
                <StackPanel Grid.Row="3" Orientation="Horizontal" HorizontalAlignment="Right">
                  <Button x:Name="ConfirmYes" Style="{StaticResource MbAuthPrimaryBtn}"
                          Content="Yes" MinWidth="96" Height="30" Padding="16,0" Margin="0,0,8,0"
                          IsDefault="True" TabIndex="0"/>
                  <Button x:Name="ConfirmNo" Style="{StaticResource MbAuthSecondaryBtn}"
                          Content="No" MinWidth="88" Height="30" Padding="16,0"
                          IsCancel="True" TabIndex="1"/>
                </StackPanel>
              </Grid>
            </Border>
          </Grid>
        </Border>
      </Grid>

      <Grid x:Name="SessionPickerOverlay" Visibility="Collapsed" Panel.ZIndex="250">
        <Border Background="#E6121216"/>
        <Border Width="720" Height="500" MinWidth="480" MinHeight="340"
                MaxWidth="920" MaxHeight="640"
                HorizontalAlignment="Center" VerticalAlignment="Center"
                Background="#121216" BorderBrush="#2A2A30" BorderThickness="1"
                CornerRadius="8" ClipToBounds="True" SnapsToDevicePixels="True">
          <Grid>
            <Grid.RowDefinitions>
              <RowDefinition Height="36"/>
              <RowDefinition Height="*"/>
            </Grid.RowDefinitions>
            <Border Grid.Row="0" Background="#2A2A30" BorderBrush="#3A3A42" BorderThickness="0,0,0,1"
                    CornerRadius="8,8,0,0" Padding="10,0,0,0">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="*"/>
                  <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                  <TextBlock VerticalAlignment="Center" FontSize="13" FontWeight="SemiBold">
                    <Run Text="[" Foreground="#A0A0AA"/><Run x:Name="SessionBarBrandName" Text="MiniBot" Foreground="#B80F0A"/><Run Text="-" Foreground="#A0A0AA"/><Run Text="Agent" Foreground="#B80F0A"/><Run Text="]" Foreground="#A0A0AA"/>
                  </TextBlock>
                  <Ellipse Width="3.5" Height="3.5" Fill="#8A8A96"
                           Margin="9,1,9,0" VerticalAlignment="Center" Opacity="0.9"
                           SnapsToDevicePixels="False">
                    <Ellipse.Effect>
                      <DropShadowEffect Color="#000000" BlurRadius="1.5" ShadowDepth="0.5" Opacity="0.45" Direction="270"/>
                    </Ellipse.Effect>
                  </Ellipse>
                  <TextBlock x:Name="SessionPickerTitle" Text="Load session" Foreground="#C8C8D0" FontSize="12"
                             VerticalAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="420"/>
                </StackPanel>
                <Button x:Name="SessionPickerTitleClose" Grid.Column="1" Width="46" Height="36"
                        Background="Transparent" BorderThickness="0" Cursor="Hand" Focusable="False"
                        Template="{StaticResource NoMouseOverButtonTemplate}" ToolTip="Close">
                  <Path Width="10" Height="10" Stretch="Uniform" Stroke="#C8C8D0" StrokeThickness="1.15"
                        Data="M0,0 L10,10 M10,0 L0,10" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Button>
              </Grid>
            </Border>
            <Border Grid.Row="1" Background="#121216" CornerRadius="0,0,8,8" SnapsToDevicePixels="True">
            <Grid Margin="16,14,16,14">
            <Grid.RowDefinitions>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="*"/>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <DockPanel Grid.Row="0" Margin="0,0,0,8" LastChildFill="True">
              <Button x:Name="SessionPickerBrowse" Style="{StaticResource MbAuthSecondaryBtn}"
                      Content="Browse..." MinWidth="84" Height="30" Margin="6,0,0,0"
                      DockPanel.Dock="Right" Padding="10,0"/>
              <Button x:Name="SessionPickerUp" Style="{StaticResource MbAuthSecondaryBtn}"
                      Content="Up" MinWidth="52" Height="30" Margin="6,0,0,0"
                      DockPanel.Dock="Right" Padding="10,0"/>
              <Button x:Name="SessionPickerGo" Style="{StaticResource MbAuthSecondaryBtn}"
                      Content="Go" MinWidth="52" Height="30" Margin="6,0,0,0"
                      DockPanel.Dock="Right" Padding="10,0"/>
              <TextBox x:Name="SessionPickerPath" Height="30" Padding="8,5"
                       Background="#121216" Foreground="#E0E0E8" CaretBrush="#C8C8D0"
                       BorderBrush="#3A3A42" BorderThickness="1" VerticalContentAlignment="Center"
                       FontFamily="Consolas, Cascadia Mono, Courier New" FontSize="13"/>
            </DockPanel>
            <TextBlock x:Name="SessionPickerStatus" Grid.Row="1" Text="Sessions (newest first)"
                       Foreground="#6A6A76" FontSize="11" Margin="0,0,0,6"/>
            <ListBox x:Name="SessionPickerList" Grid.Row="2"
                     Background="#121216" Foreground="#C8C8D0" BorderBrush="#3A3A42"
                     BorderThickness="1" FontFamily="Consolas, Cascadia Mono, Courier New"
                     FontSize="12" Padding="2"
                     ScrollViewer.HorizontalScrollBarVisibility="Disabled">
              <ListBox.Resources>
                <SolidColorBrush x:Key="{x:Static SystemColors.HighlightBrushKey}" Color="#3A3A42"/>
                <SolidColorBrush x:Key="{x:Static SystemColors.HighlightTextBrushKey}" Color="#7DCFFF"/>
                <SolidColorBrush x:Key="{x:Static SystemColors.ControlBrushKey}" Color="#121216"/>
                <Style TargetType="ListBoxItem">
                  <Setter Property="Padding" Value="8,4"/>
                  <Setter Property="Background" Value="Transparent"/>
                  <Setter Property="Foreground" Value="#C8C8D0"/>
                  <Setter Property="BorderThickness" Value="0"/>
                  <Style.Triggers>
                    <Trigger Property="IsMouseOver" Value="True">
                      <Setter Property="Background" Value="#363640"/>
                      <Setter Property="Foreground" Value="#E0E0E8"/>
                    </Trigger>
                    <Trigger Property="IsSelected" Value="True">
                      <Setter Property="Background" Value="#3A3A42"/>
                      <Setter Property="Foreground" Value="#7DCFFF"/>
                    </Trigger>
                  </Style.Triggers>
                </Style>
              </ListBox.Resources>
            </ListBox>
            <DockPanel Grid.Row="3" Margin="0,10,0,10" LastChildFill="True">
              <TextBlock Text="File name:  " Foreground="#8A8A96" VerticalAlignment="Center"
                         DockPanel.Dock="Left"/>
              <TextBox x:Name="SessionPickerName" Height="30" Padding="8,5"
                       Background="#121216" Foreground="#E0E0E8" CaretBrush="#C8C8D0"
                       BorderBrush="#3A3A42" BorderThickness="1" VerticalContentAlignment="Center"
                       FontFamily="Consolas, Cascadia Mono, Courier New" FontSize="13"/>
            </DockPanel>
            <StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Right">
              <Button x:Name="SessionPickerOk" Style="{StaticResource MbAuthPrimaryBtn}"
                      Content="Open" MinWidth="96" Height="30" Padding="16,0" Margin="0,0,8,0"
                      IsDefault="False"/>
              <Button x:Name="SessionPickerCancel" Style="{StaticResource MbAuthSecondaryBtn}"
                      Content="Cancel" MinWidth="88" Height="30" Padding="16,0"
                      IsCancel="False"/>
            </StackPanel>
            </Grid>
            </Border>
          </Grid>
        </Border>
      </Grid>
  </Grid>
</Window>
'@
			$reader = New-Object System.Xml.XmlNodeReader ([xml]$xaml)
			$window = [Windows.Markup.XamlReader]::Load($reader)
			$W.Window = $window
			$W.Log = $window.FindName('LogBox')
			$W.LogHost = $null
			$W.VizLiveSlots = New-Object System.Collections.ArrayList
			$W.Prompt = $window.FindName('PromptBox')
			$W.SendBtn = $window.FindName('SendBtn')
			$W.SendBtnPath = $window.FindName('SendBtnPath')
			$W.SendBtnGrad0 = $window.FindName('SendBtnGrad0')
			$W.SendBtnGrad1 = $window.FindName('SendBtnGrad1')
			$W.SendBtnGrad2 = $window.FindName('SendBtnGrad2')
			$W.SendBtnShadow = $window.FindName('SendBtnShadow')
			if ((-not $W.SendBtnGrad0 -or -not $W.SendBtnGrad1 -or -not $W.SendBtnGrad2) -and $W.SendBtnPath) {
				try {
					$sf = $W.SendBtnPath.Fill
					if ($sf -is [System.Windows.Media.LinearGradientBrush] -and $sf.GradientStops.Count -ge 3) {
						$W.SendBtnGrad0 = $sf.GradientStops[0]
						$W.SendBtnGrad1 = $sf.GradientStops[1]
						$W.SendBtnGrad2 = $sf.GradientStops[2]
					}
				} catch {}
			}
			if ($W.SendBtnPath) {
				try { $W.SendBtnPath.RenderTransform = [System.Windows.Media.Transform]::Identity } catch {}
				if (-not $W.SendBtnShadow) {
					try {
						if ($W.SendBtnPath.Effect -is [System.Windows.Media.Effects.DropShadowEffect]) {
							$W.SendBtnShadow = $W.SendBtnPath.Effect
						} else {
							$fx = New-Object System.Windows.Media.Effects.DropShadowEffect
							$fx.BlurRadius = 4
							$fx.ShadowDepth = 1.5
							$fx.Opacity = 0.75
							$fx.Direction = 315
							$fx.Color = [System.Windows.Media.Colors]::Black
							$W.SendBtnPath.Effect = $fx
							$W.SendBtnShadow = $fx
						}
					} catch {}
				}
			}
			# Send and stop path geometry
			$W.SendGeomData = 'M12,2A10,10 0 0,1 22,12A10,10 0 0,1 12,22A10,10 0 0,1 2,12A10,10 0 0,1 12,2M8,7.71V11.05L15.14,12L8,12.95V16.29L18,12L8,7.71Z'
			$W.StopGeomData = 'M12,2A10,10 0 0,1 22,12A10,10 0 0,1 12,22A10,10 0 0,1 2,12A10,10 0 0,1 12,2M9,9H15V15H9V9Z'
			$W.HdrLine1 = $window.FindName('HdrLine1')
			$W.HdrLine1Shadow = $window.FindName('HdrLine1Shadow')
			$W.HdrLine2 = $null
			$W.HdrLine2Shadow = $null
			$W.HdrToolGroups = $window.FindName('HdrToolGroups')
			$W.ToolGroupsFp = ''
			$W.ToolGroupsBuilt = $false
			$W.ToolGroupsDirty = $true
			$W.ToolGroupsData = $null
			# TaskBoard sticky under chips (paint must run in this STA runspace — not main-runspace functions)
			$W.TaskBoardSticky = $window.FindName('TaskBoardSticky')
			$W.TaskBoardStickyScroll = $window.FindName('TaskBoardStickyScroll')
			$W.TaskBoardStickyInner = $window.FindName('TaskBoardStickyInner')
			$W.TaskBoardStickyHeader = $window.FindName('TaskBoardStickyHeader')
			$W.TaskBoardStickyItems = $window.FindName('TaskBoardStickyItems')
			$W.TaskBoardStickyGoal = $window.FindName('TaskBoardStickyGoal')
			$W.TaskBoardStickySum = $window.FindName('TaskBoardStickySum')
			$W.TaskBoardStickyLabel = $window.FindName('TaskBoardStickyLabel')
			$W.HdrBrandAccent = $window.FindName('HdrBrandAccent')
			# Items scroller shows at most 5 rows; title banner stays fixed above it
			$W.TaskBoardMaxVisibleRows = 5
			$W.TaskBoardMaxScrollH = 140.0
			$W.TaskBoardPulseEls = New-Object System.Collections.ArrayList
			$W.TaskBoardExpanded = $false
			$W.TaskBoardRetractTimer = $null
			$W.BrandAccentShimmerOn = $false
			$W.BrandAccentTranslate = $null
			# Mostly-dark accent: solid when TaskBoard closed; soft light/dark slide while open
			$W.SetBrandAccentIdle = {
				try {
					$rect = $W.HdrBrandAccent
					if (-not $rect) { return }
					try {
						if ($W.BrandAccentTranslate) {
							$W.BrandAccentTranslate.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $null)
						}
					} catch {}
					$W.BrandAccentTranslate = $null
					$W.BrandAccentShimmerOn = $false
					$bc = New-Object System.Windows.Media.BrushConverter
					# Deep dark resting line (not bright)
					$rect.Fill = $bc.ConvertFromString('#25252C')
				} catch {}
			}.GetNewClosure()
			$W.SetBrandAccentShimmer = {
				try {
					$rect = $W.HdrBrandAccent
					if (-not $rect) { return }
					if ([bool]$W.BrandAccentShimmerOn) { return }
					# Dark base with a dim mid highlight that drifts left→right forever
					$brush = New-Object System.Windows.Media.LinearGradientBrush
					$brush.StartPoint = New-Object System.Windows.Point(0, 0.5)
					$brush.EndPoint = New-Object System.Windows.Point(1, 0.5)
					$brush.MappingMode = [System.Windows.Media.BrushMappingMode]::RelativeToBoundingBox
					$cDark = [System.Windows.Media.Color]::FromRgb(0x1A, 0x1A, 0x20)   # almost black
					$cMid  = [System.Windows.Media.Color]::FromRgb(0x3A, 0x3A, 0x46)   # soft lift (still muted)
					$cEdge = [System.Windows.Media.Color]::FromRgb(0x22, 0x22, 0x2A)
					# Wide dark regions; narrow lighter band for a slow slide
					[void]$brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($cDark, 0.0)))
					[void]$brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($cDark, 0.32)))
					[void]$brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($cMid, 0.50)))
					[void]$brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($cDark, 0.68)))
					[void]$brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($cEdge, 1.0)))
					$tt = New-Object System.Windows.Media.TranslateTransform(0, 0)
					# RelativeTransform so X is in 0..1 brush space
					$tg = New-Object System.Windows.Media.TransformGroup
					[void]$tg.Children.Add($tt)
					$brush.RelativeTransform = $tg
					$rect.Fill = $brush
					$W.BrandAccentTranslate = $tt
					$anim = New-Object System.Windows.Media.Animation.DoubleAnimation
					# Drift the highlight band across the bar, then reverse
					$anim.From = -0.55
					$anim.To = 0.55
					$anim.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(3200))
					$anim.AutoReverse = $true
					$anim.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
					try {
						$ease = New-Object System.Windows.Media.Animation.SineEase
						$ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
						$anim.EasingFunction = $ease
					} catch {}
					$tt.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $anim)
					$W.BrandAccentShimmerOn = $true
				} catch {}
			}.GetNewClosure()
			try { & $W.SetBrandAccentIdle } catch {}
			$W.StopTaskBoardPulse = {
				try {
					foreach ($el in @($W.TaskBoardPulseEls)) {
						if ($null -eq $el) { continue }
						try {
							if ($el -is [System.Windows.Media.SolidColorBrush]) {
								$el.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $null)
							} else {
								$el.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
								try { $el.Opacity = 1.0 } catch {}
							}
						} catch {}
					}
					$W.TaskBoardPulseEls = New-Object System.Collections.ArrayList
				} catch {}
			}.GetNewClosure()
			$W.StartColorPulse = {
				param($Brush, [string]$FromHex, [string]$ToHex, [int]$Ms = 1000)
				if (-not $Brush) { return }
				try {
					$bc = New-Object System.Windows.Media.BrushConverter
					$fromC = ([System.Windows.Media.SolidColorBrush]$bc.ConvertFromString($FromHex)).Color
					$toC = ([System.Windows.Media.SolidColorBrush]$bc.ConvertFromString($ToHex)).Color
					$anim = New-Object System.Windows.Media.Animation.ColorAnimation
					$anim.From = $fromC
					$anim.To = $toC
					$anim.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds([Math]::Max(250, $Ms)))
					$anim.AutoReverse = $true
					$anim.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
					try {
						$ease = New-Object System.Windows.Media.Animation.SineEase
						$ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
						$anim.EasingFunction = $ease
					} catch {}
					$Brush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $anim)
				} catch {}
			}.GetNewClosure()
			$W.StartOpacityPulse = {
				param($Element, [double]$From = 0.82, [double]$To = 1.0, [int]$Ms = 1000)
				if (-not $Element) { return }
				try {
					$anim = New-Object System.Windows.Media.Animation.DoubleAnimation
					$anim.From = $From
					$anim.To = $To
					$anim.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds([Math]::Max(200, $Ms)))
					$anim.AutoReverse = $true
					$anim.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
					try {
						$ease = New-Object System.Windows.Media.Animation.SineEase
						$ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
						$anim.EasingFunction = $ease
					} catch {}
					$Element.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $anim)
				} catch {}
			}.GetNewClosure()
			# Coalesce TaskBoard paints on STA; always paint latest LiveSnap (not a stale dequeued Pending).
			$W.DrainTaskBoardPaint = {
				try {
					$busy = $false
					try { $busy = [bool]$W.TaskBoardPaintBusy } catch { $busy = $false }
					if ($busy) {
						try { $W.TaskBoardPaintQueued = $true } catch {}
						return
					}
					try { $W.TaskBoardPaintBusy = $true } catch {}
					try {
						$guard = 0
						do {
							$guard++
							if ($guard -gt 12) { break }
							try { $W.TaskBoardPaintQueued = $false } catch {}
							# Clear dirty; paint LiveSnap (always newest). Fall back to Pending.
							$tbPend = $null
							$live = $null
							try { $tbPend = $W.PendingTaskBoard } catch { $tbPend = $null }
							try { $live = $W.TaskBoardLiveSnap } catch { $live = $null }
							try { $W.PendingTaskBoard = $null } catch {}
							$toPaint = $live
							if ($null -eq $toPaint) { $toPaint = $tbPend }
							if ($null -eq $toPaint) { break }
							try {
								$inSeq = 0; $had = 0; $liveGen = 0
								try {
									if ($toPaint -is [System.Collections.IDictionary] -and $toPaint.Contains('Seq')) {
										$inSeq = [int]$toPaint['Seq']
									} else { $inSeq = [int]$toPaint.Seq }
								} catch { $inSeq = 0 }
								try { $had = [int]$W.TaskBoardAppliedSeq } catch { $had = 0 }
								try { $liveGen = [int]$W.TaskBoardLiveGen } catch { $liveGen = 0 }
								# Already painted this exact gen and nothing newer — skip.
								if ($inSeq -gt 0 -and $had -gt 0 -and $inSeq -eq $had -and ($liveGen -le 0 -or $liveGen -le $had)) {
									$againEq = $false
									try { if ([bool]$W.TaskBoardPaintQueued) { $againEq = $true } } catch {}
									try { if ($null -ne $W.PendingTaskBoard) { $againEq = $true } } catch {}
									if (-not $againEq) { break }
									continue
								}
								# Prefer newer LiveSnap if dequeued object is behind LiveGen.
								if ($liveGen -gt 0 -and $inSeq -gt 0 -and $inSeq -lt $liveGen -and $null -ne $live) {
									$toPaint = $live
								}
							} catch {}
							try {
								$apply = $null
								try { $apply = $W.ApplyTaskBoardSticky } catch { $apply = $null }
								if ($apply -is [scriptblock]) {
									& $apply $toPaint
								}
								try { $W.TaskBoardPaintRetry = 0 } catch {}
							} catch {
								try { $W.LastTaskBoardPaintErr = [string]$_.Exception.Message } catch {}
								try {
									$retry = 0
									try { $retry = [int]$W.TaskBoardPaintRetry } catch { $retry = 0 }
									if ($retry -lt 3 -and $null -eq $W.PendingTaskBoard) {
										$W.TaskBoardPaintRetry = $retry + 1
										$W.PendingTaskBoard = $toPaint
									}
								} catch {}
							}
							$again = $false
							try { if ([bool]$W.TaskBoardPaintQueued) { $again = $true } } catch {}
							try { if ($null -ne $W.PendingTaskBoard) { $again = $true } } catch {}
							# Newer snap arrived during apply.
							try {
								$lg2 = 0; $had2 = 0
								try { $lg2 = [int]$W.TaskBoardLiveGen } catch { $lg2 = 0 }
								try { $had2 = [int]$W.TaskBoardAppliedSeq } catch { $had2 = 0 }
								if ($lg2 -gt 0 -and $lg2 -gt $had2) { $again = $true }
							} catch {}
						} while ($again)
					} finally {
						try { $W.TaskBoardPaintBusy = $false } catch {}
						try {
							$needKick = $false
							try { if ($null -ne $W.PendingTaskBoard) { $needKick = $true } } catch {}
							try {
								$lg3 = 0; $had3 = 0
								try { $lg3 = [int]$W.TaskBoardLiveGen } catch { $lg3 = 0 }
								try { $had3 = [int]$W.TaskBoardAppliedSeq } catch { $had3 = 0 }
								if ($lg3 -gt 0 -and $lg3 -gt $had3) { $needKick = $true }
							} catch {}
							if ($needKick -and $W.KickTaskBoardPaint -is [System.Action]) {
								[void]$W.Window.Dispatcher.BeginInvoke(
									[System.Windows.Threading.DispatcherPriority]::Send,
									$W.KickTaskBoardPaint
								)
							}
						} catch {}
					}
				} catch {}
			}.GetNewClosure()

			# STA entry point for agent BeginInvoke.
			$W.KickTaskBoardPaint = $null
			try {
				$kickSb = {
					try {
						$fn = $null
						try { $fn = $W.DrainTaskBoardPaint } catch { $fn = $null }
						if ($null -ne $fn) { & $fn }
					} catch {}
				}.GetNewClosure()
				try {
					$W.KickTaskBoardPaint = [System.Action]$kickSb
				} catch {
					$W.KickTaskBoardPaint = $kickSb
				}
			} catch {
				try { $W.KickTaskBoardPaint = $null } catch {}
			}

			$W.ApplyTaskBoardSticky = {
				param($S)
				if ($null -eq $S) { return }
				# Prefer latest LiveSnap so we never paint a dequeued stale picture.
				try {
					$live = $null
					try { $live = $W.TaskBoardLiveSnap } catch { $live = $null }
					if ($null -ne $live) {
						$sSeq = 0; $lSeq = 0
						try {
							if ($S -is [System.Collections.IDictionary] -and $S.Contains('Seq')) { $sSeq = [int]$S['Seq'] }
							else { $sSeq = [int]$S.Seq }
						} catch { $sSeq = 0 }
						try {
							if ($live -is [System.Collections.IDictionary] -and $live.Contains('Seq')) { $lSeq = [int]$live['Seq'] }
							else { $lSeq = [int]$live.Seq }
						} catch { $lSeq = 0 }
						if ($lSeq -gt 0 -and ($sSeq -le 0 -or $lSeq -gt $sSeq)) { $S = $live }
					}
				} catch {}
				# Skip only exact already-applied gen (never drop a newer LiveSnap).
				try {
					$inSeq = 0; $had = 0
					try {
						if ($S -is [System.Collections.IDictionary] -and $S.Contains('Seq')) { $inSeq = [int]$S['Seq'] }
						else { $inSeq = [int]$S.Seq }
					} catch { $inSeq = 0 }
					try { $had = [int]$W.TaskBoardAppliedSeq } catch { $had = 0 }
					if ($inSeq -gt 0 -and $had -gt 0 -and $inSeq -lt $had) { return }
					if ($inSeq -gt 0 -and $had -gt 0 -and $inSeq -eq $had) {
						# Same gen already on screen — still allow forced urgent re-paint only if flagged.
						$urg = $false
						try { $urg = [bool]$W.TaskBoardPaintUrgent } catch { $urg = $false }
						if (-not $urg) { return }
					}
				} catch {}
				try { $W.TaskBoardPaintUrgent = $false } catch {}
				try {
					if ((-not $W.TaskBoardSticky -or -not $W.TaskBoardStickyScroll) -and $W.Window) {
						if (-not $W.TaskBoardSticky) { $W.TaskBoardSticky = $W.Window.FindName('TaskBoardSticky') }
						if (-not $W.TaskBoardStickyScroll) { $W.TaskBoardStickyScroll = $W.Window.FindName('TaskBoardStickyScroll') }
						if (-not $W.TaskBoardStickyInner) { $W.TaskBoardStickyInner = $W.Window.FindName('TaskBoardStickyInner') }
						if (-not $W.TaskBoardStickyHeader) { $W.TaskBoardStickyHeader = $W.Window.FindName('TaskBoardStickyHeader') }
						if (-not $W.TaskBoardStickyItems) { $W.TaskBoardStickyItems = $W.Window.FindName('TaskBoardStickyItems') }
						if (-not $W.TaskBoardStickyGoal) { $W.TaskBoardStickyGoal = $W.Window.FindName('TaskBoardStickyGoal') }
						if (-not $W.TaskBoardStickySum) { $W.TaskBoardStickySum = $W.Window.FindName('TaskBoardStickySum') }
						if (-not $W.TaskBoardStickyLabel) { $W.TaskBoardStickyLabel = $W.Window.FindName('TaskBoardStickyLabel') }
					}
				} catch {}
				if (-not $W.TaskBoardSticky) { return }
				$hostBd = $W.TaskBoardSticky
				$inner = $W.TaskBoardStickyInner
				$hdrBd = $null
				try { $hdrBd = $W.TaskBoardStickyHeader } catch { $hdrBd = $null }
				$itemsSp = $W.TaskBoardStickyItems
				$goalTb = $W.TaskBoardStickyGoal
				$sumTb = $W.TaskBoardStickySum
				$labelTb = $W.TaskBoardStickyLabel
				if (-not $itemsSp) { return }
				try {
					if ($W.TaskBoardRetractTimer) {
						$W.TaskBoardRetractTimer.Stop()
						$W.TaskBoardRetractTimer = $null
					}
				} catch {}
				try { & $W.StopTaskBoardPulse } catch {}

				$hide = $false
				try {
					$emp = $false; $wshow = $true
					if ($S -is [System.Collections.IDictionary]) {
						if ($S.Contains('Empty')) { $emp = [bool]$S['Empty'] }
						if ($S.Contains('WantShow')) { $wshow = [bool]$S['WantShow'] }
					} else {
						$emp = [bool]$S.Empty
						$wshow = [bool]$S.WantShow
					}
					$hide = $emp -or -not $wshow
				} catch { $hide = $true }
				if ($hide) {
					# Mark gen applied even on hide so retract/clear does not leave paint stuck.
					try {
						$hideSeq = 0
						try {
							if ($S -is [System.Collections.IDictionary] -and $S.Contains('Seq')) { $hideSeq = [int]$S['Seq'] }
							else { $hideSeq = [int]$S.Seq }
						} catch { $hideSeq = 0 }
						if ($hideSeq -gt 0) {
							$prevH = 0
							try { $prevH = [int]$W.TaskBoardAppliedSeq } catch { $prevH = 0 }
							if ($hideSeq -ge $prevH) { $W.TaskBoardAppliedSeq = $hideSeq }
						}
					} catch {}
					try { if ($W.SetBrandAccentIdle) { & $W.SetBrandAccentIdle } } catch {}
					try {
						$curH = 0.0
						try {
							if ($hostBd.Visibility -eq [System.Windows.Visibility]::Visible -and $hostBd.ActualHeight -gt 0) {
								$curH = [double]$hostBd.ActualHeight
							}
						} catch {}
						try { $hostBd.BeginAnimation([System.Windows.FrameworkElement]::MaxHeightProperty, $null) } catch {}
						if ($curH -le 1.0) {
							$hostBd.MaxHeight = 0
							$hostBd.Visibility = [System.Windows.Visibility]::Collapsed
							try { $itemsSp.Children.Clear() } catch {}
							$W.TaskBoardExpanded = $false
							return
						}
						$hostBd.MaxHeight = $curH
						$anim = New-Object System.Windows.Media.Animation.DoubleAnimation
						$anim.From = $curH
						$anim.To = 0.0
						$anim.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(260))
						try {
							$ease = New-Object System.Windows.Media.Animation.QuadraticEase
							$ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseIn
							$anim.EasingFunction = $ease
						} catch {}
						$anim.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
						$anim.add_Completed({
							try {
								$hostBd.BeginAnimation([System.Windows.FrameworkElement]::MaxHeightProperty, $null)
								$hostBd.MaxHeight = 0
								$hostBd.Visibility = [System.Windows.Visibility]::Collapsed
								try { $itemsSp.Children.Clear() } catch {}
								$W.TaskBoardExpanded = $false
							} catch {}
						}.GetNewClosure())
						$hostBd.BeginAnimation([System.Windows.FrameworkElement]::MaxHeightProperty, $anim)
					} catch {
						try {
							$hostBd.MaxHeight = 0
							$hostBd.Visibility = [System.Windows.Visibility]::Collapsed
							$W.TaskBoardExpanded = $false
						} catch {}
					}
					return
				}

				# TaskBoard open: keep accent mostly dark with a slow sliding highlight
				try { if ($W.SetBrandAccentShimmer) { & $W.SetBrandAccentShimmer } } catch {}

				$snapGoal = ''; $snapSum = ''; $snapOpenN = 0; $snapFocus = ''
				$pausedUi = $false
				try {
					if ($S -is [System.Collections.IDictionary]) {
						if ($S.Contains('Goal')) { $snapGoal = [string]$S['Goal'] }
						if ($S.Contains('Summary')) { $snapSum = [string]$S['Summary'] }
						if ($S.Contains('OpenN')) { $snapOpenN = [int]$S['OpenN'] }
						if ($S.Contains('FocusId')) { $snapFocus = [string]$S['FocusId'] }
						if ($S.Contains('Paused')) { $pausedUi = [bool]$S['Paused'] }
					} else {
						$snapGoal = [string]$S.Goal
						$snapSum = [string]$S.Summary
						$snapOpenN = [int]$S.OpenN
						$snapFocus = [string]$S.FocusId
						$pausedUi = [bool]$S.Paused
					}
				} catch {}
				try { if ($goalTb) { $goalTb.Text = $snapGoal } } catch {}
				try { if ($sumTb) { $sumTb.Text = $snapSum } } catch {}
				$conv = New-Object System.Windows.Media.BrushConverter
				if (-not $W.BrushCache) { $W.BrushCache = @{} }
				$hxLabel = '#7DCFFF'
				try {
					if ($pausedUi) { $hxLabel = '#E0AF68' }
					elseif ($snapOpenN -le 0) { $hxLabel = '#9ECE6A' }
				} catch {}
				try {
					if ($labelTb) {
						$labelTb.Text = $(if ($pausedUi) { 'TaskBoard paused' } else { 'TaskBoard' })
						if (-not $W.BrushCache.ContainsKey($hxLabel)) {
							$W.BrushCache[$hxLabel] = $conv.ConvertFromString($hxLabel)
						}
						$labelTb.Foreground = $W.BrushCache[$hxLabel]
					}
				} catch {}

				$hxPend = '#A0A0AA'; $hxProg = '#BB9AF7'; $hxDone = '#9ECE6A'; $hxBlock = '#F7768E'
				$hxPause = '#E0AF68'   # same yellow used elsewhere (compacting / soft warn)
				$hxProgBg = '#2A2238'; $hxProgBg2 = '#3D2F55'
				$hxDoneBg = '#1E2A1C'; $hxBlockBg = '#3D2228'; $hxPendBg = '#14141A'
				$hxPauseBg = '#3D3422'; $hxPauseBg2 = '#5C4A28'
				$hxProgFg2 = '#D4B8FF'; $hxPauseFg2 = '#FFD9A0'
				foreach ($hx in @($hxPend, $hxProg, $hxDone, $hxBlock, $hxPause, $hxProgBg, $hxProgBg2, $hxDoneBg, $hxBlockBg, $hxPendBg, $hxPauseBg, $hxPauseBg2, $hxProgFg2, $hxPauseFg2)) {
					if (-not $W.BrushCache.ContainsKey($hx)) {
						try { $W.BrushCache[$hx] = $conv.ConvertFromString($hx) } catch {}
					}
				}
				$mono = $null
				try { $mono = $W.MonoFont } catch {}
				if (-not $mono) {
					try { $mono = New-Object System.Windows.Media.FontFamily('Consolas, Cascadia Mono, Courier New') } catch {}
				}
				try { $itemsSp.Children.Clear() } catch {}
				$pulseList = New-Object System.Collections.ArrayList
				$focusId = $snapFocus
				if ([string]::IsNullOrWhiteSpace($focusId)) {
					try { $focusId = [string]$S.FocusId } catch { $focusId = '' }
				}
				$focusRow = $null
				$firstProgRow = $null
				# Body max width for ellipsis (avoid GridLength star ctor issues on PS 5.1)
				$bodyMaxW = 520.0
				try {
					$aw = 0.0
					try { $aw = [double]$hostBd.ActualWidth } catch { $aw = 0 }
					if ($aw -lt 80 -and $hostBd.Parent) {
						try { $aw = [double]$hostBd.Parent.ActualWidth } catch {}
					}
					if ($aw -gt 120) { $bodyMaxW = [math]::Max(160.0, $aw - 80.0) }
				} catch {}
				$snapRows = @()
				try {
					if ($S -is [System.Collections.IDictionary] -and $S.Contains('Rows')) { $snapRows = @($S['Rows']) }
					else { $snapRows = @($S.Rows) }
				} catch { $snapRows = @() }
				foreach ($rr in $snapRows) {
					try {
						$id = ''; $titleR = ''; $st = 'pending'; $note = ''
						if ($rr -is [System.Collections.IDictionary]) {
							try { if ($rr.Contains('Id')) { $id = [string]$rr['Id'] } } catch {}
							try { if ($rr.Contains('Title')) { $titleR = [string]$rr['Title'] } } catch {}
							try { if ($rr.Contains('Status')) { $st = ([string]$rr['Status']).ToLowerInvariant() } } catch { $st = 'pending' }
							try { if ($rr.Contains('Note')) { $note = [string]$rr['Note'] } } catch {}
						} else {
							try { $id = [string]$rr.Id } catch {}
							try { $titleR = [string]$rr.Title } catch {}
							try { $st = ([string]$rr.Status).ToLowerInvariant() } catch { $st = 'pending' }
							try { $note = [string]$rr.Note } catch {}
						}
						if ([string]::IsNullOrWhiteSpace($st)) { $st = 'pending' }
						if ($st -in @('active', 'doing', 'wip', 'working')) { $st = 'in_progress' }
						if ($st -in @('complete', 'completed', 'finished')) { $st = 'done' }
						$mark = '[ ]'; $fgHex = $hxPend; $bgHex = $hxPendBg
						if ($st -eq 'done') { $mark = '[x]'; $fgHex = $hxDone; $bgHex = $hxDoneBg }
						elseif ($st -eq 'in_progress') { $mark = '[>]'; $fgHex = $hxProg; $bgHex = $hxProgBg }
						elseif ($st -eq 'paused') { $mark = '[=]'; $fgHex = $hxPause; $bgHex = $hxPauseBg }
						elseif ($st -eq 'blocked') { $mark = '[!]'; $fgHex = $hxBlock; $bgHex = $hxBlockBg }

						$rowBd = New-Object System.Windows.Controls.Border
						$rowBd.CornerRadius = New-Object System.Windows.CornerRadius(3)
						$rowBd.Padding = New-Object System.Windows.Thickness(8, 3, 8, 3)
						$rowBd.Margin = New-Object System.Windows.Thickness(0, 0, 0, 2)
						$rowBd.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Stretch
						$rowBd.SnapsToDevicePixels = $true
						try { $rowBd.Focusable = $false } catch {}
						try { $rowBd.Tag = $id } catch {}

						$bgBrush = New-Object System.Windows.Media.SolidColorBrush
						try {
							$bgBrush.Color = ([System.Windows.Media.SolidColorBrush]$conv.ConvertFromString($bgHex)).Color
						} catch {
							$bgBrush.Color = [System.Windows.Media.Color]::FromRgb(20, 20, 26)
						}
						$rowBd.Background = $bgBrush

						$sp = New-Object System.Windows.Controls.StackPanel
						$sp.Orientation = [System.Windows.Controls.Orientation]::Horizontal
						$fgBrush = New-Object System.Windows.Media.SolidColorBrush
						try {
							$fgBrush.Color = ([System.Windows.Media.SolidColorBrush]$conv.ConvertFromString($fgHex)).Color
						} catch {
							$fgBrush.Color = [System.Windows.Media.Color]::FromRgb(200, 200, 208)
						}
						$markTb = New-Object System.Windows.Controls.TextBlock
						$markTb.Text = $mark
						$markTb.Width = 28
						$markTb.FontFamily = $mono
						$markTb.FontSize = 12
						$markTb.FontWeight = [System.Windows.FontWeights]::SemiBold
						$markTb.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
						$markTb.Foreground = $fgBrush
						try { $markTb.IsHitTestVisible = $false } catch {}

						$body = $titleR
						if ($id) { $body = ('{0}: {1}' -f $id, $titleR) }
						if ($note) { $body += ('  - {0}' -f $note) }
						$tipText = ('{0} {1}' -f $mark, $body).Trim()
						$bodyTb = New-Object System.Windows.Controls.TextBlock
						$bodyTb.Text = $body
						$bodyTb.FontFamily = $mono
						$bodyTb.FontSize = 12
						$bodyTb.TextWrapping = [System.Windows.TextWrapping]::NoWrap
						$bodyTb.TextTrimming = [System.Windows.TextTrimming]::CharacterEllipsis
						$bodyTb.MaxWidth = $bodyMaxW
						$bodyTb.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
						$bodyTb.Foreground = $fgBrush
						try { $bodyTb.IsHitTestVisible = $false } catch {}
						if ($st -eq 'in_progress' -or $st -eq 'paused') {
							try { $bodyTb.FontWeight = [System.Windows.FontWeights]::SemiBold } catch {}
						}
						[void]$sp.Children.Add($markTb)
						[void]$sp.Children.Add($bodyTb)
						$rowBd.Child = $sp
						# Themed full-text tooltip (never fail the row if tip build breaks)
						try {
							if (-not [string]::IsNullOrWhiteSpace($tipText)) {
								$tipOk = $false
								try {
									if ($W.SetThemedToolTip) {
										& $W.SetThemedToolTip $rowBd $tipText 420
										$tipOk = $true
									}
								} catch { $tipOk = $false }
								if (-not $tipOk) {
									# Inline dark tip (no SystemBrush chrome)
									$tip = New-Object System.Windows.Controls.ToolTip
									try { $tip.OverridesDefaultStyle = $true } catch {}
									$tip.Background = $conv.ConvertFromString('#1A1A1E')
									$tip.Foreground = $conv.ConvertFromString('#C8C8D0')
									$tip.BorderBrush = $conv.ConvertFromString('#3A3A42')
									$tip.BorderThickness = New-Object System.Windows.Thickness(1)
									$tip.Padding = New-Object System.Windows.Thickness(10, 7, 10, 7)
									$ttb = New-Object System.Windows.Controls.TextBlock
									$ttb.Text = $tipText
									$ttb.TextWrapping = [System.Windows.TextWrapping]::Wrap
									$ttb.MaxWidth = 420
									$ttb.Foreground = $tip.Foreground
									$ttb.FontSize = 12
									if ($mono) { $ttb.FontFamily = $mono }
									$tip.Content = $ttb
									$rowBd.ToolTip = $tip
								}
							}
						} catch {
							try { $rowBd.ToolTip = $tipText } catch {}
						}
						[void]$itemsSp.Children.Add($rowBd)
						if ($st -eq 'in_progress' -or $st -eq 'paused') {
							if ($null -eq $firstProgRow) { $firstProgRow = $rowBd }
						}
						if ($focusId -and $id -and [string]::Equals($id, $focusId, [StringComparison]::OrdinalIgnoreCase)) {
							$focusRow = $rowBd
						}
						# Pulse focused active row (color only).
						$doPulse = $false
						if ($st -eq 'in_progress' -or $st -eq 'paused') {
							if ($focusId -and $id -and [string]::Equals($id, $focusId, [StringComparison]::OrdinalIgnoreCase)) {
								$doPulse = $true
							} elseif (-not $focusId -and [object]::ReferenceEquals($rowBd, $firstProgRow)) {
								$doPulse = $true
							}
						}
						if ($doPulse) {
							try {
								if ($W.StartColorPulse) {
									if ($st -eq 'paused') {
										& $W.StartColorPulse $bgBrush $hxPauseBg $hxPauseBg2 1400
										& $W.StartColorPulse $fgBrush $hxPause $hxPauseFg2 1400
									} else {
										& $W.StartColorPulse $bgBrush $hxProgBg $hxProgBg2 1200
										& $W.StartColorPulse $fgBrush $hxProg $hxProgFg2 1200
									}
									[void]$pulseList.Add($bgBrush)
									[void]$pulseList.Add($fgBrush)
								}
							} catch {}
						}
					} catch {
						# One bad row must not kill the whole board paint
						try { $W.LastTaskBoardPaintErr = [string]$_.Exception.Message } catch {}
					}
				}
				if ($null -eq $focusRow) { $focusRow = $firstProgRow }
				$W.TaskBoardPulseEls = $pulseList
				$W.TaskBoardFocusRow = $focusRow

				try { $hostBd.BeginAnimation([System.Windows.FrameworkElement]::MaxHeightProperty, $null) } catch {}
				# Header is fixed outside the scroller; ScrollViewer height = first N task rows only
				$maxRowsVis = 5
				try {
					if ($null -ne $W.TaskBoardMaxVisibleRows -and [int]$W.TaskBoardMaxVisibleRows -gt 0) {
						$maxRowsVis = [int]$W.TaskBoardMaxVisibleRows
					}
				} catch {}
				if ($maxRowsVis -lt 1) { $maxRowsVis = 5 }
				$maxScroll = 140.0
				$targetH = 96.0
				$headerH = 28.0
				$hostCap = 180.0
				$availW = 640.0
				try {
					try { $availW = [double]$hostBd.ActualWidth } catch { $availW = 0 }
					if ($availW -lt 40) {
						try { if ($hostBd.Parent) { $availW = [double]$hostBd.Parent.ActualWidth } } catch {}
					}
					if ($availW -lt 40) { $availW = 640.0 }
					$measureW = [math]::Max(80.0, $availW - 4.0)
					$measSize = New-Object System.Windows.Size($measureW, [double]::PositiveInfinity)
					try {
						if ($hdrBd) {
							$hdrBd.Measure($measSize)
							$headerH = [double]$hdrBd.DesiredSize.Height
						} elseif ($inner -and $inner.Children.Count -gt 0) {
							$hdrEl = $inner.Children[0]
							$hdrEl.Measure($measSize)
							$headerH = [double]$hdrEl.DesiredSize.Height
						}
					} catch {}
					if ($headerH -lt 20) { $headerH = 28.0 }
					$rowsH = 0.0
					$nRow = 0
					try {
						foreach ($c in @($itemsSp.Children)) {
							if ($nRow -ge $maxRowsVis) { break }
							$c.Measure($measSize)
							$rowsH += [double]$c.DesiredSize.Height
							try { $rowsH += [double]$c.Margin.Top + [double]$c.Margin.Bottom } catch {}
							$nRow++
						}
					} catch {}
					# Scroll viewport = rows only (header is outside)
					$maxScroll = [math]::Max(48.0, $rowsH + 10.0)
					try { $W.TaskBoardMaxScrollH = $maxScroll } catch {}
					# Host = fixed header + scroller viewport
					$targetH = [math]::Max(40.0, $headerH + $maxScroll + 2.0)
					# If fewer than N rows, shrink host to content (no empty scroll space)
					try {
						$allRowsH = 0.0
						foreach ($c2 in @($itemsSp.Children)) {
							$c2.Measure($measSize)
							$allRowsH += [double]$c2.DesiredSize.Height
							try { $allRowsH += [double]$c2.Margin.Top + [double]$c2.Margin.Bottom } catch {}
						}
						$contentH = $headerH + $allRowsH + 12.0
						if ($contentH -lt $targetH) { $targetH = [math]::Max(40.0, $contentH) }
						if ($allRowsH + 10.0 -lt $maxScroll) { $maxScroll = [math]::Max(24.0, $allRowsH + 10.0) }
					} catch {}
				} catch {
					try {
						if ($null -ne $W.TaskBoardMaxScrollH -and [double]$W.TaskBoardMaxScrollH -gt 40) {
							$maxScroll = [double]$W.TaskBoardMaxScrollH
						}
					} catch {}
				}
				$sv = $null
				try {
					$sv = $W.TaskBoardStickyScroll
					if (-not $sv -and $W.Window) {
						try { $sv = $W.Window.FindName('TaskBoardStickyScroll'); $W.TaskBoardStickyScroll = $sv } catch {}
					}
					if ($sv) {
						# Only the items list scrolls under the fixed title banner
						$sv.MaxHeight = $maxScroll
						try { $sv.VerticalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Auto } catch {}
						try { $sv.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Disabled } catch {}
					}
				} catch {}
				# Host = header + scroll viewport
				$hostCap = $headerH + $maxScroll + 4.0
				if ($targetH -gt $hostCap) { $targetH = $hostCap }

				# Scroll active / highlighted task into view (items panel only; header stays put)
				$scrollFocusIntoView = {
					param($ScrollViewer, $Row, $ItemsPanel)
					if (-not $ScrollViewer -or -not $Row) { return }
					try {
						try { $ScrollViewer.UpdateLayout() } catch {}
						try { if ($ItemsPanel) { $ItemsPanel.UpdateLayout() } } catch {}
						try { $Row.UpdateLayout() } catch {}
						try { $Row.BringIntoView() } catch {}
						try {
							$origin = $null
							if ($ItemsPanel) { $origin = $ItemsPanel }
							if (-not $origin) {
								try { $origin = $ScrollViewer.Content } catch { $origin = $null }
							}
							if (-not $origin) { return }
							$t = $Row.TransformToAncestor($origin)
							if (-not $t) { return }
							$pt = $t.Transform((New-Object System.Windows.Point(0, 0)))
							$rowTop = [double]$pt.Y
							$rowH = [double]$Row.ActualHeight
							if ($rowH -le 0) {
								try { $rowH = [double]$Row.DesiredSize.Height } catch { $rowH = 24.0 }
							}
							if ($rowH -le 0) { $rowH = 24.0 }
							$rowBot = $rowTop + $rowH
							$vp = [double]$ScrollViewer.ViewportHeight
							if ($vp -le 1) { $vp = [double]$ScrollViewer.ActualHeight }
							$off = [double]$ScrollViewer.VerticalOffset
							$pad = 4.0
							$newOff = $off
							if ($rowTop -lt ($off + $pad)) {
								$newOff = [math]::Max(0.0, $rowTop - $pad)
							} elseif ($rowBot -gt ($off + $vp - $pad)) {
								$newOff = [math]::Max(0.0, $rowBot - $vp + $pad)
							}
							$maxOff = 0.0
							try { $maxOff = [double]$ScrollViewer.ScrollableHeight } catch { $maxOff = 0.0 }
							if ($newOff -gt $maxOff) { $newOff = $maxOff }
							if ([math]::Abs($newOff - $off) -gt 0.5) {
								$ScrollViewer.ScrollToVerticalOffset($newOff)
							}
						} catch {}
					} catch {}
				}.GetNewClosure()

				$wasOpen = $false
				try { $wasOpen = [bool]$W.TaskBoardExpanded } catch { $wasOpen = $false }
				# Ensure expand animation is not holding MaxHeight at 0 after a mid-flight update
				try { $hostBd.BeginAnimation([System.Windows.FrameworkElement]::MaxHeightProperty, $null) } catch {}
				$hostBd.Visibility = [System.Windows.Visibility]::Visible
				# Host height = fixed title banner + items scroller (not scroller alone)
				$showH = $targetH
				if ($showH -lt 40) { $showH = $hostCap }
				if ($showH -gt $hostCap) { $showH = $hostCap }
				if ($showH -lt 40) { $showH = 96.0 }
				if (-not $wasOpen) {
					$hostBd.MaxHeight = 0
					try { $hostBd.UpdateLayout() } catch {}
					$anim = New-Object System.Windows.Media.Animation.DoubleAnimation
					$anim.From = 0.0
					$anim.To = $showH
					$anim.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(300))
					try {
						$ease = New-Object System.Windows.Media.Animation.QuadraticEase
						$ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
						$anim.EasingFunction = $ease
					} catch {}
					$anim.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
					$capH = $hostCap
					$focusRowCap = $focusRow
					$svCap = $sv
					$itemsCap = $itemsSp
					$anim.add_Completed({
						try {
							$hostBd.BeginAnimation([System.Windows.FrameworkElement]::MaxHeightProperty, $null)
							# Cap at header + scroll viewport so items can scroll under fixed title
							$hostBd.MaxHeight = $capH
							$W.TaskBoardExpanded = $true
							try { & $scrollFocusIntoView $svCap $focusRowCap $itemsCap } catch {}
						} catch {}
					}.GetNewClosure())
					$hostBd.BeginAnimation([System.Windows.FrameworkElement]::MaxHeightProperty, $anim)
					$W.TaskBoardExpanded = $true
				} else {
					# Already open: force height + layout so status/color changes repaint
					$hostBd.MaxHeight = $hostCap
					$W.TaskBoardExpanded = $true
					try { $itemsSp.InvalidateMeasure(); $itemsSp.InvalidateArrange() } catch {}
					try { if ($inner) { $inner.InvalidateMeasure(); $inner.UpdateLayout() } } catch {}
					try { $hostBd.InvalidateMeasure(); $hostBd.UpdateLayout() } catch {}
					try {
						if ($sv) {
							try { $sv.UpdateLayout() } catch {}
							try {
								$maxOff = [double]$sv.ScrollableHeight
								if ($sv.VerticalOffset -gt $maxOff) {
									$sv.ScrollToVerticalOffset($maxOff)
								}
							} catch {}
							try { & $scrollFocusIntoView $sv $focusRow $itemsSp } catch {}
						}
					} catch {}
					# Second scroll after layout settles (listview was a frame behind auto-advance)
					try {
						$sv2 = $sv; $fr2 = $focusRow; $ip2 = $itemsSp
						$scrollAgain = {
							try { & $scrollFocusIntoView $sv2 $fr2 $ip2 } catch {}
						}.GetNewClosure()
						if ($W.Window -and $W.Window.Dispatcher) {
							[void]$W.Window.Dispatcher.BeginInvoke(
								[Action]$scrollAgain,
								[System.Windows.Threading.DispatcherPriority]::Loaded
							)
						}
					} catch {}
				}
				try {
					$seqDone = 0
					try {
						if ($S -is [System.Collections.IDictionary] -and $S.Contains('Seq')) { $seqDone = [int]$S['Seq'] }
						else { $seqDone = [int]$S.Seq }
					} catch { $seqDone = 0 }
					if ($seqDone -gt 0) {
						$prevA = 0
						try { $prevA = [int]$W.TaskBoardAppliedSeq } catch { $prevA = 0 }
						if ($seqDone -ge $prevA) { $W.TaskBoardAppliedSeq = $seqDone }
					}
				} catch {}

				# Auto-retract after complete
				$doRetract = $false
				try {
					$wr = $false; $tot = 0; $opn = 0
					if ($S -is [System.Collections.IDictionary]) {
						if ($S.Contains('WantRetract')) { $wr = [bool]$S['WantRetract'] }
						if ($S.Contains('Total')) { $tot = [int]$S['Total'] }
						if ($S.Contains('OpenN')) { $opn = [int]$S['OpenN'] }
					} else {
						$wr = [bool]$S.WantRetract
						$tot = [int]$S.Total
						$opn = [int]$S.OpenN
					}
					$doRetract = $wr -and $tot -gt 0 -and $opn -eq 0
				} catch { $doRetract = $false }
				if ($doRetract) {
					try {
						$tmr = New-Object System.Windows.Threading.DispatcherTimer
						$tmr.Interval = [TimeSpan]::FromMilliseconds(2000)
						$tmr.add_Tick({
							param($sender, $e)
							try {
								$sender.Stop()
								$W.TaskBoardRetractTimer = $null
								# Only hide if still complete (LiveSnap may have reopened)
								$stillOpen = $false
								try {
									$chk = $null
									try { $chk = $W.TaskBoardLiveSnap } catch { $chk = $null }
									if ($null -eq $chk) { try { $chk = $W.PendingTaskBoard } catch { $chk = $null } }
									if ($null -ne $chk) {
										$ws = $false; $on = 0
										if ($chk -is [System.Collections.IDictionary]) {
											if ($chk.Contains('WantShow')) { $ws = [bool]$chk['WantShow'] }
											if ($chk.Contains('OpenN')) { $on = [int]$chk['OpenN'] }
										} else {
											$ws = [bool]$chk.WantShow
											$on = [int]$chk.OpenN
										}
										if ($ws -and $on -gt 0) { $stillOpen = $true }
									}
								} catch {}
								if (-not $stillOpen) {
									# Monotonic seq — never TickCount (would freeze later paints via AppliedSeq).
									$rseq = 1
									try {
										$prevR = 0
										try { $prevR = [int]$W.TaskBoardSeqCounter } catch { $prevR = 0 }
										if ($prevR -lt 0) { $prevR = 0 }
										$rseq = $prevR + 1
										$W.TaskBoardSeqCounter = $rseq
									} catch { $rseq = 1 }
									$rsnap = New-Object System.Collections.Hashtable
									$rsnap['WantShow'] = $false
									$rsnap['WantRetract'] = $true
									$rsnap['Empty'] = $true
									$rsnap['Paused'] = $false
									$rsnap['Goal'] = ''
									$rsnap['Summary'] = ''
									$rsnap['Rows'] = @()
									$rsnap['Action'] = 'retract'
									$rsnap['OpenN'] = 0
									$rsnap['DoneN'] = 0
									$rsnap['Total'] = 0
									$rsnap['FocusId'] = ''
									$rsnap['Seq'] = [int]$rseq
									$W.TaskBoardLiveSnap = $rsnap
									$W.TaskBoardLiveGen = $rseq
									$W.TaskBoardWantSeq = $rseq
									$W.PendingTaskBoard = $rsnap
									$W.TaskBoardPaintUrgent = $true
									try {
										if ($W.KickTaskBoardPaint -is [System.Action]) {
											[void]$W.Window.Dispatcher.BeginInvoke(
												[System.Windows.Threading.DispatcherPriority]::Send,
												$W.KickTaskBoardPaint
											)
										}
									} catch {}
								}
							} catch {}
						}.GetNewClosure())
						$W.TaskBoardRetractTimer = $tmr
						$tmr.Start()
					} catch {}
				}
			}.GetNewClosure()
			$W.HdrPoweredBy = $window.FindName('HdrPoweredBy')
			$W.HdrPoweredByShadow = $window.FindName('HdrPoweredByShadow')
			$W.HdrPoweredByHost = $window.FindName('HdrPoweredByHost')
			$W.CustomTitleBar = $window.FindName('CustomTitleBar')
			$W.TitleRobotHost = $window.FindName('TitleRobotHost')
			$W.TitleRobotPath = $window.FindName('TitleRobotPath')
			$W.TitleRobotStop0 = $window.FindName('TitleRobotStop0')
			$W.TitleRobotStop1 = $window.FindName('TitleRobotStop1')
			$W.TitleRobotStop2 = $window.FindName('TitleRobotStop2')
			$W.TitleRobotShadow = $window.FindName('TitleRobotShadow')
			$W.TitleRobotTranslate = $window.FindName('TitleRobotTranslate')
			# Resolve gradient/effect refs if FindName missed them
			if ((-not $W.TitleRobotStop0 -or -not $W.TitleRobotStop1 -or -not $W.TitleRobotStop2) -and $W.TitleRobotPath) {
				try {
					$rb = $W.TitleRobotPath.Fill
					if ($rb -is [System.Windows.Media.LinearGradientBrush] -and $rb.GradientStops.Count -ge 3) {
						$W.TitleRobotStop0 = $rb.GradientStops[0]
						$W.TitleRobotStop1 = $rb.GradientStops[1]
						$W.TitleRobotStop2 = $rb.GradientStops[2]
					}
				} catch {}
			}
			if (-not $W.TitleRobotShadow -and $W.TitleRobotPath) {
				try { $W.TitleRobotShadow = $W.TitleRobotPath.Effect } catch {}
			}
			if (-not $W.TitleRobotTranslate -and $W.TitleRobotPath) {
				try {
					$rt = $W.TitleRobotPath.RenderTransform
					if ($rt -is [System.Windows.Media.TranslateTransform]) {
						$W.TitleRobotTranslate = $rt
					} else {
						$tt = New-Object System.Windows.Media.TranslateTransform(0, 0)
						$W.TitleRobotPath.RenderTransform = $tt
						$W.TitleRobotTranslate = $tt
					}
				} catch {}
			}
			if (-not $W.RobotGeomCache) { $W.RobotGeomCache = @{} }
			$W.RobotMood = ''
			$W.RobotErrorBounceOn = $false
			$W.RobotErrorStoryboard = $null
			$W.StopRobotErrorBounce = {
				try {
					if ($W.RobotErrorStoryboard) {
						try { $W.RobotErrorStoryboard.Stop() } catch {}
						try { $W.RobotErrorStoryboard.Children.Clear() } catch {}
						$W.RobotErrorStoryboard = $null
					}
					if ($W.TitleRobotTranslate) {
						try { $W.TitleRobotTranslate.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $null) } catch {}
						$W.TitleRobotTranslate.Y = 0
						$W.TitleRobotTranslate.X = 0
					}
					if ($W.TitleRobotShadow) {
						try {
							$W.TitleRobotShadow.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::ShadowDepthProperty, $null)
							$W.TitleRobotShadow.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::BlurRadiusProperty, $null)
						} catch {}
						try {
							$W.TitleRobotShadow.ShadowDepth = 1.25
							$W.TitleRobotShadow.BlurRadius = 3.5
						} catch {}
					}
					$W.RobotErrorBounceOn = $false
				} catch {}
			}.GetNewClosure()
			$W.StartRobotErrorBounce = {
				try {
					if ([bool]$W.RobotErrorBounceOn -and $W.RobotErrorStoryboard) { return }
					if (-not $W.TitleRobotPath) { return }
					if (-not $W.TitleRobotTranslate) {
						$tt = New-Object System.Windows.Media.TranslateTransform(0, 0)
						$W.TitleRobotPath.RenderTransform = $tt
						$W.TitleRobotTranslate = $tt
					}
					if (-not $W.TitleRobotShadow) {
						try { $W.TitleRobotShadow = $W.TitleRobotPath.Effect } catch {}
					}
					try {
						if ($W.RobotErrorStoryboard) {
							try { $W.RobotErrorStoryboard.Stop() } catch {}
							$W.RobotErrorStoryboard = $null
						}
						if ($W.TitleRobotTranslate) {
							try { $W.TitleRobotTranslate.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $null) } catch {}
							$W.TitleRobotTranslate.Y = 0
						}
					} catch {}

					$addKf = {
						param($anim, $ms, $val)
						$frame = New-Object System.Windows.Media.Animation.LinearDoubleKeyFrame
						$frame.KeyTime = [System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds($ms))
						$frame.Value = [double]$val
						[void]$anim.KeyFrames.Add($frame)
					}
					$cycleMs = 1350
					$yAnim = New-Object System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames
					$yAnim.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds($cycleMs))
					& $addKf $yAnim 0 0
					& $addKf $yAnim 120 -3
					& $addKf $yAnim 240 0
					& $addKf $yAnim 360 -3
					& $addKf $yAnim 480 0
					& $addKf $yAnim $cycleMs 0

					$depthAnim = New-Object System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames
					$depthAnim.Duration = $yAnim.Duration
					& $addKf $depthAnim 0 1.25
					& $addKf $depthAnim 120 3.0
					& $addKf $depthAnim 240 1.25
					& $addKf $depthAnim 360 3.0
					& $addKf $depthAnim 480 1.25
					& $addKf $depthAnim $cycleMs 1.25

					$blurAnim = New-Object System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames
					$blurAnim.Duration = $yAnim.Duration
					& $addKf $blurAnim 0 3.5
					& $addKf $blurAnim 120 5.0
					& $addKf $blurAnim 240 3.5
					& $addKf $blurAnim 360 5.0
					& $addKf $blurAnim 480 3.5
					& $addKf $blurAnim $cycleMs 3.5

					$story = New-Object System.Windows.Media.Animation.Storyboard
					$story.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
					[System.Windows.Media.Animation.Storyboard]::SetTarget($yAnim, $W.TitleRobotTranslate)
					[System.Windows.Media.Animation.Storyboard]::SetTargetProperty($yAnim, (New-Object System.Windows.PropertyPath([System.Windows.Media.TranslateTransform]::YProperty)))
					[void]$story.Children.Add($yAnim)
					if ($W.TitleRobotShadow) {
						[System.Windows.Media.Animation.Storyboard]::SetTarget($depthAnim, $W.TitleRobotShadow)
						[System.Windows.Media.Animation.Storyboard]::SetTargetProperty($depthAnim, (New-Object System.Windows.PropertyPath([System.Windows.Media.Effects.DropShadowEffect]::ShadowDepthProperty)))
						[void]$story.Children.Add($depthAnim)
						[System.Windows.Media.Animation.Storyboard]::SetTarget($blurAnim, $W.TitleRobotShadow)
						[System.Windows.Media.Animation.Storyboard]::SetTargetProperty($blurAnim, (New-Object System.Windows.PropertyPath([System.Windows.Media.Effects.DropShadowEffect]::BlurRadiusProperty)))
						[void]$story.Children.Add($blurAnim)
					}
					$W.RobotErrorStoryboard = $story
					$story.Begin()
					$W.RobotErrorBounceOn = $true
				} catch {
					try { $W.RobotErrorBounceOn = $false } catch {}
				}
			}.GetNewClosure()
			# Apply robot face and gradient for status
			$W.SetRobotMood = {
				param([string]$Mode = 'ready', [bool]$Force = $false)
				try {
					if (-not $W.TitleRobotPath) { return }
					$m = ([string]$Mode).Trim().ToLowerInvariant()
					$face = 'happy'
					$isError = $false
					if ($m -match 'error|fail|dead') { $face = 'dead'; $isError = $true }
					elseif ($m -match 'think') { $face = 'confused' }
					elseif ($m -match 'work') { $face = 'excited' }
					elseif ($m -match 'compact|autocompact') { $face = 'default' }
					elseif ($m -match 'off|offline|disconnect') { $face = 'off' }
					elseif ($m -match 'angry|warn') { $face = 'angry' }
					elseif ($m -match 'happy|success') { $face = 'happy' }
					elseif ($m -match 'default|neutral|normal') { $face = 'default' }
					if (-not $Force -and [string]$W.RobotMood -eq $face -and [bool]$W.RobotErrorBounceOn -eq $isError) { return }

					$cat = $W.RobotCatalog
					if (-not $cat) { return }
					$faceKey = if (@($cat.Keys) -contains $face) { $face } else { 'default' }
					$data = [string]$cat[$faceKey]
					if ([string]::IsNullOrWhiteSpace($data)) { return }
					if (-not $W.RobotGeomCache) { $W.RobotGeomCache = @{} }
					if (-not $W.RobotGeomCache.ContainsKey($faceKey)) {
						$W.RobotGeomCache[$faceKey] = [System.Windows.Media.Geometry]::Parse($data)
					}
					$W.TitleRobotPath.Data = $W.RobotGeomCache[$faceKey]
					$W.RobotMood = $faceKey

					$cols = if ($isError) {
						@('#D0C4C6', '#B08084', '#9A585C')
					} else {
						@('#C8C8D0', '#6A6A74', '#3A3A42')
					}
					$stops = @($W.TitleRobotStop0, $W.TitleRobotStop1, $W.TitleRobotStop2)
					for ($si = 0; $si -lt 3; $si++) {
						if (-not $stops[$si]) { continue }
						try {
							$stops[$si].Color = [System.Windows.Media.ColorConverter]::ConvertFromString([string]$cols[$si])
						} catch {}
					}
					$tip = switch ($faceKey) {
						'confused' { 'thinking' }
						'excited'  { 'working' }
						'default'  { 'compacting' }
						'dead'     { 'error' }
						'off'      { 'offline' }
						'angry'    { 'warning' }
						default    { 'ready' }
					}
					$tipFull = 'MiniBot' + [string][char]0x00A0 + [string][char]0x00B7 + [string][char]0x00A0 + $tip
					if ($W.TitleRobotHost) { $W.TitleRobotHost.ToolTip = $tipFull }
					elseif ($W.TitleRobotPath) { $W.TitleRobotPath.ToolTip = $tipFull }
					if ($isError) {
						try { if ($W.StartRobotErrorBounce) { & $W.StartRobotErrorBounce } } catch {}
					} else {
						try { if ($W.StopRobotErrorBounce) { & $W.StopRobotErrorBounce } } catch {}
					}
					# Sync taskbar icon with robot face
					try {
						if ($W.ApplyWindowRobotIcon) { & $W.ApplyWindowRobotIcon $faceKey }
					} catch {}
				} catch {}
			}.GetNewClosure()
			try { & $W.SetRobotMood 'ready' $true } catch {}
			$W.TitleDotBrand = $window.FindName('TitleDotBrand')
			$W.TitleDotPath = $window.FindName('TitleDotPath')
			$W.TitleBrand = $window.FindName('TitleBrand')
			$W.TitleBrandName = $window.FindName('TitleBrandName')
			$W.TitleBrandNameShadow = $window.FindName('TitleBrandNameShadow')
			$W.TitlePath = $window.FindName('TitlePath')
			$W.TitlePathShadow = $window.FindName('TitlePathShadow')
			$W.TitlePoweredBy = $window.FindName('TitlePoweredBy')
			$W.TitlePoweredByShadow = $window.FindName('TitlePoweredByShadow')
			$W.TitlePoweredByLabel = $window.FindName('TitlePoweredByLabel')
			$W.TitleModelPicker = $window.FindName('TitleModelPicker')
			$W.TitleModelPickerText = $window.FindName('TitleModelPickerText')
			$W.RemoteModelsSeqApplied = 0
			$W.ModelPickerUpdating = $false
			$W.ActiveModel = $(try { [string]$W.ActiveModel } catch { '' })
			$W.ModelDirty = $false
			if (-not $W.RemoteModels) { $W.RemoteModels = @() }
			$W.ShortModelLabel = {
				param([string]$Id, [int]$MaxLen = 36)
				$m = ([string]$Id).Trim()
				if ([string]::IsNullOrWhiteSpace($m)) { return 'Select Model' }
				# Basename for llama-server path / .gguf ids
				try {
					if ($m -match '^[A-Za-z]:[\\/]' -or $m -match '[\\/]' -or $m -match '(?i)\.gguf$') {
						$leaf = [System.IO.Path]::GetFileName($m.TrimEnd([char[]]@('\', '/')))
						if (-not [string]::IsNullOrWhiteSpace($leaf)) { $m = $leaf }
					}
				} catch {}
				if ($m.Length -le $MaxLen) { return $m }
				$m2 = $m -replace '\.gguf$', ''
				if ($m2.Length -le $MaxLen) { return $m2 }
				return ($m2.Substring(0, [math]::Max(1, $MaxLen - 3)) + '...')
			}.GetNewClosure()
			# Dark themed ToolTip (no SystemBrush / highlight chrome)
			$W.MakeThemedToolTip = {
				param([string]$Text, [double]$MaxWidth = 340)
				if ([string]::IsNullOrWhiteSpace($Text)) { return $null }
				try {
					$bc = New-Object System.Windows.Media.BrushConverter
					foreach ($hx in @('#1A1A1E', '#C8C8D0', '#3A3A42', '#121216')) {
						if (-not $W.BrushCache.ContainsKey($hx)) {
							try { $W.BrushCache[$hx] = $bc.ConvertFromString($hx) } catch {}
						}
					}
					$tipBg = $W.BrushCache['#1A1A1E']
					$tipFg = $W.BrushCache['#C8C8D0']
					$tipBd = $W.BrushCache['#3A3A42']
					$tip = New-Object System.Windows.Controls.ToolTip
					try { $tip.OverridesDefaultStyle = $true } catch {}
					$tip.Background = $tipBg
					$tip.Foreground = $tipFg
					$tip.BorderBrush = $tipBd
					$tip.BorderThickness = New-Object System.Windows.Thickness(1)
					$tip.Padding = New-Object System.Windows.Thickness(10, 7, 10, 7)
					$tip.HasDropShadow = $true
					try { $tip.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Mouse } catch {}
					# Kill system highlight / control brushes on the popup
					try {
						if ($null -eq $tip.Resources) { $tip.Resources = New-Object System.Windows.ResourceDictionary }
						$sysKeys = @(
							[System.Windows.SystemColors]::ControlBrushKey,
							[System.Windows.SystemColors]::ControlLightBrushKey,
							[System.Windows.SystemColors]::ControlLightLightBrushKey,
							[System.Windows.SystemColors]::ControlDarkBrushKey,
							[System.Windows.SystemColors]::HighlightBrushKey,
							[System.Windows.SystemColors]::HighlightTextBrushKey,
							[System.Windows.SystemColors]::InfoBrushKey,
							[System.Windows.SystemColors]::InfoTextBrushKey,
							[System.Windows.SystemColors]::WindowBrushKey,
							[System.Windows.SystemColors]::WindowTextBrushKey,
							[System.Windows.SystemColors]::InactiveSelectionHighlightBrushKey
						)
						foreach ($sk in $sysKeys) {
							try { $tip.Resources[$sk] = $tipBg } catch {}
						}
						try { $tip.Resources[[System.Windows.SystemColors]::ControlTextBrushKey] = $tipFg } catch {}
						try { $tip.Resources[[System.Windows.SystemColors]::InfoTextBrushKey] = $tipFg } catch {}
						try { $tip.Resources[[System.Windows.SystemColors]::WindowTextBrushKey] = $tipFg } catch {}
						try { $tip.Resources[[System.Windows.SystemColors]::HighlightTextBrushKey] = $tipFg } catch {}
					} catch {}
					try {
						$tipTplXaml = @'
<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" TargetType="ToolTip">
  <Border Background="{TemplateBinding Background}"
          BorderBrush="{TemplateBinding BorderBrush}"
          BorderThickness="{TemplateBinding BorderThickness}"
          Padding="{TemplateBinding Padding}"
          CornerRadius="4" SnapsToDevicePixels="True">
    <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"
                      TextElement.Foreground="{TemplateBinding Foreground}"/>
  </Border>
</ControlTemplate>
'@
						$tipTpl = [Windows.Markup.XamlReader]::Parse($tipTplXaml)
						if ($null -ne $tipTpl) { $tip.Template = $tipTpl }
					} catch {}
					$ttb = New-Object System.Windows.Controls.TextBlock
					$ttb.Text = [string]$Text
					$ttb.TextWrapping = [System.Windows.TextWrapping]::Wrap
					$ttb.MaxWidth = [double]$MaxWidth
					$ttb.Foreground = $tipFg
					$ttb.Background = [System.Windows.Media.Brushes]::Transparent
					$ttb.FontSize = 12
					$ttb.LineHeight = 16
					try {
						if ($W.MonoFont) { $ttb.FontFamily = $W.MonoFont }
					} catch {}
					$tip.Content = $ttb
					return $tip
				} catch {
					return [string]$Text
				}
			}.GetNewClosure()
			$W.SetThemedToolTip = {
				param($Target, [string]$Text, [double]$MaxWidth = 340)
				if ($null -eq $Target) { return }
				try {
					$obj = $null
					if ($W.MakeThemedToolTip) { $obj = & $W.MakeThemedToolTip $Text $MaxWidth }
					if ($null -ne $obj) {
						$Target.ToolTip = $obj
						try {
							[System.Windows.Controls.ToolTipService]::SetInitialShowDelay($Target, 350)
							[System.Windows.Controls.ToolTipService]::SetShowDuration($Target, 20000)
							[System.Windows.Controls.ToolTipService]::SetBetweenShowDelay($Target, 100)
							# No system "highlight" flash while tip is open
							[System.Windows.Controls.ToolTipService]::SetShowsToolTipOnKeyboardFocus($Target, $false)
						} catch {}
					} else {
						$Target.ToolTip = [string]$Text
					}
				} catch {
					try { $Target.ToolTip = [string]$Text } catch {}
				}
			}.GetNewClosure()
			$W.BuildModelMenu = {
				param([object[]]$Models = @(), [string]$Selected = '')
				try {
					$chip = $W.TitleModelPicker
					$lbl = $W.TitleModelPickerText
					if (-not $chip) { return }
					$bc = New-Object System.Windows.Media.BrushConverter
					foreach ($hx in @('#1A1A1E', '#C8C8D0', '#3A3A42', '#BB9AF7', '#8A8A96', '#B8F07A')) {
						if (-not $W.BrushCache.ContainsKey($hx)) {
							try { $W.BrushCache[$hx] = $bc.ConvertFromString($hx) } catch {}
						}
					}
					$menuBg = $W.BrushCache['#1A1A1E']
					$menuFg = $W.BrushCache['#C8C8D0']
					$chipBg = $W.BrushCache['#3A3A42']
					$accent = $W.BrushCache['#BB9AF7']
					$muted = $W.BrushCache['#8A8A96']
					$selFg = $W.BrushCache['#B8F07A']
					$entries = @()
					try { $entries = @($W.RemoteModelEntries) } catch { $entries = @() }
					if ($entries.Count -eq 0 -and $Models -and @($Models).Count -gt 0) {
						# Fallback: plain id list (primary only)
						$entries = @($Models | ForEach-Object {
							[pscustomobject]@{ Key = [string]$_; Id = [string]$_; Base = ''; Host = ''; Label = [string]$_ }
						})
					}
					$sel = ([string]$Selected).Trim()
					$selKey = ''
					try { $selKey = [string]$W.ActiveModelKey } catch { $selKey = '' }
					if ($entries.Count -eq 1) {
						$sel = [string]$entries[0].Id
						$selKey = [string]$entries[0].Key
						$curKey = ''
						try { $curKey = [string]$W.ActiveModelKey } catch { $curKey = '' }
						$W.ActiveModel = $sel
						$W.ActiveModelBase = [string]$entries[0].Base
						$W.ActiveModelKey = $selKey
						# Only mark dirty when selection actually changes (avoids switch/save loops)
						if ($curKey -ne $selKey) { $W.ModelDirty = $true }
					} elseif ($entries.Count -gt 1) {
						$hit = $null
						if ($selKey) { $hit = @($entries | Where-Object { $_.Key -eq $selKey } | Select-Object -First 1) }
						if (-not $hit -and $sel) { $hit = @($entries | Where-Object { $_.Id -eq $sel } | Select-Object -First 1) }
						if ($hit) {
							$sel = [string]$hit.Id
							$selKey = [string]$hit.Key
						} else {
							$sel = ''
							$selKey = ''
						}
					}
					$display = if ($sel) { (& $W.ShortModelLabel $sel 36) } else { 'Select Model' }
					if ($lbl) {
						$lbl.Text = $display
						$lbl.Foreground = $(if ($sel) { $accent } else { $muted })
					}
					if ($entries.Count -eq 0) {
						$chip.Opacity = 0.55
						$chip.IsEnabled = $true
						if ($W.SetThemedToolTip) {
							& $W.SetThemedToolTip $chip 'No models yet - click to refresh or add an endpoint'
						} else {
							$chip.ToolTip = 'No models yet - click to refresh or add an endpoint'
						}
					} else {
						$chip.Opacity = 1.0
						$chip.IsEnabled = $true
						$tipBase = ''
						try {
							if ($selKey) {
								$he = @($entries | Where-Object { $_.Key -eq $selKey } | Select-Object -First 1)
								if ($he -and $he.Host) { $tipBase = "`nEndpoint: $($he.Host)" }
							}
						} catch {}
						$tipTxt = if ($sel) {
							"Model: $sel$tipBase`nClick to open/close model list or add endpoint"
						} else {
							'Click to open/close model list or add endpoint'
						}
						if ($W.SetThemedToolTip) { & $W.SetThemedToolTip $chip $tipTxt }
						else { $chip.ToolTip = $tipTxt }
					}
					$cm = New-Object System.Windows.Controls.ContextMenu
					try {
						$cm.Background = $menuBg
						$cm.Foreground = $menuFg
						$cm.BorderBrush = $chipBg
						$cm.BorderThickness = New-Object System.Windows.Thickness(1)
						$cm.Padding = New-Object System.Windows.Thickness(2)
						if ($null -eq $cm.Resources) { $cm.Resources = New-Object System.Windows.ResourceDictionary }
						try { $cm.Resources[[System.Windows.SystemColors]::MenuBrushKey] = $menuBg } catch {}
						try { $cm.Resources[[System.Windows.SystemColors]::MenuBarBrushKey] = $menuBg } catch {}
						try { $cm.Resources[[System.Windows.SystemColors]::ControlBrushKey] = $menuBg } catch {}
						try { $cm.Resources[[System.Windows.SystemColors]::MenuTextBrushKey] = $menuFg } catch {}
						try { $cm.Resources[[System.Windows.SystemColors]::HighlightBrushKey] = $chipBg } catch {}
						try { $cm.Resources[[System.Windows.SystemColors]::HighlightTextBrushKey] = $menuFg } catch {}
						try {
							$cmTplXaml = @'
<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" TargetType="ContextMenu">
  <Border Background="{TemplateBinding Background}"
          BorderBrush="{TemplateBinding BorderBrush}"
          BorderThickness="{TemplateBinding BorderThickness}"
          CornerRadius="4" Padding="{TemplateBinding Padding}"
          SnapsToDevicePixels="True">
    <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Cycle"/>
  </Border>
</ControlTemplate>
'@
							$cmTpl = [Windows.Markup.XamlReader]::Parse($cmTplXaml)
							if ($null -ne $cmTpl) { $cm.Template = $cmTpl }
						} catch {}
						try {
							$miStyle = New-Object System.Windows.Style ([System.Windows.Controls.MenuItem])
							$miStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BackgroundProperty, $menuBg)))
							$miStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::BorderThicknessProperty, (New-Object System.Windows.Thickness(0)))))
							$miStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::PaddingProperty, (New-Object System.Windows.Thickness(10, 5, 14, 5)))))
							$miTplXaml = @'
<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" TargetType="MenuItem">
  <Border x:Name="Bd" Background="{TemplateBinding Background}"
          BorderThickness="0" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True"
          TextElement.Foreground="{TemplateBinding Foreground}">
    <ContentPresenter ContentSource="Header" RecognizesAccessKey="True"
                      VerticalAlignment="Center" HorizontalAlignment="Left"
                      TextElement.Foreground="{TemplateBinding Foreground}"/>
  </Border>
  <ControlTemplate.Triggers>
    <Trigger Property="IsHighlighted" Value="True">
      <Setter TargetName="Bd" Property="Background" Value="#3A3A42"/>
    </Trigger>
  </ControlTemplate.Triggers>
</ControlTemplate>
'@
							$miTpl = [Windows.Markup.XamlReader]::Parse($miTplXaml)
							if ($null -ne $miTpl) {
								$miStyle.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.Control]::TemplateProperty, $miTpl)))
							}
							$cm.Resources[[System.Windows.Controls.MenuItem]] = $miStyle
						} catch {}
					} catch {}
					if ($entries.Count -eq 0) {
						$mi = New-Object System.Windows.Controls.MenuItem
						$mi.Header = 'No models . click chip to refresh'
						$mi.IsEnabled = $false
						$mi.Foreground = $muted
						[void]$cm.Items.Add($mi)
					} else {
						$menuCount = 0
						foreach ($ent in $entries) {
							$mid = [string]$ent.Id
							$ekey = [string]$ent.Key
							$elabel = if ($ent.Label) { [string]$ent.Label } else { $mid }
							# Active model stays on the chip only - never list it in the switch menu
							$isSel = ($selKey -and $ekey -eq $selKey) -or ((-not $selKey) -and $sel -and $mid -eq $sel)
							if ($isSel) { continue }
							$mi = New-Object System.Windows.Controls.MenuItem
							$mi.IsEnabled = $true
							$mi.Focusable = $false
							try { $mi.StaysOpenOnClick = $false } catch {}
							$hdr = New-Object System.Windows.Controls.TextBlock
							$hdr.Text = "  $elabel"
							$hdr.FontSize = 12
							$hdr.Foreground = $menuFg
							$mi.Header = $hdr
							$mi.Tag = [pscustomobject]@{ Id = $mid; Base = [string]$ent.Base; Key = $ekey }
							$mi.Background = $menuBg
							$mi.Foreground = $menuFg
							$null = $mi.Add_Click({
								param($s2, $e2)
								try {
									$tag = $null
									try { $tag = $s2.Tag } catch { $tag = $null }
									$id = ''; $b = ''; $k = ''
									if ($tag -is [string]) { $id = [string]$tag }
									else {
										try { $id = [string]$tag.Id } catch {}
										try { $b = [string]$tag.Base } catch {}
										try { $k = [string]$tag.Key } catch {}
									}
									if ([string]::IsNullOrWhiteSpace($id)) { return }
									$W.ActiveModel = $id
									$W.ActiveModelBase = $b
									$W.ActiveModelKey = $k
									$W.ModelDirty = $true
									if ($W.TitleModelPickerText) {
										$W.TitleModelPickerText.Text = (& $W.ShortModelLabel $id 36)
										$W.TitleModelPickerText.Foreground = $W.BrushCache['#BB9AF7']
									}
									if ($W.TitleModelPicker) {
										$tipTxt = "Model: $id`nClick to change or add endpoint"
										if ($W.SetThemedToolTip) { & $W.SetThemedToolTip $W.TitleModelPicker $tipTxt }
										else { $W.TitleModelPicker.ToolTip = $tipTxt }
									}
									try {
										if ($W.BuildModelMenu) { & $W.BuildModelMenu @($W.RemoteModels) $id }
									} catch {}
								} catch {}
							}.GetNewClosure())
							[void]$cm.Items.Add($mi)
							$menuCount++
						}
						if ($menuCount -eq 0 -and $entries.Count -gt 0) {
							$mi = New-Object System.Windows.Controls.MenuItem
							$mi.Header = '(active model - add another endpoint to switch)'
							$mi.IsEnabled = $false
							$mi.Foreground = $muted
							[void]$cm.Items.Add($mi)
						}
					}
					# Separator + add endpoint
					try {
						$sep = New-Object System.Windows.Controls.Separator
						try { $sep.Background = $chipBg } catch {}
						try { $sep.Margin = New-Object System.Windows.Thickness(4, 4, 4, 4) } catch {}
						[void]$cm.Items.Add($sep)
					} catch {}
					$addMi = New-Object System.Windows.Controls.MenuItem
					$addMi.IsEnabled = $true
					$addMi.Focusable = $false
					$addHdr = New-Object System.Windows.Controls.TextBlock
					$addHdr.Text = '+  Add endpoint...'
					$addHdr.FontSize = 12
					$addHdr.Foreground = $accent
					$addMi.Header = $addHdr
					$addMi.Background = $menuBg
					$addMi.Foreground = $accent
					$null = $addMi.Add_Click({
						param($s2, $e2)
						try {
							if ($W.ShowAddEndpointDialog) { & $W.ShowAddEndpointDialog }
						} catch {}
					}.GetNewClosure())
					[void]$cm.Items.Add($addMi)
					try {
						$cm.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
						$cm.PlacementTarget = $chip
						$cm.HorizontalOffset = 0
						$cm.VerticalOffset = 2
					} catch {}
					# Keep open state if rebuild happens while menu is visible
					$wasShowing = $false
					try { $wasShowing = [bool]$W.ModelMenuIsShowing } catch { $wasShowing = $false }
					try {
						$oldCm = $chip.ContextMenu
						if ($oldCm -and [bool]$oldCm.IsOpen) {
							$wasShowing = $true
							try { $oldCm.IsOpen = $false } catch {}
						}
					} catch {}
					$chip.ContextMenu = $cm
					$null = $cm.Add_Closed({
						try { $W.ModelMenuIsShowing = $false } catch {}
						# Same left-click that dismisses the menu is delivered to the chip next —
						# stamp close time so PreviewMouseLeftButtonDown does not reopen it.
						try { $W.ModelMenuClosedTick = [Environment]::TickCount } catch {}
					}.GetNewClosure())
					# One-time click toggle (open on first click, close on second)
					if (-not $W.ModelPickerClickHooked) {
						$W.ModelPickerClickHooked = $true
						try { $W.ModelMenuIsShowing = $false } catch {}
						try { $W.ModelMenuClosedTick = 0 } catch {}
						$null = $chip.Add_PreviewMouseLeftButtonDown({
							param($sender, $e)
							try {
								if (-not $sender) { return }
								$m = $null
								try { $m = $sender.ContextMenu } catch { $m = $null }
								if (-not $m) { return }
								$e.Handled = $true
								$now = [Environment]::TickCount

								# Click that just closed the menu (WPF closes first, then raises this on the chip)
								$closedTick = 0
								try { $closedTick = [int]$W.ModelMenuClosedTick } catch { $closedTick = 0 }
								if ($closedTick -ne 0) {
									$dt = ($now - $closedTick) -band 0x7fffffff
									if ($dt -lt 500) {
										try { $W.ModelMenuClosedTick = 0 } catch {}
										try { $W.ModelMenuIsShowing = $false } catch {}
										try { $m.IsOpen = $false } catch {}
										return
									}
								}

								$isOpen = $false
								try { if ([bool]$m.IsOpen) { $isOpen = $true } } catch {}
								try { if ([bool]$W.ModelMenuIsShowing) { $isOpen = $true } } catch {}
								if ($isOpen) {
									try { $W.ModelMenuIsShowing = $false } catch {}
									try { $W.ModelMenuClosedTick = $now } catch {}
									try { $m.IsOpen = $false } catch {}
									return
								}

								# Open (refresh list only when empty — rebuild while open breaks toggle)
								try {
									$needRefresh = $false
									$ents = $null
									try { $ents = @($W.RemoteModelEntries) } catch { $ents = @() }
									if (-not $ents -or $ents.Count -eq 0) { $needRefresh = $true }
									if ($needRefresh) { $W.RemoteModelsRefreshWanted = $true }
								} catch {}
								try {
									$m.PlacementTarget = $sender
									$m.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
									$m.HorizontalOffset = 0
									$m.VerticalOffset = 2
								} catch {}
								try { $W.ModelMenuClosedTick = 0 } catch {}
								try { $W.ModelMenuIsShowing = $true } catch {}
								$m.IsOpen = $true
							} catch {}
						}.GetNewClosure())
					}
					if ($wasShowing) {
						try {
							$W.ModelMenuIsShowing = $true
							$cm.IsOpen = $true
						} catch {}
					}
				} catch {}
			}.GetNewClosure()
			$W.ApplyModelPicker = {
				param([object[]]$Models = @(), [string]$Selected = '')
				try {
					if ($W.BuildModelMenu) { & $W.BuildModelMenu $Models $Selected }
				} catch {}
			}.GetNewClosure()
			$W.ShowAddEndpointDialog = {
				# Dedicated overlay on this chat window (Collapsed until opened; Cancel hides it).
				try {
					if (-not $W.AddEndpointOverlay) { return }
					# Leave URL blank — pre-filling the active base made Connect always look like a duplicate.
					try {
						if ($W.AddEpUrl) {
							$W.AddEpUrl.Text = ''
							$W.AddEpUrl.IsEnabled = $true
						}
					} catch {}
					try { if ($W.AddEpKey) { $W.AddEpKey.Password = '' } } catch {}
					try {
						if ($W.AddEpAuthNone) { $W.AddEpAuthNone.IsChecked = $true }
						if ($W.AddEpAuthKey) { $W.AddEpAuthKey.IsChecked = $false }
						if ($W.AddEpAuthNpm) { $W.AddEpAuthNpm.IsChecked = $false }
					} catch {}
					try {
						if ($W.AddEpError) { $W.AddEpError.Text = '' }
					} catch {}
					try {
						if ($W.AddEpSubtitle) {
							$curHint = ''
							try { $curHint = [string]$W.ActiveModelBase } catch {}
							if (-not [string]::IsNullOrWhiteSpace($curHint)) {
								$W.AddEpSubtitle.Text = ("Currently using {0}. Enter a different API base to add." -f $curHint)
							} else {
								$W.AddEpSubtitle.Text = 'Add another API base for the model picker. Example: http://127.0.0.1:8081/v1'
							}
						}
					} catch {}
					try { $W.AddEndpointBusy = $false } catch {}
					try {
						if ($W.AddEpConnect) {
							$W.AddEpConnect.IsEnabled = $true
							$W.AddEpConnect.Content = 'Connect'
							$W.AddEpConnect.IsDefault = $true
						}
					} catch {}
					try { $W.ModalUi = $true } catch {}
					$W.AddEndpointOverlay.Visibility = [System.Windows.Visibility]::Visible
					try {
						if ($W.SyncAddEpKey) { & $W.SyncAddEpKey }
					} catch {}
					try {
						if ($W.AddEpUrl) { [void]$W.AddEpUrl.Focus() }
					} catch {}
				} catch {}
			}.GetNewClosure()
			try {
				$initModels = @()
				try { $initModels = @($W.RemoteModels) } catch { $initModels = @() }
				$initSel = ''
				try { $initSel = [string]$W.ActiveModel } catch { $initSel = '' }
				if ($W.ApplyModelPicker) { & $W.ApplyModelPicker $initModels $initSel }
			} catch {}
			$W.TitleBtnMin = $window.FindName('TitleBtnMin')
			$W.TitleBtnMax = $window.FindName('TitleBtnMax')
			$W.TitleBtnClose = $window.FindName('TitleBtnClose')
			$W.TitleBtnMinPath = $window.FindName('TitleBtnMinPath')
			$W.TitleBtnMaxPath = $window.FindName('TitleBtnMaxPath')
			$W.TitleBtnClosePath = $window.FindName('TitleBtnClosePath')
			# Maximize to work area (not WindowState.Maximized)
			$W.IsWorkAreaMaximized = $false
			$W.RestoreBounds = $null
			$W.MaxGeom = 'M0.5,0.5 H9.5 V9.5 H0.5 Z'
			$W.RestoreGeom = 'M0,3 H7.5 V10.5 H0 Z M3,0 H10.5 V7.5'
			# Titlebar window buttons
			try {
				$getWorkAreaForWindow = {
					param($win)
					try {
						Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
						$helper = New-Object System.Windows.Interop.WindowInteropHelper($win)
						$hwnd = $helper.Handle
						$scr = $null
						if ($hwnd -ne [IntPtr]::Zero) {
							$scr = [System.Windows.Forms.Screen]::FromHandle($hwnd)
						} else {
							$cx = [int]($win.Left + ($win.Width / 2.0))
							$cy = [int]($win.Top + ($win.Height / 2.0))
							$scr = [System.Windows.Forms.Screen]::FromPoint((New-Object System.Drawing.Point($cx, $cy)))
						}
						$wa = $scr.WorkingArea
						$src = [System.Windows.PresentationSource]::FromVisual($win)
						if ($src -and $src.CompositionTarget) {
							$t = $src.CompositionTarget.TransformFromDevice
							$p1 = $t.Transform((New-Object System.Windows.Point($wa.Left, $wa.Top)))
							$p2 = $t.Transform((New-Object System.Windows.Point(($wa.Left + $wa.Width), ($wa.Top + $wa.Height))))
							return @{ Left = [double]$p1.X; Top = [double]$p1.Y; Width = [double]($p2.X - $p1.X); Height = [double]($p2.Y - $p1.Y) }
						}
						return @{ Left = [double]$wa.Left; Top = [double]$wa.Top; Width = [double]$wa.Width; Height = [double]$wa.Height }
					} catch {
						$r = [System.Windows.SystemParameters]::WorkArea
						return @{ Left = [double]$r.Left; Top = [double]$r.Top; Width = [double]$r.Width; Height = [double]$r.Height }
					}
				}.GetNewClosure()
				$W.GetWorkAreaForWindow = $getWorkAreaForWindow
				$setMaxIcon = {
					param([bool]$isMax)
					try {
						if ($W.TitleBtnMaxPath) {
							$g = if ($isMax) { $W.RestoreGeom } else { $W.MaxGeom }
							$W.TitleBtnMaxPath.Data = [System.Windows.Media.Geometry]::Parse([string]$g)
						}
						if ($W.TitleBtnMax) {
							$tip = if ($isMax) { 'Restore' } else { 'Maximize' }
							if ($W.SetThemedToolTip) { & $W.SetThemedToolTip $W.TitleBtnMax $tip 180 }
							else { $W.TitleBtnMax.ToolTip = $tip }
						}
					} catch {}
				}.GetNewClosure()
				$W.SetMaxIcon = $setMaxIcon
				$toggleWorkAreaMax = {
					try {
						if ($W.IsWorkAreaMaximized) {
							$rb = $W.RestoreBounds
							if ($rb) {
								$window.Left = [double]$rb.Left
								$window.Top = [double]$rb.Top
								$window.Width = [double]$rb.Width
								$window.Height = [double]$rb.Height
							}
							$W.IsWorkAreaMaximized = $false
							& $setMaxIcon $false
						} else {
							$W.RestoreBounds = @{
								Left = [double]$window.Left
								Top = [double]$window.Top
								Width = [double]$window.Width
								Height = [double]$window.Height
							}
							try { $window.WindowState = [System.Windows.WindowState]::Normal } catch {}
							$wa = & $getWorkAreaForWindow $window
							$window.Left = [double]$wa.Left
							$window.Top = [double]$wa.Top
							$window.Width = [Math]::Max(200.0, [double]$wa.Width)
							$window.Height = [Math]::Max(150.0, [double]$wa.Height)
							$W.IsWorkAreaMaximized = $true
							& $setMaxIcon $true
						}
						try {
							if ($W.ApplyWindowChromeCorners) { & $W.ApplyWindowChromeCorners $window $W }
						} catch {}
					} catch {}
				}.GetNewClosure()
				$W.ToggleWorkAreaMax = $toggleWorkAreaMax
				# Themed tooltips (title chrome)
				try {
					if ($W.SetThemedToolTip) {
						if ($W.TitlePath) { & $W.SetThemedToolTip $W.TitlePath 'Click to change working directory' 280 }
						if ($W.TitleBtnMin) { & $W.SetThemedToolTip $W.TitleBtnMin 'Minimize' 160 }
						if ($W.TitleBtnMax) {
							$mx = if ([bool]$W.IsWorkAreaMaximized) { 'Restore' } else { 'Maximize' }
							& $W.SetThemedToolTip $W.TitleBtnMax $mx 160
						}
						if ($W.TitleBtnClose) { & $W.SetThemedToolTip $W.TitleBtnClose 'Close' 140 }
					} elseif ($W.TitlePath) {
						$W.TitlePath.ToolTip = 'Click to change working directory'
					}
				} catch {}
				# Hover: exit red, min/max lighter grey (NoMouseOver - Background only)
				$bcTitle = New-Object System.Windows.Media.BrushConverter
				$hoverGrey = $bcTitle.ConvertFromString('#3A3A42')
				$hoverRed = $bcTitle.ConvertFromString('#E81123')
				$hoverClear = [System.Windows.Media.Brushes]::Transparent
				if ($W.TitleBtnMin) {
					$W.TitleBtnMin.add_MouseEnter({
						try { $W.TitleBtnMin.Background = $hoverGrey } catch {}
					}.GetNewClosure())
					$W.TitleBtnMin.add_MouseLeave({
						try { $W.TitleBtnMin.Background = $hoverClear } catch {}
					}.GetNewClosure())
					$W.TitleBtnMin.add_Click({
						try { $window.WindowState = [System.Windows.WindowState]::Minimized } catch {}
					}.GetNewClosure())
				}
				if ($W.TitleBtnMax) {
					$W.TitleBtnMax.add_MouseEnter({
						try { $W.TitleBtnMax.Background = $hoverGrey } catch {}
					}.GetNewClosure())
					$W.TitleBtnMax.add_MouseLeave({
						try { $W.TitleBtnMax.Background = $hoverClear } catch {}
					}.GetNewClosure())
					$W.TitleBtnMax.add_Click({
						try { & $toggleWorkAreaMax } catch {}
					}.GetNewClosure())
				}
				if ($W.TitleBtnClose) {
					$W.TitleBtnClose.add_MouseEnter({
						try { $W.TitleBtnClose.Background = $hoverRed } catch {}
					}.GetNewClosure())
					$W.TitleBtnClose.add_MouseLeave({
						try { $W.TitleBtnClose.Background = $hoverClear } catch {}
					}.GetNewClosure())
					$W.TitleBtnClose.add_Click({
						try { $window.Close() } catch {}
					}.GetNewClosure())
				}
				# Double-click titlebar maximizes to work area
				if ($W.CustomTitleBar) {
					$W.CustomTitleBar.add_MouseLeftButtonDown({
						param($s, $e)
						try {
							if ($e.ClickCount -eq 2) { & $toggleWorkAreaMax }
						} catch {}
					}.GetNewClosure())
				}
				# Title path: cwd editor popup
				try {
					if ($W.TitlePath) {
						if (-not $W.BrushCache) { $W.BrushCache = @{} }
						$bcCwd = New-Object System.Windows.Media.BrushConverter
						$cwdHexes = @('#121216', '#1E1E24', '#2A2A30', '#3A3A42', '#E0E0E8', '#C8C8D0', '#6A6A76', '#F05C5C', '#7DCFFF', '#4A4A56', '#5C5C6A', '#3A3A48', '#363640', '#5A5A66', '#222228')
						foreach ($hx in $cwdHexes) {
							if (-not $W.BrushCache.ContainsKey($hx)) {
								try { $W.BrushCache[$hx] = $bcCwd.ConvertFromString($hx) } catch {}
							}
						}
						$cwdPopup = New-Object System.Windows.Controls.Primitives.Popup
						$cwdPopup.StaysOpen = $true
						$cwdPopup.AllowsTransparency = $true
						$cwdPopup.PlacementTarget = $W.TitlePath
						# Custom: top-left of popup = bottom-left of title address (no left flyout)
						$cwdPopup.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Custom
						$cwdPopup.HorizontalOffset = 0
						$cwdPopup.VerticalOffset = 0
						$cwdPopup.CustomPopupPlacementCallback = [System.Windows.Controls.Primitives.CustomPopupPlacementCallback]{
							param([System.Windows.Size]$popupSize, [System.Windows.Size]$targetSize, [System.Windows.Point]$offset)
							# TitlePath bottom-left -> popup top-left, small vertical gap (no auto left-flyout)
							$pt = New-Object System.Windows.Point(0, ($targetSize.Height + 4))
							$place = New-Object System.Windows.Controls.Primitives.CustomPopupPlacement (
								$pt,
								[System.Windows.Controls.Primitives.PopupPrimaryAxis]::Horizontal
							)
							return [System.Windows.Controls.Primitives.CustomPopupPlacement[]]@($place)
						}
						$cwdShell = New-Object System.Windows.Controls.Border
						$cwdShell.Background = $W.BrushCache['#121216']
						$cwdShell.BorderBrush = $W.BrushCache['#2A2A30']
						$cwdShell.BorderThickness = New-Object System.Windows.Thickness(1)
						$cwdShell.CornerRadius = New-Object System.Windows.CornerRadius(8)
						$cwdShell.Padding = New-Object System.Windows.Thickness(12, 10, 12, 10)
						$cwdShell.MinWidth = 420
						$cwdShell.MaxWidth = 640
						$cwdShell.SnapsToDevicePixels = $true
						$cwdRoot = New-Object System.Windows.Controls.StackPanel
						$cwdRoot.Orientation = [System.Windows.Controls.Orientation]::Vertical
						$cwdLabel = New-Object System.Windows.Controls.TextBlock
						$cwdLabel.Text = 'Working directory'
						$cwdLabel.Foreground = $W.BrushCache['#C8C8D0']
						$cwdLabel.FontSize = 12
						$cwdLabel.FontWeight = [System.Windows.FontWeights]::SemiBold
						$cwdLabel.Margin = New-Object System.Windows.Thickness(0, 0, 0, 8)
						$cwdRow = New-Object System.Windows.Controls.DockPanel
						$cwdRow.LastChildFill = $true
						$cwdRow.Margin = New-Object System.Windows.Thickness(0, 0, 0, 6)
						# NoMouseOverButtonTemplate — kills system highlight brush (same as title chrome / SessionPicker)
						$cwdNoMoTpl = $null
						$cwdSecStyle = $null
						try { $cwdNoMoTpl = $window.TryFindResource('NoMouseOverButtonTemplate') } catch {}
						try { $cwdSecStyle = $window.TryFindResource('MbAuthSecondaryBtn') } catch {}
						if ($null -eq $cwdNoMoTpl) {
							try {
								$cwdNoMoTpl = [System.Windows.Markup.XamlReader]::Parse(
									'<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" TargetType="Button"><Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}" CornerRadius="4" SnapsToDevicePixels="True"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border></ControlTemplate>'
								)
							} catch {}
						}
						$styleCwdBtn = {
							param($btn)
							if ($null -ne $cwdSecStyle) {
								try { $btn.Style = $cwdSecStyle } catch {}
							}
							if ($null -ne $cwdNoMoTpl) {
								try { $btn.Template = $cwdNoMoTpl } catch {}
							}
							try {
								$btn.Background = $W.BrushCache['#2A2A30']
								$btn.Foreground = $W.BrushCache['#C8C8D0']
								$btn.BorderBrush = $W.BrushCache['#3A3A42']
								$btn.BorderThickness = New-Object System.Windows.Thickness(1)
							} catch {}
							# Themed hover without system chrome (NoMouseOver has no built-in hover)
							try {
								$btn.add_MouseEnter({
									param($s2, $e2)
									try { $s2.Background = $W.BrushCache['#363640']; $s2.BorderBrush = $W.BrushCache['#5A5A66'] } catch {}
								}.GetNewClosure())
								$btn.add_MouseLeave({
									param($s2, $e2)
									try { $s2.Background = $W.BrushCache['#2A2A30']; $s2.BorderBrush = $W.BrushCache['#3A3A42'] } catch {}
								}.GetNewClosure())
								$btn.add_PreviewMouseLeftButtonDown({
									param($s2, $e2)
									try { $s2.Background = $W.BrushCache['#222228'] } catch {}
								}.GetNewClosure())
								$btn.add_PreviewMouseLeftButtonUp({
									param($s2, $e2)
									try { $s2.Background = $W.BrushCache['#363640'] } catch {}
								}.GetNewClosure())
							} catch {}
						}.GetNewClosure()
						# Dock order: first Right = rightmost (Browse), then Go left of Browse — matches SessionPicker layout
						$cwdBrowse = New-Object System.Windows.Controls.Button
						$cwdBrowse.Content = 'Browse...'
						$cwdBrowse.MinWidth = 84
						$cwdBrowse.Height = 30
						$cwdBrowse.Margin = New-Object System.Windows.Thickness(6, 0, 0, 0)
						$cwdBrowse.Padding = New-Object System.Windows.Thickness(10, 0, 10, 0)
						$cwdBrowse.Cursor = [System.Windows.Input.Cursors]::Hand
						$cwdBrowse.Focusable = $true
						& $styleCwdBtn $cwdBrowse
						[System.Windows.Controls.DockPanel]::SetDock($cwdBrowse, [System.Windows.Controls.Dock]::Right)
						$cwdGo = New-Object System.Windows.Controls.Button
						$cwdGo.Content = 'Go'
						$cwdGo.MinWidth = 52
						$cwdGo.Height = 30
						$cwdGo.Margin = New-Object System.Windows.Thickness(6, 0, 0, 0)
						$cwdGo.Padding = New-Object System.Windows.Thickness(10, 0, 10, 0)
						$cwdGo.Cursor = [System.Windows.Input.Cursors]::Hand
						$cwdGo.Focusable = $true
						& $styleCwdBtn $cwdGo
						[System.Windows.Controls.DockPanel]::SetDock($cwdGo, [System.Windows.Controls.Dock]::Right)
						$cwdBox = New-Object System.Windows.Controls.TextBox
						$cwdBox.Height = 30
						$cwdBox.Padding = New-Object System.Windows.Thickness(8, 5, 8, 5)
						$cwdBox.Background = $W.BrushCache['#121216']
						$cwdBox.Foreground = $W.BrushCache['#E0E0E8']
						$cwdBox.CaretBrush = $W.BrushCache['#C8C8D0']
						$cwdBox.BorderBrush = $W.BrushCache['#3A3A42']
						$cwdBox.BorderThickness = New-Object System.Windows.Thickness(1)
						$cwdBox.VerticalContentAlignment = [System.Windows.VerticalAlignment]::Center
						try {
							$cwdBox.FontFamily = New-Object System.Windows.Media.FontFamily('Consolas, Cascadia Mono, Courier New')
						} catch {}
						$cwdBox.FontSize = 13
						# Children: Browse (right edge), Go (left of Browse), box fills remainder
						[void]$cwdRow.Children.Add($cwdBrowse)
						[void]$cwdRow.Children.Add($cwdGo)
						[void]$cwdRow.Children.Add($cwdBox)
						$cwdStatus = New-Object System.Windows.Controls.TextBlock
						$cwdStatus.Text = 'Enter a folder path, then Go — or Browse...'
						$cwdStatus.Foreground = $W.BrushCache['#6A6A76']
						$cwdStatus.FontSize = 11
						$cwdStatus.TextWrapping = [System.Windows.TextWrapping]::Wrap
						[void]$cwdRoot.Children.Add($cwdLabel)
						[void]$cwdRoot.Children.Add($cwdRow)
						[void]$cwdRoot.Children.Add($cwdStatus)
						$cwdShell.Child = $cwdRoot
						$cwdPopup.Child = $cwdShell
						$W.CwdPopup = $cwdPopup
						$W.CwdPopupBox = $cwdBox
						$W.CwdPopupGo = $cwdGo
						$W.CwdPopupBrowse = $cwdBrowse
						$W.CwdPopupStatus = $cwdStatus
						$openCwdPopup = {
							try {
								$cur = ''
								try { $cur = [string]$W.CurrentCwd } catch {}
								if ([string]::IsNullOrWhiteSpace($cur)) {
									try { $cur = [string]$W.TitlePath.Text } catch {}
								}
								if ([string]::IsNullOrWhiteSpace($cur) -or $cur.StartsWith('...')) {
									try { $cur = [string]$W.CurrentCwd } catch {}
								}
								if ([string]::IsNullOrWhiteSpace($cur)) {
									try { $cur = [Environment]::CurrentDirectory } catch { $cur = '' }
								}
								$W.CwdPopupBox.Text = $cur
								$W.CwdPopupStatus.Text = 'Enter a folder path, then Go — or Browse...'
								try { $W.CwdPopupStatus.Foreground = $W.BrushCache['#6A6A76'] } catch {}
								# Re-anchor under title path every open (title layout can shift)
								$W.CwdPopup.PlacementTarget = $W.TitlePath
								$W.CwdPopup.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Custom
								$W.CwdPopup.HorizontalOffset = 0
								$W.CwdPopup.VerticalOffset = 0
								$W.CwdPopup.IsOpen = $true
								try {
									[void]$W.CwdPopupBox.Focus()
									$W.CwdPopupBox.SelectAll()
								} catch {}
							} catch {}
						}.GetNewClosure()
						$closeCwdPopup = {
							try { if ($W.CwdPopup) { $W.CwdPopup.IsOpen = $false } } catch {}
						}.GetNewClosure()
						$applyCwdGo = {
							try {
								$dir = ([string]$W.CwdPopupBox.Text).Trim().Trim('"')
								if ([string]::IsNullOrWhiteSpace($dir)) {
									$W.CwdPopupStatus.Text = 'Enter a folder path first.'
									try { $W.CwdPopupStatus.Foreground = $W.BrushCache['#F05C5C'] } catch {}
									return
								}
								$exists = $false
								try { $exists = [System.IO.Directory]::Exists($dir) } catch { $exists = $false }
								if (-not $exists) {
									$W.CwdPopupStatus.Text = 'Folder not found - check the path and try again.'
									try { $W.CwdPopupStatus.Foreground = $W.BrushCache['#F05C5C'] } catch {}
									return
								}
								$full = $dir
								try { $full = [System.IO.Path]::GetFullPath($dir) } catch { $full = $dir }
								$W.CwdPopupBox.Text = $full
								$W.PendingCwd = $full
								$W.CurrentCwd = $full
								$W.CwdDirty = $true
								# Optimistic title path (short)
								$disp = $full
								if ($disp.Length -gt 56) { $disp = '...' + $disp.Substring($disp.Length - 53) }
								$W.PendingTitlePath = $disp
								try { $W.TitlePath.Text = $disp } catch {}
								try { if ($W.TitlePathShadow) { $W.TitlePathShadow.Text = $disp } } catch {}
								$W.CwdPopupStatus.Text = ('Working directory set: {0}' -f $full)
								try { $W.CwdPopupStatus.Foreground = $W.BrushCache['#7DCFFF'] } catch {}
								try { $W.CwdPopup.IsOpen = $false } catch {}
							} catch {}
						}.GetNewClosure()
						$browseCwdFolder = {
							try {
								Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
								$fb = New-Object System.Windows.Forms.FolderBrowserDialog
								$fb.Description = 'Choose working directory'
								$fb.ShowNewFolderButton = $true
								try {
									$cur = ([string]$W.CwdPopupBox.Text).Trim().Trim('"')
									if ($cur -and [System.IO.Directory]::Exists($cur)) {
										$fb.SelectedPath = $cur
									} elseif ($W.CurrentCwd -and [System.IO.Directory]::Exists([string]$W.CurrentCwd)) {
										$fb.SelectedPath = [string]$W.CurrentCwd
									}
								} catch {}
								$dr = $fb.ShowDialog()
								if ($dr -eq [System.Windows.Forms.DialogResult]::OK -and $fb.SelectedPath) {
									$W.CwdPopupBox.Text = [string]$fb.SelectedPath
									$W.CwdPopupStatus.Text = 'Folder selected — click Go to set working directory.'
									try { $W.CwdPopupStatus.Foreground = $W.BrushCache['#7DCFFF'] } catch {}
									try {
										[void]$W.CwdPopupBox.Focus()
										$W.CwdPopupBox.SelectAll()
									} catch {}
								}
							} catch {
								try {
									$W.CwdPopupStatus.Text = ('Browse failed: {0}' -f $_.Exception.Message)
									$W.CwdPopupStatus.Foreground = $W.BrushCache['#F05C5C']
								} catch {}
							}
						}.GetNewClosure()
						$W.OpenCwdPopup = $openCwdPopup
						$W.CloseCwdPopup = $closeCwdPopup
						$W.ApplyCwdGo = $applyCwdGo
						$W.BrowseCwdFolder = $browseCwdFolder
						$cwdGo.add_Click({
							param($s, $e)
							try { & $applyCwdGo } catch {}
						}.GetNewClosure())
						$cwdBrowse.add_Click({
							param($s, $e)
							try { & $browseCwdFolder } catch {}
						}.GetNewClosure())
						$cwdBox.add_KeyDown({
							param($s, $e)
							try {
								if ($e.Key -eq 'Return') {
									$e.Handled = $true
									& $applyCwdGo
								} elseif ($e.Key -eq 'Escape') {
									$e.Handled = $true
									& $closeCwdPopup
								}
							} catch {}
						}.GetNewClosure())
						$W.TitlePath.add_MouseLeftButtonUp({
							param($s, $e)
							try {
								if ($null -ne $e) { $e.Handled = $true }
								if ($W.CwdPopup -and [bool]$W.CwdPopup.IsOpen) {
									& $closeCwdPopup
								} else {
									& $openCwdPopup
								}
							} catch {}
						}.GetNewClosure())
						$W.TitlePath.add_MouseLeftButtonDown({
							param($s, $e)
							try { if ($null -ne $e) { $e.Handled = $true } } catch {}
						}.GetNewClosure())
						# Click outside closes cwd popup
						if ($W.Window -and -not $W.CwdPopupOutsideHooked) {
							$W.CwdPopupOutsideHooked = $true
							$W.Window.add_PreviewMouseDown({
								param($s, $e)
								try {
									if (-not $W.CwdPopup -or -not [bool]$W.CwdPopup.IsOpen) { return }
									$src = $null
									try { $src = $e.OriginalSource } catch {}
									$keep = $false
									try {
										$vis = $src
										while ($null -ne $vis) {
											if ($vis -eq $W.TitlePath -or $vis -eq $W.CwdPopup.Child -or $vis -eq $W.CwdPopupBrowse -or $vis -eq $W.CwdPopupGo -or $vis -eq $W.CwdPopupBox) {
												$keep = $true
												break
											}
											try { $vis = [System.Windows.Media.VisualTreeHelper]::GetParent($vis) } catch { break }
										}
									} catch {}
									if (-not $keep) { $W.CwdPopup.IsOpen = $false }
								} catch {}
							}.GetNewClosure())
						}
					}
				} catch {}
			} catch {}
			$W.HdrAutoCompact = $window.FindName('HdrAutoCompact')
			$W.HdrAutoCompactShadow = $window.FindName('HdrAutoCompactShadow')
			$W.HdrLeft = $W.HdrLine1
			$W.HdrRight = $window.FindName('LowerRight')
			$W.LowerRight = $window.FindName('LowerRight')
			$W.WordWrapToggle = $window.FindName('WordWrapToggle')
			$W.LogWordWrap = $true
			try {
				if ($W.WordWrapToggle) { $W.WordWrapToggle.IsChecked = $true }
			} catch {}
			try {
				if ($W.WordWrapToggle -and $W.SetThemedToolTip) {
					& $W.SetThemedToolTip $W.WordWrapToggle 'Wrap long log lines' 220
					$wwLbl = $window.FindName('WordWrapLabel')
					if ($wwLbl) { & $W.SetThemedToolTip $wwLbl 'Wrap long log lines' 220 }
				}
			} catch {}
			$W.CtxBarFill = $window.FindName('CtxBarFill')
			$W.CtxPctText = $window.FindName('CtxPctText')
			$W.CtxTokText = $window.FindName('CtxTokText')
			$W.CtxBarMaxW = 120
			$W.HintBar = $window.FindName('HintBar')
			$W.HintBarBorder = $window.FindName('HintBarBorder')
			$W.SpeechWaveBox = $window.FindName('SpeechWaveBox')
			$W.SpeechWaveCanvas = $window.FindName('SpeechWaveCanvas')
			$W.SpeechWaveLine = $window.FindName('SpeechWaveLine')
			$W.SpeechWaveStatus = $window.FindName('SpeechWaveStatus')
			$W.SpeechWaveLang = $window.FindName('SpeechWaveLang')
			$W.SpeechWaveTimer = $null
			$W.SpeechWavePhase = 0.0
			$W.SpeechWaveSeed = 1
			$W.StatusDot = $window.FindName('StatusDot')
			$W.StatusTimer = $window.FindName('StatusTimer')
			$W.StatusBand = $window.FindName('StatusBand')
			$W.StatusBusySince = 0
			try {
				$W.MonoFont = New-Object System.Windows.Media.FontFamily(
					'Consolas, Cascadia Mono, Courier New, Segoe UI')
				$W.EmojiFont = New-Object System.Windows.Media.FontFamily('Segoe UI Emoji')
			} catch {
				try { $W.EmojiFont = New-Object System.Windows.Media.FontFamily('Segoe UI Emoji') } catch {}
			}
			$W.AuthOverlay = $window.FindName('AuthOverlay')
			$W.AuthTitle = $window.FindName('AuthTitle')
			$W.AuthSubtitle = $window.FindName('AuthSubtitle')
			$W.AuthUser = $window.FindName('AuthUser')
			$W.AuthPass = $window.FindName('AuthPass')
			$W.AuthError = $window.FindName('AuthError')
			$W.AuthOk = $window.FindName('AuthOk')
			$W.AuthCancel = $window.FindName('AuthCancel')
			$W.AuthTitleClose = $window.FindName('AuthTitleClose')
			$W.AuthSaveCreds = $window.FindName('AuthSaveCreds')
			$W.AddEndpointOverlay = $window.FindName('AddEndpointOverlay')
			$W.AddEpSubtitle = $window.FindName('AddEpSubtitle')
			$W.AddEpUrl = $window.FindName('AddEpUrl')
			$W.AddEpKey = $window.FindName('AddEpKey')
			$W.AddEpKeyLbl = $window.FindName('AddEpKeyLbl')
			$W.AddEpAuthNone = $window.FindName('AddEpAuthNone')
			$W.AddEpAuthKey = $window.FindName('AddEpAuthKey')
			$W.AddEpAuthNpm = $window.FindName('AddEpAuthNpm')
			$W.AddEpError = $window.FindName('AddEpError')
			$W.AddEpConnect = $window.FindName('AddEpConnect')
			$W.AddEpCancel = $window.FindName('AddEpCancel')
			$W.AddEpTitleClose = $window.FindName('AddEpTitleClose')
			$W.ConfirmOverlay = $window.FindName('ConfirmOverlay')
			$W.ConfirmTitle = $window.FindName('ConfirmTitle')
			$W.ConfirmPrompt = $window.FindName('ConfirmPrompt')
			$W.ConfirmYes = $window.FindName('ConfirmYes')
			$W.ConfirmNo = $window.FindName('ConfirmNo')
			$W.ConfirmTitleClose = $window.FindName('ConfirmTitleClose')
			$W.ConfirmAccentBar = $window.FindName('ConfirmAccentBar')
			$W.SessionPickerOverlay = $window.FindName('SessionPickerOverlay')
			$W.SessionPickerTitle = $window.FindName('SessionPickerTitle')
			$W.SessionPickerTitleClose = $window.FindName('SessionPickerTitleClose')
			try {
				$barAgent = ''
				try { $barAgent = [string]$W.AgentName } catch {}
				if ([string]::IsNullOrWhiteSpace($barAgent)) {
					try { $barAgent = [string]$AgentName } catch { $barAgent = 'MiniBot' }
				}
				if ([string]::IsNullOrWhiteSpace($barAgent)) { $barAgent = 'MiniBot' }
				foreach ($barNm in @('AuthBarBrandName', 'AddEpBarBrandName', 'ConfirmBarBrandName', 'SessionBarBrandName')) {
					try {
						$barEl = $window.FindName($barNm)
						if ($null -ne $barEl) { $barEl.Text = $barAgent }
					} catch {}
				}
			} catch {}
			$W.SessionPickerPath = $window.FindName('SessionPickerPath')
			$W.SessionPickerGo = $window.FindName('SessionPickerGo')
			$W.SessionPickerUp = $window.FindName('SessionPickerUp')
			$W.SessionPickerBrowse = $window.FindName('SessionPickerBrowse')
			$W.SessionPickerStatus = $window.FindName('SessionPickerStatus')
			$W.SessionPickerList = $window.FindName('SessionPickerList')
			$W.SessionPickerName = $window.FindName('SessionPickerName')
			$W.SessionPickerOk = $window.FindName('SessionPickerOk')
			$W.SessionPickerCancel = $window.FindName('SessionPickerCancel')
			$W.SessionPickerRows = New-Object System.Collections.ArrayList
			# Titlebar close button hover
			try {
				$bcDlg = New-Object System.Windows.Media.BrushConverter
				$hoverRed = $bcDlg.ConvertFromString('#E81123')
				$hoverClear = [System.Windows.Media.Brushes]::Transparent
				$wireDlgCloseHover = {
					param($btn)
					if (-not $btn) { return }
					$btn.add_MouseEnter({
						try { $btn.Background = $hoverRed } catch {}
					}.GetNewClosure())
					$btn.add_MouseLeave({
						try { $btn.Background = $hoverClear } catch {}
					}.GetNewClosure())
				}.GetNewClosure()
				& $wireDlgCloseHover $W.AuthTitleClose
				& $wireDlgCloseHover $W.ConfirmTitleClose
				& $wireDlgCloseHover $W.SessionPickerTitleClose
			} catch {}

			
			# Session picker overlay
			try {
			$sessionPickerReload = {
				# Folder scan off UI thread
				try {
					$list = $W.SessionPickerList
					$pathBox = $W.SessionPickerPath
					$status = $W.SessionPickerStatus
					if (-not $list -or -not $pathBox) { return }
					$dir = ([string]$pathBox.Text).Trim().Trim('"')
					if ([string]::IsNullOrWhiteSpace($dir)) {
						if ($status) {
							$status.Text = 'Enter a folder path first.'
							try {
								$bc = New-Object System.Windows.Media.BrushConverter
								$status.Foreground = $bc.ConvertFromString('#F05C5C')
							} catch {}
						}
						return
					}
					# Require existing folder path
					$exists = $false
					try { $exists = [System.IO.Directory]::Exists($dir) } catch { $exists = $false }
					if (-not $exists) {
						if ($status) {
							$status.Text = 'Folder not found - check the path and try again.'
							try {
								$bc = New-Object System.Windows.Media.BrushConverter
								$status.Foreground = $bc.ConvertFromString('#F05C5C')
							} catch {}
						}
						return
					}
					$pathBox.Text = $dir
					$list.Items.Clear()
					$W.SessionPickerRows = New-Object System.Collections.ArrayList
					[void]$list.Items.Add('(scanning...)')
					if ($status) {
						$status.Text = 'Scanning...'
						try {
							$bc = New-Object System.Windows.Media.BrushConverter
							$status.Foreground = $bc.ConvertFromString('#6A6A76')
						} catch {}
					}
					try { Ensure-MBSessionScanType } catch {}
					$gen = 0
					try { $gen = [int]$W.SessionPickerScanGen + 1 } catch { $gen = 1 }
					$W.SessionPickerScanGen = $gen
					$dirCopy = $dir
					$genCopy = $gen
					$rs = $null
					$ps = $null
					try {
						$rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
						$rs.Open()
						$ps = [powershell]::Create()
						$ps.Runspace = $rs
						[void]$ps.AddScript({
							param([string]$Dir, [int]$Max, [int]$TimeoutMs)
							if (-not ('MiniBot.SessionScan' -as [type])) { return @() }
							$raw = [MiniBot.SessionScan]::ListSessions($Dir, $Max, $TimeoutMs)
							if (-not $raw) { return @() }
							$out = New-Object System.Collections.ArrayList
							foreach ($r in @($raw)) {
								if ($null -eq $r -or $r.Length -lt 6) { continue }
								[void]$out.Add(@{
									Name = [string]$r[0]; Path = [string]$r[1]; Modified = [string]$r[2]
									Size = [string]$r[3]; Type = [string]$r[4]; Line = [string]$r[5]
								})
							}
							return @($out)
						}).AddArgument($dirCopy).AddArgument(400).AddArgument(1500)
						$async = $ps.BeginInvoke()
						$timer = New-Object System.Windows.Threading.DispatcherTimer
						$timer.Interval = [TimeSpan]::FromMilliseconds(50)
						$timer.Tag = @{
							Async = $async; PS = $ps; RS = $rs; Gen = $genCopy; Dir = $dirCopy
						}
						$timer.add_Tick({
							param($s, $e)
							try {
								$tag = $s.Tag
								if (-not $tag -or -not $tag.Async) { try { $s.Stop() } catch {}; return }
								if (-not $tag.Async.IsCompleted) { return }
								try { $s.Stop() } catch {}
								$rows = @()
								try {
									$out = $tag.PS.EndInvoke($tag.Async)
									if ($out) { $rows = @($out) }
								} catch { $rows = @() }
								try { $tag.PS.Dispose() } catch {}
								try { $tag.RS.Close(); $tag.RS.Dispose() } catch {}
								$curGen = 0
								try { $curGen = [int]$W.SessionPickerScanGen } catch {}
								if ($curGen -ne [int]$tag.Gen) { return }
								$curDir = ''
								try { $curDir = ([string]$W.SessionPickerPath.Text).Trim().Trim('"') } catch {}
								if ($curDir -and $tag.Dir -and ($curDir -ne [string]$tag.Dir)) { return }
								if (-not $W.SessionPickerList) { return }
								$W.SessionPickerRows = New-Object System.Collections.ArrayList
								$W.SessionPickerList.Items.Clear()
								if ($rows.Count -eq 0) {
									[void]$W.SessionPickerList.Items.Add('(none)')
									if ($W.SessionPickerStatus) {
										$W.SessionPickerStatus.Text = 'No .json/.md here - type a name and Save/Open'
										try {
											$bc = New-Object System.Windows.Media.BrushConverter
											$W.SessionPickerStatus.Foreground = $bc.ConvertFromString('#6A6A76')
										} catch {}
									}
								} else {
									foreach ($row in $rows) {
										[void]$W.SessionPickerRows.Add($row)
										[void]$W.SessionPickerList.Items.Add([string]$row.Line)
									}
									if ($W.SessionPickerStatus) {
										$W.SessionPickerStatus.Text = ('{0} session(s)  |  newest first' -f $W.SessionPickerRows.Count)
										try {
											$bc = New-Object System.Windows.Media.BrushConverter
											$W.SessionPickerStatus.Foreground = $bc.ConvertFromString('#6A6A76')
										} catch {}
									}
								}
							} catch {
								try {
									if ($W.SessionPickerList) {
										$W.SessionPickerList.Items.Clear()
										[void]$W.SessionPickerList.Items.Add('(scan failed)')
									}
								} catch {}
							}
						}.GetNewClosure())
						$timer.Start()
					} catch {
						try { if ($ps) { $ps.Dispose() } } catch {}
						try { if ($rs) { $rs.Close(); $rs.Dispose() } } catch {}
						try {
							$list.Items.Clear()
							[void]$list.Items.Add('(scan failed)')
						} catch {}
					}
				} catch {}
			}.GetNewClosure()
			$W.SessionPickerReload = $sessionPickerReload

			# Dismiss picker UI before agent continues
			$sessionPickerDismissUi = {
				try {
					if ($W.SessionPickerOverlay) {
						$W.SessionPickerOverlay.Visibility = [System.Windows.Visibility]::Collapsed
						$W.SessionPickerOverlay.IsHitTestVisible = $false
					}
					if ($W.SessionPickerOk) { try { $W.SessionPickerOk.IsDefault = $false } catch {} }
					if ($W.SessionPickerCancel) { try { $W.SessionPickerCancel.IsCancel = $false } catch {} }
				} catch {}
			}.GetNewClosure()
			$sessionPickerAccept = {
				try {
					$mode = [string]$W.SessionPickerMode
					if ([string]::IsNullOrWhiteSpace($mode)) { $mode = 'Open' }
					$p = $null
					if ($mode -eq 'Save') {
						$nm = ''
						try { $nm = ([string]$W.SessionPickerName.Text).Trim().Trim('"') } catch {}
						$idx = -1
						try { $idx = [int]$W.SessionPickerList.SelectedIndex } catch {}
						if ([string]::IsNullOrWhiteSpace($nm) -and $idx -ge 0 -and $idx -lt $W.SessionPickerRows.Count) {
							$nm = [string]$W.SessionPickerRows[$idx].Name
						}
						if ([string]::IsNullOrWhiteSpace($nm)) { return }
						$low = $nm.ToLowerInvariant()
						if (-not ($low.EndsWith('.json') -or $low.EndsWith('.md') -or $low.EndsWith('.markdown'))) {
							$nm = $nm + '.json'
						}
						$dir = ''
						try { $dir = ([string]$W.SessionPickerPath.Text).Trim() } catch {}
						$p = [System.IO.Path]::Combine($dir, $nm)
						if ([System.IO.File]::Exists($p)) {
							# Avoid owned MessageBox on borderless host
							$r = [System.Windows.MessageBox]::Show(
								('Overwrite existing file?' + [Environment]::NewLine + [Environment]::NewLine + $p),
								'Save session',
								[System.Windows.MessageBoxButton]::YesNo,
								[System.Windows.MessageBoxImage]::Warning
							)
							if ($r -ne [System.Windows.MessageBoxResult]::Yes) { return }
						}
					} else {
						$idx = -1
						try { $idx = [int]$W.SessionPickerList.SelectedIndex } catch {}
						if ($idx -ge 0 -and $idx -lt $W.SessionPickerRows.Count) {
							$p = [string]$W.SessionPickerRows[$idx].Path
						}
						if ([string]::IsNullOrWhiteSpace($p) -or -not [System.IO.File]::Exists($p)) { return }
					}
					$W.SessionPickerResult = $p
					# Dismiss overlay before save continues
					& $sessionPickerDismissUi
					try { [void]$W.SessionPickerWait.Set() } catch {}
				} catch {}
			}.GetNewClosure()

			if ($W.SessionPickerGo) {
				$W.SessionPickerGo.add_Click({ & $sessionPickerReload }.GetNewClosure())
			}
			if ($W.SessionPickerUp) {
				$W.SessionPickerUp.add_Click({
					try {
						$cur = ([string]$W.SessionPickerPath.Text).Trim()
						$parent = [System.IO.Directory]::GetParent($cur)
						if ($parent) {
							$W.SessionPickerPath.Text = $parent.FullName
							& $sessionPickerReload
						}
					} catch {}
				}.GetNewClosure())
			}
			if ($W.SessionPickerBrowse) {
				$W.SessionPickerBrowse.add_Click({
					try {
						Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
						$fb = New-Object System.Windows.Forms.FolderBrowserDialog
						$fb.Description = 'Choose folder'
						$fb.ShowNewFolderButton = $true
						try {
							$cur = ([string]$W.SessionPickerPath.Text).Trim()
							if ($cur -and [System.IO.Directory]::Exists($cur)) { $fb.SelectedPath = $cur }
						} catch {}
						$dr = $fb.ShowDialog()
						if ($dr -eq [System.Windows.Forms.DialogResult]::OK -and $fb.SelectedPath) {
							$W.SessionPickerPath.Text = [string]$fb.SelectedPath
							& $sessionPickerReload
						}
					} catch {}
				}.GetNewClosure())
			}
			if ($W.SessionPickerPath) {
				$W.SessionPickerPath.add_KeyDown({
					param($s, $e)
					if ($e.Key -eq 'Return') {
						$e.Handled = $true
						& $sessionPickerReload
					}
				}.GetNewClosure())
			}
			if ($W.SessionPickerList) {
				$W.SessionPickerList.add_SelectionChanged({
					try {
						$idx = [int]$W.SessionPickerList.SelectedIndex
						if ($idx -ge 0 -and $idx -lt $W.SessionPickerRows.Count -and $W.SessionPickerName) {
							$W.SessionPickerName.Text = [string]$W.SessionPickerRows[$idx].Name
						}
					} catch {}
				}.GetNewClosure())
				$W.SessionPickerList.add_MouseDoubleClick({
					& $sessionPickerAccept
				}.GetNewClosure())
			}
			if ($W.SessionPickerOk) {
				$W.SessionPickerOk.add_Click({ & $sessionPickerAccept }.GetNewClosure())
			}
			if ($W.SessionPickerCancel) {
				$W.SessionPickerCancel.add_Click({
					$W.SessionPickerResult = $null
					try { & $sessionPickerDismissUi } catch {}
					try { [void]$W.SessionPickerWait.Set() } catch {}
				}.GetNewClosure())
			}
			if ($W.SessionPickerTitleClose) {
				$W.SessionPickerTitleClose.add_Click({
					$W.SessionPickerResult = $null
					try { & $sessionPickerDismissUi } catch {}
					try { [void]$W.SessionPickerWait.Set() } catch {}
				}.GetNewClosure())
			}
			} catch {
				try { $W['SessionPickerWireError'] = [string]$_.Exception.Message } catch {}
			}

			$W.Dispatcher = [System.Windows.Threading.Dispatcher]::CurrentDispatcher
			try {
				$bootTitle = "[{0}-Agent]" -f $(if ($W.AgentName) { [string]$W.AgentName } else { 'MiniBot' })
				$bootModel = ''
				try { $bootModel = [string]$W.ActiveModel } catch { $bootModel = '' }
				if ([string]::IsNullOrWhiteSpace($bootModel)) {
					try { $bootModel = @($W.RemoteModels)[0] } catch { $bootModel = '' }
				}
				$sep = ("  {0}  " -f [string][char]0x00B7)
				if (-not [string]::IsNullOrWhiteSpace($bootModel)) {
					$bootTitle = ("{0}{1}PoweredBy: {2}" -f $bootTitle, $sep, $bootModel.Trim())
				} else {
					$bootTitle = ("{0}{1}PoweredBy: Select Model" -f $bootTitle, $sep)
				}
				$window.Title = $bootTitle
			} catch {
				$window.Title = ("MiniBot v{0}" -f $W.Version)
			}
			# Window and taskbar robot icon
			try {
				$appId = 'MiniBot-Agent'
				try { if ($W.AgentName) { $appId = ("{0}-Agent" -f $W.AgentName) } } catch {}
				$W.AppId = $appId
				if (-not $W.RobotIconCache) { $W.RobotIconCache = @{} }
				$W.ToShellIcon = {
					param($Source)
					if (-not $Source) { return $null }
					try {
						$enc = New-Object System.Windows.Media.Imaging.PngBitmapEncoder
						[void]$enc.Frames.Add([System.Windows.Media.Imaging.BitmapFrame]::Create($Source))
						$ms = New-Object System.IO.MemoryStream
						try {
							$enc.Save($ms)
							$ms.Position = 0
							$frame = [System.Windows.Media.Imaging.BitmapFrame]::Create(
								$ms,
								[System.Windows.Media.Imaging.BitmapCreateOptions]::None,
								[System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
							)
							if ($frame.CanFreeze) { $frame.Freeze() }
							return $frame
						} finally { try { $ms.Dispose() } catch {} }
					} catch { return $Source }
				}.GetNewClosure()
				$W.SetNativeWindowIcon = {
					param($Window, $BitmapSource)
					if (-not $Window -or -not $BitmapSource) { return }
					try {
						if (-not ('MiniBot.UI.NativeIcon' -as [type])) {
							Add-Type -Namespace MiniBot.UI -Name NativeIcon -MemberDefinition @"
[System.Runtime.InteropServices.DllImport("user32.dll", CharSet=System.Runtime.InteropServices.CharSet.Auto)]
public static extern System.IntPtr SendMessage(System.IntPtr hWnd, int Msg, System.IntPtr wParam, System.IntPtr lParam);
[System.Runtime.InteropServices.DllImport("user32.dll", SetLastError=true)]
public static extern bool DestroyIcon(System.IntPtr hIcon);
[System.Runtime.InteropServices.DllImport("user32.dll", SetLastError=true)]
public static extern System.IntPtr CopyIcon(System.IntPtr hIcon);
public const int WM_SETICON = 0x0080;
public const int ICON_SMALL = 0;
public const int ICON_BIG = 1;
"@ -ErrorAction Stop
						}
						Add-Type -AssemblyName System.Drawing -ErrorAction SilentlyContinue
						$enc = New-Object System.Windows.Media.Imaging.PngBitmapEncoder
						[void]$enc.Frames.Add([System.Windows.Media.Imaging.BitmapFrame]::Create($BitmapSource))
						$ms = New-Object System.IO.MemoryStream
						try {
							$enc.Save($ms)
							$ms.Position = 0
							$gdi = [System.Drawing.Bitmap]::FromStream($ms)
							try {
								$hIcon = $gdi.GetHicon()
								try {
									$helper = New-Object System.Windows.Interop.WindowInteropHelper($Window)
									$hwnd = $helper.EnsureHandle()
									if ($hwnd -ne [IntPtr]::Zero) {
										$hSmall = [MiniBot.UI.NativeIcon]::CopyIcon($hIcon)
										$hBig = [MiniBot.UI.NativeIcon]::CopyIcon($hIcon)
										$prevSmall = [MiniBot.UI.NativeIcon]::SendMessage($hwnd, [MiniBot.UI.NativeIcon]::WM_SETICON, [IntPtr][MiniBot.UI.NativeIcon]::ICON_SMALL, $hSmall)
										$prevBig = [MiniBot.UI.NativeIcon]::SendMessage($hwnd, [MiniBot.UI.NativeIcon]::WM_SETICON, [IntPtr][MiniBot.UI.NativeIcon]::ICON_BIG, $hBig)
										if ($prevSmall -ne [IntPtr]::Zero) { try { [void][MiniBot.UI.NativeIcon]::DestroyIcon($prevSmall) } catch {} }
										if ($prevBig -ne [IntPtr]::Zero) { try { [void][MiniBot.UI.NativeIcon]::DestroyIcon($prevBig) } catch {} }
									}
								} finally { try { [void][MiniBot.UI.NativeIcon]::DestroyIcon($hIcon) } catch {} }
							} finally { try { $gdi.Dispose() } catch {} }
						} finally { try { $ms.Dispose() } catch {} }
					} catch {}
				}.GetNewClosure()
				$W.RenderRobotIcon = {
					param([string]$Face = 'happy', [int]$Size = 64)
					try {
						if ($Size -lt 16) { $Size = 16 }
						$cat = $W.RobotCatalog
						$faceKey = if ($cat -and (@($cat.Keys) -contains $Face)) { $Face } else { 'happy' }
						if ($cat -and (@($cat.Keys) -notcontains $faceKey)) { $faceKey = 'default' }
						$data = if ($cat) { [string]$cat[$faceKey] } else { '' }
						if ([string]::IsNullOrWhiteSpace($data)) { return $null }
						$cols = if ($faceKey -eq 'dead' -or $faceKey -eq 'error') {
							@('#D0C4C6', '#B08084', '#9A585C')
						} else {
							@('#C8C8D0', '#6A6A74', '#3A3A42')
						}
						$geom = [System.Windows.Media.Geometry]::Parse($data)
						$brush = New-Object System.Windows.Media.LinearGradientBrush
						$brush.StartPoint = New-Object System.Windows.Point(0.15, 0.0)
						$brush.EndPoint = New-Object System.Windows.Point(0.9, 1.0)
						for ($ci = 0; $ci -lt 3; $ci++) {
							$off = @(0.0, 0.48, 1.0)[$ci]
							$col = [System.Windows.Media.ColorConverter]::ConvertFromString([string]$cols[$ci])
							[void]$brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($col, $off)))
						}
						$brush.Freeze()
						$bgBrush = New-Object System.Windows.Media.SolidColorBrush(([System.Windows.Media.ColorConverter]::ConvertFromString('#252530')))
						$bgBrush.Freeze()
						$visual = New-Object System.Windows.Media.DrawingVisual
						$dc = $visual.RenderOpen()
						try {
							$cx = [double]$Size / 2.0
							$dc.DrawEllipse($bgBrush, $null, (New-Object System.Windows.Point($cx, $cx)), ($cx - 0.5), ($cx - 0.5))
							$pad = [math]::Max(2.0, [double]$Size * 0.14)
							$inner = [double]$Size - (2.0 * $pad)
							$scale = $inner / 24.0
							$dc.PushTransform((New-Object System.Windows.Media.TranslateTransform($pad, $pad)))
							$dc.PushTransform((New-Object System.Windows.Media.ScaleTransform($scale, $scale)))
							$dc.DrawGeometry($brush, $null, $geom)
							$dc.Pop(); $dc.Pop()
						} finally { $dc.Close() }
						$rtb = New-Object System.Windows.Media.Imaging.RenderTargetBitmap(
							[int]$Size, [int]$Size, 96, 96,
							[System.Windows.Media.PixelFormats]::Pbgra32
						)
						$rtb.Render($visual)
						if ($W.ToShellIcon) { return (& $W.ToShellIcon $rtb) }
						if ($rtb.CanFreeze) { $rtb.Freeze() }
						return $rtb
					} catch { return $null }
				}.GetNewClosure()
				$W.ApplyWindowRobotIcon = {
					param([string]$Face = 'happy')
					try {
						if (-not $W.Window) { return }
						$faceKey = if ([string]::IsNullOrWhiteSpace($Face)) { 'happy' } else { [string]$Face }
						if (-not $W.RobotIconCache) { $W.RobotIconCache = @{} }
						if (-not $W.RobotIconCache.ContainsKey($faceKey)) {
							$bmpNew = $null
							if ($W.RenderRobotIcon) { $bmpNew = & $W.RenderRobotIcon $faceKey 64 }
							if ($bmpNew) { $W.RobotIconCache[$faceKey] = $bmpNew }
						}
						$bmp = $null
						try { $bmp = $W.RobotIconCache[$faceKey] } catch {}
						if (-not $bmp) { return }
						$W.Window.Icon = $bmp
						if (-not $W.Window.TaskbarItemInfo) {
							$W.Window.TaskbarItemInfo = New-Object System.Windows.Shell.TaskbarItemInfo
						}
						$W.Window.TaskbarItemInfo.Overlay = $bmp
						$W.Window.TaskbarItemInfo.Description = $(if ($W.AppId) { [string]$W.AppId } else { 'MiniBot' })
						if ($W.SetNativeWindowIcon) { & $W.SetNativeWindowIcon $W.Window $bmp }
					} catch {}
				}.GetNewClosure()
				try { & $W.ApplyWindowRobotIcon 'happy' } catch {}
				try {
					$window.add_SourceInitialized({
						try { if ($W.ApplyWindowRobotIcon) { & $W.ApplyWindowRobotIcon $(if ($W.RobotMood) { [string]$W.RobotMood } else { 'happy' }) } } catch {}
					}.GetNewClosure())
				} catch {}
			} catch {}

			# Collapse unused sticky header nodes
			try {
				foreach ($el in @($W.HdrPoweredBy, $W.HdrPoweredByShadow, $W.HdrPoweredByHost, $W.HdrLine1, $W.HdrLine1Shadow, $W.HdrAutoCompact, $W.HdrAutoCompactShadow)) {
					if ($el) {
						try { $el.Visibility = [System.Windows.Visibility]::Collapsed } catch {}
					}
				}
			} catch {}

			$syncLogPageWidth = {
				param($box, $bag)
				try {
					if (-not $box -or -not $box.Document) { return }
					$viewW = [double]$box.ActualWidth
					if ($viewW -lt 40 -or [double]::IsNaN($viewW)) { return }

					$padL = 0.0; $padR = 0.0
					try {
						$padL = [double]$box.Padding.Left
						$padR = [double]$box.Padding.Right
					} catch {
						$padL = 12.0; $padR = 12.0
					}
					$vBar = 0.0
					try {
						if ($box.ComputedVerticalScrollBarVisibility -eq [System.Windows.Visibility]::Visible) {
							$vBar = 14.0
						} else {
							$vBar = 2.0
						}
					} catch { $vBar = 14.0 }

					$columnW = $viewW - $padL - $padR - $vBar - 2.0
					if ($columnW -lt 40) { $columnW = 40 }

					$wrap = $false
					try { $wrap = [bool]$bag.LogWordWrap } catch { $wrap = $false }
					if ($wrap) {
						$box.Document.PageWidth = $columnW
						$box.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Disabled
						return
					}

					$charW = 7.2
					$maxChars = 0
					try { $maxChars = [int]$bag.LogMaxLineChars } catch { $maxChars = 0 }
					$contentW = if ($maxChars -gt 0) { ($maxChars * $charW) + 8.0 } else { 0.0 }

					$needsH = ($contentW -gt ($columnW + 1.0))
					if ($needsH) {
						$pageW = [math]::Min(60000.0, [math]::Max($columnW, $contentW))
						$box.Document.PageWidth = $pageW
						$box.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Auto
					} else {
						$box.Document.PageWidth = $columnW
						$box.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Disabled
					}
				} catch {}
			}.GetNewClosure()
			$W.SyncLogPageWidth = $syncLogPageWidth
			$syncMdStretch = {
				param($box, $bag)
				try {
					if (-not $box -or -not $bag) { return }
					$viewW = [double]$box.ActualWidth
					if ($viewW -lt 40 -or [double]::IsNaN($viewW)) { return }
					$padL = 12.0; $padR = 12.0
					try {
						$padL = [double]$box.Padding.Left
						$padR = [double]$box.Padding.Right
					} catch {}
					$vBar = 16.0
					try {
						if ($box.ComputedVerticalScrollBarVisibility -eq [System.Windows.Visibility]::Visible) {
							$vBar = 16.0
						}
					} catch {}
					$w = $viewW - $padL - $padR - $vBar - 2.0
					if ($w -lt 40) { $w = 40 }
					$list = $null
					try {
						if ($bag -is [hashtable]) {
							if (-not $bag.ContainsKey('MdStretchElements') -or $null -eq $bag['MdStretchElements']) {
								$bag['MdStretchElements'] = New-Object System.Collections.ArrayList
							}
							$list = $bag['MdStretchElements']
						} else {
							try { $list = $bag.MdStretchElements } catch { $list = $null }
							if ($null -eq $list) {
								$list = New-Object System.Collections.ArrayList
								try { $bag | Add-Member -NotePropertyName MdStretchElements -NotePropertyValue $list -Force } catch {
									try { $bag.MdStretchElements = $list } catch {}
								}
							}
						}
					} catch { $list = $null }
					if ($null -eq $list) { return }
					$alive = New-Object System.Collections.ArrayList
					foreach ($el in @($list)) {
						if ($null -eq $el) { continue }
						try {
							if ($null -eq $el.Parent) { continue }
							$el.Width = $w
							try { $el.MaxWidth = $w } catch {}
							try {
								$meta = $el.Tag
								if ($meta -is [hashtable] -and $meta['Kind'] -eq 'md-code' -and $null -ne $meta['Rtb']) {
									$rtb = $meta['Rtb']
									if ($null -ne $rtb.Document) {
										$rtb.Document.PageWidth = [Math]::Max(80, $w - 8)
									}
								}
							} catch {}
							[void]$alive.Add($el)
						} catch {}
					}
					if ($bag -is [hashtable]) { $bag['MdStretchElements'] = $alive }
					else {
						try { $bag.MdStretchElements = $alive } catch {}
					}
				} catch {}
			}.GetNewClosure()
			$W.SyncMdStretch = $syncMdStretch


			if ($W.Log) {
				try { $W.Log.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Disabled } catch {}
				$W.Log.add_SizeChanged({
					param($s, $e)
					try { & $syncLogPageWidth $W.Log $W } catch {}
					try { & $syncMdStretch $W.Log $W } catch {}
				}.GetNewClosure())
				$W.Log.add_Loaded({
					param($s, $e)
					try { & $syncLogPageWidth $W.Log $W } catch {}
					try { & $syncMdStretch $W.Log $W } catch {}
				}.GetNewClosure())
				try { & $syncLogPageWidth $W.Log $W } catch {}
			}
			if ($W.WordWrapToggle) {
				$onWrapChanged = {
					param($s, $e)
					try {
						$W.LogWordWrap = [bool]$W.WordWrapToggle.IsChecked
						if ($W.SyncLogPageWidth -and $W.Log) { & $W.SyncLogPageWidth $W.Log $W }
						try {
							$tb = $window.FindName('WordWrapLabel')
							if (-not $tb) { $tb = $W.WordWrapToggle.Content }
							if ($tb -is [System.Windows.Controls.TextBlock]) {
								$hex = if ($W.LogWordWrap) { '#C8C8D0' } else { '#6A6A76' }
								$bc = New-Object System.Windows.Media.BrushConverter
								$tb.Foreground = $bc.ConvertFromString($hex)
							}
						} catch {}
					} catch {}
				}.GetNewClosure()
				$W.WordWrapToggle.add_Checked($onWrapChanged)
				$W.WordWrapToggle.add_Unchecked($onWrapChanged)
				try { & $onWrapChanged $null $null } catch {}
			}

			# Dark chrome + corner policy (rounded border; kill Win11 DWM rounding)
			$applyWindowChromeCorners = {
				param($win, $bag)
				try {
					# Use work-area maximize flag (not WindowState.Maximized)
					$maximized = $false
					try { $maximized = [bool]$bag.IsWorkAreaMaximized } catch { $maximized = $false }
					$r = if ($maximized) { 0.0 } else { 8.0 }
					$main = $null
					try { $main = $bag.MainChromeBorder } catch { $main = $null }
					if (-not $main) { try { $main = $win.FindName('MainChromeBorder') } catch {} }
					$title = $null
					try { $title = $bag.CustomTitleBar } catch { $title = $null }
					if (-not $title) { try { $title = $win.FindName('CustomTitleBar') } catch {} }
					if ($main) {
						$main.CornerRadius = New-Object System.Windows.CornerRadius($r)
						# Maximized: flush to work area (no transparent gap around rounded mask)
						if ($maximized) {
							$main.Margin = New-Object System.Windows.Thickness(0)
							$main.BorderThickness = New-Object System.Windows.Thickness(0)
						} else {
							$main.Margin = New-Object System.Windows.Thickness(0)
							$main.BorderThickness = New-Object System.Windows.Thickness(1)
						}
					}
					if ($title) {
						if ($maximized) {
							$title.CornerRadius = New-Object System.Windows.CornerRadius(0)
						} else {
							$title.CornerRadius = New-Object System.Windows.CornerRadius($r, $r, 0, 0)
						}
					}
					# Bottom chrome strip (hint bar) matches top radius when restored
					$hintBar = $null
					try { $hintBar = $bag.HintBarBorder } catch { $hintBar = $null }
					if (-not $hintBar) { try { $hintBar = $win.FindName('HintBarBorder') } catch {} }
					if ($hintBar) {
						if ($maximized) {
							$hintBar.CornerRadius = New-Object System.Windows.CornerRadius(0)
						} else {
							$hintBar.CornerRadius = New-Object System.Windows.CornerRadius(0, 0, $r, $r)
						}
					}
					# Keep WindowChrome radius in sync
					try {
						$chrome = [System.Windows.Shell.WindowChrome]::GetWindowChrome($win)
						if ($chrome) {
							if ($maximized) {
								$chrome.CornerRadius = New-Object System.Windows.CornerRadius(0)
								$chrome.CaptionHeight = 36
							} else {
								$chrome.CornerRadius = New-Object System.Windows.CornerRadius($r)
								$chrome.CaptionHeight = 36
							}
						}
					} catch {}
				} catch {}
			}.GetNewClosure()
			$applyDarkTitle = {
				param($win)
				try {
					if (-not ("MB.Native.Dwm" -as [type])) {
						Add-Type -Namespace MB.Native -Name Dwm -MemberDefinition @"
[System.Runtime.InteropServices.DllImport("dwmapi.dll")]
public static extern int DwmSetWindowAttribute(System.IntPtr hwnd, int attr, ref int attrValue, int attrSize);
"@ -ErrorAction Stop
					}
					$helper = New-Object System.Windows.Interop.WindowInteropHelper($win)
					$hwnd = $helper.Handle
					if ($hwnd -eq [IntPtr]::Zero) { return }
					$useDark = 1
					# DWMWA_USE_IMMERSIVE_DARK_MODE: 20 (20H1+), 19 (older)
					[void][MB.Native.Dwm]::DwmSetWindowAttribute($hwnd, 20, [ref]$useDark, 4)
					[void][MB.Native.Dwm]::DwmSetWindowAttribute($hwnd, 19, [ref]$useDark, 4)
					# DWMWA_WINDOW_CORNER_PREFERENCE (33): 1=DONOTROUND (we paint MainChromeBorder radius).
					# Keep OS from double-rounding on top of our 8px chrome.
					try {
						$noRound = 1
						[void][MB.Native.Dwm]::DwmSetWindowAttribute($hwnd, 33, [ref]$noRound, 4)
					} catch {}
					# DWMWA_CAPTION_COLOR (35); COLORREF 0x00BBGGRR = #2A2A30
					try {
						$caption = 0x00302A2A
						[void][MB.Native.Dwm]::DwmSetWindowAttribute($hwnd, 35, [ref]$caption, 4)
					} catch {}
					# DWMWA_BORDER_COLOR (34) match chrome
					try {
						$border = 0x00302A2A
						[void][MB.Native.Dwm]::DwmSetWindowAttribute($hwnd, 34, [ref]$border, 4)
					} catch {}
				} catch {}
			}.GetNewClosure()
			try {
				$W.MainChromeBorder = $window.FindName('MainChromeBorder')
				$W.ApplyWindowChromeCorners = $applyWindowChromeCorners
			} catch {}
			# Soft border pulse on MainChromeBorder (BorderBrush only).
			$W.StartChromeGlow = {
				try {
					if ($W.ChromeGlowStory) { return }
					$border = $W.MainChromeBorder
					if (-not $border) {
						try { $border = $window.FindName('MainChromeBorder') } catch {}
						$W.MainChromeBorder = $border
					}
					if (-not $border) { return }
					# Unfrozen SolidColorBrush so Color can animate (frozen brushes cannot)
					$brush = New-Object System.Windows.Media.SolidColorBrush
					$cBase = [System.Windows.Media.ColorConverter]::ConvertFromString('#2A2A30')
					$cPeak = [System.Windows.Media.ColorConverter]::ConvertFromString('#4A8AB8')
					$brush.Color = $cBase
					$border.BorderBrush = $brush
					try { $border.BorderThickness = New-Object System.Windows.Thickness 1 } catch {}
					$sb = New-Object System.Windows.Media.Animation.Storyboard
					$sb.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
					$anim = New-Object System.Windows.Media.Animation.ColorAnimationUsingKeyFrames
					$anim.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(6.0))
					$anim.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
					$mkKf = {
						param([System.Windows.Media.Color]$C, [double]$Sec)
						$kf = New-Object System.Windows.Media.Animation.LinearColorKeyFrame
						$kf.Value = $C
						$kf.KeyTime = [System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromSeconds($Sec))
						return $kf
					}
					[void]$anim.KeyFrames.Add((& $mkKf $cBase 0.0))
					[void]$anim.KeyFrames.Add((& $mkKf $cPeak 3.0))
					[void]$anim.KeyFrames.Add((& $mkKf $cBase 6.0))
					[System.Windows.Media.Animation.Storyboard]::SetTarget($anim, $brush)
					[System.Windows.Media.Animation.Storyboard]::SetTargetProperty($anim, (New-Object System.Windows.PropertyPath('Color')))
					[void]$sb.Children.Add($anim)
					$W.ChromeGlowBrush = $brush
					$W.ChromeGlowStory = $sb
					$sb.Begin()
				} catch {}
			}.GetNewClosure()
			$W.SyncChromeGlow = {
				# No geometry - pulse is on BorderBrush; re-arm only if storyboard was lost
				try {
					if (-not $W.ChromeGlowStory -and $W.StartChromeGlow) { & $W.StartChromeGlow }
				} catch {}
			}.GetNewClosure()
			$window.add_SourceInitialized({
				param($s, $e)
				try { & $applyDarkTitle $s } catch {}
				try { & $applyWindowChromeCorners $s $W } catch {}
			}.GetNewClosure())
			$window.add_Loaded({
				param($s, $e)
				try { & $applyDarkTitle $s } catch {}
				try { & $applyWindowChromeCorners $s $W } catch {}
				try { if ($W.StartChromeGlow) { & $W.StartChromeGlow } } catch {}
			}.GetNewClosure())
			$window.add_StateChanged({
				param($s, $e)
				try { & $applyWindowChromeCorners $s $W } catch {}
				try {
					if ($W.SetMaxIcon) { & $W.SetMaxIcon ([bool]$W.IsWorkAreaMaximized) }
				} catch {}
			}.GetNewClosure())
			$window.add_SizeChanged({
				param($s, $e)
				try {
					$now = [Environment]::TickCount
					$last = 0
					try { $last = [int]$W.LastPathBudgetTick } catch {}
					if ($last -ne 0 -and ((($now - $last) -band 0x7fffffff) -lt 120)) {
						try { if ($W.SyncMdStretch -and $W.Log) { & $W.SyncMdStretch $W.Log $W } } catch {}
						return
					}
					$W.LastPathBudgetTick = $now
					$W.NeedPathBudgetRefresh = $true
					try { if ($W.SyncMdStretch -and $W.Log) { & $W.SyncMdStretch $W.Log $W } } catch {}
				} catch {}
			}.GetNewClosure())

			$submitAuth = {
				try {
					$u = ''
					$p = ''
					try { $u = [string]$W.AuthUser.Text } catch {}
					try { $p = [string]$W.AuthPass.Password } catch {}
					if ([string]::IsNullOrWhiteSpace($u) -or [string]::IsNullOrWhiteSpace($p)) {
						if ($W.AuthError) { $W.AuthError.Text = 'Username and password are required.' }
						return
					}
					if ($W.AuthError) { $W.AuthError.Text = '' }
					$wantSave = $false
					try { if ($W.AuthSaveCreds -and $W.AuthSaveCreds.IsChecked) { $wantSave = $true } } catch {}
					$W.CredResult = @{
						User           = $u.Trim()
						Pass           = $p
						Cancelled      = $false
						Store          = $wantSave
						StoreSpecified = $true
						ClearStored    = $false
					}
					if ($W.AuthOverlay) { $W.AuthOverlay.Visibility = [System.Windows.Visibility]::Collapsed }
					if ($W.AuthOk) { $W.AuthOk.IsDefault = $false }
					try { $W.AuthPass.Password = '' } catch {}
					[void]$W.CredWait.Set()
				} catch {
					try {
						[System.Windows.MessageBox]::Show(
							$_.Exception.Message,
							'Login error',
							[System.Windows.MessageBoxButton]::OK,
							[System.Windows.MessageBoxImage]::Error
						) | Out-Null
					} catch {}
				}
			}.GetNewClosure()

			$W.AuthOk.add_Click({
				param($s,$e)
				try { & $submitAuth } catch {
					try {
						[System.Windows.MessageBox]::Show($_.Exception.Message, 'Login error') | Out-Null
					} catch {}
				}
			}.GetNewClosure())
			$doAuthCancel = {
				try {
					$W.SoftClose = $false
					$W.CloseKind = 'user_x'
					$W.ForceProcessExit = $true
					$W.ExitRequested = $true
					$W.CredResult = @{
						User = $null; Pass = $null; Cancelled = $true; SoftExit = $false; HardClose = $true
						Store = $false; StoreSpecified = $true; ClearStored = $false
					}
					if ($W.AuthOverlay) { $W.AuthOverlay.Visibility = [System.Windows.Visibility]::Collapsed }
					if ($W.AuthOk) { $W.AuthOk.IsDefault = $false }
					try { $W.AuthPass.Password = '' } catch {}
					[void]$W.CredWait.Set()
				} catch {}
			}.GetNewClosure()
			$W.AuthCancel.add_Click({
				param($s,$e)
				try { & $doAuthCancel } catch {}
			}.GetNewClosure())
			if ($W.AuthTitleClose) {
				$W.AuthTitleClose.add_Click({
					param($s,$e)
					try { & $doAuthCancel } catch {}
				}.GetNewClosure())
			}
			$W.AuthPass.add_KeyDown({
				param($s,$e)
				try {
					if ($e.Key -eq 'Return') { $e.Handled = $true; & $submitAuth }
				} catch {}
			}.GetNewClosure())
			$W.AuthUser.add_KeyDown({
				param($s,$e)
				try {
					if ($e.Key -eq 'Return') {
						$e.Handled = $true
						try { [void]$W.AuthPass.Focus() } catch {}
					}
				} catch {}
			}.GetNewClosure())

			# --- Mid-session Add endpoint overlay (show/hide only on this window) ---
			$W.SyncAddEpKey = {
				try {
					$use = $false
					try { $use = [bool]$W.AddEpAuthKey.IsChecked } catch {}
					if ($W.AddEpKey) {
						$W.AddEpKey.IsEnabled = $use
						$W.AddEpKey.Opacity = $(if ($use) { 1.0 } else { 0.45 })
					}
					if ($W.AddEpKeyLbl) { $W.AddEpKeyLbl.Opacity = $(if ($use) { 1.0 } else { 0.55 }) }
				} catch {}
			}.GetNewClosure()
			try {
				if ($W.AddEpAuthNone) { $null = $W.AddEpAuthNone.Add_Checked({ & $W.SyncAddEpKey }.GetNewClosure()) }
				if ($W.AddEpAuthKey) { $null = $W.AddEpAuthKey.Add_Checked({ & $W.SyncAddEpKey }.GetNewClosure()) }
				if ($W.AddEpAuthNpm) { $null = $W.AddEpAuthNpm.Add_Checked({ & $W.SyncAddEpKey }.GetNewClosure()) }
			} catch {}
			$W.HideAddEndpointOverlay = {
				try {
					if ($W.AddEndpointOverlay) {
						$W.AddEndpointOverlay.Visibility = [System.Windows.Visibility]::Collapsed
					}
					try { $W.AddEndpointBusy = $false } catch {}
					try { $W.ModalUi = $false } catch {}
					try {
						if ($W.AddEpConnect) {
							$W.AddEpConnect.IsEnabled = $true
							$W.AddEpConnect.Content = 'Connect'
							$W.AddEpConnect.IsDefault = $false
						}
					} catch {}
					try { if ($W.AddEpUrl) { $W.AddEpUrl.IsEnabled = $true } } catch {}
					try {
						if ($W.AddEpAuthNone) { $W.AddEpAuthNone.IsEnabled = $true }
						if ($W.AddEpAuthKey) { $W.AddEpAuthKey.IsEnabled = $true }
						if ($W.AddEpAuthNpm) { $W.AddEpAuthNpm.IsEnabled = $true }
					} catch {}
					try { if ($W.SyncAddEpKey) { & $W.SyncAddEpKey } } catch {}
				} catch {}
			}.GetNewClosure()
			$probeAddEp = {
				param([string]$BaseUrlIn, [string]$Mode, [string]$Key, [int]$TimeoutSec = 8)
				$raw = ([string]$BaseUrlIn).Trim()
				while ($raw.EndsWith('/')) { $raw = $raw.Substring(0, $raw.Length - 1) }
				$raw = $raw -replace '/chat/completions\s*$', '' -replace '/models\s*$', ''
				$raw = $raw -replace '/v1/chat/completions\s*$', '' -replace '/v1/models\s*$', ''
				while ($raw.EndsWith('/')) { $raw = $raw.Substring(0, $raw.Length - 1) }
				$bases = New-Object System.Collections.Generic.List[string]
				if ($raw -match '/v1$') {
					[void]$bases.Add($raw)
					$root = $raw -replace '/v1$', ''
					if ($root -and -not $bases.Contains($root)) { [void]$bases.Add($root) }
				} else {
					[void]$bases.Add($raw + '/v1')
					[void]$bases.Add($raw)
				}
				$headers = @{}
				if ($Mode -eq 'apikey' -and $Key) { $headers['Authorization'] = "Bearer $Key" }
				try {
					$proto = [System.Net.SecurityProtocolType]::Tls12
					try { $proto = $proto -bor [System.Net.SecurityProtocolType]::Tls13 } catch {}
					[System.Net.ServicePointManager]::SecurityProtocol = $proto
				} catch {
					try { [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12 } catch {}
				}
				$lastMsg = 'No response'
				$lastCode = 0
				$pp = $Global:ProgressPreference
				$Global:ProgressPreference = 'SilentlyContinue'
				try {
					foreach ($base in $bases) {
						$testUrl = "$base/models"
						try {
							$response = Invoke-WebRequest -Uri $testUrl -Method GET -Headers $headers -TimeoutSec $TimeoutSec -UseBasicParsing -ErrorAction Stop
							$code = [int]$response.StatusCode
							if ($code -eq 200) {
								$body = ''
								try { $body = [string]$response.Content } catch { $body = '' }
								if ($body -match '"object"\s*:\s*"list"' -or $body -match '"data"\s*:\s*\[' -or $body.Trim().StartsWith('{') -or $body.Trim().StartsWith('[')) {
									return @{ Ok = $true; StatusCode = 200; Message = "OK -> $base"; BaseUrl = $base }
								}
								$lastMsg = "HTTP 200 from $testUrl but body is not a models API"
								$lastCode = 200
								continue
							}
							$lastMsg = "HTTP $code from $testUrl"
							$lastCode = $code
						} catch [System.Net.WebException] {
							$code = 0
							try { $code = [int]$_.Exception.Response.StatusCode } catch {}
							if ($code -in 401, 403) {
								if ($Mode -eq 'apikey') {
									return @{ Ok = $false; StatusCode = $code; Message = "Authentication failed ($code) - check Bearer API key."; BaseUrl = $base }
								}
								return @{ Ok = $true; StatusCode = $code; Message = 'Reachable (auth required)'; BaseUrl = $base; NeedsAuth = $true }
							}
							if ($code) { $lastMsg = "Server returned HTTP $code from $testUrl"; $lastCode = $code }
							else { $lastMsg = "$($_.Exception.Message)"; $lastCode = 0 }
						} catch {
							$lastMsg = $_.Exception.Message
							$lastCode = 0
						}
					}
				} finally { $Global:ProgressPreference = $pp }
				return @{ Ok = $false; StatusCode = $lastCode; Message = $lastMsg; BaseUrl = $raw }
			}.GetNewClosure()
			# Local normalize + "already connected" check (STA has W bag, not $script:MB)
			$normAddEpUrl = {
				param([string]$Url)
				$u0 = [string]$Url
				if ([string]::IsNullOrWhiteSpace($u0)) { return '' }
				$u0 = $u0.Trim()
				if ($u0 -notmatch '^(?i)https?://') {
					if ($u0 -match '^\d+$') { $u0 = "http://127.0.0.1:$u0" }
					else { $u0 = "http://$u0" }
				}
				while ($u0.EndsWith('/')) { $u0 = $u0.Substring(0, $u0.Length - 1) }
				$u0 = $u0 -replace '/chat/completions\s*$', '' -replace '/models\s*$', ''
				$u0 = $u0 -replace '/v1/chat/completions\s*$', '' -replace '/v1/models\s*$', ''
				while ($u0.EndsWith('/')) { $u0 = $u0.Substring(0, $u0.Length - 1) }
				return $u0
			}.GetNewClosure()
			$idKeysAddEp = {
				param([string]$Url)
				$n0 = & $normAddEpUrl $Url
				if ([string]::IsNullOrWhiteSpace($n0)) { return @() }
				$ks = New-Object System.Collections.ArrayList
				[void]$ks.Add($n0)
				if ($n0 -match '(?i)/v1$') {
					$r0 = $n0 -replace '(?i)/v1$', ''
					if ($r0) { [void]$ks.Add($r0) }
				} else {
					[void]$ks.Add(($n0 + '/v1'))
				}
				return @($ks)
			}.GetNewClosure()
			$isAlreadyAddEp = {
				param([string]$Url)
				# Returns $null if free, or the matched base string if already in use.
				# Strict: ActiveModelBase + ExtraApiBases only (same as Get-MBLiveApiBases).
				$want = @(& $idKeysAddEp $Url)
				if ($want.Count -eq 0) { return $null }
				$candidates = New-Object System.Collections.ArrayList
				try {
					$ab = [string]$W.ActiveModelBase
					if (-not [string]::IsNullOrWhiteSpace($ab)) { [void]$candidates.Add($ab) }
				} catch {}
				try {
					foreach ($x in @($W.ExtraApiBases)) {
						if ($null -eq $x) { continue }
						$xs = [string]$x
						if ([string]::IsNullOrWhiteSpace($xs)) { continue }
						[void]$candidates.Add($xs)
					}
				} catch {}
				try {
					foreach ($x in @($W.KnownApiBases)) {
						if ($null -eq $x) { continue }
						$xs = [string]$x
						if ([string]::IsNullOrWhiteSpace($xs)) { continue }
						[void]$candidates.Add($xs)
					}
				} catch {}
				foreach ($cand in @($candidates)) {
					$cKeys = @(& $idKeysAddEp $cand)
					foreach ($ck in $cKeys) {
						if ([string]::IsNullOrWhiteSpace($ck)) { continue }
						foreach ($w in $want) {
							if ([string]::IsNullOrWhiteSpace($w)) { continue }
							if ([string]::Equals($w, $ck, [StringComparison]::OrdinalIgnoreCase)) {
								return (& $normAddEpUrl $cand)
							}
						}
					}
				}
				return $null
			}.GetNewClosure()
			$tryAddEpConnect = {
				try {
					if ([bool]$W.AddEndpointBusy) { return }
					$bcX = New-Object System.Windows.Media.BrushConverter
					$u = ''
					try { $u = ([string]$W.AddEpUrl.Text).Trim() } catch {}
					if ([string]::IsNullOrWhiteSpace($u)) {
						if ($W.AddEpError) {
							$W.AddEpError.Foreground = $bcX.ConvertFromString('#F05C5C')
							$W.AddEpError.Text = 'Enter a base URL (e.g. http://127.0.0.1:8080 or .../v1).'
						}
						return
					}
					if ($u -notmatch '^(?i)https?://') {
						if ($W.AddEpError) {
							$W.AddEpError.Foreground = $bcX.ConvertFromString('#F05C5C')
							$W.AddEpError.Text = 'URL must start with http:// or https://'
						}
						return
					}
					# Block only if URL is this session's active base or an already-added extra
					try {
						$dup = & $isAlreadyAddEp $u
						if ($null -ne $dup -and -not [string]::IsNullOrWhiteSpace([string]$dup)) {
							if ($W.AddEpError) {
								$W.AddEpError.Foreground = $bcX.ConvertFromString('#F05C5C')
								$W.AddEpError.Text = ("Already connected to {0}. Use a different URL, or switch models in the picker." -f [string]$dup)
							}
							return
						}
					} catch {}
					$mode = 'none'
					try {
						if ([bool]$W.AddEpAuthKey.IsChecked) { $mode = 'apikey' }
						elseif ([bool]$W.AddEpAuthNpm.IsChecked) { $mode = 'npm' }
					} catch {}
					$k = ''
					if ($mode -eq 'apikey') {
						try { $k = [string]$W.AddEpKey.Password } catch { $k = '' }
						if ([string]::IsNullOrWhiteSpace($k) -or $k -eq 'none') {
							if ($W.AddEpError) {
								$W.AddEpError.Foreground = $bcX.ConvertFromString('#F05C5C')
								$W.AddEpError.Text = 'API mode requires a Bearer token.'
							}
							return
						}
					}
					$W.AddEndpointBusy = $true
					try {
						if ($W.AddEpConnect) {
							$W.AddEpConnect.IsEnabled = $false
							$W.AddEpConnect.Content = '...'
						}
						if ($W.AddEpUrl) { $W.AddEpUrl.IsEnabled = $false }
						if ($W.AddEpAuthNone) { $W.AddEpAuthNone.IsEnabled = $false }
						if ($W.AddEpAuthKey) { $W.AddEpAuthKey.IsEnabled = $false }
						if ($W.AddEpAuthNpm) { $W.AddEpAuthNpm.IsEnabled = $false }
						if ($W.AddEpKey) { $W.AddEpKey.IsEnabled = $false }
					} catch {}
					if ($W.AddEpError) {
						$W.AddEpError.Foreground = $bcX.ConvertFromString('#8A8A96')
						$W.AddEpError.Text = 'Connecting...'
					}
					[void]$W.Dispatcher.BeginInvoke([Action]{
						try {
							$probe = & $probeAddEp $u $mode $k 8
							if (-not $W.AddEndpointOverlay -or $W.AddEndpointOverlay.Visibility -ne [System.Windows.Visibility]::Visible) {
								try { $W.AddEndpointBusy = $false } catch {}
								return
							}
							if ($probe -and $probe.Ok) {
								$useUrl = $u
								try { if ($probe.BaseUrl) { $useUrl = [string]$probe.BaseUrl } } catch {}
								# Probe may rewrite to .../v1 — same active/extra host still blocked
								try {
									$dup2 = & $isAlreadyAddEp $useUrl
									if ($null -ne $dup2 -and -not [string]::IsNullOrWhiteSpace([string]$dup2)) {
										if ($W.AddEpError) {
											$W.AddEpError.Foreground = $bcX.ConvertFromString('#F05C5C')
											$W.AddEpError.Text = ("Already connected to {0}. Use a different URL, or switch models in the picker." -f [string]$dup2)
										}
										$W.AddEndpointBusy = $false
										try {
											if ($W.AddEpConnect) {
												$W.AddEpConnect.IsEnabled = $true
												$W.AddEpConnect.Content = 'Connect'
											}
											if ($W.AddEpUrl) { $W.AddEpUrl.IsEnabled = $true }
											if ($W.AddEpAuthNone) { $W.AddEpAuthNone.IsEnabled = $true }
											if ($W.AddEpAuthKey) { $W.AddEpAuthKey.IsEnabled = $true }
											if ($W.AddEpAuthNpm) { $W.AddEpAuthNpm.IsEnabled = $true }
											if ($W.SyncAddEpKey) { & $W.SyncAddEpKey }
										} catch {}
										return
									}
								} catch {}
								$W.PendingAddBaseUrl = $useUrl
								$W.PendingAddBaseAuthMode = $mode
								$W.PendingAddBaseApiKey = $(if ($mode -eq 'apikey') { $k } else { '' })
								$W.PendingAddBaseDirty = $true
								if ($W.AddEpError) {
									$W.AddEpError.Foreground = $bcX.ConvertFromString('#8A8A96')
									$W.AddEpError.Text = 'Connected - adding endpoint...'
								}
								if ($W.HideAddEndpointOverlay) { & $W.HideAddEndpointOverlay }
								return
							}
							$detail = if ($probe -and $probe.Message) { [string]$probe.Message } else { 'No response from server.' }
							$detail = ($detail -replace '[\r\n]+', ' ').Trim()
							if ($detail.Length -gt 120) { $detail = $detail.Substring(0, 117) + '...' }
							if ($W.AddEpError) {
								$W.AddEpError.Foreground = $bcX.ConvertFromString('#F05C5C')
								$W.AddEpError.Text = "Connection was not successful. $detail"
							}
							$W.AddEndpointBusy = $false
							try {
								if ($W.AddEpConnect) {
									$W.AddEpConnect.IsEnabled = $true
									$W.AddEpConnect.Content = 'Connect'
								}
								if ($W.AddEpUrl) { $W.AddEpUrl.IsEnabled = $true }
								if ($W.AddEpAuthNone) { $W.AddEpAuthNone.IsEnabled = $true }
								if ($W.AddEpAuthKey) { $W.AddEpAuthKey.IsEnabled = $true }
								if ($W.AddEpAuthNpm) { $W.AddEpAuthNpm.IsEnabled = $true }
								if ($W.SyncAddEpKey) { & $W.SyncAddEpKey }
								if ($W.AddEpUrl) { [void]$W.AddEpUrl.Focus() }
							} catch {}
						} catch {
							try {
								if ($W.AddEpError) {
									$W.AddEpError.Foreground = $bcX.ConvertFromString('#F05C5C')
									$W.AddEpError.Text = "Connection was not successful. $($_.Exception.Message)"
								}
							} catch {}
							try { $W.AddEndpointBusy = $false } catch {}
							try {
								if ($W.AddEpConnect) {
									$W.AddEpConnect.IsEnabled = $true
									$W.AddEpConnect.Content = 'Connect'
								}
								if ($W.AddEpUrl) { $W.AddEpUrl.IsEnabled = $true }
								if ($W.AddEpAuthNone) { $W.AddEpAuthNone.IsEnabled = $true }
								if ($W.AddEpAuthKey) { $W.AddEpAuthKey.IsEnabled = $true }
								if ($W.AddEpAuthNpm) { $W.AddEpAuthNpm.IsEnabled = $true }
								if ($W.SyncAddEpKey) { & $W.SyncAddEpKey }
							} catch {}
						}
					}.GetNewClosure(), [System.Windows.Threading.DispatcherPriority]::Background)
				} catch {
					try { $W.AddEndpointBusy = $false } catch {}
				}
			}.GetNewClosure()
			try {
				if ($W.AddEpConnect) {
					$null = $W.AddEpConnect.Add_Click({ & $tryAddEpConnect }.GetNewClosure())
				}
				if ($W.AddEpCancel) {
					$null = $W.AddEpCancel.Add_Click({
						try { if ($W.HideAddEndpointOverlay) { & $W.HideAddEndpointOverlay } } catch {}
					}.GetNewClosure())
				}
				if ($W.AddEpTitleClose) {
					$null = $W.AddEpTitleClose.Add_Click({
						try { if ($W.HideAddEndpointOverlay) { & $W.HideAddEndpointOverlay } } catch {}
					}.GetNewClosure())
				}
				if ($W.AddEpUrl) {
					$null = $W.AddEpUrl.Add_KeyDown({
						param($s, $e)
						try {
							if ($e.Key -eq 'Return') { $e.Handled = $true; & $tryAddEpConnect }
							elseif ($e.Key -eq 'Escape') {
								$e.Handled = $true
								if ($W.HideAddEndpointOverlay) { & $W.HideAddEndpointOverlay }
							}
						} catch {}
					}.GetNewClosure())
				}
			} catch {}

			if ($W.ConfirmYes) {
				$W.ConfirmYes.add_Click({
					param($s, $e)
					try {
						$W.ConfirmResult = $true
						if ($W.ConfirmOverlay) {
							$W.ConfirmOverlay.Visibility = [System.Windows.Visibility]::Collapsed
						}
						if ($W.ConfirmYes) { $W.ConfirmYes.IsDefault = $false }
						[void]$W.ConfirmWait.Set()
					} catch {}
				}.GetNewClosure())
			}
			$doConfirmNo = {
				try {
					$W.ConfirmResult = $false
					if ($W.ConfirmOverlay) {
						$W.ConfirmOverlay.Visibility = [System.Windows.Visibility]::Collapsed
					}
					if ($W.ConfirmYes) { $W.ConfirmYes.IsDefault = $false }
					[void]$W.ConfirmWait.Set()
				} catch {}
			}.GetNewClosure()
			if ($W.ConfirmNo) {
				$W.ConfirmNo.add_Click({
					param($s, $e)
					try { & $doConfirmNo } catch {}
				}.GetNewClosure())
			}
			if ($W.ConfirmTitleClose) {
				$W.ConfirmTitleClose.add_Click({
					param($s, $e)
					try { & $doConfirmNo } catch {}
				}.GetNewClosure())
			}

			$conv = New-Object System.Windows.Media.BrushConverter
			$colorMap = @{
				'Black'='#5C5C5C'; 'DarkBlue'='#7AA2F7'; 'DarkGreen'='#9ECE6A'; 'DarkCyan'='#7DCFFF'
				'DarkRed'='#B80F0A'; 'DarkMagenta'='#BB9AF7'; 'DarkYellow'='#E0AF68'; 'Gray'='#A0A0AA'
				'DarkGray'='#565F89'; 'Blue'='#7AA2F7'; 'Green'='#9ECE6A'; 'Cyan'='#7DCFFF'
				'Red'='#B80F0A'; 'Magenta'='#BB9AF7'; 'Yellow'='#E0AF68'; 'White'='#C0CAF5'
			}
			$brailleFrames = @(
				[string][char]0x280B,  # ⠋
				[string][char]0x2819,  # ⠙
				[string][char]0x2839,  # ⠹
				[string][char]0x2838,  # ⠸
				[string][char]0x283C,  # ⠼
				[string][char]0x2834,  # ⠴
				[string][char]0x2826,  # ⠦
				[string][char]0x2827,  # ⠧
				[string][char]0x2807,  # ⠇
				[string][char]0x280F   # ⠏
			)
			# Emoji codepoint detection. Keep ZWJ/VS/keycap joiners with emoji runs.
			$isEmojiCp = {
				param([int]$cp)
				if ($cp -ge 0x1F000 -and $cp -le 0x1FAFF) { return $true }   # emoji blocks
				if ($cp -ge 0x1F1E6 -and $cp -le 0x1F1FF) { return $true }   # regional indicators
				if ($cp -ge 0x1F300 -and $cp -le 0x1F9FF) { return $true }
				if ($cp -ge 0x1FA00 -and $cp -le 0x1FAFF) { return $true }
				if ($cp -ge 0x1FB00 -and $cp -le 0x1FBFF) { return $true }
				if ($cp -ge 0x2600 -and $cp -le 0x27BF) { return $true }     # misc symbols / dingbats
				if ($cp -ge 0x2300 -and $cp -le 0x23FF) { return $true }     # misc technical (⏱ etc.)
				if ($cp -ge 0x2190 -and $cp -le 0x21FF) { return $true }     # arrows often used as emoji
				if ($cp -ge 0x2460 -and $cp -le 0x24FF) { return $true }
				if ($cp -ge 0x25A0 -and $cp -le 0x25FF) { return $true }
				if ($cp -ge 0x2B00 -and $cp -le 0x2BFF) { return $true }
				if ($cp -ge 0xFE00 -and $cp -le 0xFE0F) { return $true }     # variation selectors
				if ($cp -eq 0x200D -or $cp -eq 0x20E3 -or $cp -eq 0xFE0F) { return $true } # ZWJ / keycap
				if ($cp -eq 0x200C) { return $true }                        # ZWNJ in some sequences
				if ($cp -ge 0xE0020 -and $cp -le 0xE007F) { return $true }   # tag chars (flags)
				if ($cp -ge 0x1F3FB -and $cp -le 0x1F3FF) { return $true }   # skin tones
				return $false
			}.GetNewClosure()

			# Display units for layout (wcwidth-ish). Emoji graphemes count as 2; joiners 0; ASCII 1.
			$measureDisplayUnits = {
				param([string]$text)
				if ([string]::IsNullOrEmpty($text)) { return 0.0 }
				$units = 0.0
				$i = 0
				$len = $text.Length
				$inEmoji = $false
				while ($i -lt $len) {
					$code = [int][char]$text[$i]
					$cp = $code
					$take = 1
					if ($code -ge 0xD800 -and $code -le 0xDBFF -and ($i + 1) -lt $len) {
						$low = [int][char]$text[$i + 1]
						if ($low -ge 0xDC00 -and $low -le 0xDFFF) {
							$cp = 0x10000 + (($code - 0xD800) -shl 10) + ($low - 0xDC00)
							$take = 2
						}
					}
					$em = [bool](& $isEmojiCp $cp)
					# Combining marks / joiners / VS: zero width (part of prior emoji cluster)
					if ($cp -eq 0x200D -or $cp -eq 0x200C -or $cp -eq 0x20E3 -or
						($cp -ge 0xFE00 -and $cp -le 0xFE0F) -or
						($cp -ge 0x1F3FB -and $cp -le 0x1F3FF) -or
						($cp -ge 0xE0020 -and $cp -le 0xE007F) -or
						($cp -ge 0x0300 -and $cp -le 0x036F) -or
						($cp -ge 0x1AB0 -and $cp -le 0x1AFF) -or
						($cp -ge 0x20D0 -and $cp -le 0x20FF)) {
						$i += $take
						continue
					}
					if ($em) {
						# One visual emoji cell (even for multi-codepoint clusters counted once per base)
						if (-not $inEmoji) { $units += 2.0; $inEmoji = $true }
						else {
							# Regional indicator pairs / consecutive emoji bases: each new base +2
							# After ZWJ cluster we stay inEmoji; a new base after non-joiner path resets above
							$units += 2.0
						}
						$i += $take
						# Consume following joiners/VS/skin/tags in the same cluster without extra width
						while ($i -lt $len) {
							$c2 = [int][char]$text[$i]
							$cp2 = $c2
							$tk2 = 1
							if ($c2 -ge 0xD800 -and $c2 -le 0xDBFF -and ($i + 1) -lt $len) {
								$lo2 = [int][char]$text[$i + 1]
								if ($lo2 -ge 0xDC00 -and $lo2 -le 0xDFFF) {
									$cp2 = 0x10000 + (($c2 - 0xD800) -shl 10) + ($lo2 - 0xDC00)
									$tk2 = 2
								}
							}
							if ($cp2 -eq 0x200D) {
								# ZWJ: include next emoji base in same cluster (no extra width)
								$i += $tk2
								if ($i -lt $len) {
									$c3 = [int][char]$text[$i]
									$tk3 = 1
									if ($c3 -ge 0xD800 -and $c3 -le 0xDBFF -and ($i + 1) -lt $len) {
										$lo3 = [int][char]$text[$i + 1]
										if ($lo3 -ge 0xDC00 -and $lo3 -le 0xDFFF) { $tk3 = 2 }
									}
									$i += $tk3
									# optional VS/skin after joined base
									while ($i -lt $len) {
										$c4 = [int][char]$text[$i]
										$cp4 = $c4
										$tk4 = 1
										if ($c4 -ge 0xD800 -and $c4 -le 0xDBFF -and ($i + 1) -lt $len) {
											$lo4 = [int][char]$text[$i + 1]
											if ($lo4 -ge 0xDC00 -and $lo4 -le 0xDFFF) {
												$cp4 = 0x10000 + (($c4 - 0xD800) -shl 10) + ($lo4 - 0xDC00)
												$tk4 = 2
											}
										}
										if (($cp4 -ge 0xFE00 -and $cp4 -le 0xFE0F) -or
											($cp4 -ge 0x1F3FB -and $cp4 -le 0x1F3FF) -or
											($cp4 -ge 0xE0020 -and $cp4 -le 0xE007F) -or
											$cp4 -eq 0x20E3) { $i += $tk4; continue }
										break
									}
								}
								continue
							}
							if (($cp2 -ge 0xFE00 -and $cp2 -le 0xFE0F) -or
								($cp2 -ge 0x1F3FB -and $cp2 -le 0x1F3FF) -or
								($cp2 -ge 0xE0020 -and $cp2 -le 0xE007F) -or
								$cp2 -eq 0x20E3) {
								$i += $tk2
								continue
							}
							break
						}
						$inEmoji = $false
						continue
					}
					$inEmoji = $false
					# CJK / fullwidth wide
					if (($cp -ge 0x1100 -and $cp -le 0x115F) -or
						($cp -ge 0x2E80 -and $cp -le 0xA4CF) -or
						($cp -ge 0xAC00 -and $cp -le 0xD7A3) -or
						($cp -ge 0xF900 -and $cp -le 0xFAFF) -or
						($cp -ge 0xFE10 -and $cp -le 0xFE19) -or
						($cp -ge 0xFE30 -and $cp -le 0xFE6F) -or
						($cp -ge 0xFF00 -and $cp -le 0xFF60) -or
						($cp -ge 0xFFE0 -and $cp -le 0xFFE6) -or
						($cp -ge 0x20000 -and $cp -le 0x3FFFD)) {
						$units += 2.0
					} else {
						$units += 1.0
					}
					$i += $take
				}
				return $units
			}.GetNewClosure()

			# Measure mixed mono+emoji text width in DIPs (FormattedText when possible).
			$measureTextWidth = {
				param([string]$text, [double]$fontSize, $monoFont, $emojiFont)
				if ([string]::IsNullOrEmpty($text)) { return 0.0 }
				$fs = $fontSize
				if ($fs -le 0) { $fs = 12.5 }
				try {
					$ff = $null
					# Stack mono + emoji so FormattedText accounts for both glyph widths
					try {
						$ff = New-Object System.Windows.Media.FontFamily(
							'Consolas, Cascadia Mono, Segoe UI Emoji, Courier New, Segoe UI')
					} catch {
						$ff = $monoFont
						if ($null -eq $ff) { $ff = $emojiFont }
					}
					if ($null -eq $ff) {
						$u = [double](& $measureDisplayUnits $text)
						return ($u * $fs * 0.62)
					}
					$tf = New-Object System.Windows.Media.Typeface (
						$ff,
						[System.Windows.FontStyles]::Normal,
						[System.Windows.FontWeights]::Normal,
						[System.Windows.FontStretches]::Normal
					)
					$dpi = 96.0
					try {
						if ($W.Window -and $W.Window.ActualWidth -gt 0) {
							$src = [System.Windows.PresentationSource]::FromVisual($W.Window)
							if ($null -ne $src -and $null -ne $src.CompositionTarget) {
								$dpi = 96.0 * [double]$src.CompositionTarget.TransformToDevice.M11
							}
						}
					} catch { $dpi = 96.0 }
					$pxPerDip = $dpi / 96.0
					if ($pxPerDip -le 0) { $pxPerDip = 1.0 }
					$ft = $null
					# pixelsPerDip overload needs .NET 4.6.2+; fall back for older hosts
					try {
						$ft = New-Object System.Windows.Media.FormattedText (
							$text,
							[System.Globalization.CultureInfo]::CurrentCulture,
							[System.Windows.FlowDirection]::LeftToRight,
							$tf,
							$fs,
							[System.Windows.Media.Brushes]::Black,
							$pxPerDip
						)
					} catch {
						$ft = New-Object System.Windows.Media.FormattedText (
							$text,
							[System.Globalization.CultureInfo]::CurrentCulture,
							[System.Windows.FlowDirection]::LeftToRight,
							$tf,
							$fs,
							[System.Windows.Media.Brushes]::Black
						)
					}
					try { $ft.MaxTextWidth = 0 } catch {}
					$w = 0.0
					try { $w = [double]$ft.WidthIncludingTrailingWhitespace } catch { $w = 0.0 }
					if ($w -le 0) { try { $w = [double]$ft.Width } catch { $w = 0.0 } }
					# Floor with unit estimate so emoji never under-measure
					$u2 = [double](& $measureDisplayUnits $text)
					$minW = $u2 * $fs * 0.60
					if ($w -lt $minW) { $w = $minW }
					return $w
				} catch {
					$u3 = [double](& $measureDisplayUnits $text)
					return ($u3 * $fs * 0.62)
				}
			}.GetNewClosure()

			# Emoji runs: native Segoe UI Emoji (WPF has no color-font support without non-native deps).
			$emitEmoji = {
				param($target, [string]$emojiText, $emojiFont, $brush, [double]$fontSize)
				if ([string]::IsNullOrEmpty($emojiText) -or $null -eq $target) { return }
				try {
					$run = New-Object System.Windows.Documents.Run ($emojiText)
					if ($emojiFont) { $run.FontFamily = $emojiFont }
					else {
						try { $run.FontFamily = New-Object System.Windows.Media.FontFamily ('Segoe UI Emoji') } catch {}
					}
					if ($null -ne $brush) { $run.Foreground = $brush }
					if ($fontSize -gt 0) { try { $run.FontSize = $fontSize } catch {} }
					$target.Inlines.Add($run)
				} catch {}
			}.GetNewClosure()

			$appendRuns = {
				param($para, $chunk, $brush, $monoFont, $emojiFont, $fontSize = 0.0)
				if ([string]::IsNullOrEmpty($chunk) -or $null -eq $para) { return }
				$fsUse = 0.0
				try { $fsUse = [double]$fontSize } catch { $fsUse = 0.0 }
				if ($fsUse -le 0) {
					try { $fsUse = [double]$para.FontSize } catch { $fsUse = 0.0 }
				}
				if ($fsUse -le 0) { $fsUse = 13.0 }
				$sb = New-Object System.Text.StringBuilder
				$mode = $null  # 't' text, 'e' emoji
				$emit = {
					param($targetPara, $m, $s, $br, $mf, $ef, $fs)
					if ($null -eq $s -or $s.Length -eq 0) { return }
					$txt = $s.ToString()
					if ($m -eq 'e') {
						& $emitEmoji $targetPara $txt $ef $br $fs
					} else {
						$run = New-Object System.Windows.Documents.Run ($txt)
						if ($mf) { $run.FontFamily = $mf }
						$run.Foreground = $br
						if ($fs -gt 0) { try { $run.FontSize = $fs } catch {} }
						$targetPara.Inlines.Add($run)
					}
					[void]$s.Clear()
				}
				$i = 0
				$len = $chunk.Length
				while ($i -lt $len) {
					$code = [int][char]$chunk[$i]
					$cp = $code
					$take = 1
					# Surrogate pair: full codepoint
					if ($code -ge 0xD800 -and $code -le 0xDBFF -and ($i + 1) -lt $len) {
						$low = [int][char]$chunk[$i + 1]
						if ($low -ge 0xDC00 -and $low -le 0xDFFF) {
							$cp = 0x10000 + (($code - 0xD800) -shl 10) + ($low - 0xDC00)
							$take = 2
						}
					}
					$isEmoji = [bool](& $isEmojiCp $cp)
					# Unpaired high surrogate → emoji path
					if (-not $isEmoji -and $code -ge 0xD800 -and $code -le 0xDBFF -and $take -eq 1) {
						$isEmoji = $true
					}
					$want = if ($isEmoji) { 'e' } else { 't' }
					if ($null -eq $mode) { $mode = $want }
					if ($want -ne $mode) {
						& $emit $para $mode $sb $brush $monoFont $emojiFont $fsUse
						$mode = $want
					}
					[void]$sb.Append($chunk.Substring($i, $take))
					$i += $take
				}
				& $emit $para $mode $sb $brush $monoFont $emojiFont $fsUse
			}.GetNewClosure()

			# Code-block syntax highlighting (regex lexer -> WPF Runs)
			$synNormLang = {
				param([string]$L)
				$x = ([string]$L).Trim().ToLowerInvariant() -replace '^\.+', ''
				switch -Regex ($x) {
					'^(ps1|psm1|psd1|powershell|pwsh|ps)$' { return 'ps' }
					'^(py|python|pyw)$' { return 'py' }
					'^(js|javascript|jsx|mjs|cjs)$' { return 'js' }
					'^(ts|typescript|tsx)$' { return 'ts' }
					'^(json|jsonc)$' { return 'json' }
					'^(sh|bash|zsh|shell|ksh)$' { return 'sh' }
					'^(cs|csharp|c#)$' { return 'cs' }
					'^(c|h)$' { return 'c' }
					'^(cpp|cxx|cc|hpp|hh|hxx)$' { return 'cpp' }
					'^(java)$' { return 'java' }
					'^(kt|kotlin)$' { return 'java' }
					'^(go|golang)$' { return 'go' }
					'^(rs|rust)$' { return 'rust' }
					'^(rb|ruby)$' { return 'rb' }
					'^(php)$' { return 'php' }
					'^(sql|mysql|pgsql|postgres|tsql|plsql)$' { return 'sql' }
					'^(html|htm|xml|svg|xaml|xsl|xsd)$' { return 'xml' }
					'^(css|scss|less|sass)$' { return 'css' }
					'^(yml|yaml)$' { return 'yaml' }
					'^(md|markdown)$' { return 'md' }
					'^(diff|patch)$' { return 'diff' }
					'^(ini|toml|conf|cfg|env)$' { return 'ini' }
					'^(dockerfile|docker)$' { return 'docker' }
					'^(bat|cmd)$' { return 'bat' }
					'^(r)$' { return 'r' }
					'^(lua)$' { return 'lua' }
					'^(swift)$' { return 'swift' }
					'^(vb|vbs|vba)$' { return 'vb' }
					default { return 'generic' }
				}
			}.GetNewClosure()

			$synBuildRules = {
				param([string]$Norm)
				$o = New-Object System.Collections.ArrayList
				$add = {
					param($list, $name, $pat)
					try {
						$rx = New-Object System.Text.RegularExpressions.Regex (
							$pat,
							[System.Text.RegularExpressions.RegexOptions]::CultureInvariant
						)
						[void]$list.Add(@{ N = $name; Rx = $rx })
					} catch {}
				}
				$strDQ = '"(?:\\.|[^"\\])*"'
				$strSQ = "'(?:\\.|[^'\\])*'"
				$strBT = '`(?:\\.|[^`\\])*`'
				$num   = '\b(?:0[xX][0-9A-Fa-f]+|\d+\.\d+(?:[eE][+-]?\d+)?|\d+[eE][+-]?\d+|\d+)\b'
				$cLine = '//[^\r\n]*'
				$cBlock = '/\*[\s\S]*?\*/'
				$hashLine = '#[^\r\n]*'
				$kwC = 'if|else|elif|for|while|do|switch|case|break|continue|return|goto|class|struct|enum|union|typedef|sizeof|const|static|extern|volatile|register|inline|void|int|char|short|long|float|double|signed|unsigned|bool|true|false|NULL|nullptr|new|delete|this|public|private|protected|namespace|using|template|typename|try|catch|throw|default|auto'
				switch ($Norm) {
					'ps' {
						& $add $o 'string'  ('@"[\s\S]*?"@|@''[\s\S]*?''@|"[^"\r\n`]*"|''[^''\r\n]*''')
						& $add $o 'comment' $hashLine
						& $add $o 'variable' '\$\w+|\$\{[^}]+\}|\$\?'
						& $add $o 'keyword'  '\b(?:function|filter|workflow|configuration|class|enum|param|begin|process|end|dynamicparam|if|elseif|else|foreach|for|while|do|switch|break|continue|return|exit|throw|try|catch|finally|trap|data|in|and|or|not|xor|bor|band|bnot|as|is|isnot|contains|notcontains|like|notlike|match|notmatch|replace|split|join|eq|ne|gt|ge|lt|le|shl|shr|inlinescript|parallel|sequence|from|where|hidden|static|var|ValidateSet|ValidateRange|ValidateNotNull|ValidateNotNullOrEmpty|CmdletBinding|Parameter|Alias|OutputType|SupportsShouldProcess)\b'
						& $add $o 'builtin'  '\b(?:Get|Set|New|Remove|Add|Clear|Copy|Move|Rename|Test|Invoke|Start|Stop|Restart|Wait|Write|Read|Out|Import|Export|ConvertTo|ConvertFrom|Select|Where|ForEach|Sort|Group|Measure|Compare|Format|Update|Register|Unregister|Enable|Disable|Install|Uninstall|Push|Pop|Enter|Exit|Connect|Disconnect|Send|Receive|Join|Split|Expand|Compress|Mount|Dismount|Resolve|Find|Search|Show|Hide|Lock|Unlock|Grant|Revoke|Approve|Deny|Publish|Unpublish|Protect|Unprotect|Backup|Restore|Checkpoint|Complete|Suspend|Resume|Limit|Skip|Use|Trace|Debug|Assert|Confirm|Request)-[A-Za-z][\w.]*\b'
						& $add $o 'operator' '(?:-eq|-ne|-gt|-ge|-lt|-le|-like|-notlike|-match|-notmatch|-replace|-contains|-notcontains|-in|-notin|-and|-or|-not|-xor|-band|-bor|-bxor|-bnot|-shl|-shr|\|=|[\+\-\*/%]=|==|!=|<=|>=|=>|=|\||&|;|\.\.|\.\.|::)'
						& $add $o 'number'   $num
						& $add $o 'function' '\bfunction\s+([A-Za-z_][\w-]*)'
						& $add $o 'type'     '\[(?:string|int|long|double|float|bool|char|byte|decimal|datetime|timespan|guid|xml|hashtable|psobject|pscustomobject|array|void|object|switch|scriptblock|regex|uri|version|ipaddress|[\w.]+)\]'
					}
					'py' {
						& $add $o 'string'  ('"""[\s\S]*?"""|''''[\s\S]*?''''|f?"(?:\\.|[^"\\])*"|f?''(?:\\.|[^''\\])*''')
						& $add $o 'comment' $hashLine
						& $add $o 'keyword'  '\b(?:False|None|True|and|as|assert|async|await|break|class|continue|def|del|elif|else|except|finally|for|from|global|if|import|in|is|lambda|nonlocal|not|or|pass|raise|return|try|while|with|yield|match|case)\b'
						& $add $o 'builtin'  '\b(?:abs|all|any|bin|bool|bytearray|bytes|callable|chr|classmethod|compile|complex|dict|dir|divmod|enumerate|eval|exec|filter|float|format|frozenset|getattr|globals|hasattr|hash|help|hex|id|input|int|isinstance|issubclass|iter|len|list|locals|map|max|memoryview|min|next|object|oct|open|ord|pow|print|property|range|repr|reversed|round|set|setattr|slice|sorted|staticmethod|str|sum|super|tuple|type|vars|zip)\b'
						& $add $o 'function' '\bdef\s+([A-Za-z_]\w*)|\bclass\s+([A-Za-z_]\w*)|\b([A-Za-z_]\w*)\s*(?=\()'
						& $add $o 'number'   $num
						& $add $o 'decorator' '@[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*'
						& $add $o 'operator' '==|!=|<=|>=|//|\*\*|:=|[-+*/%@&|^~<>]=?|='
					}
					'js' {
						& $add $o 'comment' ("$cBlock|$cLine")
						& $add $o 'string'  ("$strDQ|$strSQ|$strBT")
						& $add $o 'keyword'  '\b(?:async|await|break|case|catch|class|const|continue|debugger|default|delete|do|else|export|extends|finally|for|from|function|if|import|in|instanceof|let|new|of|return|static|super|switch|this|throw|try|typeof|var|void|while|with|yield|enum|implements|interface|package|private|protected|public|abstract|boolean|byte|char|double|final|float|goto|int|long|native|short|synchronized|throws|transient|volatile|as|type|keyof|readonly|infer|never|unknown|any|string|number|bigint|symbol|object|undefined|null|true|false)\b'
						& $add $o 'number'   $num
						& $add $o 'function' '\b(?:function\s+)?([A-Za-z_$][\w$]*)\s*(?=\()|\b([A-Za-z_$][\w$]*)\s*(?==>\s*)'
						& $add $o 'operator' '===|!==|=>|\?\?|\?\.|&&|\|\||\*\*|[-+*/%&|^~<>!=]=?|\?\?='
					}
					'ts' {
						& $add $o 'comment' ("$cBlock|$cLine")
						& $add $o 'string'  ("$strDQ|$strSQ|$strBT")
						& $add $o 'keyword'  '\b(?:async|await|break|case|catch|class|const|continue|debugger|default|delete|do|else|export|extends|finally|for|from|function|if|import|in|instanceof|let|new|of|return|static|super|switch|this|throw|try|typeof|var|void|while|with|yield|enum|implements|interface|package|private|protected|public|abstract|readonly|type|namespace|module|declare|keyof|infer|is|as|satisfies|override|true|false|null|undefined|any|unknown|never|string|number|boolean|bigint|symbol|object)\b'
						& $add $o 'type'     '\b(?:string|number|boolean|bigint|symbol|object|undefined|null|void|never|unknown|any|Record|Partial|Required|Readonly|Pick|Omit|Exclude|Extract|NonNullable|ReturnType|InstanceType|Promise|Array|Map|Set|Date|Error|RegExp)\b'
						& $add $o 'number'   $num
						& $add $o 'function' '\b(?:function\s+)?([A-Za-z_$][\w$]*)\s*(?=\()'
						& $add $o 'operator' '===|!==|=>|\?\?|\?\.|&&|\|\||[-+*/%&|^~<>!=]=?'
					}
					'json' {
						& $add $o 'string'  $strDQ
						& $add $o 'number'  $num
						& $add $o 'keyword' '\b(?:true|false|null)\b'
						& $add $o 'punctuation' '[{}\[\],:]'
