										$W.AutoCompactOnSeg = $acTog.On
										$W.AutoCompactToggleTip = $acTog.Hit
										[void]$lr.Children.Add($acTog.Outer)
										& $addMuted ("  {0}  " -f $dot)
										# auto-approve label (opens turns flyout) + ON/OFF toggle
										$aaLabel = New-Object System.Windows.Controls.TextBlock
