										if ($mono) { try { $aaUnlimLbl.FontFamily = $mono } catch {} }
										[void]$aaUnlimRow.Children.Add($aaUnlimLbl)
										# --- Row 2: - Turns[N] +  (mid becomes infinity when unlimited) ---
										$aaTurnsRow = New-Object System.Windows.Controls.StackPanel
