												$cur = 30
												try { $cur = [int]$W.MaxTurnsSetting } catch { $cur = 30 }
												$nxt = $cur + [int]$Delta
												if ($nxt -lt 1) { $nxt = 1 }
												if ($nxt -gt 200) { $nxt = 200 }
												$W.MaxTurnsSetting = $nxt
												$W.MaxTurnsDirty = $true
