													if ([bool]$W.TurnsInFlight) {
														$used = 0
														try { $used = [int]$W.TurnsUsed } catch { $used = 0 }
														if ($used -lt 0) { $used = 0 }
														$left = $nxt - $used
														if ($left -lt 0) { $left = 0 }
														$W.TurnsLeft = $left
														$disp = $left
													} else {
														$W.TurnsLeft = $nxt
														$disp = $nxt
													}
												} catch {}
												try { if ($W.AaTurnsNumTb) { $W.AaTurnsNumTb.Text = [string]$disp } } catch {}
											} catch {}
