										[void]$aaTurnsRow.Children.Add($aaTurnsMidHost)
										[void]$aaTurnsRow.Children.Add($btnAaPlus)
										$applyUnlimitedTurnsLook = {
											param([bool]$isUnlim)
											try {
												if ($W.AaTurnsCountPanel) {
